const HSK5_WORDS = [
  {"id":"hsk5-001","chinese":"唉","pinyin":"ài","meaning":"interjection or grunt of agreement or recognition (e.g. yes, it's me!); to sigh","meaningThai":"ดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"唉，完了，我们没赶上公共汽车。","pinyin":"Āi， wán le， wǒ mén méi gǎn shàng gōng gòng qì chē。","meaning":"Alas and alack , we had missed our bus.","meaningThai":"อนิจจา จบแล้ว เราพลาดรถบัส"},{"chinese":"唉，那就是我遭到摒弃的意见。","pinyin":"Āi， nà jiù shì wǒ zāo dào bìng qì de yì jiàn。","meaning":"Well that's my theory ruled out of court.","meaningThai":"นั่นเป็นทฤษฎีของผมที่ตัดสินออกจากศาล"}],"partOfSpeech":["interjection"]},
  {"id":"hsk5-002","chinese":"哎","pinyin":"āi","meaning":"hey!; (interjection used to attract attention or to express surprise or disapprobation)","meaningThai":"ทำไม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"哎，算了，情况本可能会更糟的。","pinyin":"Āi， suàn le， qíng kuàng běn kě néng huì gēng zāo de。","meaning":"Oh well, it could be worse.","meaningThai":"มันอาจจะแย่กว่านี้ก็ได้"},{"chinese":"哎，你总是说：你是个男人。","pinyin":"Āi， nǐ zǒng shì shuō： nǐ shì gè nán rén。","meaning":"Well, you would say that: you're a man.","meaningThai":"คุณจะพูดว่า: คุณเป็นผู้ชาย"}],"partOfSpeech":["interjection"]},
  {"id":"hsk5-003","chinese":"爱护","pinyin":"àihù","meaning":"to cherish; to treasure; to take care of; to love and protect","meaningThai":"การดูแล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"爱护文物, 人人有责。","pinyin":"Ài hù wén wù,  rén rén yǒu zé。","meaning":"It is everyone's duty to cherish cultural relics. / Cherish our cultural relics; it is all our duty.","meaningThai":"มันเป็นหน้าที่ของทุกคนที่จะหวงแหนวัตถุโบราณทางวัฒนธรรม/หวงแหนวัตถุโบราณทางวัฒนธรรมของเรามันเป็นหน้าที่ของเราทั้งหมด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-004","chinese":"哎呀","pinyin":"āiyā","meaning":"interjection of wonder, shock or admiration","meaningThai":"โอ๊ย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"哎呀，我忘了！","pinyin":"Ai ya, wo wang le!","meaning":"Oh dear, I forgot!","meaningThai":"โอ้, ฉันลืมไป!"}],"partOfSpeech":["interjection"]},
  {"id":"hsk5-005","chinese":"暗","pinyin":"àn","meaning":"variant of 暗","meaningThai":"มืด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"天空骤然转暗，随即下起雨来。","pinyin":"Tiān kōng zhòu rán zhuǎn àn， suí jí xià qǐ yǔ lái。","meaning":"The sky suddenly went dark and it started to rain.","meaningThai":"ทันใดนั้นท้องฟ้าก็มืดลงและฝนก็เริ่มตก"},{"chinese":"幕布升起，剧场内的灯光暗了下来。","pinyin":"Mù bù shēng qǐ， jù cháng nèi de dēng guāng àn le xià lái。","meaning":"The lights in the theatre dimmed as the curtain rose.","meaningThai":"แสงไฟในโรงละครจางลงเมื่อม่านลุกขึ้น"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-006","chinese":"安","pinyin":"ān","meaning":"surname An","meaningThai":"ติดตั้ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你不能邀请胡安参加这个聚会吗？","pinyin":"Nǐ bù néng yāo qǐng hú ān cān jiā zhè gè jù huì ma？","meaning":"Couldn't you ask Juan to the party?","meaningThai":"คุณไม่สามารถชวนฮวนไปงานปาร์ตี้ได้ไหม?"},{"chinese":"玛丽安希望他不要再谈这事。","pinyin":"Mǎ lì ān xī wàng tā bù yào zài tán zhè shì。","meaning":"Mary Ann wished he would just drop it.","meaningThai":"แมรี่ แอนหวังว่าเขาจะทิ้งมันไป"}],"partOfSpeech":["verb","other","noun","adjective","pronoun"]},
  {"id":"hsk5-007","chinese":"安全带","pinyin":"ānquándài","meaning":"seat belt","meaningThai":"เข็มขัดนิรภัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"请系好安全带。","pinyin":"Qǐng xì hǎo ān quán dài.","meaning":"Please fasten your seatbelt.","meaningThai":"กรุณารัดเข็มขัดนิรภัย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-008","chinese":"安慰","pinyin":"ānwèi","meaning":"to comfort; to console","meaningThai":"ปลอบโยน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"内德搂着她，试图安慰她。","pinyin":"Nèi dé lǒu zháo tā， shì tú ān wèi tā。","meaning":"Ned put his arm around her, trying to comfort her.","meaningThai":"เน็ดโอบแขนรอบตัวเธอ พยายามปลอบเธอ"},{"chinese":"“他会回来的。”苏珊安慰她道。","pinyin":"“ tā huì huí lái de。” sū shān ān wèi tā dào。","meaning":"'He'll come back,' Susan assured her.","meaningThai":"“เขาจะกลับมา” ซูซานรับรองกับเธอ"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-009","chinese":"安装","pinyin":"ānzhuāng","meaning":"to install; to erect; to fix; to mount; installation","meaningThai":"ติดตั้ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我得找人帮忙安装这个软件。","pinyin":"Wǒ dé zhǎo rén bāng máng ān zhuāng zhè gè ruǎn jiàn。","meaning":"I'll need some help installing the software.","meaningThai":"ฉันต้องการความช่วยเหลือในการติดตั้งซอฟต์แวร์"},{"chinese":"新系统的安装需要几天时间。","pinyin":"Xīn xì tǒng de ān zhuāng xū yào jī tiān shí jiān。","meaning":"Installation of the new system will take several days.","meaningThai":"การติดตั้งระบบใหม่จะใช้เวลาหลายวัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-010","chinese":"熬夜","pinyin":"áoyè","meaning":"to stay up late or all night","meaningThai":"อยู่ต่อไป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"今天晚上非得熬夜，真是烦人。","pinyin":"Jīn tiān wǎn shàng fēi dé āo yè， zhēn shì fán rén。","meaning":"It's such a bore having to stay late this evening.","meaningThai":"มันน่าเบื่อมากที่ต้องอยู่ดึกคืนนี้"},{"chinese":"你明天要上学。我不想让你熬夜。","pinyin":"Nǐ míng tiān yào shàng xué。 wǒ bù xiǎng ràng nǐ āo yè。","meaning":"You've got school tomorrow. I don't want you staying up late.","meaningThai":"พรุ่งนี้คุณมีเรียน ฉันไม่อยากให้คุณนอนดึก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-011","chinese":"白","pinyin":"bái","meaning":"surname Bai","meaningThai":"สีขาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"墙面不是白的，而是灰不溜秋的。","pinyin":"Qiáng miàn bù shì bái de， ér shì huī bù liū qiū de。","meaning":"The walls were not white, but rather a sort of dirty grey.","meaningThai":"ผนังไม่ใช่สีขาว แต่เป็นสีเทาสกปรก"},{"chinese":"实验室助手穿着一件白罩衣。","pinyin":"Shí yàn shì zhù shǒu chuān zháo yī jiàn bái zhào yī。","meaning":"The lab assistant was wearing a white overall.","meaningThai":"ผู้ช่วยห้องปฏิบัติการสวมชุดสีขาว"}],"partOfSpeech":["adjective","noun","adverb","verb","other"]},
  {"id":"hsk5-012","chinese":"傍晚","pinyin":"bàngwǎn","meaning":"in the evening; when night falls; towards evening; at night fall; at dusk","meaningThai":"พลบค่ำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"傍晚我们去散步。","pinyin":"Bang wan wo men qu san bu.","meaning":"We walk in the evening.","meaningThai":"เราเดินเล่นในตอนเย็น"}],"partOfSpeech":["other"]},
  {"id":"hsk5-013","chinese":"半夜","pinyin":"bànyè","meaning":"midnight; in the middle of the night","meaningThai":"เที่ยงคืน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们直到半夜才把婴孩哄睡着。","pinyin":"Tā mén zhí dào bàn yè cái bǎ yīng hái hōng shuì zháo。","meaning":"They couldn't get the baby off till midnight.","meaningThai":"พวกเขาไม่สามารถพาลูกออกไปได้จนถึงเที่ยงคืน"},{"chinese":"我们得回家了，已过半夜了。","pinyin":"Wǒ mén dé huí jiā le， yǐ guò bàn yè le。","meaning":"We must be getting home ; it's past midnight.","meaningThai":"เราคงต้องกลับบ้านแล้ว เลยเที่ยงคืนไปแล้ว"}],"partOfSpeech":["other"]},
  {"id":"hsk5-014","chinese":"薄","pinyin":"báo","meaning":"surname Bo","meaningThai":"บาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个食品加工机有薄、中、厚的切片盘。","pinyin":"Zhè gè shí pǐn jiā gōng jī yǒu báo、 zhōng、 hòu de qiē piàn pán。","meaning":"The food processor has thin, medium, and thick slicing discs.","meaningThai":"เครื่องเตรียมอาหารมีแผ่นหั่นบาง ปานกลาง และหนา"},{"chinese":"第一批滑雪板是又长又薄的山胡桃木板子。","pinyin":"Dì yī pī huá xuě bǎn shì yòu cháng yòu báo de shān hú táo mù bǎn zǐ。","meaning":"The first skis were long, thin strips of hickory.","meaningThai":"สกีช่วงแรกเป็นแถบยาวและบางจากไม้ฮิคโครี่"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-015","chinese":"宝","pinyin":"bǎo","meaning":"variant of 宝","meaningThai":"ล้ำค่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"施贵宝的股票猛涨了$2.50。","pinyin":"Shī guì bǎo de gǔ piào měng zhǎng le$2.50。","meaning":"Squibb shares jumped $2.50.","meaningThai":"หุ้น Squibb พุ่งขึ้น 2.50 ดอลลาร์"},{"chinese":"这幅画是我们家的传家宝。","pinyin":"Zhè fú huà shì wǒ mén jiā de chuán jiā bǎo。","meaning":"This painting has been in our family for generations.","meaningThai":"ภาพวาดนี้อยู่ในครอบครัวของเรามาหลายชั่วอายุคน"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-016","chinese":"保","pinyin":"bǎo","meaning":"Bulgaria; Bulgarian; abbr. for 保加利亚","meaningThai":"บันทึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"银行在支票上标有“保付”的字样。","pinyin":"Yín háng zài zhī piào shàng biāo yǒu “ bǎo fù ” de zì yàng。","meaning":"The bank marks the cheque \"certified.\"","meaningThai":"ธนาคารทำเครื่องหมายเช็คว่า \"รับรอง\""},{"chinese":"这份保险单是否保我丈夫的驾车险？","pinyin":"Zhè fèn bǎo xiǎn dān shì fǒu bǎo wǒ zhàng fū de jià chē xiǎn？","meaning":"Does this policy cover my husband to drive?","meaningThai":"กรมธรรม์นี้คุ้มครองสามีของฉันในการขับรถหรือไม่?"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-017","chinese":"保安","pinyin":"bǎo'ān","meaning":"to ensure public security; to ensure safety (for workers engaged in production); public security; security guard","meaningThai":"เจ้าหน้าที่รักษาความปลอดภัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"袭击事件已被保安摄像机拍摄下来。","pinyin":"Xí jī shì jiàn yǐ bèi bǎo ān shè xiàng jī pāi shè xià lái。","meaning":"The attack was captured on film by security cameras.","meaningThai":"การโจมตีดังกล่าวบันทึกภาพไว้โดยกล้องวงจรปิด"},{"chinese":"他们装扮成保安人员混了进去。","pinyin":"Tā mén zhuāng bàn chéng bǎo ān rén yuán hùn le jìn qù。","meaning":"They got in disguised as security guards.","meaningThai":"พวกเขาปลอมตัวเป็นรปภ."}],"partOfSpeech":["adjective","noun","verb"]},
  {"id":"hsk5-018","chinese":"宝贝","pinyin":"bǎobèi","meaning":"treasured object; treasure; darling; baby; cowry; good-for-nothing or queer character","meaningThai":"ที่รัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你见到我的钥匙了吗，宝贝？","pinyin":"Nǐ jiàn dào wǒ de yuè chí le ma， bǎo bèi？","meaning":"Have you seen my keys, honey?","meaningThai":"คุณเห็นกุญแจของฉันไหมที่รัก?"},{"chinese":"你现在得醒了，宝贝儿。","pinyin":"Nǐ xiàn zài dé xǐng le， bǎo bèi ér。","meaning":"You have to wake up now, baby.","meaningThai":"คุณต้องตื่นเดี๋ยวนี้นะที่รัก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-019","chinese":"保持","pinyin":"bǎochí","meaning":"to keep; to maintain; to hold; to preserve","meaningThai":"เก็บ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"警方吁请公众保持镇静。","pinyin":"Jǐng fāng xū qǐng gōng zhòng bǎo chí zhèn jìng。","meaning":"The police made an appeal to the public to remain calm.","meaningThai":"ตำรวจได้เรียกร้องให้ประชาชนอยู่ในความสงบ"},{"chinese":"家人帮助我保持冷静。","pinyin":"Jiā rén bāng zhù wǒ bǎo chí lěng jìng。","meaning":"My family helps to keep me centred.","meaningThai":"ครอบครัวของฉันช่วยให้ฉันเป็นศูนย์กลาง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-020","chinese":"保存","pinyin":"bǎocún","meaning":"to conserve; to preserve; to keep; to save (a file etc) (computing)","meaningThai":"บันทึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"输入完毕后，要记着保存文档。","pinyin":"Shū rù wán bì hòu， yào jì zháo bǎo cún wén dàng。","meaning":"When you are finished typing, remember to save your document.","meaningThai":"เมื่อคุณพิมพ์เสร็จแล้ว อย่าลืมบันทึกเอกสารของคุณ"},{"chinese":"他们的音乐已为后世保存起来。","pinyin":"Tā mén de yīn lè yǐ wéi hòu shì bǎo cún qǐ lái。","meaning":"Their music has been preserved for posterity.","meaningThai":"ดนตรีของพวกเขาได้รับการเก็บรักษาไว้เพื่อลูกหลาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-021","chinese":"报到","pinyin":"bàodào","meaning":"to report for duty; to check in; to register","meaningThai":"เช็คอิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"所有来访者都应先到传达室报到。","pinyin":"Suǒ yǒu lái fǎng zhě dū yīng xiān dào chuán dá shì bào dào。","meaning":"All visitors should report to the porter's lodge.","meaningThai":"ผู้มาเยือนทุกคนควรรายงานตัวที่บ้านพักของลูกหาบ"},{"chinese":"你应该在上午9:30报到上班。","pinyin":"Nǐ yīng gāi zài shàng wǔ 9:30 bào dào shàng bān。","meaning":"You should report for duty at 9.30 a.m.","meaningThai":"ควรมารายงานตัวเวลา 09.30 น."}],"partOfSpeech":["verb"]},
  {"id":"hsk5-022","chinese":"报道","pinyin":"bàodào","meaning":"to report (news); report","meaningThai":"รายงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他觉得必须报道这件事。","pinyin":"Tā jué dé bì xū bào dào zhè jiàn shì。","meaning":"He felt compelled to report the incident.","meaningThai":"เขารู้สึกว่าจำเป็นต้องรายงานเหตุการณ์นี้"},{"chinese":"汤姆写了篇非常有深度的报道。","pinyin":"Tāng mǔ xiě le piān fēi cháng yǒu shēn dù de bào dào。","meaning":"Tom wrote a very profound report.","meaningThai":"ทอมเขียนรายงานที่ลึกซึ้งมาก"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-023","chinese":"报告","pinyin":"bàogào","meaning":"to inform; to report; to make known; report; speech; talk; lecture","meaningThai":"รายงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该报告陈述理由反对增税。","pinyin":"Gāi bào gào chén shù lǐ yóu fǎn duì zēng shuì。","meaning":"The report argues against tax increases.","meaningThai":"รายงานโต้แย้งการขึ้นภาษี"},{"chinese":"这报告应该给予认真考虑。","pinyin":"Zhè bào gào yīng gāi gěi yú rèn zhēn kǎo lǜ。","meaning":"The report deserves careful consideration.","meaningThai":"รายงานดังกล่าวสมควรได้รับการพิจารณาอย่างรอบคอบ"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-024","chinese":"宝贵","pinyin":"bǎoguì","meaning":"valuable; precious; to value; to treasure; to set store by","meaningThai":"มีค่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"现在请长话短说–我的时间很宝贵。","pinyin":"Xiàn zài qǐng cháng huà duǎn shuō – wǒ de shí jiān hěn bǎo guì。","meaning":"Now please be brief – my time is valuable.","meaningThai":"ตอนนี้โปรดพูดสั้น ๆ – เวลาของฉันมีค่า"},{"chinese":"从事这项工程使他获得了宝贵的经验。","pinyin":"Cóng shì zhè xiàng gōng chéng shǐ tā huò dé le bǎo guì de jīng yàn。","meaning":"He gained valuable experience whilst working on the project.","meaningThai":"เขาได้รับประสบการณ์อันมีค่าในขณะที่ทำงานในโครงการนี้"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-025","chinese":"包裹","pinyin":"bāoguǒ","meaning":"to wrap up; to bind up; bundle; parcel; package","meaningThai":"หีบห่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"警方警告公众要警惕可疑包裹。","pinyin":"Jǐng fāng jǐng gào gōng zhòng yào jǐng tì kě yí bāo guǒ。","meaning":"Police are warning the public to be on the alert for suspicious packages.","meaningThai":"ตำรวจเตือนประชาชนระวังพัสดุต้องสงสัย"},{"chinese":"成打的包裹从美国寄来。","pinyin":"Chéng dǎ de bāo guǒ cóng měi guó jì lái。","meaning":"Packages arrived by the dozen from America.","meaningThai":"แพคเกจมาถึงโหลจากอเมริกา"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-026","chinese":"包含","pinyin":"bāohán","meaning":"to contain; to embody; to include","meaningThai":"รวม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个故事包含很多层面的悖论。","pinyin":"Zhè gè gù shì bāo hán hěn duō céng miàn de bèi lùn。","meaning":"The story contains many levels of paradox.","meaningThai":"เรื่องราวนี้มีความขัดแย้งหลายระดับ"},{"chinese":"所有价格都包含邮资和手续费。","pinyin":"Suǒ yǒu jià gé dū bāo hán yóu zī hé shǒu xù fèi。","meaning":"All prices include postage and handling.","meaningThai":"ราคาทั้งหมดรวมค่าจัดส่งและการจัดการแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-027","chinese":"报警","pinyin":"bàojǐng","meaning":"to sound an alarm; to report sth to the police","meaningThai":"โทรแจ้งตำรวจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们强烈建议将此事报警。","pinyin":"Wǒ mén qiáng liè jiàn yì jiāng cǐ shì bào jǐng。","meaning":"We strongly recommend reporting the incident to the police.","meaningThai":"เราขอแนะนำอย่างยิ่งให้รายงานเหตุการณ์ดังกล่าวให้ตำรวจทราบ"},{"chinese":"遗憾的是没有早些报警。","pinyin":"Yí hàn de shì méi yǒu zǎo xiē bào jǐng。","meaning":"It is regrettable that the police were not informed sooner.","meaningThai":"น่าเสียดายที่ตำรวจไม่แจ้งให้ทราบเร็วกว่านี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-028","chinese":"包括","pinyin":"bāokuò","meaning":"to comprise; to include; to involve; to incorporate; to consist of","meaningThai":"รวม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"症状包括头痛和咽喉疼痛。","pinyin":"Zhèng zhuàng bāo kuò tóu tòng hé yān hóu téng tòng。","meaning":"Symptoms include a headache and sore throat.","meaningThai":"อาการต่างๆ ได้แก่ ปวดศีรษะและเจ็บคอ"},{"chinese":"这个价钱是否包括税款？","pinyin":"Zhè gè jià qián shì fǒu bāo kuò shuì kuǎn？","meaning":"Does the price include tax?","meaningThai":"ราคานี้รวมภาษีหรือไม่?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-029","chinese":"保留","pinyin":"bǎoliú","meaning":"to keep; to retain; to have reservations (about sth); to hold back (from saying sth); to put aside for later","meaningThai":"จอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她将保留她在该公司的重要股权。","pinyin":"Tā jiāng bǎo liú tā zài gāi gōng sī de zhòng yào gǔ quán。","meaning":"She will retain her very significant shareholding in the company.","meaningThai":"เธอจะยังคงถือหุ้นที่สำคัญมากในบริษัทต่อไป"},{"chinese":"我们保留打进电话的录音磁带。","pinyin":"Wǒ mén bǎo liú dǎ jìn diàn huà de lù yīn cí dài。","meaning":"We keep a tape of incoming calls.","meaningThai":"เราเก็บเทปสายเรียกเข้า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-030","chinese":"保险","pinyin":"bǎoxiǎn","meaning":"insurance; to insure; safe; secure; be sure; be bound to","meaningThai":"ประกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我买了健康保险。","pinyin":"Wǒ mǎi le jiàn kāng bǎo xiǎn.","meaning":"I bought health insurance.","meaningThai":"ฉันซื้อประกันสุขภาพ"}],"partOfSpeech":["noun","adjective","verb"]},
  {"id":"hsk5-031","chinese":"暴雨","pinyin":"bàoyǔ","meaning":"torrential rain; rainstorm","meaningThai":"ฝนตกหนัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"暴雨来了。","pinyin":"Bao yu lai le.","meaning":"The heavy rain is coming.","meaningThai":"ฝนตกหนักกำลังจะมา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-032","chinese":"抱怨","pinyin":"bàoyuàn","meaning":"to complain; to grumble; to harbor a complaint; to feel dissatisfied","meaningThai":"บ่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"不要抱怨。","pinyin":"Bu yao bao yuan.","meaning":"Don't complain.","meaningThai":"อย่าบ่น."}],"partOfSpeech":["verb"]},
  {"id":"hsk5-033","chinese":"保质期","pinyin":"bǎozhìqī","meaning":"shelf life; expiration date","meaningThai":"อายุการเก็บรักษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"超市会扔掉未在保质期前出售的食物，而家里则会扔掉吃不完的食物。","pinyin":"Chāo shì huì rēng diào wèi zài bǎo zhì qī qián chū shòu de shí wù， ér jiā lǐ zé huì rēng diào chī bù wán de shí wù。","meaning":"Supermarkets throw away food that is not sold before its sell-by date, while families throw away food that they can't finish eating.","meaningThai":"ซูเปอร์มาร์เก็ตทิ้งอาหารที่ไม่ได้ขายก่อนวันที่ขาย ในขณะที่ครอบครัวทิ้งอาหารที่พวกเขากินไม่หมด"},{"chinese":"一家名为“真正的垃圾食品项目”的英国公司表示，过了保质期的食品仍然可以安全食用。","pinyin":"Yī jiā míng wéi “ zhēn zhèng de lā jī shí pǐn xiàng mù ” de yīng guó gōng sī biǎo shì， guò le bǎo zhì qī de shí pǐn réng rán kě yǐ ān quán shí yòng。","meaning":"A UK company called The Real Junk Food Project says that food that has passed its sell-by date is still safe to eat.","meaningThai":"บริษัทในสหราชอาณาจักรชื่อ The Real Junk Food Project กล่าวว่าอาหารที่พ้นกำหนดการขายแล้วยังคงสามารถรับประทานได้อย่างปลอดภัย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-034","chinese":"包装","pinyin":"bāozhuāng","meaning":"to pack; to package; to wrap; packaging","meaningThai":"บรรจุภัณฑ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个包装很精美。","pinyin":"Zhe ge bao zhuang hen jing mei.","meaning":"This packaging is very elegant.","meaningThai":"บรรจุภัณฑ์นี้ดูหรูหรามาก"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-035","chinese":"把握","pinyin":"bǎwò","meaning":"to grasp (also fig.); to seize; to hold; assurance; certainty; sure (of the outcome)","meaningThai":"เข้าใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她已无法把握自己的未来。","pinyin":"Tā yǐ wú fǎ bǎ wò zì jǐ de wèi lái。","meaning":"She was no longer master of her own future.","meaningThai":"เธอไม่ใช่นายแห่งอนาคตของเธอเองอีกต่อไป"},{"chinese":"她有把握获得成功。","pinyin":"Tā yǒu bǎ wò huò dé chéng gōng。","meaning":"Success was within her grasp.","meaningThai":"ความสำเร็จอยู่ในมือของเธอ"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-036","chinese":"背","pinyin":"bèi","meaning":"variant of 背","meaningThai":"ถือ; หิ้วหลัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"如水流过鸭背般毫无反应。","pinyin":"Rú shuǐliú guò yā bèi bān háowú fǎnyìng.","meaning":"Like water off a duck&#x27;s back.","meaningThai":"เหมือนน้ำจากหลังเป็ด"},{"chinese":"我昨天整天都在背英文字。","pinyin":"Wǒ zuótiān zhěngtiān dōu zài bèi yīngwénzì.","meaning":"I learned English words by heart all day yesterday.","meaningThai":"เมื่อวานฉันเรียนคำศัพท์ภาษาอังกฤษด้วยใจทั้งวัน"},{"chinese":"他背周期表只是为了好玩。","pinyin":"Tā bèi zhōuqībiǎo zhǐshì wèile hǎowán.","meaning":"He learnt the periodic table by heart just for fun.","meaningThai":"เขาเรียนรู้ตารางธาตุด้วยใจเพียงเพื่อความสนุกสนาน"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-037","chinese":"背后","pinyin":"bèihòu","meaning":"behind; at the back; in the rear; behind sb's back","meaningThai":"ด้านหลัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那背后是什么意思？","pinyin":"Nà bèi hòu shì shí mó yì sī？","meaning":"What's the idea behind that?","meaningThai":"แนวคิดเบื้องหลังสิ่งนั้นคืออะไร?"},{"chinese":"下车，把手放在背后。","pinyin":"Xià chē， bǎ shǒu fàng zài bèi hòu。","meaning":"Step out of the car and place your hands behind your back.","meaningThai":"ก้าวออกจากรถแล้ววางมือไว้ด้านหลัง"}],"partOfSpeech":["other"]},
  {"id":"hsk5-038","chinese":"背景","pinyin":"bèijǐng","meaning":"background; backdrop; context; (fig.) powerful backer","meaningThai":"พื้นหลัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"选举的背景是逐渐不稳的局势。","pinyin":"Xuǎn jǔ de bèi jǐng shì zhú jiàn bù wěn de jú shì。","meaning":"The election will take place against a backdrop of increasing instability.","meaningThai":"การเลือกตั้งจะเกิดขึ้นท่ามกลางความไม่มั่นคงที่เพิ่มมากขึ้น"},{"chinese":"我不断听到背景音中有掌声。","pinyin":"Wǒ bù duàn tīng dào bèi jǐng yīn zhōng yǒu zhǎng shēng。","meaning":"I kept hearing the sound of applause in the background.","meaningThai":"ฉันยังคงได้ยินเสียงปรบมืออยู่เบื้องหลัง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-039","chinese":"被子","pinyin":"bèizi","meaning":"quilt","meaningThai":"ผ้าห่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"玛吉知道怎样缝被子。","pinyin":"Mǎ jí zhī dào zěn yàng féng bèi zǐ。","meaning":"Maggie knows how to quilt.","meaningThai":"แม็กกี้รู้วิธีควิ้ลท์"},{"chinese":"她做了很多被子。","pinyin":"Tā zuò le hěn duō bèi zǐ。","meaning":"She does a lot of quilting.","meaningThai":"เธอควิ้ลท์บ่อยมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-040","chinese":"本","pinyin":"běn","meaning":"root; stem; origin; source; this; the current; original; inherent; originally; classifier for books, periodicals, files etc","meaningThai":"เล่ม (ลักษณะนาม)","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我有一本书。","pinyin":"Wǒ yǒu yì běn shū.","meaning":"I have one book.","meaningThai":"ฉันมีหนังสือเล่มหนึ่ง"},{"chinese":"这本书很好看。","pinyin":"Zhè běn shū hěn hǎokàn.","meaning":"This book is enjoyable to read.","meaningThai":"หนังสือเล่มนี้อ่านเพลิน"},{"chinese":"你要哪本书？","pinyin":"Nǐ yào nǎ běn shū?","meaning":"Which book do you want?","meaningThai":"คุณต้องการหนังสือเล่มไหน?"}],"partOfSpeech":["pronoun","measure word","adverb","noun"]},
  {"id":"hsk5-041","chinese":"本地","pinyin":"běndì","meaning":"local; this locality","meaningThai":"ท้องถิ่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们完全没有尝试融入本地社区。","pinyin":"Tā mén wán quán méi yǒu cháng shì róng rù běn dì shè qū。","meaning":"They have not made any effort to integrate with the local community.","meaningThai":"พวกเขาไม่ได้พยายามบูรณาการกับชุมชนท้องถิ่น"},{"chinese":"本地牧师为他们主持了婚礼。","pinyin":"Běn dì mù shī wéi tā mén zhǔ chí le hūn lǐ。","meaning":"They were married by the local priest.","meaningThai":"ทั้งคู่แต่งงานกันโดยนักบวชท้องถิ่น"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-042","chinese":"本领","pinyin":"běnlǐng","meaning":"skill; ability; capability","meaningThai":"ความสามารถ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"本领就在于避开这两个极端，走中间路线。","pinyin":"Běn lǐng jiù zài yú bì kāi zhè liǎng gè jí duān， zǒu zhōng jiān lù xiàn。","meaning":"The skill is in steering a middle course between the two extremes.","meaningThai":"ทักษะคือการขับเคลื่อนเส้นทางสายกลางระหว่างสองขั้วสุดขั้ว"},{"chinese":"他只好使出说服人的全部本领。","pinyin":"Tā zhī hǎo shǐ chū shuō fú rén de quán bù běn lǐng。","meaning":"He had to use all his powers of persuasion.","meaningThai":"เขาต้องใช้พลังทั้งหมดในการโน้มน้าวใจ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-043","chinese":"本人","pinyin":"běnrén","meaning":"I; me; myself; oneself; yourself; himself; herself; the person concerned","meaningThai":"ตัวฉันเอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那张照片不如你本人好看。","pinyin":"Nà zhāng zhào piàn bù rú nǐ běn rén hǎo kàn。","meaning":"That photo doesn't do you justice.","meaningThai":"รูปนั้นไม่ยุติธรรมเลย"},{"chinese":"总统本人正在访问北京。","pinyin":"Zǒng tǒng běn rén zhèng zài fǎng wèn běi jīng。","meaning":"The president himself is on a visit to Beijing.","meaningThai":"ประธานาธิบดีเองก็กำลังเยือนกรุงปักกิ่ง"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-044","chinese":"本质","pinyin":"běnzhì","meaning":"essence; nature; innate character; intrinsic quality","meaningThai":"ธรรมชาติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"外人可能会误解这种关系的本质。","pinyin":"Wài rén kě néng huì wù jiě zhè zhǒng guān xì de běn zhì。","meaning":"An outsider might misconstrue the nature of the relationship.","meaningThai":"คนนอกอาจตีความธรรมชาติของความสัมพันธ์ผิดไป"},{"chinese":"他本质上来说是个教师而不是经理。","pinyin":"Tā běn zhì shàng lái shuō shì gè jiào shī ér bù shì jīng lǐ。","meaning":"He was, essentially, a teacher, not a manager.","meaningThai":"โดยพื้นฐานแล้วเขาเป็นครู ไม่ใช่ผู้จัดการ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-045","chinese":"必","pinyin":"bì","meaning":"certainly; must; will; necessarily","meaningThai":"ต้อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"悉尼是世界上的必游城市之一。","pinyin":"Xī ní shì shì jiè shàng de bì yóu chéng shì zhī yī。","meaning":"Sydney is one of the world's must-see cities.","meaningThai":"ซิดนีย์เป็นหนึ่งในเมืองที่ต้องไปชมของโลก"},{"chinese":"坠入爱河必已使你神魂颠倒。","pinyin":"Zhuì rù ài hé bì yǐ shǐ nǐ shén hún diān dǎo。","meaning":"Being in love must have addled your brain.","meaningThai":"การมีความรักคงจะเพิ่มสมองของคุณ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-046","chinese":"便","pinyin":"biàn","meaning":"plain; informal; suitable; convenient; opportune; to urinate or defecate; equivalent to 就: then; in that case; even if; soon afterwards","meaningThai":"สะดวก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"机器一坏，工作便停了下来。","pinyin":"Jī qì yī huài， gōng zuò biàn tíng le xià lái。","meaning":"Work came to a halt when the machine broke down.","meaningThai":"งานหยุดชะงักเมื่อเครื่องพัง"},{"chinese":"他们道别后，便各自走了。","pinyin":"Tā mén dào bié hòu， biàn gè zì zǒu le。","meaning":"They said goodbye and went their several ways.","meaningThai":"พวกเขากล่าวคำอำลาและไปตามทางต่างๆ"}],"partOfSpeech":["adverb","other"]},
  {"id":"hsk5-047","chinese":"变动","pinyin":"biàndòng","meaning":"to change; to fluctuate; change; fluctuation","meaningThai":"เปลี่ยน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我觉得没人真正赞成这些变动。","pinyin":"Wǒ jué dé méi rén zhēn zhèng zàn chéng zhè xiē biàn dòng。","meaning":"It strikes me that nobody is really in favour of the changes.","meaningThai":"ฉันรู้สึกว่าไม่มีใครเห็นด้วยกับการเปลี่ยนแปลงนี้จริงๆ"},{"chinese":"时间安排也许会有些小小的变动。","pinyin":"Shí jiān ān pái yě xǔ huì yǒu xiē xiǎo xiǎo de biàn dòng。","meaning":"There may be some minor changes to the schedule.","meaningThai":"อาจมีการเปลี่ยนแปลงกำหนดการเล็กน้อย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-048","chinese":"便利","pinyin":"biànlì","meaning":"convenient; easy; to facilitate","meaningThai":"สะดวก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"水果是维生素和能量的便利来源。","pinyin":"Shuǐ guǒ shì wéi shēng sù hé néng liáng de biàn lì lái yuán。","meaning":"Fruit is a convenient source of vitamins and energy.","meaningThai":"ผลไม้เป็นแหล่งวิตามินและพลังงานที่สะดวก"},{"chinese":"在这个度假胜地你可享受所有现代旅游的舒适与便利。","pinyin":"Zài zhè gè dù jiǎ shèng dì nǐ kě xiǎng shòu suǒ yǒu xiàn dài lǚ yóu de shū shì yǔ biàn lì。","meaning":"In this resort you can enjoy all the comfort and convenience of modern tourism.","meaningThai":"ในรีสอร์ทแห่งนี้คุณสามารถเพลิดเพลินกับความสะดวกสบายของการท่องเที่ยวสมัยใหม่"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-049","chinese":"便利店","pinyin":"biànlìdiàn","meaning":"convenience store","meaningThai":"ร้านสะดวกซื้อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"大多数加油站都附带有便利店并非偶然。","pinyin":"Dà duō shù jiā yóu zhàn dū fù dài yǒu biàn lì diàn bìng fēi ǒu rán。","meaning":"It's no accident that most gas stations have convenience stores attached.","meaningThai":"ไม่ใช่เรื่องบังเอิญที่ปั๊มน้ำมันส่วนใหญ่จะมีร้านสะดวกซื้อติดอยู่"},{"chinese":"你听说了吗？加油站旁边的便利店昨晚被抢劫了。","pinyin":"Nǐ tīng shuō le ma？ jiā yóu zhàn páng biān de biàn lì diàn zuó wǎn bèi qiāng jié le。","meaning":"Did you hear that the convenience store next to the gas station was held up last night?","meaningThai":"ได้ยินมาว่าเมื่อคืนร้านสะดวกซื้อข้างปั๊มน้ำมันถูกจัดขึ้น?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-050","chinese":"表达","pinyin":"biǎodá","meaning":"to express; to convey","meaningThai":"ด่วน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我大概未把自己的意思表达清楚。","pinyin":"Wǒ dà gài wèi bǎ zì jǐ de yì sī biǎo dá qīng chǔ。","meaning":"Perhaps I have not expressed myself very well.","meaningThai":"บางทีฉันอาจจะแสดงออกได้ไม่ดีนัก"},{"chinese":"人们以投票方式表达他们的愿望。","pinyin":"Rén mén yǐ tóu piào fāng shì biǎo dá tā mén de yuàn wàng。","meaning":"The people make their wishes known through the ballot box.","meaningThai":"ประชาชนแสดงความปรารถนาของตนผ่านตู้ลงคะแนน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-051","chinese":"表面","pinyin":"biǎomiàn","meaning":"surface; face; outside; appearance","meaningThai":"พื้นผิว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"湿气被吸到织物表面而蒸发。","pinyin":"Shī qì bèi xī dào zhī wù biǎo miàn ér zhēng fā。","meaning":"Moisture is drawn to the surface of the fabric so that it evaporates.","meaningThai":"ความชื้นถูกดูดไปที่พื้นผิวของผ้าเพื่อให้ระเหยออกไป"},{"chinese":"鞋底表面有较浅的纹理。","pinyin":"Xié dǐ biǎo miàn yǒu jiào qiǎn de wén lǐ。","meaning":"The shoe's sole had a slightly textured surface.","meaningThai":"พื้นรองเท้ามีพื้นผิวเล็กน้อย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-052","chinese":"表明","pinyin":"biǎomíng","meaning":"to make clear; to make known; to state clearly; to indicate; known","meaningThai":"แสดง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"描记图表明心率正常。","pinyin":"Miáo jì tú biǎo míng xīn shuài zhèng cháng。","meaning":"The trace showed a normal heart rhythm.","meaningThai":"ร่องรอยแสดงจังหวะการเต้นของหัวใจปกติ"},{"chinese":"化验表明她非常贫血。","pinyin":"Huà yàn biǎo míng tā fēi cháng pín xiě。","meaning":"Tests showed that she was very anaemic.","meaningThai":"ผลการทดสอบพบว่าเธอเป็นโรคโลหิตจางมาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-053","chinese":"表情","pinyin":"biǎoqíng","meaning":"(facial) expression; to express one's feelings","meaningThai":"การแสดงออก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"约翰脸上显出惭愧的表情。","pinyin":"Yuē hàn liǎn shàng xiǎn chū cán kuì de biǎo qíng。","meaning":"John had a guilty look on his face.","meaningThai":"จอห์นมีสีหน้ารู้สึกผิด"},{"chinese":"她的表情显得严肃起来。","pinyin":"Tā de biǎo qíng xiǎn dé yán sù qǐ lái。","meaning":"Her expression grew solemn.","meaningThai":"สีหน้าของเธอดูเคร่งขรึม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-054","chinese":"标题","pinyin":"biāotí","meaning":"title; heading; headline; caption; subject","meaningThai":"ชื่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"章节标题有助于了解书的内容。","pinyin":"Zhāng jié biāo tí yǒu zhù yú le jiě shū de nèi róng。","meaning":"The chapter headings are useful signposts to the content of the book.","meaningThai":"ส่วนหัวของบทเป็นป้ายบอกทางที่เป็นประโยชน์สำหรับเนื้อหาของหนังสือ"},{"chinese":"报道的标题是“回到未来”。","pinyin":"Bào dào de biāo tí shì “ huí dào wèi lái”。","meaning":"The story was headlined 'Back to the future'.","meaningThai":"เรื่องนี้มีหัวข้อว่า 'กลับสู่อนาคต'"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-055","chinese":"标志","pinyin":"biāozhì","meaning":"sign; mark; symbol; logo; to symbolize; to indicate; to mark","meaningThai":"โลโก้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"价格并不总是质量的准确标志。","pinyin":"Jià gé bìng bù zǒng shì zhì liáng de zhǔn què biāo zhì。","meaning":"Price is not always an accurate marker of quality.","meaningThai":"ราคาไม่ใช่ตัวบ่งชี้คุณภาพที่ถูกต้องเสมอไป"},{"chinese":"她没有理会警示前方危险的标志。","pinyin":"Tā méi yǒu lǐ huì jǐng shì qián fāng wēi xiǎn de biāo zhì。","meaning":"She had ignored the warning signs of trouble ahead.","meaningThai":"เธอเพิกเฉยต่อสัญญาณเตือนปัญหาที่อยู่ข้างหน้า"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-056","chinese":"彼此","pinyin":"bǐcǐ","meaning":"each other; one another","meaningThai":"กันและกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们彼此多年没有见面了。","pinyin":"Tā mén bǐ cǐ duō nián méi yǒu jiàn miàn le。","meaning":"They haven't seen each other for years.","meaningThai":"พวกเขาไม่ได้เจอกันมาหลายปีแล้ว"},{"chinese":"他们伸出双臂彼此拥抱。","pinyin":"Tā mén shēn chū shuāng bì bǐ cǐ yōng bào。","meaning":"They put their arms around each other and hugged.","meaningThai":"พวกเขาโอบแขนกันและกอดกัน"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-057","chinese":"别","pinyin":"bié","meaning":"surname Bie","meaningThai":"อย่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我会别。","pinyin":"Wǒ huì bié.","meaning":"I can don't.","meaningThai":"ฉันทำไม่ได้"},{"chinese":"他正在别。","pinyin":"Tā zhèngzài bié.","meaning":"He is don'ting.","meaningThai":"เขาไม่ทำ."},{"chinese":"我们一起别吧。","pinyin":"Wǒmen yìqǐ bié ba.","meaning":"Let’s don't together.","meaningThai":"อย่ามารวมกันเลย."}],"partOfSpeech":["adverb","verb","pronoun"]},
  {"id":"hsk5-058","chinese":"比分","pinyin":"bǐfēn","meaning":"score","meaningThai":"คะแนน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们的比分现在相等。","pinyin":"Wǒ mén de bǐ fēn xiàn zài xiāng děng。","meaning":"Our scores are now even.","meaningThai":"ตอนนี้คะแนนของเราเท่ากันแล้ว"},{"chinese":"最终的比分是4:3。","pinyin":"Zuì zhōng de bǐ fēn shì4:3。","meaning":"The final score was 4–3.","meaningThai":"คะแนนสุดท้ายคือ 4–3"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-059","chinese":"毕竟","pinyin":"bìjìng","meaning":"after all; all in all; when all is said and done; in the final analysis","meaningThai":"หลังจากนั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"法老毕竟被当作神，因而长生不死。","pinyin":"Fǎ lǎo bì jìng bèi dāng zuò shén， yīn ér cháng shēng bù sǐ。","meaning":"The pharaohs, after all, were considered gods and therefore immortal.","meaningThai":"ฟาโรห์ถือเป็นเทพเจ้าและเป็นอมตะด้วยเหตุนี้"},{"chinese":"他毕竟不能阻止世上所有的恶行。","pinyin":"Tā bì jìng bù néng zǔ zhǐ shì shàng suǒ yǒu de è háng。","meaning":"He could not, after all, stop all the evil in the world.","meaningThai":"ในที่สุดเขาก็ไม่สามารถหยุดยั้งความชั่วร้ายทั้งหมดในโลกได้"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-060","chinese":"比例","pinyin":"bǐlì","meaning":"proportion; scale","meaningThai":"สัดส่วน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"1772 年，埃斯皮利先生計算出法國人口超過 2,200 萬人；其中男性 10,562,631 人，女性 11,451,726 人；因此，女性與男性的比例約為 14 比 13。","pinyin":"1772  nián， āi sī pí lì xiān shēng jì suàn chū fǎ guó rén kǒu chāo guò 2,200  wàn rén； qí zhōng nán xìng 10,562,631  rén， nǚ xìng 11,451,726  rén； yīn cǐ， nǚ xìng yǔ nán xìng de bǐ lì yuē wéi  14  bǐ 13。","meaning":"Monsieur D'Espilly, in the year 1772, calculated the population of France at upwards of 22 millions; namely, 10,562,631 males, and 11,451,726 females; consequently the proportion of females to males was about 14 to 13.","meaningThai":"Monsieur D'Espilly ในปี พ.ศ. 2315 คำนวณจำนวนประชากรของฝรั่งเศสได้มากกว่า 22 ล้านคน เป็นชาย 10,562,631 คน และหญิง 11,451,726 คน ดังนั้นสัดส่วนของผู้หญิงต่อผู้ชายจึงอยู่ที่ประมาณ 14 ถึง 13"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-061","chinese":"避免","pinyin":"bìmiǎn","meaning":"to avert; to prevent; to avoid; to refrain from","meaningThai":"หลีกเลี่ยง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"工人们戴着面罩避免吸入尘土。","pinyin":"Gōng rén mén dài zháo miàn zhào bì miǎn xī rù chén tǔ。","meaning":"The workers wear masks to avoid inhaling the dust.","meaningThai":"คนงานสวมหน้ากากอนามัยเพื่อหลีกเลี่ยงการสูดดมฝุ่น"},{"chinese":"他们避免黄昏后独自出门。","pinyin":"Tā mén bì miǎn huáng hūn hòu dú zì chū mén。","meaning":"They avoid going out alone after dark.","meaningThai":"พวกเขาหลีกเลี่ยงการออกไปคนเดียวหลังมืด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-062","chinese":"闭幕式","pinyin":"bìmùshì","meaning":"closing ceremony","meaningThai":"พิธีปิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"欧洲颂歌在开幕式和闭幕式上演奏。","pinyin":"Ōu zhōu sòng gē zài kāi mù shì hé bì mù shì shàng yǎn zòu。","meaning":"The European anthem was played at the opening and closing ceremonies.","meaningThai":"มีการเล่นเพลงชาติยุโรปในพิธีเปิดและปิด"},{"chinese":"赛手们慢跑进入比赛场地，结束了闭幕式。","pinyin":"Sài shǒu mén màn pǎo jìn rù bǐ sài cháng dì， jié shù le bì mù shì。","meaning":"The competitors cantered into the arena to conclude the closing ceremony.","meaningThai":"ผู้เข้าแข่งขันต่างพากันเข้าสู่สนามเพื่อสรุปพิธีปิด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-063","chinese":"饼","pinyin":"bǐng","meaning":"round flat cake; cookie; cake; pastry","meaningThai":"เค้ก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的胡萝卜饼好吃极了。","pinyin":"Tā de hú luó bǔ bǐng hǎo chī jí le。","meaning":"Her carrot cake is divine.","meaningThai":"เค้กแครอทของเธอช่างศักดิ์สิทธิ์"},{"chinese":"这种饼很能填饱肚子。","pinyin":"Zhè zhǒng bǐng hěn néng tián bǎo dù zǐ。","meaning":"This cake is very filling.","meaningThai":"เค้กชิ้นนี้อิ่มมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-064","chinese":"病房","pinyin":"bìngfáng","meaning":"ward (of a hospital); sickroom","meaningThai":"วอร์ด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们把她转移到了精神病病房。","pinyin":"Tā mén bǎ tā zhuǎn yí dào le jīng shén bìng bìng fáng。","meaning":"They transferred her to the psychiatric ward.","meaningThai":"พวกเขาส่งเธอไปที่แผนกจิตเวช"},{"chinese":"允许密友进入病房探视病人。","pinyin":"Yǔn xǔ mì yǒu jìn rù bìng fáng tàn shì bìng rén。","meaning":"Close friends were allowed into the sickroom.","meaningThai":"เพื่อนสนิทได้รับอนุญาตให้เข้าห้องผู้ป่วย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-065","chinese":"病情","pinyin":"bìngqíng","meaning":"state of an illness; patient's condition","meaningThai":"การเจ็บป่วย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"对这种病情有各种疗法。","pinyin":"Duì zhè zhǒng bìng qíng yǒu gè zhǒng liáo fǎ。","meaning":"There are various treat we are pirates, these data are stolen from youdao s available for this condition.","meaningThai":"มีวิธีการรักษาที่หลากหลายสำหรับภาวะนี้"},{"chinese":"她的病情突然急剧恶化。","pinyin":"Tā de bìng qíng tū rán jí jù è huà。","meaning":"Her condition took a sharp turn for the worse.","meaningThai":"อาการของเธอแย่ลงอย่างมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-066","chinese":"必然","pinyin":"bìrán","meaning":"inevitable; certain; necessity","meaningThai":"หลีกเลี่ยงไม่ได้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"减税政策必然导致公共开支减少。","pinyin":"Jiǎn shuì zhèng cè bì rán dǎo zhì gōng gòng kāi zhī jiǎn shǎo。","meaning":"Policies of tax reduction must lead to reduced public expenditure.","meaningThai":"นโยบายการลดภาษีจะต้องนำไปสู่การลดค่าใช้จ่ายสาธารณะ"},{"chinese":"这一事件必然使华盛顿大为尴尬。","pinyin":"Zhè yī shì jiàn bì rán shǐ huá shèng dùn dà wéi gān gà。","meaning":"This episode is bound to be a deep embarrassment for Washington.","meaningThai":"ตอนนี้คงจะเป็นเรื่องที่น่าอับอายอย่างมากสำหรับวอชิงตัน"}],"partOfSpeech":["adverb","adjective","noun"]},
  {"id":"hsk5-067","chinese":"必需","pinyin":"bìxū","meaning":"to need; to require; essential; indispensable","meaningThai":"ที่จำเป็น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"此行业的产品分配环节必需重组。","pinyin":"Cǐ háng yè de chǎn pǐn fēn pèi huán jié bì xū zhòng zǔ。","meaning":"Reorganization is necessary on the distributive side of this industry.","meaningThai":"การปรับโครงสร้างองค์กรเป็นสิ่งจำเป็นในด้านการกระจายตัวของอุตสาหกรรมนี้"},{"chinese":"他们无法得到住房取暖必需的燃料。","pinyin":"Tā mén wú fǎ dé dào zhù fáng qǔ nuǎn bì xū de rán liào。","meaning":"They've been deprived of the fuel necessary to heat their homes.","meaningThai":"พวกเขาขาดเชื้อเพลิงที่จำเป็นในการทำความร้อนให้กับบ้าน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-068","chinese":"必要","pinyin":"bìyào","meaning":"necessary; essential; indispensable; required","meaningThai":"จำเป็น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们没必要节省—再吃点！","pinyin":"Wǒ mén méi bì yào jié shěng — zài chī diǎn！","meaning":"We don't need to stint ourselves—have some more!","meaningThai":"เราไม่จำเป็นต้องจำกัดตัวเอง—มีเพิ่มอีก!"},{"chinese":"好啦，没有必要炫耀了。","pinyin":"Hǎo lā， méi yǒu bì yào xuàn yào le。","meaning":"All right, there's no need to show off.","meaningThai":"เอาล่ะ ไม่ต้องโชว์หรอก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-069","chinese":"比喻","pinyin":"bǐyù","meaning":"to compare; to liken to; metaphor; analogy; figure of speech; figuratively","meaningThai":"อุปมา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"牧师讲道时用了亡羊的比喻。","pinyin":"Mù shī jiǎng dào shí yòng le wáng yáng de bǐ yù。","meaning":"The minister preached a sermon on the parable of the lost sheep.","meaningThai":"รัฐมนตรีเทศนาเรื่องอุปมาเรื่องแกะหลง"},{"chinese":"老师打了个比喻，把人的心脏比作水泵。","pinyin":"Lǎo shī dǎ le gè bǐ yù， bǎ rén de xīn zāng bǐ zuò shuǐ bèng。","meaning":"The teacher drew an analogy between the human heart and a pump.","meaningThai":"ครูได้เปรียบเทียบระหว่างหัวใจมนุษย์กับปั๊ม"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-070","chinese":"拨打","pinyin":"bōdǎ","meaning":"to call; to dial","meaningThai":"หมุนหมายเลข","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"如有问题，请拨打这个电话号码。","pinyin":"Rú yǒu wèn tí， qǐng bō dǎ zhè gè diàn huà hào mǎ。","meaning":"If you have any issues, please call this number.","meaningThai":"หากมีปัญหากรุณาโทรไปที่หมายเลขนี้"},{"chinese":"欲知详情，请拨打这个电话号码。","pinyin":"Yù zhī xiáng qíng， qǐng bō dǎ zhè gè diàn huà hào mǎ。","meaning":"For further details call this number.","meaningThai":"หากต้องการรายละเอียดเพิ่มเติมโทรไปที่หมายเลขนี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-071","chinese":"玻璃","pinyin":"bōli","meaning":"glass; (slang) male homosexual","meaningThai":"กระจก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"屋里到处落满了玻璃碎片。","pinyin":"Wū lǐ dào chǔ luò mǎn le bō lí suì piàn。","meaning":"Pieces of glass sprayed all over the room.","meaningThai":"เศษแก้วก็กระเด็นไปทั่วห้อง"},{"chinese":"街上到处是玻璃碎片。","pinyin":"Jiē shàng dào chǔ shì bō lí suì piàn。","meaning":"Broken glass littered the streets.","meaningThai":"กระจกแตกเกลื่อนถนน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-072","chinese":"博物馆","pinyin":"bówùguǎn","meaning":"museum","meaningThai":"พิพิธภัณฑ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这家博物馆由私人提供资金。","pinyin":"Zhè jiā bó wù guǎn yóu sī rén tí gōng zī jīn。","meaning":"The museum is privately funded.","meaningThai":"พิพิธภัณฑ์ได้รับทุนจากเอกชน"},{"chinese":"这家博物馆的确值得参观。","pinyin":"Zhè jiā bó wù guǎn de què zhí dé cān guān。","meaning":"The museum is certainly worth a visit.","meaningThai":"พิพิธภัณฑ์แห่งนี้คุ้มค่าแก่การเยี่ยมชมอย่างแน่นอน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-073","chinese":"补充","pinyin":"bǔchōng","meaning":"to replenish; to supplement; to complement; additional; supplementary","meaningThai":"เติมเงิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“还有别迟到。”她补充说道。","pinyin":"“ huán yǒu bié chí dào。” tā bǔ chōng shuō dào。","meaning":"'And don't be late,' she added.","meaningThai":"“และอย่าช้า” เธอกล่าวเสริม"},{"chinese":"铁和叶酸补充剂常给孕妇服用。","pinyin":"Tiě hé yè suān bǔ chōng jì cháng gěi yùn fù fú yòng。","meaning":"Iron and folic acid supplements are frequently given to pregnant women.","meaningThai":"สตรีมีครรภ์มักให้อาหารเสริมธาตุเหล็กและกรดโฟลิก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-074","chinese":"不得了","pinyin":"bùdéliǎo","meaning":"desperately serious; disastrous; extremely; exceedingly","meaningThai":"เหลือเชื่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"事故前一刻发生的事他都记不得了。","pinyin":"Shì gù qián yī kè fā shēng de shì tā dū jì bù dé le。","meaning":"What happened just before the accident was expunged from his memory.","meaningThai":"สิ่งที่เกิดขึ้นก่อนเกิดอุบัติเหตุจะถูกลบออกจากความทรงจำของเขา"},{"chinese":"她总是让我们做多得不得了的家庭作业。","pinyin":"Tā zǒng shì ràng wǒ mén zuò duō dé bù dé le de jiā tíng zuò yè。","meaning":"She always gives us far too much homework.","meaningThai":"เธอมักจะให้การบ้านเรามากเกินไปเสมอ"}],"partOfSpeech":["expression"]},
  {"id":"hsk5-075","chinese":"不符","pinyin":"bùfú","meaning":"Does not match","meaningThai":"ไม่ตรงกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这座建筑物不符合安全条例。","pinyin":"Zhè zuò jiàn zhù wù bù fú hé ān quán tiáo lì。","meaning":"The building does not conform with safety regulations.","meaningThai":"อาคารไม่เป็นไปตามข้อกำหนดด้านความปลอดภัย"},{"chinese":"她讲话不符合语法规则，却很流利。","pinyin":"Tā jiǎng huà bù fú hé yǔ fǎ guī zé， què hěn liú lì。","meaning":"She talked ungrammatically but fluently.","meaningThai":"เธอพูดอย่างไม่มีไวยากรณ์แต่คล่อง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-076","chinese":"不利","pinyin":"búlì","meaning":"unfavorable; disadvantageous; harmful; detrimental","meaningThai":"ไม่เอื้ออำนวย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这项交易不会对你公司不利。","pinyin":"Zhè xiàng jiāo yì bù huì duì nǐ gōng sī bù lì。","meaning":"The deal will not be disadvantageous to your company.","meaningThai":"ข้อตกลงนี้จะไม่เป็นผลเสียต่อบริษัทของคุณ"},{"chinese":"这项政策将不利于和平进程。","pinyin":"Zhè xiàng zhèng cè jiāng bù lì yú hé píng jìn chéng。","meaning":"The policy will be detri we are pirates, these data are stolen from youdao al to the peace process.","meaningThai":"นโยบายนี้จะเป็นอันตรายต่อกระบวนการสันติภาพ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-077","chinese":"不良","pinyin":"bùliáng","meaning":"bad; harmful; unhealthy","meaningThai":"แย่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"众所周知，这种药具有不良副作用。","pinyin":"Zhòng suǒ zhōu zhī， zhè zhǒng yào jù yǒu bù liáng fù zuò yòng。","meaning":"This drug is known to have adverse side effects.","meaningThai":"เป็นที่รู้กันว่ายานี้มีผลข้างเคียง"},{"chinese":"贫困和健康不良常有连带关系。","pinyin":"Pín kùn hé jiàn kāng bù liáng cháng yǒu lián dài guān xì。","meaning":"Poverty and poor health often go hand in hand.","meaningThai":"ความยากจนและสุขภาพที่ไม่ดีมักจะมาคู่กัน"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-078","chinese":"不然","pinyin":"bùrán","meaning":"not so; no; or else; otherwise; if not; How about ...?","meaningThai":"มิฉะนั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"别太使劲拉，不然把手会脱落。","pinyin":"Bié tài shǐ jìn lā， bù rán bǎ shǒu huì tuō luò。","meaning":"Don't pull so hard or the handle will come off.","meaningThai":"อย่าดึงแรงๆ ไม่เช่นนั้นที่จับจะหลุดออกมา"},{"chinese":"我们最好赶快，不然要受罚的。","pinyin":"Wǒ mén zuì hǎo gǎn kuài， bù rán yào shòu fá de。","meaning":"We'd better hurry or we'll be in for it.","meaningThai":"เราควรรีบดีกว่า ไม่งั้นเราจะเข้าไปแล้ว"}],"partOfSpeech":["conjunction","verb","adjective"]},
  {"id":"hsk5-079","chinese":"不幸","pinyin":"búxìng","meaning":"misfortune; adversity; unfortunate; sad; unfortunately","meaningThai":"โชคไม่ดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"不幸的是她已擦掉了那条信息。","pinyin":"Bù xìng de shì tā yǐ cā diào le nà tiáo xìn xī。","meaning":"It was unfortunate that she had rubbed out the message.","meaningThai":"น่าเสียดายที่เธอลบข้อความออกไป"},{"chinese":"不幸的是，她总是说错话。","pinyin":"Bù xìng de shì， tā zǒng shì shuō cuò huà。","meaning":"She has the unfortunate knack of always saying the wrong thing.","meaningThai":"เธอมีพรสวรรค์ด้านการพูดผิดอยู่เสมอ"}],"partOfSpeech":["adjective","noun"]},
  {"id":"hsk5-080","chinese":"步行","pinyin":"bùxíng","meaning":"to go on foot; to walk","meaningThai":"เดิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“我宁愿步行。”她答道。","pinyin":"“ wǒ níng yuàn bù háng。” tā dá dào。","meaning":"'I'd prefer to walk,' she answered.","meaningThai":"“ฉันอยากเดินมากกว่า” เธอตอบ"},{"chinese":"我步行上班，可以省车钱。","pinyin":"Wǒ bù háng shàng bān， kě yǐ shěng chē qián。","meaning":"I save on fares by walking to work.","meaningThai":"ฉันประหยัดค่าโดยสารด้วยการเดินไปทำงาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-081","chinese":"不要紧","pinyin":"búyàojǐn","meaning":"unimportant; not serious; it doesn't matter; never mind; it looks all right, but","meaningThai":"ไม่สำคัญ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"不要紧，慢慢来。","pinyin":"Bú yào jǐn, màn màn lái.","meaning":"It's okay, take your time.","meaningThai":"ไม่เป็นไร ใช้เวลาของคุณ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-082","chinese":"不足","pinyin":"bùzú","meaning":"insufficient; lacking; deficiency; not enough; inadequate; not worth; cannot; should not","meaningThai":"ไม่เพียงพอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"准备不足。","pinyin":"Zhun bei bu zu.","meaning":"Insufficient preparation.","meaningThai":"การเตรียมการไม่เพียงพอ"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-083","chinese":"才","pinyin":"cái","meaning":"ability; talent; sb of a certain type; a capable individual; then and only then; just now; (before an expression of quantity) only","meaningThai":"เท่านั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我昨天晚上十二点才睡。","pinyin":"Wǒ zuótiānwǎnshàng shíèrdiǎn cái shuì.","meaning":"I did not go to sleep until midnight last night.","meaningThai":"เมื่อคืนฉันไม่ได้นอนจนถึงเที่ยงคืน"},{"chinese":"他学了两年才明白这个问题。","pinyin":"Tā xué le liǎngnián cái míngbai zhège wèntí.","meaning":"He studied for two years before understanding this problem.","meaningThai":"เขาศึกษามาสองปีก่อนที่จะเข้าใจปัญหานี้"},{"chinese":"我们到家以后才发现护照不见了。","pinyin":"Wǒmen dào jiā yǐhòu cái fāxiàn hùzhào bújiàn le.","meaning":"Only after we got home did we discover the passport was missing.","meaningThai":"หลังจากที่เรากลับถึงบ้านเราจึงพบว่าหนังสือเดินทางหายไป"}],"partOfSpeech":["adverb","conjunction","noun"]},
  {"id":"hsk5-084","chinese":"采访","pinyin":"cǎifǎng","meaning":"to interview; to gather news; to hunt for and collect; to cover","meaningThai":"สัมภาษณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们能采访他吗？","pinyin":"Wǒ mén néng cǎi fǎng tā ma？","meaning":"Can we interview him?","meaningThai":"เราสัมภาษณ์เขาได้ไหม?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-085","chinese":"裁判","pinyin":"cáipàn","meaning":"judgment; to referee; umpire; judge; referee","meaningThai":"ผู้ตัดสิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们似乎得罪了裁判。","pinyin":"Tā mén sì hū dé zuì le cái pàn。","meaning":"They seemed to offend the referee.","meaningThai":"ดูเหมือนพวกเขาจะรุกรานผู้ตัดสิน"},{"chinese":"裁判抛硬币来决定谁来开球。","pinyin":"Cái pàn pāo yìng bì lái jué dìng shuí lái kāi qiú。","meaning":"The coin toss decides who will kick off the match.","meaningThai":"การโยนเหรียญจะตัดสินว่าใครจะเป็นผู้เริ่มการแข่งขัน"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-086","chinese":"采取","pinyin":"cǎiqǔ","meaning":"to adopt or carry out (measures, policies, course of action); to take","meaningThai":"เอา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"政府只得采取紧急措施。","pinyin":"Zhèng fǔ zhī dé cǎi qǔ jǐn jí cuò shī。","meaning":"The government had to take emergency action.","meaningThai":"รัฐบาลต้องดำเนินการฉุกเฉิน"},{"chinese":"应该采取措施减少污染。","pinyin":"Yīng gāi cǎi qǔ cuò shī jiǎn shǎo wū rǎn。","meaning":"Steps are to be taken to abate pollution.","meaningThai":"จะต้องดำเนินการตามขั้นตอนเพื่อลดมลพิษ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-087","chinese":"彩色","pinyin":"cǎisè","meaning":"color; multicolored","meaningThai":"สีสัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"彩色的气球很漂亮。","pinyin":"Cǎi sè de qi qiú hěn piāo liàng.","meaning":"Colorful balloons are beautiful.","meaningThai":"ลูกโป่งสีสันสดใสสวยงามมาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-088","chinese":"采用","pinyin":"cǎiyòng","meaning":"to adopt; to employ; to use","meaningThai":"ใช้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"学校采用各种各样的测试方法。","pinyin":"Xué xiào cǎi yòng gè zhǒng gè yàng de cè shì fāng fǎ。","meaning":"Schools use various methods of testing.","meaningThai":"โรงเรียนใช้วิธีการทดสอบที่หลากหลาย"},{"chinese":"这些房屋将采用最新节能技术。","pinyin":"Zhè xiē fáng wū jiāng cǎi yòng zuì xīn jié néng jì shù。","meaning":"The houses will boast the latest energy-saving technology.","meaningThai":"บ้านจะมีเทคโนโลยีประหยัดพลังงานล่าสุด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-089","chinese":"藏","pinyin":"cáng","meaning":"Tibet; abbr. for Xizang or Tibet Autonomous Region 藏","meaningThai":"ทิเบต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这张画在档案室藏了40多年。","pinyin":"Zhè zhāng huà zài dàng àn shì cáng le 40 duō nián。","meaning":"The picture lay hidden in the archives for over 40 years.","meaningThai":"รูปภาพนี้ซ่อนอยู่ในเอกสารสำคัญมากว่า 40 ปี"},{"chinese":"当他们走近时，那个小男孩跑开了并藏了起来。","pinyin":"Dāng tā mén zǒu jìn shí， nà gè xiǎo nán hái pǎo kāi le bìng cáng le qǐ lái。","meaning":"At their approach the little boy ran away and hid.","meaningThai":"เมื่อเข้าใกล้เด็กน้อยก็วิ่งหนีไปซ่อนตัว"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-090","chinese":"参考","pinyin":"cānkǎo","meaning":"consultation; reference; to consult; to refer","meaningThai":"อ้างถึง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"获得语义知识的参考点是这个世界。","pinyin":"Huò dé yǔ yì zhī shí de cān kǎo diǎn shì zhè gè shì jiè。","meaning":"The point of reference for semantic knowledge is the world.","meaningThai":"จุดอ้างอิงสำหรับความรู้เชิงความหมายคือโลก"},{"chinese":"每一章的后面都有一组参考书目。","pinyin":"Měi yī zhāng de hòu miàn dū yǒu yī zǔ cān kǎo shū mù。","meaning":"There is a list of references at the end of each chapter.","meaningThai":"มีรายการอ้างอิงอยู่ท้ายแต่ละบท"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-091","chinese":"餐饮","pinyin":"cānyǐn","meaning":"food and beverage; catering; repast","meaningThai":"อาหารและเครื่องดื่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"餐饮行业。","pinyin":"Can yin hang ye.","meaning":"Food and beverage industry.","meaningThai":"อุตสาหกรรมอาหารและเครื่องดื่ม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-092","chinese":"参与","pinyin":"cānyù","meaning":"to participate (in sth)","meaningThai":"เข้าร่วม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"白宫方面没有参与任何会谈。","pinyin":"Bái gōng fāng miàn méi yǒu cān yǔ rèn hé huì tán。","meaning":"The White House has not participated in any talks.","meaningThai":"ทำเนียบขาวไม่ได้เข้าร่วมการเจรจาใดๆ"},{"chinese":"他拒绝参与任何暴力活动。","pinyin":"Tā jù jué cān yǔ rèn hé bào lì huó dòng。","meaning":"He refused to be a party to any violence.","meaningThai":"เขาปฏิเสธที่จะเป็นภาคีกับความรุนแรงใดๆ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-093","chinese":"操作","pinyin":"cāozuò","meaning":"to work; to operate; to manipulate","meaningThai":"ดำเนินงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"合同明确规定谁可以操作机器。","pinyin":"Hé tóng míng què guī dìng shuí kě yǐ cāo zuò jī qì。","meaning":"The contract clearly specifies who can operate the machinery.","meaningThai":"สัญญาระบุอย่างชัดเจนว่าใครสามารถใช้งานเครื่องจักรได้"},{"chinese":"我练习过操作这些控制装置。","pinyin":"Wǒ liàn xí guò cāo zuò zhè xiē kòng zhì zhuāng zhì。","meaning":"I practised operating the controls.","meaningThai":"ฉันฝึกควบคุมการควบคุม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-094","chinese":"册","pinyin":"cè","meaning":"book; booklet; classifier for books","meaningThai":"หนังสือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"每一册都用颜色鲜亮的布料装订。","pinyin":"Měi yī cè dū yòng yán sè xiān liàng de bù liào zhuāng dìng。","meaning":"Each volume is bound in bright-coloured cloth.","meaningThai":"แต่ละเล่มเย็บด้วยผ้าสีสดใส"},{"chinese":"丛书的第三册现在正准备出版。","pinyin":"Cóng shū de dì sān cè xiàn zài zhèng zhǔn bèi chū bǎn。","meaning":"The third book in the series is currently in preparation.","meaningThai":"หนังสือเล่มที่สามในชุดนี้อยู่ระหว่างการเตรียมการ"}],"partOfSpeech":["measure word","other"]},
  {"id":"hsk5-095","chinese":"测","pinyin":"cè","meaning":"to survey; to measure; to conjecture","meaningThai":"ทดสอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"要测一下它的味道。棒极了。","pinyin":"Yào cè yī xià tā de wèi dào。 bàng jí le。","meaning":"It needs a taste test. Yum.","meaningThai":"มันต้องมีการทดสอบรสชาติ ยำ"},{"chinese":"这样的沉静不能测透、侵袭着一切。","pinyin":"Zhè yàng de chén jìng bù néng cè tòu、 qīn xí zháo yī qiē。","meaning":"The silence was fathomless and overwhelming.","meaningThai":"ความเงียบงันนั้นไร้ขอบเขตและท่วมท้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-096","chinese":"曾","pinyin":"céng","meaning":"surname Zeng","meaningThai":"เคย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我曾嘗試忘記。","pinyin":"Wǒ zēng cháng shì wàng jì。","meaning":"I tried forgetting.","meaningThai":"ฉันพยายามจะลืม"},{"chinese":"你曾經結過婚嗎？","pinyin":"Nǐ zēng jīng jié guò hūn má？","meaning":"Did you ever get married?","meaningThai":"คุณเคยแต่งงานไหม?"}],"partOfSpeech":["adverb","noun"]},
  {"id":"hsk5-097","chinese":"曾经","pinyin":"céngjīng","meaning":"once; already; former; previously; ever; (past tense marker used before verb or clause)","meaningThai":"ครั้งหนึ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有人曾经认为铅可以变成黄金。","pinyin":"Yǒu rén zēng jīng rèn wéi qiān kě yǐ biàn chéng huáng jīn。","meaning":"It was once thought that lead could be transmuted into gold.","meaningThai":"ครั้งหนึ่งเคยคิดว่าตะกั่วสามารถเปลี่ยนเป็นทองคำได้"},{"chinese":"人们曾经认为地球是平的。","pinyin":"Rén mén zēng jīng rèn wéi dì qiú shì píng de。","meaning":"People used to think the earth was flat.","meaningThai":"คนเคยคิดว่าโลกแบน"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-098","chinese":"测试","pinyin":"cèshì","meaning":"to test (machinery etc); to test (a person's skill in a particular area); a test; (computing) beta (version of software)","meaningThai":"การทดสอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"发布前要做充分的测试。","pinyin":"Fā bù qián yào zuò chōng fèn de cè shì.","meaning":"Do thorough testing before release.","meaningThai":"ทำการทดสอบอย่างละเอียดก่อนปล่อย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-099","chinese":"插","pinyin":"chā","meaning":"to insert; stick in; pierce; to take part in; to interfere; to interpose","meaningThai":"แทรก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们在他嘴里插了根导管帮助他呼吸。","pinyin":"Tā mén zài tā zuǐ lǐ chā le gēn dǎo guǎn bāng zhù tā hū xī。","meaning":"They inserted a tube in his mouth to help him breathe.","meaningThai":"พวกเขาสอดท่อเข้าไปในปากของเขาเพื่อช่วยให้เขาหายใจ"},{"chinese":"我能用这个插座插一下熨斗吗？","pinyin":"Wǒ néng yòng zhè gè chā zuò chā yī xià yùn dǒu ma？","meaning":"Can I use this plug for my iron?","meaningThai":"ฉันสามารถใช้ปลั๊กนี้กับเตารีดของฉันได้หรือไม่?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-100","chinese":"差别","pinyin":"chābié","meaning":"difference; distinction; disparity","meaningThai":"ความแตกต่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这两个有很大的差别。","pinyin":"Zhe liang ge you hen da de cha bie.","meaning":"These two are very different.","meaningThai":"สองคนนี้แตกต่างกันมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-101","chinese":"拆","pinyin":"chāi","meaning":"to tear open; to tear down; to tear apart; to open","meaningThai":"รื้อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这所房子保住了，可以不拆。","pinyin":"Zhè suǒ fáng zǐ bǎo zhù le， kě yǐ bù chāi。","meaning":"The house was rescued from demolition.","meaningThai":"บ้านได้รับการช่วยเหลือจากการรื้อถอน"},{"chinese":"老戏院被拆了，对不？","pinyin":"Lǎo xì yuàn bèi chāi le， duì bù？","meaning":"The old theatre was pulled down, wasn't it?","meaningThai":"โรงหนังเก่าถูกรื้อทิ้งแล้วใช่หรือไม่?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-102","chinese":"差距","pinyin":"chājù","meaning":"disparity; gap","meaningThai":"ช่องว่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"差距在缩小。","pinyin":"Cha ju zai suo xiao.","meaning":"The gap is narrowing.","meaningThai":"ช่องว่างกำลังแคบลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-103","chinese":"产","pinyin":"chǎn","meaning":"to give birth; to reproduce; to produce; product; resource; estate; property","meaningThai":"ผลิต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"以优产为目的的精选养殖是有潜力的。","pinyin":"Yǐ yōu chǎn wéi mù de de jīng xuǎn yǎng zhí shì yǒu qián lì de。","meaning":"There is potential for selective breeding for better yields.","meaningThai":"มีศักยภาพในการคัดเลือกพันธุ์เพื่อให้ได้ผลผลิตที่ดีขึ้น"},{"chinese":"智利是世界上最大的产铜国。","pinyin":"Zhì lì shì shì jiè shàng zuì dà de chǎn tóng guó。","meaning":"Chile is the world's largest producer of copper.","meaningThai":"ชิลีเป็นผู้ผลิตทองแดงรายใหญ่ที่สุดในโลก"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-104","chinese":"长处","pinyin":"chángchù","meaning":"good aspects; strong points","meaningThai":"จุดแข็ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"老练从来不是穆尔先生的长处。","pinyin":"Lǎo liàn cóng lái bù shì mù ěr xiān shēng de cháng chǔ。","meaning":"Tact was never Mr. Moore's strength.","meaningThai":"ชั้นเชิงไม่เคยเป็นจุดแข็งของคุณมัวร์"},{"chinese":"能够保持冷静是她的多项长处之一。","pinyin":"Néng gòu bǎo chí lěng jìng shì tā de duō xiàng cháng chǔ zhī yī。","meaning":"The ability to keep calm is one of her many strengths.","meaningThai":"ความสามารถในการรักษาความสงบเป็นหนึ่งในจุดแข็งของเธอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-105","chinese":"长度","pinyin":"chángdù","meaning":"length","meaningThai":"ความยาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"测量长度。","pinyin":"Ce liang chang du.","meaning":"Measure the length.","meaningThai":"วัดความยาว."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-106","chinese":"长久","pinyin":"chángjiǔ","meaning":"(for a) long time","meaningThai":"ยาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是场长久的战争。","pinyin":"Zhè shì cháng cháng jiǔ de zhàn zhēng。","meaning":"It's been a long war.","meaningThai":"มันเป็นสงครามที่ยาวนาน"},{"chinese":"淡淡地爱我，长久地爱我。","pinyin":"Dàn dàn dì ài wǒ， cháng jiǔ dì ài wǒ。","meaning":"Love me little, love me long.","meaningThai":"รักฉันให้น้อยรักฉันให้นาน"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-107","chinese":"长期","pinyin":"chángqī","meaning":"long term; long time; long range (of a forecast)","meaningThai":"ยาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们的长期努力以失败告终。","pinyin":"Tā mén de cháng qī nǔ lì yǐ shī bài gào zhōng。","meaning":"Their long struggle ended in failure.","meaningThai":"การต่อสู้อันยาวนานของพวกเขาจบลงด้วยความล้มเหลว"},{"chinese":"我感谢他们长期忠诚的效力。","pinyin":"Wǒ gǎn xiè tā mén cháng qī zhōng chéng de xiào lì。","meaning":"I thanked them for their long and loyal service.","meaningThai":"ฉันขอบคุณพวกเขาสำหรับการบริการที่ยาวนานและภักดีของพวกเขา"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-108","chinese":"常识","pinyin":"chángshí","meaning":"common sense; general knowledge","meaningThai":"สามัญสำนึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"游泳是最好的运动之一是普遍常识。","pinyin":"Yóu yǒng shì zuì hǎo de yùn dòng zhī yī shì pǔ biàn cháng shí。","meaning":"It is common knowledge that swimming is one of the best forms of exercise.","meaningThai":"เป็นที่ทราบกันดีว่าการว่ายน้ำเป็นการออกกำลังกายรูปแบบหนึ่งที่ดีที่สุด"},{"chinese":"我们希望常识能占上风。","pinyin":"Wǒ mén xī wàng cháng shí néng zhān shàng fēng。","meaning":"We hoped that common sense would prevail.","meaningThai":"เราหวังว่าสามัญสำนึกจะมีชัย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-109","chinese":"尝试","pinyin":"chángshì","meaning":"to try; to attempt","meaningThai":"พยายาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"作出一种寓教于乐的尝试。","pinyin":"Zuò chū yī zhǒng yù jiào yú lè de cháng shì。","meaning":"An attempt was made to intertwine the amusing with the educational.","meaningThai":"มีความพยายามที่จะผสมผสานความสนุกสนานเข้ากับการศึกษา"},{"chinese":"我被迫尝试一次骑马疾驰。","pinyin":"Wǒ bèi pò cháng shì yī cì qí mǎ jí chí。","meaning":"I was forced to attempt a gallop.","meaningThai":"ฉันถูกบังคับให้พยายามควบม้า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-110","chinese":"场所","pinyin":"chǎngsuǒ","meaning":"location; place","meaningThai":"สถานที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"工作场所的年龄歧视问题常被忽视。","pinyin":"Gōng zuò cháng suǒ de nián líng qí shì wèn tí cháng bèi hū shì。","meaning":"The problem of ageism in the workplace often goes unrecognized.","meaningThai":"ปัญหาเรื่องวัยนิยมในที่ทำงานมักไม่มีใครรับรู้"},{"chinese":"大多数工作场所现在都已禁止吸烟。","pinyin":"Dà duō shù gōng zuò cháng suǒ xiàn zài dū yǐ jīn zhǐ xī yān。","meaning":"Non-smoking is now the norm in most workplaces.","meaningThai":"ปัจจุบันการไม่สูบบุหรี่ถือเป็นเรื่องปกติในที่ทำงานส่วนใหญ่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-111","chinese":"长途","pinyin":"chángtú","meaning":"long distance","meaningThai":"ลากยาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"长途步行之后，我们大家急需喝水。","pinyin":"Cháng tú bù háng zhī hòu， wǒ mén dà jiā jí xū hē shuǐ。","meaning":"After the long walk, we were all ready for a drink.","meaningThai":"หลังจากเดินมาไกลเราก็พร้อมที่จะดื่มกัน"},{"chinese":"我们不情愿的开始长途跋涉回家。","pinyin":"Wǒ mén bù qíng yuàn de kāi shǐ cháng tú bá shè huí jiā。","meaning":"We were reluctant to start the long trudge home.","meaningThai":"เราลังเลที่จะเริ่มต้นการเดินทางไกลกลับบ้าน"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-112","chinese":"长远","pinyin":"chángyuǎn","meaning":"long-term; long-range","meaningThai":"ยาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"航天计划的长远前景尚未明朗。","pinyin":"Háng tiān jì huá de cháng yuǎn qián jǐng shàng wèi míng lǎng。","meaning":"The long-term future of the space programme hangs in the balance.","meaningThai":"อนาคตระยะยาวของโครงการอวกาศแขวนอยู่บนความสมดุล"},{"chinese":"长远目标一定是销毁所有的核武器。","pinyin":"Cháng yuǎn mù biāo yī dìng shì xiāo huǐ suǒ yǒu de hé wǔ qì。","meaning":"The long-range goal must be to do away with nuclear weapons altogether.","meaningThai":"เป้าหมายระยะยาวจะต้องกำจัดอาวุธนิวเคลียร์โดยสิ้นเชิง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-113","chinese":"产量","pinyin":"chǎnliàng","meaning":"output","meaningThai":"ผลผลิต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"日本的工业产量增长了2%。","pinyin":"Rì běn de gōng yè chǎn liáng zēng cháng le2%。","meaning":"Japan's industrial output increased by 2%.","meaningThai":"ผลผลิตภาคอุตสาหกรรมของญี่ปุ่นเพิ่มขึ้น 2%"},{"chinese":"重要的是别让产量滑落。","pinyin":"Zhòng yào de shì bié ràng chǎn liáng huá luò。","meaning":"It is important not to let production levels fall.","meaningThai":"สิ่งสำคัญคือต้องไม่ปล่อยให้ระดับการผลิตลดลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-114","chinese":"产品","pinyin":"chǎnpǐn","meaning":"goods; merchandise; product","meaningThai":"ผลิตภัณฑ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"谁在英国经销我们的产品？","pinyin":"Shuí zài yīng guó jīng xiāo wǒ mén de chǎn pǐn？","meaning":"Who distributes our products in the UK?","meaningThai":"ใครเป็นผู้จัดจำหน่ายผลิตภัณฑ์ของเราในสหราชอาณาจักร?"},{"chinese":"这些产品不会使头发脱色。","pinyin":"Zhè xiē chǎn pǐn bù huì shǐ tóu fā tuō sè。","meaning":"These products don't bleach the hair.","meaningThai":"ผลิตภัณฑ์เหล่านี้ไม่ฟอกสีผม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-115","chinese":"产业","pinyin":"chǎnyè","meaning":"industry; estate; property; industrial","meaningThai":"อุตสาหกรรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"卡车产业是衡量经济发展的基准。","pinyin":"Kǎ chē chǎn yè shì héng liáng jīng jì fā zhǎn de jī zhǔn。","meaning":"The truck industry is a benchmark for the economy.","meaningThai":"อุตสาหกรรมรถบรรทุกเป็นเกณฑ์มาตรฐานสำหรับเศรษฐกิจ"},{"chinese":"提高利率已使住房产业不堪负荷。","pinyin":"Tí gāo lì shuài yǐ shǐ zhù fáng chǎn yè bù kān fù hé。","meaning":"Higher interest rates are already pinching the housing industry.","meaningThai":"อัตราดอกเบี้ยที่สูงขึ้นกำลังส่งผลกระทบต่ออุตสาหกรรมที่อยู่อาศัยอยู่แล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-116","chinese":"朝","pinyin":"cháo","meaning":"abbr. for 朝鲜 Korea","meaningThai":"ต่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我在學朝鮮語。","pinyin":"Wǒ zài xué zhāo xiān yǔ。","meaning":"I'm learning Korean. / I am learning Korean.","meaningThai":"ฉันกำลังเรียนภาษาเกาหลี / ฉันกำลังเรียนภาษาเกาหลี."},{"chinese":"把这里翻个底朝天！","pinyin":"Bǎ zhè lǐ fān gè dǐ zhāo tiān！","meaning":"Leave no stone unturned.","meaningThai":"อย่าทิ้งหินไว้"}],"partOfSpeech":["preposition","noun","adjective","verb","measure word"]},
  {"id":"hsk5-117","chinese":"吵","pinyin":"chǎo","meaning":"to quarrel; to make a noise; noisy; to disturb by making a noise","meaningThai":"ทะเลาะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个地方夜间有时会非常吵。","pinyin":"Zhè gè dì fāng yè jiān yǒu shí huì fēi cháng chǎo。","meaning":"This area can be very noisy at night-time.","meaningThai":"บริเวณนี้อาจมีเสียงดังมากในเวลากลางคืน"},{"chinese":"我们隔壁的邻居非常吵。","pinyin":"Wǒ mén gé bì de lín jū fēi cháng chǎo。","meaning":"Our next-door neighbours are very noisy.","meaningThai":"เพื่อนบ้านข้างบ้านเราเสียงดังมาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-118","chinese":"炒","pinyin":"chǎo","meaning":"to sauté; to stir-fry; to speculate; to hype; to fire (sb)","meaningThai":"ผัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他炒的菜很好吃。","pinyin":"Ta chao de cai hen hao chi.","meaning":"His stir-fried dishes are delicious.","meaningThai":"เมนูผัดของเขาอร่อยมาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-119","chinese":"超","pinyin":"chāo","meaning":"to exceed; to overtake; to surpass; to transcend; to pass; to cross; ultra-; super-","meaningThai":"แซง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们度过了一段超好的时光。","pinyin":"Wǒ mén dù guò le yī duàn chāo hǎo de shí guāng。","meaning":"We had a super time.","meaningThai":"เรามีช่วงเวลาที่ยอดเยี่ยม"},{"chinese":"这种超黏度胶应该管用。","pinyin":"Zhè zhǒng chāo nián dù jiāo yīng gāi guǎn yòng。","meaning":"This extra strong glue should do the job.","meaningThai":"กาวที่แข็งแรงเป็นพิเศษนี้น่าจะได้ผล"}],"partOfSpeech":["verb","prefix"]},
  {"id":"hsk5-120","chinese":"超出","pinyin":"chāochū","meaning":"to exceed; to overstep; to go too far; to encroach","meaningThai":"เกิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那超出了我的理解。","pinyin":"Nà chāo chū le wǒ de lǐ jiě。","meaning":"That was beyond my comprehension.","meaningThai":"นั่นเกินกว่าความเข้าใจของฉัน"},{"chinese":"這超出了我的想像範圍。","pinyin":"Zhè chāo chū le wǒ de xiǎng xiàng fàn wéi。","meaning":"This is beyond the scope of my imagination.","meaningThai":"นี่อยู่นอกเหนือขอบเขตจินตนาการของฉัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-121","chinese":"超级","pinyin":"chāojí","meaning":"super-; ultra-; hyper-","meaningThai":"สุด ๆ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她从无名小辈一跃成为超级明星。","pinyin":"Tā cóng wú míng xiǎo bèi yī yuè chéng wéi chāo jí míng xīng。","meaning":"She rose from being a nobody to become a superstar.","meaningThai":"เธอเติบโตจากการไม่มีใครเลยกลายเป็นซุปเปอร์สตาร์"},{"chinese":"她在超级体育明星中独占鳌头。","pinyin":"Tā zài chāo jí tǐ yù míng xīng zhōng dú zhān áo tóu。","meaning":"Among sports superstars she's (the) tops.","meaningThai":"ในบรรดาซูเปอร์สตาร์ด้านกีฬา เธอคือ (เดอะ) ชั้นนำ"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-122","chinese":"超速","pinyin":"chāosù","meaning":"to exceed the speed limit; to speed; high-speed","meaningThai":"เร่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"超速驾驶可能会被处以高额罚款。","pinyin":"Chāo sù jià shǐ kě néng huì bèi chǔ yǐ gāo é fá kuǎn。","meaning":"The penalty for speeding can be a heavy fine.","meaningThai":"โทษของการขับรถเร็วอาจมีโทษปรับหนัก"},{"chinese":"他因超速驾驶到当地法庭受审。","pinyin":"Tā yīn chāo sù jià shǐ dào dāng dì fǎ tíng shòu shěn。","meaning":"He came up before the local magistrate for speeding.","meaningThai":"เขามาต่อหน้าผู้พิพากษาท้องถิ่นเพื่อเร่งรถ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-123","chinese":"叉子","pinyin":"chāzi","meaning":"fork","meaningThai":"ส้อม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她用叉子把气球砰的一声戳爆了。","pinyin":"Tā yòng chā zǐ bǎ qì qiú pēng de yī shēng chuō bào le。","meaning":"She popped a balloon with her fork.","meaningThai":"เธอใช้ส้อมทุบลูกโป่ง"},{"chinese":"她用叉子在空中比画。","pinyin":"Tā yòng chā zǐ zài kōng zhōng bǐ huà。","meaning":"She stabbed the air with her fork.","meaningThai":"เธอใช้ส้อมแทงอากาศ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-124","chinese":"彻底","pinyin":"chèdǐ","meaning":"thorough; thoroughly; complete","meaningThai":"อย่างละเอียด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"整个事情彻底失败了。","pinyin":"Zhěng gè shì qíng chè dǐ shī bài le。","meaning":"The whole thing was a complete failure.","meaningThai":"สิ่งทั้งหมดเป็นความล้มเหลวโดยสิ้นเชิง"},{"chinese":"确保将其彻底除霜。","pinyin":"Què bǎo jiāng qí chè dǐ chú shuāng。","meaning":"Make sure that you defrost it completely.","meaningThai":"ตรวจสอบให้แน่ใจว่าคุณละลายน้ำแข็งเรียบร้อยแล้ว"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-125","chinese":"车祸","pinyin":"chēhuò","meaning":"traffic accident; car crash","meaningThai":"อุบัติเหตุทางรถยนต์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他从车祸以后就离不开轮椅了。","pinyin":"Tā cóng chē huò yǐ hòu jiù lí bù kāi lún yǐ le。","meaning":"He's been confined to a wheelchair since the accident.","meaningThai":"เขาถูกคุมขังอยู่บนรถเข็นตั้งแต่เกิดอุบัติเหตุ"},{"chinese":"她被卷入一场车祸，扭伤了脖子。","pinyin":"Tā bèi juàn rù yī cháng chē huò， niǔ shāng le bó zǐ。","meaning":"She was involved in a car accident and she ricked her neck.","meaningThai":"เธอประสบอุบัติเหตุทางรถยนต์และเธอหักคอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-126","chinese":"车库","pinyin":"chēkù","meaning":"garage","meaningThai":"โรงรถ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她小心翼翼地将车开进了车库。","pinyin":"Tā xiǎo xīn yì yì dì jiāng chē kāi jìn le chē kù。","meaning":"She manoeuvred the car carefully into the garage.","meaningThai":"เธอเคลื่อนรถเข้าไปในโรงรถอย่างระมัดระวัง"},{"chinese":"那名男子最终被警方逼到了车库里。","pinyin":"Nà míng nán zǐ zuì zhōng bèi jǐng fāng bī dào le chē kù lǐ。","meaning":"The man was finally cornered by police in a garage.","meaningThai":"ในที่สุดชายคนนั้นก็ถูกตำรวจจนมุมในโรงรถ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-127","chinese":"车辆","pinyin":"chēliàng","meaning":"vehicle","meaningThai":"ยานพาหนะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"所有租赁车辆仅供个人使用。","pinyin":"Suǒ yǒu zū lìn chē liàng jǐn gōng gè rén shǐ yòng。","meaning":"All hire cars are for personal use only.","meaningThai":"รถเช่าทั้งหมดมีไว้สำหรับการใช้งานส่วนตัวเท่านั้น"},{"chinese":"非法停放的车辆将被拖走。","pinyin":"Fēi fǎ tíng fàng de chē liàng jiāng bèi tuō zǒu。","meaning":"Illegally parked vehicles will be removed.","meaningThai":"ยานพาหนะที่จอดอย่างผิดกฎหมายจะถูกลบออก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-128","chinese":"沉","pinyin":"chén","meaning":"to submerge; to immerse; to sink; to keep down; to lower; to drop; deep; profound; heavy","meaningThai":"จม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"别让船超载了，否则它会沉。","pinyin":"Bié ràng chuán chāo zǎi le， fǒu zé tā huì chén。","meaning":"Don't overload the boat or it will sink.","meaningThai":"อย่าบรรทุกเกินขนาดเรือ ไม่เช่นนั้นเรือจะจม"},{"chinese":"我们若不排水，船就要沉。","pinyin":"Wǒ mén ruò bù pái shuǐ， chuán jiù yào chén。","meaning":"The boat will sink unless we bail out.","meaningThai":"เรือจะจมเว้นแต่เราจะประกันตัวออกมา"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-129","chinese":"称","pinyin":"chēng","meaning":"to fit; balanced; suitable","meaningThai":"พูด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"警方称这次袭击只是个别事件。","pinyin":"Jǐng fāng chēng zhè cì xí jī zhī shì gè bié shì jiàn。","meaning":"The police said the attack was an isolated incident.","meaningThai":"ตำรวจกล่าวว่าการโจมตีเป็นเหตุการณ์ที่เกิดขึ้นเดี่ยวๆ"},{"chinese":"当局称该监狱现在在正常运转。","pinyin":"Dāng jú chēng gāi jiān yù xiàn zài zài zhèng cháng yùn zhuǎn。","meaning":"The authorities say the prison is now functioning normally.","meaningThai":"เจ้าหน้าที่กล่าวว่าขณะนี้เรือนจำทำงานได้ตามปกติแล้ว"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-131","chinese":"成本","pinyin":"chéngběn","meaning":"(manufacturing, production etc) costs","meaningThai":"ค่าใช้จ่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"再说，我们必须考虑成本。","pinyin":"Zài shuō， wǒ mén bì xū kǎo lǜ chéng běn。","meaning":"And again, we must think of the cost.","meaningThai":"และอีกครั้งเราต้องคิดถึงต้นทุน"},{"chinese":"通胀数字未包括借贷成本。","pinyin":"Tōng zhàng shù zì wèi bāo kuò jiè dài chéng běn。","meaning":"The cost of borrowing has been excluded from the inflation figures.","meaningThai":"ต้นทุนการกู้ยืมไม่รวมอยู่ในตัวเลขเงินเฟ้อ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-132","chinese":"承担","pinyin":"chéngdān","meaning":"to undertake; to assume (responsibility etc)","meaningThai":"หมี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她拒绝承担传统妇女的角色。","pinyin":"Tā jù jué chéng dān chuán tǒng fù nǚ de jiǎo sè。","meaning":"She refused to take on the traditional woman's role.","meaningThai":"เธอปฏิเสธที่จะรับบทบาทของผู้หญิงตามประเพณี"},{"chinese":"我不能承担任何额外工作。","pinyin":"Wǒ bù néng chéng dān rèn hé é wài gōng zuò。","meaning":"I can't take on any extra work.","meaningThai":"ฉันไม่สามารถทำงานพิเศษใดๆ ได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-133","chinese":"程度","pinyin":"chéngdù","meaning":"degree; level; extent","meaningThai":"ระดับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"大气中的污染程度正在加深。","pinyin":"Dà qì zhōng de wū rǎn chéng dù zhèng zài jiā shēn。","meaning":"Levels of pollution present in the atmosphere are increasing.","meaningThai":"ระดับมลพิษในชั้นบรรยากาศเพิ่มขึ้น"},{"chinese":"在某种程度上这是事实。","pinyin":"Zài mǒu zhǒng chéng dù shàng zhè shì shì shí。","meaning":"To some extent this was the truth.","meaningThai":"นี่คือความจริงในระดับหนึ่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-134","chinese":"成分","pinyin":"chéngfèn","meaning":"composition; ingredient; element; component; one's social status","meaningThai":"ส่วนประกอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"食品成分。","pinyin":"Shi pin cheng fen.","meaning":"Food ingredients.","meaningThai":"ส่วนผสมอาหาร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-135","chinese":"成果","pinyin":"chéngguǒ","meaning":"result; achievement; gain; profit","meaningThai":"ความสำเร็จ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是一次带来极其有益的成果的合作。","pinyin":"Zhè shì yī cì dài lái jí qí yǒu yì de chéng guǒ de hé zuò。","meaning":"It was a collaboration that produced extremely useful results.","meaningThai":"เป็นความร่วมมือที่สร้างผลลัพธ์ที่เป็นประโยชน์อย่างยิ่ง"},{"chinese":"他被指控剽窃同事的成果。","pinyin":"Tā bèi zhǐ kòng piāo qiè tóng shì de chéng guǒ。","meaning":"He was accused of plagiarizing his colleague's results.","meaningThai":"เขาถูกกล่าวหาว่าลอกผลงานผลงานของเพื่อนร่วมงาน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-136","chinese":"成就","pinyin":"chéngjiù","meaning":"accomplishment; success; achievement; to achieve (a result); to create; to bring about","meaningThai":"ความสำเร็จ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她对于自己的成就如此缄默。","pinyin":"Tā duì yú zì jǐ de chéng jiù rú cǐ jiān mò。","meaning":"She is so reticent about her achievements.","meaningThai":"เธอค่อนข้างนิ่งเฉยกับความสำเร็จของเธอ"},{"chinese":"那是总统最伟大的成就之一。","pinyin":"Nà shì zǒng tǒng zuì wěi dà de chéng jiù zhī yī。","meaning":"It was one of the President's greatest accomplishments.","meaningThai":"นี่เป็นหนึ่งในความสำเร็จที่ยิ่งใหญ่ที่สุดของประธานาธิบดี"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-137","chinese":"成立","pinyin":"chénglì","meaning":"to establish; to set up; to be tenable; to hold water","meaningThai":"ที่จัดตั้งขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"发言人宣布了新学院的成立。","pinyin":"Fā yán rén xuān bù le xīn xué yuàn de chéng lì。","meaning":"The speaker announced the establishment of a new college.","meaningThai":"วิทยากรประกาศจัดตั้งวิทยาลัยแห่งใหม่"},{"chinese":"委员会在首都里加举行了成立大会。","pinyin":"Wěi yuán huì zài shǒu dū lǐ jiā jǔ háng le chéng lì dà huì。","meaning":"The committee held its founding congress in the capital, Riga.","meaningThai":"คณะกรรมการได้จัดการประชุมสมัชชาก่อตั้งในเมืองหลวงริกา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-138","chinese":"成年","pinyin":"chéngnián","meaning":"to grow to adulthood; fully grown; adult; the whole year","meaningThai":"ผู้ใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"成年人还得这样诉诸暴力，真可悲。","pinyin":"Chéng nián rén huán dé zhè yàng sù zhū bào lì， zhēn kě bēi。","meaning":"It's pathetic that grown men have to resort to violence like this.","meaningThai":"น่าสงสารผู้ชายที่โตแล้วต้องใช้ความรุนแรงแบบนี้"},{"chinese":"她对成年学生的问题很同情。","pinyin":"Tā duì chéng nián xué shēng de wèn tí hěn tóng qíng。","meaning":"She was very sympathetic to the problems of adult students.","meaningThai":"เธอเห็นอกเห็นใจต่อปัญหาของนักเรียนผู้ใหญ่เป็นอย่างมาก"}],"partOfSpeech":["verb","noun","adjective"]},
  {"id":"hsk5-139","chinese":"城区","pinyin":"chéngqū","meaning":"city district; urban area","meaningThai":"เขตเมือง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"某些城区已划出要进行特别治理。","pinyin":"Mǒu xiē chéng qū yǐ huá chū yào jìn háng tè bié zhì lǐ。","meaning":"Certain city areas have been singled out for special treatment.","meaningThai":"พื้นที่เมืองบางแห่งได้รับการดูแลเป็นพิเศษ"},{"chinese":"大多数城区都靠近公园。","pinyin":"Dà duō shù chéng qū dū kào jìn gōng yuán。","meaning":"Most urban areas are close to a park.","meaningThai":"พื้นที่เมืองส่วนใหญ่อยู่ใกล้กับสวนสาธารณะ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-140","chinese":"成人","pinyin":"chéngrén","meaning":"adult","meaningThai":"ผู้ใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"每张票只准许一位成人入场。","pinyin":"Měi zhāng piào zhī zhǔn xǔ yī wèi chéng rén rù cháng。","meaning":"Each ticket admits one adult.","meaningThai":"ตั๋วแต่ละใบยอมรับผู้ใหญ่หนึ่งคน"},{"chinese":"成人往往对风疹有免疫力。","pinyin":"Chéng rén wǎng wǎng duì fēng zhěn yǒu miǎn yì lì。","meaning":"Adults are often immune to German measles.","meaningThai":"ผู้ใหญ่มักมีภูมิคุ้มกันต่อโรคหัดเยอรมัน"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-141","chinese":"承认","pinyin":"chéngrèn","meaning":"to admit; to concede; to recognize; recognition (diplomatic, artistic etc); to acknowledge","meaningThai":"ยอมรับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她不愿承认自己有错。","pinyin":"Tā bù yuàn chéng rèn zì jǐ yǒu cuò。","meaning":"She was reluctant to admit she was wrong.","meaningThai":"เธอลังเลที่จะยอมรับว่าเธอผิด"},{"chinese":"他承认扰乱了治安。","pinyin":"Tā chéng rèn rǎo luàn le zhì ān。","meaning":"He admitted causing a breach of the peace.","meaningThai":"เขายอมรับว่าก่อให้เกิดการละเมิดสันติภาพ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-142","chinese":"承受","pinyin":"chéngshòu","meaning":"to bear; to support; to inherit","meaningThai":"หมี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"墙壁因承受不了重压而坍塌了。","pinyin":"Qiáng bì yīn chéng shòu bù le zhòng yā ér tān tā le。","meaning":"The wall collapsed under the strain.","meaningThai":"ผนังพังทลายลงเพราะแรงตึง"},{"chinese":"他承受着要辞职的巨大压力。","pinyin":"Tā chéng shòu zháo yào cí zhí de jù dà yā lì。","meaning":"He was under strong pressure to resign.","meaningThai":"เขาถูกกดดันอย่างหนักให้ลาออก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-143","chinese":"成熟","pinyin":"chéngshú","meaning":"mature; ripe; to mature; to ripen; Taiwan pr. [chéng shóu]","meaningThai":"เป็นผู้ใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"社会变革的时机已经成熟。","pinyin":"Shè huì biàn gé de shí jī yǐ jīng chéng shú。","meaning":"The conditions were ripe for social change.","meaningThai":"เงื่อนไขสุกงอมสำหรับการเปลี่ยนแปลงทางสังคม"},{"chinese":"简年龄不大，却很成熟。","pinyin":"Jiǎn nián líng bù dà， què hěn chéng shú。","meaning":"Jane is very mature for her age.","meaningThai":"เจนเป็นผู้ใหญ่มากตามอายุของเธอ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-144","chinese":"称为","pinyin":"chēngwéi","meaning":"to be called; to be known as; to call it \"...\"","meaningThai":"เรียกว่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些蝙蝠有时被误称为“飞狐”。","pinyin":"Zhè xiē biān fú yǒu shí bèi wù chēng wéi “ fēi hú”。","meaning":"These bats are sometimes misleadingly referred to as 'flying foxes'.","meaningThai":"ค้างคาวเหล่านี้บางครั้งถูกเรียกอย่างเข้าใจผิดว่า 'สุนัขจิ้งจอกบิน'"},{"chinese":"这种设计后来被称为东方风格。","pinyin":"Zhè zhǒng shè jì hòu lái bèi chēng wéi dōng fāng fēng gé。","meaning":"This design came to be known as the Oriental style.","meaningThai":"การออกแบบนี้เป็นที่รู้จักในชื่อสไตล์ตะวันออก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-145","chinese":"乘务员","pinyin":"chéngwùyuán","meaning":"attendant on an airplane, train, boat etc","meaningThai":"พนักงานต้อนรับบนเครื่องบิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们还声称治安队把一名乘务员推到了一边。","pinyin":"Tā mén huán shēng chēng zhì ān duì bǎ yī míng chéng wù yuán tuī dào le yī biān。","meaning":"They also claim that the security team elbowed aside a steward.","meaningThai":"พวกเขายังอ้างว่าทีมรักษาความปลอดภัยข้อศอกสจ๊วตออกไป"},{"chinese":"乘务员都戴了臂章。","pinyin":"Chéng wù yuán dū dài le bì zhāng。","meaning":"The stewards all wore armbands.","meaningThai":"ผู้ดูแลทุกคนสวมปลอกแขน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-146","chinese":"程序","pinyin":"chéngxù","meaning":"procedures; sequence; order; computer program","meaningThai":"โปรแกรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是个未经多少试验的新程序。","pinyin":"Zhè shì gè wèi jīng duō shǎo shì yàn de xīn chéng xù。","meaning":"This is a new and relatively untried procedure.","meaningThai":"นี่เป็นขั้นตอนใหม่และยังไม่ได้ทดลอง"},{"chinese":"你需要时间熟悉我们的程序。","pinyin":"Nǐ xū yào shí jiān shú xī wǒ mén de chéng xù。","meaning":"You'll need time to familiarize yourself with our procedures.","meaningThai":"คุณจะต้องใช้เวลาในการทำความคุ้นเคยกับขั้นตอนของเรา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-147","chinese":"成员","pinyin":"chéngyuán","meaning":"member","meaningThai":"สมาชิก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"所有隶属成员都有投票权。","pinyin":"Suǒ yǒu lì shǔ chéng yuán dū yǒu tóu piào quán。","meaning":"All affiliated members can vote.","meaningThai":"สมาชิกในเครือทุกคนสามารถลงคะแนนได้"},{"chinese":"新成员将配发临时身份卡。","pinyin":"Xīn chéng yuán jiāng pèi fā lín shí shēn fèn kǎ。","meaning":"New members will be issued with a temporary identity card.","meaningThai":"สมาชิกใหม่จะได้รับบัตรประจำตัวชั่วคราว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-148","chinese":"称赞","pinyin":"chēngzàn","meaning":"to praise; to acclaim; to commend; to compliment","meaningThai":"ยกย่อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"法官的勇气和人道受到称赞。","pinyin":"Fǎ guān de yǒng qì hé rén dào shòu dào chēng zàn。","meaning":"The judge was praised for his courage and humanity.","meaningThai":"ผู้พิพากษาได้รับการยกย่องในความกล้าหาญและความเป็นมนุษย์ของเขา"},{"chinese":"他称赞首相时有溢美之词。","pinyin":"Tā chēng zàn shǒu xiāng shí yǒu yì měi zhī cí。","meaning":"He was fulsome in his praise of the Prime Minister.","meaningThai":"ทรงชื่นชมยินดีต่อนายกรัฐมนตรี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-149","chinese":"成长","pinyin":"chéngzhǎng","meaning":"to mature; to grow; growth","meaningThai":"เติบโตขึ้นมา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些孩子处于不同的成长阶段。","pinyin":"Zhè xiē hái zǐ chǔ yú bù tóng de chéng cháng jiē duàn。","meaning":"The children are at different stages of development.","meaningThai":"เด็กมีพัฒนาการในระยะต่างๆ"},{"chinese":"她不想让子女在众人瞩目中成长。","pinyin":"Tā bù xiǎng ràng zǐ nǚ zài zhòng rén zhǔ mù zhōng chéng cháng。","meaning":"She doesn't want her children growing up in the public eye.","meaningThai":"เธอไม่อยากให้ลูกๆ ของเธอเติบโตในสายตาของสาธารณชน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-150","chinese":"橙子","pinyin":"chéngzi","meaning":"orange","meaningThai":"ส้ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"橙子可以存放很久而不发霉。","pinyin":"Chéng zǐ kě yǐ cún fàng hěn jiǔ ér bù fā méi。","meaning":"Oranges can be kept for a long time without getting mouldy.","meaningThai":"ส้มสามารถเก็บไว้ได้นานโดยไม่เกิดเชื้อรา"},{"chinese":"自产橙子的巨大优势是其极好的味道。","pinyin":"Zì chǎn chéng zǐ de jù dà yōu shì shì qí jí hǎo de wèi dào。","meaning":"The great advantage of home-grown oranges is their magnificent flavour.","meaningThai":"ข้อได้เปรียบที่ยอดเยี่ยมของส้มที่ปลูกเองที่บ้านคือรสชาติอันยอดเยี่ยม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-151","chinese":"沉默","pinyin":"chénmò","meaning":"taciturn; uncommunicative; silent","meaningThai":"ความเงียบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些罪犯陷入了愤懑的沉默。","pinyin":"Zhè xiē zuì fàn xiàn rù le fèn mèn de chén mò。","meaning":"The offenders lapsed into a sullen silence.","meaningThai":"ผู้กระทำความผิดตกอยู่ในความเงียบบูดบึ้ง"},{"chinese":"他的沉默令我们心里发慌。","pinyin":"Tā de chén mò líng wǒ mén xīn lǐ fā huāng。","meaning":"His silence unnerved us.","meaningThai":"ความเงียบของเขาทำให้เราตกใจ"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-152","chinese":"车厢","pinyin":"chēxiāng","meaning":"carriage","meaningThai":"รถ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们让乘客车厢与火车头脱离开。","pinyin":"Tā mén ràng chéng kè chē xiāng yǔ huǒ chē tóu tuō lí kāi。","meaning":"They uncoupled the passenger cars from the train engine.","meaningThai":"พวกเขาแยกรถโดยสารออกจากเครื่องยนต์รถไฟ"},{"chinese":"他坐在一个二等车厢的角落里。","pinyin":"Tā zuò zài yī gè èr děng chē xiāng de jiǎo luò lǐ。","meaning":"He sat in the corner of a second-class compartment.","meaningThai":"เขานั่งอยู่ตรงมุมห้องชั้นสอง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-153","chinese":"车主","pinyin":"chēzhǔ","meaning":"vehicle owner","meaningThai":"เจ้าของรถ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"出于经济原因，车主需要处理掉这辆车。","pinyin":"Chū yú jīng jì yuán yīn， chē zhǔ xū yào chǔ lǐ diào zhè liàng chē。","meaning":"The owner needs to get rid of the car for financial reasons.","meaningThai":"เจ้าของจำเป็นต้องกำจัดรถด้วยเหตุผลทางการเงิน"},{"chinese":"这辆汽车以前没换过车主。","pinyin":"Zhè liàng qì chē yǐ qián méi huàn guò chē zhǔ。","meaning":"The car has only had one previous owner.","meaningThai":"รถมีเจ้าของเดิมเพียงคนเดียว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-154","chinese":"池","pinyin":"chí","meaning":"pool","meaningThai":"สระน้ำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她选了鸭池旁的一张长椅坐了下来。","pinyin":"Tā xuǎn le yā chí páng de yī zhāng cháng yǐ zuò le xià lái。","meaning":"She chose a bench beside the duck pond and sat down.","meaningThai":"เธอเลือกม้านั่งข้างสระเป็ดแล้วนั่งลง"},{"chinese":"这家医院率先使用了分娩池。","pinyin":"Zhè jiā yī yuàn shuài xiān shǐ yòng le fēn miǎn chí。","meaning":"The hospital has pioneered the use of birthing pools.","meaningThai":"โรงพยาบาลได้บุกเบิกการใช้สระคลอดบุตร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-155","chinese":"翅膀","pinyin":"chìbǎng","meaning":"wing","meaningThai":"ปีก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"猩红的翅膀到了翼端渐变成浅红。","pinyin":"Xīng hóng de chì bǎng dào le yì duān jiàn biàn chéng qiǎn hóng。","meaning":"The scarlet of the wings shades into pink at the tips.","meaningThai":"ปีกสีแดงเข้มเป็นสีชมพูที่ปลาย"},{"chinese":"这昆虫的翅膀几乎是透明的。","pinyin":"Zhè kūn chóng de chì bǎng jī hū shì tòu míng de。","meaning":"The insect's wings are almost transparent.","meaningThai":"ปีกของแมลงเกือบจะโปร่งใส"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-156","chinese":"持续","pinyin":"chíxù","meaning":"to continue; to persist; to last; sustainable; preservation","meaningThai":"อย่างต่อเนื่อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"会谈预料将持续到明天。","pinyin":"Huì tán yù liào jiāng chí xù dào míng tiān。","meaning":"The talks are expected to continue until tomorrow.","meaningThai":"การเจรจาคาดว่าจะดำเนินต่อไปจนถึงวันพรุ่งนี้"},{"chinese":"改革的呼声持续高涨。","pinyin":"Gǎi gé de hū shēng chí xù gāo zhǎng。","meaning":"The pressure for change continued to mount.","meaningThai":"ความกดดันในการเปลี่ยนแปลงยังคงเพิ่มขึ้นอย่างต่อเนื่อง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-157","chinese":"尺子","pinyin":"chǐzi","meaning":"ruler (measuring instrument)","meaningThai":"ไม้บรรทัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"尺子裂了，碎成了片。","pinyin":"Chǐ zǐ liè le， suì chéng le piàn。","meaning":"The ruler cracked and splintered into pieces.","meaningThai":"ไม้บรรทัดแตกและแตกเป็นชิ้น ๆ"},{"chinese":"帕特，这是我的尺子。","pinyin":"Pà tè， zhè shì wǒ de chǐ zǐ。","meaning":"Pat, this is my ruler.","meaningThai":"แพท นี่คือผู้ปกครองของฉัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-158","chinese":"冲","pinyin":"chōng","meaning":"(of water) to dash against; to mix with water; to infuse; to rinse; to flush; to develop (a film); to rise in the air; to clash; to collide with","meaningThai":"รีบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你冲厕所了吗？","pinyin":"Nǐ chōng cè suǒ le ma？","meaning":"Have you flushed the toilet?","meaningThai":"คุณล้างห้องน้ำแล้วหรือยัง?"},{"chinese":"她冲他笑笑，他也冲她笑笑。","pinyin":"Tā chōng tā xiào xiào， tā yě chōng tā xiào xiào。","meaning":"She smiled at him and he smiled back.","meaningThai":"เธอยิ้มให้เขาและเขาก็ยิ้มกลับ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-159","chinese":"充电","pinyin":"chōngdiàn","meaning":"to recharge (a battery); (fig.) to recharge one's batteries (through leisure); to update one's skills and knowledge","meaningThai":"ค่าใช้จ่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他把剃刀插在插座上，给它充电。","pinyin":"Tā bǎ tì dāo chā zài chā zuò shàng， gěi tā chōng diàn。","meaning":"He plugged his razor in to recharge it.","meaningThai":"เขาเสียบมีดโกนเพื่อชาร์จใหม่"},{"chinese":"这种电动剃须刀可充电供旅行使用。","pinyin":"Zhè zhǒng diàn dòng tì xū dāo kě chōng diàn gōng lǚ háng shǐ yòng。","meaning":"The shaver can be charged up and used when travelling.","meaningThai":"เครื่องโกนหนวดสามารถชาร์จและใช้งานได้เมื่อเดินทาง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-160","chinese":"充分","pinyin":"chōngfèn","meaning":"ample; sufficient; adequate; full; fully; to the full","meaningThai":"เต็ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们充分享用了旅馆设施。","pinyin":"Wǒ mén chōng fēn xiǎng yòng le lǚ guǎn shè shī。","meaning":"We took full advantage of the hotel facilities.","meaningThai":"เราใช้ประโยชน์จากสิ่งอำนวยความสะดวกครบครันของโรงแรม"},{"chinese":"我们充分意识到危险。","pinyin":"Wǒ mén chōng fēn yì shí dào wēi xiǎn。","meaning":"We are fully aware of the dangers.","meaningThai":"เราตระหนักดีถึงอันตราย"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-161","chinese":"重复","pinyin":"chóngfù","meaning":"to repeat; to duplicate","meaningThai":"ทำซ้ำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他重复了几遍直到能记住为止。","pinyin":"Tā zhòng fù le jī biàn zhí dào néng jì zhù wéi zhǐ。","meaning":"He repeated it several times over until he could remember it.","meaningThai":"เขาพูดซ้ำหลายครั้งจนเขาจำได้"},{"chinese":"这些作业重复冗长，没有什么意义。","pinyin":"Zhè xiē zuò yè zhòng fù rǒng cháng， méi yǒu shí mó yì yì。","meaning":"These tasks were repetitive, lengthy and lacking any intrinsic interest.","meaningThai":"งานเหล่านี้ซ้ำซาก ยาว และขาดความสนใจที่แท้จริง"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-162","chinese":"充满","pinyin":"chōngmǎn","meaning":"full of; brimming with; very full; permeated","meaningThai":"เต็ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她总是充满活力。","pinyin":"Tā zǒng shì chōng mǎn huó lì。","meaning":"She's always full of energy.","meaningThai":"เธอเต็มไปด้วยพลังอยู่เสมอ"},{"chinese":"我对欧洲并不充满幻想。","pinyin":"Wǒ duì ōu zhōu bìng bù chōng mǎn huàn xiǎng。","meaning":"I'm not starry-eyed about Europe.","meaningThai":"ฉันไม่ได้ตาดีเกี่ยวกับยุโรป"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-163","chinese":"宠物","pinyin":"chǒngwù","meaning":"house pet","meaningThai":"สัตว์เลี้ยง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"把海龟当宠物养显然是残忍的。","pinyin":"Bǎ hǎi guī dāng chǒng wù yǎng xiǎn rán shì cán rěn de。","meaning":"It is plainly cruel to keep turtles as pets.","meaningThai":"การให้เต่าเป็นสัตว์เลี้ยงเป็นเรื่องโหดร้ายอย่างเห็นได้ชัด"},{"chinese":"他们请人把他们的宠物狗制成了标本。","pinyin":"Tā mén qǐng rén bǎ tā mén de chǒng wù gǒu zhì chéng le biāo běn。","meaning":"They had had their pet dog stuffed.","meaningThai":"พวกเขายัดสุนัขเลี้ยงไว้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-164","chinese":"充值","pinyin":"chōngzhí","meaning":"top up","meaningThai":"เติมเงิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我手机没钱了，得去给手机充值。","pinyin":"Wǒ shǒu jī méi qián le， dé qù gěi shǒu jī chōng zhí。","meaning":"My mobile phone is out of credit，I have to top up it .","meaningThai":"โทรศัพท์มือถือของฉันหมดเครดิต ฉันต้องเติมเงิน"},{"chinese":"请问交通卡充值在哪里？","pinyin":"Qǐng wèn jiāo tōng kǎ chōng zhí zài nǎ lǐ？","meaning":"P: Where can I recharge my card, please?","meaningThai":"P: ฉันสามารถเติมเงินบัตรของฉันได้ที่ไหน?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-165","chinese":"虫子","pinyin":"chóngzi","meaning":"insect; bug; worm","meaningThai":"แมลง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个苹果生满了虫子。","pinyin":"Zhè gè píng guǒ shēng mǎn le chóng zǐ。","meaning":"This apple is full of worms.","meaningThai":"แอปเปิ้ลลูกนี้เต็มไปด้วยหนอน"},{"chinese":"房间很小还有虫子。","pinyin":"Fáng jiān hěn xiǎo huán yǒu chóng zǐ。","meaning":"Rooms are small and there are bugs.","meaningThai":"ห้องพักมีขนาดเล็กและมีแมลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-166","chinese":"充足","pinyin":"chōngzú","meaning":"adequate; sufficient; abundant","meaningThai":"อุดมสมบูรณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"供应充足。","pinyin":"Gong ying chong zu.","meaning":"Supply is adequate.","meaningThai":"อุปทานมีเพียงพอ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-167","chinese":"臭","pinyin":"chòu","meaning":"stench; smelly; to smell (bad); repulsive; loathsome; terrible; bad; severely; ruthlessly; dud (ammunition)","meaningThai":"มีกลิ่นเหม็น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有多少人会说它们都很臭?","pinyin":"Yǒu duō shǎo rén huì shuō tā mén dū hěn chòu?","meaning":"How many would say they all stink?","meaningThai":"จะมีสักกี่คนที่บอกว่าพวกเขาทั้งหมดมีกลิ่นเหม็น?"},{"chinese":"停止流动的河流会变臭。","pinyin":"Tíng zhǐ liú dòng de hé liú huì biàn chòu。","meaning":"A river that stops moving gets smelly.","meaningThai":"แม่น้ำที่หยุดเคลื่อนไหวจะมีกลิ่นเหม็น"}],"partOfSpeech":["adjective","other"]},
  {"id":"hsk5-168","chinese":"丑","pinyin":"chǒu","meaning":"surname Chou","meaningThai":"น่าเกลียด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那条流经米德尔斯伯勒的河变得丑不忍睹，臭不可闻。","pinyin":"Nà tiáo liú jīng mǐ dé ěr sī bó lè de hé biàn dé chǒu bù rěn dǔ， chòu bù kě wén。","meaning":"The river that runs through Middlesbrough became ugly on the eye and hard on the nose.","meaningThai":"แม่น้ำที่ไหลผ่านมิดเดิลสโบรห์กลายเป็นแม่น้ำที่น่าเกลียดและแข็งจนจมูก"},{"chinese":"米老鼠开始是又丑又小的噬齿动物。","pinyin":"Mǐ lǎo shǔ kāi shǐ shì yòu chǒu yòu xiǎo de shì chǐ dòng wù。","meaning":"Mickey Mouse starts as an ugly, little rodent.","meaningThai":"มิกกี้เมาส์เริ่มต้นจากการเป็นสัตว์ฟันแทะตัวน้อยที่น่าเกลียด"}],"partOfSpeech":["adjective","other"]},
  {"id":"hsk5-169","chinese":"抽","pinyin":"chōu","meaning":"to draw out; to pull out from in between; to remove part of the whole; (of certain plants) to sprout or bud; to whip or thrash","meaningThai":"ควัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你一天抽几支香烟？","pinyin":"Nǐ yī tiān chōu jī zhī xiāng yān？","meaning":"How many cigarettes do you smoke a day?","meaningThai":"คุณสูบบุหรี่วันละกี่มวน?"},{"chinese":"给我支烟抽可以吗？我的烟好像抽完了。","pinyin":"Gěi wǒ zhī yān chōu kě yǐ ma？ wǒ de yān hǎo xiàng chōu wán le。","meaning":"Could I have a cigarette? I seem to have run out.","meaningThai":"ฉันขอบุหรี่ได้ไหม? ดูเหมือนฉันจะหมดลงแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-170","chinese":"处","pinyin":"chù","meaning":"to reside; to live; to dwell; to be in; to be situated at; to stay; to get along with; to be in a position of; to deal with; to discipline; to punish","meaningThai":"ที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他胳膊上有三处骨折。","pinyin":"Tā gē bó shàng yǒu sān chǔ gǔ zhē。","meaning":"He broke his arm in three places.","meaningThai":"เขาหักแขนของเขาสามแห่ง"},{"chinese":"将有免费停泊处。","pinyin":"Jiāng yǒu miǎn fèi tíng bó chǔ。","meaning":"Free moorings will be available.","meaningThai":"จะมีท่าเทียบเรือฟรี"}],"partOfSpeech":["noun","measure word","verb"]},
  {"id":"hsk5-171","chinese":"处","pinyin":"chǔ","meaning":"to reside; to live; to dwell; to be in; to be situated at; to stay; to get along with; to be in a position of; to deal with; to discipline; to punish","meaningThai":"ที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他胳膊上有三处骨折。","pinyin":"Tā gē bó shàng yǒu sān chǔ gǔ zhē。","meaning":"He broke his arm in three places.","meaningThai":"เขาหักแขนของเขาสามแห่ง"},{"chinese":"将有免费停泊处。","pinyin":"Jiāng yǒu miǎn fèi tíng bó chǔ。","meaning":"Free moorings will be available.","meaningThai":"จะมีท่าเทียบเรือฟรี"}],"partOfSpeech":["noun","measure word","verb"]},
  {"id":"hsk5-172","chinese":"初","pinyin":"chū","meaning":"at first; (at the) beginning; first; junior; basic","meaningThai":"แต่แรก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"法文版在2006年初面市。","pinyin":"Fǎ wén bǎn zài 2006 nián chū miàn shì。","meaning":"The French edition came out in early 2006.","meaningThai":"ฉบับภาษาฝรั่งเศสออกมาเมื่อต้นปี พ.ศ. 2549"},{"chinese":"我3月初飞到了密尔沃基。","pinyin":"Wǒ 3 yuè chū fēi dào le mì ěr wò jī。","meaning":"I flew to Milwaukee in early March.","meaningThai":"ฉันบินไปมิลวอกีเมื่อต้นเดือนมีนาคม"}],"partOfSpeech":["other","adverb"]},
  {"id":"hsk5-173","chinese":"传","pinyin":"chuán","meaning":"to pass on; to spread; to transmit; to infect; to transfer; to circulate; to conduct (electricity)","meaningThai":"ผ่าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他在伦敦推销他新出版的肯尼迪传。","pinyin":"Tā zài lún dūn tuī xiāo tā xīn chū bǎn de kěn ní dí chuán。","meaning":"He was in London publicizing his new biography of Kennedy.","meaningThai":"เขาอยู่ในลอนดอนเพื่อเผยแพร่ชีวประวัติใหม่ของเคนเนดี้"},{"chinese":"观众欣赏了这支球队娴熟的传接配合。","pinyin":"Guān zhòng xīn shǎng le zhè zhī qiú duì xián shú de chuán jiē pèi hé。","meaning":"The crowd enjoyed the team's slick passing.","meaningThai":"ฝูงชนสนุกสนานกับการจ่ายบอลที่ลื่นไหลของทีม"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-174","chinese":"传播","pinyin":"chuánbō","meaning":"to disseminate; to propagate; to spread","meaningThai":"การแพร่กระจาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种疾病容易传播。","pinyin":"Zhè zhǒng jí bìng róng yì chuán bō。","meaning":"The disease spreads easily.","meaningThai":"โรคนี้แพร่กระจายได้ง่าย"},{"chinese":"他们的研究成果已经广为传播。","pinyin":"Tā mén de yán jiū chéng guǒ yǐ jīng guǎng wéi chuán bō。","meaning":"Their findings have been widely disseminated.","meaningThai":"การค้นพบของพวกเขาได้รับการเผยแพร่อย่างกว้างขวาง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-175","chinese":"传递","pinyin":"chuándì","meaning":"to transmit; to pass on to sb else; (math.) transitive","meaningThai":"ส่งต่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"传递火炬。","pinyin":"Chuan di huo ju.","meaning":"Pass the torch.","meaningThai":"ผ่านคบเพลิง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-176","chinese":"床单","pinyin":"chuángdān","meaning":"bed sheet","meaningThai":"แผ่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"丝绸床单乃是极度的奢侈品。","pinyin":"Sī chóu chuáng dān nǎi shì jí dù de shē chǐ pǐn。","meaning":"Silk sheets are the ultimate luxury.","meaningThai":"ผ้าปูที่นอนผ้าไหมถือเป็นความหรูหราขั้นสูงสุด"},{"chinese":"女仆每个星期换一次床单。","pinyin":"Nǚ pū měi gè xīng qī huàn yī cì chuáng dān。","meaning":"Once a week, a maid changes the sheets.","meaningThai":"แม่บ้านจะเปลี่ยนผ้าปูที่นอนสัปดาห์ละครั้ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-177","chinese":"窗台","pinyin":"chuāngtái","meaning":"window sill; window ledge","meaningThai":"ขอบหน้าต่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"多萝西已经爬到了他窗台外面。","pinyin":"Duō luó xī yǐ jīng pá dào le tā chuāng tái wài miàn。","meaning":"Dorothy had climbed onto the ledge outside his window.","meaningThai":"โดโรธีปีนขึ้นไปบนขอบนอกหน้าต่าง"},{"chinese":"他双手拢作杯状把她托上了窗台。","pinyin":"Tā shuāng shǒu lǒng zuò bēi zhuàng bǎ tā tuō shàng le chuāng tái。","meaning":"He cupped his hands and gave her a boost up to the ledge.","meaningThai":"เขาจับมือของเขาและให้กำลังใจเธอขึ้นไปบนหิ้ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-178","chinese":"创新","pinyin":"chuàngxīn","meaning":"to bring forth new ideas; to blaze new trails; innovation","meaningThai":"นวัตกรรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该乐队仍是音乐界的一支创新力量。","pinyin":"Gāi lè duì réng shì yīn lè jiè de yī zhī chuàng xīn lì liáng。","meaning":"The band is still an innovative force in music.","meaningThai":"วงดนตรียังคงเป็นพลังแห่งนวัตกรรมทางดนตรี"},{"chinese":"他最伟大的创新是使用了可互换部件。","pinyin":"Tā zuì wěi dà de chuàng xīn shì shǐ yòng le kě hù huàn bù jiàn。","meaning":"His greatest innovation was the use of interchangeable parts.","meaningThai":"นวัตกรรมที่ยิ่งใหญ่ที่สุดของเขาคือการใช้ชิ้นส่วนที่เปลี่ยนได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-179","chinese":"创业","pinyin":"chuàngyè","meaning":"to begin an undertaking; to start a major task; to initiate; to venture; venture; entrepreneurship","meaningThai":"เริ่มธุรกิจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"年轻人创业需要勇气。","pinyin":"Nián qīng rén chuàng yè xū yào yǒng qì.","meaning":"Young people need courage to start a business.","meaningThai":"คนหนุ่มสาวต้องการความกล้าในการเริ่มต้นธุรกิจ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-180","chinese":"创造","pinyin":"chuàngzào","meaning":"to create; to bring about; to produce; to set (a record)","meaningThai":"สร้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该法案旨在为妇女创造均等机会。","pinyin":"Gāi fǎ àn zhǐ zài wéi fù nǚ chuàng zào jūn děng jī huì。","meaning":"The bill is needed to create equal opportunity for women.","meaningThai":"ร่างกฎหมายนี้มีความจำเป็นเพื่อสร้างโอกาสที่เท่าเทียมกันสำหรับผู้หญิง"},{"chinese":"工业的主要宗旨是创造财富。","pinyin":"Gōng yè de zhǔ yào zōng zhǐ shì chuàng zào cái fù。","meaning":"The main purpose of industry is to create wealth.","meaningThai":"วัตถุประสงค์หลักของอุตสาหกรรมคือการสร้างความมั่งคั่ง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-181","chinese":"创作","pinyin":"chuàngzuò","meaning":"to create; to produce; to write; creative work; creation","meaningThai":"การสร้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"作为作家，他似乎缺少创作激情。","pinyin":"Zuò wéi zuò jiā， tā sì hū quē shǎo chuàng zuò jī qíng。","meaning":"As a writer he seemed to lack creative spark.","meaningThai":"ในฐานะนักเขียน ดูเหมือนเขาจะขาดจุดประกายความคิดสร้างสรรค์"},{"chinese":"这个浴室完全是我个人的创作。","pinyin":"Zhè gè yù shì wán quán shì wǒ gè rén de chuàng zuò。","meaning":"The bathroom is entirely my own creation.","meaningThai":"ห้องน้ำเป็นผลงานของฉันเองทั้งหมด"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-182","chinese":"传说","pinyin":"chuánshuō","meaning":"legend; folk tale; to repeat from mouth to mouth; they say that...","meaningThai":"ตำนาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"传说与事实很难分辨。","pinyin":"Chuán shuō yǔ shì shí hěn nán fēn biàn。","meaning":"It is difficult to separate legend from truth.","meaningThai":"เป็นการยากที่จะแยกตำนานออกจากความจริง"},{"chinese":"这座山据说是传说中的路德国王休息的地方。","pinyin":"Zhè zuò shān jù shuō shì chuán shuō zhōng de lù dé guó wáng xiū xī de dì fāng。","meaning":"The hill is supposed to be the resting place of the legendary King Lud.","meaningThai":"เนินเขาแห่งนี้น่าจะเป็นที่ประทับของกษัตริย์ลุดในตำนาน"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-183","chinese":"传统","pinyin":"chuántǒng","meaning":"tradition; traditional; convention; conventional","meaningThai":"ธรรมเนียม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"生物燃料能够和传统燃料混合。","pinyin":"Shēng wù rán liào néng gòu hé chuán tǒng rán liào hùn hé。","meaning":"Biofuels can be mixed with conventional fuels.","meaningThai":"เชื้อเพลิงชีวภาพสามารถผสมกับเชื้อเพลิงทั่วไปได้"},{"chinese":"男人还是留着短发，着装传统。","pinyin":"Nán rén huán shì liú zháo duǎn fā， zháo zhuāng chuán tǒng。","meaning":"Men still wore their hair short and dressed conventionally.","meaningThai":"ผู้ชายยังคงไว้ผมสั้นและแต่งตัวตามอัตภาพ"}],"partOfSpeech":["noun","adjective"]},
  {"id":"hsk5-184","chinese":"出版","pinyin":"chūbǎn","meaning":"to publish","meaningThai":"ตีพิมพ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"出版书籍。","pinyin":"Chu ban shu ji.","meaning":"Publish books.","meaningThai":"เผยแพร่หนังสือ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-185","chinese":"初级","pinyin":"chūjí","meaning":"junior; primary","meaningThai":"หลัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他作为一名初级职员进入了该公司。","pinyin":"Tā zuò wéi yī míng chū jí zhí yuán jìn rù le gāi gōng sī。","meaning":"He entered the firm as a junior associate.","meaningThai":"เขาเข้ามาในบริษัทในฐานะผู้ร่วมงานรุ่นน้อง"},{"chinese":"初级护士通常和较高级的护士一起工作。","pinyin":"Chū jí hù shì tōng cháng hé jiào gāo jí de hù shì yī qǐ gōng zuò。","meaning":"Junior nurses usually work alongside more senior nurses.","meaningThai":"พยาบาลรุ่นน้องมักจะทำงานร่วมกับพยาบาลรุ่นพี่มากกว่า"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-186","chinese":"处理","pinyin":"chǔlǐ","meaning":"to handle; to deal with; to punish; to treat sth by a special process; to process; to sell at reduced prices","meaningThai":"จัดการกับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她对情势的处理非常巧妙。","pinyin":"Tā duì qíng shì de chǔ lǐ fēi cháng qiǎo miào。","meaning":"Her handling of the situation was masterly.","meaningThai":"การจัดการกับสถานการณ์ของเธอเป็นไปอย่างเชี่ยวชาญ"},{"chinese":"所有询问都将从速处理。","pinyin":"Suǒ yǒu xún wèn dū jiāng cóng sù chǔ lǐ。","meaning":"All enquiries will be dealt with as speedily as possible.","meaningThai":"คำถามทั้งหมดจะได้รับการจัดการโดยเร็วที่สุด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-187","chinese":"初期","pinyin":"chūqī","meaning":"initial stage; beginning period","meaningThai":"ระยะแรก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"项目初期。","pinyin":"Xiang mu chu qi.","meaning":"Early stage of the project.","meaningThai":"ระยะเริ่มต้นของโครงการ"}],"partOfSpeech":["other"]},
  {"id":"hsk5-188","chinese":"出色","pinyin":"chūsè","meaning":"remarkable; outstanding","meaningThai":"โดดเด่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你的演說很出色。","pinyin":"Nǐ de yǎn shuō hěn chū sè。","meaning":"Your speech was excellent.","meaningThai":"คำพูดของคุณยอดเยี่ยมมาก"},{"chinese":"妳的演說很出色。","pinyin":"Nǐ de yǎn shuō hěn chū sè。","meaning":"Your speech was excellent.","meaningThai":"คำพูดของคุณยอดเยี่ยมมาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-189","chinese":"出售","pinyin":"chūshòu","meaning":"to sell; to offer for sale; to put on the market","meaningThai":"ขาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那时出售股份是精明之举。","pinyin":"Nà shí chū shòu gǔ fèn shì jīng míng zhī jǔ。","meaning":"It was an astute move to sell the shares then.","meaningThai":"มันเป็นการเคลื่อนไหวที่ชาญฉลาดในการขายหุ้นในตอนนั้น"},{"chinese":"他们的房子现在出售。","pinyin":"Tā mén de fáng zǐ xiàn zài chū shòu。","meaning":"They've put their house up for sale.","meaningThai":"พวกเขานำบ้านของพวกเขาไปขาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-190","chinese":"除夕","pinyin":"chúxī","meaning":"lunar New Year's Eve","meaningThai":"วันส่งท้ายปีเก่าทางจันทรคติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"除夕那天我们在海滩上举行了烧烤野餐。","pinyin":"Chú xī nà tiān wǒ mén zài hǎi tān shàng jǔ háng le shāo kǎo yě cān。","meaning":"On New Year's Eve we had a barbecue on the beach.","meaningThai":"ในวันส่งท้ายปีเก่าเรามีบาร์บีคิวบนชายหาด"},{"chinese":"除夕日，我通常举办一个聚会，总是一片狼藉。","pinyin":"Chú xī rì， wǒ tōng cháng jǔ bàn yī gè jù huì， zǒng shì yī piàn láng jiè。","meaning":"On New Year's Eve I usually give a party, which is always chaotic.","meaningThai":"ในวันส่งท้ายปีเก่า ฉันมักจะจัดงานปาร์ตี้ซึ่งมักจะวุ่นวายอยู่เสมอ"}],"partOfSpeech":["other"]},
  {"id":"hsk5-191","chinese":"出席","pinyin":"chūxí","meaning":"to attend; to participate; present","meaningThai":"เข้าร่วม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"全員均須出席。","pinyin":"Quán yuán jūn xū chū xí。","meaning":"Attendance is compulsory for all members.","meaningThai":"การเข้าร่วมเป็นสิ่งจำเป็นสำหรับสมาชิกทุกคน"},{"chinese":"他出席了会议。","pinyin":"Tā chū xí le huì yì。","meaning":"He was present at the meeting.","meaningThai":"เขาอยู่ในที่ประชุม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-192","chinese":"处于","pinyin":"chǔyú","meaning":"to be in (some state, position, or condition)","meaningThai":"ใน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这病尚处于初始阶段。","pinyin":"Zhè bìng shàng chǔ yú chū shǐ jiē duàn。","meaning":"The disease is still in its primary stage.","meaningThai":"โรคนี้ยังอยู่ในระยะเริ่มแรก"},{"chinese":"我觉得处于不利地位。","pinyin":"Wǒ jué dé chǔ yú bù lì dì wèi。","meaning":"I felt at a disadvantage.","meaningThai":"ฉันรู้สึกเสียเปรียบ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-193","chinese":"出自","pinyin":"chūzì","meaning":"to come from","meaningThai":"จาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她一直不很愿意说出自己的计划。","pinyin":"Tā yī zhí bù hěn yuàn yì shuō chū zì jǐ de jì huá。","meaning":"She's never very forthcoming about her plans.","meaningThai":"เธอไม่เคยเตรียมพร้อมเกี่ยวกับแผนการของเธอมากนัก"},{"chinese":"这份报告出自我们的科学部。","pinyin":"Zhè fèn bào gào chū zì wǒ mén de kē xué bù。","meaning":"This report is from our Science Unit.","meaningThai":"รายงานนี้มาจากหน่วยวิทยาศาสตร์ของเรา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-194","chinese":"此后","pinyin":"cǐhòu","meaning":"after this; afterwards; hereafter","meaningThai":"หลังจากนั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"此后不久，国防开支的削减迫使航空航天业紧缩开支。","pinyin":"Cǐ hòu bù jiǔ， guó fáng kāi zhī de xiāo jiǎn pò shǐ háng kōng háng tiān yè jǐn suō kāi zhī。","meaning":"Shortly afterwards, cuts in defence spending forced the aerospace industry to retrench.","meaningThai":"หลังจากนั้นไม่นาน การลดการใช้จ่ายด้านกลาโหมทำให้อุตสาหกรรมการบินและอวกาศต้องถอยทัพลง"},{"chinese":"他们为此后的发展奠定了基础。","pinyin":"Tā mén wéi cǐ hòu de fā zhǎn diàn dìng le jī chǔ。","meaning":"They had laid the groundwork for future develop we are pirates, these data are stolen from youdao .","meaningThai":"พวกเขาวางรากฐานสำหรับการพัฒนาในอนาคต"}],"partOfSpeech":["other"]},
  {"id":"hsk5-195","chinese":"词汇","pinyin":"cíhuì","meaning":"variant of 词汇","meaningThai":"คำศัพท์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的词汇量丰富而且语法也很棒。","pinyin":"Tā de cí huì liáng fēng fù ér qiě yǔ fǎ yě hěn bàng。","meaning":"His vocabulary was sound and his grammar excellent.","meaningThai":"คำศัพท์ของเขาถูกต้องและไวยากรณ์ของเขายอดเยี่ยม"},{"chinese":"他讲话不成熟，词汇量也有限。","pinyin":"Tā jiǎng huà bù chéng shú， cí huì liáng yě yǒu xiàn。","meaning":"His speech is immature, his vocabulary limited.","meaningThai":"คำพูดของเขายังไม่บรรลุนิติภาวะ คำศัพท์ของเขามีจำกัด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-196","chinese":"刺激","pinyin":"cìjī","meaning":"to provoke; to irritate; to upset; to stimulate; to excite; irritant","meaningThai":"กระตุ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你今年做的最刺激的事是什么？","pinyin":"Nǐ jīn nián zuò de zuì cì jī de shì shì shí mó？","meaning":"What's the most exciting thing you've done this year?","meaningThai":"คุณทำอะไรที่น่าตื่นเต้นที่สุดในปีนี้?"},{"chinese":"减税常被用作刺激经济的主要财政手段。","pinyin":"Jiǎn shuì cháng bèi yòng zuò cì jī jīng jì de zhǔ yào cái zhèng shǒu duàn。","meaning":"Tax cuts are often used as a major fiscal tool to stimulate the economy.","meaningThai":"การลดภาษีมักใช้เป็นเครื่องมือทางการคลังที่สำคัญในการกระตุ้นเศรษฐกิจ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-197","chinese":"此前","pinyin":"cǐqián","meaning":"before this; before then; previously","meaningThai":"ก่อนหน้านี้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“这在此前早该定下了。”—“我们不可能事事都考虑。”","pinyin":"“ zhè zài cǐ qián zǎo gāi dìng xià le。”—“ wǒ mén bù kě néng shì shì dū kǎo lǜ。”","meaning":"\"This should have been decided long before now.\"—\"We can't think of everything.\"","meaningThai":"\"เรื่องนี้ควรจะตัดสินใจมานานแล้ว\"—\"เราไม่สามารถคิดถึงทุกสิ่งได้\""},{"chinese":"此前，科学家们注意到污染物随风抵达北极。","pinyin":"Cǐ qián， kē xué jiā mén zhù yì dào wū rǎn wù suí fēng dǐ dá běi jí。","meaning":"Previously, scientists noticed pollutants arriving in the Arctic with the wind.","meaningThai":"ก่อนหน้านี้ นักวิทยาศาสตร์สังเกตเห็นมลพิษที่เข้ามาถึงอาร์กติกพร้อมกับลม"}],"partOfSpeech":["other"]},
  {"id":"hsk5-198","chinese":"此时","pinyin":"cǐshí","meaning":"now; this moment","meaningThai":"ในเวลานี้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"从此时开始，我们可能会有麻烦。","pinyin":"Cóng cǐ shí kāi shǐ， wǒ mén kě néng huì yǒu má fán。","meaning":"We can expect trouble from this moment on.","meaningThai":"เราอาจคาดหวังปัญหาได้ตั้งแต่บัดนี้เป็นต้นไป"},{"chinese":"到此时，已没有什么道理可讲。","pinyin":"Dào cǐ shí， yǐ méi yǒu shí mó dào lǐ kě jiǎng。","meaning":"By now all logic had gone out of the window.","meaningThai":"ตอนนี้ตรรกะทั้งหมดหายไปนอกหน้าต่างแล้ว"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-199","chinese":"辞职","pinyin":"cízhí","meaning":"to resign","meaningThai":"ลาออก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他辞职了。","pinyin":"Ta ci zhi le.","meaning":"He resigned.","meaningThai":"เขาลาออก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-200","chinese":"从不","pinyin":"cóng bù","meaning":"never","meaningThai":"ไม่เคย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他对他妻子从不抱怨。","pinyin":"Tā duì tā qī zǐ cóng bù bào yuàn。","meaning":"He never complains about his wife.","meaningThai":"เขาไม่เคยบ่นเกี่ยวกับภรรยาของเขา"},{"chinese":"我从不吝啬使用大蒜。","pinyin":"Wǒ cóng bù lìn sè shǐ yòng dà suàn。","meaning":"I'm never sparing with the garlic.","meaningThai":"ฉันไม่เคยงดเว้นกับกระเทียม"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-201","chinese":"从而","pinyin":"cóng’ér","meaning":"thus; thereby","meaningThai":"จึง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"从而取得成功。","pinyin":"Cong er qu de cheng gong.","meaning":"Thus achieving success.","meaningThai":"จึงจะบรรลุผลสำเร็จ.."}],"partOfSpeech":["conjunction"]},
  {"id":"hsk5-202","chinese":"从前","pinyin":"cóngqián","meaning":"previously; formerly; once upon a time","meaningThai":"กาลครั้งหนึ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"传统故事采用“从前…”一类的套语。","pinyin":"Chuán tǒng gù shì cǎi yòng “ cóng qián …” yī lèi de tào yǔ。","meaning":"Traditional stories make use of formulaic expressions like 'Once upon a time...'.","meaningThai":"เรื่องราวแบบดั้งเดิมใช้สำนวนที่เป็นสูตร เช่น 'กาลครั้งหนึ่ง...'"},{"chinese":"从前，有一位美丽的公主。","pinyin":"Cóng qián， yǒu yī wèi měi lì de gōng zhǔ。","meaning":"Once upon a time there was a beautiful princess.","meaningThai":"กาลครั้งหนึ่งมีเจ้าหญิงแสนสวยองค์หนึ่ง"}],"partOfSpeech":["other"]},
  {"id":"hsk5-203","chinese":"从事","pinyin":"cóngshì","meaning":"to go for; to engage in; to undertake; to deal with; to handle; to do","meaningThai":"มีส่วนร่วม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他想从事电影制作。","pinyin":"Tā xiǎng cóng shì diàn yǐng zhì zuò。","meaning":"He wants a career in film production.","meaningThai":"เขาต้องการมีอาชีพในการผลิตภาพยนตร์"},{"chinese":"我想从事戏剧工作。","pinyin":"Wǒ xiǎng cóng shì xì jù gōng zuò。","meaning":"I want to work in theatre.","meaningThai":"ฉันอยากทำงานในโรงละคร"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-204","chinese":"催","pinyin":"cuī","meaning":"to urge; to press; to prompt; to rush sb; to hasten sth; to expedite","meaningThai":"กระตุ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"别催我。我需要时间考虑一下。","pinyin":"Bié cuī wǒ。 wǒ xū yào shí jiān kǎo lǜ yī xià。","meaning":"Don't rush me. I need time to think about it.","meaningThai":"อย่าเร่งฉันเลย ฉันต้องใช้เวลาคิดเกี่ยวกับมัน"},{"chinese":"我得催他组织安排这次会议。","pinyin":"Wǒ dé cuī tā zǔ zhī ān pái zhè cì huì yì。","meaning":"I need to chase him about organizing the meeting.","meaningThai":"ฉันต้องไล่เขาเรื่องการจัดประชุม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-205","chinese":"促进","pinyin":"cùjìn","meaning":"to promote (an idea or cause); to advance; boost","meaningThai":"ส่งเสริม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些蛋白质促进血细胞的生成。","pinyin":"Zhè xiē dàn bái zhì cù jìn xiě xì bāo de shēng chéng。","meaning":"These proteins stimulate the production of blood cells.","meaningThai":"โปรตีนเหล่านี้กระตุ้นการผลิตเซลล์เม็ดเลือด"},{"chinese":"身体运动促进健康。","pinyin":"Shēn tǐ yùn dòng cù jìn jiàn kāng。","meaning":"Physical activity promotes good health.","meaningThai":"การออกกำลังกายส่งเสริมสุขภาพที่ดี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-206","chinese":"存放","pinyin":"cúnfàng","meaning":"to deposit; to store; to leave in sb's care","meaningThai":"เก็บ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"蓝色卷宗是用来存放旧发票的。","pinyin":"Lán sè juàn zōng shì yòng lái cún fàng jiù fā piào de。","meaning":"The blue files are used for storing old invoices.","meaningThai":"ไฟล์สีน้ำเงินใช้สำหรับจัดเก็บใบแจ้งหนี้เก่า"},{"chinese":"烫衣板能够折起来，便于存放。","pinyin":"Tàng yī bǎn néng gòu zhē qǐ lái， biàn yú cún fàng。","meaning":"The ironing board folds flat for easy storage.","meaningThai":"โต๊ะรีดผ้าพับแบนเพื่อให้จัดเก็บได้ง่าย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-207","chinese":"存款","pinyin":"cúnkuǎn","meaning":"to deposit money (in a bank etc); bank savings; bank deposit","meaningThai":"เงินฝาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的存款以前在第一国民银行。","pinyin":"Tā de cún kuǎn yǐ qián zài dì yī guó mín yín háng。","meaning":"Her savings were in the First National Bank.","meaningThai":"เงินออมของเธออยู่ในธนาคารแห่งชาติแห่งแรก"},{"chinese":"高利率的存款会产生丰厚的收益。","pinyin":"Gāo lì shuài de cún kuǎn huì chǎn shēng fēng hòu de shōu yì。","meaning":"Higher-rate deposit accounts yield good returns.","meaningThai":"บัญชีเงินฝากที่มีอัตราดอกเบี้ยสูงจะให้ผลตอบแทนที่ดี"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-208","chinese":"存在","pinyin":"cúnzài","meaning":"to exist; to be; existence","meaningThai":"มีอยู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我去看过母校是否依然存在。","pinyin":"Wǒ qù kàn guò mǔ xiào shì fǒu yī rán cún zài。","meaning":"I went to see if my old school was still there.","meaningThai":"ฉันไปดูว่าโรงเรียนเก่าของฉันยังอยู่ที่นั่นหรือไม่"},{"chinese":"它于梦想而非实际中存在。","pinyin":"Tā yú mèng xiǎng ér fēi shí jì zhōng cún zài。","meaning":"It exists in dreams rather than actuality.","meaningThai":"มันมีอยู่ในความฝันมากกว่าความเป็นจริง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-209","chinese":"措施","pinyin":"cuòshī","meaning":"measure; step","meaningThai":"วัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些措施旨在防止暴力犯罪。","pinyin":"Zhè xiē cuò shī zhǐ zài fáng zhǐ bào lì fàn zuì。","meaning":"These measures are aimed at preventing violent crime.","meaningThai":"มาตรการเหล่านี้มีวัตถุประสงค์เพื่อป้องกันอาชญากรรมรุนแรง"},{"chinese":"有人要求采用新型的安保措施。","pinyin":"Yǒu rén yào qiú cǎi yòng xīn xíng de ān bǎo cuò shī。","meaning":"There have been calls for a new kind of security arrangement.","meaningThai":"มีการเรียกร้องให้มีการจัดการด้านความปลอดภัยรูปแบบใหม่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-210","chinese":"促使","pinyin":"cùshǐ","meaning":"to induce; to promote; to urge; to impel; to bring about; to provoke; to drive (sb to do sth); to catalyze; to actuate; to contribute to (some development)","meaningThai":"พร้อมท์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这次访问促使全世界关注难民困境。","pinyin":"Zhè cì fǎng wèn cù shǐ quán shì jiè guān zhù nán mín kùn jìng。","meaning":"The visit helped to focus world attention on the plight of the refugees.","meaningThai":"การเยือนครั้งนี้ช่วยดึงความสนใจของโลกไปที่ชะตากรรมของผู้ลี้ภัย"},{"chinese":"是什么促使你从事律师业的呢？","pinyin":"Shì shí mó cù shǐ nǐ cóng shì lǜ shī yè de ne？","meaning":"What made you go into law?","meaningThai":"อะไรทำให้คุณเข้าสู่กฎหมาย?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-211","chinese":"促销","pinyin":"cùxiāo","meaning":"to promote sales","meaningThai":"ส่งเสริมการขาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"商场正在进行促销活动。","pinyin":"Shāng chǎng zhèng zài jìn xíng cù xiāo huó dòng.","meaning":"The mall is having a promotion event.","meaningThai":"ห้างสรรพสินค้ากำลังมีกิจกรรมส่งเสริมการขาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-212","chinese":"打扮","pinyin":"dǎban","meaning":"to decorate; to dress; to make up; to adorn; manner of dressing; style of dress","meaningThai":"แต่งตัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她打扮得很漂亮。","pinyin":"Ta da ban de hen piao liang.","meaning":"She dressed up beautifully.","meaningThai":"เธอแต่งตัวได้สวยงาม"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-213","chinese":"打包","pinyin":"dǎbāo","meaning":"to wrap; to pack; to put leftovers in a doggy bag for take-out; (computing) to package (i.e. create an archive file)","meaningThai":"ห่อกลับบ้าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"吃不完的打包吧。","pinyin":"Chi bu wan de da bao ba.","meaning":"Let's pack the leftovers.","meaningThai":"มาแพ็คของที่เหลือกัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-214","chinese":"达成","pinyin":"dáchéng","meaning":"to reach (an agreement); to accomplish","meaningThai":"บรรลุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"双方最终达成了暂时的妥协。","pinyin":"Shuāng fāng zuì zhōng dá chéng le zàn shí de tuǒ xié。","meaning":"The two sides eventually reached an uneasy compromise.","meaningThai":"ทั้งสองฝ่ายบรรลุข้อตกลงประนีประนอมอย่างไม่สบายใจในที่สุด"},{"chinese":"他和当局达成了辩诉交易。","pinyin":"Tā hé dāng jú dá chéng le biàn sù jiāo yì。","meaning":"He reached a plea bargain with the authorities.","meaningThai":"เขาบรรลุข้อตกลงต่อรองกับเจ้าหน้าที่แล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-215","chinese":"大胆","pinyin":"dàdǎn","meaning":"brazen; audacious; outrageous; bold; daring; fearless","meaningThai":"ตัวหนา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在1960年，这是一个大胆的举动。","pinyin":"Zài 1960 nián， zhè shì yī gè dà dǎn de jǔ dòng。","meaning":"In 1960 this was a bold move.","meaningThai":"ในปี 1960 นี่เป็นการเคลื่อนไหวที่กล้าหาญ"},{"chinese":"该画廊以其举办的大胆画展而享有盛名。","pinyin":"Gāi huà láng yǐ qí jǔ bàn de dà dǎn huà zhǎn ér xiǎng yǒu shèng míng。","meaning":"The gallery was known for putting on daring exhibitions.","meaningThai":"แกลเลอรีแห่งนี้มีชื่อเสียงในด้านการจัดนิทรรศการที่ท้าทายความสามารถ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-216","chinese":"打断","pinyin":"dǎduàn","meaning":"to interrupt; to break off; to break (a bone)","meaningThai":"ขัดจังหวะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"电话铃声打断了我的思路。","pinyin":"Diàn huà líng shēng dǎ duàn le wǒ de sī lù。","meaning":"The phone ringing interrupted my train of thought.","meaningThai":"เสียงโทรศัพท์ดังขึ้นขัดจังหวะความคิดของฉัน"},{"chinese":"她为什么偏要打断呢？","pinyin":"Tā wéi shí mó piān yào dǎ duàn ne？","meaning":"Why must she interrupt?","meaningThai":"ทำไมเธอต้องขัดขวาง?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-217","chinese":"大多","pinyin":"dàduō","meaning":"for the most part; many; most; the greater part; mostly","meaningThai":"ที่สุด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的笑话大多粗俗不堪。","pinyin":"Tā de xiào huà dà duō cū sú bù kān。","meaning":"Most of his jokes were in very poor taste.","meaningThai":"เรื่องตลกของเขาส่วนใหญ่มีรสนิยมแย่มาก"},{"chinese":"汽车大多是金属制成的。","pinyin":"Qì chē dà duō shì jīn shǔ zhì chéng de。","meaning":"Cars are mostly metal.","meaningThai":"รถยนต์ส่วนใหญ่เป็นโลหะ"}],"partOfSpeech":["adverb","numeral"]},
  {"id":"hsk5-218","chinese":"大会","pinyin":"dàhuì","meaning":"general assembly; general meeting; convention","meaningThai":"สมัชชาใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该党雇她精心策划他们的大会。","pinyin":"Gāi dǎng gù tā jīng xīn cè huá tā mén de dà huì。","meaning":"The party hired her to stage-manage their convention.","meaningThai":"งานปาร์ตี้จ้างเธอให้จัดเวทีจัดการการประชุมของพวกเขา"},{"chinese":"他们挥动着非洲国民大会的旗帜。","pinyin":"Tā mén huī dòng zháo fēi zhōu guó mín dà huì de qí zhì。","meaning":"They flew the flag of the African National Congress.","meaningThai":"พวกเขาชักธงของสภาแห่งชาติแอฟริกัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-219","chinese":"代","pinyin":"dài","meaning":"to substitute; to act on behalf of others; to replace; generation; dynasty; age; period; (historical) era; (geological) eon","meaningThai":"รุ่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这座房子属于她家已有三四代了。","pinyin":"Zhè zuò fáng zǐ shǔ yú tā jiā yǐ yǒu sān sì dài le。","meaning":"The house had belonged to her family for three or four generations.","meaningThai":"บ้านหลังนี้เป็นของครอบครัวของเธอมาสามหรือสี่ชั่วอายุคนแล้ว"},{"chinese":"该剧表现了3代人之间的冲突。","pinyin":"Gāi jù biǎo xiàn le 3 dài rén zhī jiān de chōng tū。","meaning":"The play represents the collision of three generations.","meaningThai":"ละครแสดงถึงการปะทะกันของสามชั่วอายุคน"}],"partOfSpeech":["verb","measure word","noun"]},
  {"id":"hsk5-220","chinese":"代表","pinyin":"dàibiǎo","meaning":"representative; delegate; to represent; to stand for; on behalf of; in the name of","meaningThai":"แทน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"代表依次在桌子周围就座。","pinyin":"Dài biǎo yī cì zài zhuō zǐ zhōu wéi jiù zuò。","meaning":"The delegates ranged themselves around the table.","meaningThai":"บรรดาผู้ได้รับมอบหมายต่างยืนล้อมรอบโต๊ะ"},{"chinese":"那位加拿大代表没给答复。","pinyin":"Nà wèi jiā ná dà dài biǎo méi gěi dá fù。","meaning":"The Canadian delegate offered no reply.","meaningThai":"ผู้แทนชาวแคนาดาไม่ตอบ"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-221","chinese":"带动","pinyin":"dàidòng","meaning":"to spur; to provide impetus; to drive","meaningThai":"ขับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们试着用柴油机来带动水泵。","pinyin":"Wǒ mén shì zháo yòng chái yóu jī lái dài dòng shuǐ bèng。","meaning":"We experimented with diesel engines to drive the pumps.","meaningThai":"เราทดลองเครื่องยนต์ดีเซลเพื่อขับเคลื่อนปั๊ม"},{"chinese":"电视的普及带动了冷冻食品的普及。","pinyin":"Diàn shì de pǔ jí dài dòng le lěng dòng shí pǐn de pǔ jí。","meaning":"The popularity of TV led to the popularity of frozen food.","meaningThai":"ความนิยมของทีวีส่งผลให้อาหารแช่แข็งได้รับความนิยม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-222","chinese":"代替","pinyin":"dàitì","meaning":"to replace; to take the place of","meaningThai":"แทนที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这道食谱可以用牛奶代替奶油。","pinyin":"Zhè dào shí pǔ kě yǐ yòng niú nǎi dài tì nǎi yóu。","meaning":"You can use milk in place of cream in this recipe.","meaningThai":"คุณสามารถใช้นมแทนครีมได้ในสูตรนี้"},{"chinese":"他们找到了代替她的人没有？","pinyin":"Tā mén zhǎo dào le dài tì tā de rén méi yǒu？","meaning":"Have they found anyone to replace her yet?","meaningThai":"พวกเขาพบใครมาแทนที่เธอแล้วหรือยัง?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-223","chinese":"待遇","pinyin":"dàiyù","meaning":"treatment; pay; salary; status; rank","meaningThai":"การรักษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她对自己受到的待遇大为光火。","pinyin":"Tā duì zì jǐ shòu dào de dài yù dà wéi guāng huǒ。","meaning":"She was very indignant at the way she had been treated.","meaningThai":"เธอไม่พอใจมากกับวิธีที่เธอได้รับการปฏิบัติ"},{"chinese":"农民能够享受某种具体的税收待遇。","pinyin":"Nóng mín néng gòu xiǎng shòu mǒu zhǒng jù tǐ de shuì shōu dài yù。","meaning":"A farmer is entitled to a certain particularized tax treat we are pirates, these data are stolen from youdao .","meaningThai":"เกษตรกรสามารถเพลิดเพลินกับการรักษาภาษีบางประเภทได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-224","chinese":"大力","pinyin":"dàlì","meaning":"energetically; vigorously","meaningThai":"อย่างจริงจัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些措施得到环境保护组织的大力支持。","pinyin":"Zhè xiē cuò shī dé dào huán jìng bǎo hù zǔ zhī de dà lì zhī chí。","meaning":"These measures are strongly supported by environmental groups.","meaningThai":"มาตรการเหล่านี้ได้รับการสนับสนุนอย่างมากจากกลุ่มสิ่งแวดล้อม"},{"chinese":"公众大力支持这一变革。","pinyin":"Gōng zhòng dà lì zhī chí zhè yī biàn gé。","meaning":"There is strong public support for the change.","meaningThai":"มีการสนับสนุนจากสาธารณะอย่างแข็งขันสำหรับการเปลี่ยนแปลง"}],"partOfSpeech":["adverb","noun"]},
  {"id":"hsk5-225","chinese":"大妈","pinyin":"dàmā","meaning":"father's elder brother's wife; aunt (affectionate term for an elderly woman)","meaningThai":"ป้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"霍勒大妈很快就厌倦了她，告诉她可以走了。","pinyin":"Huò lè dà mā hěn kuài jiù yàn juàn le tā， gào sù tā kě yǐ zǒu le。","meaning":"Mother Holle very soon got tired of her, and told her she might go.","meaningThai":"ไม่นานคุณแม่โฮลก็เบื่อเธอ และบอกเธอว่าเธอไปได้แล้ว"},{"chinese":"大妈，我帮您好吗？","pinyin":"Dà mā， wǒ bāng nín hǎo ma？","meaning":"May I help you, Auntie?","meaningThai":"ฉันสามารถช่วยคุณป้าได้ไหม?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-226","chinese":"大米","pinyin":"dàmǐ","meaning":"(husked) rice","meaningThai":"ข้าว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人们按照传统习俗朝他们抛撒大米。","pinyin":"Rén mén àn zhào chuán tǒng xí sú zhāo tā mén pāo sā dà mǐ。","meaning":"They were showered with rice in the traditional manner.","meaningThai":"จะมีการอาบข้าวตามวิธีดั้งเดิม"},{"chinese":"大米是世界上半数以上人口的主食。","pinyin":"Dà mǐ shì shì jiè shàng bàn shù yǐ shàng rén kǒu de zhǔ shí。","meaning":"Rice is the staple food of more than half the world's population.","meaningThai":"ข้าวเป็นอาหารหลักของประชากรมากกว่าครึ่งหนึ่งของโลก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-227","chinese":"淡","pinyin":"dàn","meaning":"insipid; diluted; weak; mild; light in color; tasteless; indifferent; (variant of 氮) nitrogen","meaningThai":"แสงสว่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这颜料可用水稀释以使色度淡一些。","pinyin":"Zhè yán liào kě yòng shuǐ xī shì yǐ shǐ sè dù dàn yī xiē。","meaning":"The paint can be diluted with water to make a lighter shade.","meaningThai":"สามารถเจือจางสีด้วยน้ำเพื่อให้ได้สีที่จางลง"},{"chinese":"卧室涂成了淡粉红色。","pinyin":"Wò shì tú chéng le dàn fěn hóng sè。","meaning":"The bedroom was decorated in pale pinks.","meaningThai":"ห้องนอนตกแต่งด้วยสีชมพูอ่อน"}],"partOfSpeech":["adjective","other"]},
  {"id":"hsk5-228","chinese":"单","pinyin":"dān","meaning":"surname Shan","meaningThai":"หนึ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她脖子上戴着单串珍珠。","pinyin":"Tā bó zǐ shàng dài zháo dān chuàn zhēn zhū。","meaning":"She wore a single strand of pearls around her neck.","meaningThai":"เธอสวมไข่มุกเส้นเดียวรอบคอของเธอ"},{"chinese":"他单膝跪下向她求婚。","pinyin":"Tā dān xī guì xià xiàng tā qiú hūn。","meaning":"He went down on one knee and asked her to marry him.","meaningThai":"เขาคุกเข่าข้างหนึ่งแล้วขอเธอแต่งงานกับเขา"}],"partOfSpeech":["adverb","adjective","other"]},
  {"id":"hsk5-229","chinese":"大脑","pinyin":"dànǎo","meaning":"brain; cerebrum","meaningThai":"สมอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"大脑控制身体。","pinyin":"Dà nǎo kòng zhì shēn tǐ.","meaning":"The brain controls the body.","meaningThai":"สมองควบคุมร่างกาย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-230","chinese":"单独","pinyin":"dāndú","meaning":"alone; by oneself; on one's own","meaningThai":"ตามลำพัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们先单独照相，然后合影。","pinyin":"Tā mén xiān dān dú zhào xiāng， rán hòu hé yǐng。","meaning":"They were photographed separately and then as a group.","meaningThai":"พวกเขาถ่ายรูปแยกกันและถ่ายรูปเป็นกลุ่ม"},{"chinese":"这些涂料可单独或混合使用。","pinyin":"Zhè xiē tú liào kě dān dú huò hùn hé shǐ yòng。","meaning":"These paints can be used individually or in combination.","meaningThai":"สีเหล่านี้สามารถใช้เป็นสีเดียวหรือรวมกันได้"}],"partOfSpeech":["adverb","adjective"]},
  {"id":"hsk5-231","chinese":"当","pinyin":"dàng","meaning":"(onom.) dong; ding dong (bell)","meaningThai":"เป็น; เมื่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们选出了詹姆斯当主席。","pinyin":"Wǒmen xuǎnchū le zhānmǔsī dāng zhǔxí.","meaning":"We elected James chairman.","meaningThai":"เราเลือกประธานเจมส์"},{"chinese":"当我醒来时，天正下著雪。","pinyin":"Dāng wǒ xǐngláishí, tiānzhèng xià zhù xuě.","meaning":"When I awoke, it was snowing.","meaningThai":"เมื่อฉันตื่นขึ้น หิมะตก"},{"chinese":"当我到达时，天正下著雨。","pinyin":"Dāng wǒ dàodá shí, tiānzhèng xià zhù yǔ.","meaning":"When I arrived, it was raining.","meaningThai":"เมื่อฉันมาถึง ฝนก็ตก"}],"partOfSpeech":["preposition","verb"]},
  {"id":"hsk5-232","chinese":"挡","pinyin":"dǎng","meaning":"to resist; to obstruct; to hinder; to keep off; to block (a blow); to get in the way of; cover; gear (e.g. in a car's transmission)","meaningThai":"ปิดกั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他换了挡，慢慢把车开走了。","pinyin":"Tā huàn le dǎng， màn màn bǎ chē kāi zǒu le。","meaning":"He changes gear and pulls away slowly.","meaningThai":"เขาเปลี่ยนเกียร์และออกตัวช้าๆ"},{"chinese":"在山上，他必须用低速挡。","pinyin":"Zài shān shàng， tā bì xū yòng dī sù dǎng。","meaning":"On hills, he must use low gears.","meaningThai":"บนเนินเขาต้องใช้เกียร์ต่ำ"}],"partOfSpeech":["verb","measure word"]},
  {"id":"hsk5-233","chinese":"当成","pinyin":"dàngchéng","meaning":"to consider as; to take to be","meaningThai":"เช่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我一直把你当成自家人。","pinyin":"Wǒ yī zhí bǎ nǐ dāng chéng zì jiā rén。","meaning":"I always think of you as one of the family.","meaningThai":"ฉันคิดเสมอว่าคุณเป็นหนึ่งในครอบครัว"},{"chinese":"我把这个地方当成了家。","pinyin":"Wǒ bǎ zhè gè dì fāng dāng chéng le jiā。","meaning":"I think of this place as my home.","meaningThai":"ฉันคิดว่าสถานที่แห่งนี้เป็นบ้านของฉัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-234","chinese":"当地","pinyin":"dāngdì","meaning":"local","meaningThai":"ท้องถิ่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那只猫相当地胖。","pinyin":"Nà zhī māo xiāng dāng dì pàng。","meaning":"That cat is quite fat.","meaningThai":"แมวตัวนั้นค่อนข้างอ้วน"},{"chinese":"这家报社在当地知名度颇高。","pinyin":"Zhè jiā bào shè zài dāng dì zhī míng dù pō gāo。","meaning":"This newspaper is well known in the local area.","meaningThai":"หนังสือพิมพ์ฉบับนี้เป็นที่รู้จักกันดีในท้องถิ่น"}],"partOfSpeech":["other"]},
  {"id":"hsk5-235","chinese":"当年","pinyin":"dāngnián","meaning":"in those days; then; in those years; during that time","meaningThai":"แล้ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们称赞他为当年的最佳作者。","pinyin":"Tā mén chēng zàn tā wéi dāng nián de zuì jiā zuò zhě。","meaning":"They acclaimed him as the best writer of the year.","meaningThai":"พวกเขายกย่องให้เขาเป็นนักเขียนที่ดีที่สุดแห่งปี"},{"chinese":"这是当年白求恩大夫用的手术刀。","pinyin":"Zhè shì dāng nián bái qiú ēn dà fū yòng de shǒu shù dāo。","meaning":"This is the scalpel which Norman Bethune used in those days.","meaningThai":"นี่คือมีดผ่าตัดที่นอร์แมน เบทูนใช้ในสมัยนั้น"}],"partOfSpeech":["other"]},
  {"id":"hsk5-236","chinese":"当前","pinyin":"dāngqián","meaning":"the present time; to be faced with","meaningThai":"ปัจจุบัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他承认，当前的制度有些缺陷。","pinyin":"Tā chéng rèn， dāng qián de zhì dù yǒu xiē quē xiàn。","meaning":"He concedes that there are imperfections in the current system.","meaningThai":"เขายอมรับว่ามีความไม่สมบูรณ์ในระบบปัจจุบัน"},{"chinese":"事情主要取决于当前和谈的结果。","pinyin":"Shì qíng zhǔ yào qǔ jué yú dāng qián hé tán de jié guǒ。","meaning":"Much turns on the outcome of the current peace talks.","meaningThai":"ผลลัพธ์ของการเจรจาสันติภาพในปัจจุบันเปลี่ยนแปลงไปมาก"}],"partOfSpeech":["other"]},
  {"id":"hsk5-237","chinese":"当中","pinyin":"dāngzhōng","meaning":"among; in the middle; in the center","meaningThai":"ท่ามกลาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"谁知道他们当中谁有更大权利？","pinyin":"Shuí zhī dào tā mén dāng zhōng shuí yǒu gēng dà quán lì？","meaning":"Who is to say which of them had more power?","meaningThai":"ใครจะบอกว่าใครมีอำนาจมากกว่ากัน?"},{"chinese":"他们当中并不是人人都受到邀请。","pinyin":"Tā mén dāng zhōng bìng bù shì rén rén dū shòu dào yāo qǐng。","meaning":"Not all of them were invited.","meaningThai":"ไม่ใช่ทุกคนที่ได้รับเชิญ"}],"partOfSpeech":["other"]},
  {"id":"hsk5-238","chinese":"当作","pinyin":"dàngzuò","meaning":"to treat as; to regard as","meaningThai":"เช่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他力劝她把这次拘捕当作一次警钟。","pinyin":"Tā lì quàn tā bǎ zhè cì jū bǔ dāng zuò yī cì jǐng zhōng。","meaning":"He urged her to treat the arrest as a wake-up call.","meaningThai":"เขากระตุ้นให้เธอปฏิบัติต่อการจับกุมเหมือนเป็นการปลุก"},{"chinese":"他们伟大的学术成就被当作了典范。","pinyin":"Tā mén wěi dà de xué shù chéng jiù bèi dāng zuò le diǎn fàn。","meaning":"Their great academic success was paraded as paradigmatic.","meaningThai":"ความสำเร็จทางวิชาการอันยิ่งใหญ่ของพวกเขาได้รับการยกย่องว่าเป็นกระบวนทัศน์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-239","chinese":"担任","pinyin":"dānrèn","meaning":"to hold a governmental office or post; to assume office of; to take charge of; to serve as","meaningThai":"ดูแล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他将会继续担任荣誉主席。","pinyin":"Tā jiāng huì jì xù dān rèn róng yù zhǔ xí。","meaning":"He will continue as chairman emeritus.","meaningThai":"เขาจะดำรงตำแหน่งประธานกิตติมศักดิ์ต่อไป"},{"chinese":"由他担任临时法官。","pinyin":"Yóu tā dān rèn lín shí fǎ guān。","meaning":"He was sitting as a temporary judge.","meaningThai":"พระองค์ทรงนั่งเป็นผู้พิพากษาชั่วคราว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-240","chinese":"胆小","pinyin":"dǎnxiǎo","meaning":"cowardice; timid","meaningThai":"ขี้อาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他公开指责对手胆小怯懦。","pinyin":"Tā gōng kāi zhǐ zé duì shǒu dǎn xiǎo qiè nuò。","meaning":"He openly accused his opponents of cowardice.","meaningThai":"เขากล่าวหาฝ่ายตรงข้ามอย่างเปิดเผยว่าขี้ขลาด"},{"chinese":"它们通常很胆小，极少远离自己的洞穴。","pinyin":"Tā mén tōng cháng hěn dǎn xiǎo， jí shǎo yuǎn lí zì jǐ de dòng xué。","meaning":"Normally timid, they rarely stray far from their burrows.","meaningThai":"โดยปกติแล้วพวกมันจะขี้อาย พวกมันจะไม่ค่อยหลงทางไปไกลจากโพรง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-241","chinese":"单一","pinyin":"dānyī","meaning":"single; only; sole","meaningThai":"เดี่ยว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"支持欧洲单一货币的人比反对的多。","pinyin":"Zhī chí ōu zhōu dān yī huò bì de rén bǐ fǎn duì de duō。","meaning":"More people favour a single European currency than oppose it.","meaningThai":"ผู้คนจำนวนมากนิยมสกุลเงินยุโรปสกุลเดียวมากกว่าที่คัดค้าน"},{"chinese":"什么时候实行单一货币？","pinyin":"Shí mó shí hòu shí háng dān yī huò bì？","meaning":"When will the single currency be operable?","meaningThai":"สกุลเงินเดียวจะใช้งานได้เมื่อใด?"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-242","chinese":"单元","pinyin":"dānyuán","meaning":"unit (forming an entity); element; (in a residential building) entrance or staircase","meaningThai":"หน่วย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"存储单元里的数据应该左对齐。","pinyin":"Cún chǔ dān yuán lǐ de shù jù yīng gāi zuǒ duì qí。","meaning":"The data in the cells should be left-justified.","meaningThai":"ข้อมูลในเซลล์ควรจัดชิดซ้าย"},{"chinese":"农业过去以一个家庭单元为基础。","pinyin":"Nóng yè guò qù yǐ yī gè jiā tíng dān yuán wéi jī chǔ。","meaning":"Agriculture was based in the past on the family as a unit.","meaningThai":"เกษตรกรรมมีพื้นฐานมาจากครอบครัวเป็นหน่วย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-243","chinese":"倒","pinyin":"dǎo","meaning":"to fall; to collapse; to lie horizontally; to fail; to go bankrupt; to overthrow; to change (trains or buses); to move around; to resell at a profit","meaningThai":"เท; กลับหัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"请把水倒进杯子里。","pinyin":"Qǐng bǎ shuǐ dào jìn bēizi lǐ.","meaning":"Please pour the water into the cup.","meaningThai":"กรุณาเทน้ำลงในถ้วย"},{"chinese":"他给客人倒了一杯茶。","pinyin":"Tā gěi kèrén dào le yìbēi chá.","meaning":"He poured a cup of tea for the guest.","meaningThai":"เขารินชาให้แขก"},{"chinese":"你把地图拿倒了。","pinyin":"Nǐ bǎ dìtú ná dào le.","meaning":"You are holding the map upside down.","meaningThai":"คุณกำลังถือแผนที่กลับหัว"}],"partOfSpeech":["verb","adverb"]},
  {"id":"hsk5-244","chinese":"到达","pinyin":"dàodá","meaning":"to reach; to arrive","meaningThai":"ถึง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们准时到达了。","pinyin":"Wǒ men zhǔn shí dào dá le.","meaning":"We arrived on time.","meaningThai":"เรามาถึงตรงเวลา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-245","chinese":"道理","pinyin":"dàolǐ","meaning":"reason; argument; sense; principle; basis; justification","meaningThai":"เหตุผล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"认为她在说谎完全没道理。","pinyin":"Rèn wéi tā zài shuō huǎng wán quán méi dào lǐ。","meaning":"There is no reason to suppose she's lying.","meaningThai":"ไม่มีเหตุผลที่จะคิดว่าเธอกำลังโกหก"},{"chinese":"饱和营销的概念很有道理。","pinyin":"Bǎo hé yíng xiāo de gài niàn hěn yǒu dào lǐ。","meaning":"The concept of saturation marketing makes perfect sense.","meaningThai":"แนวคิดเรื่องการตลาดแบบอิ่มตัวนั้นสมเหตุสมผลอย่างยิ่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-246","chinese":"到期","pinyin":"dàoqī","meaning":"to fall due (loan etc); to expire (visa etc); to mature (investment bond etc)","meaningThai":"วุฒิภาวะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"贷款的最后一期付款下个星期到期。","pinyin":"Dài kuǎn de zuì hòu yī qī fù kuǎn xià gè xīng qī dào qī。","meaning":"The final instalment on the loan is due next week.","meaningThai":"งวดสุดท้ายของเงินกู้จะครบกำหนดในสัปดาห์หน้า"},{"chinese":"你的驾照什么时候到期？","pinyin":"Nǐ de jià zhào shí mó shí hòu dào qī？","meaning":"When does your driving licence expire?","meaningThai":"ใบขับขี่ของคุณจะหมดอายุเมื่อใด?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-247","chinese":"导演","pinyin":"dǎoyǎn","meaning":"to direct; director (film etc)","meaningThai":"ผู้อำนวยการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“停！”导演叫道。“太好了！”","pinyin":"“ tíng！” dǎo yǎn jiào dào。“ tài hǎo le！”","meaning":"\"Cut!\" the director yelled. \"That was perfect.\"","meaningThai":"\"ตัด!\" ผู้กำกับตะโกน \"นั่นสมบูรณ์แบบ\""},{"chinese":"导演反对按审查员的指令作删剪。","pinyin":"Dǎo yǎn fǎn duì àn shěn chá yuán de zhǐ líng zuò shān jiǎn。","meaning":"The director objected to the cuts ordered by the censor.","meaningThai":"ผู้อำนวยการคัดค้านการตัดคำสั่งจากเซ็นเซอร์"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-248","chinese":"导致","pinyin":"dǎozhì","meaning":"to lead to; to create; to cause; to bring about","meaningThai":"นำไปสู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"污秽导致疾病。","pinyin":"Wū huì dǎo zhì jí bìng。","meaning":"Filth breeds illnesses.","meaningThai":"ความสกปรกทำให้เกิดโรคภัยไข้เจ็บ"},{"chinese":"疫苗不会导致自闭症。","pinyin":"Yì miáo bù huì dǎo zhì zì bì zhèng。","meaning":"Vaccines don't cause autism.","meaningThai":"วัคซีนไม่ทำให้เกิดออทิสติก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-249","chinese":"大批","pinyin":"dàpī","meaning":"large quantities of","meaningThai":"ในปริมาณมาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这部影片吸引着大批观众。","pinyin":"Zhè bù yǐng piàn xī yǐn zháo dà pī guān zhòng。","meaning":"The movie is drawing large audiences.","meaningThai":"ภาพยนตร์เรื่องนี้ดึงดูดผู้ชมจำนวนมาก"},{"chinese":"这家工厂正大批裁员。","pinyin":"Zhè jiā gōng chǎng zhèng dà pī cái yuán。","meaning":"The factory is shedding a large number of jobs.","meaningThai":"โรงงานกำลังปลดพนักงานจำนวนมาก"}],"partOfSpeech":["numeral"]},
  {"id":"hsk5-250","chinese":"打破","pinyin":"dǎpò","meaning":"to break; to smash","meaningThai":"บุกเข้ามา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他打破玻璃，从窗口摔了出去。","pinyin":"Tā dǎ pò bō lí， cóng chuāng kǒu shuāi le chū qù。","meaning":"He fell through the window, breaking the glass.","meaningThai":"เขาตกลงไปทางหน้าต่างจนกระจกแตก"},{"chinese":"这部影片打破了所有的票房纪录。","pinyin":"Zhè bù yǐng piàn dǎ pò le suǒ yǒu de piào fáng jì lù。","meaning":"The movie broke all box-office records.","meaningThai":"ภาพยนตร์เรื่องนี้ทำลายสถิติบ็อกซ์ออฟฟิศทั้งหมด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-251","chinese":"大厦","pinyin":"dàshà","meaning":"(used in the names of grand buildings such as 百老汇大厦 Broadway Mansions (in Shanghai) or 帝国大厦 Empire State Building etc)","meaningThai":"ตึกใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"商业大厦。","pinyin":"Shang ye da sha.","meaning":"Commercial building.","meaningThai":"อาคารพาณิชย์."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-252","chinese":"大事","pinyin":"dàshì","meaning":"major event; major political event (war or change of regime); major social event (wedding or funeral); (do sth) in a big way","meaningThai":"เหตุการณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那次选举是2004年的主要大事。","pinyin":"Nà cì xuǎn jǔ shì 2004 nián de zhǔ yào dà shì。","meaning":"The election was the main event of 2004.","meaningThai":"การเลือกตั้งเป็นเหตุการณ์หลักของปี 2547"},{"chinese":"这或许是要有大事的苗头。","pinyin":"Zhè huò xǔ shì yào yǒu dà shì de miáo tóu。","meaning":"This could be the start of something big.","meaningThai":"นี่อาจเป็นจุดเริ่มต้นของสิ่งที่ยิ่งใหญ่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-253","chinese":"打听","pinyin":"dǎting","meaning":"to ask about; to make some inquiries; to ask around","meaningThai":"สอบถามเกี่ยวกับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"记者经常纠缠着打听她的私生活。","pinyin":"Jì zhě jīng cháng jiū chán zháo dǎ tīng tā de sī shēng huó。","meaning":"Reporters constantly badger her about her private life.","meaningThai":"ผู้สื่อข่าวคอยตะคอกเธอเกี่ยวกับชีวิตส่วนตัวของเธออยู่ตลอดเวลา"},{"chinese":"他给他们打了几次电话打听就业的可能性。","pinyin":"Tā gěi tā mén dǎ le jī cì diàn huà dǎ tīng jiù yè de kě néng xìng。","meaning":"He called them several times to inquire about job possibilities.","meaningThai":"เขาโทรหาพวกเขาหลายครั้งเพื่อสอบถามเกี่ยวกับความเป็นไปได้ในการทำงาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-254","chinese":"大象","pinyin":"dàxiàng","meaning":"elephant","meaningThai":"ช้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"大象是最大的陆地动物。","pinyin":"Dà xiàng shì zuì dà de lù dì dòng wù.","meaning":"Elephants are the largest land animals.","meaningThai":"ช้างเป็นสัตว์บกที่ใหญ่ที่สุด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-255","chinese":"大型","pinyin":"dàxíng","meaning":"large; large-scale","meaningThai":"ใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这块地承受不住大型建筑的压力。","pinyin":"Zhè kuài dì chéng shòu bù zhù dà xíng jiàn zhù de yā lì。","meaning":"The ground here cannot take the strain of a large building.","meaningThai":"พื้นดินที่นี่ไม่สามารถรับน้ำหนักของอาคารขนาดใหญ่ได้"},{"chinese":"小商店被大型的连锁店抢了生意。","pinyin":"Xiǎo shāng diàn bèi dà xíng de lián suǒ diàn qiāng le shēng yì。","meaning":"Small businesses are losing out to the large chains.","meaningThai":"ธุรกิจขนาดเล็กกำลังสูญเสียเครือข่ายขนาดใหญ่"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-256","chinese":"大爷","pinyin":"dàye","meaning":"arrogant idler; self-centered show-off","meaningThai":"ลุง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"听说张大爷心脏病犯了，唐大夫心急如火立即赶去抢救。","pinyin":"Tīng shuō zhāng dà yé xīn zāng bìng fàn le， táng dà fū xīn jí rú huǒ lì jí gǎn qù qiāng jiù。","meaning":"Hearing of Uncle Zhang's heart attack, Doctor Tang was extremely worried and rushed to his bedside immediately.","meaningThai":"เมื่อได้ยินเรื่องหัวใจวายของลุงจาง หมอถังก็กังวลอย่างมากและรีบไปข้างเตียงทันที"},{"chinese":"然后我们可以把这个表寄给乔大爷。","pinyin":"Rán hòu wǒ mén kě yǐ bǎ zhè gè biǎo jì gěi qiáo dà yé。","meaning":"Then we can send it to Steve.","meaningThai":"จากนั้นเราก็ส่งมันให้สตีฟได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-257","chinese":"大于","pinyin":"dàyú","meaning":"greater than; bigger than; more than","meaningThai":"มากกว่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们遭遇扒窃的危险大于遭受枪击。","pinyin":"Tā mén zāo yù bā qiè de wēi xiǎn dà yú zāo shòu qiāng jī。","meaning":"They were more in danger of having their pockets picked than being shot at.","meaningThai":"พวกเขาเสี่ยงต่อการถูกล้วงกระเป๋ามากกว่าถูกยิง"},{"chinese":"美国人上大学的比例大于英国。","pinyin":"Měi guó rén shàng dà xué de bǐ lì dà yú yīng guó。","meaning":"A higher proportion of Americans go on to higher education than is the case in Britain.","meaningThai":"สัดส่วนของชาวอเมริกันเข้าเรียนต่อในระดับอุดมศึกษาสูงกว่าในอังกฤษ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-258","chinese":"大众","pinyin":"dàzhòng","meaning":"Volkswagen (automobile manufacturer)","meaningThai":"สาธารณะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我只是个大众脸。","pinyin":"Wǒ zhī shì gè dà zhòng liǎn。","meaning":"I'm just another man.","meaningThai":"ฉันก็แค่ผู้ชายอีกคน"},{"chinese":"夏威夷是一个大众化旅游圣地。","pinyin":"Xià wēi yí shì yī gè dà zhòng huà lǚ yóu shèng dì。","meaning":"Hawaii is a popular tourist resort.","meaningThai":"ฮาวายเป็นรีสอร์ทท่องเที่ยวยอดนิยม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-259","chinese":"登","pinyin":"dēng","meaning":"to scale (a height); to ascend; to mount; to publish or record; to enter (e.g. in a register); to press down with the foot; to step or tread on; to put on (shoes or trousers) (dialect); to be gathered and taken to the threshing ground (old)","meaningThai":"กระดาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"登那座山真把我累得筋疲力尽。","pinyin":"Dēng nà zuò shān zhēn bǎ wǒ léi dé jīn pí lì jìn。","meaning":"Climbing that hill really finished me off.","meaningThai":"การปีนเนินเขานั้นทำให้ฉันหมดแรงจริงๆ"},{"chinese":"表露自己的感情这点可不像戈登。","pinyin":"Biǎo lòu zì jǐ de gǎn qíng zhè diǎn kě bù xiàng gē dēng。","meaning":"It was unlike Gordon to display his feelings.","meaningThai":"มันไม่เหมือนกับกอร์ดอนที่จะแสดงความรู้สึกของเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-260","chinese":"等待","pinyin":"děngdài","meaning":"to wait; to wait for","meaningThai":"รอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们坐着，焦急地等待电影开演。","pinyin":"Wǒ mén zuò zháo， jiāo jí dì děng dài diàn yǐng kāi yǎn。","meaning":"We sat waiting impatiently for the movie to start.","meaningThai":"เรานั่งรออย่างใจจดใจจ่อเพื่อให้หนังเริ่มฉาย"},{"chinese":"到这种时刻，我们只好等待了。","pinyin":"Dào zhè zhǒng shí kè， wǒ mén zhī hǎo děng dài le。","meaning":"At this point in time we just have to wait.","meaningThai":"ในเวลานี้เราก็แค่ต้องรอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-261","chinese":"灯光","pinyin":"dēngguāng","meaning":"(stage) lighting; light","meaningThai":"แสงสว่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他负责全部舞台道具和灯光。","pinyin":"Tā fù zé quán bù wǔ tái dào jù hé dēng guāng。","meaning":"He is responsible for all the stage props and lighting.","meaningThai":"เขารับผิดชอบอุปกรณ์ประกอบฉากและแสงบนเวทีทั้งหมด"},{"chinese":"灯光暗淡，弥漫着浪漫情调。","pinyin":"Dēng guāng àn dàn， mí màn zháo làng màn qíng tiáo。","meaning":"The lights were low and romance was in the air.","meaningThai":"แสงไฟสลัวและความโรแมนติคอยู่ในอากาศ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-262","chinese":"等候","pinyin":"děnghòu","meaning":"to wait; to wait for","meaningThai":"คอย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"等候通知。","pinyin":"Deng hou tong zhi.","meaning":"Await notification.","meaningThai":"รอการแจ้งเตือน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-263","chinese":"登记","pinyin":"dēngjì","meaning":"to register (one's name)","meaningThai":"ลงทะเบียน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们在登记房间。","pinyin":"Tā mén zài dēng jì fáng jiān。","meaning":"They are registering the room.","meaningThai":"พวกเขากำลังลงทะเบียนห้อง"},{"chinese":"先生，请出示护照或者身份证，让我登记一下。","pinyin":"Xiān shēng， qǐng chū shì hù zhào huò zhě shēn fèn zhèng， ràng wǒ dēng jì yī xià。","meaning":"Sir, please present your passport or identity card, so I can register it.","meaningThai":"ท่านโปรดแสดงหนังสือเดินทางหรือบัตรประจำตัวของคุณเพื่อให้ฉันสามารถลงทะเบียนได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-264","chinese":"登录","pinyin":"dēnglù","meaning":"to register; to log in","meaningThai":"เข้าสู่ระบบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"顾客们花钱登录，与其他用户闲聊。","pinyin":"Gù kè mén huā qián dēng lù， yǔ qí tā yòng hù xián liáo。","meaning":"Customers pay to log on and gossip with other users.","meaningThai":"ลูกค้าจ่ายเงินเพื่อเข้าสู่ระบบและนินทากับผู้ใช้รายอื่น"},{"chinese":"这个系统无法让你登录。","pinyin":"Zhè gè xì tǒng wú fǎ ràng nǐ dēng lù。","meaning":"The system is unable to log you on.","meaningThai":"ระบบไม่สามารถเข้าสู่ระบบของคุณได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-265","chinese":"等于","pinyin":"děngyú","meaning":"to equal; to be tantamount to","meaningThai":"เท่ากัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"一单位酒精等于半品脱啤酒。","pinyin":"Yī dān wèi jiǔ jīng děng yú bàn pǐn tuō pí jiǔ。","meaning":"One unit of alcohol is equal to half a pint of beer.","meaningThai":"แอลกอฮอล์หนึ่งหน่วยเท่ากับเบียร์ครึ่งไพน์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-266","chinese":"递","pinyin":"dì","meaning":"to hand over; to pass on; to deliver; (bound form) progressively; in the proper order","meaningThai":"ส่งมอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我感激地接过她递来的一杯咖啡。","pinyin":"Wǒ gǎn jī dì jiē guò tā dì lái de yī bēi kā fēi。","meaning":"I gratefully took the cup of coffee she offered me.","meaningThai":"ฉันรับแก้วกาแฟที่เธอให้ฉันมาด้วยความขอบคุณ"},{"chinese":"兰尼吞下胶囊，把玻璃杯递还给特兰卡斯先生。","pinyin":"Lán ní tūn xià jiāo náng， bǎ bō lí bēi dì huán gěi tè lán kǎ sī xiān shēng。","meaning":"Lenny swallowed the caplets and handed the glass back to Mr. Trancas.","meaningThai":"เลนนี่กลืนแคปเล็ตแล้วส่งแก้วคืนให้มิสเตอร์ทรานกัส"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-267","chinese":"电池","pinyin":"diànchí","meaning":"battery","meaningThai":"แบตเตอรี่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"换电池。","pinyin":"Huan dian chi.","meaning":"Change the battery.","meaningThai":"เปลี่ยนแบตเตอรี่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-268","chinese":"电动","pinyin":"diàndòng","meaning":"electric-powered; (Tw) video game","meaningThai":"ไฟฟ้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"医院里使用的雾化器应该是电动的。","pinyin":"Yī yuàn lǐ shǐ yòng de wù huà qì yīng gāi shì diàn dòng de。","meaning":"Vaporizers for use in hospitals should be electric.","meaningThai":"เครื่องพ่นไอน้ำสำหรับใช้ในโรงพยาบาลควรใช้ไฟฟ้า"},{"chinese":"电动汽车仍然是一种新鲜玩意儿。","pinyin":"Diàn dòng qì chē réng rán shì yī zhǒng xīn xiān wán yì ér。","meaning":"Electric-powered cars are still something of a novelty.","meaningThai":"รถยนต์ไฟฟ้ายังคงเป็นสิ่งแปลกใหม่"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-269","chinese":"电器","pinyin":"diànqì","meaning":"(electrical) appliance; device","meaningThai":"เครื่องใช้ไฟฟ้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"家用电器。","pinyin":"Jia yong dian qi.","meaning":"Household appliances.","meaningThai":"เครื่องใช้ในครัวเรือน."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-270","chinese":"电商","pinyin":"diànshāng","meaning":"E-commerce","meaningThai":"อีคอมเมิร์ซ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"互联网的快速发展创造了电商的繁荣。","pinyin":"Hù lián wǎng de kuài sù fā zhǎn chuàng zào le diàn shāng de fán róng。","meaning":"The rapid development of the Internet has created a boom in e-commerce.","meaningThai":"การพัฒนาอย่างรวดเร็วของอินเทอร์เน็ตทำให้เกิดความเจริญรุ่งเรืองในอีคอมเมิร์ซ"},{"chinese":"电商平台的未来将是标准品或者近似标准品的非标品的天下。","pinyin":"Diàn shāng píng tái de wèi lái jiāng shì biāo zhǔn pǐn huò zhě jìn sì biāo zhǔn pǐn de fēi biāo pǐn de tiān xià。","meaning":"Electric business platform of the future will be standard or similar standard of non-standard products.","meaningThai":"แพลตฟอร์มธุรกิจไฟฟ้าแห่งอนาคตจะเป็นมาตรฐานหรือมาตรฐานที่คล้ายกันของผลิตภัณฑ์ที่ไม่ได้มาตรฐาน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-271","chinese":"电视台","pinyin":"diànshìtái","meaning":"television station","meaningThai":"สถานีโทรทัศน์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"电视台正在播足球赛。","pinyin":"Diàn shì tái zhèng zài bō zú qiú sài。","meaning":"The football game is now on the air.","meaningThai":"เกมฟุตบอลกำลังออนแอร์แล้ว"},{"chinese":"现在电视台正在播放足球赛。","pinyin":"Xiàn zài diàn shì tái zhèng zài bō fàng zú qiú sài。","meaning":"The football game is now on the air.","meaningThai":"เกมฟุตบอลกำลังออนแอร์แล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-272","chinese":"点心","pinyin":"diǎnxin","meaning":"light refreshments; pastry; dim sum (in Cantonese cooking); dessert","meaningThai":"ติ่มซำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"吃点心。","pinyin":"Chi dian xin.","meaning":"Eat dim sum.","meaningThai":"กินติ่มซำ."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-273","chinese":"点赞","pinyin":"diǎnzàn","meaning":"Like","meaningThai":"ชอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个消息太激动人心了！我们为他点赞吧！","pinyin":"Zhè gè xiāo xī tài jī dòng rén xīn le！ wǒ mén wéi tā diǎn zàn bā！","meaning":"What exciting news it is! Let's give him the thumbs-up!","meaningThai":"เป็นข่าวที่น่าตื่นเต้นอะไรเช่นนี้! ยกนิ้วให้เขากันเถอะ!"},{"chinese":"后来，我们把照片发到微博或者微信上，等着被点赞。","pinyin":"Hòu lái， wǒ mén bǎ zhào piàn fā dào wēi bó huò zhě wēi xìn shàng， děng zháo bèi diǎn zàn。","meaning":"Later, we post the photos onto Weibo or Wechat, waiting to be \"liked\".","meaningThai":"ต่อมาเราก็โพสต์รูปลงใน Weibo หรือ Wechat เพื่อรอการ \"ถูกใจ\""}],"partOfSpeech":["verb"]},
  {"id":"hsk5-274","chinese":"电子版","pinyin":"diànzǐbǎn","meaning":"electronic edition; digital version","meaningThai":"รุ่นอิเล็กทรอนิกส์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"本词典有电子版。","pinyin":"Běn cí diǎn yǒu diàn zǐ bǎn。","meaning":"This dictionary is available in electronic form.","meaningThai":"พจนานุกรมนี้มีให้ในรูปแบบอิเล็กทรอนิกส์"},{"chinese":"我想你可以给我发一份电子版。","pinyin":"Wǒ xiǎng nǐ kě yǐ gěi wǒ fā yī fèn diàn zǐ bǎn。","meaning":"I suppose you could send me an E-copy.","meaningThai":"ฉันคิดว่าคุณสามารถส่ง E-copy มาให้ฉันได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-275","chinese":"调","pinyin":"diào","meaning":"to transfer; to move (troops or cadres); to investigate; to enquire into; accent; view; argument; key (in music); mode (music); tune; tone; melody","meaningThai":"ปรับแต่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"补偿可由调税实现。","pinyin":"Bǔ cháng kě yóu tiáo shuì shí xiàn。","meaning":"Compensation could be made by adjustments to taxation.","meaningThai":"การชดเชยสามารถทำได้โดยการปรับภาษี"},{"chinese":"我们也许要将这个数字往上调一调。","pinyin":"Wǒ mén yě xǔ yào jiāng zhè gè shù zì wǎng shàng tiáo yī tiáo。","meaning":"We may have to revise this figure upwards.","meaningThai":"เราอาจจะต้องแก้ไขตัวเลขนี้ขึ้นไป"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-276","chinese":"调研","pinyin":"diàoyán","meaning":"to investigate and research; research; investigation","meaningThai":"วิจัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"市场调研公司BMRB为此项目采用了12个焦点组。","pinyin":"Shì cháng tiáo yán gōng sī BMRB wéi cǐ xiàng mù cǎi yòng le 12 gè jiāo diǎn zǔ。","meaning":"The market research company BMRB conducted 12 focus groups for the project.","meaningThai":"บริษัทวิจัยตลาด BMRB ได้จัดการสนทนากลุ่ม 12 กลุ่มสำหรับโครงการนี้"},{"chinese":"他读完一份市场调研报告后，10秒钟就做出了决定。","pinyin":"Tā dú wán yī fèn shì cháng tiáo yán bào gào hòu，10 miǎo zhōng jiù zuò chū le jué dìng。","meaning":"The decision had taken about 10 seconds once he'd read a market research study.","meaningThai":"การตัดสินใจใช้เวลาประมาณ 10 วินาทีเมื่อเขาอ่านการศึกษาวิจัยตลาด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-277","chinese":"地理","pinyin":"dìlǐ","meaning":"geography","meaningThai":"ภูมิศาสตร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"地理课学习世界各国的位置。","pinyin":"Dì lǐ kè xué xí shì jiè gè guó de wèi zhì.","meaning":"Geography class learns the locations of countries.","meaningThai":"ชั้นเรียนภูมิศาสตร์เรียนรู้สถานที่ตั้งของประเทศต่างๆ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-278","chinese":"地面","pinyin":"dìmiàn","meaning":"floor; ground; surface","meaningThai":"พื้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"多石陡峭的地面很容易排水。","pinyin":"Duō shí dǒu qiào de dì miàn hěn róng yì pái shuǐ。","meaning":"The steep, stony ground is well drained.","meaningThai":"พื้นหินสูงชันระบายน้ำได้ดี"},{"chinese":"该路外面的地面陡然下降。","pinyin":"Gāi lù wài miàn de dì miàn dǒu rán xià jiàng。","meaning":"The ground beyond the road fell away precipitously.","meaningThai":"พื้นดินที่อยู่นอกถนนก็ตกลงไปอย่างตกตะลึง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-279","chinese":"定期","pinyin":"dìngqī","meaning":"at set dates; at regular intervals; periodic; limited to a fixed period of time; fixed term","meaningThai":"ปกติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"定期检查机油，经常保养汽车。","pinyin":"Dìng qī jiǎn chá jī yóu， jīng cháng bǎo yǎng qì chē。","meaning":"Check the oil at regular intervals, and have the car serviced regularly.","meaningThai":"ตรวจสอบน้ำมันเครื่องเป็นระยะ และนำรถเข้ารับบริการอย่างสม่ำเสมอ"},{"chinese":"我们的记录定期更新。","pinyin":"Wǒ mén de jì lù dìng qī gēng xīn。","meaning":"Our records are regularly updated.","meaningThai":"บันทึกของเราได้รับการปรับปรุงอย่างสม่ำเสมอ"}],"partOfSpeech":["adverb","adjective"]},
  {"id":"hsk5-280","chinese":"地区","pinyin":"dìqū","meaning":"local; regional; district (not necessarily formal administrative unit); region; area; as suffix to city name, means prefecture or county (area administered by a prefecture-level city or, county-level city)","meaningThai":"พื้นที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个地区吸引大批游人。","pinyin":"Zhè gè dì qū xī yǐn dà pī yóu rén。","meaning":"The region attracts tourists in their multitudes.","meaningThai":"ภูมิภาคนี้ดึงดูดนักท่องเที่ยวจำนวนมาก"},{"chinese":"约翰是伦敦地区经理。","pinyin":"Yuē hàn shì lún dūn dì qū jīng lǐ。","meaning":"John is the London area manager.","meaningThai":"จอห์นเป็นผู้จัดการพื้นที่ลอนดอน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-281","chinese":"的确","pinyin":"díquè","meaning":"really; indeed","meaningThai":"อย่างแท้จริง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的确显得很疲倦。","pinyin":"Tā de què xiǎn dé hěn pí juàn。","meaning":"He does look tired.","meaningThai":"เขาดูเหนื่อยนะ."},{"chinese":"她的确是网球高手。","pinyin":"Tā de què shì wǎng qiú gāo shǒu。","meaning":"She's really hot stuff at tennis.","meaningThai":"เธอเป็นคนที่ร้อนแรงจริงๆในกีฬาเทนนิส"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-282","chinese":"敌人","pinyin":"dírén","meaning":"enemy","meaningThai":"ศัตรู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个国家正在备战迎击敌人。","pinyin":"Zhè gè guó jiā zhèng zài bèi zhàn yíng jī dí rén。","meaning":"The country was arming against the enemy.","meaningThai":"ประเทศกำลังติดอาวุธต่อต้านศัตรู"},{"chinese":"他们联手对付共同的敌人。","pinyin":"Tā mén lián shǒu duì fù gòng tóng de dí rén。","meaning":"They combined against a common enemy.","meaningThai":"พวกเขารวมตัวกันต่อต้านศัตรูร่วมกัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-283","chinese":"低头","pinyin":"dītóu","meaning":"to bow the head; to yield; to give in","meaningThai":"ก้มหัวของคุณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她当时站在我床边低头凝视着我。","pinyin":"Tā dāng shí zhàn zài wǒ chuáng biān dī tóu níng shì zháo wǒ。","meaning":"She was standing beside my bed staring down at me.","meaningThai":"เธอยืนอยู่ข้างเตียงของฉันและจ้องมองมาที่ฉัน"},{"chinese":"他痛苦地低头看着自己的盘子。","pinyin":"Tā tòng kǔ dì dī tóu kàn zháo zì jǐ de pán zǐ。","meaning":"He looked miserably down at his plate.","meaningThai":"เขาก้มมองจานอย่างเศร้าสร้อย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-284","chinese":"丢失","pinyin":"diūshī","meaning":"to lose; to misplace","meaningThai":"สูญหาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"如有丢失或损坏，将由你个人负责。","pinyin":"Rú yǒu diū shī huò sǔn huài， jiāng yóu nǐ gè rén fù zé。","meaning":"You will be held personally responsible for any loss or breakage.","meaningThai":"คุณจะต้องรับผิดชอบเป็นการส่วนตัวต่อการสูญเสียหรือการแตกหัก"},{"chinese":"他们仍然希望找到他们丢失的儿子。","pinyin":"Tā mén réng rán xī wàng zhǎo dào tā mén diū shī de ér zǐ。","meaning":"They still hoped to find their missing son.","meaningThai":"พวกเขายังคงหวังว่าจะพบลูกชายที่หายไป"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-285","chinese":"地位","pinyin":"dìwèi","meaning":"position; status; place","meaningThai":"สถานะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有地位者自有特权。","pinyin":"Yǒu dì wèi zhě zì yǒu tè quán。","meaning":"Those in authority were in a privileged position.","meaningThai":"ผู้มีอำนาจอยู่ในตำแหน่งพิเศษ"},{"chinese":"培训被摆在了非常次要的地位。","pinyin":"Péi xùn bèi bǎi zài le fēi cháng cì yào de dì wèi。","meaning":"Training was given a very low priority.","meaningThai":"การฝึกอบรมได้รับความสำคัญต่ำมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-286","chinese":"地下","pinyin":"dìxià","meaning":"underground; subterranean; covert","meaningThai":"ใต้ดิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"矿工被困在地下深处。","pinyin":"Kuàng gōng bèi kùn zài dì xià shēn chǔ。","meaning":"The miners were trapped deep underground.","meaningThai":"คนงานเหมืองถูกขังอยู่ใต้ดินลึก"},{"chinese":"她轻盈地下楼来迎接我们。","pinyin":"Tā qīng yíng dì xià lóu lái yíng jiē wǒ mén。","meaning":"She floated down the steps to greet us.","meaningThai":"เธอลอยลงบันไดมาทักทายเรา"}],"partOfSpeech":["other"]},
  {"id":"hsk5-287","chinese":"地震","pinyin":"dìzhèn","meaning":"earthquake","meaningThai":"แผ่นดินไหว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"发生了地震。","pinyin":"Fa sheng le di zhen.","meaning":"An earthquake occurred.","meaningThai":"เกิดเหตุแผ่นดินไหว."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-288","chinese":"冻","pinyin":"dòng","meaning":"to freeze; to feel very cold; aspic or jelly","meaningThai":"แช่แข็ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"冻鱼是一种非常健康的方便食品。","pinyin":"Dòng yú shì yī zhǒng fēi cháng jiàn kāng de fāng biàn shí pǐn。","meaning":"Frozen fish is a very healthy convenience food.","meaningThai":"ปลาแช่แข็งเป็นอาหารสะดวกซื้อที่ดีต่อสุขภาพมาก"},{"chinese":"水管已经冻了，我们接不到水。","pinyin":"Shuǐ guǎn yǐ jīng dòng le， wǒ mén jiē bù dào shuǐ。","meaning":"The pipes have frozen, so we've got no water.","meaningThai":"ท่อกลายเป็นน้ำแข็ง เราเลยไม่มีน้ำ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-289","chinese":"洞","pinyin":"dòng","meaning":"cave; hole; zero (unambiguous spoken form when spelling out numbers)","meaningThai":"รู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"球滚进了洞，她赢了。","pinyin":"Qiú gǔn jìn le dòng， tā yíng le。","meaning":"The ball rolled into the hole and she had won.","meaningThai":"บอลกลิ้งลงหลุมแล้วเธอก็ชนะ"},{"chinese":"香烟把地毯烧了个洞。","pinyin":"Xiāng yān bǎ dì tǎn shāo le gè dòng。","meaning":"The cigarette burned a hole in the carpet.","meaningThai":"บุหรี่ไหม้เป็นรูบนพรม"}],"partOfSpeech":["noun","other"]},
  {"id":"hsk5-290","chinese":"动画","pinyin":"dònghuà","meaning":"animation; cartoon","meaningThai":"แอนิเมชั่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这部动画片达到了风靡一时的地步。","pinyin":"Zhè bù dòng huà piàn dá dào le fēng mí yī shí de dì bù。","meaning":"The cartoon has achieved cult status.","meaningThai":"การ์ตูนได้รับสถานะลัทธิ"},{"chinese":"这些电影是动画和情节长片的混合体。","pinyin":"Zhè xiē diàn yǐng shì dòng huà hé qíng jié cháng piàn de hùn hé tǐ。","meaning":"The films are a mix of animation and full-length features.","meaningThai":"ภาพยนตร์เรื่องนี้ผสมผสานระหว่างแอนิเมชั่นและเรื่องยาว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-291","chinese":"动人","pinyin":"dòngrén","meaning":"touching; moving","meaningThai":"การย้าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"音乐沉闷枯燥毫不动人，表演也是。","pinyin":"Yīn lè chén mèn kū zào háo bù dòng rén， biǎo yǎn yě shì。","meaning":"The music is dull and uninspiring, and the same is true of the acting.","meaningThai":"ดนตรีน่าเบื่อและไม่น่าดึงดูด และการแสดงก็เช่นเดียวกัน"},{"chinese":"几乎13％的劳动人口已经失业。","pinyin":"Jī hū 13％ de láo dòng rén kǒu yǐ jīng shī yè。","meaning":"Almost 13 percent of the working population is already unemployed.","meaningThai":"เกือบร้อยละ 13 ของประชากรวัยทำงานไม่มีงานทำแล้ว"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-292","chinese":"动手","pinyin":"dòngshǒu","meaning":"to set about (a task); to hit; to punch; to touch","meaningThai":"ดำเนินการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他没提到是他先动手打人的。","pinyin":"Tā méi tí dào shì tā xiān dòng shǒu dǎ rén de。","meaning":"He failed to mention that he was the one who started the fight.","meaningThai":"เขาลืมบอกไปเลยว่าเขาคือคนที่เริ่มการต่อสู้"},{"chinese":"我拼命地来回摇动手柄。","pinyin":"Wǒ pīn mìng dì lái huí yáo dòng shǒu bǐng。","meaning":"I pumped the handle like crazy.","meaningThai":"ฉันปั๊มที่จับอย่างบ้าคลั่ง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-293","chinese":"豆腐","pinyin":"dòufu","meaning":"tofu; bean curd","meaningThai":"เต้าหู้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"麻婆豆腐很好吃。","pinyin":"Má pó dòu fu hěn hǎo chī.","meaning":"Mapo tofu is delicious.","meaningThai":"เต้าหู้มาโปก็อร่อย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-294","chinese":"豆浆","pinyin":"dòujiāng","meaning":"soy milk","meaningThai":"นมถั่วเหลือง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我早餐喝了些豆浆。","pinyin":"Wǒ zǎo cān hē le xiē dòu jiāng。","meaning":"I had some soybean milk for breakfast.","meaningThai":"ฉันกินนมถั่วเหลืองเป็นอาหารเช้า"},{"chinese":"典型的饭菜包括甜酱萝卜糕，鸡蛋煎饼和豆浆。","pinyin":"Diǎn xíng de fàn cài bāo kuò tián jiàng luó bǔ gāo， jī dàn jiān bǐng hé dòu jiāng。","meaning":"Typical fare includes fried radish cake with a sweetish sauce, egg pancakes and soybean milk.","meaningThai":"อาหารทั่วไป ได้แก่ เค้กหัวไชเท้าทอดพร้อมซอสหวาน แพนเค้กไข่ และนมถั่วเหลือง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-295","chinese":"度","pinyin":"dù","meaning":"to pass; to spend (time); measure; limit; extent; degree of intensity; degree (angles, temperature etc); kilowatt-hour; classifier for events and occurrences","meaningThai":"ใช้จ่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"气温慢慢升至刚过40度。","pinyin":"Qì wēn màn màn shēng zhì gāng guò 40 dù。","meaning":"The temperature crept up to just above 40 degrees.","meaningThai":"อุณหภูมิพุ่งสูงถึง 40 องศาเลยทีเดียว"},{"chinese":"温度在30度至零下20度之间变化。","pinyin":"Wēn dù zài 30 dù zhì líng xià 20 dù zhī jiān biàn huà。","meaning":"The temperature varies from 30 degrees to minus 20.","meaningThai":"อุณหภูมิแตกต่างกันไปตั้งแต่ 30 องศาถึงลบ 20"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-296","chinese":"堵","pinyin":"dǔ","meaning":"to block up (a road, pipe etc); to stop up (a hole); (fig.) (of a person) choked up with anxiety or stress; wall (literary); (classifier for walls)","meaningThai":"ปิดกั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这条路被堵了—你们得开车绕着走了。","pinyin":"Zhè tiáo lù bèi dǔ le — nǐ mén dé kāi chē rào zháo zǒu le。","meaning":"The road's blocked—you'll have to drive the long way round.","meaningThai":"ถนนถูกปิดกั้น คุณจะต้องขับรถเป็นระยะทางไกล"},{"chinese":"她开上自家车道，不料发现路已被堵。","pinyin":"Tā kāi shàng zì jiā chē dào， bù liào fā xiàn lù yǐ bèi dǔ。","meaning":"She turned up the driveway, only to find her way blocked.","meaningThai":"เธอเลี้ยวรถไปแต่กลับพบว่าถูกขวางทาง"}],"partOfSpeech":["verb","measure word"]},
  {"id":"hsk5-297","chinese":"断","pinyin":"duàn","meaning":"to break; to snap; to cut off; to give up or abstain from sth; to judge; (usu. used in the negative) absolutely; definitely; decidedly","meaningThai":"หยุดพัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这艘船撞上了恶名远扬的斯戈尔尖岬暗礁群，断为三截。","pinyin":"Zhè sōu chuán zhuàng shàng le è míng yuǎn yáng de sī gē ěr jiān jiǎ àn jiāo qún， duàn wéi sān jié。","meaning":"The ship crashed into the infamous Sker Point rocks and broke into three pieces.","meaningThai":"เรือชนเข้ากับหิน Sker Point ที่น่าอับอายและแตกออกเป็นสามชิ้น"},{"chinese":"我们永远不能告诉那可怜的孩子它是怎么断的。","pinyin":"Wǒ mén yǒng yuǎn bù néng gào sù nà kě lián de hái zǐ tā shì zěn mó duàn de。","meaning":"We couldn't never tell him how it broke, poor lad.","meaningThai":"เราไม่สามารถบอกเขาได้เลยว่ามันพังยังไง เจ้าเด็กน่าสงสาร"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-298","chinese":"短处","pinyin":"duǎnchù","meaning":"shortcoming; defect; fault; one's weak points","meaningThai":"ข้อเสีย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他承认自己的短处。","pinyin":"Tā chéng rèn zì jǐ de duǎn chǔ。","meaning":"He admitted his weakness.","meaningThai":"เขายอมรับความอ่อนแอของเขา"},{"chinese":"他们应该知道自己的长处和短处，做出的选择要扬长避短。","pinyin":"Tā mén yīng gāi zhī dào zì jǐ de cháng chǔ hé duǎn chǔ， zuò chū de xuǎn zé yào yáng cháng bì duǎn。","meaning":"They should know their merits and demerits and their choices must give play to their strengths whilst circumvent weaknesses.","meaningThai":"พวกเขาควรรู้ข้อดีและข้อเสียของตนเอง และทางเลือกของพวกเขาต้องให้ความสำคัญกับจุดแข็งของตนในขณะที่หลีกเลี่ยงจุดอ่อน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-299","chinese":"短期","pinyin":"duǎnqī","meaning":"short term; short-term","meaningThai":"ระยะสั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"短期合同会增加员工的流动率。","pinyin":"Duǎn qī hé tóng huì zēng jiā yuán gōng de liú dòng shuài。","meaning":"Short-term contracts increase staff turnover.","meaningThai":"สัญญาระยะสั้นช่วยเพิ่มการหมุนเวียนของพนักงาน"},{"chinese":"从短期来看，失业率可能降低。","pinyin":"Cóng duǎn qī lái kàn， shī yè shuài kě néng jiàng dī。","meaning":"In the short run, unemployment may fall.","meaningThai":"ในระยะสั้นการว่างงานอาจลดลง"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-300","chinese":"堆","pinyin":"duī","meaning":"to pile up; to heap up; a mass; pile; heap; stack; large amount","meaningThai":"กอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"树叶已经用耙子拢成了一堆。","pinyin":"Shù yè yǐ jīng yòng bà zǐ lǒng chéng le yī duī。","meaning":"The leaves had been raked into a pile.","meaningThai":"ใบไม้ถูกกวาดให้เป็นกอง"},{"chinese":"他把食物猛往自己盘子里堆。","pinyin":"Tā bǎ shí wù měng wǎng zì jǐ pán zǐ lǐ duī。","meaning":"He piled his plate with as much food as he could.","meaningThai":"เขาซ้อนจานด้วยอาหารให้มากที่สุด"}],"partOfSpeech":["measure word","verb","suffix","noun"]},
  {"id":"hsk5-301","chinese":"对比","pinyin":"duìbǐ","meaning":"to contrast; contrast; ratio","meaningThai":"ตัดกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这位艺术家娴熟地运用了明暗对比。","pinyin":"Zhè wèi yì shù jiā xián shú dì yùn yòng le míng àn duì bǐ。","meaning":"The artist's use of contrast is masterly.","meaningThai":"การใช้คอนทราสต์ของศิลปินนั้นเชี่ยวชาญ"},{"chinese":"他的诗歌充满了对立与对比。","pinyin":"Tā de shī gē chōng mǎn le duì lì yǔ duì bǐ。","meaning":"His poetry is full of oppositions and contrasts.","meaningThai":"บทกวีของเขาเต็มไปด้วยความขัดแย้งและความแตกต่าง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-302","chinese":"对待","pinyin":"duìdài","meaning":"to treat; treatment","meaningThai":"รักษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他这样对待我真使我恼火。","pinyin":"Tā zhè yàng duì dài wǒ zhēn shǐ wǒ nǎo huǒ。","meaning":"The way he treats me really burns me up.","meaningThai":"วิธีที่เขาปฏิบัติต่อฉันทำให้ฉันเผาไหม้จริงๆ"},{"chinese":"她对待孩子反复无常。","pinyin":"Tā duì dài hái zǐ fǎn fù wú cháng。","meaning":"She's not very consistent in the way she treats her children.","meaningThai":"เธอปฏิบัติต่อลูกๆ ของเธอไม่สอดคล้องกันมากนัก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-303","chinese":"对手","pinyin":"duìshǒu","meaning":"opponent; rival; competitor; (well-matched) adversary; match","meaningThai":"คู่ต่อสู้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他反正总能设法智胜对手。","pinyin":"Tā fǎn zhèng zǒng néng shè fǎ zhì shèng duì shǒu。","meaning":"Somehow he always manages to outwit his opponents.","meaningThai":"ยังไงก็ตามเขามักจะจัดการเอาชนะคู่ต่อสู้ของเขาได้เสมอ"},{"chinese":"最糟的做法就是低估对手。","pinyin":"Zuì zāo de zuò fǎ jiù shì dī gū duì shǒu。","meaning":"The worst thing you can do is underestimate an opponent.","meaningThai":"สิ่งที่แย่ที่สุดที่คุณสามารถทำได้คือดูถูกคู่ต่อสู้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-304","chinese":"队伍","pinyin":"duìwu","meaning":"ranks; troops; queue; line; procession","meaningThai":"ทีม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"队伍沿着狭窄的街道曲折穿行。","pinyin":"Duì wǔ yán zháo xiá zhǎi de jiē dào qū zhē chuān háng。","meaning":"The procession snaked its way through narrow streets.","meaningThai":"ขบวนแห่เคลื่อนไปตามถนนแคบ ๆ"},{"chinese":"我们的核心队伍已经就位。","pinyin":"Wǒ mén de hé xīn duì wǔ yǐ jīng jiù wèi。","meaning":"We already have our core team in place.","meaningThai":"เรามีทีมงานหลักของเราอยู่แล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-305","chinese":"对象","pinyin":"duìxiàng","meaning":"target; object; partner; boyfriend; girlfriend","meaningThai":"วัตถุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这家公司据传是并购的对象。","pinyin":"Zhè jiā gōng sī jù chuán shì bìng gòu de duì xiàng。","meaning":"The company is rumoured to be a takeover target.","meaningThai":"มีข่าวลือว่าบริษัทจะเป็นเป้าหมายในการเทคโอเวอร์"},{"chinese":"尽可能靠近对象，拿稳相机。","pinyin":"Jìn kě néng kào jìn duì xiàng， ná wěn xiāng jī。","meaning":"Get as close to the subject as you can and hold the camera steady.","meaningThai":"เข้าใกล้วัตถุให้มากที่สุดเท่าที่จะทำได้และถือกล้องให้มั่นคง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-306","chinese":"独立","pinyin":"dúlì","meaning":"independent; independence; to stand alone","meaningThai":"เป็นอิสระ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"莫桑比克于1975年获得独立。","pinyin":"Mò sāng bǐ kè yú 1975 nián huò dé dú lì。","meaning":"Mozambique became independent in 1975.","meaningThai":"โมซัมบิกได้รับเอกราชในปี พ.ศ. 2518"},{"chinese":"他担心丧失自己的独立。","pinyin":"Tā dān xīn sāng shī zì jǐ de dú lì。","meaning":"He was afraid of losing his independence.","meaningThai":"เขากลัวที่จะสูญเสียอิสรภาพของเขา"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-307","chinese":"吨","pinyin":"dūn","meaning":"ton (loanword); Taiwan pr. [dùn]","meaningThai":"ตัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"发电厂每小时喷出了5吨的灰。","pinyin":"Fā diàn chǎng měi xiǎo shí pēn chū le 5 dūn de huī。","meaning":"The power-generation plant belched out five tons of ash an hour.","meaningThai":"โรงไฟฟ้าแห่งนี้พ่นเถ้าถ่านออกมา 5 ตันต่อชั่วโมง"},{"chinese":"最大的石头每块重五吨以上。","pinyin":"Zuì dà de shí tóu měi kuài zhòng wǔ dūn yǐ shàng。","meaning":"The largest stones weigh over five tonnes apiece.","meaningThai":"หินที่ใหญ่ที่สุดมีน้ำหนักมากกว่าห้าตันต่อชิ้น"}],"partOfSpeech":["measure word"]},
  {"id":"hsk5-308","chinese":"朵","pinyin":"duǒ","meaning":"flower; earlobe; fig. item on both sides; classifier for flowers, clouds etc","meaningThai":"ดูโอ้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这株植物开了一朵美丽鲜红的花。","pinyin":"Zhè zhū zhí wù kāi le yī duǒ měi lì xiān hóng de huā。","meaning":"The plant has a beautiful bright red flower.","meaningThai":"พืชมีดอกสีแดงสดสวยงาม"},{"chinese":"一夜之间长出来好几百朵蘑菇。","pinyin":"Yī yè zhī jiān cháng chū lái hǎo jī bǎi duǒ mó gū。","meaning":"Hundreds of mushrooms had sprouted up overnight.","meaningThai":"เห็ดหลายร้อยตัวงอกขึ้นมาในชั่วข้ามคืน"}],"partOfSpeech":["measure word","other"]},
  {"id":"hsk5-309","chinese":"躲","pinyin":"duǒ","meaning":"to hide; to dodge; to avoid","meaningThai":"ซ่อน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她有一种异样的感觉—他在躲着她。","pinyin":"Tā yǒu yī zhǒng yì yàng de gǎn jué — tā zài duǒ zháo tā。","meaning":"She had the oddest feeling that he was avoiding her.","meaningThai":"เธอมีความรู้สึกแปลกที่สุดที่เขากำลังหลีกเลี่ยงเธอ"},{"chinese":"我躲了起来，不能冒险出去。","pinyin":"Wǒ duǒ le qǐ lái， bù néng mào xiǎn chū qù。","meaning":"I stayed hidden; I couldn't chance coming out.","meaningThai":"ฉันซ่อนตัวอยู่ ฉันไม่มีโอกาสได้ออกมา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-310","chinese":"独特","pinyin":"dútè","meaning":"unique; distinctive","meaningThai":"มีเอกลักษณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他用乐器奏出了独特圆浑的音调。","pinyin":"Tā yòng lè qì zòu chū le dú tè yuán hún de yīn tiáo。","meaning":"He draws a unique full sound from the instrument.","meaningThai":"เขาดึงเสียงเต็มอันเป็นเอกลักษณ์จากเครื่องดนตรี"},{"chinese":"此野营地有其自身独特的魅力。","pinyin":"Cǐ yě yíng dì yǒu qí zì shēn dú tè de mèi lì。","meaning":"The wilderness campsite had its own peculiar enchantment.","meaningThai":"ที่ตั้งแคมป์ในถิ่นทุรกันดารมีเสน่ห์ที่แปลกประหลาดในตัวเอง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-311","chinese":"读音","pinyin":"dúyīn","meaning":"pronunciation; literary (rather than colloquial) pronunciation of a Chinese character","meaningThai":"การออกเสียง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"garage的读音不止一种。","pinyin":"Garage de dú yīn bù zhǐ yī zhǒng。","meaning":"There is more than one pronunciation of 'garage'.","meaningThai":"มีการออกเสียงคำว่า 'garage' มากกว่าหนึ่งคำ"},{"chinese":"平均而言，教师使用它增加了他们教如看字读音及单词积累这样的阅读技巧的时间。","pinyin":"Píng jūn ér yán， jiào shī shǐ yòng tā zēng jiā le tā mén jiào rú kàn zì dú yīn jí dān cí jī léi zhè yàng de yuè dú jì qiǎo de shí jiān。","meaning":"On average, teachers using it increased the time they taught reading skills like phonics and vocabulary.","meaningThai":"โดยเฉลี่ยแล้ว ครูที่ใช้แอปนี้จะเพิ่มเวลาในการสอนทักษะการอ่าน เช่น การออกเสียงและคำศัพท์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-312","chinese":"独自","pinyin":"dúzì","meaning":"alone","meaningThai":"ตามลำพัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们避免黄昏后独自出门。","pinyin":"Tā mén bì miǎn huáng hūn hòu dú zì chū mén。","meaning":"They avoid going out alone after dark.","meaningThai":"พวกเขาหลีกเลี่ยงการออกไปคนเดียวหลังมืด"},{"chinese":"他独自坐在黑暗中。","pinyin":"Tā dú zì zuò zài hēi àn zhōng。","meaning":"He was sitting alone in the darkness.","meaningThai":"เขานั่งอยู่คนเดียวในความมืด"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-313","chinese":"儿女","pinyin":"érnǚ","meaning":"children; sons and daughters; a young man and a young woman (in love)","meaningThai":"เด็ก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的儿女们已经离开家了。","pinyin":"Tā de ér nǚ mén yǐ jīng lí kāi jiā le。","meaning":"His children have left home.","meaningThai":"ลูก ๆ ของเขาออกจากบ้านแล้ว"},{"chinese":"她极度疼爱自己的儿女。","pinyin":"Tā jí dù téng ài zì jǐ de ér nǚ。","meaning":"She worships her children.","meaningThai":"เธอบูชาลูก ๆ ของเธอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-314","chinese":"二手","pinyin":"èrshǒu","meaning":"indirectly acquired; second-hand (information, equipment etc); assistant","meaningThai":"มือสอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我买的这架照相机是二手货。","pinyin":"Wǒ mǎi de zhè jià zhào xiāng jī shì èr shǒu huò。","meaning":"I bought the camera second-hand.","meaningThai":"ฉันซื้อกล้องมือสอง"},{"chinese":"你知道我在哪儿可以买到二手计算机吗？","pinyin":"Nǐ zhī dào wǒ zài nǎ ér kě yǐ mǎi dào èr shǒu jì suàn jī ma？","meaning":"Do you know anywhere I can buy a second-hand computer?","meaningThai":"คุณรู้ไหมว่าฉันสามารถซื้อคอมพิวเตอร์มือสองได้จากที่ไหน?"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-315","chinese":"二维码","pinyin":"èrwéimǎ","meaning":"two-dimensional barcode; QR code","meaningThai":"คิวอาร์โค้ด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"扫二维码加好友。","pinyin":"Sǎo èr wéi mǎ jiā hǎo yǒu.","meaning":"Scan the QR code to add a friend.","meaningThai":"สแกนรหัส QR เพื่อเพิ่มเพื่อน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-316","chinese":"罚","pinyin":"fá","meaning":"to punish; to penalize","meaningThai":"ลงโทษ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在比赛的最后一刻，他罚失了点球。","pinyin":"Zài bǐ sài de zuì hòu yī kè， tā fá shī le diǎn qiú。","meaning":"He missed a penalty in the last minute of the game.","meaningThai":"เขาพลาดจุดโทษในนาทีสุดท้ายของเกม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-317","chinese":"发表","pinyin":"fābiǎo","meaning":"to issue; to publish","meaningThai":"เผยแพร่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"正式的文本很快就要发表了。","pinyin":"Zhèng shì de wén běn hěn kuài jiù yào fā biǎo le。","meaning":"The definitive version of the text is ready to be published.","meaningThai":"ข้อความเวอร์ชันสุดท้ายพร้อมที่จะเผยแพร่แล้ว"},{"chinese":"谁授权发表这些资料的？","pinyin":"Shuí shòu quán fā biǎo zhè xiē zī liào de？","meaning":"Who gave the authorization to release the data?","meaningThai":"ใครเป็นผู้อนุญาตให้เปิดเผยข้อมูล?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-318","chinese":"发布","pinyin":"fābù","meaning":"to release; to issue; to announce; to distribute; also written 发布","meaningThai":"ปล่อย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们只会发布合他们意的消息。","pinyin":"Tā mén zhī huì fā bù hé tā mén yì de xiāo xī。","meaning":"They will only release information if it suits them.","meaningThai":"พวกเขาจะเปิดเผยข้อมูลเฉพาะเมื่อเหมาะสมเท่านั้น"},{"chinese":"巴克斯特解释了新闻发布的内容。","pinyin":"Bā kè sī tè jiě shì le xīn wén fā bù de nèi róng。","meaning":"Baxter paraphrased the contents of the press release.","meaningThai":"Baxter ถอดความเนื้อหาของข่าวประชาสัมพันธ์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-319","chinese":"发达","pinyin":"fādá","meaning":"well-developed; flourishing; to develop; to promote; to expand; (literary) to achieve fame and fortune; to prosper","meaningThai":"ที่พัฒนา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"海豚已经进化形成高度发达的下颌。","pinyin":"Hǎi tún yǐ jīng jìn huà xíng chéng gāo dù fā dá de xià hé。","meaning":"The dolphin has evolved a highly developed jaw.","meaningThai":"โลมามีการพัฒนากรามที่พัฒนาอย่างมาก"},{"chinese":"在欠发达国家这种匮乏是不可避免的。","pinyin":"Zài qiàn fā dá guó jiā zhè zhǒng kuì fá shì bù kě bì miǎn de。","meaning":"This scarcity is inevitable in less developed countries.","meaningThai":"ความขาดแคลนนี้เป็นสิ่งที่หลีกเลี่ยงไม่ได้ในประเทศที่พัฒนาน้อยกว่า"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-320","chinese":"发挥","pinyin":"fāhuī","meaning":"to display; to exhibit; to bring out implicit or innate qualities; to express (a thought or moral); to develop (an idea); to elaborate (on a theme)","meaningThai":"เล่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"联合国将在监督停火方面发挥主要作用。","pinyin":"Lián hé guó jiāng zài jiān dū tíng huǒ fāng miàn fā huī zhǔ yào zuò yòng。","meaning":"The U.N. would play a major role in monitoring a ceasefire.","meaningThai":"สหประชาชาติจะมีบทบาทสำคัญในการติดตามการหยุดยิง"},{"chinese":"多数广告都是通过暗示而发挥作用。","pinyin":"Duō shù guǎng gào dū shì tōng guò àn shì ér fā huī zuò yòng。","meaning":"Most advertisements work through suggestion.","meaningThai":"โฆษณาส่วนใหญ่ทำงานผ่านคำแนะนำ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-321","chinese":"罚款","pinyin":"fákuǎn","meaning":"to fine; penalty; fine (monetary)","meaningThai":"ค่าปรับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"交罚款。","pinyin":"Jiao fa kuan.","meaning":"Pay a fine.","meaningThai":"จ่ายค่าปรับ."}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-322","chinese":"发明","pinyin":"fāmíng","meaning":"to invent; an invention","meaningThai":"สิ่งประดิษฐ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们经常听说新发明不断问世。","pinyin":"Wǒ mén jīng cháng tīng shuō xīn fā míng bù duàn wèn shì。","meaning":"We're hearing a lot about new inventions coming down the pike.","meaningThai":"เราได้ยินมามากมายเกี่ยวกับสิ่งประดิษฐ์ใหม่ๆ ที่มาจากหอก"},{"chinese":"据说是他发明了观赏名人这项活动。","pinyin":"Jù shuō shì tā fā míng le guān shǎng míng rén zhè xiàng huó dòng。","meaning":"He is said to have invented the sport of celebrity-watching.","meaningThai":"กล่าวกันว่าเขาได้คิดค้นกีฬาดูคนดังขึ้นมา"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-323","chinese":"反","pinyin":"fǎn","meaning":"contrary; in reverse; inside out or upside down; to reverse; to return; to oppose; opposite; against; anti-; to rebel; to use analogy; instead; abbr. for 切 phonetic system","meaningThai":"ตรงข้าม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"镜子里的字是反的。","pinyin":"Jìng zǐ lǐ de zì shì fǎn de。","meaning":"Writing is reversed in a mirror.","meaningThai":"การเขียนกลับด้านในกระจก"},{"chinese":"书可以正着放，也可以反着放。","pinyin":"Shū kě yǐ zhèng zháo fàng， yě kě yǐ fǎn zháo fàng。","meaning":"Books have a right and a wrong way up.","meaningThai":"หนังสือย่อมมีทางถูกและมีทางผิด"}],"partOfSpeech":["verb","adjective","adverb"]},
  {"id":"hsk5-324","chinese":"翻","pinyin":"fān","meaning":"to turn over; to flip over; to overturn; to rummage through; to translate; to decode; to double; to climb over or into; to cross","meaningThai":"เปลี่ยน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她翻找自己的护照，但没找着。","pinyin":"Tā fān zhǎo zì jǐ de hù zhào， dàn méi zhǎo zháo。","meaning":"She searched in vain for her passport.","meaningThai":"เธอค้นหาหนังสือเดินทางของเธออย่างไร้ผล"},{"chinese":"她打开抽屉，翻找她的钥匙。","pinyin":"Tā dǎ kāi chōu tì， fān zhǎo tā de yuè chí。","meaning":"She opened the drawer and ferreted around for her keys.","meaningThai":"เธอเปิดลิ้นชักและควานหากุญแจของเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-325","chinese":"反而","pinyin":"fǎn’ér","meaning":"on the contrary; instead","meaningThai":"แทน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"反而，他看来坚决要握紧权力不放。","pinyin":"Fǎn ér， tā kàn lái jiān jué yào wò jǐn quán lì bù fàng。","meaning":"Instead, he appears determined to cling to power.","meaningThai":"แต่กลับดูเหมือนเขาตั้งใจแน่วแน่ที่จะยึดอำนาจ"},{"chinese":"那女人不但不生气反而笑了。","pinyin":"Nà nǚ rén bù dàn bù shēng qì fǎn ér xiào le。","meaning":"Instead of taking offence, the woman smiled.","meaningThai":"แทนที่จะโกรธ ผู้หญิงคนนั้นก็ยิ้ม"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-326","chinese":"反复","pinyin":"fǎnfù","meaning":"variant of 反复","meaningThai":"ซ้ำแล้วซ้ำเล่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这项政策在国会反复受到强烈批评。","pinyin":"Zhè xiàng zhèng cè zài guó huì fǎn fù shòu dào qiáng liè pī píng。","meaning":"This policy had repeatedly come under strong criticism on Capitol Hill.","meaningThai":"นโยบายนี้ถูกวิพากษ์วิจารณ์อย่างหนักต่อแคปิตอลฮิลล์หลายครั้ง"},{"chinese":"他反复说自己从未故意吸毒。","pinyin":"Tā fǎn fù shuō zì jǐ cóng wèi gù yì xī dú。","meaning":"He repeated that he had never knowingly taken illegal drugs.","meaningThai":"เขาย้ำว่าเขาไม่เคยเสพยาผิดกฎหมายโดยเจตนา"}],"partOfSpeech":["adverb","verb"]},
  {"id":"hsk5-327","chinese":"防","pinyin":"fáng","meaning":"to protect; to defend; to guard against; to prevent","meaningThai":"ปกป้อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"现在还没有防艾滋病病毒传染的疫苗。","pinyin":"Xiàn zài huán méi yǒu fáng ài zī bìng bìng dú chuán rǎn de yì miáo。","meaning":"There is no vaccine against HIV infection.","meaningThai":"ไม่มีวัคซีนป้องกันการติดเชื้อเอชไอวี"},{"chinese":"遇到这样的对手几乎防不胜防。","pinyin":"Yù dào zhè yàng de duì shǒu jī hū fáng bù shèng fáng。","meaning":"Defence was well-nigh impossible against such opponents.","meaningThai":"การป้องกันแทบจะเป็นไปไม่ได้เลยกับคู่ต่อสู้เช่นนี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-328","chinese":"方","pinyin":"fāng","meaning":"surname Fang","meaningThai":"สี่เหลี่ยม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他长着一副结实的方下巴。","pinyin":"Tā cháng zháo yī fù jié shí de fāng xià bā。","meaning":"He has a strong square jaw.","meaningThai":"เขามีกรามสี่เหลี่ยมที่แข็งแรง"},{"chinese":"我们采用第一方案还是第二方案？","pinyin":"Wǒ mén cǎi yòng dì yī fāng àn huán shì dì èr fāng àn？","meaning":"Shall we go for plan A or plan B?","meaningThai":"เราจะไปแผน A หรือแผน B?"}],"partOfSpeech":["measure word","adverb","other","adjective"]},
  {"id":"hsk5-329","chinese":"方案","pinyin":"fāng'àn","meaning":"plan; program (for action etc); proposal; proposed bill","meaningThai":"วางแผน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个方案的具体细节尚需制订。","pinyin":"Zhè gè fāng àn de jù tǐ xì jié shàng xū zhì dìng。","meaning":"The fine detail of the plan has yet to be worked out.","meaningThai":"รายละเอียดปลีกย่อยของแผนยังไม่ได้รับการแก้ไข"},{"chinese":"目前尚无扩建地方机场的方案。","pinyin":"Mù qián shàng wú kuò jiàn dì fāng jī cháng de fāng àn。","meaning":"There are no plans to expand the local airport.","meaningThai":"ไม่มีแผนที่จะขยายสนามบินท้องถิ่น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-330","chinese":"仿佛","pinyin":"fǎngfú","meaning":"variant of 仿佛","meaningThai":"ราวกับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"仿佛在梦里。","pinyin":"Fang fu zai meng li.","meaning":"As if in a dream.","meaningThai":"ราวกับอยู่ในความฝัน"}],"partOfSpeech":["adverb","verb"]},
  {"id":"hsk5-331","chinese":"访问","pinyin":"fǎngwèn","meaning":"to visit; to call on; to interview","meaningThai":"เข้าถึง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"布什总统定于下月访问该国。","pinyin":"Bù shí zǒng tǒng dìng yú xià yuè fǎng wèn gāi guó。","meaning":"President Bush is due to visit the country next month.","meaningThai":"ประธานาธิบดีบุชมีกำหนดเยือนประเทศเดือนหน้า"},{"chinese":"总统的访问富有象征意义。","pinyin":"Zǒng tǒng de fǎng wèn fù yǒu xiàng zhēng yì yì。","meaning":"The president's visit is loaded with symbolic significance.","meaningThai":"การมาเยือนของประธานาธิบดีเต็มไปด้วยความหมายเชิงสัญลักษณ์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-332","chinese":"房屋","pinyin":"fángwū","meaning":"house; building","meaningThai":"บ้าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"活动房屋怎么也比不上传统的房屋。","pinyin":"Huó dòng fáng wū zěn mó yě bǐ bù shàng chuán tǒng de fáng wū。","meaning":"A mobile home simply doesn't stack up against a traditional house.","meaningThai":"บ้านเคลื่อนที่ไม่สามารถเทียบได้กับบ้านแบบเดิมๆ"},{"chinese":"最后，我们看到了几座房屋。","pinyin":"Zuì hòu， wǒ mén kàn dào le jī zuò fáng wū。","meaning":"At last we came in sight of a few houses.","meaningThai":"ในที่สุดเราก็มาเห็นบ้านบางหลังแล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-333","chinese":"防止","pinyin":"fángzhǐ","meaning":"to prevent; to guard against; to take precautions","meaningThai":"ป้องกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们采取积极措施，防止疾病蔓延。","pinyin":"Tā mén cǎi qǔ jī jí cuò shī， fáng zhǐ jí bìng màn yán。","meaning":"They took active steps to prevent the spread of the disease.","meaningThai":"พวกเขาดำเนินมาตรการเชิงรุกเพื่อป้องกันการแพร่กระจายของโรค"},{"chinese":"这些措施旨在防止暴力犯罪。","pinyin":"Zhè xiē cuò shī zhǐ zài fáng zhǐ bào lì fàn zuì。","meaning":"These measures are aimed at preventing violent crime.","meaningThai":"มาตรการเหล่านี้มีวัตถุประสงค์เพื่อป้องกันอาชญากรรมรุนแรง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-334","chinese":"返回","pinyin":"fǎnhuí","meaning":"to return to; to come (or go) back","meaningThai":"กลับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"柯蒂斯开车，他们启程返回小屋。","pinyin":"Kē dì sī kāi chē， tā mén qǐ chéng fǎn huí xiǎo wū。","meaning":"Curtis got behind the wheel and they started back toward the cottage.","meaningThai":"เคอร์ติสขึ้นหลังพวงมาลัยแล้วพวกเขาก็กลับไปที่กระท่อม"},{"chinese":"哈雷彗星将在2061年返回。","pinyin":"Hā léi huì xīng jiāng zài 2061 nián fǎn huí。","meaning":"Halley's Comet is going to come back in 2061.","meaningThai":"ดาวหางฮัลเลย์จะกลับมาในปี 2061"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-335","chinese":"番茄","pinyin":"fānqié","meaning":"tomato","meaningThai":"มะเขือเทศ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"不是血，是番茄酱。","pinyin":"Bù shì xiě， shì fān qié jiàng。","meaning":"It's not blood - it's ketchup.","meaningThai":"ไม่ใช่เลือด แต่เป็นซอสมะเขือเทศ"},{"chinese":"梅格買一罐番茄。","pinyin":"Méi gé mǎi yī guàn fān qié。","meaning":"Meg bought a can of tomatoes.","meaningThai":"เม็กซื้อมะเขือเทศหนึ่งกระป๋อง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-336","chinese":"繁荣","pinyin":"fánróng","meaning":"prosperous; booming (economy)","meaningThai":"รุ่งเรือง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"经济繁荣。","pinyin":"Jing ji fan rong.","meaning":"Economic prosperity.","meaningThai":"ความเจริญรุ่งเรืองทางเศรษฐกิจ"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-337","chinese":"范围","pinyin":"fànwéi","meaning":"range; scope; limit; extent","meaningThai":"ขอบเขต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这项工作涉及的职责范围很广。","pinyin":"Zhè xiàng gōng zuò shè jí de zhí zé fàn wéi hěn guǎng。","meaning":"The job encompasses a wide range of responsibilities.","meaningThai":"งานครอบคลุมความรับผิดชอบที่หลากหลาย"},{"chinese":"那个问题不在本次会谈范围之内。","pinyin":"Nà gè wèn tí bù zài běn cì huì tán fàn wéi zhī nèi。","meaning":"That question is not within the scope of this talk.","meaningThai":"คำถามนั้นไม่อยู่ในขอบเขตของคำพูดนี้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-338","chinese":"反应","pinyin":"fǎnyìng","meaning":"to react; to respond; reaction; response; reply; chemical reaction","meaningThai":"ปฏิกิริยา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我等着看她如何反应。","pinyin":"Wǒ děng zháo kàn tā rú hé fǎn yīng。","meaning":"I waited to see how she responded.","meaningThai":"ฉันรอดูว่าเธอตอบอย่างไร"},{"chinese":"他的反应令我诧异。","pinyin":"Tā de fǎn yīng líng wǒ chà yì。","meaning":"His reaction struck me as odd.","meaningThai":"ปฏิกิริยาของเขาทำให้ฉันรู้สึกว่าแปลก"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-339","chinese":"反映","pinyin":"fǎnyìng","meaning":"to mirror; to reflect; mirror image; reflection; (fig.) to report; to make known; to render","meaningThai":"สะท้อน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这反映出对未来真正的愤怒和忧虑。","pinyin":"Zhè fǎn yìng chū duì wèi lái zhēn zhèng de fèn nù hé yōu lǜ。","meaning":"It reflects real anger and apprehension about the future.","meaningThai":"มันสะท้อนถึงความโกรธและความหวาดหวั่นที่แท้จริงเกี่ยวกับอนาคต"},{"chinese":"穿着常常反映出一个人的个性。","pinyin":"Chuān zháo cháng cháng fǎn yìng chū yī gè rén de gè xìng。","meaning":"Your clothes are often a reflection of your personality.","meaningThai":"เสื้อผ้าของคุณมักจะสะท้อนถึงบุคลิกภาพของคุณ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-340","chinese":"反正","pinyin":"fǎnzhèng","meaning":"anyway; in any case; to come over from the enemy's side","meaningThai":"ถึงอย่างไร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"反正我们也打算给那个房间贴墙纸的。","pinyin":"Fǎn zhèng wǒ mén yě dǎ suàn gěi nà gè fáng jiān tiē qiáng zhǐ de。","meaning":"We were going to wallpaper that room anyway.","meaningThai":"เราจะติดวอลเปเปอร์ห้องนั้นอยู่แล้ว"},{"chinese":"反正现在已经太迟了。","pinyin":"Fǎn zhèng xiàn zài yǐ jīng tài chí le。","meaning":"It's too late now, anyway.","meaningThai":"ตอนนี้มันสายเกินไปแล้ว"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-341","chinese":"发起","pinyin":"fāqǐ","meaning":"to originate; to initiate; to launch (an attack, an initiative etc); to start; to propose sth (for the first time)","meaningThai":"เริ่มต้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"总统授意发起了一项救援基金。","pinyin":"Zǒng tǒng shòu yì fā qǐ le yī xiàng jiù yuán jī jīn。","meaning":"An appeal fund was launched at the instigation of the President.","meaningThai":"มีการเปิดตัวกองทุนอุทธรณ์ตามคำแนะนำของประธานาธิบดี"},{"chinese":"他发起了某项后来改变了中国面貌的行动。","pinyin":"Tā fā qǐ le mǒu xiàng hòu lái gǎi biàn le zhōng guó miàn mào de háng dòng。","meaning":"He started something that was to change the face of China.","meaningThai":"เขาเริ่มต้นบางสิ่งที่จะเปลี่ยนโฉมหน้าของจีน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-342","chinese":"发言","pinyin":"fāyán","meaning":"to make a speech; statement; utterance","meaningThai":"พูด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的发言里没有浮夸或自负。","pinyin":"Tā de fā yán lǐ méi yǒu fú kuā huò zì fù。","meaning":"There was no bombast or conceit in his speech.","meaningThai":"ไม่มีการระเบิดหรือหยิ่งในคำพูดของเขา"},{"chinese":"他在未经君王许可而发言。","pinyin":"Tā zài wèi jīng jūn wáng xǔ kě ér fā yán。","meaning":"He was speaking without the prince's authority.","meaningThai":"เขาพูดโดยไม่ได้รับอำนาจจากเจ้าชาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-343","chinese":"发音","pinyin":"fāyīn","meaning":"pronounce","meaningThai":"ออกเสียง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个词怎么发音？","pinyin":"Zhè gè cí zěn mó fā yīn？","meaning":"How do you pronounce this word?","meaningThai":"คุณออกเสียงคำนี้ได้อย่างไร?"},{"chinese":"他的发音远非完美。","pinyin":"Tā de fā yīn yuǎn fēi wán měi。","meaning":"His pronunciation is far from perfect.","meaningThai":"การออกเสียงของเขายังห่างไกลจากความสมบูรณ์แบบ"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-344","chinese":"法院","pinyin":"fǎyuàn","meaning":"court of law; court","meaningThai":"ศาล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"以色列法院尚未对此案做出裁决。","pinyin":"Yǐ sè liè fǎ yuàn shàng wèi duì cǐ àn zuò chū cái jué。","meaning":"The Israeli court has not yet ruled on the case.","meaningThai":"ศาลอิสราเอลยังไม่ได้ตัดสินคดีนี้"},{"chinese":"法院有权因某些罪行判处罪犯死刑。","pinyin":"Fǎ yuàn yǒu quán yīn mǒu xiē zuì háng pàn chǔ zuì fàn sǐ xíng。","meaning":"The courts were empowered to impose the death sentence for certain crimes.","meaningThai":"ศาลมีอำนาจกำหนดโทษประหารชีวิตสำหรับอาชญากรรมบางประเภท"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-345","chinese":"飞行","pinyin":"fēixíng","meaning":"(of planes etc) to fly; flying; flight; aviation","meaningThai":"เที่ยวบิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个男人有飞行恐惧症。","pinyin":"Zhè gè nán rén yǒu fēi háng kǒng jù zhèng。","meaning":"The man had a phobia about flying.","meaningThai":"ชายผู้นี้เป็นโรคกลัวการบิน"},{"chinese":"我们在云层上面飞行。","pinyin":"Wǒ mén zài yún céng shàng miàn fēi háng。","meaning":"We were flying above the clouds.","meaningThai":"เรากำลังบินอยู่เหนือเมฆ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-346","chinese":"飞行员","pinyin":"fēixíngyuán","meaning":"pilot; aviator","meaningThai":"นักบิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这位飞行员数秒之内死里逃生。","pinyin":"Zhè wèi fēi háng yuán shù miǎo zhī nèi sǐ lǐ táo shēng。","meaning":"The pilot escaped death by seconds.","meaningThai":"นักบินรอดพ้นความตายไปได้ไม่กี่วินาที"},{"chinese":"驾驶飞机对飞行员要求很高。","pinyin":"Jià shǐ fēi jī duì fēi háng yuán yào qiú hěn gāo。","meaning":"Flying makes enormous demands on pilots.","meaningThai":"การบินทำให้นักบินมีความต้องการมหาศาล"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-347","chinese":"非洲","pinyin":"Fēizhōu","meaning":"Africa","meaningThai":"แอฟริกา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他离开英格兰，打算去非洲旅行。","pinyin":"Tā lí kāi yīng gé lán， dǎ suàn qù fēi zhōu lǚ háng。","meaning":"He left England with the intention of travelling in Africa.","meaningThai":"เขาออกจากอังกฤษด้วยความตั้งใจที่จะเดินทางไปแอฟริกา"},{"chinese":"很多非洲部落相信转世再生。","pinyin":"Hěn duō fēi zhōu bù luò xiāng xìn zhuǎn shì zài shēng。","meaning":"Many African tribes believe in reincarnation.","meaningThai":"ชนเผ่าแอฟริกันจำนวนมากเชื่อเรื่องการกลับชาติมาเกิด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-348","chinese":"分别","pinyin":"fēnbié","meaning":"to part; to leave each other; to distinguish; to tell apart; difference; distinction; in different ways; differently; separately; individually","meaningThai":"ตามลำดับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们分别时又是流泪，又是拥抱。","pinyin":"Tā mén fēn bié shí yòu shì liú lèi， yòu shì yōng bào。","meaning":"There were tears and embraces as they said goodbye.","meaningThai":"มีน้ำตาและกอดกันเมื่อพวกเขากล่าวคำอำลา"},{"chinese":"我能否一件一件地分别付钱？","pinyin":"Wǒ néng fǒu yī jiàn yī jiàn dì fēn bié fù qián？","meaning":"Can I pay for each item separately?","meaningThai":"ฉันสามารถชำระเงินแต่ละรายการแยกกันได้หรือไม่?"}],"partOfSpeech":["adverb","verb"]},
  {"id":"hsk5-349","chinese":"分布","pinyin":"fēnbù","meaning":"to scatter; to distribute; to be distributed (over an area etc); (statistical, geographic) distribution","meaningThai":"กระจาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"压力必须均匀分布于整个表面。","pinyin":"Yā lì bì xū jūn yún fēn bù yú zhěng gè biǎo miàn。","meaning":"Pressure must be uniformly distributed over the whole surface.","meaningThai":"แรงดันจะต้องกระจายสม่ำเสมอทั่วทั้งพื้นผิว"},{"chinese":"他们研究了这种疾病的地域分布情况。","pinyin":"Tā mén yán jiū le zhè zhǒng jí bìng de dì yù fēn bù qíng kuàng。","meaning":"They studied the geographical distribution of the disease.","meaningThai":"พวกเขาศึกษาการกระจายทางภูมิศาสตร์ของโรค"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-350","chinese":"奋斗","pinyin":"fèndòu","meaning":"to strive; to struggle","meaningThai":"การต่อสู้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她努力奋斗，逐渐登上公司的高位。","pinyin":"Tā nǔ lì fèn dǒu， zhú jiàn dēng shàng gōng sī de gāo wèi。","meaning":"She gradually fought her way to the top of the company.","meaningThai":"เธอค่อยๆ ต่อสู้เพื่อก้าวไปสู่จุดสูงสุดของบริษัท"},{"chinese":"她全心全意为这一事业而奋斗。","pinyin":"Tā quán xīn quán yì wéi zhè yī shì yè ér fèn dǒu。","meaning":"She committed herself body and soul to fighting for the cause.","meaningThai":"เธอทุ่มเททั้งร่างกายและจิตวิญญาณเพื่อต่อสู้เพื่อสาเหตุ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-351","chinese":"纷纷","pinyin":"fēnfēn","meaning":"one after another; in succession; one by one; continuously; diverse; in profusion; numerous and confused; pell-mell","meaningThai":"ทีละคน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"各家报纸纷纷退避，不敢调查详情。","pinyin":"Gè jiā bào zhǐ fēn fēn tuì bì， bù gǎn tiáo chá xiáng qíng。","meaning":"The newspapers have shied away from investigating the story.","meaningThai":"หนังสือพิมพ์เบือนหน้าหนีจากการสืบสวนเรื่องนี้"},{"chinese":"人群议论纷纷，赞成和反对的都有。","pinyin":"Rén qún yì lùn fēn fēn， zàn chéng hé fǎn duì de dū yǒu。","meaning":"There were murmurs of both assent and dissent from the crowd.","meaningThai":"มีเสียงพึมพำทั้งเห็นด้วยและไม่เห็นด้วยจากฝูงชน"}],"partOfSpeech":["adverb","other"]},
  {"id":"hsk5-352","chinese":"丰富多彩","pinyin":"fēngfù-duōcǎi","meaning":"richly colorful","meaningThai":"มีสีสัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"艺术使生活丰富多彩。","pinyin":"Yì shù shǐ shēng huó fēng fù duō cǎi。","meaning":"Art makes our lives rich and colourful.","meaningThai":"ศิลปะทำให้ชีวิตของเราอุดมสมบูรณ์และมีสีสัน"},{"chinese":"这都增添了人类生活的丰富多彩性。","pinyin":"Zhè dū zēng tiān le rén lèi shēng huó de fēng fù duō cǎi xìng。","meaning":"It all adds to the richness of human life.","meaningThai":"ทั้งหมดนี้เพิ่มความสมบูรณ์ของชีวิตมนุษย์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-353","chinese":"风格","pinyin":"fēnggé","meaning":"style","meaningThai":"สไตล์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种设计后来被称为东方风格。","pinyin":"Zhè zhǒng shè jì hòu lái bèi chēng wéi dōng fāng fēng gé。","meaning":"This design came to be known as the Oriental style.","meaningThai":"การออกแบบนี้เป็นที่รู้จักในชื่อสไตล์ตะวันออก"},{"chinese":"全城到处可见这种风格的建筑。","pinyin":"Quán chéng dào chǔ kě jiàn zhè zhǒng fēng gé de jiàn zhù。","meaning":"You'll find this style of architecture all over the town.","meaningThai":"คุณจะพบกับสถาปัตยกรรมสไตล์นี้ทั่วเมือง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-354","chinese":"疯狂","pinyin":"fēngkuáng","meaning":"crazy; frenzied; wild","meaningThai":"คลั่งไคล้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"透过他的眼睛，她看到了疯狂。","pinyin":"Tòu guò tā de yǎn jīng， tā kàn dào le fēng kuáng。","meaning":"She looked into his eyes and beheld madness.","meaningThai":"เธอมองเข้าไปในดวงตาของเขาและเห็นความบ้าคลั่ง"},{"chinese":"下面大街上，人们在疯狂地挥手。","pinyin":"Xià miàn dà jiē shàng， rén mén zài fēng kuáng dì huī shǒu。","meaning":"Down in the streets people were waving madly.","meaningThai":"บนถนนผู้คนโบกมืออย่างบ้าคลั่ง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-355","chinese":"风俗","pinyin":"fēngsú","meaning":"social custom","meaningThai":"กำหนดเอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个节目介绍全国各地的风俗习惯。","pinyin":"Zhè gè jié mù jiè shào quán guó gè dì de fēng sú xí guàn。","meaning":"The programme was about customs in different parts of the country.","meaningThai":"โปรแกรมนี้เกี่ยวกับศุลกากรในส่วนต่างๆ ของประเทศ"},{"chinese":"这一特殊风俗起源于威尔士。","pinyin":"Zhè yī tè shū fēng sú qǐ yuán yú wēi ěr shì。","meaning":"This particular custom has its origins in Wales.","meaningThai":"ประเพณีนี้มีต้นกำเนิดในเวลส์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-356","chinese":"风险","pinyin":"fēngxiǎn","meaning":"risk; hazard","meaningThai":"เสี่ยง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"官员们曾冒着被解职的风险。","pinyin":"Guān yuán mén zēng mào zháo bèi jiě zhí de fēng xiǎn。","meaning":"The officers had run the risk of being dismissed.","meaningThai":"เจ้าหน้าที่เสี่ยงต่อการถูกไล่ออก"},{"chinese":"买保险可以应对此类风险。","pinyin":"Mǎi bǎo xiǎn kě yǐ yīng duì cǐ lèi fēng xiǎn。","meaning":"Insurance can be purchased to provide protection against such risks.","meaningThai":"สามารถซื้อประกันเพื่อป้องกันความเสี่ยงดังกล่าวได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-357","chinese":"分类","pinyin":"fēnlèi","meaning":"to classify","meaningThai":"การจำแนกประเภท","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"图书馆的书按学科分类。","pinyin":"Tú shū guǎn de shū àn xué kē fēn lèi。","meaning":"The books in the library are classified according to subject.","meaningThai":"หนังสือในห้องสมุดแบ่งตามหัวเรื่อง"},{"chinese":"按照困难程度对工作进行了分类。","pinyin":"Àn zhào kùn nán chéng dù duì gōng zuò jìn háng le fēn lèi。","meaning":"The tasks have been ranked in order of difficulty.","meaningThai":"งานได้รับการจัดอันดับตามความยาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-358","chinese":"分离","pinyin":"fēnlí","meaning":"to separate","meaningThai":"การแยก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们要把教学与研究分离开来。","pinyin":"Tā mén yào bǎ jiào xué yǔ yán jiū fēn lí kāi lái。","meaning":"They want to separate teaching from research.","meaningThai":"พวกเขาต้องการแยกการสอนออกจากการวิจัย"},{"chinese":"南美洲和非洲于2亿年前分离。","pinyin":"Nán měi zhōu hé fēi zhōu yú 2 yì nián qián fēn lí。","meaning":"South America and Africa separated 200 million years ago.","meaningThai":"อเมริกาใต้และแอฟริกาแยกจากกันเมื่อ 200 ล้านปีก่อน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-359","chinese":"分配","pinyin":"fēnpèi","meaning":"to distribute; to assign; to allocate; to partition (a hard drive)","meaningThai":"แจกจ่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们在做的是建立好货物分配网络。","pinyin":"Tā mén zài zuò de shì jiàn lì hǎo huò wù fēn pèi wǎng luò。","meaning":"What they're doing is setting up distributional networks.","meaningThai":"สิ่งที่พวกเขากำลังทำคือการจัดตั้งเครือข่ายการกระจายสินค้า"},{"chinese":"票数有限，将分配给那些先申请的人。","pinyin":"Piào shù yǒu xiàn， jiāng fēn pèi gěi nà xiē xiān shēn qǐng de rén。","meaning":"Tickets are limited and will be allocated to those who apply first.","meaningThai":"บัตรมีจำนวนจำกัดและจะถูกจัดสรรให้กับผู้ที่สมัครก่อน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-360","chinese":"分手","pinyin":"fēnshǒu","meaning":"to part company; to split up; to break up","meaningThai":"แยก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"客船抵达开普敦后，我们就分手了。","pinyin":"Kè chuán dǐ dá kāi pǔ dūn hòu， wǒ mén jiù fēn shǒu le。","meaning":"When the boat reached Cape Town, we said goodbye.","meaningThai":"เมื่อเรือมาถึง Cape Town เราก็บอกลากัน"},{"chinese":"我不愿分手时关系闹得这么僵。","pinyin":"Wǒ bù yuàn fēn shǒu shí guān xì nào dé zhè mó jiāng。","meaning":"I hate to part on such bad terms.","meaningThai":"ฉันเกลียดที่ต้องพรากจากกันด้วยเงื่อนไขที่เลวร้ายเช่นนี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-361","chinese":"分析","pinyin":"fēnxī","meaning":"to analyze; analysis","meaningThai":"วิเคราะห์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们需要分析这个问题。","pinyin":"Wo men xu yao fen xi zhe ge wen ti.","meaning":"We need to analyze this problem.","meaningThai":"เราจำเป็นต้องวิเคราะห์ปัญหานี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-362","chinese":"分享","pinyin":"fēnxiǎng","meaning":"to share (let others have some of sth good)","meaningThai":"แบ่งปัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他一直不吝分享自己丰富的知识。","pinyin":"Tā yī zhí bù lìn fēn xiǎng zì jǐ fēng fù de zhī shí。","meaning":"He was always generous in sharing his enormous knowledge.","meaningThai":"เขาใจดีเสมอในการแบ่งปันความรู้อันมหาศาลของเขา"},{"chinese":"与你信任的人分享你的情感会是有益的。","pinyin":"Yǔ nǐ xìn rèn de rén fēn xiǎng nǐ de qíng gǎn huì shì yǒu yì de。","meaning":"It can be beneficial to share your feelings with someone you trust.","meaningThai":"การแบ่งปันความรู้สึกของคุณกับคนที่คุณไว้วางใจอาจเป็นประโยชน์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-363","chinese":"否定","pinyin":"fǒudìng","meaning":"to negate; to deny; to reject; negative (answer); negation","meaningThai":"เชิงลบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"誰也不能否定其事實。","pinyin":"Shuí yě bù néng fǒu dìng qí shì shí。","meaning":"No one can deny the fact. / Nobody can refute that fact.","meaningThai":"ไม่มีใครสามารถปฏิเสธความจริงได้ / ไม่มีใครสามารถปฏิเสธความจริงข้อนั้นได้"},{"chinese":"汤姆认为答案是否定的。","pinyin":"Tāng mǔ rèn wéi dá àn shì fǒu dìng de。","meaning":"Tom thinks the answer is no.","meaningThai":"ทอมคิดว่าคำตอบคือไม่"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-364","chinese":"否认","pinyin":"fǒurèn","meaning":"to declare to be untrue; to deny","meaningThai":"ปฏิเสธ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他否认这部影片美化暴力。","pinyin":"Tā fǒu rèn zhè bù yǐng piàn měi huà bào lì。","meaning":"He denies that the movie glorifies violence.","meaningThai":"เขาปฏิเสธว่าภาพยนตร์เรื่องนี้เชิดชูความรุนแรง"},{"chinese":"他们否认共谋走私毒品。","pinyin":"Tā mén fǒu rèn gòng móu zǒu sī dú pǐn。","meaning":"They deny conspiring together to smuggle drugs.","meaningThai":"พวกเขาปฏิเสธการสมรู้ร่วมคิดร่วมกันเพื่อลักลอบขนยาเสพติด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-365","chinese":"扶","pinyin":"fú","meaning":"to support with the hand; to help sb up; to support oneself by holding onto something; to help","meaningThai":"ช่วย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她扶他站了起来。","pinyin":"Tā fú tā zhàn le qǐ lái。","meaning":"She helped him to his feet.","meaningThai":"เธอช่วยให้เขาลุกขึ้นยืน"},{"chinese":"喂——让我扶你起来。","pinyin":"Wèi —— ràng wǒ fú nǐ qǐ lái。","meaning":"There—let me help thee up.","meaningThai":"ที่นั่น - ให้ฉันช่วยคุณขึ้นไป"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-366","chinese":"福","pinyin":"fú","meaning":"surname Fu; abbr. for Fujian province 省","meaningThai":"พร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"愿你得到赐福！","pinyin":"Yuàn nǐ dé dào cì fú！","meaning":"May ye be blessed!","meaningThai":"ขอให้ท่านได้รับพร!"},{"chinese":"叩响幸福之门","pinyin":"Kòu xiǎng xìng fú zhī mén","meaning":"Knock on the door of happiness.","meaningThai":"เคาะประตูแห่งความสุข"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-367","chinese":"副","pinyin":"fù","meaning":"secondary; auxiliary; deputy; assistant; vice-; abbr. for 副词 adverb; classifier for pairs, sets of things & facial expressions","meaningThai":"รอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"马克西莫戴上了一副眼镜。","pinyin":"Mǎ kè xī mò dài shàng le yī fù yǎn jìng。","meaning":"Maximo put on a pair of glasses.","meaningThai":"แม็กซิโม่สวมแว่นตา"},{"chinese":"瞧他那副自命不凡的样儿！","pinyin":"Qiáo tā nà fù zì mìng bù fán de yàng ér！","meaning":"He's so pretentious!","meaningThai":"เขาอวดรู้มาก!"}],"partOfSpeech":["adjective","measure word"]},
  {"id":"hsk5-368","chinese":"富","pinyin":"fù","meaning":"surname Fu","meaningThai":"รวย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你将成为一个非常富的人。","pinyin":"Nǐ jiāng chéng wéi yī gè fēi cháng fù de rén。","meaning":"You're going to be a very rich man.","meaningThai":"คุณจะเป็นคนที่รวยมาก"},{"chinese":"他们开出一个富铁矿层。","pinyin":"Tā mén kāi chū yī gè fù tiě kuàng céng。","meaning":"They struck a rich seam of iron ore.","meaningThai":"พวกเขาฟาดตะเข็บแร่เหล็กอันอุดมสมบูรณ์"}],"partOfSpeech":["other","adjective"]},
  {"id":"hsk5-369","chinese":"付出","pinyin":"fùchū","meaning":"to pay; to expend; to invest (energy or time)","meaningThai":"จ่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她因犯错误而付出了巨大的代价。","pinyin":"Tā yīn fàn cuò wù ér fù chū le jù dà de dài jià。","meaning":"She paid dearly for her mistake.","meaningThai":"เธอจ่ายแพงสำหรับความผิดพลาดของเธอ"},{"chinese":"他将为自己缺乏决心付出高昂的代价。","pinyin":"Tā jiāng wéi zì jǐ quē fá jué xīn fù chū gāo áng de dài jià。","meaning":"He was to pay dearly for his lack of resolve.","meaningThai":"เขาต้องจ่ายแพงเพราะขาดความมุ่งมั่น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-370","chinese":"负担","pinyin":"fùdān","meaning":"to bear (an expense, a responsibility etc); burden","meaningThai":"ภาระ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们不去，只是因为我们负担不起。","pinyin":"Wǒ mén bù qù， zhī shì yīn wéi wǒ mén fù dān bù qǐ。","meaning":"We aren't going for the simple reason that we can't afford it.","meaningThai":"เราจะไม่ไปด้วยเหตุผลง่ายๆ ที่เราไม่สามารถจ่ายได้"},{"chinese":"57%的人抱怨工作负担过重。","pinyin":"57% de rén bào yuàn gōng zuò fù dān guò zhòng。","meaning":"57 percent complained of work overload.","meaningThai":"ร้อยละ 57 บ่นเรื่องงานล้นมือ"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-371","chinese":"夫妇","pinyin":"fūfù","meaning":"a (married) couple; husband and wife","meaningThai":"คู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这对夫妇都有烹饪美食的爱好。","pinyin":"Zhè duì fū fù dū yǒu pēng rèn měi shí de ài hǎo。","meaning":"The couple share a love of gourmet cooking.","meaningThai":"ทั้งคู่แบ่งปันความรักในการทำอาหารรสเลิศ"},{"chinese":"这对夫妇试图和解但未成功。","pinyin":"Zhè duì fū fù shì tú hé jiě dàn wèi chéng gōng。","meaning":"The couple made an unsuccessful attempt at a compromise.","meaningThai":"ทั้งคู่พยายามประนีประนอมไม่สำเร็จ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-372","chinese":"妇女","pinyin":"fùnǚ","meaning":"woman","meaningThai":"สตรี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"妇女节。","pinyin":"Fu nv jie.","meaning":"Women's Day.","meaningThai":"วันสตรี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-373","chinese":"富有","pinyin":"fùyǒu","meaning":"rich; wealthy; affluent; to be rich in; to be replete with","meaningThai":"รวย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“他富有吗？”—“他生活宽裕。”","pinyin":"“ tā fù yǒu ma？”—“ tā shēng huó kuān yù。”","meaning":"\"Is he rich?\"—\"He's comfortable.\"","meaningThai":"\"เขารวยหรือเปล่า?\"—\"เขาสบายใจ\""},{"chinese":"他们并不是那么富有。","pinyin":"Tā mén bìng bù shì nà mó fù yǒu。","meaning":"They're not as rich as all that.","meaningThai":"พวกเขาไม่ได้รวยขนาดนั้น"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-374","chinese":"复制","pinyin":"fùzhì","meaning":"to duplicate; to make a copy of; to copy; to reproduce; to clone","meaningThai":"สำเนา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这份材料可以复制，不会侵犯版权。","pinyin":"Zhè fèn cái liào kě yǐ fù zhì， bù huì qīn fàn bǎn quán。","meaning":"The material can be copied without infringing copyright.","meaningThai":"สามารถคัดลอกเนื้อหาได้โดยไม่ละเมิดลิขสิทธิ์"},{"chinese":"这幅画是复制品，原画在马德里。","pinyin":"Zhè fú huà shì fù zhì pǐn， yuán huà zài mǎ dé lǐ。","meaning":"This painting is a copy; the original is in Madrid.","meaningThai":"ภาพวาดนี้เป็นสำเนา ต้นฉบับอยู่ในมาดริด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-375","chinese":"服装","pinyin":"fúzhuāng","meaning":"dress; clothing; costume; clothes","meaningThai":"เสื้อผ้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们身着华丽的服装等待。","pinyin":"Wǒ mén shēn zháo huá lì de fú zhuāng děng dài。","meaning":"We waited in our fine clothes.","meaningThai":"เรารออยู่ในเสื้อผ้าที่สวยงามของเรา"},{"chinese":"所有员工必须穿防护服装。","pinyin":"Suǒ yǒu yuán gōng bì xū chuān fáng hù fú zhuāng。","meaning":"It is obligatory for all employees to wear protective clothing.","meaningThai":"บังคับให้พนักงานทุกคนสวมชุดป้องกัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-376","chinese":"盖","pinyin":"gài","meaning":"surname Ge","meaningThai":"สร้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她又拧了一下，盖儿开了。","pinyin":"Tā yòu níng le yī xià， gài ér kāi le。","meaning":"She gave the lid another twist and it came off.","meaningThai":"เธอบิดฝาอีกครั้งและมันก็หลุดออกมา"},{"chinese":"他猛然开盖，朝箱里看。","pinyin":"Tā měng rán kāi gài， zhāo xiāng lǐ kàn。","meaning":"He flipped the lid open and looked inside the case.","meaningThai":"เขาพลิกฝาเปิดออกแล้วมองเข้าไปในกล่อง"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-377","chinese":"改革","pinyin":"gǎigé","meaning":"reform; to reform","meaningThai":"ปฏิรูป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"改革开放。","pinyin":"Gai ge kai fang.","meaning":"Reform and opening up.","meaningThai":"การปฏิรูปและการเปิดกว้าง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-378","chinese":"改进","pinyin":"gǎijìn","meaning":"to improve; to make better; improvement","meaningThai":"ทำให้ดีขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们在研究如何改进人们饮食。","pinyin":"Tā mén zài yán jiū rú hé gǎi jìn rén mén yǐn shí。","meaning":"They're researching into ways of improving people's diet.","meaningThai":"พวกเขากำลังค้นคว้าวิธีปรับปรุงอาหารของผู้คน"},{"chinese":"我们得考虑改进营销方法。","pinyin":"Wǒ mén dé kǎo lǜ gǎi jìn yíng xiāo fāng fǎ。","meaning":"We need to look to ways of improving our marketing.","meaningThai":"เราจำเป็นต้องมองหาวิธีปรับปรุงการตลาดของเรา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-379","chinese":"概括","pinyin":"gàikuò","meaning":"to summarize; to generalize; briefly; in broad outline","meaningThai":"สรุป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他对讲话做了精练的概括。","pinyin":"Tā duì jiǎng huà zuò le jīng liàn de gài kuò。","meaning":"He summarized the speech snappily.","meaningThai":"เขาสรุปคำพูดได้ฉับไว"},{"chinese":"在莎士比亚所有的戏剧中，《哈姆雷特》最难概括。","pinyin":"Zài suō shì bǐ yà suǒ yǒu de xì jù zhōng，《 hā mǔ léi tè 》 zuì nán gài kuò。","meaning":"'Hamlet' is the least amenable of all Shakespeare's plays to being summarized.","meaningThai":"'Hamlet' เป็นบทละครของเช็คสเปียร์ที่สามารถสรุปได้น้อยที่สุด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-380","chinese":"概念","pinyin":"gàiniàn","meaning":"concept; idea","meaningThai":"แนวคิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我对他的样子有了个大致的概念。","pinyin":"Wǒ duì tā de yàng zǐ yǒu le gè dà zhì de gài niàn。","meaning":"I've got a rough idea of what he looks like.","meaningThai":"ฉันมีความคิดคร่าวๆว่าเขาหน้าตาเป็นอย่างไร"},{"chinese":"这两个系统实际上是概念模型。","pinyin":"Zhè liǎng gè xì tǒng shí jì shàng shì gài niàn mó xíng。","meaning":"The two systems are, at bottom, conceptual models.","meaningThai":"ทั้งสองระบบอยู่ที่ด้านล่างซึ่งเป็นโมเดลเชิงแนวคิด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-381","chinese":"改善","pinyin":"gǎishàn","meaning":"to make better; to improve","meaningThai":"ทำให้ดีขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"很遗憾，我们无力改善目前的状况。","pinyin":"Hěn yí hàn， wǒ mén wú lì gǎi shàn mù qián de zhuàng kuàng。","meaning":"Unfortunately, there is nothing we can do to improve matters.","meaningThai":"ขออภัย เราไม่สามารถปรับปรุงเรื่องต่างๆ ได้"},{"chinese":"关系一改善他们就会获准离开。","pinyin":"Guān xì yī gǎi shàn tā mén jiù huì huò zhǔn lí kāi。","meaning":"As soon as relations improve they will be allowed to go.","meaningThai":"เมื่อความสัมพันธ์ดีขึ้นก็จะได้รับอนุญาตให้ไป"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-382","chinese":"改天","pinyin":"gǎitiān","meaning":"Another day","meaningThai":"อีกวัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我下班了，改天聊。","pinyin":"Wǒ xià bān le， gǎi tiān liáo。","meaning":"I am leaving work, so let's talk another day.","meaningThai":"ฉันกำลังเลิกงานแล้ว ไว้คุยกันวันอื่น"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-383","chinese":"改正","pinyin":"gǎizhèng","meaning":"to correct; to amend; to put right; correction","meaningThai":"ถูกต้อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有一些程序错误需要改正。","pinyin":"Yǒu yī xiē chéng xù cuò wù xū yào gǎi zhèng。","meaning":"There are some programming errors that need correction.","meaningThai":"มีข้อผิดพลาดในการเขียนโปรแกรมบางอย่างที่ต้องแก้ไข"},{"chinese":"从头至尾看一遍你们的作业，发现的错误都要改正过来。","pinyin":"Cóng tóu zhì wěi kàn yī biàn nǐ mén de zuò yè， fā xiàn de cuò wù dū yào gǎi zhèng guò lái。","meaning":"Read through your work and correct any mistakes that you find.","meaningThai":"อ่านงานของคุณและแก้ไขข้อผิดพลาดที่คุณพบ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-384","chinese":"刚好","pinyin":"gānghǎo","meaning":"just; exactly; to happen to be","meaningThai":"แค่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"碰巧运气好，我们刚好同时到达。","pinyin":"Pèng qiǎo yùn qì hǎo， wǒ mén gāng hǎo tóng shí dào dá。","meaning":"By a happy coincidence , we arrived at exactly the same time.","meaningThai":"ด้วยความบังเอิญ เรามาทันเวลาพอดีเลย"},{"chinese":"他们只刚好设法勉强凑够了那笔钱。","pinyin":"Tā mén zhī gāng hǎo shè fǎ miǎn qiáng còu gòu le nà bǐ qián。","meaning":"They only just managed to scrape the money together.","meaningThai":"พวกเขาแค่จัดการหาเงินด้วยกันเท่านั้น"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-385","chinese":"敢于","pinyin":"gǎnyú","meaning":"to have the courage to do sth; to dare to; bold in","meaningThai":"กล้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我赞赏她敢于拒绝。","pinyin":"Wǒ zàn shǎng tā gǎn yú jù jué。","meaning":"I applaud her for having the courage to refuse.","meaningThai":"ฉันชื่นชมเธอที่กล้าปฏิเสธ"},{"chinese":"我希望人们能敢于大胆说出来，反对这种不公。","pinyin":"Wǒ xī wàng rén mén néng gǎn yú dà dǎn shuō chū lái， fǎn duì zhè zhǒng bù gōng。","meaning":"I hope people will be courageous enough to speak out against this injustice.","meaningThai":"ฉันหวังว่าผู้คนจะกล้าพอที่จะออกมาต่อต้านความอยุติธรรมนี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-386","chinese":"搞","pinyin":"gǎo","meaning":"to do; to make; to go in for; to set up; to get hold of; to take care of","meaningThai":"ทำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"搞好关系。","pinyin":"Gao hao guan xi.","meaning":"Build good relations.","meaningThai":"สร้างความสัมพันธ์อันดี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-387","chinese":"告别","pinyin":"gàobié","meaning":"to leave; to part from; to bid farewell to; to say goodbye to","meaningThai":"กล่าวคำอำลา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“开车小心，”他说着挥手告别。","pinyin":"“ kāi chē xiǎo xīn，” tā shuō zháo huī shǒu gào bié。","meaning":"\"Drive safely,\" he said and waved goodbye.","meaningThai":"“ขับรถอย่างปลอดภัย” เขาพูดและโบกมือลา"},{"chinese":"我向母亲挥手告别时她哭了。","pinyin":"Wǒ xiàng mǔ qīn huī shǒu gào bié shí tā kū le。","meaning":"My mother was crying as I waved her goodbye.","meaningThai":"แม่ของฉันกำลังร้องไห้ขณะที่ฉันโบกมือลาเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-388","chinese":"高大","pinyin":"gāodà","meaning":"tall; lofty; towering","meaningThai":"สูงใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他长得很高大。","pinyin":"Ta zhang de hen gao da.","meaning":"He is very tall.","meaningThai":"เขาสูงมาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-389","chinese":"高档","pinyin":"gāodàng","meaning":"superior quality; high grade; top grade","meaningThai":"หรู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"很多人不断将手机升级到最高档的款式。","pinyin":"Hěn duō rén bù duàn jiāng shǒu jī shēng jí dào zuì gāo dàng de kuǎn shì。","meaning":"Many people are upgrading their mobiles to top-end models.","meaningThai":"หลายๆ คนกำลังอัพเกรดมือถือของตนเป็นรุ่นท็อปเอนด์"},{"chinese":"棕榈泉有高档餐厅和奢华的夜生活。","pinyin":"Zōng lǘ quán yǒu gāo dàng cān tīng hé shē huá de yè shēng huó。","meaning":"Palm Springs has ritzy restaurants and glitzy nightlife.","meaningThai":"ปาล์มสปริงส์มีร้านอาหารหรูหราและสถานบันเทิงยามค่ำคืนที่หรูหรา"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-390","chinese":"高度","pinyin":"gāodù","meaning":"height; altitude; elevation; high degree; highly","meaningThai":"ความสูง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"高度关注。","pinyin":"Gao du guan zhu.","meaning":"High attention.","meaningThai":"ความสนใจสูง"}],"partOfSpeech":["adverb","noun"]},
  {"id":"hsk5-391","chinese":"高级","pinyin":"gāojí","meaning":"high level; high grade; advanced; high-ranking","meaningThai":"ขั้นสูง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"明年她将参加高级组别的比赛。","pinyin":"Míng nián tā jiāng cān jiā gāo jí zǔ bié de bǐ sài。","meaning":"She'll be racing for the senior team next year.","meaningThai":"เธอจะลงแข่งให้กับทีมชุดใหญ่ในปีหน้า"},{"chinese":"高级防务官员举行了秘密会谈。","pinyin":"Gāo jí fáng wù guān yuán jǔ háng le mì mì huì tán。","meaning":"Senior defence officials held private talks.","meaningThai":"เจ้าหน้าที่กลาโหมอาวุโสจัดการเจรจาเป็นการส่วนตัว"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-392","chinese":"高科技","pinyin":"gāokējì","meaning":"high tech; high technology","meaningThai":"เทคโนโลยีชั้นสูง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"去年，投入到高科技公司的钱较少。","pinyin":"Qù nián， tóu rù dào gāo kē jì gōng sī de qián jiào shǎo。","meaning":"Last year less of the money went into high-technology companies.","meaningThai":"ปีที่แล้วเงินน้อยลงไปให้กับบริษัทเทคโนโลยีชั้นสูง"},{"chinese":"目前劳务市场上仅有的一些亮点是小企业和新创办的高科技公司。","pinyin":"Mù qián láo wù shì cháng shàng jǐn yǒu de yī xiē liàng diǎn shì xiǎo qǐ yè hé xīn chuàng bàn de gāo kē jì gōng sī。","meaning":"For now the only bright spots in the labour market are small businesses and high-tech startups.","meaningThai":"ในตอนนี้จุดสว่างเพียงแห่งเดียวในตลาดแรงงานคือธุรกิจขนาดเล็กและสตาร์ทอัพที่มีเทคโนโลยีสูง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-393","chinese":"高效","pinyin":"gāoxiào","meaning":"efficient; highly effective","meaningThai":"มีประสิทธิภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我工作高效、决策果断而且判断准确。","pinyin":"Wǒ gōng zuò gāo xiào、 jué cè guǒ duàn ér qiě pàn duàn zhǔn què。","meaning":"I work very efficiently and am decisive, and accurate in my judgement.","meaningThai":"ฉันทำงานอย่างมีประสิทธิผลมาก มีความเด็ดขาด และแม่นยำในการตัดสิน"},{"chinese":"石墨是一种高效的电导体。","pinyin":"Shí mò shì yī zhǒng gāo xiào de diàn dǎo tǐ。","meaning":"Graphite is a highly efficient conductor of electricity.","meaningThai":"กราไฟท์เป็นตัวนำไฟฟ้าที่มีประสิทธิภาพสูง"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-394","chinese":"隔","pinyin":"gé","meaning":"to separate; to partition; to stand or lie between; at a distance from; after or at an interval of","meaningThai":"แยกออกจากกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这间屋子被隔为三小间。","pinyin":"Zhè jiān wū zǐ bèi gé wéi sān xiǎo jiān。","meaning":"The room is partitioned into three sections.","meaningThai":"ห้องแบ่งออกเป็นสามส่วน"},{"chinese":"龟蛇二山隔江相望。","pinyin":"Guī shé èr shān gé jiāng xiāng wàng。","meaning":"Tortoise and Snake Hills face each other across the river.","meaningThai":"เนินเขาเต่าและงูเผชิญหน้ากันข้ามแม่น้ำ"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-395","chinese":"个别","pinyin":"gèbié","meaning":"individually; one by one; just one or two; exceptional; rare","meaningThai":"รายบุคคล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"为了满足个别需要，大多数旅行社都愿意做出专门的旅游安排。","pinyin":"Wéi le mǎn zú gè bié xū yào， dà duō shù lǚ háng shè dū yuàn yì zuò chū zhuān mén de lǚ yóu ān pái。","meaning":"Most travel agents are prepared to tailor travel arrange we are pirates, these data are stolen from youdao s to meet individual require we are pirates, these data are stolen from youdao s.","meaningThai":"ตัวแทนการท่องเที่ยวส่วนใหญ่ยินดีจัดเตรียมการเดินทางแบบพิเศษให้เหมาะกับความต้องการของแต่ละบุคคล"},{"chinese":"警方称这次袭击只是个别事件。","pinyin":"Jǐng fāng chēng zhè cì xí jī zhī shì gè bié shì jiàn。","meaning":"The police said the attack was an isolated incident.","meaningThai":"ตำรวจกล่าวว่าการโจมตีเป็นเหตุการณ์ที่เกิดขึ้นเดี่ยวๆ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-396","chinese":"歌词","pinyin":"gēcí","meaning":"song lyric; lyrics","meaningThai":"เนื้อเพลง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"听听曲调，看你能否记起歌词。","pinyin":"Tīng tīng qū tiáo， kàn nǐ néng fǒu jì qǐ gē cí。","meaning":"Listen to the tune and see if you can remember the words.","meaningThai":"ฟังเพลงและดูว่าคุณสามารถจำคำศัพท์ได้หรือไม่"},{"chinese":"这张光盘配有歌曲的全部歌词。","pinyin":"Zhè zhāng guāng pán pèi yǒu gē qū de quán bù gē cí。","meaning":"The CD comes complete with all the words of the songs.","meaningThai":"แผ่นซีดีมีเนื้อเพลงครบทุกเพลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-397","chinese":"各行各业","pinyin":"gèháng-gèyè","meaning":"All walks of life","meaningThai":"ทุกสาขาอาชีพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这份工作最大的乐趣之一就是结识来自各行各业的人。","pinyin":"Zhè fèn gōng zuò zuì dà de lè qù zhī yī jiù shì jié shí lái zì gè háng gè yè de rén。","meaning":"One of the greatest pleasures of this job is meeting people from all walks of life.","meaningThai":"ความสุขที่ยิ่งใหญ่ที่สุดของงานนี้คือการได้พบปะผู้คนจากทุกสาขาอาชีพ"},{"chinese":"各行各业的人都喜欢在运河边聚会。","pinyin":"Gè háng gè yè de rén dū xǐ huān zài yùn hé biān jù huì。","meaning":"People from all walks of life preferred to get together along the canal.","meaningThai":"ผู้คนจากทุกสาขาอาชีพนิยมมารวมตัวกันริมคลอง"}]},
  {"id":"hsk5-398","chinese":"根","pinyin":"gēn","meaning":"root; basis; classifier for long slender objects, e.g. cigarettes, guitar strings; radical (chemistry)","meaningThai":"ราก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他划了根火柴，然后伸长胳膊举着。","pinyin":"Tā huá le gēn huǒ chái， rán hòu shēn cháng gē bó jǔ zháo。","meaning":"He struck a match, and held it at arm's length.","meaningThai":"เขาตีไม้ขีดและถือมันไว้จนสุดแขน"},{"chinese":"你断了一根肋骨，也许不止一根。","pinyin":"Nǐ duàn le yī gēn lèi gǔ， yě xǔ bù zhǐ yī gēn。","meaning":"You've fractured a rib, maybe more than one.","meaningThai":"คุณกระดูกซี่โครงหัก อาจมากกว่าหนึ่งซี่"}],"partOfSpeech":["measure word","noun"]},
  {"id":"hsk5-399","chinese":"根本","pinyin":"gēnběn","meaning":"fundamental; basic; root; simply; absolutely (not); (not) at all","meaningThai":"พื้นฐาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那根本不是真的！","pinyin":"Nà gēn běn bù shì zhēn de！","meaning":"That is simply not true!","meaningThai":"นั่นไม่เป็นความจริงเลย!"},{"chinese":"态度发生了根本的变化。","pinyin":"Tài dù fā shēng le gēn běn de biàn huà。","meaning":"Attitudes have changed radically.","meaningThai":"ทัศนคติมีการเปลี่ยนแปลงอย่างรุนแรง"}],"partOfSpeech":["adverb","noun","adjective"]},
  {"id":"hsk5-400","chinese":"更换","pinyin":"gēnghuàn","meaning":"to replace (a worn-out tire etc); to change (one's address etc)","meaningThai":"แทนที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我考虑更换工作。","pinyin":"Wǒ kǎo lǜ gēng huàn gōng zuò。","meaning":"I considered changing my job.","meaningThai":"ฉันคิดที่จะเปลี่ยนงาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-401","chinese":"更新","pinyin":"gēngxīn","meaning":"to replace the old with new; to renew; to renovate; to upgrade; to update; to regenerate","meaningThai":"ต่ออายุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"高等教育事业中人员更新很少。","pinyin":"Gāo děng jiào yù shì yè zhōng rén yuán gēng xīn hěn shǎo。","meaning":"There has been very little renewal of personnel in higher education.","meaningThai":"มีการต่ออายุบุคลากรในระดับอุดมศึกษาน้อยมาก"},{"chinese":"公司花了几千英镑更新计算机系统。","pinyin":"Gōng sī huā le jī qiān yīng bàng gēng xīn jì suàn jī xì tǒng。","meaning":"The company has spent thousands of pounds updating their computer systems.","meaningThai":"บริษัทได้ใช้เงินหลายพันปอนด์ในการอัปเดตระบบคอมพิวเตอร์ของตน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-402","chinese":"歌曲","pinyin":"gēqǔ","meaning":"song","meaningThai":"เพลง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这张光盘配有歌曲的全部歌词。","pinyin":"Zhè zhāng guāng pán pèi yǒu gē qū de quán bù gē cí。","meaning":"The CD comes complete with all the words of the songs.","meaningThai":"แผ่นซีดีมีเนื้อเพลงครบทุกเพลง"},{"chinese":"这是他最受喜爱的歌曲之一。","pinyin":"Zhè shì tā zuì shòu xǐ ài de gē qū zhī yī。","meaning":"It was one of his best-loved songs.","meaningThai":"มันเป็นหนึ่งในเพลงที่เขาชื่นชอบที่สุด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-403","chinese":"个人","pinyin":"gèrén","meaning":"individual; personal; oneself","meaningThai":"ส่วนตัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"每个人我都请了，却只来了两个人。","pinyin":"Měi gè rén wǒ dū qǐng le， què zhī lái le liǎng gè rén。","meaning":"I'd asked everybody but only two people came.","meaningThai":"ฉันถามทุกคนแล้ว แต่มาแค่สองคน"},{"chinese":"我这个人讲究整洁。","pinyin":"Wǒ zhè gè rén jiǎng jiū zhěng jié。","meaning":"I'm a tidy person.","meaningThai":"ฉันเป็นคนเรียบร้อย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-404","chinese":"格外","pinyin":"géwài","meaning":"especially; particularly","meaningThai":"โดยเฉพาะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你要格外小心，别犯错误。","pinyin":"Nǐ yào gé wài xiǎo xīn， bié fàn cuò wù。","meaning":"You need to be extra careful not to make any mistakes.","meaningThai":"คุณจะต้องระมัดระวังเป็นพิเศษที่จะไม่ทำผิดพลาดใดๆ"},{"chinese":"进展一直格外令人失望。","pinyin":"Jìn zhǎn yī zhí gé wài líng rén shī wàng。","meaning":"Progress has been particularly disappointing.","meaningThai":"ความคืบหน้าน่าผิดหวังอย่างยิ่ง"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-405","chinese":"个性","pinyin":"gèxìng","meaning":"individuality; personality","meaningThai":"บุคลิกภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"嘉利•梅个性鲜明，热情洋溢。","pinyin":"Jiā lì • méi gè xìng xiān míng， rè qíng yáng yì。","meaning":"Kerrie Mae had an extraordinary, incandescent personality.","meaningThai":"เคอร์รี เมมีบุคลิกที่สดใสและโดดเด่นเป็นพิเศษ"},{"chinese":"她有个如此招人喜爱的个性。","pinyin":"Tā yǒu gè rú cǐ zhāo rén xǐ ài de gè xìng。","meaning":"She has such an endearing personality.","meaningThai":"เธอมีบุคลิกที่น่ารักเช่นนี้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-406","chinese":"各自","pinyin":"gèzì","meaning":"each; respective; apiece","meaningThai":"ตามลำดับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们在各自的领域都被视为专家。","pinyin":"Tā mén zài gè zì de lǐng yù dū bèi shì wéi zhuān jiā。","meaning":"They are each recognized specialists in their respective fields.","meaningThai":"พวกเขาแต่ละคนเป็นผู้เชี่ยวชาญที่ได้รับการยอมรับในสาขาของตน"},{"chinese":"本课程允许学生按各自的速度学习。","pinyin":"Běn kè chéng yǔn xǔ xué shēng àn gè zì de sù dù xué xí。","meaning":"The course allows students to progress at their own speed.","meaningThai":"หลักสูตรนี้ช่วยให้นักเรียนก้าวหน้าได้ตามความเร็วของตนเอง"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-407","chinese":"公布","pinyin":"gōngbù","meaning":"to announce; to make public; to publish","meaningThai":"ประกาศ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"最终选举结果将在周五被公布。","pinyin":"Zuì zhōng xuǎn jǔ jié guǒ jiāng zài zhōu wǔ bèi gōng bù。","meaning":"The final election results will be announced on Friday.","meaningThai":"ผลการเลือกตั้งครั้งสุดท้ายจะประกาศในวันศุกร์"},{"chinese":"竞赛的获胜者将于下月公布。","pinyin":"Jìng sài de huò shèng zhě jiāng yú xià yuè gōng bù。","meaning":"The winners of the competition will be announced next month.","meaningThai":"ผู้ชนะการแข่งขันจะประกาศผลในเดือนหน้า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-408","chinese":"工程","pinyin":"gōngchéng","meaning":"engineering; an engineering project; project; undertaking","meaningThai":"โครงการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们祝贺他们工程顺利竣工。","pinyin":"Wǒ mén zhù hè tā mén gōng chéng shùn lì jùn gōng。","meaning":"We congratulated them on the successful completion of the project.","meaningThai":"เราขอแสดงความยินดีกับพวกเขาที่ความสำเร็จของโครงการนี้"},{"chinese":"这项工程开始显出成效。","pinyin":"Zhè xiàng gōng chéng kāi shǐ xiǎn chū chéng xiào。","meaning":"The project is beginning to show results.","meaningThai":"โครงการเริ่มแสดงผลแล้ว."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-409","chinese":"工程师","pinyin":"gōngchéngshī","meaning":"engineer","meaningThai":"วิศวกร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"工程师对轨道进行了彻底检查。","pinyin":"Gōng chéng shī duì guǐ dào jìn háng le chè dǐ jiǎn chá。","meaning":"Engineers carried out a thorough inspection of the track.","meaningThai":"วิศวกรได้ทำการตรวจสอบเส้นทางอย่างละเอียด"},{"chinese":"军队称赞他为杰出能干的工程师。","pinyin":"Jūn duì chēng zàn tā wéi jié chū néng gān de gōng chéng shī。","meaning":"The army recognized him as an outstandingly able engineer.","meaningThai":"กองทัพยอมรับว่าเขาเป็นวิศวกรที่มีความสามารถโดดเด่น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-410","chinese":"工具","pinyin":"gōngjù","meaning":"tool; instrument; utensil; means (to achieve a goal etc)","meaningThai":"เครื่องมือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这台研磨机用于制作精细工具。","pinyin":"Zhè tái yán mó jī yòng yú zhì zuò jīng xì gōng jù。","meaning":"The grinder is used for making precision tooling.","meaningThai":"เครื่องบดใช้สำหรับทำเครื่องมือที่มีความแม่นยำ"},{"chinese":"这个工具是用来加工木料的。","pinyin":"Zhè gè gōng jù shì yòng lái jiā gōng mù liào de。","meaning":"This tool is used for shaping wood.","meaningThai":"เครื่องมือนี้ใช้สำหรับการขึ้นรูปไม้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-411","chinese":"功能","pinyin":"gōngnéng","meaning":"function; capability","meaningThai":"การทำงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"现在已有可能了解大脑的各种功能。","pinyin":"Xiàn zài yǐ yǒu kě néng le jiě dà nǎo de gè zhǒng gōng néng。","meaning":"It is now possible to map the different functions of the brain.","meaningThai":"ตอนนี้คุณสามารถสร้างแผนผังการทำงานต่างๆ ของสมองได้แล้ว"},{"chinese":"心脏的功能就是把血液输往全身。","pinyin":"Xīn zāng de gōng néng jiù shì bǎ xiě yè shū wǎng quán shēn。","meaning":"The function of the heart is to pump blood through the body.","meaningThai":"หน้าที่ของหัวใจคือการสูบฉีดเลือดไปทั่วร่างกาย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-412","chinese":"公平","pinyin":"gōngpíng","meaning":"fair; impartial","meaningThai":"ยุติธรรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的垮台也算是大致公平。","pinyin":"Tā de kuǎ tái yě suàn shì dà zhì gōng píng。","meaning":"There was a certain amount of rough justice in his downfall.","meaningThai":"มีความยุติธรรมหยาบจำนวนหนึ่งในการล่มสลายของเขา"},{"chinese":"“这不公平。”她抱怨道。","pinyin":"“ zhè bù gōng píng。” tā bào yuàn dào。","meaning":"'It's not fair,' she complained.","meaningThai":"“มันไม่ยุติธรรมเลย” เธอบ่น"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-413","chinese":"公务员","pinyin":"gōngwùyuán","meaning":"functionary; office-bearer","meaningThai":"ข้าราชการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他是一个忠诚、出色、很有能力的公务员。","pinyin":"Tā shì yī gè zhōng chéng、 chū sè、 hěn yǒu néng lì de gōng wù yuán。","meaning":"He was a loyal, distinguished and very competent civil servant.","meaningThai":"เขาเป็นข้าราชการที่มีความจงรักภักดี มีชื่อเสียง และมีความสามารถมาก"},{"chinese":"他以公务员的工作作为搞间谍活动的掩护。","pinyin":"Tā yǐ gōng wù yuán de gōng zuò zuò wéi gǎo jiān dié huó dòng de yǎn hù。","meaning":"His work as a civil servant was a cover for his activities as a spy.","meaningThai":"งานของเขาในฐานะข้าราชการเป็นเพียงการปกปิดกิจกรรมของเขาในฐานะสายลับ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-414","chinese":"恭喜","pinyin":"gōngxǐ","meaning":"to congratulate; (interj.) congratulations!","meaningThai":"ยินดีด้วย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"恭喜成為本店第一千位顧客！","pinyin":"Gōng xǐ chéng wéi běn diàn dì yī qiān wèi gù kè！","meaning":"Congratulations! You are our thousandth visitor!","meaningThai":"ยินดีด้วย! คุณคือผู้เยี่ยมชมคนที่พันของเรา!"},{"chinese":"我听说你通过了入学考试。恭喜你了！","pinyin":"Wǒ tīng shuō nǐ tōng guò le rù xué kǎo shì。 gōng xǐ nǐ le！","meaning":"I hear you passed the entrance exam. Congratulations!","meaningThai":"ฉันได้ยินมาว่าคุณสอบผ่าน ยินดีด้วย!"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-415","chinese":"贡献","pinyin":"gòngxiàn","meaning":"to contribute; to dedicate; to devote; contribution","meaningThai":"การมีส่วนร่วม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"做出贡献。","pinyin":"Zuo chu gong xian.","meaning":"Make a contribution.","meaningThai":"บริจาค."}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-416","chinese":"共享","pinyin":"gòngxiǎng","meaning":"to share; to enjoy together","meaningThai":"แบ่งปัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"是的，我想和你共享生活。","pinyin":"Shì de， wǒ xiǎng hé nǐ gòng xiǎng shēng huó。","meaning":"Yes, I want to share my life with you.","meaningThai":"ใช่ ฉันต้องการแบ่งปันชีวิตของฉันกับคุณ"},{"chinese":"丹尼自愿与任何感兴趣者共享他的知识。","pinyin":"Dān ní zì yuàn yǔ rèn hé gǎn xīng qù zhě gòng xiǎng tā de zhī shí。","meaning":"Danny shared his knowledge freely with anyone interested.","meaningThai":"แดนนี่แบ่งปันความรู้ของเขาอย่างเสรีกับทุกคนที่สนใจ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-417","chinese":"工业","pinyin":"gōngyè","meaning":"industry","meaningThai":"อุตสาหกรรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"电力工业消耗大量的矿物燃料。","pinyin":"Diàn lì gōng yè xiāo hào dà liáng de kuàng wù rán liào。","meaning":"The electricity industry consumes large amounts of fossil fuels.","meaningThai":"อุตสาหกรรมไฟฟ้าใช้เชื้อเพลิงฟอสซิลจำนวนมาก"},{"chinese":"政府已保证要清除工业排放物。","pinyin":"Zhèng fǔ yǐ bǎo zhèng yào qīng chú gōng yè pái fàng wù。","meaning":"The government has pledged to clean up industrial emissions.","meaningThai":"รัฐบาลได้ให้คำมั่นที่จะทำความสะอาดการปล่อยก๊าซเรือนกระจกทางอุตสาหกรรม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-418","chinese":"工艺","pinyin":"gōngyì","meaning":"arts and crafts; industrial arts","meaningThai":"งานฝีมือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"低等的手工艺品；感到比他的兄妹们低一等","pinyin":"Dī děng de shǒu gōng yì pǐn； gǎn dào bǐ tā de xiōng mèi mén dī yī děng","meaning":"Inferior craft; felt inferior to his older sibling.","meaningThai":"ฝีมือด้อยกว่า; รู้สึกด้อยกว่าพี่ชายของเขา"},{"chinese":"在未来，国与国之间的竞争将越来越以工艺技术为基础。","pinyin":"Zài wèi lái， guó yǔ guó zhī jiān de jìng zhēng jiāng yuè lái yuè yǐ gōng yì jì shù wéi jī chǔ。","meaning":"For the future, competition between nations will be increasingly based on technological skill.","meaningThai":"สำหรับอนาคตการแข่งขันระหว่างประเทศจะขึ้นอยู่กับทักษะทางเทคโนโลยีมากขึ้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-419","chinese":"公寓","pinyin":"gōngyù","meaning":"apartment building; block of flats","meaningThai":"อพาร์ทเมนต์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"安妮回到公寓时早已过了午夜。","pinyin":"Ān nī huí dào gōng yù shí zǎo yǐ guò le wǔ yè。","meaning":"It was well after midnight by the time Anne returned to her apartment.","meaningThai":"เป็นเวลาหลังเที่ยงคืนพอดีที่แอนน์กลับมาที่อพาร์ตเมนต์ของเธอ"},{"chinese":"公寓里面到处都是老鼠和蟑螂。","pinyin":"Gōng yù lǐ miàn dào chǔ dū shì lǎo shǔ hé zhāng láng。","meaning":"The apartments were infested with rats and roaches.","meaningThai":"อพาร์ทเมนท์เต็มไปด้วยหนูและแมลงสาบ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-420","chinese":"构成","pinyin":"gòuchéng","meaning":"to constitute; to form; to compose; to make up; to configure (computing)","meaningThai":"ประกอบด้วย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些画将构成新的收藏系列的基础。","pinyin":"Zhè xiē huà jiāng gòu chéng xīn de shōu cáng xì liè de jī chǔ。","meaning":"These paintings will form the nucleus of a new collection.","meaningThai":"ภาพวาดเหล่านี้จะสร้างแกนกลางของคอลเลกชันใหม่"},{"chinese":"女警察构成警力的13%。","pinyin":"Nǚ jǐng chá gòu chéng jǐng lì de13%。","meaning":"Women officers make up 13 percent of the police force.","meaningThai":"เจ้าหน้าที่หญิงคิดเป็นร้อยละ 13 ของกำลังตำรวจ"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-421","chinese":"沟通","pinyin":"gōutōng","meaning":"to join; to connect; to link up; to communicate","meaningThai":"สื่อสาร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"沟通很重要。","pinyin":"Gou tong hen zhong yao.","meaning":"Communication is important.","meaningThai":"การสื่อสารเป็นสิ่งสำคัญ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-422","chinese":"古","pinyin":"gǔ","meaning":"surname Gu","meaningThai":"สมัยโบราณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"拉古纳峡谷路的北行道又被封了。","pinyin":"Lā gǔ nà xiá gǔ lù de běi háng dào yòu bèi fēng le。","meaning":"Laguna Canyon Road was blocked off again northbound.","meaningThai":"ถนนลากูน่าแคนยอนถูกบล็อกไปทางเหนืออีกครั้ง"},{"chinese":"雷姆森大街与蒙塔古大街是平行的。","pinyin":"Léi mǔ sēn dà jiē yǔ mēng tǎ gǔ dà jiē shì píng háng de。","meaning":"Remsen Street is parallel with Montague Street.","meaningThai":"ถนน Remsen ขนานกับถนน Montague"}],"partOfSpeech":["adjective","noun"]},
  {"id":"hsk5-423","chinese":"鼓","pinyin":"gǔ","meaning":"old variant of 鼓","meaningThai":"กลอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"鼓是非洲音乐的基本乐器。","pinyin":"Gǔ shì fēi zhōu yīn lè de jī běn lè qì。","meaning":"Drums are basic to African music.","meaningThai":"กลองเป็นพื้นฐานของดนตรีแอฟริกัน"},{"chinese":"鼓是最古老的乐器之一。","pinyin":"Gǔ shì zuì gǔ lǎo de lè qì zhī yī。","meaning":"The drum is one of the oldest musical instruments.","meaningThai":"กลองเป็นหนึ่งในเครื่องดนตรีที่เก่าแก่ที่สุด"}],"partOfSpeech":["verb","noun","other","adjective"]},
  {"id":"hsk5-424","chinese":"挂号","pinyin":"guàhào","meaning":"to register (at a hospital etc); to send by registered mail","meaningThai":"ลงทะเบียนแล้ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他让他妈妈用挂号邮件寄。","pinyin":"Tā ràng tā mā mā yòng guà hào yóu jiàn jì。","meaning":"He asked his mother to send it by registered mail.","meaningThai":"เขาขอให้แม่ส่งทางไปรษณีย์ลงทะเบียน"},{"chinese":"你这封信要不要挂号？","pinyin":"Nǐ zhè fēng xìn yào bù yào guà hào？","meaning":"Do you want to have this letter registered?","meaningThai":"คุณต้องการลงทะเบียนจดหมายนี้หรือไม่?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-425","chinese":"怪","pinyin":"guài","meaning":"bewildering; odd; strange; uncanny; devil; monster; to wonder at; to blame; quite; rather","meaningThai":"แปลก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这音乐有些地方有点怪。","pinyin":"Zhè yīn lè yǒu xiē dì fāng yǒu diǎn guài。","meaning":"Some of the music was weird.","meaningThai":"เพลงบางเพลงก็แปลกๆ"},{"chinese":"这个城镇怪面熟的。","pinyin":"Zhè gè chéng zhèn guài miàn shú de。","meaning":"The town was weirdly familiar.","meaningThai":"เมืองนี้คุ้นเคยอย่างประหลาด"}],"partOfSpeech":["verb","adjective","adverb"]},
  {"id":"hsk5-426","chinese":"关闭","pinyin":"guānbì","meaning":"to close; to shut (a window etc); (of a shop, school etc) to shut down","meaningThai":"ปิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"关闭他妈的门啊！","pinyin":"Guān bì tā mā de mén ā！","meaning":"Close the fucking door!","meaningThai":"ปิดประตูไอ้บ้า!"},{"chinese":"他们今天关闭。","pinyin":"Tā mén jīn tiān guān bì。","meaning":"They're closed today.","meaningThai":"วันนี้พวกเขาปิดแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-427","chinese":"观察","pinyin":"guānchá","meaning":"to observe; to watch; to survey","meaningThai":"สังเกต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们曾观察过这些动物的习性。","pinyin":"Tā mén zēng guān chá guò zhè xiē dòng wù de xí xìng。","meaning":"They had observed regularities in the behaviour of the animals.","meaningThai":"พวกเขาสังเกตเห็นความสม่ำเสมอในพฤติกรรมของสัตว์"},{"chinese":"奥尔森还研究并观察婴儿的行为。","pinyin":"Ào ěr sēn huán yán jiū bìng guān chá yīng ér de háng wéi。","meaning":"Olson also studies and observes the behaviour of babies.","meaningThai":"โอลสันยังศึกษาและสังเกตพฤติกรรมของเด็กทารกด้วย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-428","chinese":"观点","pinyin":"guāndiǎn","meaning":"point of view; viewpoint; standpoint","meaningThai":"มุมมอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"观点因人而异。","pinyin":"Guān diǎn yīn rén ér yì。","meaning":"Opinions vary from person to person.","meaningThai":"ความคิดเห็นแตกต่างกันไปในแต่ละบุคคล"},{"chinese":"你为什么问我的观点？","pinyin":"Nǐ wéi shí mó wèn wǒ de guān diǎn？","meaning":"Why are you asking my opinion?","meaningThai":"ทำไมคุณถึงถามความคิดเห็นของฉัน?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-429","chinese":"广","pinyin":"guǎng","meaning":"\"house on a cliff\" radical in Chinese characters (Kangxi radical 53), occurring in 店, 序, 底 etc","meaningThai":"กว้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该公司在这个国家开设的饭店地理分布相当广。","pinyin":"Gāi gōng sī zài zhè gè guó jiā kāi shè de fàn diàn dì lǐ fēn bù xiāng dāng guǎng。","meaning":"The company has a good geographical spread of hotels in this country.","meaningThai":"บริษัทมีการกระจายโรงแรมทางภูมิศาสตร์ที่ดีในประเทศนี้"},{"chinese":"他名叫广志，但人们都称他广。","pinyin":"Tā míng jiào guǎng zhì， dàn rén mén dū chēng tā guǎng。","meaning":"His name's Hiroshi but everyone calls him Hiro.","meaningThai":"เขาชื่อฮิโรชิ แต่ใครๆ ก็เรียกเขาว่าฮิโระ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-430","chinese":"广场","pinyin":"guǎngchǎng","meaning":"public square; plaza","meaningThai":"สี่เหลี่ยม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"设置的路障控制人流涌向广场。","pinyin":"Shè zhì de lù zhàng kòng zhì rén liú yǒng xiàng guǎng cháng。","meaning":"Barricades funnelled the crowds towards the square.","meaningThai":"เครื่องกีดขวางส่งฝูงชนไปทางจัตุรัส"},{"chinese":"街道豁然变宽，成为一个小广场。","pinyin":"Jiē dào huō rán biàn kuān， chéng wéi yī gè xiǎo guǎng cháng。","meaning":"The street opened out into a small square.","meaningThai":"ถนนเปิดออกเป็นจัตุรัสเล็กๆ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-431","chinese":"广大","pinyin":"guǎngdà","meaning":"(of an area) vast or extensive; large-scale; widespread; (of people) numerous","meaningThai":"กว้างใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"开发建设影响了乡村广大地区。","pinyin":"Kāi fā jiàn shè yǐng xiǎng le xiāng cūn guǎng dà dì qū。","meaning":"Development has affected vast swathes of our countryside.","meaningThai":"การพัฒนาได้ส่งผลกระทบต่อพื้นที่อันกว้างใหญ่ในชนบทของเรา"},{"chinese":"该中心对于广大公众来讲很便利。","pinyin":"Gāi zhōng xīn duì yú guǎng dà gōng zhòng lái jiǎng hěn biàn lì。","meaning":"The centre is easily accessible to the general public.","meaningThai":"ประชาชนทั่วไปสามารถเข้าถึงศูนย์ได้อย่างง่ายดาย"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-432","chinese":"广泛","pinyin":"guǎngfàn","meaning":"extensive; wide range","meaningThai":"อย่างกว้างขวาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"广泛应用。","pinyin":"Guang fan ying yong.","meaning":"Widely used.","meaningThai":"ใช้กันอย่างแพร่หลาย"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-433","chinese":"光临","pinyin":"guānglín","meaning":"(formal) to honor with one's presence; to attend","meaningThai":"เยี่ยม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"讲话前先感谢大家光临，这是惯例。","pinyin":"Jiǎng huà qián xiān gǎn xiè dà jiā guāng lín， zhè shì guàn lì。","meaning":"It is usual to start a speech by thanking everybody for coming.","meaningThai":"เป็นเรื่องปกติที่จะเริ่มกล่าวขอบคุณทุกคนที่มา"},{"chinese":"最后，我感谢大家今天的光临。","pinyin":"Zuì hòu， wǒ gǎn xiè dà jiā jīn tiān de guāng lín。","meaning":"And finally, I would like to thank you all for coming here today.","meaningThai":"และสุดท้ายนี้ผมขอขอบคุณทุกท่านที่มาในวันนี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-434","chinese":"光明","pinyin":"guāngmíng","meaning":"light; radiance; (fig.) bright (prospects etc); openhearted","meaningThai":"สว่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"古巴属于热带气候，终年阳光明媚。","pinyin":"Gǔ bā shǔ yú rè dài qì hòu， zhōng nián yáng guāng míng mèi。","meaning":"Cuba has a tropical climate with year-round sunshine.","meaningThai":"คิวบามีภูมิอากาศแบบเขตร้อนและมีแสงแดดตลอดทั้งปี"},{"chinese":"用光明与黑暗来象征善与恶。","pinyin":"Yòng guāng míng yǔ hēi àn lái xiàng zhēng shàn yǔ è。","meaning":"The use of light and dark symbolizes good and evil.","meaningThai":"การใช้แสงสว่างและความมืดเป็นสัญลักษณ์ของความดีและความชั่ว"}],"partOfSpeech":["noun","adjective"]},
  {"id":"hsk5-435","chinese":"光线","pinyin":"guāngxiàn","meaning":"light ray; light; illumination; lighting (for a photograph)","meaningThai":"แสงสว่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是用来阻挡太阳直射光线的。","pinyin":"Zhè shì yòng lái zǔ dǎng tài yáng zhí shè guāng xiàn de。","meaning":"This was intended to exclude the direct rays of the sun.","meaningThai":"สิ่งนี้มีจุดมุ่งหมายเพื่อยกเว้นรังสีโดยตรงของดวงอาทิตย์"},{"chinese":"在这儿的山里，光线减弱得更快了。","pinyin":"Zài zhè ér de shān lǐ， guāng xiàn jiǎn ruò dé gēng kuài le。","meaning":"Here in the hills, the light failed more quickly.","meaningThai":"ที่นี่บนเนินเขา แสงดับเร็วขึ้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-436","chinese":"冠军","pinyin":"guànjūn","meaning":"champion","meaningThai":"แชมป์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"下周我们要和联赛冠军队比赛。","pinyin":"Xià zhōu wǒ mén yào hé lián sài guān jūn duì bǐ sài。","meaning":"We're playing against the league champions next week.","meaningThai":"เรากำลังเล่นกับแชมป์ลีกในสัปดาห์หน้า"},{"chinese":"联队是上个赛季的联赛冠军。","pinyin":"Lián duì shì shàng gè sài jì de lián sài guān jūn。","meaning":"United were league champions last season.","meaningThai":"ยูไนเต็ดเป็นแชมป์ลีกเมื่อฤดูกาลที่แล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-437","chinese":"观念","pinyin":"guānniàn","meaning":"notion; thought; concept; sense; views; ideology; general impressions","meaningThai":"แนวคิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"十年过去，最初的观念依然适用。","pinyin":"Shí nián guò qù， zuì chū de guān niàn yī rán shì yòng。","meaning":"Ten years on, the original concept was wearing well.","meaningThai":"สิบปีผ่านไป แนวคิดดั้งเดิมก็ดูดี"},{"chinese":"绝对个人自由的观念是一种幻想。","pinyin":"Jué duì gè rén zì yóu de guān niàn shì yī zhǒng huàn xiǎng。","meaning":"The idea of absolute personal freedom is an illusion.","meaningThai":"ความคิดเรื่องอิสรภาพส่วนบุคคลที่สมบูรณ์นั้นเป็นเพียงภาพลวงตา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-438","chinese":"古代","pinyin":"gǔdài","meaning":"ancient times","meaningThai":"สมัยโบราณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在死海边的洞穴里发现了古代的卷轴。","pinyin":"Zài sǐ hǎi biān de dòng xué lǐ fā xiàn le gǔ dài de juàn zhóu。","meaning":"Ancient scrolls were found in caves by the Dead Sea.","meaningThai":"ม้วนหนังสือโบราณถูกพบในถ้ำใกล้ทะเลเดดซี"},{"chinese":"现代猫的直系物种原型是古代埃及的卡菲尔猫。","pinyin":"Xiàn dài māo de zhí xì wù zhǒng yuán xíng shì gǔ dài āi jí de kǎ fēi ěr māo。","meaning":"The direct ancestor of the modern cat was the Kaffir cat of ancient Egypt.","meaningThai":"บรรพบุรุษโดยตรงของแมวสมัยใหม่คือแมว Kaffir ของอียิปต์โบราณ"}],"partOfSpeech":["other"]},
  {"id":"hsk5-439","chinese":"固定","pinyin":"gùdìng","meaning":"to fix; to fasten; to set rigidly in place; fixed; set; regular","meaningThai":"ที่ตายตัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"它是固定在墙上的。","pinyin":"Tā shì gù dìng zài qiáng shàng de。","meaning":"It is fixed on the wall.","meaningThai":"ได้รับการแก้ไขบนผนัง"},{"chinese":"固定这个轮子的几个螺栓断了。","pinyin":"Gù dìng zhè gè lún zǐ de jī gè luó shuān duàn le。","meaning":"The bolts holding the wheel in place sheared off.","meaningThai":"น็อตที่ยึดล้ออยู่กับที่ก็หลุดออกไป"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-440","chinese":"规律","pinyin":"guīlǜ","meaning":"rule (e.g. of science); law of behavior; regular pattern; rhythm; discipline","meaningThai":"กฎ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"自然规律是绝对确凿的。","pinyin":"Zì rán guī lǜ shì jué duì què záo de。","meaning":"The laws of nature are absolute.","meaningThai":"กฎแห่งธรรมชาติเป็นสิ่งแน่นอน"},{"chinese":"他在自己的绘画艺术中打破了科学的直线透视法规律。","pinyin":"Tā zài zì jǐ de huì huà yì shù zhōng dǎ pò le kē xué de zhí xiàn tòu shì fǎ guī lǜ。","meaning":"In his art he broke the laws of scientific linear perspective.","meaningThai":"ในงานศิลปะของเขา เขาฝ่าฝืนกฎของมุมมองเชิงเส้นทางวิทยาศาสตร์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-441","chinese":"规模","pinyin":"guīmó","meaning":"scale; scope; extent","meaningThai":"มาตราส่วน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这座建筑的规模和设计气势宏伟。","pinyin":"Zhè zuò jiàn zhù de guī mó hé shè jì qì shì hóng wěi。","meaning":"The building was awe-inspiring in size and design.","meaningThai":"ตัวอาคารมีขนาดและการออกแบบที่น่าทึ่งมาก"},{"chinese":"这种规模的灾难是空前的。","pinyin":"Zhè zhǒng guī mó de zāi nán shì kōng qián de。","meaning":"There is no precedent for a disaster of this scale.","meaningThai":"ไม่มีกรณีตัวอย่างสำหรับภัยพิบัติขนาดนี้"}],"partOfSpeech":["noun","adverb"]},
  {"id":"hsk5-442","chinese":"贵姓","pinyin":"guìxìng","meaning":"your surname","meaningThai":"นามสกุลของคุณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"王先生/王小姐：免贵姓王。","pinyin":"Wáng xiān shēng / wáng xiǎo jiě： miǎn guì xìng wáng。","meaning":"Mr./Miss Wang: My surname is Wang.","meaningThai":"นาย/นางสาวหวาง: ฉันนามสกุลหวาง"},{"chinese":"我连您贵姓也还不知道。","pinyin":"Wǒ lián nín guì xìng yě huán bù zhī dào。","meaning":"I do not even know your name.","meaningThai":"ฉันไม่รู้ชื่อของคุณด้วยซ้ำ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-443","chinese":"规则","pinyin":"guīzé","meaning":"rule; regulation; rules and regulations","meaningThai":"กฎ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这项规则是为此特意推行的。","pinyin":"Zhè xiàng guī zé shì wéi cǐ tè yì tuī háng de。","meaning":"The rule was introduced expressly for this purpose.","meaningThai":"กฎนี้ถูกนำมาใช้อย่างชัดเจนเพื่อจุดประสงค์นี้"},{"chinese":"这些规则是不会突然改变的。","pinyin":"Zhè xiē guī zé shì bù huì tū rán gǎi biàn de。","meaning":"The rules are not going to change overnight.","meaningThai":"กฎจะไม่เปลี่ยนแปลงในชั่วข้ามคืน"}],"partOfSpeech":["noun","adjective"]},
  {"id":"hsk5-444","chinese":"柜子","pinyin":"guìzi","meaning":"cupboard; cabinet","meaningThai":"ตู้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个柜子是橡木做的，并且经手工雕刻而成。","pinyin":"Zhè gè guì zǐ shì xiàng mù zuò de， bìng qiě jīng shǒu gōng diāo kè ér chéng。","meaning":"The cabinet was made of oak and was hand-carved.","meaningThai":"ตู้ทำจากไม้โอ๊คและแกะสลักด้วยมือ"},{"chinese":"他把目光投向了一排排占满了庞大工作区的柜子。","pinyin":"Tā bǎ mù guāng tóu xiàng le yī pái pái zhān mǎn le páng dà gōng zuò qū de guì zǐ。","meaning":"He cast his eyes at the rows of cabinets that filled the enormous work area.","meaningThai":"เขามองดูตู้แถวที่เต็มพื้นที่ทำงานขนาดมหึมา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-445","chinese":"古老","pinyin":"gǔlǎo","meaning":"ancient; old; age-old","meaningThai":"โบราณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是现存最古老的希伯来语手稿。","pinyin":"Zhè shì xiàn cún zuì gǔ lǎo de xī bó lái yǔ shǒu gǎo。","meaning":"This is the oldest Hebrew manuscript in existence.","meaningThai":"นี่เป็นต้นฉบับภาษาฮีบรูที่เก่าแก่ที่สุดที่มีอยู่"},{"chinese":"这是最古老、最神圣的神道教仪式。","pinyin":"Zhè shì zuì gǔ lǎo、 zuì shén shèng de shén dào jiào yí shì。","meaning":"This is the most ancient, and holiest of the Shinto rituals.","meaningThai":"นี่เป็นพิธีกรรมที่เก่าแก่ที่สุดและศักดิ์สิทธิ์ที่สุดของศาสนาชินโต"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-446","chinese":"滚","pinyin":"gǔn","meaning":"to boil; to roll; to take a hike; Get lost!","meaningThai":"ม้วน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我用无香味的，滚抹除臭剂。","pinyin":"Wǒ yòng wú xiāng wèi de， gǔn mǒ chú chòu jì。","meaning":"I use unperfumed, roll-on deodorant.","meaningThai":"ฉันใช้ยาระงับกลิ่นกายแบบโรลออนที่ไม่มีน้ำหอม"},{"chinese":"如果本周没有人获得彩票头奖，头奖将再次滚计到下周。","pinyin":"Rú guǒ běn zhōu méi yǒu rén huò dé cǎi piào tóu jiǎng， tóu jiǎng jiāng zài cì gǔn jì dào xià zhōu。","meaning":"If the jackpot isn't won this week it will roll over again to next week.","meaningThai":"หากไม่ถูกรางวัลแจ็กพอตในสัปดาห์นี้ ก็จะทบยอดอีกครั้งในสัปดาห์หน้า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-447","chinese":"锅","pinyin":"guō","meaning":"pot; pan; wok; cauldron; pot-shaped thing","meaningThai":"หม้อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些锅上有蓝色的搪瓷。","pinyin":"Zhè xiē guō shàng yǒu lán sè de táng cí。","meaning":"The pots are made with blue enamel.","meaningThai":"หม้อทำจากเคลือบสีฟ้า"},{"chinese":"她掀起锅盖加点盐。","pinyin":"Tā xiān qǐ guō gài jiā diǎn yán。","meaning":"She lifted the lid of the pot to add some salt.","meaningThai":"เธอยกฝาหม้อขึ้นเพื่อเติมเกลือ"}],"partOfSpeech":["noun","measure word"]},
  {"id":"hsk5-448","chinese":"过度","pinyin":"guòdù","meaning":"excessive; over-; excess; going too far; extravagant; intemperate; overdue","meaningThai":"เกิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"警方坚决否认曾过度使用武力。","pinyin":"Jǐng fāng jiān jué fǒu rèn zēng guò dù shǐ yòng wǔ lì。","meaning":"The police vigorously denied that excessive force had been used.","meaningThai":"ตำรวจปฏิเสธอย่างหนักแน่นว่ามีการใช้กำลังมากเกินไป"},{"chinese":"这家公司扩张过度而面临破产。","pinyin":"Zhè jiā gōng sī kuò zhāng guò dù ér miàn lín pò chǎn。","meaning":"The company was overextended and faced bankruptcy.","meaningThai":"บริษัทมีการขยายเวลามากเกินไปและเผชิญกับการล้มละลาย"}],"partOfSpeech":["verb","adverb"]},
  {"id":"hsk5-449","chinese":"过分","pinyin":"guòfèn","meaning":"excessive; undue; overly","meaningThai":"มากเกินไป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们还是不要过分乐观。","pinyin":"Wǒ mén huán shì bù yào guò fēn lè guān。","meaning":"Let's not count our proverbial chickens.","meaningThai":"อย่านับไก่สุภาษิตของเรา"},{"chinese":"你对他要求过分了。","pinyin":"Nǐ duì tā yào qiú guò fēn le。","meaning":"You're asking too much of him.","meaningThai":"คุณถามเขามากเกินไป"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-450","chinese":"国画","pinyin":"guóhuà","meaning":"traditional Chinese painting","meaningThai":"ภาพวาดจีนแบบดั้งเดิม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"与西方画作不同，中国画更加抽象。","pinyin":"Yǔ xī fāng huà zuò bù tóng， zhōng guó huà gēng jiā chōu xiàng。","meaning":"Distinct from western paintings, Chinese paintings are more abstract.","meaningThai":"ภาพวาดจีนมีความแตกต่างจากภาพวาดตะวันตก จึงมีความเป็นนามธรรมมากกว่า"},{"chinese":"展厅里张挂着许多国画。","pinyin":"Zhǎn tīng lǐ zhāng guà zháo xǔ duō guó huà。","meaning":"The exhibition hall is decorated with many traditional Chinese paintings.","meaningThai":"ห้องนิทรรศการตกแต่งด้วยภาพวาดจีนโบราณมากมาย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-451","chinese":"过敏","pinyin":"guòmǐn","meaning":"oversensitive; allergic; allergy","meaningThai":"แพ้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我对花粉过敏。","pinyin":"Wǒ duì huā fěn guò mǐn.","meaning":"I am allergic to pollen.","meaningThai":"ฉันแพ้เกสรดอกไม้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-452","chinese":"过期","pinyin":"guòqī","meaning":"to be overdue; to exceed the time limit; to expire (as in expiration date)","meaningThai":"หมดอายุแล้ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"但是过期的苏打水跑气，味道也会大打折扣。","pinyin":"Dàn shì guò qī de sū dǎ shuǐ pǎo qì， wèi dào yě huì dà dǎ zhē kòu。","meaning":"But soda past its expiration date goes flat and loses much of its taste.","meaningThai":"แต่โซดาที่เลยวันหมดอายุจะแบนและสูญเสียรสชาติไปมาก"},{"chinese":"他的访问签证过期了。","pinyin":"Tā de fǎng wèn qiān zhèng guò qī le。","meaning":"His visitor's visa expired.","meaningThai":"วีซ่าผู้มาเยือนของเขาหมดอายุ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-453","chinese":"国庆","pinyin":"guóqìng","meaning":"National Day","meaningThai":"วันชาติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人们载歌载舞庆祝国庆。","pinyin":"Rén mén zǎi gē zǎi wǔ qìng zhù guó qìng。","meaning":"Singing and dancing, people celebrated National Day.","meaningThai":"ผู้คนต่างร้องเพลงและเต้นรำเฉลิมฉลองวันชาติ"},{"chinese":"这是我的国庆出游计划。","pinyin":"Zhè shì wǒ de guó qìng chū yóu jì huá。","meaning":"This is my vacation plan on National Day.","meaningThai":"นี่คือแผนวันหยุดของฉันในวันชาติ"}],"partOfSpeech":["other","noun"]},
  {"id":"hsk5-454","chinese":"果然","pinyin":"guǒrán","meaning":"really; sure enough; as expected; if indeed","meaningThai":"จริงหรือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我说他会忘记，他果然就忘了。","pinyin":"Wǒ shuō tā huì wàng jì， tā guǒ rán jiù wàng le。","meaning":"I said he'd forget, and sure enough he did.","meaningThai":"ฉันบอกว่าเขาจะลืม และแน่นอนว่าเขาลืม"},{"chinese":"新闻报道证明了他的推测果然不假。","pinyin":"Xīn wén bào dào zhèng míng le tā de tuī cè guǒ rán bù jiǎ。","meaning":"The truth of his conjecture was confirmed by the newspaper report.","meaningThai":"ความจริงของการคาดเดาของเขาได้รับการยืนยันจากรายงานของหนังสือพิมพ์"}],"partOfSpeech":["adverb","conjunction"]},
  {"id":"hsk5-455","chinese":"果实","pinyin":"guǒshí","meaning":"fruit (produced by a plant); (fig.) fruits (of success etc); results; gains","meaningThai":"ผล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"树上结满了果实。","pinyin":"Shù shàng jié mǎn le guǒ shí.","meaning":"The tree is full of fruit.","meaningThai":"ต้นไม้เต็มไปด้วยผลไม้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-456","chinese":"过于","pinyin":"guòyú","meaning":"too much; excessively","meaningThai":"ด้วย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"课程设置过于狭窄和死板。","pinyin":"Kè chéng shè zhì guò yú xiá zhǎi hé sǐ bǎn。","meaning":"The curriculum was too narrow and too rigid.","meaningThai":"หลักสูตรแคบและเข้มงวดเกินไป"},{"chinese":"他变得太过于美国化了。","pinyin":"Tā biàn dé tài guò yú měi guó huà le。","meaning":"He is getting much too Americanized.","meaningThai":"เขากลายเป็นคนอเมริกันมากเกินไป"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-457","chinese":"故乡","pinyin":"gùxiāng","meaning":"home; homeland; native place","meaningThai":"บ้าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"不由得想起了故乡。","pinyin":"Bù yóu dé xiǎng qǐ le gù xiāng。","meaning":"I can never forget my hometown.","meaningThai":"ฉันไม่สามารถลืมบ้านเกิดของฉันได้"},{"chinese":"我突然很想念我的故乡。","pinyin":"Wǒ tū rán hěn xiǎng niàn wǒ de gù xiāng。","meaning":"I suddenly feel nostalgic for my homeland.","meaningThai":"จู่ๆ ฉันก็รู้สึกคิดถึงบ้านเกิดของตัวเอง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-458","chinese":"鼓掌","pinyin":"gǔzhǎng","meaning":"to applaud; to clap","meaningThai":"ปรบมือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们上前领奖时，大家都为我们鼓掌。","pinyin":"Wǒ mén shàng qián lǐng jiǎng shí， dà jiā dū wéi wǒ mén gǔ zhǎng。","meaning":"Everyone clapped us when we went up to get our prize.","meaningThai":"ทุกคนปรบมือเมื่อเราขึ้นไปรับรางวัล"},{"chinese":"男人们跳舞，女人们鼓掌。","pinyin":"Nán rén mén tiào wǔ， nǚ rén mén gǔ zhǎng。","meaning":"The men danced and the women clapped.","meaningThai":"ผู้ชายเต้นรำและผู้หญิงปรบมือ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-459","chinese":"哈","pinyin":"hā","meaning":"abbr. for 哈萨克斯坦, Kazakhstan; abbr. for 哈尔滨, Harbin","meaningThai":"ฮ่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"哈里路亚！大学终于上完了！","pinyin":"Hā lǐ lù yà！ dà xué zhōng yú shàng wán le！","meaning":"Hallelujah! College days are over!","meaningThai":"ฮาเลลูยา! วันวิทยาลัยสิ้นสุดลงแล้ว!"},{"chinese":"札哈里亚斯听到门关上了。","pinyin":"Zhá hā lǐ yà sī tīng dào mén guān shàng le。","meaning":"Zacharias heard the door close.","meaningThai":"เศคาริยาห์ได้ยินเสียงปิดประตู"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-460","chinese":"海关","pinyin":"hǎiguān","meaning":"customs (i.e. border crossing inspection)","meaningThai":"ศุลกากร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"过海关要排队。","pinyin":"Guo hǎi guān yào pái duì.","meaning":"You queue through customs.","meaningThai":"คุณต่อคิวผ่านศุลกากร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-461","chinese":"海外","pinyin":"hǎiwài","meaning":"overseas; abroad","meaningThai":"ในต่างประเทศ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"对赴海外工作的人员有特别安排。","pinyin":"Duì fù hǎi wài gōng zuò de rén yuán yǒu tè bié ān pái。","meaning":"There are special arrangements for people working overseas.","meaningThai":"มีการเตรียมการพิเศษสำหรับผู้ที่ทำงานในต่างประเทศ"},{"chinese":"海外投资对出口有积极影响。","pinyin":"Hǎi wài tóu zī duì chū kǒu yǒu jī jí yǐng xiǎng。","meaning":"Overseas investment has had a positive effect on exports.","meaningThai":"การลงทุนในต่างประเทศส่งผลดีต่อการส่งออก"}],"partOfSpeech":["other"]},
  {"id":"hsk5-462","chinese":"海鲜","pinyin":"hǎixiān","meaning":"seafood","meaningThai":"อาหารทะเล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这儿的海鲜是美食家的一大享受。","pinyin":"Zhè ér de hǎi xiān shì měi shí jiā de yī dà xiǎng shòu。","meaning":"The seafood here is a gourmet's delight.","meaningThai":"อาหารทะเลที่นี่เป็นที่ชื่นชอบของนักชิม"},{"chinese":"海鲜是个当地特色，安德森船长餐厅是其典型代表。","pinyin":"Hǎi xiān shì gè dāng dì tè sè， ān dé sēn chuán cháng cān tīng shì qí diǎn xíng dài biǎo。","meaning":"Seafood is a regional speciality epitomized by Captain Anderson's Restaurant.","meaningThai":"อาหารทะเลเป็นอาหารพิเศษประจำภูมิภาคที่จัดทำโดยร้านอาหาร Captain Anderson's"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-463","chinese":"含","pinyin":"hán","meaning":"to keep in the mouth; to contain","meaningThai":"ประกอบด้วย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的语气中微含讽刺。","pinyin":"Tā de yǔ qì zhōng wēi hán fěng cì。","meaning":"His tone was tinged with irony.","meaningThai":"น้ำเสียงของเขาแต่งแต้มด้วยความประชด"},{"chinese":"只有蛋黄含胆固醇。","pinyin":"Zhī yǒu dàn huáng hán dǎn gù chún。","meaning":"Only the yolk contains cholesterol.","meaningThai":"เฉพาะไข่แดงเท่านั้นที่มีคอเลสเตอรอล"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-464","chinese":"行","pinyin":"háng","meaning":"row; line; commercial firm; line of business; profession; to rank (first, second etc) among one's siblings (by age); (in data tables) row; (Tw) column","meaningThai":"เดิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个办法行，我们就这样做。","pinyin":"Zhège bànfǎ xíng, wǒmen jiù zhèyàng zuò.","meaning":"This method will work, so let us do it this way.","meaningThai":"วิธีนี้จะได้ผล ดังนั้นให้เราทำเช่นนี้"},{"chinese":"我今天身体不行，想休息。","pinyin":"Wǒ jīntiān shēntǐ bùxíng, xiǎng xiūxī.","meaning":"I do not feel well today and want to rest.","meaningThai":"วันนี้ฉันไม่สบายและอยากพักผ่อน"},{"chinese":"步行十分钟就到了。","pinyin":"Bùxíng shífēnzhōng jiù dào le.","meaning":"It is only a ten-minute walk away.","meaningThai":"ใช้เวลาเดินเพียงสิบนาที"}],"partOfSpeech":["verb","other","measure word","adjective","noun"]},
  {"id":"hsk5-465","chinese":"行业","pinyin":"hángyè","meaning":"trade; profession; industry; business","meaningThai":"อุตสาหกรรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个行业发展很快。","pinyin":"Zhè ge háng yè fā zhǎn hěn kuài.","meaning":"This industry is developing rapidly.","meaningThai":"อุตสาหกรรมนี้มีการพัฒนาอย่างรวดเร็ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-466","chinese":"含量","pinyin":"hánliàng","meaning":"content; quantity contained","meaningThai":"เนื้อหา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"食品中钾的含量是多变的。","pinyin":"Shí pǐn zhōng jiǎ de hán liáng shì duō biàn de。","meaning":"The potassium content of foodstuffs is very variable.","meaningThai":"ปริมาณโพแทสเซียมในอาหารมีความผันแปรมาก"},{"chinese":"测试显示水中污染物质的含量很高。","pinyin":"Cè shì xiǎn shì shuǐ zhōng wū rǎn wù zhì de hán liáng hěn gāo。","meaning":"Tests have shown high levels of pollutants in the water.","meaningThai":"การทดสอบพบว่ามีสารมลพิษในน้ำอยู่ในระดับสูง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-467","chinese":"汗水","pinyin":"hànshuǐ","meaning":"sweat; perspiration","meaningThai":"เหงื่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"格莱布擦去了脸上的汗水。","pinyin":"Gé lái bù cā qù le liǎn shàng de hàn shuǐ。","meaning":"Gleb wiped the sweat from his face.","meaningThai":"เกลบเช็ดเหงื่อออกจากใบหน้าของเขา"},{"chinese":"她很热，汗水滴入双眼。","pinyin":"Tā hěn rè， hàn shuǐ dī rù shuāng yǎn。","meaning":"She was hot and sweat dripped into her eyes.","meaningThai":"เธอร้อนและเหงื่อหยดเข้าตาเธอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-468","chinese":"含有","pinyin":"hányǒu","meaning":"to contain; including","meaningThai":"บรรจุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"可能含有堅果。","pinyin":"Kě néng hán yǒu jiān guǒ。","meaning":"May contain nuts.","meaningThai":"อาจมีถั่ว"},{"chinese":"大多数牙膏里含有氟化物。","pinyin":"Dà duō shù yá gāo lǐ hán yǒu fú huà wù。","meaning":"Most toothpastes contain fluoride.","meaningThai":"ยาสีฟันส่วนใหญ่มีฟลูออไรด์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-469","chinese":"好","pinyin":"hào","meaning":"good; appropriate; proper; all right!; (before a verb) easy to; (before a verb) good to; (before an adjective for exclamatory effect) so; (verb complement indicating completion); (of two people) close; on intimate terms; (after a personal pronoun) hello","meaningThai":"ดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"今天天气很好。","pinyin":"Jīntiān tiānqì hěn hǎo.","meaning":"The weather is good today.","meaningThai":"วันนี้อากาศดี"},{"chinese":"这个老师很好。","pinyin":"Zhège lǎoshī hěn hǎo.","meaning":"This teacher is very kind.","meaningThai":"ครูคนนี้ใจดีมาก"},{"chinese":"你好吗？","pinyin":"Nǐ hǎo ma?","meaning":"How are you?","meaningThai":"คุณเป็นอย่างไร?"}],"partOfSpeech":["adjective","adverb","verb"]},
  {"id":"hsk5-470","chinese":"好评","pinyin":"hǎopíng","meaning":"favorable criticism; positive evaluation","meaningThai":"รีวิวดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个店的好评率很高。","pinyin":"Zhe ge dian de hao ping lv hen gao.","meaning":"This store has a high positive review rate.","meaningThai":"ร้านค้านี้มีอัตราการรีวิวเชิงบวกสูง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-471","chinese":"好奇","pinyin":"hàoqí","meaning":"inquisitive; curious; inquisitiveness; curiosity","meaningThai":"อยากรู้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"最好忍住好奇心，别碰鸟巢。","pinyin":"Zuì hǎo rěn zhù hǎo qí xīn， bié pèng niǎo cháo。","meaning":"It is best to stifle curiosity and leave birds' nests alone.","meaningThai":"เป็นการดีที่สุดที่จะระงับความอยากรู้อยากเห็นและปล่อยให้รังนกอยู่ตามลำพัง"},{"chinese":"我们满足了朋友的好奇心。","pinyin":"Wǒ mén mǎn zú le péng yǒu de hǎo qí xīn。","meaning":"We gratified our friend's curiosity.","meaningThai":"เราพอใจกับความอยากรู้อยากเห็นของเพื่อนของเรา"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-472","chinese":"好运","pinyin":"hǎoyùn","meaning":"good luck","meaningThai":"ขอให้โชคดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"希望这个符咒会给你带来好运。","pinyin":"Xī wàng zhè gè fú zhòu huì gěi nǐ dài lái hǎo yùn。","meaning":"I hope this charm will bring you luck.","meaningThai":"ฉันหวังว่าเสน่ห์นี้จะนำโชคมาให้คุณ"},{"chinese":"他也祝她交好运。","pinyin":"Tā yě zhù tā jiāo hǎo yùn。","meaning":"He reciprocated by wishing her good luck.","meaningThai":"เขาตอบแทนด้วยการอวยพรให้เธอโชคดี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-473","chinese":"好转","pinyin":"hǎozhuǎn","meaning":"to improve; to take a turn for the better; improvement","meaningThai":"ดีขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"慢慢地，情况开始好转了。","pinyin":"Màn màn dì， qíng kuàng kāi shǐ hǎo zhuǎn le。","meaning":"Slowly things began to improve.","meaningThai":"สิ่งต่างๆเริ่มดีขึ้นอย่างช้าๆ"},{"chinese":"大家都认为情况正在好转。","pinyin":"Dà jiā dū rèn wéi qíng kuàng zhèng zài hǎo zhuǎn。","meaning":"Everyone agrees things are getting better.","meaningThai":"ทุกคนเห็นพ้องต้องกันว่าสิ่งต่างๆ เริ่มดีขึ้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-474","chinese":"合","pinyin":"hé","meaning":"100 ml; one-tenth of a peck; measure for dry grain equal to one-tenth of sheng 升 or liter, or one-hundredth dou 斗","meaningThai":"รวมกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"清洗这些蚌，并且丢掉任何合不上的。","pinyin":"Qīng xǐ zhè xiē bàng， bìng qiě diū diào rèn hé hé bù shàng de。","meaning":"Clean the mussels and discard any that do not close.","meaningThai":"ทำความสะอาดหอยแมลงภู่และทิ้งส่วนที่ปิดไม่สนิททิ้งไป"},{"chinese":"那些窗帘纯粹用于装饰目的，不能开合。","pinyin":"Nà xiē chuāng lián chún cuì yòng yú zhuāng shì mù de， bù néng kāi hé。","meaning":"The curtains are for purely decorative purposes and do not open or close.","meaningThai":"ผ้าม่านมีไว้เพื่อการตกแต่งเท่านั้น ห้ามเปิดหรือปิด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-475","chinese":"合法","pinyin":"héfǎ","meaning":"lawful; legitimate; legal","meaningThai":"ถูกต้องตามกฎหมาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种酒合法出售，由卡车运出该州。","pinyin":"Zhè zhǒng jiǔ hé fǎ chū shòu， yóu kǎ chē yùn chū gāi zhōu。","meaning":"The liquor was sold legally and trucked out of the state.","meaningThai":"สุราถูกขายอย่างถูกกฎหมายและถูกขนส่งออกจากรัฐ"},{"chinese":"这项约定是否合法值得怀疑。","pinyin":"Zhè xiàng yuē dìng shì fǒu hé fǎ zhí dé huái yí。","meaning":"The arrangement is of doubtful legality.","meaningThai":"ข้อตกลงดังกล่าวมีความถูกต้องตามกฎหมายที่น่าสงสัย"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-476","chinese":"盒饭","pinyin":"héfàn","meaning":"meal in a partitioned box","meaningThai":"กล่องอาหารกลางวัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"可以准备盒饭让你们带着，在峡谷一日游的路上吃。","pinyin":"Kě yǐ zhǔn bèi hé fàn ràng nǐ mén dài zháo， zài xiá gǔ yī rì yóu de lù shàng chī。","meaning":"Packed lunches can be arranged to take with you on day trips into the valley.","meaningThai":"สามารถจัดอาหารกลางวันแบบแพ็คกล่องเพื่อนำติดตัวคุณไปท่องเที่ยวในหุบเขาแบบไปเช้าเย็นกลับ"},{"chinese":"但是我倒是不介意吃盒饭。","pinyin":"Dàn shì wǒ dǎo shì bù jiè yì chī hé fàn。","meaning":"But I don't mind eating boxed lunch.","meaningThai":"แต่ฉันไม่รังเกียจที่จะกินข้าวกล่อง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-477","chinese":"黑","pinyin":"hēi","meaning":"abbr. for Heilongjiang province 黑龙江","meaningThai":"สีดำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们快步穿过黑魆魆的街道。","pinyin":"Wǒ mén kuài bù chuān guò hēi xū xū de jiē dào。","meaning":"We walked quickly through the darkened streets.","meaningThai":"เราเดินอย่างรวดเร็วผ่านถนนที่มืดมิด"},{"chinese":"参加葬礼的人都身着黑服。","pinyin":"Cān jiā zàng lǐ de rén dū shēn zháo hēi fú。","meaning":"Everyone at the funeral was dressed in black.","meaningThai":"ทุกคนที่งานศพแต่งกายด้วยชุดสีดำ"}],"partOfSpeech":["adjective","other"]},
  {"id":"hsk5-478","chinese":"合理","pinyin":"hélǐ","meaning":"rational; reasonable; sensible; fair","meaningThai":"มีเหตุผล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们的收费还算合理。","pinyin":"Tā mén de shōu fèi huán suàn hé lǐ。","meaning":"The fees they charge are not unreasonable.","meaningThai":"ค่าธรรมเนียมที่พวกเขาเรียกเก็บนั้นไม่สมเหตุสมผล"},{"chinese":"在我看来，这个决定是完全合理的。","pinyin":"Zài wǒ kàn lái， zhè gè jué dìng shì wán quán hé lǐ de。","meaning":"In my opinion, the decision was wholly justified.","meaningThai":"ในความคิดของฉันการตัดสินใจนั้นสมเหตุสมผลทั้งหมด"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-479","chinese":"河流","pinyin":"héliú","meaning":"river","meaningThai":"แม่น้ำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"黄河是中国第二长的河流。","pinyin":"Huang he shi Zhong guo di er chang de he liu.","meaning":"The Yellow River is China's second longest.","meaningThai":"แม่น้ำเหลืองเป็นแม่น้ำที่ยาวเป็นอันดับสองของจีน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-480","chinese":"合同","pinyin":"hétóng","meaning":"(business) contract","meaningThai":"สัญญา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"双方签署了合作协议。","pinyin":"Shuāng fāng qiān shǔ le hé zuò xié yì.","meaning":"Both parties signed a cooperation agreement.","meaningThai":"ทั้งสองฝ่ายลงนามข้อตกลงความร่วมมือ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-481","chinese":"合影","pinyin":"héyǐng","meaning":"to take a joint photo; group photo","meaningThai":"ภาพถ่ายกลุ่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"开会前，六国外长一起合影。","pinyin":"Kāi huì qián， liù guó wài cháng yī qǐ hé yǐng。","meaning":"Before going into their meeting the six foreign ministers posed for photographs.","meaningThai":"ก่อนเข้าประชุมรัฐมนตรีต่างประเทศทั้ง 6 ท่านได้ถ่ายรูปร่วมกัน"},{"chinese":"两位领导人出场参加了合影。","pinyin":"Liǎng wèi lǐng dǎo rén chū cháng cān jiā le hé yǐng。","meaning":"The two leaders emerged for a photo session.","meaningThai":"แกนนำทั้ง 2 ถ่ายรูปร่วมกัน"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-482","chinese":"合作","pinyin":"hézuò","meaning":"to cooperate; to collaborate; to work together; cooperation","meaningThai":"ให้ความร่วมมือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这家工厂现为工人合作企业。","pinyin":"Zhè jiā gōng chǎng xiàn wéi gōng rén hé zuò qǐ yè。","meaning":"The factory is now a workers' cooperative.","meaningThai":"ปัจจุบันโรงงานแห่งนี้เป็นสหกรณ์คนงาน"},{"chinese":"这种合作很有可能行不通。","pinyin":"Zhè zhǒng hé zuò hěn yǒu kě néng háng bù tōng。","meaning":"There is the strong possibility that such cooperation will prove unworkable.","meaningThai":"มีความเป็นไปได้สูงที่ความร่วมมือดังกล่าวจะพิสูจน์ได้ว่าใช้ไม่ได้ผล"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-483","chinese":"红","pinyin":"hóng","meaning":"surname Hong","meaningThai":"สีแดง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她穿着她的新衣服，那件红的。","pinyin":"Tā chuān zháo tā de xīn yī fú， nà jiàn hóng de。","meaning":"She was wearing her new dress, the red one.","meaningThai":"เธอสวมชุดใหม่ของเธอ ชุดสีแดง"},{"chinese":"我用我的红围巾换了她的蓝围巾。","pinyin":"Wǒ yòng wǒ de hóng wéi jīn huàn le tā de lán wéi jīn。","meaning":"I swapped my red scarf for her blue one.","meaningThai":"ฉันเปลี่ยนผ้าพันคอสีแดงเป็นผ้าพันคอสีน้ำเงินของเธอ"}],"partOfSpeech":["adjective","verb","other"]},
  {"id":"hsk5-484","chinese":"厚度","pinyin":"hòudù","meaning":"thickness","meaningThai":"ความหนา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"现有四种不同厚度的木板可供使用。","pinyin":"Xiàn yǒu sì zhǒng bù tóng hòu dù de mù bǎn kě gōng shǐ yòng。","meaning":"The board is available in four thicknesses.","meaningThai":"กระดานมีให้เลือกสี่ความหนา"},{"chinese":"鱼的大小决定鱼排的厚度。","pinyin":"Yú de dà xiǎo jué dìng yú pái de hòu dù。","meaning":"The size of the fish will determine the thickness of the steaks.","meaningThai":"ขนาดของปลาจะเป็นตัวกำหนดความหนาของสเต็ก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-485","chinese":"后果","pinyin":"hòuguǒ","meaning":"consequences; aftermath","meaningThai":"อันเป็นผลมาจาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"汤姆准备承担后果。","pinyin":"Tāng mǔ zhǔn bèi chéng dān hòu guǒ。","meaning":"Tom is prepared to accept the consequences.","meaningThai":"ทอมพร้อมที่จะยอมรับผลที่ตามมา"},{"chinese":"我准备好了承担后果。","pinyin":"Wǒ zhǔn bèi hǎo le chéng dān hòu guǒ。","meaning":"I'm prepared to accept the consequences.","meaningThai":"ฉันพร้อมที่จะยอมรับผลที่ตามมา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-486","chinese":"猴子","pinyin":"hóuzi","meaning":"monkey","meaningThai":"ลิง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"猴子很聪明。","pinyin":"Hóu zi hěn cōng míng.","meaning":"Monkeys are very smart.","meaningThai":"ลิงฉลาดมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-487","chinese":"湖","pinyin":"hú","meaning":"lake","meaningThai":"ทะเลสาบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个湖几乎填满了泥沙和植被。","pinyin":"Zhè gè hú jī hū tián mǎn le ní shā hé zhí bèi。","meaning":"The lake was almost solid with silt and vegetation.","meaningThai":"ทะเลสาบเกือบจะแข็งไปด้วยตะกอนและพืชพรรณ"},{"chinese":"那个湖的大部分都在背阴中。","pinyin":"Nà gè hú de dà bù fēn dū zài bèi yīn zhōng。","meaning":"Most of the lake was in shadow.","meaningThai":"ทะเลสาบส่วนใหญ่อยู่ในเงามืด"}],"partOfSpeech":["noun","adjective"]},
  {"id":"hsk5-488","chinese":"滑","pinyin":"huá","meaning":"surname Hua","meaningThai":"ลื่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这条小径有些路段又湿又滑。","pinyin":"Zhè tiáo xiǎo jìng yǒu xiē lù duàn yòu shī yòu huá。","meaning":"In places the path can be wet and slippery.","meaningThai":"ในบางจุดเส้นทางอาจเปียกและลื่นได้"},{"chinese":"汽车驾驶者被提醒小心路滑。","pinyin":"Qì chē jià shǐ zhě bèi tí xǐng xiǎo xīn lù huá。","meaning":"Motorists were warned to beware of slippery conditions.","meaningThai":"เตือนผู้ขับขี่ระมัดระวังสภาพถนนลื่น"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-489","chinese":"划","pinyin":"huá","meaning":"to row; to paddle; profitable; worth (the effort); it pays (to do sth)","meaningThai":"แถว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他尽可能快速地将船划向了岸边。","pinyin":"Tā jìn kě néng kuài sù dì jiāng chuán huá xiàng le àn biān。","meaning":"He rowed as quickly as he could to the shore.","meaningThai":"เขาพายเรือให้เร็วที่สุดเท่าที่จะเป็นไปได้ถึงฝั่ง"},{"chinese":"他们去加拿大的野外划独木舟。","pinyin":"Tā mén qù jiā ná dà de yě wài huá dú mù zhōu。","meaning":"They went canoeing in the wilds of Canada.","meaningThai":"พวกเขาไปพายเรือแคนูในป่าของแคนาดา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-490","chinese":"化","pinyin":"huà","meaning":"variant of 花","meaningThai":"เปลี่ยน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"私有化趋势可能逆转吗？","pinyin":"Sī yǒu huà qū shì kě néng nì zhuǎn ma？","meaning":"Is the trend towards privatization reversible?","meaningThai":"แนวโน้มของการแปรรูปสามารถพลิกกลับได้หรือไม่?"},{"chinese":"我们都需要饮食多样化。","pinyin":"Wǒ mén dū xū yào yǐn shí duō yàng huà。","meaning":"We all need variety in our diet.","meaningThai":"เราทุกคนต้องการความหลากหลายในการรับประทานอาหารของเรา"}],"partOfSpeech":["verb","suffix"]},
  {"id":"hsk5-491","chinese":"话费","pinyin":"huàfèi","meaning":"call charge","meaningThai":"ค่าโทรศัพท์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"电话费包括线路租用费。","pinyin":"Diàn huà fèi bāo kuò xiàn lù zū yòng fèi。","meaning":"Telephone charges include line rental.","meaningThai":"ค่าโทรศัพท์รวมค่าเช่าสายแล้ว"},{"chinese":"他们用信用卡账户支付电话费。","pinyin":"Tā mén yòng xìn yòng kǎ zhàng hù zhī fù diàn huà fèi。","meaning":"They charge the calls to their credit-card account.","meaningThai":"พวกเขาเรียกเก็บเงินค่าโทรเข้าบัญชีบัตรเครดิต"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-492","chinese":"花费","pinyin":"huāfèi","meaning":"expense; cost; to spend (time or money); expenditure","meaningThai":"ใช้จ่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"花费时间。","pinyin":"Hua fei shi jian.","meaning":"Spend time.","meaningThai":"ใช้เวลา."}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-493","chinese":"画面","pinyin":"huàmiàn","meaning":"scene; tableau; picture; image; screen (displayed by a computer); (motion picture) frame; field of view","meaningThai":"รูปภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们被战争的画面牢牢抓住了。","pinyin":"Wǒ mén bèi zhàn zhēng de huà miàn láo láo zhuā zhù le。","meaning":"We were all transfixed by the images of the war.","meaningThai":"เราทุกคนต่างตกตะลึงกับภาพสงคราม"},{"chinese":"画面上有个人用气笔给抹掉了。","pinyin":"Huà miàn shàng yǒu gè rén yòng qì bǐ gěi mǒ diào le。","meaning":"Somebody had been airbrushed out of the picture.","meaningThai":"มีคนถูกพ่นสีออกจากภาพ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-494","chinese":"黄瓜","pinyin":"huángguā","meaning":"cucumber","meaningThai":"แตงกวา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"黄瓜对缓解眼睛疲劳很有效。","pinyin":"Huáng guā duì huǎn jiě yǎn jīng pí láo hěn yǒu xiào。","meaning":"Cucumber is good for soothing tired eyes.","meaningThai":"แตงกวาช่วยบรรเทาอาการเหนื่อยล้าของดวงตาได้ดี"},{"chinese":"贝斯戳起一片黄瓜。","pinyin":"Bèi sī chuō qǐ yī piàn huáng guā。","meaning":"Bess stabbed a slice of cucumber.","meaningThai":"เบสแทงแตงกวาชิ้นหนึ่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-495","chinese":"黄金","pinyin":"huángjīn","meaning":"gold; golden (opportunity); prime (time)","meaningThai":"ทอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有人曾经认为铅可以变成黄金。","pinyin":"Yǒu rén zēng jīng rèn wéi qiān kě yǐ biàn chéng huáng jīn。","meaning":"It was once thought that lead could be transmuted into gold.","meaningThai":"ครั้งหนึ่งเคยคิดว่าตะกั่วสามารถเปลี่ยนเป็นทองคำได้"},{"chinese":"一个金矿不是无限的，黄金采光了。","pinyin":"Yī gè jīn kuàng bù shì wú xiàn de， huáng jīn cǎi guāng le。","meaning":"A gold mine is not a bottomless pit, the gold runs out.","meaningThai":"เหมืองทองคำไม่ใช่หลุมที่ไม่มีก้นบ่อ เพราะทองคำจะหมดลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-496","chinese":"环节","pinyin":"huánjié","meaning":"(zoology) segment (of the body of a worm, centipede etc); (fig.) a part of an integrated whole: aspect (of a project), element (of a policy), sector (of the economy), stage (of a process) etc","meaningThai":"ส่วน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"重要环节。","pinyin":"Zhong yao huan jie.","meaning":"Important link.","meaningThai":"ลิงค์สำคัญ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-497","chinese":"缓解","pinyin":"huǎnjiě","meaning":"to bring relief; to alleviate (a crisis); to dull (a pain)","meaningThai":"ผ่อนปรน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"脑部扫描已经证实疾病有所缓解。","pinyin":"Nǎo bù sǎo miáo yǐ jīng zhèng shí jí bìng yǒu suǒ huǎn jiě。","meaning":"Brain scans have confirmed that the disease is in remission.","meaningThai":"การสแกนสมองยืนยันว่าโรคนี้อยู่ในภาวะทุเลาแล้ว"},{"chinese":"药物可以大大缓解疼痛。","pinyin":"Yào wù kě yǐ dà dà huǎn jiě téng tòng。","meaning":"Drugs can relieve much of the pain.","meaningThai":"ยาเสพติดสามารถบรรเทาอาการปวดได้มาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-498","chinese":"缓慢","pinyin":"huǎnmàn","meaning":"slow","meaningThai":"ช้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"手术后，他正在缓慢好转。","pinyin":"Shǒu shù hòu， tā zhèng zài huǎn màn hǎo zhuǎn。","meaning":"He's mending slowly after the operation.","meaningThai":"เขากำลังฟื้นตัวอย่างช้าๆ หลังการผ่าตัด"},{"chinese":"事情进展得极其缓慢。","pinyin":"Shì qíng jìn zhǎn dé jí qí huǎn màn。","meaning":"Things are moving painfully slowly.","meaningThai":"สิ่งต่างๆ ดำเนินไปอย่างช้าๆ อย่างเจ็บปวด"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-499","chinese":"话题","pinyin":"huàtí","meaning":"subject (of a talk or conversation); topic","meaningThai":"หัวข้อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"好吧。咱们就抛开这个话题吧。","pinyin":"Hǎo bā。 zán mén jiù pāo kāi zhè gè huà tí bā。","meaning":"Point taken. Let's drop the subject.","meaningThai":"จุดที่ถ่ายแล้ว เรามาวางเรื่องกันเถอะ"},{"chinese":"规定禁止谈论这个话题。","pinyin":"Guī dìng jīn zhǐ tán lùn zhè gè huà tí。","meaning":"The subject was ruled off-limits.","meaningThai":"วัตถุถูกจำกัดขอบเขต"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-500","chinese":"化学","pinyin":"huàxué","meaning":"chemistry; chemical","meaningThai":"เคมี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"化学课要做实验。","pinyin":"Huà xué kè yào zuò shí yàn.","meaning":"Chemistry class requires experiments.","meaningThai":"ชั้นเรียนเคมีต้องมีการทดลอง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-501","chinese":"蝴蝶","pinyin":"húdié","meaning":"butterfly","meaningThai":"ผีเสื้อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"蝴蝶在花园里飞舞。","pinyin":"Hú dié zài huā yuán lǐ fēi wǔ.","meaning":"Butterflies flutter in the garden.","meaningThai":"ผีเสื้อกระพือปีกอยู่ในสวน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-502","chinese":"互动","pinyin":"hùdòng","meaning":"to interact; interactive","meaningThai":"โต้ตอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这所学校相信互动教学法。","pinyin":"Zhè suǒ xué xiào xiāng xìn hù dòng jiào xué fǎ。","meaning":"The school believes in interactive teaching methods.","meaningThai":"โรงเรียนเชื่อในวิธีการสอนแบบโต้ตอบ"},{"chinese":"几乎没有证据表明这促进灵活互动的课堂教学。","pinyin":"Jī hū méi yǒu zhèng jù biǎo míng zhè cù jìn líng huó hù dòng de kè táng jiào xué。","meaning":"There is little evidence that this encouraged flexible, interactive teaching in the classroom.","meaningThai":"มีหลักฐานเพียงเล็กน้อยที่สนับสนุนการสอนแบบโต้ตอบและยืดหยุ่นในห้องเรียน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-503","chinese":"灰","pinyin":"huī","meaning":"ash; dust; lime; gray; discouraged; dejected","meaningThai":"เถ้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我看见这个穿着灰西装的英俊男子。","pinyin":"Wǒ kàn jiàn zhè gè chuān zháo huī xī zhuāng de yīng jùn nán zǐ。","meaning":"I saw this nice-looking man in a grey suit.","meaningThai":"ฉันเห็นชายหน้าตาดีคนนี้ในชุดสูทสีเทา"},{"chinese":"发电厂每小时喷出了5吨的灰。","pinyin":"Fā diàn chǎng měi xiǎo shí pēn chū le 5 dūn de huī。","meaning":"The power-generation plant belched out five tons of ash an hour.","meaningThai":"โรงไฟฟ้าแห่งนี้พ่นเถ้าถ่านออกมา 5 ตันต่อชั่วโมง"}],"partOfSpeech":["other","noun","adjective"]},
  {"id":"hsk5-504","chinese":"挥","pinyin":"huī","meaning":"to wave; to brandish; to command; to conduct; to scatter; to disperse","meaningThai":"คลื่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"史蒂夫把手一挥，制止了他。","pinyin":"Shǐ dì fū bǎ shǒu yī huī， zhì zhǐ le tā。","meaning":"Steve stopped him with a wave of the hand.","meaningThai":"สตีฟหยุดเขาด้วยการโบกมือ"},{"chinese":"他对准球猛地挥拍一击。","pinyin":"Tā duì zhǔn qiú měng dì huī pāi yī jī。","meaning":"He took a wild swing at the ball.","meaningThai":"เขาเหวี่ยงลูกบอลอย่างดุเดือด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-505","chinese":"恢复","pinyin":"huīfù","meaning":"to reinstate; to resume; to restore; to recover; to regain; to rehabilitate","meaningThai":"ฟื้นฟู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"恢复健康。","pinyin":"Hui fu jian kang.","meaning":"Recover health.","meaningThai":"ฟื้นฟูสุขภาพ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-506","chinese":"汇率","pinyin":"huìlǜ","meaning":"exchange rate","meaningThai":"อัตราแลกเปลี่ยน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人民币兑美元汇率上升了。","pinyin":"Rén mín bì duì Měi yuán huì lǜ shàng shēng le.","meaning":"The RMB to USD exchange rate has risen.","meaningThai":"อัตราแลกเปลี่ยน RMB เป็น USD เพิ่มขึ้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-507","chinese":"灰色","pinyin":"huīsè","meaning":"gray; ash gray; grizzly; pessimistic; gloomy; dispirited; ambiguous","meaningThai":"สีเทา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他穿着灰色的衣服。","pinyin":"Ta chuan zhe hui se de yi fu.","meaning":"He is wearing gray clothes.","meaningThai":"เขาสวมเสื้อผ้าสีเทา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-508","chinese":"回收","pinyin":"huíshōu","meaning":"to recycle; to reclaim; to retrieve; to recover; to recall (a defective product)","meaningThai":"รีไซเคิล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"请把垃圾分类回收。","pinyin":"Qǐng bǎ lā jī fēn lèi huí shōu.","meaning":"Please sort trash for recycling.","meaningThai":"กรุณาคัดแยกขยะเพื่อการรีไซเคิล"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-509","chinese":"婚礼","pinyin":"hūnlǐ","meaning":"wedding ceremony; wedding","meaningThai":"งานแต่งงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"婚礼在哪儿举行？","pinyin":"Hūn lǐ zài nǎ ér jǔ háng？","meaning":"Where is the wedding to be?","meaningThai":"จะจัดงานแต่งงานที่ไหน?"},{"chinese":"你出席了我的婚礼。","pinyin":"Nǐ chū xí le wǒ de hūn lǐ。","meaning":"You were at my wedding.","meaningThai":"คุณอยู่ที่งานแต่งงานของฉัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-510","chinese":"伙","pinyin":"huǒ","meaning":"meals (abbr. for 食); variant of 伙","meaningThai":"พันธมิตร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这场打斗是一伙少年挑起来的。","pinyin":"Zhè cháng dǎ dǒu shì yī huǒ shǎo nián tiāo qǐ lái de。","meaning":"The fight was started by a gang of youths.","meaningThai":"การต่อสู้เริ่มต้นโดยกลุ่มวัยรุ่น"},{"chinese":"一伙持枪歹徒袭击了一所监狱并放走了9名罪犯。","pinyin":"Yī huǒ chí qiāng dǎi tú xí jī le yī suǒ jiān yù bìng fàng zǒu le 9 míng zuì fàn。","meaning":"A group of gunmen attacked a prison and set free nine criminals.","meaningThai":"กลุ่มมือปืนโจมตีเรือนจำและปล่อยตัวอาชญากร 9 คน"}],"partOfSpeech":["measure word"]},
  {"id":"hsk5-511","chinese":"伙伴","pinyin":"huǒbàn","meaning":"partner; companion; comrade","meaningThai":"พันธมิตร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"总统说日本现在是盟国和国际伙伴。","pinyin":"Zǒng tǒng shuō rì běn xiàn zài shì méng guó hé guó jì huǒ bàn。","meaning":"The president said that Japan is now a friend and international partner.","meaningThai":"ประธานาธิบดีกล่าวว่าตอนนี้ญี่ปุ่นเป็นเพื่อนและหุ้นส่วนระหว่างประเทศแล้ว"},{"chinese":"你的伙伴该把球回传给你。","pinyin":"Nǐ de huǒ bàn gāi bǎ qiú huí chuán gěi nǐ。","meaning":"Your partner should then pass the ball back to you.","meaningThai":"คู่ของคุณควรส่งบอลกลับมาให้คุณ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-512","chinese":"火锅","pinyin":"huǒguō","meaning":"hotpot","meaningThai":"กระติกน้ำร้อน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们可以在夏天吃火锅。","pinyin":"Wǒ mén kě yǐ zài xià tiān chī huǒ guō。","meaning":"We can eat hot pot in summer.","meaningThai":"ฤดูร้อนเราสามารถกินหม้อไฟได้"},{"chinese":"这是巧克力火锅吗？","pinyin":"Zhè shì qiǎo kè lì huǒ guō ma？","meaning":"Is it the chocolate hot pot?","meaningThai":"หม้อไฟช็อคโกแลตหรือเปล่า?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-513","chinese":"或是","pinyin":"huòshì","meaning":"or; either one or the other","meaningThai":"หรือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"接受或是拒绝这些建议由你决定。","pinyin":"Jiē shòu huò shì jù jué zhè xiē jiàn yì yóu nǐ jué dìng。","meaning":"It lies with you to accept or reject the proposals.","meaningThai":"มันขึ้นอยู่กับคุณที่จะยอมรับหรือปฏิเสธข้อเสนอ"},{"chinese":"你常出汗或是常脸红吗？","pinyin":"Nǐ cháng chū hàn huò shì cháng liǎn hóng ma？","meaning":"Do you sweat a lot or flush a lot?","meaningThai":"คุณเหงื่อออกมากหรือหน้าแดงมาก?"}],"partOfSpeech":["conjunction"]},
  {"id":"hsk5-514","chinese":"货物","pinyin":"huòwù","meaning":"goods; commodity; merchandise","meaningThai":"สินค้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"货物毫无损坏地到达了。","pinyin":"Huò wù háo wú sǔn huài dì dào dá le。","meaning":"The goods arrived undamaged.","meaningThai":"สินค้ามาถึงไม่เสียหาย"},{"chinese":"货物运到，我会通知你们的。","pinyin":"Huò wù yùn dào， wǒ huì tōng zhī nǐ mén de。","meaning":"I will notify you of the arrival of the goods.","meaningThai":"ฉันจะแจ้งให้คุณทราบถึงสินค้ามาถึง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-515","chinese":"或许","pinyin":"huòxǔ","meaning":"perhaps; maybe","meaningThai":"บางที","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个要花二百英镑，或许三百英镑。","pinyin":"Zhè gè yào huā èr bǎi yīng bàng， huò xǔ sān bǎi yīng bàng。","meaning":"It will cost two, maybe three hundred pounds.","meaningThai":"ราคาสองหรือสามร้อยปอนด์"},{"chinese":"我们或许可以自己划桨过去。","pinyin":"Wǒ mén huò xǔ kě yǐ zì jǐ huá jiǎng guò qù。","meaning":"We might be able to push ourselves across with the paddle.","meaningThai":"เราอาจจะสามารถดันตัวเราข้ามไปกับไม้พายได้"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-516","chinese":"忽视","pinyin":"hūshì","meaning":"to neglect; to overlook; to disregard; to ignore","meaningThai":"ไม่สนใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"叛逆的孩子不太可能被忽视。","pinyin":"Pàn nì de hái zǐ bù tài kě néng bèi hū shì。","meaning":"The child who rebels is unlikely to be overlooked.","meaningThai":"เด็กที่กบฏไม่น่าจะถูกมองข้าม"},{"chinese":"此类争论忽视了最终责任何在的问题。","pinyin":"Cǐ lèi zhēng lùn hū shì le zuì zhōng zé rèn hé zài de wèn tí。","meaning":"Such arguments ignore the question of where ultimate responsibility lay.","meaningThai":"ข้อโต้แย้งดังกล่าวเพิกเฉยต่อคำถามที่ว่าความรับผิดชอบสูงสุดอยู่ที่ใด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-517","chinese":"胡同","pinyin":"hútòng","meaning":"lane; alley","meaningThai":"ตรอก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他把自行车推进了房屋一侧的胡同里。","pinyin":"Tā bǎ zì háng chē tuī jìn le fáng wū yī cè de hú tóng lǐ。","meaning":"He wheeled his bike into the alley at the side of the house.","meaningThai":"เขาปั่นจักรยานเข้าไปในซอยข้างบ้าน"},{"chinese":"我往后一闪，躲进胡同里等了一会儿。","pinyin":"Wǒ wǎng hòu yī shǎn， duǒ jìn hú tóng lǐ děng le yī huì ér。","meaning":"I dodged back into the alley and waited a minute.","meaningThai":"ฉันหลบกลับเข้าไปในตรอกและรอสักครู่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-518","chinese":"户外","pinyin":"hùwài","meaning":"outdoor","meaningThai":"กลางแจ้ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"户外的空气阴沉、潮湿而闷热。","pinyin":"Hù wài de kōng qì yīn chén、 cháo shī ér mèn rè。","meaning":"The outside air was heavy and moist and sultry.","meaningThai":"อากาศภายนอกก็หนักหน่วงและชื้นและร้อนอบอ้าว"},{"chinese":"雨天使他们无法户外用餐。","pinyin":"Yǔ tiān shǐ tā mén wú fǎ hù wài yòng cān。","meaning":"The rain prevented them from eating outdoors.","meaningThai":"ฝนตกทำให้พวกเขาไม่สามารถรับประทานอาหารนอกบ้านได้"}],"partOfSpeech":["other"]},
  {"id":"hsk5-519","chinese":"呼吸","pinyin":"hūxī","meaning":"to breathe","meaningThai":"หายใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"深呼吸可以放松。","pinyin":"Shēn hū xī kě yǐ fàng sōng.","meaning":"Deep breathing can relax you.","meaningThai":"การหายใจลึกๆ สามารถทำให้คุณผ่อนคลายได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-520","chinese":"及","pinyin":"jí","meaning":"and; to reach; up to; in time for","meaningThai":"และ, ถึง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你应该及时完成。","pinyin":"Ni ying gai ji shi wan cheng.","meaning":"You should finish on time.","meaningThai":"คุณควรจะเสร็จตรงเวลา"}],"partOfSpeech":["other","verb"]},
  {"id":"hsk5-521","chinese":"级","pinyin":"jí","meaning":"level; grade; rank; step (of stairs); classifier: step, level","meaningThai":"ระดับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"风力仍在增强，接近九级。","pinyin":"Fēng lì réng zài zēng qiáng， jiē jìn jiǔ jí。","meaning":"The wind was still rising, approaching a force nine gale.","meaningThai":"ลมยังคงพัดแรงเข้าใกล้พายุเก้าลูก"},{"chinese":"我单脚跳下3级台阶。","pinyin":"Wǒ dān jiǎo tiào xià 3 jí tái jiē。","meaning":"I hopped down three steps.","meaningThai":"ฉันกระโดดลงไปสามก้าว"}],"partOfSpeech":["measure word","noun"]},
  {"id":"hsk5-522","chinese":"集","pinyin":"jí","meaning":"to gather; to collect; collected works; classifier for sections of a TV series etc: episode","meaningThai":"ชุด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"最后一集将于下星期天晚上播出。","pinyin":"Zuì hòu yī jí jiāng yú xià xīng qī tiān wǎn shàng bō chū。","meaning":"The final part will be shown next Sunday evening.","meaningThai":"ส่วนสุดท้ายจะแสดงเย็นวันอาทิตย์หน้า"},{"chinese":"这部小说分六集在电视上播出。","pinyin":"Zhè bù xiǎo shuō fēn liù jí zài diàn shì shàng bō chū。","meaning":"The novel was serialized on TV in six parts.","meaningThai":"นวนิยายเรื่องนี้ได้รับการต่อเนื่องทางทีวีเป็นหกตอน"}],"partOfSpeech":["measure word","other"]},
  {"id":"hsk5-523","chinese":"系","pinyin":"jì","meaning":"to connect; to relate to; to tie up; to bind; to be (literary)","meaningThai":"ผูก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我得系领带吗？","pinyin":"Wǒ dé xì lǐng dài ma？","meaning":"Do I have to wear a tie?","meaningThai":"ฉันต้องผูกเน็คไทหรือไม่?"},{"chinese":"她把皮带松松地系在腰上。","pinyin":"Tā bǎ pí dài sōng sōng dì xì zài yāo shàng。","meaning":"She fastened the belt loosely around her waist.","meaningThai":"เธอคาดเข็มขัดรอบเอวอย่างหลวมๆ"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-524","chinese":"挤","pinyin":"jǐ","meaning":"to crowd in; to cram in; to force others aside; to press; to squeeze; to find (time in one's busy schedule)","meaningThai":"บีบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"大家稍稍挤一挤，地方就够了。","pinyin":"Dà jiā shāo shāo jǐ yī jǐ， dì fāng jiù gòu le。","meaning":"There'll be enough room if we all squeeze up a little.","meaningThai":"จะมีที่ว่างเพียงพอถ้าเราทุกคนบีบคั้นกันสักหน่อย"},{"chinese":"挤一点鲜青柠汁能减少鳄梨的油腻。","pinyin":"Jǐ yī diǎn xiān qīng níng zhī néng jiǎn shǎo è lí de yóu nì。","meaning":"A squeeze of fresh lime juice cuts the richness of the avocado.","meaningThai":"น้ำมะนาวคั้นสดจะช่วยลดความเข้มข้นของอะโวคาโด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-525","chinese":"架","pinyin":"jià","meaning":"to support; frame; rack; framework; classifier for planes, large vehicles, radios etc","meaningThai":"ชั้นวาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"行李架是个明智的选择。","pinyin":"Háng lǐ jià shì gè míng zhì de xuǎn zé。","meaning":"A luggage rack is a sensible option.","meaningThai":"ชั้นวางสัมภาระเป็นตัวเลือกที่สมเหตุสมผล"},{"chinese":"三架飞机停在跑道上，等候起飞。","pinyin":"Sān jià fēi jī tíng zài pǎo dào shàng， děng hòu qǐ fēi。","meaning":"Three planes were standing on the tarmac, waiting to take off.","meaningThai":"เครื่องบินสามลำกำลังยืนอยู่บนพื้นยางมะตอยเพื่อรอเครื่องขึ้น"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-526","chinese":"甲","pinyin":"jiǎ","meaning":"first of the ten Heavenly Stems 干; (used for an unspecified person or thing); first (in a list, as a party to a contract etc); letter \"A\" or roman \"I\" in list \"A, B, C\", or \"I, II, III\" etc; armor plating; shell or carapace; (of the fingers or toes) nail; bladed leather or metal armor (old); ranking system used in the Imperial examinations (old); civil administration unit in the baojia 甲 system (old); ancient Chinese compass point: 75°","meaningThai":"อันดับแรก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我偶尔会做一次手甲护理。","pinyin":"Wǒ ǒu ěr huì zuò yī cì shǒu jiǎ hù lǐ。","meaning":"I have a manicure occasionally.","meaningThai":"ฉันทำเล็บเป็นบางครั้ง"},{"chinese":"好莱坞的名人都涌向简内特•沃恩的美甲沙龙。","pinyin":"Hǎo lái wù de míng rén dū yǒng xiàng jiǎn nèi tè • wò ēn de měi jiǎ shā lóng。","meaning":"The glitterati of Hollywood are flocking to Janet Vaughan's nail salon.","meaningThai":"เหล่าคนดังแห่งฮอลลีวูดแห่กันไปที่ร้านทำเล็บของ Janet Vaughan"}],"partOfSpeech":["noun","other","numeral"]},
  {"id":"hsk5-527","chinese":"嘉宾","pinyin":"jiābīn","meaning":"esteemed guest; honored guest; guest (on a show)","meaningThai":"แขก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我的特邀嘉宾将是杰瑞•塞菲尔德。","pinyin":"Wǒ de tè yāo jiā bīn jiāng shì jié ruì • sāi fēi ěr dé。","meaning":"My special guest will be Jerry Seinfeld.","meaningThai":"แขกรับเชิญพิเศษของฉันคือเจอร์รี่ ไซน์เฟลด์"},{"chinese":"我打算邀请70位嘉宾参加婚礼。","pinyin":"Wǒ dǎ suàn yāo qǐng 70 wèi jiā bīn cān jiā hūn lǐ。","meaning":"I'm thinking in terms of about 70 guests at the wedding.","meaningThai":"ฉันคิดว่าในแง่ของแขกประมาณ 70 คนในงานแต่งงาน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-528","chinese":"家电","pinyin":"jiādiàn","meaning":"household electric appliance; abbr. for 家用电器","meaningThai":"เครื่องใช้ในบ้าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这家电影制片厂正迁往好莱坞。","pinyin":"Zhè jiā diàn yǐng zhì piàn chǎng zhèng qiān wǎng hǎo lái wù。","meaning":"The film studio is transferring to Hollywood.","meaningThai":"สตูดิโอภาพยนตร์กำลังย้ายไปฮอลลีวูด"},{"chinese":"该工程规划为国家电网发电约3千万瓦。","pinyin":"Gāi gōng chéng guī huá wéi guó jiā diàn wǎng fā diàn yuē 3 qiān wàn wǎ。","meaning":"The project is designed to generate around 30 megawatts of power for the national grid.","meaningThai":"โครงการนี้ออกแบบมาเพื่อผลิตไฟฟ้าประมาณ 30 เมกะวัตต์สำหรับโครงข่ายไฟฟ้าของประเทศ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-529","chinese":"加工","pinyin":"jiāgōng","meaning":"to process; processing; working (of machinery)","meaningThai":"กำลังประมวลผล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"政府强制禁止出口未加工过的木料。","pinyin":"Zhèng fǔ qiáng zhì jīn zhǐ chū kǒu wèi jiā gōng guò de mù liào。","meaning":"The government slapped a ban on the export of unprocessed logs.","meaningThai":"รัฐบาลสั่งห้ามส่งออกไม้ซุงที่ยังไม่แปรรูป"},{"chinese":"美国把棉花运到英格兰加工。","pinyin":"Měi guó bǎ mián huā yùn dào yīng gé lán jiā gōng。","meaning":"America sent cotton to England for processing.","meaningThai":"อเมริกาส่งฝ้ายไปอังกฤษเพื่อแปรรูป"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-530","chinese":"建","pinyin":"jiàn","meaning":"to establish; to found; to set up; to build; to construct","meaningThai":"สร้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们得到建200座新房的许可。","pinyin":"Tā mén dé dào jiàn 200 zuò xīn fáng de xǔ kě。","meaning":"They have permission to build 200 new houses.","meaningThai":"พวกเขาได้รับอนุญาตให้สร้างบ้านใหม่ได้ 200 หลัง"},{"chinese":"这房子是围绕着中央的庭院而建的。","pinyin":"Zhè fáng zǐ shì wéi rào zháo zhōng yāng de tíng yuàn ér jiàn de。","meaning":"The house is built around a central courtyard.","meaningThai":"บ้านถูกสร้างขึ้นรอบลานกลาง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-531","chinese":"键","pinyin":"jiàn","meaning":"key (on a piano or computer keyboard); button (on a mouse or other device); chemical bond; linchpin","meaningThai":"สำคัญ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我选定了一份文件，然后按下了删除键。","pinyin":"Wǒ xuǎn dìng le yī fèn wén jiàn， rán hòu àn xià le shān chú jiàn。","meaning":"I selected a file and pressed the delete key.","meaningThai":"ฉันเลือกไฟล์แล้วกดปุ่มลบ"},{"chinese":"罗德尼把录音机放在桌面上，按下了播放键。","pinyin":"Luó dé ní bǎ lù yīn jī fàng zài zhuō miàn shàng， àn xià le bō fàng jiàn。","meaning":"Rodney put the recorder on the desk top and pushed the play button.","meaningThai":"ร็อดนีย์วางเครื่องบันทึกไว้บนโต๊ะแล้วกดปุ่มเล่น"}],"partOfSpeech":["noun","other"]},
  {"id":"hsk5-532","chinese":"捡","pinyin":"jiǎn","meaning":"to pick up; to collect; to gather","meaningThai":"หยิบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她弯腰去捡报纸。","pinyin":"Tā wān yāo qù jiǎn bào zhǐ。","meaning":"She bent forward to pick up the newspaper.","meaningThai":"เธอก้มหน้าหยิบหนังสือพิมพ์"},{"chinese":"她俯身去捡手套。","pinyin":"Tā fǔ shēn qù jiǎn shǒu tào。","meaning":"She bent down to pick up her glove.","meaningThai":"เธอก้มลงไปหยิบถุงมือของเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-533","chinese":"剪","pinyin":"jiǎn","meaning":"surname Jian","meaningThai":"ตัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他现在已开始快速剪那张纸。","pinyin":"Tā xiàn zài yǐ kāi shǐ kuài sù jiǎn nà zhāng zhǐ。","meaning":"He has now begun to snip away at the piece of paper.","meaningThai":"ตอนนี้เขาเริ่มที่จะตัดกระดาษออกไปแล้ว"},{"chinese":"用指甲刀整块地剪脚指甲。","pinyin":"Yòng zhǐ jiǎ dāo zhěng kuài dì jiǎn jiǎo zhǐ jiǎ。","meaning":"Trim toenails straight across using nail clippers.","meaningThai":"ตัดเล็บเท้าให้ตรงโดยใช้กรรไกรตัดเล็บ"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-534","chinese":"剪刀","pinyin":"jiǎndāo","meaning":"scissors","meaningThai":"กรรไกร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"海恩斯太太站在旁边，拿着剪刀剪缎带。","pinyin":"Hǎi ēn sī tài tài zhàn zài páng biān， ná zháo jiǎn dāo jiǎn duàn dài。","meaning":"Mrs. Haines stood nearby, holding scissors to cut a ribbon.","meaningThai":"นางไฮน์สยืนอยู่ใกล้ๆ ถือกรรไกรตัดริบบิ้น"},{"chinese":"快点用剪刀。我需要用。","pinyin":"Kuài diǎn yòng jiǎn dāo。 wǒ xū yào yòng。","meaning":"Hurry up with the scissors. I need them.","meaningThai":"รีบใช้กรรไกรเลย ฉันต้องการพวกเขา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-535","chinese":"减肥","pinyin":"jiǎnféi","meaning":"to lose weight","meaningThai":"ลดน้ำหนัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她在减肥，不吃甜食。","pinyin":"Tā zài jiǎn féi, bù chī tián shí.","meaning":"She is losing weight and doesn't eat sweets.","meaningThai":"เธอกำลังลดน้ำหนักและไม่กินของหวาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-536","chinese":"讲话","pinyin":"jiǎnghuà","meaning":"a speech; to speak; to talk; to address","meaningThai":"คำพูด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"不许那样对我讲话，小姐！","pinyin":"Bù xǔ nà yàng duì wǒ jiǎng huà， xiǎo jiě！","meaning":"Don't you speak to me like that, missy!","meaningThai":"อย่าพูดแบบนั้นกับฉันนะคุณหนู!"},{"chinese":"这次讲话的语气颇为乐观。","pinyin":"Zhè cì jiǎng huà de yǔ qì pō wéi lè guān。","meaning":"The tone of the speech was upbeat.","meaningThai":"น้ำเสียงของคำพูดมีจังหวะดี"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-537","chinese":"将近","pinyin":"jiāngjìn","meaning":"almost; nearly; close to","meaningThai":"เกือบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"玛莎那时每天吃将近一磅奶酪。","pinyin":"Mǎ suō nà shí měi tiān chī jiāng jìn yī bàng nǎi lào。","meaning":"Martha would consume nearly a pound of cheese per day.","meaningThai":"มาร์ธาจะกินชีสเกือบหนึ่งปอนด์ต่อวัน"},{"chinese":"她将近90岁了，但身体仍然十分强健。","pinyin":"Tā jiāng jìn 90 suì le， dàn shēn tǐ réng rán shí fēn qiáng jiàn。","meaning":"She was almost 90, but still very robust.","meaningThai":"เธออายุเกือบ 90 แล้ว แต่ก็ยังแข็งแรงมาก"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-538","chinese":"讲究","pinyin":"jiǎngjiu","meaning":"to pay particular attention to; carefully selected for quality; tastefully chosen","meaningThai":"ให้ความสนใจกับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他穿着上很不讲究。","pinyin":"Tā chuān zháo shàng hěn bù jiǎng jiū。","meaning":"He's very sloppy in his dress.","meaningThai":"เขาเลอะเทอะมากในการแต่งตัวของเขา"},{"chinese":"这家饭馆的餐具很讲究","pinyin":"Zhè jiā fàn guǎn de cān jù hěn jiǎng jiū","meaning":"This restaurant is particular about cutlery.","meaningThai":"ร้านอาหารแห่งนี้เน้นเรื่องช้อนส้อมโดยเฉพาะ"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-539","chinese":"奖励","pinyin":"jiǎnglì","meaning":"to reward; reward (as encouragement)","meaningThai":"รางวัล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"给予奖励。","pinyin":"Gei yu jiang li.","meaning":"Give a reward.","meaningThai":"ให้รางวัล."}],"partOfSpeech":["verb"]},
  {"id":"hsk5-540","chinese":"讲述","pinyin":"jiǎngshù","meaning":"to talk about; to narrate; to give an account","meaningThai":"บอก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他开始向我讲述他新书的情节。","pinyin":"Tā kāi shǐ xiàng wǒ jiǎng shù tā xīn shū de qíng jié。","meaning":"He began to tell me the plot of his new book.","meaningThai":"เขาเริ่มเล่าเรื่องหนังสือเล่มใหม่ของเขาให้ฉันฟัง"},{"chinese":"故事是以倒叙手法向读者讲述的。","pinyin":"Gù shì shì yǐ dǎo xù shǒu fǎ xiàng dú zhě jiǎng shù de。","meaning":"The reader is told the story in flashback.","meaningThai":"ผู้อ่านจะเล่าเรื่องย้อนหลัง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-541","chinese":"降水","pinyin":"jiàngshuǐ","meaning":"precipitation","meaningThai":"การตกตะกอน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"其次，北极的大部分降水形式为雪。","pinyin":"Qí cì， běi jí de dà bù fēn jiàng shuǐ xíng shì wéi xuě。","meaning":"Second, most of the precipitation in the Arctic is in the form of snow.","meaningThai":"ประการที่สอง ปริมาณน้ำฝนส่วนใหญ่ในอาร์กติกอยู่ในรูปของหิมะ"},{"chinese":"除其他因素外，降水还受到地形的影响。","pinyin":"Chú qí tā yīn sù wài， jiàng shuǐ huán shòu dào dì xíng de yǐng xiǎng。","meaning":"Precipitation is influenced by topography among other things.","meaningThai":"ปริมาณน้ำฝนได้รับอิทธิพลจากภูมิประเทศเหนือสิ่งอื่นใด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-542","chinese":"讲座","pinyin":"jiǎngzuò","meaning":"a course of lectures","meaningThai":"บรรยาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那次讲座被突然鸣响的火警中断了。","pinyin":"Nà cì jiǎng zuò bèi tū rán míng xiǎng de huǒ jǐng zhōng duàn le。","meaning":"The lecture was curtailed by the fire alarm going off.","meaningThai":"การบรรยายถูกตัดทอนลงเนื่องจากสัญญาณเตือนไฟไหม้ดังขึ้น"},{"chinese":"本书是去年举行的系列讲座的扩充。","pinyin":"Běn shū shì qù nián jǔ háng de xì liè jiǎng zuò de kuò chōng。","meaning":"The book is an expansion of a series of lectures given last year.","meaningThai":"หนังสือเล่มนี้เป็นการขยายชุดการบรรยายที่ได้รับเมื่อปีที่แล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-543","chinese":"渐渐","pinyin":"jiànjiàn","meaning":"gradually","meaningThai":"ค่อยๆ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"水渐渐变深了。","pinyin":"Shuǐ jiàn jiàn biàn shēn le。","meaning":"The water deepened gradually.","meaningThai":"น้ำก็ลึกขึ้นเรื่อยๆ"},{"chinese":"雨渐渐停下来。","pinyin":"Yǔ jiàn jiàn tíng xià lái。","meaning":"The rain is clearing slowly.","meaningThai":"ฝนกำลังซาลงอย่างช้าๆ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-544","chinese":"艰苦","pinyin":"jiānkǔ","meaning":"difficult; hard; arduous","meaningThai":"ลำบาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"艰苦的岁月。","pinyin":"Jian ku de sui yue.","meaning":"Difficult times.","meaningThai":"ช่วงเวลาที่ยากลำบาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-545","chinese":"建立","pinyin":"jiànlì","meaning":"to establish; to set up; to found","meaningThai":"สร้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他就是策划建立新医院的人。","pinyin":"Tā jiù shì cè huá jiàn lì xīn yī yuàn de rén。","meaning":"He was the man behind the plan to build a new hospital.","meaningThai":"เขาคือผู้อยู่เบื้องหลังแผนสร้างโรงพยาบาลแห่งใหม่"},{"chinese":"建立了一块滩头阵地。","pinyin":"Jiàn lì le yī kuài tān tóu zhèn dì。","meaning":"A bridgehead was established.","meaningThai":"มีการสร้างหัวสะพานขึ้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-546","chinese":"简历","pinyin":"jiǎnlì","meaning":"curriculum vitae (CV); résumé; biographical notes","meaningThai":"เรซูเม่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"请把你的简历发给我。","pinyin":"Qǐng bǎ nǐ de jiǎn lì fā gěi wǒ.","meaning":"Please send me your resume.","meaningThai":"กรุณาส่งประวัติการทำงานของคุณมาให้ฉัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-547","chinese":"键盘","pinyin":"jiànpán","meaning":"keyboard","meaningThai":"แป้นพิมพ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"电脑键盘。","pinyin":"Dian nao jian pan.","meaning":"Computer keyboard.","meaningThai":"แป้นพิมพ์คอมพิวเตอร์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-548","chinese":"坚强","pinyin":"jiānqiáng","meaning":"staunch; strong","meaningThai":"แข็งแกร่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我知道这不容易。不过要坚强！","pinyin":"Wǒ zhī dào zhè bù róng yì。 bù guò yào jiān qiáng！","meaning":"It's difficult, I know. But be strong!","meaningThai":"มันยากฉันรู้ แต่จงเข้มแข็ง!"},{"chinese":"她是个坚强、有原则的女人。","pinyin":"Tā shì gè jiān qiáng、 yǒu yuán zé de nǚ rén。","meaning":"She was a strong, principled woman.","meaningThai":"เธอเป็นผู้หญิงที่เข้มแข็งและมีหลักการ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-549","chinese":"建设","pinyin":"jiànshè","meaning":"to build; to construct; to establish; to develop; to institute","meaningThai":"การก่อสร้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在日本，关西机场的建设仍在继续。","pinyin":"Zài rì běn， guān xī jī cháng de jiàn shè réng zài jì xù。","meaning":"In Japan, the building of Kansai airport continues.","meaningThai":"ในญี่ปุ่น การสร้างสนามบินคันไซยังคงดำเนินต่อไป"},{"chinese":"这笔款项已指定用于新校舍建设。","pinyin":"Zhè bǐ kuǎn xiàng yǐ zhǐ dìng yòng yú xīn xiào shě jiàn shè。","meaning":"The money had been earmarked for spending on new school buildings.","meaningThai":"เงินได้ถูกจัดสรรไว้สำหรับการใช้จ่ายในอาคารเรียนใหม่"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-550","chinese":"建造","pinyin":"jiànzào","meaning":"to construct; to build","meaningThai":"วางขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些房子多数是用石头建造的。","pinyin":"Zhè xiē fáng zǐ duō shù shì yòng shí tóu jiàn zào de。","meaning":"Most of the houses are built of stone.","meaningThai":"บ้านส่วนใหญ่สร้างด้วยหิน"},{"chinese":"建筑工人们已经完成了屋顶的建造。","pinyin":"Jiàn zhù gōng rén mén yǐ jīng wán chéng le wū dǐng de jiàn zào。","meaning":"The builders have finished the roof.","meaningThai":"ช่างก่อสร้างมุงหลังคาเสร็จแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-551","chinese":"简直","pinyin":"jiǎnzhí","meaning":"simply; really","meaningThai":"อย่างง่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那场讲座简直无聊透了。","pinyin":"Nà cháng jiǎng zuò jiǎn zhí wú liáo tòu le。","meaning":"The lecture was absolutely deadly.","meaningThai":"การบรรยายนั้นถึงตายอย่างแน่นอน"},{"chinese":"这部电影简直糟透了。","pinyin":"Zhè bù diàn yǐng jiǎn zhí zāo tòu le。","meaning":"The film was just chronic.","meaningThai":"ภาพยนตร์เรื่องนี้เป็นเรื้อรัง"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-552","chinese":"建筑","pinyin":"jiànzhù","meaning":"to construct; building","meaningThai":"สถาปัตยกรรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这座建筑很古老。","pinyin":"Zhe zuo jian zhu hen gu lao.","meaning":"This building is very old.","meaningThai":"ตึกนี้เก่ามาก"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-553","chinese":"较","pinyin":"jiào","meaning":"to compare; to dispute; compared to; (before adj.) relatively; comparatively; rather; also pr. [jiǎo]","meaningThai":"เปรียบเทียบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们想迁移到气候较温暖的地区。","pinyin":"Tā mén xiǎng qiān yí dào qì hòu jiào wēn nuǎn de dì qū。","meaning":"They wanted to move to a warmer climate.","meaningThai":"พวกเขาต้องการย้ายไปอยู่ในสภาพอากาศที่อุ่นขึ้น"},{"chinese":"我说的是较狭义的“教育”。","pinyin":"Wǒ shuō de shì jiào xiá yì de “ jiào yù”。","meaning":"I am using the word 'education' in the narrower sense.","meaningThai":"ฉันใช้คำว่า 'การศึกษา' ในความหมายที่แคบกว่า"}],"partOfSpeech":["adverb","preposition"]},
  {"id":"hsk5-554","chinese":"浇","pinyin":"jiāo","meaning":"to pour liquid; to irrigate (using waterwheel); to water; to cast (molten metal); to mold","meaningThai":"เท","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我打算浇浇我自己的花。","pinyin":"Wǒ dǎ suàn jiāo jiāo wǒ zì jǐ de huā。","meaning":"I am going to water my flowers.","meaningThai":"ฉันจะไปรดน้ำดอกไม้ของฉัน"},{"chinese":"他只是清理了地板并浇上了混凝土。","pinyin":"Tā zhī shì qīng lǐ le dì bǎn bìng jiāo shàng le hùn níng tǔ。","meaning":"He merely cleared and concreted the floors.","meaningThai":"เขาเพียงแค่เคลียร์และเทพื้นคอนกรีต"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-555","chinese":"脚步","pinyin":"jiǎobù","meaning":"footstep; step","meaningThai":"ก้าว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"加快脚步。","pinyin":"Jia kuai jiao bu.","meaning":"Quicken your pace.","meaningThai":"เร่งความเร็วของคุณ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-556","chinese":"教材","pinyin":"jiàocái","meaning":"teaching material","meaningThai":"สื่อการเรียน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"老师发了新教材。","pinyin":"Lǎo shī fā le xīn jiào cái.","meaning":"The teacher handed out new materials.","meaningThai":"ครูแจกเอกสารใหม่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-557","chinese":"角度","pinyin":"jiǎodù","meaning":"angle; point of view","meaningThai":"มุม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"从实际角度考虑，我劝你不要去。","pinyin":"Cóng shí jì jiǎo dù kǎo lǜ， wǒ quàn nǐ bù yào qù。","meaning":"From a practical viewpoint, I'd advise you not to go.","meaningThai":"จากมุมมองเชิงปฏิบัติ ฉันแนะนำว่าอย่าไป"},{"chinese":"这本书是从父亲的角度写的。","pinyin":"Zhè běn shū shì cóng fù qīn de jiǎo dù xiě de。","meaning":"The book is written from the father's point of view.","meaningThai":"หนังสือเล่มนี้เขียนจากมุมมองของพ่อ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-558","chinese":"交换","pinyin":"jiāohuàn","meaning":"to exchange; to swap; to switch (telecom); commutative (math); to commute","meaningThai":"แลกเปลี่ยน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他拒绝考虑与好战分子交换囚犯。","pinyin":"Tā jù jué kǎo lǜ yǔ hǎo zhàn fēn zǐ jiāo huàn qiú fàn。","meaning":"He ruled out any exchange of prisoners with the militants.","meaningThai":"เขาปฏิเสธการแลกเปลี่ยนนักโทษกับกลุ่มติดอาวุธ"},{"chinese":"我幸福极了，谁也甭想跟我交换位置。","pinyin":"Wǒ xìng fú jí le， shuí yě béng xiǎng gēn wǒ jiāo huàn wèi zhì。","meaning":"I'm perfectly happy—I wouldn't change places with anyone.","meaningThai":"ฉันมีความสุขสุดๆ ฉันจะไม่เปลี่ยนสถานที่กับใครเลย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-559","chinese":"交往","pinyin":"jiāowǎng","meaning":"to associate (with); to have contact (with); to hang out (with); to date; (interpersonal) relationship; association; contact","meaningThai":"สื่อสาร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她不想与我这种类型的人交往。","pinyin":"Tā bù xiǎng yǔ wǒ zhè zhǒng lèi xíng de rén jiāo wǎng。","meaning":"She didn't want to associate with the likes of me.","meaningThai":"เธอไม่อยากคบหากับคนอย่างฉัน"},{"chinese":"她通过与这些诗人交往而成名。","pinyin":"Tā tōng guò yǔ zhè xiē shī rén jiāo wǎng ér chéng míng。","meaning":"She became famous through her association with the group of poets.","meaningThai":"เธอมีชื่อเสียงจากการคบหาสมาคมกับกลุ่มกวี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-560","chinese":"交易","pinyin":"jiāoyì","meaning":"to deal; to trade; to transact; transaction; deal","meaningThai":"ซื้อขาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我愿意和你做个交易。","pinyin":"Wǒ yuàn yì hé nǐ zuò gè jiāo yì。","meaning":"I am willing to make a trade with you.","meaningThai":"ฉันยินดีที่จะทำการค้ากับคุณ"},{"chinese":"我们做成了这笔交易。","pinyin":"Wǒ mén zuò chéng le zhè bǐ jiāo yì。","meaning":"We pulled off the deal.","meaningThai":"เราดึงข้อตกลงออกไป"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-561","chinese":"加热","pinyin":"jiārè","meaning":"to heat","meaningThai":"เครื่องทำความร้อน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她所需要做的只是加热布丁。","pinyin":"Tā suǒ xū yào zuò de zhī shì jiā rè bù dīng。","meaning":"All that she would have to do was warm up the pudding.","meaningThai":"สิ่งเดียวที่เธอต้องทำคืออุ่นพุดดิ้ง"},{"chinese":"慢慢加热直到糖溶解为止。","pinyin":"Màn màn jiā rè zhí dào táng róng jiě wéi zhǐ。","meaning":"Heat gently until the sugar dissolves.","meaningThai":"ค่อยๆ ตั้งไฟจนน้ำตาลละลาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-562","chinese":"假如","pinyin":"jiǎrú","meaning":"if","meaningThai":"ถ้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"假如我们给你加钱，你愿意留下吗？","pinyin":"Jiǎ rú wǒ mén gěi nǐ jiā qián， nǐ yuàn yì liú xià ma？","meaning":"If we were to offer you more money, would you stay?","meaningThai":"ถ้าเราเสนอเงินให้คุณมากกว่านี้ คุณจะอยู่ไหม?"},{"chinese":"假如你改变主意的话，一定要告诉我。","pinyin":"Jiǎ rú nǐ gǎi biàn zhǔ yì de huà， yī dìng yào gào sù wǒ。","meaning":"If you should change your mind, do let me know.","meaningThai":"หากคุณควรเปลี่ยนใจ โปรดแจ้งให้เราทราบ"}],"partOfSpeech":["conjunction","verb"]},
  {"id":"hsk5-563","chinese":"加深","pinyin":"jiāshēn","meaning":"to deepen","meaningThai":"ลึกซึ้งยิ่งขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"曾经有过加深一段河道的计划。","pinyin":"Zēng jīng yǒu guò jiā shēn yī duàn hé dào de jì huá。","meaning":"There were plans to deepen a stretch of the river.","meaningThai":"มีแผนจะขุดแม่น้ำให้ลึกลงไป"},{"chinese":"他们窜改了照片，加深皱纹使她尽可能地难看。","pinyin":"Tā mén cuàn gǎi le zhào piàn， jiā shēn zhòu wén shǐ tā jìn kě néng dì nán kàn。","meaning":"They doctored the prints, deepening the lines to make her look as awful as possible.","meaningThai":"พวกเขาปรับแต่งภาพพิมพ์ และเพิ่มเส้นให้ลึกขึ้นเพื่อทำให้เธอดูแย่ที่สุดเท่าที่จะเป็นไปได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-564","chinese":"驾驶","pinyin":"jiàshǐ","meaning":"to pilot (ship, airplane etc); to drive","meaningThai":"ขับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他承认鲁莽驾驶。","pinyin":"Tā chéng rèn lǔ mǎng jià shǐ。","meaning":"He admitted driving recklessly.","meaningThai":"เขายอมรับว่าขับรถโดยประมาท"},{"chinese":"他被控鲁莽驾驶。","pinyin":"Tā bèi kòng lǔ mǎng jià shǐ。","meaning":"He was charged with driving without due care and attention.","meaningThai":"เขาถูกตั้งข้อหาขับรถโดยขาดการดูแลเอาใจใส่ตามสมควร"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-565","chinese":"加速","pinyin":"jiāsù","meaning":"to speed up; to expedite","meaningThai":"เร่งความเร็ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"加速度和速度都是矢量。","pinyin":"Jiā sù dù hé sù dù dū shì shǐ liáng。","meaning":"Acceleration and velocity are both vectors.","meaningThai":"ความเร่งและความเร็วเป็นทั้งเวกเตอร์"},{"chinese":"通货膨胀不断加速。","pinyin":"Tōng huò péng zhàng bù duàn jiā sù。","meaning":"Inflation continues to accelerate.","meaningThai":"อัตราเงินเฟ้อยังคงเร่งตัวขึ้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-566","chinese":"家务","pinyin":"jiāwù","meaning":"household duties; housework","meaningThai":"งานบ้าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你可以看出他很讨厌做家务。","pinyin":"Nǐ kě yǐ kàn chū tā hěn tǎo yàn zuò jiā wù。","meaning":"You could see he was allergic to housework.","meaningThai":"คุณจะเห็นว่าเขาแพ้งานบ้าน"},{"chinese":"你应该偶尔帮忙做做家务。","pinyin":"Nǐ yīng gāi ǒu ěr bāng máng zuò zuò jiā wù。","meaning":"It wouldn't hurt you to help with the housework occasionally.","meaningThai":"การช่วยทำงานบ้านเป็นครั้งคราวก็ไม่เสียหายอะไร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-567","chinese":"驾照","pinyin":"jiàzhào","meaning":"driver's license","meaningThai":"ใบขับขี่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人们发现卡里姆把驾照落在家里了。","pinyin":"Rén mén fā xiàn kǎ lǐ mǔ bǎ jià zhào luò zài jiā lǐ le。","meaning":"It transpired that Kareem had left his driving licence at home.","meaningThai":"ปรากฏว่าคารีมทิ้งใบขับขี่ไว้ที่บ้าน"},{"chinese":"我考驾照时车子熄了三次火。","pinyin":"Wǒ kǎo jià zhào shí chē zǐ xī le sān cì huǒ。","meaning":"I stalled the car three times during my driving test.","meaningThai":"ฉันจอดรถจนตรอกสามครั้งระหว่างการทดสอบขับรถ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-568","chinese":"价值","pinyin":"jiàzhí","meaning":"value; worth; fig. values (ethical, cultural etc)","meaningThai":"ค่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他提供的信息价值难以估量。","pinyin":"Tā tí gōng de xìn xī jià zhí nán yǐ gū liáng。","meaning":"The information he provided was of inestimable value.","meaningThai":"ข้อมูลที่เขาให้มานั้นมีคุณค่าอย่างประเมินค่าไม่ได้"},{"chinese":"这场演出有很大的娱乐价值。","pinyin":"Zhè cháng yǎn chū yǒu hěn dà de yú lè jià zhí。","meaning":"The show was good entertainment value.","meaningThai":"การแสดงมีมูลค่าความบันเทิงที่ดี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-569","chinese":"疾病","pinyin":"jíbìng","meaning":"disease; sickness; ailment","meaningThai":"โรค","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"预防疾病。","pinyin":"Yu fang ji bing.","meaning":"Prevent disease.","meaningThai":"ป้องกันโรค"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-570","chinese":"季度","pinyin":"jìdù","meaning":"quarter of a year; season (sports)","meaningThai":"หนึ่งในสี่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"企业第一季度收益大幅增长。","pinyin":"Qǐ yè dì yī jì dù shōu yì dà fú zēng cháng。","meaning":"Corporate earnings in the first quarter improved sharply.","meaningThai":"ผลประกอบการของบริษัทในไตรมาสแรกปรับตัวดีขึ้นอย่างรวดเร็ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-571","chinese":"结","pinyin":"jié","meaning":"(of a plant) to produce (fruit or seeds); Taiwan pr. [jié]","meaningThai":"ปม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的手很笨拙，无法解开这个结。","pinyin":"Tā de shǒu hěn bèn zhuō， wú fǎ jiě kāi zhè gè jié。","meaning":"His clumsy fingers couldn't untie the knot.","meaningThai":"นิ้วที่เงอะงะของเขาไม่สามารถแก้ปมได้"},{"chinese":"她在樱桃梗上打了个结。","pinyin":"Tā zài yīng táo gěng shàng dǎ le gè jié。","meaning":"She tied a knot in a cherry stem.","meaningThai":"เธอผูกปมด้วยก้านเชอร์รี่"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-572","chinese":"届","pinyin":"jiè","meaning":"to arrive at (place or time); period; to become due; classifier for events, meetings, elections, sporting fixtures, years (of graduation)","meaningThai":"การประชุม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他虽年届九旬，但头脑仍然清晰。","pinyin":"Tā suī nián jiè jiǔ xún， dàn tóu nǎo réng rán qīng xī。","meaning":"Although he's ninety, his mental faculties remain unimpaired.","meaningThai":"แม้ว่าเขาจะอายุเก้าสิบแล้ว แต่ความสามารถทางจิตของเขาก็ยังคงไม่บกพร่อง"},{"chinese":"他渴望成为他们的下一届领导人。","pinyin":"Tā kě wàng chéng wéi tā mén de xià yī jiè lǐng dǎo rén。","meaning":"He aspired to be their next leader.","meaningThai":"เขาปรารถนาที่จะเป็นผู้นำคนต่อไป"}],"partOfSpeech":["measure word"]},
  {"id":"hsk5-573","chinese":"接触","pinyin":"jiēchù","meaning":"to touch; to contact; access; in touch with","meaningThai":"สัมผัส","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"和他人接触是人的基本需要。","pinyin":"Hé tā rén jiē chù shì rén de jī běn xū yào。","meaning":"Contact with other people is a basic human need.","meaningThai":"การติดต่อกับผู้อื่นเป็นความต้องการขั้นพื้นฐานของมนุษย์"},{"chinese":"豌豆与香料酸接触后会褪色。","pinyin":"Wān dòu yǔ xiāng liào suān jiē chù hòu huì tuì sè。","meaning":"Peas will discolour in contact with the acids in vinaigrette.","meaningThai":"ถั่วจะเปลี่ยนสีเมื่อสัมผัสกับกรดในน้ำส้มสายชู"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-574","chinese":"接待","pinyin":"jiēdài","meaning":"to receive (a visitor); to admit (allow sb to enter)","meaningThai":"แผนกต้อนรับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"总统在白宫接待了教皇陛下。","pinyin":"Zǒng tǒng zài bái gōng jiē dài le jiào huáng bì xià。","meaning":"The president received His Holiness at the White House.","meaningThai":"ประธานาธิบดีเข้ารับเสด็จที่ทำเนียบขาว"},{"chinese":"所有来宾必须到接待处报到。","pinyin":"Suǒ yǒu lái bīn bì xū dào jiē dài chǔ bào dào。","meaning":"All visitors must report to reception.","meaningThai":"ผู้เยี่ยมชมทุกคนจะต้องรายงานต่อแผนกต้อนรับ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-575","chinese":"阶段","pinyin":"jiēduàn","meaning":"stage; section; phase; period","meaningThai":"เวที","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些孩子处于不同的成长阶段。","pinyin":"Zhè xiē hái zǐ chǔ yú bù tóng de chéng cháng jiē duàn。","meaning":"The children are at different stages of develop we are pirates, these data are stolen from youdao .","meaningThai":"เด็กเหล่านี้อยู่ในขั้นตอนการพัฒนาที่แตกต่างกัน"},{"chinese":"这种设备仍处于试验阶段。","pinyin":"Zhè zhǒng shè bèi réng chǔ yú shì yàn jiē duàn。","meaning":"The equip we are pirates, these data are stolen from youdao  is still at the experi we are pirates, these data are stolen from youdao al stage.","meaningThai":"อุปกรณ์นี้ยังอยู่ในขั้นทดลอง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-576","chinese":"结构","pinyin":"jiégòu","meaning":"structure; composition; makeup; architecture","meaningThai":"โครงสร้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这座教堂的结构不安全。","pinyin":"Zhè zuò jiào táng de jié gòu bù ān quán。","meaning":"The church was structurally unsound.","meaningThai":"คริสตจักรมีโครงสร้างไม่มั่นคง"},{"chinese":"这座房子结构完好。","pinyin":"Zhè zuò fáng zǐ jié gòu wán hǎo。","meaning":"The building is structurally sound.","meaningThai":"ตัวอาคารมีโครงสร้างแข็งแรง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-577","chinese":"结合","pinyin":"jiéhé","meaning":"to combine; to link; to integrate; binding","meaningThai":"รวมกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"内外因结合导致了公司的倒闭。","pinyin":"Nèi wài yīn jié hé dǎo zhì le gōng sī de dǎo bì。","meaning":"A combination of internal and external factors caused the company to close down.","meaningThai":"ปัจจัยภายในและภายนอกผสมผสานกันทำให้บริษัทต้องปิดตัวลง"},{"chinese":"此次旅行将把出差和娱乐结合起来。","pinyin":"Cǐ cì lǚ háng jiāng bǎ chū chà hé yú lè jié hé qǐ lái。","meaning":"The trip will combine business with pleasure.","meaningThai":"การเดินทางจะผสมผสานธุรกิจเข้ากับความสุข"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-578","chinese":"接近","pinyin":"jiējìn","meaning":"to approach; to get close to","meaningThai":"ใกล้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"风力仍在增强，接近九级。","pinyin":"Fēng lì réng zài zēng qiáng， jiē jìn jiǔ jí。","meaning":"The wind was still rising, approaching a force nine gale.","meaningThai":"ลมยังคงพัดแรงเข้าใกล้พายุเก้าลูก"},{"chinese":"她预言选举结果将很接近。","pinyin":"Tā yù yán xuǎn jǔ jié guǒ jiāng hěn jiē jìn。","meaning":"She predicted (that) the election result would be close.","meaningThai":"เธอทำนาย(ว่า)ผลการเลือกตั้งจะใกล้เข้ามา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-579","chinese":"结论","pinyin":"jiélùn","meaning":"conclusion; verdict; to conclude; to reach a verdict","meaningThai":"ข้อสรุป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"研究得出了重要结论。","pinyin":"Yán jiū dé chū le zhòng yào jié lùn.","meaning":"The research reached an important conclusion.","meaningThai":"การวิจัยได้ข้อสรุปที่สำคัญ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-580","chinese":"节省","pinyin":"jiéshěng","meaning":"saving; to save; to use sparingly; to cut down on","meaningThai":"บันทึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们坐出租车，好节省时间。","pinyin":"Wǒ mén zuò chū zū chē， hǎo jié shěng shí jiān。","meaning":"We'll take a cab to save time.","meaningThai":"เราจะนั่งแท็กซี่เพื่อประหยัดเวลา"},{"chinese":"我们得从现在起节省开支。","pinyin":"Wǒ mén dé cóng xiàn zài qǐ jié shěng kāi zhī。","meaning":"We're going to have to economize from now on.","meaningThai":"เราคงต้องประหยัดตั้งแต่นี้ไป"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-581","chinese":"接收","pinyin":"jiēshōu","meaning":"reception (of transmitted signal); to receive; to accept; to admit; to take over (e.g. a factory); to expropriate","meaningThai":"รับช่วงต่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"电码信号通过卫星天线接收。","pinyin":"Diàn mǎ xìn hào tōng guò wèi xīng tiān xiàn jiē shōu。","meaning":"The coded signal is received by satellite dishes.","meaningThai":"รับสัญญาณเข้ารหัสจากจานดาวเทียม"},{"chinese":"我的电话接收效果很差。","pinyin":"Wǒ de diàn huà jiē shōu xiào guǒ hěn chà。","meaning":"There was very poor reception on my phone.","meaningThai":"โทรศัพท์ของฉันรับสัญญาณได้แย่มาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-582","chinese":"及格","pinyin":"jígé","meaning":"to pass an exam or a test; to meet a minimum standard","meaningThai":"ผ่าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"考试六十分及格。","pinyin":"Kǎo shì liù shí fēn jí gé.","meaning":"Sixty points passes the exam.","meaningThai":"มีคะแนนสอบผ่านหกสิบคะแนน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-583","chinese":"机构","pinyin":"jīgòu","meaning":"mechanism; structure; organization; agency; institution","meaningThai":"กลไก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们不能没有你们机构的帮助。","pinyin":"Wǒ mén bù néng méi yǒu nǐ mén jī gòu de bāng zhù。","meaning":"We can't do without the help of your organization.","meaningThai":"เราไม่สามารถดำเนินการได้หากไม่ได้รับความช่วยเหลือจากองค์กรของคุณ"},{"chinese":"这个机构为穷人提供免费医疗。","pinyin":"Zhè gè jī gòu wéi qióng rén tí gōng miǎn fèi yī liáo。","meaning":"The organization dispenses free health care to the poor.","meaningThai":"องค์กรแจกจ่ายการดูแลสุขภาพฟรีให้กับคนยากจน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-584","chinese":"集合","pinyin":"jíhé","meaning":"to gather; to assemble; (math.) set","meaningThai":"รวมตัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"全体学生获通知到大礼堂集合。","pinyin":"Quán tǐ xué shēng huò tōng zhī dào dà lǐ táng jí hé。","meaning":"All the students were asked to assemble in the main hall.","meaningThai":"ขอให้นักเรียนทุกคนมารวมตัวกันที่ห้องโถงใหญ่"},{"chinese":"我们现在先分开，午饭时再集合。","pinyin":"Wǒ mén xiàn zài xiān fēn kāi， wǔ fàn shí zài jí hé。","meaning":"Let's split up now and meet again at lunchtime.","meaningThai":"แยกย้ายกันไปพักเที่ยงแล้วพบกันใหม่"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-585","chinese":"即将","pinyin":"jíjiāng","meaning":"on the eve of; to be about to; to be on the verge of","meaningThai":"เร็วๆ นี้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些建议即将付诸实施。","pinyin":"Zhè xiē jiàn yì jí jiāng fù zhū shí shī。","meaning":"The recommendations will soon be put into effect.","meaningThai":"คำแนะนำจะมีผลใช้บังคับเร็วๆ นี้"},{"chinese":"他们担心即将修改法律。","pinyin":"Tā mén dān xīn jí jiāng xiū gǎi fǎ lǜ。","meaning":"They are worried about prospective changes in the law.","meaningThai":"พวกเขากังวลเกี่ยวกับการเปลี่ยนแปลงกฎหมายที่อาจเกิดขึ้น"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-586","chinese":"激烈","pinyin":"jīliè","meaning":"(of competition or fighting) intense; fierce; (of pain) acute; (of an expression of opinion) impassioned; vehement; (of a course of action) drastic; extreme","meaningThai":"ดุร้าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那是活动激烈的时期。","pinyin":"Nà shì huó dòng jī liè de shí qī。","meaning":"It was a period of intense activity.","meaningThai":"เป็นช่วงที่มีกิจกรรมเข้มข้น"},{"chinese":"快餐业竞争非常激烈。","pinyin":"Kuài cān yè jìng zhēng fēi cháng jī liè。","meaning":"The fast-food business is intensely competitive.","meaningThai":"ธุรกิจฟาสต์ฟู้ดมีการแข่งขันสูง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-587","chinese":"记录","pinyin":"jìlù","meaning":"to record; record (written account); note-taker; record (in sports etc)","meaningThai":"บันทึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他不想破坏那完美的记录。","pinyin":"Tā bù xiǎng pò huài nà wán měi de jì lù。","meaning":"He wasn't about to blemish that pristine record.","meaningThai":"เขาไม่ได้ตั้งใจจะตำหนิบันทึกอันเก่าแก่นั้น"},{"chinese":"血压和呼吸也做了记录。","pinyin":"Xiě yā hé hū xī yě zuò le jì lù。","meaning":"Blood pressure and respiration are also recorded.","meaningThai":"บันทึกความดันโลหิตและการหายใจด้วย"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-588","chinese":"纪录","pinyin":"jìlù","meaning":"variant of 记录 (but in Taiwan, not for the verb sense \"to record\")","meaningThai":"บันทึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"庄创造了54.64秒的纪录。","pinyin":"Zhuāng chuàng zào le54.64 miǎo de jì lù。","meaning":"Zhuang claimed the record in 54.64 seconds.","meaningThai":"จ้วงอ้างสถิติในเวลา 54.64 วินาที"},{"chinese":"答辩词是警察捏造了访谈纪录。","pinyin":"Dá biàn cí shì jǐng chá niē zào le fǎng tán jì lù。","meaning":"The defence was that the records of the interviews were fabricated by the police.","meaningThai":"ฝ่ายจำเลยคือบันทึกการสัมภาษณ์ถูกตำรวจประดิษฐ์ขึ้น"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-589","chinese":"纪录片","pinyin":"jìlùpiàn","meaning":"newsreel; documentary (film or TV program)","meaningThai":"สารคดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"纪录片的描绘对她很不利。","pinyin":"Jì lù piàn de miáo huì duì tā hěn bù lì。","meaning":"The documentary painted her in a bad light.","meaningThai":"สารคดีวาดภาพเธอในสภาพแสงที่ไม่ดี"},{"chinese":"这部纪录片从十分负面的角度来描绘他。","pinyin":"Zhè bù jì lù piàn cóng shí fēn fù miàn de jiǎo dù lái miáo huì tā。","meaning":"The documentary presents him in a very unfavourable light.","meaningThai":"สารคดีเรื่องนี้นำเสนอเขาในแง่ลบอย่างยิ่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-590","chinese":"急忙","pinyin":"jímáng","meaning":"hastily","meaningThai":"อย่างเร่งรีบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他意识到时间紧迫，急忙赶回家去。","pinyin":"Tā yì shí dào shí jiān jǐn pò， jí máng gǎn huí jiā qù。","meaning":"He rushed home, realizing there was no time to lose.","meaningThai":"เขารีบกลับบ้านโดยตระหนักว่าไม่มีเวลาให้เสียแล้ว"},{"chinese":"她连声再见都没说就急忙离开了。","pinyin":"Tā lián shēng zài jiàn dū méi shuō jiù jí máng lí kāi le。","meaning":"She hurried away without saying goodbye.","meaningThai":"เธอรีบจากไปโดยไม่บอกลา"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-591","chinese":"紧","pinyin":"jǐn","meaning":"tight; strict; close at hand; near; urgent; tense; hard up; short of money; to tighten","meaningThai":"แน่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这条裤子有点紧。","pinyin":"Zhè tiáo kù zǐ yǒu diǎn jǐn。","meaning":"These trousers are a bit tight.","meaningThai":"กางเกงตัวนี้รัดรูปนิดหน่อย"},{"chinese":"这双鞋略有点紧。","pinyin":"Zhè shuāng xié lüè yǒu diǎn jǐn。","meaning":"These shoes are a little on the tight side.","meaningThai":"รองเท้าคู่นี้ค่อนข้างรัดรูปเล็กน้อย"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-592","chinese":"进步","pinyin":"jìnbù","meaning":"progress; improvement; to improve; to progress","meaningThai":"ความคืบหน้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们决不能因进步变得自满。","pinyin":"Wǒ mén jué bù néng yīn jìn bù biàn dé zì mǎn。","meaning":"We must not become complacent about progress.","meaningThai":"เราต้องไม่นิ่งเฉยต่อความก้าวหน้า"},{"chinese":"科学的进步是无法阻挡的。","pinyin":"Kē xué de jìn bù shì wú fǎ zǔ dǎng de。","meaning":"The progress of science is unstoppable.","meaningThai":"ความก้าวหน้าของวิทยาศาสตร์ก็ผ่านพ้นไม่ได้"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-593","chinese":"近代","pinyin":"jìndài","meaning":"the not-very-distant past; modern times, excluding recent decades; (in the context of Chinese history) the period from the Opium Wars until the May 4th Movement (mid-19th century to 1919); capitalist times (pre-1949)","meaningThai":"ยุคปัจจุบัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他被看成是近代最成功的总统。","pinyin":"Tā bèi kàn chéng shì jìn dài zuì chéng gōng de zǒng tǒng。","meaning":"He was regarded as the most successful president of modern times.","meaningThai":"เขาได้รับการยกย่องว่าเป็นประธานาธิบดีที่ประสบความสำเร็จมากที่สุดในยุคปัจจุบัน"},{"chinese":"他在近代语言一科中获得第一名。","pinyin":"Tā zài jìn dài yǔ yán yī kē zhōng huò dé dì yī míng。","meaning":"He got a first in Modern Language.","meaningThai":"เขาได้อันดับหนึ่งในภาษาสมัยใหม่"}],"partOfSpeech":["other"]},
  {"id":"hsk5-594","chinese":"技能","pinyin":"jìnéng","meaning":"technical ability; skill","meaningThai":"ทักษะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们常对自己拥有的技能轻描淡写。","pinyin":"Wǒ mén cháng duì zì jǐ yōng yǒu de jì néng qīng miáo dàn xiě。","meaning":"We often underplay the skills we have.","meaningThai":"เรามักจะมองข้ามทักษะที่เรามี"},{"chinese":"操作这种机器需要什么技能？","pinyin":"Cāo zuò zhè zhǒng jī qì xū yào shí mó jì néng？","meaning":"What skills are needed to operate this machinery?","meaningThai":"ทักษะใดบ้างที่จำเป็นในการใช้งานเครื่องจักรนี้?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-595","chinese":"静","pinyin":"jìng","meaning":"still; calm; quiet; not moving","meaningThai":"เงียบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"房子里静得出奇。","pinyin":"Fáng zǐ lǐ jìng dé chū qí。","meaning":"The house was strangely quiet.","meaningThai":"บ้านเงียบแปลกๆ"},{"chinese":"股东们得到的忠告是，静待危机过去。","pinyin":"Gǔ dōng mén dé dào de zhōng gào shì， jìng dài wēi jī guò qù。","meaning":"Shareholders are being advised to sit tight until the crisis passes.","meaningThai":"แนะนำให้ผู้ถือหุ้นนั่งให้แน่นจนกว่าวิกฤติจะผ่านไป"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-596","chinese":"经典","pinyin":"jīngdiǎn","meaning":"the classics; scriptures; classical; classic (example, case etc); typical","meaningThai":"คลาสสิค","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的第一部小说堪称经典之作。","pinyin":"Tā de dì yī bù xiǎo shuō kān chēng jīng diǎn zhī zuò。","meaning":"Her first novel has all the makings of a classic.","meaningThai":"นวนิยายเรื่องแรกของเธอเต็มไปด้วยความคลาสสิก"},{"chinese":"这本书现在是一部公认的经典著作。","pinyin":"Zhè běn shū xiàn zài shì yī bù gōng rèn de jīng diǎn zhù zuò。","meaning":"The book is now recognized as a classic.","meaningThai":"หนังสือเล่มนี้ได้รับการยอมรับว่าเป็นหนังสือคลาสสิก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-597","chinese":"精力","pinyin":"jīnglì","meaning":"energy","meaningThai":"พลังงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她精力充沛，热情洋溢。","pinyin":"Tā jīng lì chōng pèi， rè qíng yáng yì。","meaning":"She was brimful of energy and enthusiasm.","meaningThai":"เธอเต็มไปด้วยพลังและความกระตือรือร้น"},{"chinese":"她生气勃勃，精力充沛。","pinyin":"Tā shēng qì bó bó， jīng lì chōng pèi。","meaning":"She was bouncy and full of energy.","meaningThai":"เธอเด้งดึ๋งและเต็มไปด้วยพลัง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-598","chinese":"精神","pinyin":"jīngshen","meaning":"spirit; mind; consciousness; thought; mental; psychological; essence; gist","meaningThai":"วิญญาณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们担心他的精神状况。","pinyin":"Wǒ mén dān xīn tā de jīng shén zhuàng kuàng。","meaning":"We're worried about his mental state.","meaningThai":"เรากังวลเกี่ยวกับสภาพจิตใจของเขา"},{"chinese":"这里集体精神比较薄弱。","pinyin":"Zhè lǐ jí tǐ jīng shén bǐ jiào báo ruò。","meaning":"There's not much community spirit around here.","meaningThai":"ที่นี่ไม่ค่อยมีจิตวิญญาณของชุมชนมากนัก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-599","chinese":"惊喜","pinyin":"jīngxǐ","meaning":"nice surprise; to be pleasantly surprised","meaningThai":"เซอร์ไพรส์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那是我曾感受过的最大惊喜。","pinyin":"Nà shì wǒ zēng gǎn shòu guò de zuì dà jīng xǐ。","meaning":"It was the best possible surprise anyone could have given me.","meaningThai":"มันเป็นความประหลาดใจที่ดีที่สุดเท่าที่จะเป็นไปได้ที่ใครๆ ก็สามารถมอบให้ฉันได้"},{"chinese":"这份惊喜礼物是感谢我们给予的帮助。","pinyin":"Zhè fèn jīng xǐ lǐ wù shì gǎn xiè wǒ mén gěi yú de bāng zhù。","meaning":"The surprise gift is a thankyou for our help.","meaningThai":"ของขวัญเซอร์ไพรส์คือการขอบคุณสำหรับความช่วยเหลือของเรา"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-600","chinese":"经营","pinyin":"jīngyíng","meaning":"to engage in (business etc); to run; to operate","meaningThai":"ธุรกิจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这家旅馆环境舒适且经营良好。","pinyin":"Zhè jiā lǚ guǎn huán jìng shū shì qiě jīng yíng liáng hǎo。","meaning":"The hotel is a comfortable and well-run establish we are pirates, these data are stolen from youdao .","meaningThai":"โรงแรมมีความสะดวกสบายและดำเนินกิจการอย่างดี"},{"chinese":"她自己经营这项生意。","pinyin":"Tā zì jǐ jīng yíng zhè xiàng shēng yì。","meaning":"She runs the business by herself.","meaningThai":"เธอดำเนินธุรกิจด้วยตัวเอง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-601","chinese":"纪念","pinyin":"jìniàn","meaning":"to commemorate; to honor the memory of; memento; keepsake; souvenir","meaningThai":"รำลึกถึง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"让我们为纪念他而干杯，怎样？","pinyin":"Ràng wǒ mén wéi jì niàn tā ér gān bēi， zěn yàng？","meaning":"Let's drink to his memory, eh?","meaningThai":"มาดื่มเพื่อความทรงจำของเขากันเถอะ?"},{"chinese":"纪念总统执政4年的活动按计划举行。","pinyin":"Jì niàn zǒng tǒng zhí zhèng 4 nián de huó dòng àn jì huá jǔ háng。","meaning":"The events to mark the president's four years in office went ahead as planned.","meaningThai":"กิจกรรมเฉลิมฉลองการดำรงตำแหน่งสี่ปีของประธานาธิบดีดำเนินไปตามแผนที่วางไว้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-602","chinese":"纪念日","pinyin":"jìniànrì","meaning":"day of commemoration; memorial day","meaningThai":"วันครบรอบปี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"下周一是我第一次遇见你的周年纪念日。","pinyin":"Xià zhōu yī shì wǒ dì yī cì yù jiàn nǐ de zhōu nián jì niàn rì。","meaning":"Next Monday is the anniversary of the day I first met you.","meaningThai":"วันจันทร์หน้าเป็นวันครบรอบวันที่ฉันพบคุณครั้งแรก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-603","chinese":"紧急","pinyin":"jǐnjí","meaning":"urgent; emergency","meaningThai":"ด่วน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"联合国已同意允许提供紧急援助。","pinyin":"Lián hé guó yǐ tóng yì yǔn xǔ tí gōng jǐn jí yuán zhù。","meaning":"The UN has agreed to allow the supply of emergency aid.","meaningThai":"สหประชาชาติได้ตกลงที่จะอนุญาตให้มีการจัดหาความช่วยเหลือฉุกเฉิน"},{"chinese":"紧急出口在公共汽车的尾部。","pinyin":"Jǐn jí chū kǒu zài gōng gòng qì chē de wěi bù。","meaning":"The emergency exit is at the back of the bus.","meaningThai":"ทางออกฉุกเฉินอยู่ที่ด้านหลังของรถบัส"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-604","chinese":"进口","pinyin":"jìnkǒu","meaning":"to import; imported; entrance; inlet (for the intake of air, water etc)","meaningThai":"นำเข้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"进口商品价格较高。","pinyin":"Jìn kǒu shāng pǐn jià gé jiào gāo.","meaning":"Imported goods have higher prices.","meaningThai":"สินค้านำเข้ามีราคาสูงกว่า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-605","chinese":"尽快","pinyin":"jǐnkuài","meaning":"as quickly as possible; as soon as possible","meaningThai":"โดยเร็วที่สุด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"全体同意尽快启动和平进程。","pinyin":"Quán tǐ tóng yì jìn kuài qǐ dòng hé píng jìn chéng。","meaning":"There was total agreement to start the peace process as soon as possible.","meaningThai":"มีข้อตกลงร่วมกันในการเริ่มกระบวนการสันติภาพโดยเร็วที่สุด"},{"chinese":"请尽快将表格填好寄回。","pinyin":"Qǐng jìn kuài jiāng biǎo gé tián hǎo jì huí。","meaning":"I would be grateful if you could send the completed form back as soon as possible.","meaningThai":"ฉันจะขอบคุณหากคุณสามารถส่งแบบฟอร์มที่กรอกเสร็จแล้วกลับมาโดยเร็วที่สุด"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-606","chinese":"尽力","pinyin":"jìnlì","meaning":"to strive one's hardest; to spare no effort","meaningThai":"พยายามอย่างเต็มที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我已经尽力了。","pinyin":"Wǒ yǐ jīng jìn lì le。","meaning":"I've done my best.","meaningThai":"ฉันทำดีที่สุดแล้ว"},{"chinese":"我们尽力而为。","pinyin":"Wǒ mén jìn lì ér wéi。","meaning":"We're doing the best we can.","meaningThai":"เรากำลังทำสิ่งที่ดีที่สุดที่เราสามารถทำได้"}],"partOfSpeech":["adverb","verb"]},
  {"id":"hsk5-607","chinese":"尽量","pinyin":"jǐnliàng","meaning":"as much as possible; to the greatest extent","meaningThai":"พยายามอย่างเต็มที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你坐下时尽量不要无精打采。","pinyin":"Nǐ zuò xià shí jìn liáng bù yào wú jīng dǎ cǎi。","meaning":"Try not to slouch when you are sitting down.","meaningThai":"พยายามอย่าพูดเหลวไหลเมื่อคุณนั่งลง"},{"chinese":"你尽量快点！我们已经晚了。","pinyin":"Nǐ jìn liáng kuài diǎn！ wǒ mén yǐ jīng wǎn le。","meaning":"Try to be quick ! We're late already.","meaningThai":"พยายามที่จะได้อย่างรวดเร็ว! เรามาสายแล้ว"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-608","chinese":"紧密","pinyin":"jǐnmì","meaning":"inseparably close","meaningThai":"ปิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"疼痛和紧张之间有紧密的关联。","pinyin":"Téng tòng hé jǐn zhāng zhī jiān yǒu jǐn mì de guān lián。","meaning":"There is a close connection between pain and tension.","meaningThai":"มีความเชื่อมโยงอย่างใกล้ชิดระหว่างความเจ็บปวดและความตึงเครียด"},{"chinese":"受紫外线照射与皮肤癌紧密相关。","pinyin":"Shòu zǐ wài xiàn zhào shè yǔ pí fū ái jǐn mì xiāng guān。","meaning":"Exposure to ultraviolet light is closely linked to skin cancer.","meaningThai":"การได้รับแสงอัลตราไวโอเลตมีความเชื่อมโยงอย่างใกล้ชิดกับมะเร็งผิวหนัง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-609","chinese":"近年来","pinyin":"jìnnián lái","meaning":"for the past few years","meaningThai":"ในช่วงไม่กี่ปีที่ผ่านมา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"近年来他的书越来越受欢迎。","pinyin":"Jìn nián lái tā de shū yuè lái yuè shòu huān yíng。","meaning":"His books have gained in popularity in recent years.","meaningThai":"หนังสือของเขาได้รับความนิยมในช่วงไม่กี่ปีที่ผ่านมา"},{"chinese":"近年来失业率已急剧上升。","pinyin":"Jìn nián lái shī yè shuài yǐ jí jù shàng shēng。","meaning":"Unemployment has risen sharply in recent years.","meaningThai":"การว่างงานเพิ่มขึ้นอย่างรวดเร็วในช่วงไม่กี่ปีที่ผ่านมา"}],"partOfSpeech":["expression"]},
  {"id":"hsk5-610","chinese":"近期","pinyin":"jìnqī","meaning":"near in time; in the near future; very soon; recent","meaningThai":"ล่าสุด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"近期的事件与我们的决定没有关系。","pinyin":"Jìn qī de shì jiàn yǔ wǒ mén de jué dìng méi yǒu guān xì。","meaning":"Recent events had no bearing on our decision.","meaningThai":"เหตุการณ์ล่าสุดไม่ส่งผลต่อการตัดสินใจของเรา"},{"chinese":"他似乎不为近期的失败感到羞耻。","pinyin":"Tā sì hū bù wéi jìn qī de shī bài gǎn dào xiū chǐ。","meaning":"He seems unabashed by his recent defeat.","meaningThai":"ดูเหมือนเขาจะไม่สะทกสะท้านกับความพ่ายแพ้ครั้งล่าสุดของเขา"}],"partOfSpeech":["other"]},
  {"id":"hsk5-611","chinese":"近日","pinyin":"jìnrì","meaning":"(in) the past few days; recently; (within) the next few days","meaningThai":"ล่าสุด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"近日，重庆三峡大学举办了一个名为“手机忍者”的活动。","pinyin":"Jìn rì， zhòng qìng sān xiá dà xué jǔ bàn le yī gè míng wéi “ shǒu jī rěn zhě ” de huó dòng。","meaning":"Recently, Chongqing Three Gorges University has held an activity named \"Cell Phone Ninja\".","meaningThai":"ล่าสุด Chongqing Three Gorges University ได้จัดกิจกรรมชื่อ \"Cell Phone Ninja\""},{"chinese":"近日，为了帮助学生更好地理解这一点，浙江湖州市第四中学举办了一场活动。","pinyin":"Jìn rì， wéi le bāng zhù xué shēng gēng hǎo dì lǐ jiě zhè yī diǎn， zhè jiāng hú zhōu shì dì sì zhōng xué jǔ bàn le yī cháng huó dòng。","meaning":"Recently, to help students better understand this, the No.4 Middle School in Huzhou, Zhejiang held an activity.","meaningThai":"เมื่อเร็วๆ นี้ เพื่อช่วยให้นักเรียนเข้าใจเรื่องนี้มากขึ้น โรงเรียนมัธยมหมายเลข 4 ในเมืองหูโจว เจ้อเจียงจึงได้จัดกิจกรรม"}],"partOfSpeech":["other"]},
  {"id":"hsk5-612","chinese":"今日","pinyin":"jīnrì","meaning":"today","meaningThai":"วันนี้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该国所有的机场今日都在正常运营。","pinyin":"Gāi guó suǒ yǒu de jī cháng jīn rì dū zài zhèng cháng yùn yíng。","meaning":"All airports in the country are working normally today.","meaningThai":"วันนี้สนามบินทุกแห่งในประเทศยังใช้งานได้ตามปกติ"},{"chinese":"今日纽约证券交易所的股价下跌。","pinyin":"Jīn rì niǔ yuē zhèng quàn jiāo yì suǒ de gǔ jià xià diē。","meaning":"Share prices fell on Wall Street today.","meaningThai":"ราคาหุ้นร่วงลงในวอลล์สตรีทวันนี้"}],"partOfSpeech":["other"]},
  {"id":"hsk5-613","chinese":"谨慎","pinyin":"jǐnshèn","meaning":"cautious; prudent","meaningThai":"ระมัดระวัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"谨慎行事。","pinyin":"Jin shen xing shi.","meaning":"Act cautiously.","meaningThai":"ดำเนินการด้วยความระมัดระวัง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-614","chinese":"进一步","pinyin":"jìnyíbù","meaning":"to go a step further; (develop, understand, improve etc) more; further","meaningThai":"ไกลออกไป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人们期待信贷条件的进一步放宽。","pinyin":"Rén mén qī dài xìn dài tiáo jiàn de jìn yī bù fàng kuān。","meaning":"People were betting on a further easing of credit conditions.","meaningThai":"ผู้คนต่างเดิมพันกับเงื่อนไขสินเชื่อที่ผ่อนคลายยิ่งขึ้น"},{"chinese":"她克制自己，不再进一步提问。","pinyin":"Tā kè zhì zì jǐ， bù zài jìn yī bù tí wèn。","meaning":"She forbore to ask any further questions.","meaningThai":"เธอไม่กล้าที่จะถามคำถามเพิ่มเติม"}],"partOfSpeech":["adverb","adjective"]},
  {"id":"hsk5-615","chinese":"极其","pinyin":"jíqí","meaning":"extremely","meaningThai":"อย่างที่สุด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她最近行为极其反常。","pinyin":"Tā zuì jìn háng wéi jí qí fǎn cháng。","meaning":"She's been behaving very oddly lately.","meaningThai":"ช่วงนี้เธอมีพฤติกรรมแปลกๆ มาก"},{"chinese":"经济仍然极其脆弱。","pinyin":"Jīng jì réng rán jí qí cuì ruò。","meaning":"The economy remains extremely fragile.","meaningThai":"เศรษฐกิจยังคงเปราะบางมาก"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-616","chinese":"机器","pinyin":"jīqì","meaning":"machine","meaningThai":"เครื่องจักร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些机器夜以继日地运转着。","pinyin":"Zhè xiē jī qì yè yǐ jì rì dì yùn zhuǎn zháo。","meaning":"The machines are kept running night and day.","meaningThai":"เครื่องจักรยังคงทำงานทั้งกลางวันและกลางคืน"},{"chinese":"美国农民使用机器收割谷穗。","pinyin":"Měi guó nóng mín shǐ yòng jī qì shōu gē gǔ suì。","meaning":"American farmers use machines to pick the ears of corn from the plants.","meaningThai":"เกษตรกรชาวอเมริกันใช้เครื่องจักรในการเด็ดรวงข้าวโพดจากต้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-617","chinese":"机器人","pinyin":"jīqìrén","meaning":"robot; android","meaningThai":"หุ่นยนต์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"机器人可以完成重复性工作。","pinyin":"Jī qì rén kě yǐ wán chéng chóng fù xìng gōng zuò.","meaning":"Robots can complete repetitive tasks.","meaningThai":"หุ่นยนต์สามารถทำงานซ้ำๆ ได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-618","chinese":"肌肉","pinyin":"jīròu","meaning":"muscle; flesh","meaningThai":"กล้ามเนื้อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"锻炼肌肉。","pinyin":"Duan lian ji rou.","meaning":"Build muscle.","meaningThai":"สร้างกล้ามเนื้อ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-619","chinese":"计算","pinyin":"jìsuàn","meaning":"to count; to calculate; to compute","meaningThai":"คำนวณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你的计算完全错误。","pinyin":"Nǐ de jì suàn wán quán cuò wù。","meaning":"Your calculation is way off beam.","meaningThai":"การคำนวณของคุณอยู่นอกลำแสง"},{"chinese":"计算机无法启动。","pinyin":"Jì suàn jī wú fǎ qǐ dòng。","meaning":"The computer won't boot.","meaningThai":"คอมพิวเตอร์จะไม่บูต"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-620","chinese":"计算机","pinyin":"jìsuànjī","meaning":"computer; (Tw) calculator","meaningThai":"คอมพิวเตอร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们认为计算机出了问题。","pinyin":"Wǒ mén rèn wéi jì suàn jī chū le wèn tí。","meaning":"We think there's something wrong with the computer.","meaningThai":"เราคิดว่ามีบางอย่างผิดปกติกับคอมพิวเตอร์"},{"chinese":"新的计算机软件往往和旧式计算机不兼容。","pinyin":"Xīn de jì suàn jī ruǎn jiàn wǎng wǎng hé jiù shì jì suàn jī bù jiān róng。","meaning":"New computer software is often incompatible with older computers.","meaningThai":"ซอฟต์แวร์คอมพิวเตอร์ใหม่มักเข้ากันไม่ได้กับคอมพิวเตอร์รุ่นเก่า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-621","chinese":"集体","pinyin":"jítǐ","meaning":"collective (decision); joint (effort); a group; a team; en masse; as a group","meaningThai":"โดยรวม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"日本人喜欢集体旅游。","pinyin":"Rì běn rén xǐ huān jí tǐ lǚ yóu。","meaning":"The Japanese like to travel in groups.","meaningThai":"คนญี่ปุ่นชอบเดินทางเป็นกลุ่ม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-622","chinese":"救","pinyin":"jiù","meaning":"variant of 救","meaningThai":"บันทึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"为了救他的命，医生们截去了他的双腿。","pinyin":"Wéi le jiù tā de mìng， yī shēng mén jié qù le tā de shuāng tuǐ。","meaning":"To save his life, doctors amputated his legs.","meaningThai":"เพื่อช่วยชีวิตเขา แพทย์จึงตัดขาของเขาออก"},{"chinese":"现在没人能救你了，小姐。","pinyin":"Xiàn zài méi rén néng jiù nǐ le， xiǎo jiě。","meaning":"There's none can save you now, missy.","meaningThai":"ตอนนี้ไม่มีใครสามารถช่วยคุณได้นะคุณหนู"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-623","chinese":"酒吧","pinyin":"jiǔbā","meaning":"bar; pub; saloon","meaningThai":"บาร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这就是典型的英格兰酒吧。","pinyin":"Zhè jiù shì diǎn xíng de yīng gé lán jiǔ bā。","meaning":"This is your typical English pub.","meaningThai":"นี่คือผับอังกฤษทั่วไปของคุณ"},{"chinese":"这间酒吧只对会员开放。","pinyin":"Zhè jiān jiǔ bā zhī duì huì yuán kāi fàng。","meaning":"The bar is for members only.","meaningThai":"บาร์นี้มีไว้สำหรับสมาชิกเท่านั้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-624","chinese":"救护车","pinyin":"jiùhùchē","meaning":"ambulance","meaningThai":"รถพยาบาล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"救护车迅速将伤员送往医院。","pinyin":"Jiù hù chē xùn sù jiāng shāng yuán sòng wǎng yī yuàn。","meaning":"Ambulances rushed the injured to the hospital.","meaningThai":"รถพยาบาลรีบนำผู้บาดเจ็บส่งโรงพยาบาล"},{"chinese":"救护车赶到时他已神志不清。","pinyin":"Jiù hù chē gǎn dào shí tā yǐ shén zhì bù qīng。","meaning":"By the time the ambulance arrived he was unconscious.","meaningThai":"เมื่อรถพยาบาลมาถึงเขาก็หมดสติไป"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-625","chinese":"就业","pinyin":"jiùyè","meaning":"to get a job; employment","meaningThai":"การจ้างงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"最近的举措还未能根除就业歧视。","pinyin":"Zuì jìn de jǔ cuò huán wèi néng gēn chú jiù yè qí shì。","meaning":"Recent measures have not eliminated discrimination in employment.","meaningThai":"มาตรการล่าสุดไม่ได้ขจัดการเลือกปฏิบัติในการจ้างงาน"},{"chinese":"每年有250000人进入就业市场。","pinyin":"Měi nián yǒu 250000 rén jìn rù jiù yè shì cháng。","meaning":"Every year, 250,000 people enter the job market.","meaningThai":"ทุกปี 250,000 คนเข้าสู่ตลาดงาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-626","chinese":"久远","pinyin":"jiǔyuǎn","meaning":"old","meaningThai":"เก่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们一起度过的时光现已成为久远的记忆。","pinyin":"Wǒ mén yī qǐ dù guò de shí guāng xiàn yǐ chéng wéi jiǔ yuǎn de jì yì。","meaning":"The time we spent together is now a distant memory.","meaningThai":"เวลาที่เราใช้ร่วมกันตอนนี้กลายเป็นความทรงจำอันห่างไกล"},{"chinese":"在更久远的过去，其他冰河时代也曾发生过这种情况。","pinyin":"Zài gēng jiǔ yuǎn de guò qù， qí tā bīng hé shí dài yě zēng fā shēng guò zhè zhǒng qíng kuàng。","meaning":"In the much more distant past, other ice ages have occurred.","meaningThai":"ในอดีตอันไกลโพ้น ยุคน้ำแข็งอื่นๆ ได้เกิดขึ้น"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-627","chinese":"急需","pinyin":"jíxū","meaning":"to urgently need; urgent need","meaningThai":"ความจำเป็นเร่งด่วน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个项目急需追加现金投资。","pinyin":"Zhè gè xiàng mù jí xū zhuī jiā xiàn jīn tóu zī。","meaning":"The project badly needs a transfusion of cash.","meaningThai":"โครงการต้องการการถ่ายเงินสดอย่างมาก"},{"chinese":"我急需一份警方报告。","pinyin":"Wǒ jí xū yī fèn jǐng fāng bào gào。","meaning":"I need a copy of the police report on the double.","meaningThai":"ฉันต้องการสำเนาใบแจ้งความของตำรวจในเรื่องคู่"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-628","chinese":"记忆","pinyin":"jìyì","meaning":"to remember; to recall; memory","meaningThai":"ความทรงจำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"美好记忆。","pinyin":"Mei hao ji yi.","meaning":"Beautiful memory.","meaningThai":"ความทรงจำที่สวยงาม"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-629","chinese":"记载","pinyin":"jìzǎi","meaning":"to write down; to record; written account","meaningThai":"บันทึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种疾病的起因已有完备的记载。","pinyin":"Zhè zhǒng jí bìng de qǐ yīn yǐ yǒu wán bèi de jì zǎi。","meaning":"Causes of the disease have been well documented.","meaningThai":"สาเหตุของโรคได้รับการบันทึกไว้เป็นอย่างดี"},{"chinese":"那是历史记载中最热的七月。","pinyin":"Nà shì lì shǐ jì zǎi zhōng zuì rè de qī yuè。","meaning":"It was the hottest July on record.","meaningThai":"เดือนกรกฎาคมเป็นเดือนที่ร้อนที่สุดเป็นประวัติการณ์"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-630","chinese":"急诊","pinyin":"jízhěn","meaning":"to give or receive urgent medical treatment; emergency treatment (at a hospital emergency department, or from a doctor on a house call)","meaningThai":"ภาวะฉุกเฉิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"一名妇女被紧急送进急诊室去洗胃。","pinyin":"Yī míng fù nǚ bèi jǐn jí sòng jìn jí zhěn shì qù xǐ wèi。","meaning":"One woman was rushed to the emergency room to have her stomach pumped.","meaningThai":"หญิงรายหนึ่งถูกนำตัวส่งห้องฉุกเฉินเพื่อปั๊มท้อง"},{"chinese":"随时都有急诊服务，并提供医疗咨询。","pinyin":"Suí shí dū yǒu jí zhěn fú wù， bìng tí gōng yī liáo zī xún。","meaning":"The emergency services were on hand with medical advice.","meaningThai":"บริการฉุกเฉินพร้อมให้คำแนะนำทางการแพทย์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-631","chinese":"集中","pinyin":"jízhōng","meaning":"to concentrate; to centralize; to focus; centralized; concentrated; to put together","meaningThai":"เข้มข้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"味蕾集中在舌尖、舌根及舌边。","pinyin":"Wèi lěi jí zhōng zài shé jiān、 shé gēn jí shé biān。","meaning":"Taste buds are concentrated at the tip and rear of the tongue and around its periphery.","meaningThai":"ปุ่มรับรสจะกระจุกอยู่ที่ปลายลิ้น ด้านหลังของลิ้น และรอบๆ ขอบลิ้น"},{"chinese":"有必要使讨论的焦点更加集中。","pinyin":"Yǒu bì yào shǐ tǎo lùn de jiāo diǎn gēng jiā jí zhōng。","meaning":"There is a need to sharpen the focus of the discussion.","meaningThai":"จำเป็นต้องทำให้จุดเน้นของการอภิปรายคมชัดขึ้น"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-632","chinese":"据","pinyin":"jù","meaning":"variant of 据","meaningThai":"ตาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"据一名官员说，已有一百多人被捕。","pinyin":"Jù yī míng guān yuán shuō， yǐ yǒu yī bǎi duō rén bèi bǔ。","meaning":"According to one official more than a hundred people have been arrested.","meaningThai":"ตามข้อมูลของเจ้าหน้าที่รายหนึ่ง มีผู้ถูกจับกุมมากกว่าร้อยคน"},{"chinese":"据米克说，这是一部了不起的电影。","pinyin":"Jù mǐ kè shuō， zhè shì yī bù le bù qǐ de diàn yǐng。","meaning":"According to Mick, it's a great movie.","meaningThai":"ตามคำบอกเล่าของมิก มันเป็นหนังที่ยอดเยี่ยม"}],"partOfSpeech":["preposition","other"]},
  {"id":"hsk5-633","chinese":"距","pinyin":"jù","meaning":"at a distance of; distance; to be apart","meaningThai":"ระยะทาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"距下面的岩石有五十米的垂直距离。","pinyin":"Jù xià miàn de yán shí yǒu wǔ shí mǐ de chuí zhí jù lí。","meaning":"There was a sheer drop of fifty metres to the rocks below.","meaningThai":"มีความสูงชันถึงห้าสิบเมตรถึงโขดหินเบื้องล่าง"},{"chinese":"她的最后一掷距世界纪录只差三厘米。","pinyin":"Tā de zuì hòu yī zhì jù shì jiè jì lù zhī chà sān lí mǐ。","meaning":"Her last throw was only three centimetres short of the world record.","meaningThai":"การขว้างครั้งสุดท้ายของเธอนั้นสั้นกว่าสถิติโลกเพียงสามเซนติเมตร"}],"partOfSpeech":["preposition","verb","other"]},
  {"id":"hsk5-634","chinese":"捐","pinyin":"juān","meaning":"to relinquish; to abandon; to contribute; to donate; (bound form) tax; levy","meaningThai":"บริจาค","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"当地一位商人出面捐了一大笔款给学校。","pinyin":"Dāng dì yī wèi shāng rén chū miàn juān le yī dà bǐ kuǎn gěi xué xiào。","meaning":"A local businessman stepped in with a large donation for the school.","meaningThai":"นักธุรกิจท้องถิ่นรายหนึ่งก้าวเข้ามาพร้อมเงินบริจาคจำนวนมากให้กับโรงเรียน"},{"chinese":"许多人捐了很多钱。","pinyin":"Xǔ duō rén juān le hěn duō qián。","meaning":"Many people donated much money.","meaningThai":"หลายคนบริจาคเงินเป็นจำนวนมาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-635","chinese":"具备","pinyin":"jùbèi","meaning":"to possess; to have; equipped with; able to fulfill (conditions or requirements)","meaningThai":"มี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"神经元本身毕竟不具备智能。","pinyin":"Shén jīng yuán běn shēn bì jìng bù jù bèi zhì néng。","meaning":"Nerve cells, after all, do not have intelligence of their own.","meaningThai":"เซลล์ประสาทไม่มีความฉลาดในตัวเอง"},{"chinese":"这是同类型汽车中首部具备这种设计特点的。","pinyin":"Zhè shì tóng lèi xíng qì chē zhōng shǒu bù jù bèi zhè zhǒng shè jì tè diǎn de。","meaning":"It is the first car of its type to have this design feature.","meaningThai":"เป็นรถยนต์คันแรกที่มีคุณสมบัติการออกแบบนี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-636","chinese":"剧场","pinyin":"jùchǎng","meaning":"theater","meaningThai":"โรงภาพยนตร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"幕布升起，剧场内的灯光暗了下来。","pinyin":"Mù bù shēng qǐ， jù cháng nèi de dēng guāng àn le xià lái。","meaning":"The lights in the theatre dimmed as the curtain rose.","meaningThai":"แสงไฟในโรงละครจางลงเมื่อม่านลุกขึ้น"},{"chinese":"她离开剧场，被记者穷追不舍。","pinyin":"Tā lí kāi jù cháng， bèi jì zhě qióng zhuī bù shě。","meaning":"She left the theatre, hotly pursued by the press.","meaningThai":"เธอออกจากโรงละครโดยสื่อมวลชนติดตามอย่างถึงพริกถึงขิง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-637","chinese":"巨大","pinyin":"jùdà","meaning":"huge; immense; very large; tremendous; gigantic; enormous","meaningThai":"ใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"尽管危险巨大，我还是活了下来。","pinyin":"Jìn guǎn wēi xiǎn jù dà， wǒ huán shì huó le xià lái。","meaning":"In spite of great peril, I have survived.","meaningThai":"แม้จะเจออันตรายมากมาย แต่ฉันก็ยังรอดมาได้"},{"chinese":"公司无法承担如此巨大的亏损。","pinyin":"Gōng sī wú fǎ chéng dān rú cǐ jù dà de kuī sǔn。","meaning":"The company is unable to absorb such huge losses.","meaningThai":"บริษัทไม่สามารถรับผลขาดทุนมหาศาลดังกล่าวได้"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-638","chinese":"绝对","pinyin":"juéduì","meaning":"absolute; unconditional","meaningThai":"แน่นอน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我觉得它绝对精彩。","pinyin":"Wǒ jué dé tā jué duì jīng cǎi。","meaning":"I thought it was absolutely tremendous.","meaningThai":"ฉันคิดว่ามันยิ่งใหญ่มาก"},{"chinese":"我绝对拒绝结婚。","pinyin":"Wǒ jué duì jù jué jié hūn。","meaning":"I absolutely refuse to get married.","meaningThai":"ฉันปฏิเสธที่จะแต่งงานโดยเด็ดขาด"}],"partOfSpeech":["adverb","adjective"]},
  {"id":"hsk5-639","chinese":"决赛","pinyin":"juésài","meaning":"finals (of a competition)","meaningThai":"รอบชิงชนะเลิศ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"令人遗憾的是，他并没有在决赛发挥他的最佳水平。","pinyin":"Líng rén yí hàn de shì， tā bìng méi yǒu zài jué sài fā huī tā de zuì jiā shuǐ píng。","meaning":"The regrettable thing is that he didn't even play at his highest level in the finals.","meaningThai":"สิ่งที่น่าเสียใจก็คือเขาไม่ได้เล่นในระดับสูงสุดในรอบชิงชนะเลิศด้วยซ้ำ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-640","chinese":"角色","pinyin":"juésè","meaning":"role; character in a novel; persona; also pr. [jiǎo sè]","meaningThai":"บทบาท","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"特里的角色已从演出中取消了。","pinyin":"Tè lǐ de jiǎo sè yǐ cóng yǎn chū zhōng qǔ xiāo le。","meaning":"Terry's character has been written out of the show.","meaningThai":"ตัวละครของเทอร์รี่ถูกตัดออกจากการแสดง"},{"chinese":"她拒绝承担传统妇女的角色。","pinyin":"Tā jù jué chéng dān chuán tǒng fù nǚ de jiǎo sè。","meaning":"She refused to take on the traditional woman's role.","meaningThai":"เธอปฏิเสธที่จะรับบทบาทของผู้หญิงตามประเพณี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-641","chinese":"决心","pinyin":"juéxīn","meaning":"determination; resolution; determined; firm and resolute; to make up one's mind","meaningThai":"การกำหนด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"政府决心解决通货膨胀问题。","pinyin":"Zhèng fǔ jué xīn jiě jué tōng huò péng zhàng wèn tí。","meaning":"The government is determined to tackle inflation.","meaningThai":"รัฐบาลมุ่งมั่นที่จะจัดการกับภาวะเงินเฟ้อ"},{"chinese":"她下了决心不要太气馁。","pinyin":"Tā xià le jué xīn bù yào tài qì něi。","meaning":"She was determined not to be too discouraged.","meaningThai":"เธอตั้งใจว่าจะไม่ท้อแท้เกินไป"}],"partOfSpeech":["noun","adverb"]},
  {"id":"hsk5-642","chinese":"居民","pinyin":"jūmín","meaning":"resident; inhabitant","meaningThai":"ถิ่นที่อยู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"当地居民和警察之间有过冲突。","pinyin":"Dāng dì jū mín hé jǐng chá zhī jiān yǒu guò chōng tū。","meaning":"There were confrontations between local residents and the police.","meaningThai":"มีการเผชิญหน้ากันระหว่างชาวบ้านกับตำรวจ"},{"chinese":"他们已经要求居民待在自己家里。","pinyin":"Tā mén yǐ jīng yào qiú jū mín dài zài zì jǐ jiā lǐ。","meaning":"They have asked the residents to remain in their homes.","meaningThai":"พวกเขาขอให้ชาวบ้านอยู่ในบ้านของตน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-643","chinese":"居然","pinyin":"jūrán","meaning":"unexpectedly; to one's surprise; go so far as to","meaningThai":"จริงๆ แล้ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"食品居然并不那么昂贵。","pinyin":"Shí pǐn jū rán bìng bù nà mó áng guì。","meaning":"The food was not actually all that expensive.","meaningThai":"อาหารก็ไม่ได้แพงขนาดนั้นจริงๆ"},{"chinese":"这居然还很有趣。","pinyin":"Zhè jū rán huán hěn yǒu qù。","meaning":"It was actually quite fun after all.","meaningThai":"มันค่อนข้างสนุกจริงๆ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-644","chinese":"据说","pinyin":"jùshuō","meaning":"it is said that; reportedly","meaningThai":"มันบอกว่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"据说这个乐队已经决定解散。","pinyin":"Jù shuō zhè gè lè duì yǐ jīng jué dìng jiě sàn。","meaning":"The band have reportedly decided to split up.","meaningThai":"มีรายงานว่าวงได้ตัดสินใจแยกทางกัน"},{"chinese":"据说他非常适合将来的任务。","pinyin":"Jù shuō tā fēi cháng shì hé jiāng lái de rèn wù。","meaning":"He was tailor-made, it was said, for the task ahead.","meaningThai":"ว่ากันว่าเขาถูกออกแบบให้เหมาะกับงานที่อยู่ข้างหน้า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-645","chinese":"具体","pinyin":"jùtǐ","meaning":"concrete; definite; specific","meaningThai":"เฉพาะเจาะจง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这场讨论围绕具体的会计技巧。","pinyin":"Zhè cháng tǎo lùn wéi rào jù tǐ de huì jì jì qiǎo。","meaning":"The debate revolves around specific accounting techniques.","meaningThai":"การอภิปรายเกี่ยวกับเทคนิคการบัญชีเฉพาะ"},{"chinese":"我当时没有明确而具体的证据。","pinyin":"Wǒ dāng shí méi yǒu míng què ér jù tǐ de zhèng jù。","meaning":"I had no concrete evidence.","meaningThai":"ฉันไม่มีหลักฐานที่เป็นรูปธรรม"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-646","chinese":"具有","pinyin":"jùyǒu","meaning":"to have; to possess","meaningThai":"มี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她具有广博的自然史知识。","pinyin":"Tā jù yǒu guǎng bó de zì rán shǐ zhī shí。","meaning":"She has an encyclopedic knowledge of natural history.","meaningThai":"เธอมีความรู้สารานุกรมเกี่ยวกับประวัติศาสตร์ธรรมชาติ"},{"chinese":"这种新油漆具有耐热性。","pinyin":"Zhè zhǒng xīn yóu qī jù yǒu nài rè xìng。","meaning":"This new paint is designed to resist heat.","meaningThai":"สีใหม่นี้ได้รับการออกแบบให้ต้านทานความร้อน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-647","chinese":"居住","pinyin":"jūzhù","meaning":"to reside; to dwell; to live in a place; resident in","meaningThai":"สด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我喜欢在船上居住的建议。","pinyin":"Wǒ xǐ huān zài chuán shàng jū zhù de jiàn yì。","meaning":"I like the idea of living on a boat.","meaningThai":"ฉันชอบความคิดในการใช้ชีวิตบนเรือ"},{"chinese":"囚犯的居住条件极为恶劣。","pinyin":"Qiú fàn de jū zhù tiáo jiàn jí wéi è liè。","meaning":"The prisoners were living in appalling conditions.","meaningThai":"นักโทษอยู่ในสภาพที่น่าตกใจ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-648","chinese":"橘子","pinyin":"júzi","meaning":"tangerine","meaningThai":"ส้มเขียวหวาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"橘子含有丰富的维生素C。","pinyin":"Jú zǐ hán yǒu fēng fù de wéi shēng sùC。","meaning":"Oranges are rich in vitamin C.","meaningThai":"ส้มอุดมไปด้วยวิตามินซี"},{"chinese":"李掰下一小瓣橘子递给他。","pinyin":"Lǐ bāi xià yī xiǎo bàn jú zǐ dì gěi tā。","meaning":"Lee broke off a small piece of orange and held it out to him.","meaningThai":"ลีหักส้มชิ้นเล็ก ๆ แล้วยื่นให้เขา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-649","chinese":"开发","pinyin":"kāifā","meaning":"to exploit (a resource); to open up (for development); to develop","meaningThai":"พัฒนา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"农民已获得政府授权开发这些农场。","pinyin":"Nóng mín yǐ huò dé zhèng fǔ shòu quán kāi fā zhè xiē nóng cháng。","meaning":"Farmers were granted concessions from the government to develop the farms.","meaningThai":"เกษตรกรได้รับสัมปทานจากรัฐบาลในการพัฒนาฟาร์ม"},{"chinese":"资金也会流入越南本地开发项目。","pinyin":"Zī jīn yě huì liú rù yuè nán běn dì kāi fā xiàng mù。","meaning":"Money will also go into local development projects in Vietnam.","meaningThai":"เงินจะถูกส่งไปยังโครงการพัฒนาท้องถิ่นในเวียดนามด้วย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-650","chinese":"开放","pinyin":"kāifàng","meaning":"to bloom; to open; to be open (to the public); to open up (to the outside); to be open-minded; unrestrained by convention; unconstrained in one's sexuality","meaningThai":"เปิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这次展览不对公众开放。","pinyin":"Zhè cì zhǎn lǎn bù duì gōng zhòng kāi fàng。","meaning":"The exhibition is not open to the general public.","meaningThai":"นิทรรศการนี้ไม่เปิดให้บุคคลทั่วไปเข้าชม"},{"chinese":"这所宅院已向公众开放。","pinyin":"Zhè suǒ zhái yuàn yǐ xiàng gōng zhòng kāi fàng。","meaning":"The house had been thrown open to the public.","meaningThai":"บ้านถูกโยนออกไปเปิดให้ประชาชนทั่วไป"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-651","chinese":"开幕","pinyin":"kāimù","meaning":"to open (a conference); to inaugurate","meaningThai":"เปิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们隆重地剪彩，宣布展会开幕。","pinyin":"Tā mén lóng zhòng dì jiǎn cǎi， xuān bù zhǎn huì kāi mù。","meaning":"They ceremoniously cut a piece of ribbon, declaring the exhibition open.","meaningThai":"พวกเขาตัดริบบิ้นเป็นพิธีประกาศเปิดนิทรรศการ"},{"chinese":"我们提早到了那儿参加开幕式。","pinyin":"Wǒ mén tí zǎo dào le nà ér cān jiā kāi mù shì。","meaning":"We got there in good time for the opening ceremony.","meaningThai":"เรามาทันช่วงพิธีเปิดพอดี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-652","chinese":"开幕式","pinyin":"kāimùshì","meaning":"opening ceremony","meaningThai":"พิธีเปิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"开幕式很精彩。","pinyin":"Kai mu shi hen jing cai.","meaning":"The opening ceremony was brilliant.","meaningThai":"พิธีเปิดก็ยอดเยี่ยมมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-653","chinese":"开水","pinyin":"kāishuǐ","meaning":"boiled water; boiling water","meaningThai":"น้ำเดือด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"阿姨，您别客气，喝杯开水就行。","pinyin":"Ā yí， nín bié kè qì， hē bēi kāi shuǐ jiù háng。","meaning":"No need to trouble yourself, Auntie. A glass of boiled water will be plenty.","meaningThai":"ไม่ต้องลำบากใจหรอกคุณป้า น้ำต้มสุกหนึ่งแก้วก็เพียงพอแล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-654","chinese":"开通","pinyin":"kāitōng","meaning":"to open (a new road or railway line); to set up (a hotline); to launch (a service); to subscribe to (a members-only service)","meaningThai":"เปิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们的电话在正常办公时间一直开通。","pinyin":"Wǒ mén de diàn huà zài zhèng cháng bàn gōng shí jiān yī zhí kāi tōng。","meaning":"Our telephone lines are open during normal office hours.","meaningThai":"สายโทรศัพท์ของเราเปิดให้บริการในช่วงเวลาทำการปกติ"},{"chinese":"一大堆问题也许会延迟新建桥梁的开通。","pinyin":"Yī dà duī wèn tí yě xǔ huì yán chí xīn jiàn qiáo liáng de kāi tōng。","meaning":"A host of problems may delay the opening of the new bridge.","meaningThai":"ปัญหามากมายอาจทำให้การเปิดสะพานใหม่ล่าช้า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-655","chinese":"开业","pinyin":"kāiyè","meaning":"to open a business; to open a practice; open (for business)","meaningThai":"เปิดทำการแล้ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在法国开业是他们的一个大胆行动。","pinyin":"Zài fǎ guó kāi yè shì tā mén de yī gè dà dǎn háng dòng。","meaning":"It was a bold move on their part to open a business in France.","meaningThai":"ถือเป็นความเคลื่อนไหวที่ชัดเจนในการเปิดธุรกิจในฝรั่งเศส"},{"chinese":"新商店将在春天开业。","pinyin":"Xīn shāng diàn jiāng zài chūn tiān kāi yè。","meaning":"The new store will be open in the spring.","meaningThai":"ร้านใหม่จะเปิดในฤดูใบไม้ผลิ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-656","chinese":"开展","pinyin":"kāizhǎn","meaning":"to launch; to develop; to unfold; (of an exhibition etc) to open","meaningThai":"ดำเนินการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个研究项目开展的规模不算太大。","pinyin":"Zhè gè yán jiū xiàng mù kāi zhǎn de guī mó bù suàn tài dà。","meaning":"The research was carried out on a modest scale.","meaningThai":"การวิจัยดำเนินการในระดับปานกลาง"},{"chinese":"该调查在城市和乡村地区都开展了。","pinyin":"Gāi tiáo chá zài chéng shì hé xiāng cūn dì qū dū kāi zhǎn le。","meaning":"The survey was carried out in both urban and rural areas.","meaningThai":"การสำรวจดำเนินการทั้งในเขตเมืองและชนบท"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-657","chinese":"看","pinyin":"kān","meaning":"to look after; to take care of; to watch; to guard","meaningThai":"เห็น; ดู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我看书。","pinyin":"Wǒ kàn shū.","meaning":"I read a book.","meaningThai":"ฉันอ่านหนังสือ"},{"chinese":"我们晚上看电视。","pinyin":"Wǒmen wǎnshang kàn diànshì.","meaning":"We watch TV in the evening.","meaningThai":"เราดูทีวีในตอนเย็น"},{"chinese":"请看这个汉字。","pinyin":"Qǐng kàn zhège Hànzì.","meaning":"Please look at this Chinese character.","meaningThai":"โปรดดูตัวอักษรจีนนี้"}],"partOfSpeech":["verb","particle"]},
  {"id":"hsk5-658","chinese":"看望","pinyin":"kànwàng","meaning":"to pay a visit to; to see (sb)","meaningThai":"เยี่ยม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我大概能腾出时间去看望他们。","pinyin":"Wǒ dà gài néng téng chū shí jiān qù kàn wàng tā mén。","meaning":"I can probably make the time to see them.","meaningThai":"ฉันคงหาเวลาไปพบพวกเขาได้"},{"chinese":"她信守诺言，定期去看望姑妈。","pinyin":"Tā xìn shǒu nuò yán， dìng qī qù kàn wàng gū mā。","meaning":"She kept her promise to visit her aunt regularly.","meaningThai":"เธอรักษาสัญญาว่าจะไปเยี่ยมป้าของเธอเป็นประจำ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-659","chinese":"看作","pinyin":"kànzuò","meaning":"to look upon as; to regard as","meaningThai":"ถือเป็น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我把他看作我的朋友。","pinyin":"Wǒ bǎ tā kàn zuò wǒ de péng yǒu。","meaning":"I consider him my friend.","meaningThai":"ฉันถือว่าเขาเป็นเพื่อนของฉัน"},{"chinese":"我会把它看作一个征兆。","pinyin":"Wǒ huì bǎ tā kàn zuò yī gè zhēng zhào。","meaning":"I would take it as a sign. / I'd take it as a sign.","meaningThai":"ฉันจะเอามันเป็นสัญญาณ / ฉันจะเอามันเป็นสัญญาณ."}],"partOfSpeech":["verb"]},
  {"id":"hsk5-660","chinese":"靠","pinyin":"kào","meaning":"to lean against or on; to stand by the side of; to come near to; to depend on; to trust; to fuck (vulgar); traditional military costume drama where the performers wear armor (old)","meaningThai":"ขึ้นอยู่กับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们靠沿街兜售为生。","pinyin":"Tā mén kào yán jiē dōu shòu wéi shēng。","meaning":"They survive by hustling on the streets.","meaningThai":"พวกเขาเอาชีวิตรอดด้วยการเร่งรีบบนท้องถนน"},{"chinese":"我们靠吃大米过活。","pinyin":"Wǒ mén kào chī dà mǐ guò huó。","meaning":"We existed on a diet of rice.","meaningThai":"เราดำรงอยู่ได้ด้วยอาหารจำพวกข้าว"}],"partOfSpeech":["verb","preposition"]},
  {"id":"hsk5-661","chinese":"靠近","pinyin":"kàojìn","meaning":"to be close to; to approach; to draw near","meaningThai":"ใกล้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们在靠近村庄的地里露营。","pinyin":"Wǒ mén zài kào jìn cūn zhuāng de dì lǐ lòu yíng。","meaning":"We camped in a field near the village.","meaningThai":"เราตั้งค่ายพักแรมในทุ่งนาใกล้หมู่บ้าน"},{"chinese":"大多数城区都靠近公园。","pinyin":"Dà duō shù chéng qū dū kào jìn gōng yuán。","meaning":"Most urban areas are close to a park.","meaningThai":"พื้นที่เมืองส่วนใหญ่อยู่ใกล้กับสวนสาธารณะ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-662","chinese":"颗","pinyin":"kē","meaning":"classifier for small spheres, pearls, corn grains, teeth, hearts, satellites etc","meaningThai":"เมล็ดพืช","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"天空没有一颗星星。","pinyin":"Tiān kōng méi yǒu yī kē xīng xīng。","meaning":"The sky was void of stars.","meaningThai":"ท้องฟ้าก็ไร้ซึ่งดวงดาว"},{"chinese":"巧克力用金箔纸一颗颗独立包装。","pinyin":"Qiǎo kè lì yòng jīn bó zhǐ yī kē kē dú lì bāo zhuāng。","meaning":"The chocolates are individually wrapped in gold foil.","meaningThai":"ช็อคโกแลตแต่ละชิ้นถูกห่อด้วยกระดาษฟอยล์สีทอง"}],"partOfSpeech":["measure word"]},
  {"id":"hsk5-663","chinese":"克服","pinyin":"kèfú","meaning":"(try to) overcome (hardships etc); to conquer; to put up with; to endure","meaningThai":"เอาชนะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我希望你能克服矜持，让我知道。","pinyin":"Wǒ xī wàng nǐ néng kè fú jīn chí， ràng wǒ zhī dào。","meaning":"I hope that you'll overcome your reserve and let me know.","meaningThai":"ฉันหวังว่าคุณจะเอาชนะการสำรองของคุณและแจ้งให้เราทราบ"},{"chinese":"有件事给了我克服困难的勇气。","pinyin":"Yǒu jiàn shì gěi le wǒ kè fú kùn nán de yǒng qì。","meaning":"Something gave me the strength to overcome the difficulty.","meaningThai":"บางสิ่งบางอย่างทำให้ฉันมีกำลังใจที่จะเอาชนะความยากลำบากได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-664","chinese":"客服","pinyin":"kèfú","meaning":"customer service","meaningThai":"การบริการลูกค้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"只有35名员工为3万多位顾客服务。","pinyin":"Zhī yǒu 35 míng yuán gōng wéi 3 wàn duō wèi gù kè fú wù。","meaning":"There are only 35 staff to serve 30,000-plus customers.","meaningThai":"มีพนักงานเพียง 35 คนเท่านั้นที่จะให้บริการลูกค้ามากกว่า 30,000 ราย"},{"chinese":"我们的宗旨是始终以高标准为顾客服务。","pinyin":"Wǒ mén de zōng zhǐ shì shǐ zhōng yǐ gāo biāo zhǔn wéi gù kè fú wù。","meaning":"We aim to maintain high standards of customer care.","meaningThai":"เรามุ่งมั่นที่จะรักษามาตรฐานระดับสูงในการดูแลลูกค้า"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-665","chinese":"客观","pinyin":"kèguān","meaning":"objective; impartial","meaningThai":"วัตถุประสงค์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"难以客观判定该问题的严重性。","pinyin":"Nán yǐ kè guān pàn dìng gāi wèn tí de yán zhòng xìng。","meaning":"Objective assessment of the severity of the problem was difficult.","meaningThai":"การประเมินความรุนแรงของปัญหาอย่างมีวัตถุประสงค์นั้นทำได้ยาก"},{"chinese":"我认为一名记者应该完全客观。","pinyin":"Wǒ rèn wéi yī míng jì zhě yīng gāi wán quán kè guān。","meaning":"I believe that a journalist should be completely objective.","meaningThai":"ฉันเชื่อว่านักข่าวควรเป็นกลางอย่างสมบูรณ์"}],"partOfSpeech":["adjective","noun"]},
  {"id":"hsk5-666","chinese":"客户","pinyin":"kèhù","meaning":"client; customer","meaningThai":"ลูกค้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"重要客户。","pinyin":"Zhong yao ke hu.","meaning":"Important client.","meaningThai":"ลูกค้าคนสำคัญ."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-667","chinese":"可见","pinyin":"kějiàn","meaning":"it can clearly be seen (that this is the case); it is (thus) clear; clear; visible","meaningThai":"มองเห็นได้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"路上几乎没有车辆可见。","pinyin":"Lù shàng jī hū méi yǒu chē liàng kě jiàn。","meaning":"Little traffic was to be seen on the streets.","meaningThai":"การจราจรบนถนนมีน้อย"},{"chinese":"大海远远地清晰可见。","pinyin":"Dà hǎi yuǎn yuǎn dì qīng xī kě jiàn。","meaning":"The sea was plainly visible in the distance.","meaningThai":"เห็นทะเลชัดเจนแต่ไกล"}],"partOfSpeech":["verb","conjunction"]},
  {"id":"hsk5-668","chinese":"可靠","pinyin":"kěkào","meaning":"reliable","meaningThai":"เชื่อถือได้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他不太可靠，但我还是喜欢他。","pinyin":"Tā bù tài kě kào， dàn wǒ huán shì xǐ huān tā。","meaning":"He's not very reliable, but I like him just the same.","meaningThai":"เขาไม่ค่อยน่าเชื่อถือ แต่ฉันก็ชอบเขาเหมือนกัน"},{"chinese":"关于这个课题缺乏可靠资料。","pinyin":"Guān yú zhè gè kè tí quē fá kě kào zī liào。","meaning":"There was a dearth of reliable information on the subject.","meaningThai":"มีข้อมูลที่เชื่อถือได้ไม่เพียงพอเกี่ยวกับเรื่องนี้"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-669","chinese":"可怕","pinyin":"kěpà","meaning":"awful; dreadful; fearful; formidable; frightful; scary; hideous; horrible; terrible; terribly","meaningThai":"น่ากลัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"可怕的事实慢慢地清晰起来。","pinyin":"Kě pà de shì shí màn màn dì qīng xī qǐ lái。","meaning":"Slowly the awful truth dawned.","meaningThai":"ความจริงอันน่าสะพรึงกลัวก็ค่อยๆ ปรากฏ"},{"chinese":"战争太可怕了，真不敢去想。","pinyin":"Zhàn zhēng tài kě pà le， zhēn bù gǎn qù xiǎng。","meaning":"The thought of war is too awful to contemplate.","meaningThai":"ความคิดเรื่องสงครามนั้นเลวร้ายเกินกว่าจะคิดได้"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-670","chinese":"科研","pinyin":"kēyán","meaning":"(scientific) research","meaningThai":"งานวิจัยทางวิทยาศาสตร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"从事科研工作。","pinyin":"Cong shi ke yan gong zuo.","meaning":"Engage in scientific research.","meaningThai":"มีส่วนร่วมในการวิจัยทางวิทยาศาสตร์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-671","chinese":"空间","pinyin":"kōngjiān","meaning":"space; room; (fig.) scope; leeway; (astronomy) outer space; (physics, math.) space","meaningThai":"ช่องว่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"所有卧室里都有内置储藏空间。","pinyin":"Suǒ yǒu wò shì lǐ dū yǒu nèi zhì chǔ cáng kōng jiān。","meaning":"There is built-in storage space in all bedrooms.","meaningThai":"มีพื้นที่เก็บของบิวท์อินในห้องนอนทุกห้อง"},{"chinese":"没有足够的空间扩建这些大楼。","pinyin":"Méi yǒu zú gòu de kōng jiān kuò jiàn zhè xiē dà lóu。","meaning":"There is insufficient space for enlargement of the buildings.","meaningThai":"มีพื้นที่ไม่เพียงพอที่จะขยายอาคารได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-672","chinese":"控制","pinyin":"kòngzhì","meaning":"to control","meaningThai":"ควบคุม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他控制了自己的情绪。","pinyin":"Ta kong zhi le zi ji de qing xu.","meaning":"He controlled his emotions.","meaningThai":"เขาควบคุมอารมณ์ของเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-673","chinese":"空中","pinyin":"kōngzhōng","meaning":"in the sky; in the air","meaningThai":"อากาศ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"探照灯在空中扫来扫去。","pinyin":"Tàn zhào dēng zài kōng zhōng sǎo lái sǎo qù。","meaning":"Searchlights swept the sky.","meaningThai":"แสงไฟส่องไปทั่วท้องฟ้า"},{"chinese":"空中交通已恢复正常。","pinyin":"Kōng zhōng jiāo tōng yǐ huī fù zhèng cháng。","meaning":"Air traffic had returned to normal.","meaningThai":"การจราจรทางอากาศกลับมาเป็นปกติแล้ว"}],"partOfSpeech":["other"]},
  {"id":"hsk5-674","chinese":"口袋","pinyin":"kǒudai","meaning":"pocket; bag; sack","meaningThai":"กระเป๋า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这条短裤口袋上有蓝色的刺绣。","pinyin":"Zhè tiáo duǎn kù kǒu dài shàng yǒu lán sè de cì xiù。","meaning":"The shorts had blue embroidery over the pockets.","meaningThai":"กางเกงขาสั้นมีการปักสีน้ำเงินที่กระเป๋า"},{"chinese":"她把那些硬纸片塞进口袋里。","pinyin":"Tā bǎ nà xiē yìng zhǐ piàn sāi jìn kǒu dài lǐ。","meaning":"She put the pieces of card in her pocket.","meaningThai":"เธอวางชิ้นส่วนของการ์ดไว้ในกระเป๋าของเธอ"}],"partOfSpeech":["noun","measure word"]},
  {"id":"hsk5-675","chinese":"口味","pinyin":"kǒuwèi","meaning":"a person's preferences; tastes (in food); flavor","meaningThai":"รสชาติที่ชอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"每个人的口味不同。","pinyin":"Mei ge ren de kou wei bu tong.","meaning":"Everyone has different taste.","meaningThai":"ทุกคนมีรสนิยมที่แตกต่างกัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-676","chinese":"库","pinyin":"kù","meaning":"warehouse; storehouse; (file) library","meaningThai":"ห้องสมุด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我退出数据库后关掉了计算机。","pinyin":"Wǒ tuì chū shù jù kù hòu guān diào le jì suàn jī。","meaning":"I exited the database and switched off the computer.","meaningThai":"ฉันออกจากฐานข้อมูลและปิดคอมพิวเตอร์"},{"chinese":"库珀是个善交际的人，很受欢迎。","pinyin":"Kù pò shì gè shàn jiāo jì de rén， hěn shòu huān yíng。","meaning":"Cooper was a good mixer, he was popular.","meaningThai":"คูเปอร์เป็นมิกเซอร์ที่ดี เขาได้รับความนิยม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-677","chinese":"宽","pinyin":"kuān","meaning":"surname Kuan","meaningThai":"ความกว้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这条路只有一个车道那么宽。","pinyin":"Zhè tiáo lù zhī yǒu yī gè chē dào nà mó kuān。","meaning":"The road is only one lane wide.","meaningThai":"ถนนมีความกว้างเพียงเลนเดียว"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-678","chinese":"宽度","pinyin":"kuāndù","meaning":"width","meaningThai":"ความกว้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这条路的宽度刚好能让两辆车开过。","pinyin":"Zhè tiáo lù de kuān dù gāng hǎo néng ràng liǎng liàng chē kāi guò。","meaning":"The road was just wide enough for two vehicles to pass.","meaningThai":"ถนนกว้างพอให้รถสองคันผ่านไปได้"},{"chinese":"这款地毯有各种宽度可供选择。","pinyin":"Zhè kuǎn dì tǎn yǒu gè zhǒng kuān dù kě gōng xuǎn zé。","meaning":"The carpet is available in different widths.","meaningThai":"พรมมีให้เลือกหลายขนาด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-679","chinese":"亏","pinyin":"kuī","meaning":"deficiency; deficit; luckily; it's lucky that...; (often ironically) fancy that...","meaningThai":"การขาดดุล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是能赚到很多钱而没有任何亏钱风险的事。","pinyin":"Zhè shì néng zhuàn dào hěn duō qián ér méi yǒu rèn hé kuī qián fēng xiǎn de shì。","meaning":"This is something where you can earn such a lot of money that there is not any risk that you will lose it.","meaningThai":"นี่คือสิ่งที่คุณสามารถได้รับเงินจำนวนมากโดยที่ไม่มีความเสี่ยงที่คุณจะสูญเสียมันไป"},{"chinese":"月亮渐盈， 直到正圆，然后消亏。","pinyin":"Yuè liàng jiàn yíng，  zhí dào zhèng yuán， rán hòu xiāo kuī。","meaning":"The moon waxes till it becomes full, and then wanes.","meaningThai":"พระจันทร์ขึ้นจนเต็มแล้วก็ดับไป"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-680","chinese":"昆虫","pinyin":"kūnchóng","meaning":"insect","meaningThai":"แมลง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"昆虫的种类非常多。","pinyin":"Kūn chóng de zhǒng lèi fēi cháng duō.","meaning":"There are many kinds of insects.","meaningThai":"แมลงมีหลายชนิด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-681","chinese":"扩大","pinyin":"kuòdà","meaning":"to expand; to enlarge; to broaden one's scope","meaningThai":"ขยาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们得到允许扩大企业规模。","pinyin":"Wǒ mén dé dào yǔn xǔ kuò dà qǐ yè guī mó。","meaning":"We've been given the nod to expand the business.","meaningThai":"เราได้รับการสนับสนุนให้ขยายธุรกิจ"},{"chinese":"我们不得不扩大图像的尺寸。","pinyin":"Wǒ mén bù dé bù kuò dà tú xiàng de chǐ cùn。","meaning":"We have to expand the size of the image.","meaningThai":"เราต้องขยายขนาดของภาพ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-682","chinese":"来源","pinyin":"láiyuán","meaning":"source (of information etc); origin","meaningThai":"แหล่งที่มา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有能替代动物肉类的其他营养来源。","pinyin":"Yǒu néng tì dài dòng wù ròu lèi de qí tā yíng yǎng lái yuán。","meaning":"There are alternative sources of nutrition to animal meat.","meaningThai":"มีแหล่งโภชนาการทางเลือกอื่นสำหรับเนื้อสัตว์"},{"chinese":"我核实了我获知那条信息的来源。","pinyin":"Wǒ hé shí le wǒ huò zhī nà tiáo xìn xī de lái yuán。","meaning":"I verified the source from which I had that information.","meaningThai":"ฉันตรวจสอบแหล่งที่มาที่ฉันมีข้อมูลนั้นแล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-683","chinese":"老百姓","pinyin":"lǎobǎixìng","meaning":"ordinary people; the \"person in the street\"","meaningThai":"คนทั่วไป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"許多老百姓加入了軍隊。","pinyin":"Xū duō lǎo bǎi xìng jiā rù le jūn duì。","meaning":"A great number of citizens went into the army.","meaningThai":"ประชาชนจำนวนมากเข้าไปในกองทัพ"},{"chinese":"自古至今，容忍的总是老百姓，被容忍的总是统治者。","pinyin":"Zì gǔ zhì jīn， róng rěn de zǒng shì lǎo bǎi xìng， bèi róng rěn de zǒng shì tǒng zhì zhě。","meaning":"Since ancient times, it has always been the commoners who tolerate their ruler.","meaningThai":"ตั้งแต่สมัยโบราณ มันเป็นสามัญชนที่อดทนต่อผู้ปกครองของตนมาโดยตลอด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-684","chinese":"老板","pinyin":"lǎobǎn","meaning":"variant of 老板","meaningThai":"เจ้านาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"老板出国期间由谁代管？","pinyin":"Lǎo bǎn chū guó qī jiān yóu shuí dài guǎn？","meaning":"Who's minding the shop while the boss is abroad?","meaningThai":"ใครรังเกียจร้านในขณะที่เจ้านายอยู่ต่างประเทศ?"},{"chinese":"她对老板总是谄媚奉承。","pinyin":"Tā duì lǎo bǎn zǒng shì chǎn mèi fèng chéng。","meaning":"She's always crawling to the boss.","meaningThai":"เธอคลานไปหาเจ้านายอยู่เสมอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-685","chinese":"劳动","pinyin":"láodòng","meaning":"work; toil; physical labor","meaningThai":"แรงงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"体力劳动。","pinyin":"Ti li lao dong.","meaning":"Physical labor.","meaningThai":"แรงงานทางกายภาพ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-686","chinese":"老公","pinyin":"lǎogōng","meaning":"(coll.) husband","meaningThai":"สามี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他总是像老公民一样谈论圣卢伊。","pinyin":"Tā zǒng shì xiàng lǎo gōng mín yī yàng tán lùn shèng lú yī。","meaning":"He was always talking about St. Looy like an old citizen.","meaningThai":"เขามักจะพูดถึงเซนท์ลอยเหมือนคนแก่เสมอ"},{"chinese":"老公：当然，有什么选择吗？","pinyin":"Lǎo gōng： dāng rán， yǒu shí mó xuǎn zé ma？","meaning":"Husband: Sure, what are my choices?","meaningThai":"สามี: แน่นอน ฉันมีตัวเลือกอะไรบ้าง?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-687","chinese":"姥姥","pinyin":"lǎolao","meaning":"(coll.) mother's mother; maternal grandmother","meaningThai":"ยาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我妈妈有个妈妈，她是我姥姥。","pinyin":"Wǒ mā mā yǒu gè mā mā， tā shì wǒ mǔ mǔ。","meaning":"My mother has a mother. She is my grandmother.","meaningThai":"แม่ของฉันมีแม่ เธอเป็นคุณยายของฉัน"},{"chinese":"小利奥与妈妈和姥姥在一起。","pinyin":"Xiǎo lì ào yǔ mā mā hé mǔ mǔ zài yī qǐ。","meaning":"Little Leo with mom and grandma.","meaningThai":"ลีโอน้อยกับแม่และยาย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-688","chinese":"老婆","pinyin":"lǎopo","meaning":"(coll.) wife","meaningThai":"ภรรยา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“我可怜的老婆啊！”他悔恨地说。","pinyin":"“ wǒ kě lián de lǎo pó ā！” tā huǐ hèn dì shuō。","meaning":"\"My poor wife!\" he said, remorsefully.","meaningThai":"“ภรรยาผู้น่าสงสารของฉัน!” เขากล่าวอย่างสำนึกผิด"},{"chinese":"他是个不幸的人—去年死了老婆，而没她他好像就过不下去。","pinyin":"Tā shì gè bù xìng de rén — qù nián sǐ le lǎo pó， ér méi tā tā hǎo xiàng jiù guò bù xià qù。","meaning":"He's a sad case—his wife died last year and he can't seem to manage without her.","meaningThai":"เขาเป็นกรณีที่น่าเศร้า ภรรยาของเขาเสียชีวิตเมื่อปีที่แล้ว และดูเหมือนเขาจะอยู่ไม่ได้ถ้าไม่มีเธอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-689","chinese":"姥爷","pinyin":"lǎoye","meaning":"maternal grandfather (dialectal)","meaningThai":"คุณปู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"姥爷对邻居也很热心，他总是乐于助人。","pinyin":"Mǔ yé duì lín jū yě hěn rè xīn， tā zǒng shì lè yú zhù rén。","meaning":"My grandfather is also warm-hearted to his neighbors and is always ready to help them.","meaningThai":"ปู่ของฉันมีจิตใจอบอุ่นต่อเพื่อนบ้านและพร้อมที่จะช่วยเหลือพวกเขาเสมอ"},{"chinese":"我母亲娘家在爱尔兰，因此姥姥总是给我讲一些太姥爷在爱尔兰的故事。","pinyin":"Wǒ mǔ qīn niáng jiā zài ài ěr lán， yīn cǐ mǔ mǔ zǒng shì gěi wǒ jiǎng yī xiē tài mǔ yé zài ài ěr lán de gù shì。","meaning":"My mom's side of the family is Irish. So my grandma would tell me stories about my great-grandpa who was from Ireland.","meaningThai":"ครอบครัวฝั่งแม่ของฉันเป็นชาวไอริช คุณยายของฉันจึงเล่าเรื่องคุณปู่ทวดของฉันที่มาจากไอร์แลนด์ให้ฉันฟัง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-690","chinese":"乐观","pinyin":"lèguān","meaning":"optimistic; hopeful","meaningThai":"มองในแง่ดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们认为你过于乐观了。","pinyin":"Wǒ mén rèn wéi nǐ guò yú lè guān le。","meaning":"We think you are being overly optimistic.","meaningThai":"เราคิดว่าคุณมองโลกในแง่ดีมากเกินไป"},{"chinese":"乐观正逐渐替代悲观。","pinyin":"Lè guān zhèng zhú jiàn tì dài bēi guān。","meaning":"Optimism was gradually taking the place of pessimism.","meaningThai":"การมองโลกในแง่ดีค่อยๆ เข้ามาแทนที่การมองโลกในแง่ร้าย"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-691","chinese":"泪","pinyin":"lèi","meaning":"tears","meaningThai":"น้ำตา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们在女儿的婚礼上会落些泪。","pinyin":"Tā mén zài nǚ ér de hūn lǐ shàng huì luò xiē lèi。","meaning":"They will shed a few tears at their daughter's wedding.","meaningThai":"พวกเขาจะหลั่งน้ำตาเล็กน้อยในงานแต่งงานของลูกสาว"},{"chinese":"他的声音颤抖着，就要落下泪来。","pinyin":"Tā de shēng yīn chàn dǒu zháo， jiù yào luò xià lèi lái。","meaning":"His voice trembled, on the verge of tears.","meaningThai":"เสียงของเขาสั่นจนน้ำตาไหล"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-692","chinese":"类","pinyin":"lèi","meaning":"kind; type; class; category; similar; like; to resemble","meaningThai":"ใจดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"移民来的工人被归入侨民类。","pinyin":"Yí mín lái de gōng rén bèi guī rù qiáo mín lèi。","meaning":"Immigrant workers were classed as aliens.","meaningThai":"แรงงานอพยพถูกจัดอยู่ในประเภทคนต่างด้าว"},{"chinese":"她是艺术家一类的人。","pinyin":"Tā shì yì shù jiā yī lèi de rén。","meaning":"She's the artistic type.","meaningThai":"เธอเป็นคนประเภทศิลปะ"}],"partOfSpeech":["measure word","noun","other"]},
  {"id":"hsk5-693","chinese":"泪水","pinyin":"lèishuǐ","meaning":"teardrop; tears","meaningThai":"น้ำตา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她忍住泪水，强作笑容。","pinyin":"Tā rěn zhù lèi shuǐ， qiáng zuò xiào róng。","meaning":"She gulped back her tears and forced a smile.","meaningThai":"เธอกลืนน้ำตาและฝืนยิ้ม"},{"chinese":"泪水模糊了她的视线。","pinyin":"Lèi shuǐ mó hū le tā de shì xiàn。","meaning":"Tears blurred her eyes.","meaningThai":"น้ำตาเบลอดวงตาของเธอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-694","chinese":"类似","pinyin":"lèisì","meaning":"similar; analogous","meaningThai":"คล้ายกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"税金估算就是比较类似房产的价值。","pinyin":"Shuì jīn gū suàn jiù shì bǐ jiào lèi sì fáng chǎn de jià zhí。","meaning":"Tax assessment is all about comparing values of similar properties.","meaningThai":"การประเมินภาษีเป็นเรื่องเกี่ยวกับการเปรียบเทียบมูลค่าของทรัพย์สินที่คล้ายคลึงกัน"},{"chinese":"警方正在档案中查阅类似案件。","pinyin":"Jǐng fāng zhèng zài dàng àn zhōng chá yuè lèi sì àn jiàn。","meaning":"The police are trawling through their files for similar cases.","meaningThai":"ตำรวจกำลังสืบค้นแฟ้มคดีที่คล้ายกัน"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-695","chinese":"类型","pinyin":"lèixíng","meaning":"type; kind; category; (computer programming) type","meaningThai":"พิมพ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些地区大小各异，但类型相同。","pinyin":"Zhè xiē dì qū dà xiǎo gè yì， dàn lèi xíng xiāng tóng。","meaning":"The regions differ in size, but not in kind.","meaningThai":"ภูมิภาคมีขนาดแตกต่างกัน แต่ไม่มีขนาด"},{"chinese":"她和各种类型的人打交道。","pinyin":"Tā hé gè zhǒng lèi xíng de rén dǎ jiāo dào。","meaning":"She mixes with all types of people.","meaningThai":"เธอผสมผสานกับคนทุกประเภท"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-696","chinese":"乐趣","pinyin":"lèqù","meaning":"delight; pleasure; joy","meaningThai":"ความพึงพอใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他从绘画中得到极大的乐趣。","pinyin":"Tā cóng huì huà zhōng dé dào jí dà de lè qù。","meaning":"He derived great pleasure from painting.","meaningThai":"เขาได้รับความยินดีอย่างยิ่งจากการวาดภาพ"},{"chinese":"看电视是我们惟一的乐趣。","pinyin":"Kàn diàn shì shì wǒ mén wéi yī de lè qù。","meaning":"Watching TV is our only pleasure.","meaningThai":"การดูทีวีเป็นความสุขเพียงอย่างเดียวของเรา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-697","chinese":"梨","pinyin":"lí","meaning":"pear","meaningThai":"ลูกแพร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她咬了一口熟透了的多汁的梨。","pinyin":"Tā yǎo le yī kǒu shú tòu le de duō zhī de lí。","meaning":"She bit into a ripe juicy pear.","meaningThai":"เธอกัดลูกแพร์สุกฉ่ำ"},{"chinese":"他们精于水果零售之道。你可以放心，你那些梨一天之内就会熟。","pinyin":"Tā mén jīng yú shuǐ guǒ líng shòu zhī dào。 nǐ kě yǐ fàng xīn， nǐ nà xiē lí yī tiān zhī nèi jiù huì shú。","meaning":"They've got fruit retailing down to a fine art. You can be sure that your pears will ripen in day.","meaningThai":"พวกเขาขายปลีกผลไม้ไปจนถึงงานศิลปะ คุณสามารถมั่นใจได้ว่าลูกแพร์ของคุณจะสุกในตอนกลางวัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-698","chinese":"力","pinyin":"lì","meaning":"surname Li","meaningThai":"บังคับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"疲劳影响注意力的集中。","pinyin":"Pí láo yǐng xiǎng zhù yì lì de jí zhōng。","meaning":"Tiredness affects your powers of concentration.","meaningThai":"ความเหนื่อยล้าส่งผลต่อสมาธิของคุณ"},{"chinese":"她有非凡的意志力。","pinyin":"Tā yǒu fēi fán de yì zhì lì。","meaning":"She has a remarkable inner strength.","meaningThai":"เธอมีความแข็งแกร่งภายในที่โดดเด่น"}],"partOfSpeech":["noun","other"]},
  {"id":"hsk5-699","chinese":"恋爱","pinyin":"liàn'ài","meaning":"(romantic) love; in love; to have an affair","meaningThai":"มีความรัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他要大声宣布，他恋爱了。","pinyin":"Tā yào dà shēng xuān bù， tā liàn ài le。","meaning":"He was in love and wanted to shout it from the rooftops.","meaningThai":"เขาหลงรักและอยากจะตะโกนจากหลังคาบ้าน"},{"chinese":"劳拉以前从未谈过恋爱。","pinyin":"Láo lā yǐ qián cóng wèi tán guò liàn ài。","meaning":"Laura had never before been in love.","meaningThai":"ลอร่าไม่เคยมีความรักมาก่อน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-700","chinese":"量","pinyin":"liàng","meaning":"to measure","meaningThai":"วัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"护士正在给他量体温。","pinyin":"Hùshì zhèngzài gěi tā liángtǐwēn.","meaning":"The nurse is taking his temperature.","meaningThai":"พยาบาลกำลังวัดอุณหภูมิของเขา"},{"chinese":"请帮我量一下桌子的长度。","pinyin":"Qǐng bāng wǒ liàng yíxià zhuōzi de chángdù.","meaning":"Please help me measure the length of the table.","meaningThai":"โปรดช่วยฉันวัดความยาวของโต๊ะ"},{"chinese":"孩子每个月都要量身高。","pinyin":"Háizi měigè yuè dōu yào liàng shēngāo.","meaning":"The child’s height is measured every month.","meaningThai":"วัดความสูงของเด็กทุกเดือน"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-701","chinese":"良好","pinyin":"liánghǎo","meaning":"good; favorable; well; fine","meaningThai":"ดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"确保良好的行为受到嘉奖。","pinyin":"Què bǎo liáng hǎo de háng wéi shòu dào jiā jiǎng。","meaning":"Make sure that good behaviour is rewarded.","meaningThai":"ตรวจสอบให้แน่ใจว่ามีการตอบแทนพฤติกรรมที่ดี"},{"chinese":"这个队在压力下表现良好。","pinyin":"Zhè gè duì zài yā lì xià biǎo xiàn liáng hǎo。","meaning":"The team performs well under pressure.","meaningThai":"ทีมทำผลงานได้ดีภายใต้ความกดดัน"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-702","chinese":"粮食","pinyin":"liángshi","meaning":"foodstuff; cereals","meaningThai":"อาหาร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这家公司是国际粮食贸易公司。","pinyin":"Zhè jiā gōng sī shì guó jì liáng shí mào yì gōng sī。","meaning":"The company is an international trader in grain.","meaningThai":"บริษัทเป็นผู้ค้าระหว่างประเทศในด้านธัญพืช"},{"chinese":"很多士兵因为缺少粮食死去。","pinyin":"Hěn duō shì bīng yīn wéi quē shǎo liáng shí sǐ qù。","meaning":"Many soldiers died because of dearth of food.","meaningThai":"ทหารหลายคนเสียชีวิตเพราะความรักของอาหาร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-703","chinese":"联合","pinyin":"liánhé","meaning":"to combine; to join; unite; alliance","meaningThai":"ข้อต่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们发表联合声明否认指控。","pinyin":"Tā mén fā biǎo lián hé shēng míng fǒu rèn zhǐ kòng。","meaning":"They issued a joint statement denying the charges.","meaningThai":"พวกเขาออกแถลงการณ์ร่วมปฏิเสธข้อกล่าวหาดังกล่าว"},{"chinese":"联合国承诺帮助监督扫雷工作。","pinyin":"Lián hé guó chéng nuò bāng zhù jiān dū sǎo léi gōng zuò。","meaning":"The U.N. pledged to help supervise the clearance of mines.","meaningThai":"สหประชาชาติให้คำมั่นที่จะช่วยกำกับดูแลการกวาดล้างทุ่นระเบิด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-704","chinese":"连接","pinyin":"liánjiē","meaning":"to link; to join; to connect","meaningThai":"เชื่อมต่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"一根横杆连接着两根立柱。","pinyin":"Yī gēn héng gān lián jiē zháo liǎng gēn lì zhù。","meaning":"A transverse bar joins the two posts.","meaningThai":"แถบขวางเชื่อมสองเสาเข้าด้วยกัน"},{"chinese":"分子连接在一起形成长串。","pinyin":"Fēn zǐ lián jiē zài yī qǐ xíng chéng cháng chuàn。","meaning":"The molecules join together to form long strings.","meaningThai":"โมเลกุลรวมตัวกันเป็นเส้นยาว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-705","chinese":"连忙","pinyin":"liánmáng","meaning":"promptly; at once","meaningThai":"อย่างรวดเร็ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他连忙去那儿。","pinyin":"Tā lián máng qù nà ér。","meaning":"He went there promptly.","meaningThai":"เขาไปที่นั่นทันที"},{"chinese":"她倒抽了一口气，连忙用手掩着嘴。","pinyin":"Tā dǎo chōu le yī kǒu qì， lián máng yòng shǒu yǎn zháo zuǐ。","meaning":"She gasped and her hand flew to her mouth.","meaningThai":"เธอหายใจไม่ออกและมือของเธอก็บินไปที่ปากของเธอ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-706","chinese":"脸色","pinyin":"liǎnsè","meaning":"complexion; look","meaningThai":"ใบหน้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他看到我脸色变了。","pinyin":"Tā kàn dào wǒ liǎn sè biàn le。","meaning":"He saw my expression change.","meaningThai":"เขาเห็นการแสดงออกของฉันเปลี่ยนไป"},{"chinese":"他病了，所以脸色显得苍白。","pinyin":"Tā bìng le， suǒ yǐ liǎn sè xiǎn dé cāng bái。","meaning":"He's pale because he's sick.","meaningThai":"เขาหน้าซีดเพราะเขาป่วย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-707","chinese":"连续","pinyin":"liánxù","meaning":"continuous; in a row; serial; consecutive","meaningThai":"อย่างต่อเนื่อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那座城市连续四天遭到了袭击。","pinyin":"Nà zuò chéng shì lián xù sì tiān zāo dào le xí jī。","meaning":"For four days the town suffered continuous attacks.","meaningThai":"เป็นเวลาสี่วันที่เมืองได้รับการโจมตีอย่างต่อเนื่อง"},{"chinese":"他常常是连续几周不见人影。","pinyin":"Tā cháng cháng shì lián xù jī zhōu bù jiàn rén yǐng。","meaning":"He would disappear for weeks on end.","meaningThai":"เขาคงจะหายตัวไปเป็นเวลาหลายสัปดาห์"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-708","chinese":"了不起","pinyin":"liǎobuqǐ","meaning":"amazing; terrific; extraordinary","meaningThai":"อัศจรรย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这将是一场了不起的比赛。","pinyin":"Zhè jiāng shì yī cháng le bù qǐ de bǐ sài。","meaning":"It's going to be a great match.","meaningThai":"มันจะเป็นแมตช์ที่ยอดเยี่ยม"},{"chinese":"很多鸟类具有了不起的返回原地的本能。","pinyin":"Hěn duō niǎo lèi jù yǒu le bù qǐ de fǎn huí yuán dì de běn néng。","meaning":"Many birds have a remarkable homing instinct.","meaningThai":"นกหลายชนิดมีสัญชาตญาณการกลับบ้านที่น่าทึ่ง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-709","chinese":"列车","pinyin":"lièchē","meaning":"(railway) train","meaningThai":"รถไฟ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"罢工过后，列车运营已经恢复正常。","pinyin":"Bà gōng guò hòu， liè chē yùn yíng yǐ jīng huī fù zhèng cháng。","meaning":"Train services have returned to normal after the strike.","meaningThai":"บริการรถไฟกลับมาเป็นปกติแล้วหลังเกิดเหตุประท้วง"},{"chinese":"他们在车流高峰期加开了列车。","pinyin":"Tā mén zài chē liú gāo fēng qī jiā kāi le liè chē。","meaning":"They run extra trains during the rush hour.","meaningThai":"พวกเขาวิ่งรถไฟเพิ่มเติมในช่วงชั่วโมงเร่งด่วน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-710","chinese":"离婚","pinyin":"líhūn","meaning":"to divorce","meaningThai":"หย่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"离婚后，他自暴自弃。","pinyin":"Lí hūn hòu， tā zì bào zì qì。","meaning":"After his divorce, he let himself go to seed.","meaningThai":"หลังจากการหย่าร้าง เขาก็ปล่อยให้ตัวเองไปหาเมล็ดพันธุ์"},{"chinese":"离婚对孩子不好。","pinyin":"Lí hūn duì hái zǐ bù hǎo。","meaning":"Divorce is bad for children.","meaningThai":"การหย่าร้างเป็นผลเสียต่อเด็ก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-711","chinese":"立即","pinyin":"lìjí","meaning":"immediately","meaningThai":"โดยทันที","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"没有立即就能获得的后备。","pinyin":"Méi yǒu lì jí jiù néng huò dé de hòu bèi。","meaning":"There is no emergency back-up immediately available.","meaningThai":"ไม่มีการสำรองข้อมูลฉุกเฉินทันที"},{"chinese":"他们要求立即释放人质。","pinyin":"Tā mén yào qiú lì jí shì fàng rén zhì。","meaning":"They called for the immediate release of the hostages.","meaningThai":"พวกเขาเรียกร้องให้ปล่อยตัวประกันทันที"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-712","chinese":"立刻","pinyin":"lìkè","meaning":"forthwith; immediate; prompt; promptly; straightway; thereupon; at once","meaningThai":"โดยทันที","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他立刻开始给安娜写回信。","pinyin":"Tā lì kè kāi shǐ gěi ān nà xiě huí xìn。","meaning":"He started at once to compose a reply to Anna.","meaningThai":"เขาเริ่มเขียนตอบกลับแอนนาทันที"},{"chinese":"消防队立刻赶到现场。","pinyin":"Xiāo fáng duì lì kè gǎn dào xiàn cháng。","meaning":"Firefighters were on the scene immediately.","meaningThai":"เจ้าหน้าที่ดับเพลิงอยู่ในที่เกิดเหตุทันที"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-713","chinese":"力量","pinyin":"lìliàng","meaning":"power; force; strength","meaningThai":"ความแข็งแกร่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"爆炸的力量震碎了所有的窗户。","pinyin":"Bào zhà de lì liáng zhèn suì le suǒ yǒu de chuāng hù。","meaning":"All the windows broke with the force of the blast.","meaningThai":"หน้าต่างทุกบานก็พังทลายลงด้วยแรงระเบิด"},{"chinese":"警官们被他超凡的力量吓到了。","pinyin":"Jǐng guān mén bèi tā chāo fán de lì liáng xià dào le。","meaning":"Officers were terrified of his superhuman strength.","meaningThai":"เจ้าหน้าที่ต่างหวาดกลัวความแข็งแกร่งเหนือมนุษย์ของเขา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-714","chinese":"理论","pinyin":"lǐlùn","meaning":"theory; to argue; to take notice of","meaningThai":"ทฤษฎี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种理论可通过实验得到证实。","pinyin":"Zhè zhǒng lǐ lùn kě tōng guò shí yàn dé dào zhèng shí。","meaning":"This theory can be confirmed experimentally.","meaningThai":"ทฤษฎีนี้สามารถยืนยันได้จากการทดลอง"},{"chinese":"该团队正在检验他们的理论。","pinyin":"Gāi tuán duì zhèng zài jiǎn yàn tā mén de lǐ lùn。","meaning":"The team are now putting their theory to the test.","meaningThai":"ขณะนี้ทีมงานกำลังนำทฤษฎีของตนไปทดสอบ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-715","chinese":"厘米","pinyin":"límǐ","meaning":"centimeter","meaningThai":"เซนติเมตร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我把裙子的下摆剪短了两厘米。","pinyin":"Wǒ bǎ qún zǐ de xià bǎi jiǎn duǎn le liǎng lí mǐ。","meaning":"I trimmed two centimetres off the hem of the skirt.","meaningThai":"ฉันตัดขอบกระโปรงออกสองเซนติเมตร"},{"chinese":"他的身高增加了2.5厘米。","pinyin":"Tā de shēn gāo zēng jiā le2.5 lí mǐ。","meaning":"His height had increased by 2.5 cm.","meaningThai":"ส่วนสูงของเขาเพิ่มขึ้น 2.5 ซม."}],"partOfSpeech":["measure word"]},
  {"id":"hsk5-716","chinese":"铃","pinyin":"líng","meaning":"(small) bell","meaningThai":"กระดิ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她在响第一声铃时就接了电话。","pinyin":"Tā zài xiǎng dì yī shēng líng shí jiù jiē le diàn huà。","meaning":"She answered her phone on the first ring.","meaningThai":"เธอรับโทรศัพท์เมื่อเสียงเรียกเข้าครั้งแรก"},{"chinese":"该电梯铃在四楼发出响声。","pinyin":"Gāi diàn tī líng zài sì lóu fā chū xiǎng shēng。","meaning":"The lift bell pinged at the fourth floor.","meaningThai":"ระฆังลิฟต์ดังขึ้นที่ชั้นสี่"}],"partOfSpeech":["other"]},
  {"id":"hsk5-717","chinese":"令","pinyin":"lìng","meaning":"used in 令; used in 狐 (Taiwan pr. [lìng])","meaningThai":"ทำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们有搜查这座房子的搜查令。","pinyin":"Tā mén yǒu sōu chá zhè zuò fáng zǐ de sōu chá líng。","meaning":"They had a warrant to search the house.","meaningThai":"พวกเขามีหมายค้นบ้าน"},{"chinese":"部队接到了动员令。","pinyin":"Bù duì jiē dào le dòng yuán líng。","meaning":"The troops were ordered to mobilize.","meaningThai":"กองทัพได้รับคำสั่งให้ระดมพล"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-718","chinese":"领","pinyin":"lǐng","meaning":"neck; collar; to lead; to receive; classifier for clothes, mats, screens etc","meaningThai":"ปกเสื้อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她领他们来到一条废弃的小巷。","pinyin":"Tā lǐng tā mén lái dào yī tiáo fèi qì de xiǎo xiàng。","meaning":"She led them into a deserted sidestreet.","meaningThai":"เธอพาพวกเขาไปสู่ถนนข้างทางที่รกร้าง"},{"chinese":"我会安排好人领你转转。","pinyin":"Wǒ huì ān pái hǎo rén lǐng nǐ zhuǎn zhuǎn。","meaning":"I will arrange for someone to take you around.","meaningThai":"ฉันจะจัดให้มีคนพาคุณไปรอบๆ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-719","chinese":"领带","pinyin":"lǐngdài","meaning":"necktie","meaningThai":"ผูก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他捋平头发，整了整领带。","pinyin":"Tā luō píng tóu fā， zhěng le zhěng lǐng dài。","meaning":"He smoothed his hair and adjusted his tie.","meaningThai":"เขาหวีผมให้เรียบและผูกเน็คไท"},{"chinese":"他上班总是系着领带。","pinyin":"Tā shàng bān zǒng shì xì zháo lǐng dài。","meaning":"He always wears a collar and tie for work.","meaningThai":"เขามักจะสวมปลอกคอและเน็คไทไปทำงาน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-720","chinese":"领导","pinyin":"lǐngdǎo","meaning":"lead; leading; to lead; leadership; leader","meaningThai":"ตะกั่ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"新任领导想要摆脱前任的影响。","pinyin":"Xīn rèn lǐng dǎo xiǎng yào bǎi tuō qián rèn de yǐng xiǎng。","meaning":"The new leader wants to escape from the shadow of his predecessor.","meaningThai":"ผู้นำคนใหม่ต้องการหลบหนีจากเงาของบรรพบุรุษ"},{"chinese":"他们会团结支持新领导人吗？","pinyin":"Tā mén huì tuán jié zhī chí xīn lǐng dǎo rén ma？","meaning":"Will they unite behind the new leader?","meaningThai":"พวกเขาจะรวมตัวกันอยู่เบื้องหลังผู้นำคนใหม่หรือไม่?"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-721","chinese":"灵活","pinyin":"línghuó","meaning":"flexible; nimble; agile","meaningThai":"ยืดหยุ่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个方法很灵活。","pinyin":"Zhe ge fang fa hen ling huo.","meaning":"This method is very flexible.","meaningThai":"วิธีนี้มีความยืดหยุ่นมาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-722","chinese":"领取","pinyin":"lǐngqǔ","meaning":"to receive; to draw; to get","meaningThai":"รับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她到邮局去领取她的养老金。","pinyin":"Tā dào yóu jú qù lǐng qǔ tā de yǎng lǎo jīn。","meaning":"She went to the post office to draw her pension.","meaningThai":"เธอไปที่ทำการไปรษณีย์เพื่อรับเงินบำนาญของเธอ"},{"chinese":"他领取基本薪金，外加佣金。","pinyin":"Tā lǐng qǔ jī běn xīn jīn， wài jiā yōng jīn。","meaning":"He gets a basic salary plus commission.","meaningThai":"เขาได้รับเงินเดือนพื้นฐานพร้อมค่าคอมมิชชั่น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-723","chinese":"领先","pinyin":"lǐngxiān","meaning":"to lead; to be in front","meaningThai":"ชั้นนำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你要努力才能保持领先优势。","pinyin":"Nǐ yào nǔ lì cái néng bǎo chí lǐng xiān yōu shì。","meaning":"You need to work hard to keep ahead.","meaningThai":"คุณต้องทำงานหนักเพื่อก้าวไปข้างหน้า"},{"chinese":"他在总统竞选中领先。","pinyin":"Tā zài zǒng tǒng jìng xuǎn zhōng lǐng xiān。","meaning":"He's leading in the presidential race.","meaningThai":"เขาเป็นผู้นำในการแข่งขันชิงตำแหน่งประธานาธิบดี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-724","chinese":"领域","pinyin":"lǐngyù","meaning":"domain; sphere; field; territory; area","meaningThai":"สาขา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"研究领域。","pinyin":"Yan jiu ling yu.","meaning":"Research field.","meaningThai":"สาขาการวิจัย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-725","chinese":"临时","pinyin":"línshí","meaning":"as the time draws near; at the last moment; temporary; interim; ad hoc","meaningThai":"ชั่วคราว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"由他担任临时法官。","pinyin":"Yóu tā dān rèn lín shí fǎ guān。","meaning":"He was sitting as a temporary judge.","meaningThai":"พระองค์ทรงนั่งเป็นผู้พิพากษาชั่วคราว"},{"chinese":"我在找临时工作。","pinyin":"Wǒ zài zhǎo lín shí gōng zuò。","meaning":"I'm looking for some temporary work.","meaningThai":"ฉันกำลังมองหางานชั่วคราว"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-726","chinese":"利润","pinyin":"lìrùn","meaning":"profits","meaningThai":"กำไร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"获得利润。","pinyin":"Huo de li run.","meaning":"Obtain profit.","meaningThai":"ได้กำไร."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-727","chinese":"里头","pinyin":"lǐtou","meaning":"inside; interior","meaningThai":"ข้างใน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我从抽屉尽里头找到一些旧照片。","pinyin":"Wǒ cóng chōu tì jìn lǐ tóu zhǎo dào yī xiē jiù zhào piàn。","meaning":"I found some old photos at the back of the drawer.","meaningThai":"ฉันพบรูปถ่ายเก่าๆ อยู่ด้านหลังลิ้นชัก"},{"chinese":"我回家常抄近路，打公园里头走。","pinyin":"Wǒ huí jiā cháng chāo jìn lù， dǎ gōng yuán lǐ tóu zǒu。","meaning":"I usually cut across the park on my way home.","meaningThai":"ฉันมักจะตัดผ่านสวนสาธารณะระหว่างทางกลับบ้าน"}],"partOfSpeech":["other"]},
  {"id":"hsk5-728","chinese":"流传","pinyin":"liúchuán","meaning":"to spread; to circulate; to hand down","meaningThai":"การแพร่กระจาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这一古老的寓言流传了数个世纪。","pinyin":"Zhè yī gǔ lǎo de yù yán liú chuán le shù gè shì jì。","meaning":"The old fable continues to echo down the centuries.","meaningThai":"นิทานเก่ายังคงสะท้อนมานานหลายศตวรรษ"},{"chinese":"这名称是从上个世纪流传下来的。","pinyin":"Zhè míng chēng shì cóng shàng gè shì jì liú chuán xià lái de。","meaning":"The name has come down from the last century.","meaningThai":"ชื่อนี้ได้มาจากศตวรรษที่ผ่านมา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-729","chinese":"流感","pinyin":"liúgǎn","meaning":"flu; influenza","meaningThai":"ไข้หวัดใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"每年冬天很多人得流感。","pinyin":"Měi nián dōng tiān hěn duō rén dé liú gǎn.","meaning":"Many people get the flu every winter.","meaningThai":"หลายๆ คนจะเป็นไข้หวัดใหญ่ทุกๆ หน้าหนาว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-730","chinese":"浏览","pinyin":"liúlǎn","meaning":"to skim over; to browse","meaningThai":"เรียกดู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他用遥控器快速浏览了各个频道。","pinyin":"Tā yòng yáo kòng qì kuài sù liú lǎn le gè gè pín dào。","meaning":"He flipped through the channels with the remote.","meaningThai":"เขาพลิกช่องต่างๆ ด้วยรีโมท"},{"chinese":"我等待时迅速浏览了一下报告。","pinyin":"Wǒ děng dài shí xùn sù liú lǎn le yī xià bào gào。","meaning":"I had a quick flip through the report while I was waiting.","meaningThai":"ฉันได้พลิกดูรายงานอย่างรวดเร็วในขณะที่ฉันกำลังรอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-731","chinese":"留言","pinyin":"liúyán","meaning":"to leave a message; to leave one's comments; message","meaningThai":"ข้อความ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我在你的电话应答机上留言了。","pinyin":"Wǒ zài nǐ de diàn huà yīng dá jī shàng liú yán le。","meaning":"I left a message on your answering machine.","meaningThai":"ฉันฝากข้อความไว้ที่เครื่องตอบรับอัตโนมัติของคุณ"},{"chinese":"我的语音信箱里有她含混不清的留言。","pinyin":"Wǒ de yǔ yīn xìn xiāng lǐ yǒu tā hán hùn bù qīng de liú yán。","meaning":"There was a garbled message from her on my voicemail.","meaningThai":"มีข้อความที่อ่านไม่ออกจากเธอในวอยซ์เมลของฉัน"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-732","chinese":"利益","pinyin":"lìyì","meaning":"benefit; (in sb's) interest","meaningThai":"ผลประโยชน์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"经济规划应该符合全体民众的利益。","pinyin":"Jīng jì guī huá yīng gāi fú hé quán tǐ mín zhòng de lì yì。","meaning":"The economy should be organized to serve the interests of all the people.","meaningThai":"เศรษฐกิจควรจัดเพื่อรองรับผลประโยชน์ของประชาชนทุกคน"},{"chinese":"这些政策有损于社会的利益。","pinyin":"Zhè xiē zhèng cè yǒu sǔn yú shè huì de lì yì。","meaning":"These policies are inimical to the interests of society.","meaningThai":"นโยบายเหล่านี้ไม่มีผลประโยชน์ต่อสังคม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-733","chinese":"利用","pinyin":"lìyòng","meaning":"to exploit; to make use of; to use; to take advantage of; to utilize","meaningThai":"ใช้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他利用这个机会宣布再次减税。","pinyin":"Tā lì yòng zhè gè jī huì xuān bù zài cì jiǎn shuì。","meaning":"He used the occasion to announce further tax cuts.","meaningThai":"เขาจึงใช้โอกาสนี้ประกาศลดหย่อนภาษีเพิ่มเติม"},{"chinese":"我们计划利用外面的咨询公司。","pinyin":"Wǒ mén jì huá lì yòng wài miàn de zī xún gōng sī。","meaning":"We plan to use an outside firm of consultants.","meaningThai":"เราวางแผนที่จะใช้บริษัทที่ปรึกษาภายนอก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-734","chinese":"理由","pinyin":"lǐyóu","meaning":"reason; grounds; justification","meaningThai":"เหตุผล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你没理由生气。","pinyin":"Nǐ méi lǐ yóu shēng qì。","meaning":"You didn't have any reasons to be angry.","meaningThai":"คุณไม่มีเหตุผลที่จะโกรธ"},{"chinese":"沒有理由生氣。","pinyin":"Méi yǒu lǐ yóu shēng qì。","meaning":"There's no reason to get angry.","meaningThai":"ไม่มีเหตุผลที่จะโกรธ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-735","chinese":"离职","pinyin":"lízhí","meaning":"to leave one's job temporarily (e.g. for study); to leave one's job; to resign","meaningThai":"ลาออก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人们普遍认为是媒体迫使他离职的。","pinyin":"Rén mén pǔ biàn rèn wéi shì méi tǐ pò shǐ tā lí zhí de。","meaning":"There is a general view around that he has been hounded out of office by the press.","meaningThai":"มีมุมมองทั่วไปว่าเขาถูกสื่อมวลชนไล่ออกจากตำแหน่ง"},{"chinese":"我们得了13个星期的离职补偿金。","pinyin":"Wǒ mén dé le 13 gè xīng qī de lí zhí bǔ cháng jīn。","meaning":"We were offered 13 weeks' severance pay.","meaningThai":"เราได้รับเงินชดเชยชดเชย 13 สัปดาห์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-736","chinese":"龙","pinyin":"lóng","meaning":"surname Long","meaningThai":"มังกร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"圣乔治杀死了那条龙。","pinyin":"Shèng qiáo zhì shā sǐ le nà tiáo lóng。","meaning":"St George slew the dragon.","meaningThai":"นักบุญจอร์จสังหารมังกร"},{"chinese":"龙队只有一次射门。","pinyin":"Lóng duì zhī yǒu yī cì shè mén。","meaning":"The Dragons had only one shot on goal.","meaningThai":"ดราก้อนส์ยิงเข้าประตูเพียงครั้งเดียว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-737","chinese":"漏","pinyin":"lòu","meaning":"to leak; to divulge; to leave out by mistake; waterclock or hourglass (old)","meaningThai":"รั่ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"屋顶每逢下雨就漏。","pinyin":"Wū dǐng měi féng xià yǔ jiù lòu。","meaning":"The roof leaks whenever it rains.","meaningThai":"หลังคารั่วทุกครั้งที่ฝนตก"},{"chinese":"发动机正在漏机油。","pinyin":"Fā dòng jī zhèng zài lòu jī yóu。","meaning":"Oil is leaking from the engine.","meaningThai":"น้ำมันเครื่องรั่วออกจากเครื่องยนต์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-738","chinese":"录","pinyin":"lù","meaning":"to carve wood","meaningThai":"บันทึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"磁带开始录时告诉我一声。","pinyin":"Cí dài kāi shǐ lù shí gào sù wǒ yī shēng。","meaning":"Tell me when the tape starts recording.","meaningThai":"บอกฉันเมื่อเทปเริ่มบันทึก"},{"chinese":"可录学生的名额不可避免地很有限。","pinyin":"Kě lù xué shēng de míng é bù kě bì miǎn dì hěn yǒu xiàn。","meaning":"The number of places available is necessarily limited.","meaningThai":"จำนวนที่นั่งว่างจำเป็นต้องมีจำนวนจำกัด"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-739","chinese":"陆地","pinyin":"lùdì","meaning":"dry land (as opposed to the sea)","meaningThai":"ที่ดิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"中国陆地的总面积是960万平方公里，是亚洲面积最大的国家，居世界第三位。","pinyin":"Zhōng guó lù dì de zǒng miàn jī shì 960 wàn píng fāng gōng lǐ， shì yà zhōu miàn jī zuì dà de guó jiā， jū shì jiè dì sān wèi。","meaning":"The mainland of China covers 96,000,000 square kilometers, and it is the largest country in Asia, as well as the third largest in the world.","meaningThai":"จีนแผ่นดินใหญ่ครอบคลุมพื้นที่ 96,000,000 ตารางกิโลเมตร และเป็นประเทศที่ใหญ่ที่สุดในเอเชีย และใหญ่เป็นอันดับสามของโลก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-740","chinese":"论文","pinyin":"lùnwén","meaning":"paper; treatise; thesis; to discuss a paper or thesis (old)","meaningThai":"วิทยานิพนธ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他在写毕业论文。","pinyin":"Tā zài xiě bì yè lùn wén.","meaning":"He is writing his graduation thesis.","meaningThai":"เขากำลังเขียนวิทยานิพนธ์สำเร็จการศึกษา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-741","chinese":"逻辑","pinyin":"luójí","meaning":"logic (loanword)","meaningThai":"ตรรกะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"没有迹象显示你在乎过逻辑的颠倒。","pinyin":"Méi yǒu jì xiàng xiǎn shì nǐ zài hū guò luó jí de diān dǎo。","meaning":"There is no sign that you bothered to consider the inverse of your logic.","meaningThai":"ไม่มีสัญญาณใดที่บ่งบอกว่าคุณใส่ใจที่จะพิจารณาสิ่งที่ตรงกันข้ามกับตรรกะของคุณ"},{"chinese":"我得承认这件事情有它的逻辑。","pinyin":"Wǒ dé chéng rèn zhè jiàn shì qíng yǒu tā de luó jí。","meaning":"I had to concede the logic of this.","meaningThai":"ฉันต้องยอมรับตรรกะของเรื่องนี้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-742","chinese":"录取","pinyin":"lùqǔ","meaning":"to accept an applicant (prospective student, employee etc) who passes an entrance exam; to admit (a student); to hire (a job candidate)","meaningThai":"ค่าเข้าชม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们执行严格挑选的录取政策。","pinyin":"Tā mén zhí háng yán gé tiāo xuǎn de lù qǔ zhèng cè。","meaning":"Their admissions policy is very selective.","meaningThai":"นโยบายการรับสมัครของพวกเขามีการคัดเลือกมาก"},{"chinese":"应试者必须满足录取的一般条件。","pinyin":"Yīng shì zhě bì xū mǎn zú lù qǔ de yī bān tiáo jiàn。","meaning":"Candidates must satisfy the general conditions for admission.","meaningThai":"ผู้สมัครจะต้องปฏิบัติตามเงื่อนไขทั่วไปในการรับเข้าเรียน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-743","chinese":"路人","pinyin":"lùrén","meaning":"passer-by; stranger","meaningThai":"ผู้สัญจรไปมา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"无辜的过路人被卷入了那场暴乱。","pinyin":"Wú gū de guò lù rén bèi juàn rù le nà cháng bào luàn。","meaning":"Innocent passers-by got caught up in the riots.","meaningThai":"ผู้บริสุทธิ์ที่สัญจรไปมาติดอยู่ในการจลาจล"},{"chinese":"这对夫妇简直就像是陌路人。","pinyin":"Zhè duì fū fù jiǎn zhí jiù xiàng shì mò lù rén。","meaning":"The couple might as well have been strangers.","meaningThai":"ทั้งคู่อาจเป็นคนแปลกหน้าเช่นกัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-744","chinese":"路线","pinyin":"lùxiàn","meaning":"itinerary; route; political line (e.g. right revisionist road)","meaningThai":"เส้นทาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她一贯奉行马克思主义路线。","pinyin":"Tā yī guàn fèng háng mǎ kè sī zhǔ yì lù xiàn。","meaning":"She always takes a Marxist line.","meaningThai":"เธอมักจะเข้าเส้นมาร์กซิสต์เสมอ"},{"chinese":"我们是不是可以另试试别的路线？","pinyin":"Wǒ mén shì bù shì kě yǐ lìng shì shì bié de lù xiàn？","meaning":"Can we perhaps try another route?","meaningThai":"เราอาจจะลองใช้เส้นทางอื่นได้หรือไม่?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-745","chinese":"旅行社","pinyin":"lǚxíngshè","meaning":"travel agency","meaningThai":"บริษัททัวร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我在旅行社订了票。","pinyin":"Wǒ zài lǚ xíng shè dìng le piào.","meaning":"I booked at the travel agency.","meaningThai":"ฉันจองที่บริษัททัวร์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-746","chinese":"陆续","pinyin":"lùxù","meaning":"in turn; successively; one after the other; bit by bit","meaningThai":"อย่างต่อเนื่อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"代表们陆续到达。","pinyin":"Dài biǎo mén lù xù dào dá。","meaning":"The delegates arrived one after another.","meaningThai":"ผู้แทนมาถึงทีละคน"},{"chinese":"客人们陆续来了。","pinyin":"Kè rén mén lù xù lái le。","meaning":"The guests came one after another.","meaningThai":"แขกก็มาทีละคน"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-747","chinese":"录音","pinyin":"lùyīn","meaning":"to record (sound); sound recording","meaningThai":"การบันทึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在这个录音中阿姆斯特朗亲自唱。","pinyin":"Zài zhè gè lù yīn zhōng ā mǔ sī tè lǎng qīn zì chàng。","meaning":"In this recording Armstrong himself is on vocals.","meaningThai":"ในการบันทึกนี้ Armstrong เองก็เป็นผู้ร้อง"},{"chinese":"现场工作多半为进行磁带录音。","pinyin":"Xiàn cháng gōng zuò duō bàn wéi jìn háng cí dài lù yīn。","meaning":"Most of the fieldwork consisted of making tape recordings.","meaningThai":"งานภาคสนามส่วนใหญ่ประกอบด้วยการบันทึกเทป"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-748","chinese":"骂","pinyin":"mà","meaning":"to scold; to abuse; to curse","meaningThai":"ดุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她骂自己运气不好。","pinyin":"Tā mà zì jǐ yùn qì bù hǎo。","meaning":"She cursed her bad luck.","meaningThai":"เธอสาปแช่งโชคร้ายของเธอ"},{"chinese":"噢，我会让她骂的。","pinyin":"Ō， wǒ huì ràng tā mà de。","meaning":"Oh, I'll let her scold.","meaningThai":"โอ้ ฉันจะปล่อยให้เธอดุ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-749","chinese":"买卖","pinyin":"mǎimai","meaning":"buying and selling; business; business transactions","meaningThai":"ซื้อและขาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"明福特关了买卖，进入了政界。","pinyin":"Míng fú tè guān le mǎi mài， jìn rù le zhèng jiè。","meaning":"Minford closed down the business and went into politics.","meaningThai":"มินฟอร์ดปิดกิจการและเข้าสู่การเมือง"},{"chinese":"炒股者赚取股票买卖的价格差。","pinyin":"Chǎo gǔ zhě zhuàn qǔ gǔ piào mǎi mài de jià gé chà。","meaning":"Market makers earn their livings from the spread between buying and selling prices.","meaningThai":"ผู้ดูแลสภาพคล่องหาเลี้ยงชีพได้จากส่วนต่างระหว่างราคาซื้อและราคาขาย"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-750","chinese":"忙碌","pinyin":"mánglù","meaning":"busy; bustling","meaningThai":"ยุ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"医生们十分忙碌，说话简短生硬。","pinyin":"Yī shēng mén shí fēn máng lù， shuō huà jiǎn duǎn shēng yìng。","meaning":"The doctors are brusque and busy.","meaningThai":"หมอเป็นคนเร่งรีบและยุ่งมาก"},{"chinese":"他忙碌工作了一天后需要休息。","pinyin":"Tā máng lù gōng zuò le yī tiān hòu xū yào xiū xī。","meaning":"He needed to relax after the exertions of a busy day at work.","meaningThai":"เขาจำเป็นต้องผ่อนคลายหลังจากเหน็ดเหนื่อยจากการทำงานมาทั้งวัน"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-751","chinese":"满足","pinyin":"mǎnzú","meaning":"to satisfy; to meet (the needs of); satisfied; content","meaningThai":"ทำให้พึงพอใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们不能满足对该产品的需求。","pinyin":"Wǒ mén bù néng mǎn zú duì gāi chǎn pǐn de xū qiú。","meaning":"We cannot satisfy demand for the product.","meaningThai":"เราไม่สามารถสนองความต้องการสินค้าได้"},{"chinese":"他需要钱来满足他的赌瘾。","pinyin":"Tā xū yào qián lái mǎn zú tā de dǔ yǐn。","meaning":"He needed money to feed his addiction to gambling.","meaningThai":"เขาต้องการเงินเพื่อเลี้ยงการติดการพนัน"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-752","chinese":"毛笔","pinyin":"máobǐ","meaning":"writing brush","meaningThai":"แปรงเขียน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我的毛笔是紫罗兰色的。","pinyin":"Wǒ de máo bǐ shì zǐ luó lán sè de。","meaning":"My brush is violet.","meaningThai":"แปรงของฉันเป็นสีม่วง"},{"chinese":"毛笔要由学生自己制作。","pinyin":"Máo bǐ yào yóu xué shēng zì jǐ zhì zuò。","meaning":"Students made their own ink brushes.","meaningThai":"นักเรียนทำพู่กันหมึกของตัวเอง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-753","chinese":"毛病","pinyin":"máobìng","meaning":"fault; defect; shortcomings; ailment","meaningThai":"ผิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们这辆车净出毛病。","pinyin":"Wǒ mén zhè liàng chē jìng chū máo bìng。","meaning":"We've had nothing but trouble with this car.","meaningThai":"เราไม่มีอะไรนอกจากปัญหากับรถคันนี้"},{"chinese":"他有贪杯的毛病。","pinyin":"Tā yǒu tān bēi de máo bìng。","meaning":"He has a drinking problem.","meaningThai":"เขามีปัญหาเรื่องการดื่ม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-754","chinese":"矛盾","pinyin":"máodùn","meaning":"contradiction; conflicting views; contradictory","meaningThai":"ความขัดแย้ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们之间有矛盾。","pinyin":"Ta men zhi jian you mao dun.","meaning":"There is a contradiction between them.","meaningThai":"มีความขัดแย้งระหว่างพวกเขา"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-755","chinese":"没法儿","pinyin":"méifǎr","meaning":"Can't","meaningThai":"ไม่มีทาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他那份虚荣心啊，简直没法儿说了。","pinyin":"Tā nà fèn xū róng xīn ā， jiǎn zhí méi fǎ ér shuō le。","meaning":"He's as full of pride as an egg's full of meat.","meaningThai":"เขาเต็มไปด้วยความภาคภูมิใจเหมือนกับไข่ที่เต็มไปด้วยเนื้อ"},{"chinese":"他甚至没法儿接近她，这使他非常生气。","pinyin":"Tā shèn zhì méi fǎ ér jiē jìn tā， zhè shǐ tā fēi cháng shēng qì。","meaning":"It made him very cross that he was not even able to get near her.","meaningThai":"มันทำให้เขาข้ามมากจนไม่สามารถเข้าใกล้เธอได้"}],"partOfSpeech":["expression"]},
  {"id":"hsk5-756","chinese":"玫瑰","pinyin":"méigui","meaning":"rugosa rose (shrub) (Rosa rugosa); rose flower","meaningThai":"กุหลาบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"玫瑰象征爱情。","pinyin":"Méi guī xiàng zhēng ài qíng.","meaning":"Roses symbolize love.","meaningThai":"กุหลาบเป็นสัญลักษณ์ของความรัก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-757","chinese":"魅力","pinyin":"mèilì","meaning":"charm; fascination; glamor; charisma","meaningThai":"เสน่ห์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她很有魅力。","pinyin":"Ta hen you mei li.","meaning":"She is very charming.","meaningThai":"เธอมีเสน่ห์มาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-758","chinese":"美术","pinyin":"měishù","meaning":"art; fine arts; painting","meaningThai":"ศิลปะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的美术作品获奖了。","pinyin":"Tā de měi shù zuò pǐn huò jiǎng le.","meaning":"Her art work won an award.","meaningThai":"ผลงานศิลปะของเธอได้รับรางวัล"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-759","chinese":"媒体","pinyin":"méitǐ","meaning":"media, esp. news media","meaningThai":"สื่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的新片媒体有很多报道。","pinyin":"Tā de xīn piàn méi tǐ yǒu hěn duō bào dào。","meaning":"Her new movie has had a lot of exposure in the media.","meaningThai":"ภาพยนตร์เรื่องใหม่ของเธอได้รับการเปิดเผยในสื่อมากมาย"},{"chinese":"现在新闻媒体无处不在。","pinyin":"Xiàn zài xīn wén méi tǐ wú chǔ bù zài。","meaning":"These days the media are omnipresent.","meaningThai":"ทุกวันนี้สื่อมีอยู่ทั่วไปทุกหนทุกแห่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-760","chinese":"美味","pinyin":"měiwèi","meaning":"delicious; delicious food; delicacy","meaningThai":"อร่อย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"总有很多种美味佳肴可供选择。","pinyin":"Zǒng yǒu hěn duō zhǒng měi wèi jiā yáo kě gōng xuǎn zé。","meaning":"There's always a wide selection of delicious meals to choose from.","meaningThai":"มีอาหารอร่อยๆ ให้เลือกมากมายเสมอ"},{"chinese":"这些蘑菇将会是一道美味可口的配菜。","pinyin":"Zhè xiē mó gū jiāng huì shì yī dào měi wèi kě kǒu de pèi cài。","meaning":"These mushrooms would make a delicious side dish.","meaningThai":"เห็ดเหล่านี้จะทำกับข้าวอร่อย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-761","chinese":"门诊","pinyin":"ménzhěn","meaning":"outpatient service","meaningThai":"คลินิกผู้ป่วยนอก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个门诊部有6名员工。","pinyin":"Zhè gè mén zhěn bù yǒu 6 míng yuán gōng。","meaning":"The outpatient programme has a staff of six people.","meaningThai":"โปรแกรมผู้ป่วยนอกมีเจ้าหน้าที่หกคน"},{"chinese":"门诊病人方案收费每人每天105美元，一切费用包括在内。","pinyin":"Mén zhěn bìng rén fāng àn shōu fèi měi rén měi tiān 105 měi yuán， yī qiē fèi yòng bāo kuò zài nèi。","meaning":"The outpatient programme costs $105 per day, all inclusive.","meaningThai":"โปรแกรมผู้ป่วยนอกมีค่าใช้จ่าย $105 ต่อวัน รวมทุกอย่างแล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-762","chinese":"迷","pinyin":"mí","meaning":"to bewilder; crazy about; fan; enthusiast; lost; confused","meaningThai":"พัดลม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她对健康饮食着了迷。","pinyin":"Tā duì jiàn kāng yǐn shí zháo le mí。","meaning":"She's fanatical about healthy eating.","meaningThai":"เธอคลั่งไคล้การกินเพื่อสุขภาพ"},{"chinese":"星迷们的钱花得值。","pinyin":"Xīng mí mén de qián huā dé zhí。","meaning":"The fans get their money's worth.","meaningThai":"แฟน ๆ ได้รับเงินอย่างคุ้มค่า"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-763","chinese":"面","pinyin":"miàn","meaning":"face; side; surface; aspect; top; classifier for objects with flat surfaces such as drums, mirrors, flags etc","meaningThai":"ด้าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是面。","pinyin":"Zhè shì miàn.","meaning":"This is side.","meaningThai":"นี่คือด้านข้าง"},{"chinese":"我看见了面。","pinyin":"Wǒ kànjiàn le miàn.","meaning":"I saw side.","meaningThai":"ฉันเห็นด้านข้าง"},{"chinese":"面在这里。","pinyin":"Miàn zài zhèlǐ.","meaning":"The side is here.","meaningThai":"ด้านข้างอยู่นี่ครับ.."}],"partOfSpeech":["noun","measure word","verb","other"]},
  {"id":"hsk5-764","chinese":"面积","pinyin":"miànjī","meaning":"area (of a floor, piece of land etc); surface area; tract of land","meaningThai":"พื้นที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"牧场的面积有10英亩。","pinyin":"Mù cháng de miàn jī yǒu 10 yīng mǔ。","meaning":"The pasture has an area of 10 acres.","meaningThai":"ทุ่งหญ้ามีพื้นที่ 10 ไร่"},{"chinese":"工厂的面积是1000平方米。","pinyin":"Gōng chǎng de miàn jī shì 1000 píng fāng mǐ。","meaning":"The area of the factory is 1,000 square meters.","meaningThai":"พื้นที่ของโรงงานคือ 1,000 ตารางเมตร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-765","chinese":"面临","pinyin":"miànlín","meaning":"to face sth; to be confronted with","meaningThai":"ใบหน้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"侦探现在面临辨认尸体这项任务。","pinyin":"Zhēn tàn xiàn zài miàn lín biàn rèn shī tǐ zhè xiàng rèn wù。","meaning":"Detectives are now faced with the task of identifying the body.","meaningThai":"ขณะนี้นักสืบกำลังเผชิญกับภารกิจในการระบุตัวศพ"},{"chinese":"多数企业都面临大量的竞争。","pinyin":"Duō shù qǐ yè dū miàn lín dà liáng de jìng zhēng。","meaning":"Most businesses face plenty of competition.","meaningThai":"ธุรกิจส่วนใหญ่เผชิญกับการแข่งขันมากมาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-766","chinese":"面向","pinyin":"miànxiàng","meaning":"to face; to turn towards; to incline to; geared towards; catering for; -oriented; facial feature; appearance; aspect; facet","meaningThai":"สำหรับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她从桌前站起来，面向着他。","pinyin":"Tā cóng zhuō qián zhàn qǐ lái， miàn xiàng zháo tā。","meaning":"She stood up from the table and faced him.","meaningThai":"เธอลุกขึ้นจากโต๊ะและเผชิญหน้ากับเขา"},{"chinese":"我把椅子转过来面向火炉。","pinyin":"Wǒ bǎ yǐ zǐ zhuǎn guò lái miàn xiàng huǒ lú。","meaning":"I turned my chair round to face the fire.","meaningThai":"ฉันหมุนเก้าอี้เพื่อเผชิญกับไฟ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-767","chinese":"描述","pinyin":"miáoshù","meaning":"to describe; description","meaningThai":"อธิบาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个描述恰好符合我们的情况。","pinyin":"Zhè gè miáo shù qià hǎo fú hé wǒ mén de qíng kuàng。","meaning":"The description fits us to a tee.","meaningThai":"คำอธิบายเหมาะกับเรากับที"},{"chinese":"有4种基本选择,简略描述如下。","pinyin":"Yǒu 4 zhǒng jī běn xuǎn zé, jiǎn lüè miáo shù rú xià。","meaning":"There are four basic alternatives; they are described briefly below.","meaningThai":"มีทางเลือกพื้นฐานสี่ทาง มีการอธิบายไว้ด้านล่างโดยย่อ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-768","chinese":"迷路","pinyin":"mílù","meaning":"to lose the way; lost; labyrinth; labyrinthus vestibularis (of the inner ear)","meaningThai":"หลงทาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我迷路了。","pinyin":"Wo mi lu le.","meaning":"I got lost.","meaningThai":"ฉันหลงทาง."}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-769","chinese":"秘密","pinyin":"mìmì","meaning":"secret; private; confidential; clandestine; a secret","meaningThai":"ความลับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她怀疑有些秘密势力在作祟。","pinyin":"Tā huái yí yǒu xiē mì mì shì lì zài zuò suì。","meaning":"She suspected that secret influences were at work.","meaningThai":"เธอสงสัยว่าอิทธิพลลับกำลังเกิดขึ้น"},{"chinese":"她知道这个秘密吗？","pinyin":"Tā zhī dào zhè gè mì mì ma？","meaning":"Is she in on the secret?","meaningThai":"เธอกำลังมีความลับอยู่หรือเปล่า?"}],"partOfSpeech":["noun","adjective"]},
  {"id":"hsk5-770","chinese":"命","pinyin":"mìng","meaning":"life; fate; order or command; to assign a name, title etc","meaningThai":"ชีวิต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她行动迅速，救了小孩的命。","pinyin":"Tā háng dòng xùn sù， jiù le xiǎo hái de mìng。","meaning":"Her quick action saved the child's life.","meaningThai":"การกระทำที่รวดเร็วของเธอช่วยชีวิตเด็กไว้ได้"},{"chinese":"他的鲁莽差点要了他的命。","pinyin":"Tā de lǔ mǎng chà diǎn yào le tā de mìng。","meaning":"His daring may have cost him his life.","meaningThai":"ความกล้าหาญของเขาอาจทำให้เขาเสียชีวิต"}],"partOfSpeech":["noun","other"]},
  {"id":"hsk5-771","chinese":"敏感","pinyin":"mǐngǎn","meaning":"sensitive; susceptible","meaningThai":"อ่อนไหว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"证券市场对政局变化非常敏感。","pinyin":"Zhèng quàn shì cháng duì zhèng jú biàn huà fēi cháng mǐn gǎn。","meaning":"The Stock Exchange is very sensitive to political change.","meaningThai":"ตลาดหลักทรัพย์มีความอ่อนไหวต่อการเปลี่ยนแปลงทางการเมืองมาก"},{"chinese":"有些鱼的眼睛对光比我们敏感。","pinyin":"Yǒu xiē yú de yǎn jīng duì guāng bǐ wǒ mén mǐn gǎn。","meaning":"The eyes of some fish have a greater sensitivity to light than ours do.","meaningThai":"ดวงตาของปลาบางชนิดมีความไวต่อแสงมากกว่าของเรา"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-772","chinese":"名称","pinyin":"míngchēng","meaning":"name (of a thing); name (of an organization)","meaningThai":"ชื่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"为完整起见，所有名称均用全名。","pinyin":"Wéi wán zhěng qǐ jiàn， suǒ yǒu míng chēng jūn yòng quán míng。","meaning":"For the sake of completeness, all names are given in full.","meaningThai":"เพื่อความสมบูรณ์ จึงขอยกชื่อให้ครบถ้วน"},{"chinese":"该公司的名称用烫金字母拼成。","pinyin":"Gāi gōng sī de míng chēng yòng tàng jīn zì mǔ pīn chéng。","meaning":"The company name was spelled out in gold letters.","meaningThai":"ชื่อบริษัทสะกดด้วยตัวอักษรสีทอง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-773","chinese":"名牌","pinyin":"míngpái","meaning":"famous brand; nameplate; name tag","meaningThai":"แบรนด์ที่มีชื่อเสียง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我喜欢把各种名牌服装混穿在一起。","pinyin":"Wǒ xǐ huān bǎ gè zhǒng míng pái fú zhuāng hùn chuān zài yī qǐ。","meaning":"I like to mix up designer clothes.","meaningThai":"ฉันชอบที่จะมิกซ์เสื้อผ้าของดีไซเนอร์"},{"chinese":"他花了几百英镑买名牌服装。","pinyin":"Tā huā le jī bǎi yīng bàng mǎi míng pái fú zhuāng。","meaning":"He splashed out hundreds of pounds on designer clothes.","meaningThai":"เขาทุ่มเงินหลายร้อยปอนด์ไปกับเสื้อผ้าดีไซเนอร์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-774","chinese":"名片","pinyin":"míngpiàn","meaning":"(business) card","meaningThai":"นามบัตร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"交换名片是商务礼仪。","pinyin":"Jiāo huàn míng piàn shì shāng wù lǐ yí.","meaning":"Exchanging business cards is business etiquette.","meaningThai":"การแลกเปลี่ยนนามบัตรถือเป็นมารยาททางธุรกิจ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-775","chinese":"明确","pinyin":"míngquè","meaning":"clear-cut; definite; explicit; to clarify; to specify; to make definite","meaningThai":"ชัดเจน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"是非之间没有明确的界限。","pinyin":"Shì fēi zhī jiān méi yǒu míng què de jiè xiàn。","meaning":"There is no clear dividing line between what is good and what is bad.","meaningThai":"ไม่มีเส้นแบ่งที่ชัดเจนระหว่างสิ่งดีและสิ่งชั่ว"},{"chinese":"警察的职权必须明确界定。","pinyin":"Jǐng chá de zhí quán bì xū míng què jiè dìng。","meaning":"The powers of the police must be clearly defined.","meaningThai":"ต้องกำหนดอำนาจของตำรวจให้ชัดเจน"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-776","chinese":"明显","pinyin":"míngxiǎn","meaning":"clear; distinct; obvious","meaningThai":"ชัดเจน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们明显很欣赏你。","pinyin":"Tā mén míng xiǎn hěn xīn shǎng nǐ。","meaning":"They obviously appreciate you very much.","meaningThai":"เห็นได้ชัดว่าพวกเขาซาบซึ้งคุณมาก"},{"chinese":"这是非常明显的。","pinyin":"Zhè shì fēi cháng míng xiǎn de。","meaning":"It was glaringly obvious.","meaningThai":"มันก็เห็นได้ชัดเจน"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-777","chinese":"明星","pinyin":"míngxīng","meaning":"star; celebrity","meaningThai":"ดาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那时她作为明星的地位已经确立。","pinyin":"Nà shí tā zuò wéi míng xīng de dì wèi yǐ jīng què lì。","meaning":"By then she was established as a star.","meaningThai":"จากนั้นเธอก็ได้รับการสถาปนาเป็นดารา"},{"chinese":"电影明星旅行时常喜欢隐瞒身份。","pinyin":"Diàn yǐng míng xīng lǚ háng shí cháng xǐ huān yǐn mán shēn fèn。","meaning":"Movie stars often prefer to travel incognito.","meaningThai":"ดาราภาพยนตร์มักชอบเดินทางโดยไม่ระบุตัวตน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-778","chinese":"命运","pinyin":"mìngyùn","meaning":"fate; destiny","meaningThai":"โชคชะตา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们的经济命运和欧洲息息相关。","pinyin":"Wǒ mén de jīng jì mìng yùn hé ōu zhōu xī xī xiāng guān。","meaning":"Our economic fortunes are inseparable from those of Europe.","meaningThai":"ความมั่งคั่งทางเศรษฐกิจของเราแยกไม่ออกจากยุโรป"},{"chinese":"她对自己的命运感到不满。","pinyin":"Tā duì zì jǐ de mìng yùn gǎn dào bù mǎn。","meaning":"She was feeling dissatisfied with her lot.","meaningThai":"เธอรู้สึกไม่พอใจกับสิ่งที่เธอมีอยู่มากมาย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-779","chinese":"密切","pinyin":"mìqiè","meaning":"close; familiar; intimate; closely (related); to foster close ties; to pay close attention","meaningThai":"ปิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"警察正在密切监视嫌疑犯的活动。","pinyin":"Jǐng chá zhèng zài mì qiē jiān shì xián yí fàn de huó dòng。","meaning":"The police are keeping a close watch on the suspect's movements.","meaningThai":"ตำรวจกำลังจับตาดูความเคลื่อนไหวของผู้ต้องสงสัยอย่างใกล้ชิด"},{"chinese":"他们同意建立更密切的经济联系。","pinyin":"Tā mén tóng yì jiàn lì gēng mì qiē de jīng jì lián xì。","meaning":"They agreed to forge closer economic ties.","meaningThai":"พวกเขาตกลงที่จะสร้างความสัมพันธ์ทางเศรษฐกิจที่ใกล้ชิดยิ่งขึ้น"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-780","chinese":"秘书","pinyin":"mìshū","meaning":"secretary","meaningThai":"เลขานุการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"秘书不停地更换，令人厌烦。","pinyin":"Mì shū bù tíng dì gēng huàn， líng rén yàn fán。","meaning":"New secretaries came and went with monotonous regularity.","meaningThai":"เลขานุการใหม่เข้ามาและจากไปด้วยความสม่ำเสมอที่ซ้ำซากจำเจ"},{"chinese":"优秀的秘书总是很抢手。","pinyin":"Yōu xiù de mì shū zǒng shì hěn qiāng shǒu。","meaning":"Good secretaries are always in demand.","meaningThai":"เลขานุการที่ดีมักเป็นที่ต้องการ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-781","chinese":"摸","pinyin":"mō","meaning":"to feel with the hand; to touch; to stroke; to grope; to steal; to abstract","meaningThai":"สัมผัส","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你一摸就知道这是丝绸。","pinyin":"Nǐ yī mō jiù zhī dào zhè shì sī chóu。","meaning":"You can tell it's silk by the feel.","meaningThai":"คุณสามารถบอกได้ว่ามันเป็นผ้าไหมด้วยความรู้สึก"},{"chinese":"他伸出手去摸她。","pinyin":"Tā shēn chū shǒu qù mō tā。","meaning":"He reached out his hand to touch her.","meaningThai":"เขายื่นมือออกไปสัมผัสเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-782","chinese":"模糊","pinyin":"móhu","meaning":"vague; indistinct; fuzzy","meaningThai":"คลุมเครือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这句句子意思模糊。","pinyin":"Zhè jù jù zǐ yì sī mó hū。","meaning":"The meaning of this sentence is obscure.","meaningThai":"ความหมายของประโยคนี้ไม่ชัดเจน"},{"chinese":"我对祖母的记忆很模糊。","pinyin":"Wǒ duì zǔ mǔ de jì yì hěn mó hū。","meaning":"I have a dim memory of my grandmother.","meaningThai":"ฉันมีความทรงจำอันเลือนลางเกี่ยวกับคุณยายของฉัน"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-783","chinese":"陌生","pinyin":"mòshēng","meaning":"strange; unfamiliar","meaningThai":"ความแปลกประหลาด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她在陌生的环境中感到局促不安。","pinyin":"Tā zài mò shēng de huán jìng zhōng gǎn dào jú cù bù ān。","meaning":"She felt uneasy in the unfamiliar surroundings.","meaningThai":"เธอรู้สึกไม่สบายใจในสภาพแวดล้อมที่ไม่คุ้นเคย"},{"chinese":"我们告诉女儿不要和陌生人讲话。","pinyin":"Wǒ mén gào sù nǚ ér bù yào hé mò shēng rén jiǎng huà。","meaning":"We've told our daughter not to speak to strangers.","meaningThai":"เราบอกลูกสาวของเราว่าอย่าพูดกับคนแปลกหน้า"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-784","chinese":"模式","pinyin":"móshì","meaning":"mode; method; pattern","meaningThai":"แบบอย่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"经济活动常常遵循周期性模式。","pinyin":"Jīng jì huó dòng cháng cháng zūn xún zhōu qī xìng mó shì。","meaning":"Economic activity often follows a cyclical pattern.","meaningThai":"กิจกรรมทางเศรษฐกิจมักเป็นไปตามรูปแบบวัฏจักร"},{"chinese":"家庭生活模式正在变得多样化。","pinyin":"Jiā tíng shēng huó mó shì zhèng zài biàn dé duō yàng huà。","meaning":"Patterns of family life are diversifying.","meaningThai":"รูปแบบชีวิตครอบครัวมีความหลากหลาย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-785","chinese":"某","pinyin":"mǒu","meaning":"some; a certain; sb or sth indefinite; such-and-such","meaningThai":"แน่ใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"学生们申请某学院的入学许可。","pinyin":"Xué shēng mén shēn qǐng mǒu xué yuàn de rù xué xǔ kě。","meaning":"Students apply for admission to a particular college.","meaningThai":"นักศึกษาสมัครเข้าเรียนในวิทยาลัยแห่งใดแห่งหนึ่ง"},{"chinese":"她住在伦敦某住宅区的一栋高楼里。","pinyin":"Tā zhù zài lún dūn mǒu zhù zhái qū de yī dòng gāo lóu lǐ。","meaning":"She lives in a tower block on an estate in London.","meaningThai":"เธออาศัยอยู่ในตึกทาวเวอร์บนที่ดินในลอนดอน"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-786","chinese":"目光","pinyin":"mùguāng","meaning":"gaze; (fig.) attention; expression in one's eyes; look; (lit. and fig.) sight; vision","meaningThai":"ดู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他目光发亮，兴奋不已。","pinyin":"Tā mù guāng fā liàng， xīng fèn bù yǐ。","meaning":"His eyes were bright and excited.","meaningThai":"ดวงตาของเขาสดใสและตื่นเต้น"},{"chinese":"她不做声，目光低垂。","pinyin":"Tā bù zuò shēng， mù guāng dī chuí。","meaning":"She was silent, her eyes downcast.","meaningThai":"เธอเงียบ สายตาของเธอลดลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-787","chinese":"木头","pinyin":"mùtou","meaning":"slow-witted; blockhead; log (of wood, timber etc)","meaningThai":"ไม้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"木头不能受潮，否则很快就会烂掉。","pinyin":"Mù tóu bù néng shòu cháo， fǒu zé hěn kuài jiù huì làn diào。","meaning":"The wood must not get damp as rot can quickly result.","meaningThai":"ไม้จะต้องไม่อับชื้นเพราะอาจเน่าเปื่อยได้อย่างรวดเร็ว"},{"chinese":"检查接头是否牢固，木头是否完好。","pinyin":"Jiǎn chá jiē tóu shì fǒu láo gù， mù tóu shì fǒu wán hǎo。","meaning":"Check that joints are secure and the wood is sound.","meaningThai":"ตรวจสอบว่าข้อต่อแน่นหนาและไม้แข็งแรง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-788","chinese":"难得","pinyin":"nándé","meaning":"seldom; rare; hard to come by","meaningThai":"หายาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我难得见到她将喜怒形于色。","pinyin":"Wǒ nán dé jiàn dào tā jiāng xǐ nù xíng yú sè。","meaning":"I have rarely seen her display any sign of emotion.","meaningThai":"ฉันไม่ค่อยเห็นเธอแสดงอาการแสดงอารมณ์ใดๆ"},{"chinese":"“我信不过他。”他以难得的坦率说道。","pinyin":"“ wǒ xìn bù guò tā。” tā yǐ nán dé de tǎn shuài shuō dào。","meaning":"'I don't trust him,' he said, in a rare moment of candour.","meaningThai":"“ฉันไม่ไว้ใจเขา” เขากล่าวในช่วงเวลาแห่งน้ำใสใจจริงที่หาได้ยาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-789","chinese":"难度","pinyin":"nándù","meaning":"degree of difficulty","meaningThai":"ความยากลำบาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这支曲子节奏变化多，难度很大。","pinyin":"Zhè zhī qū zǐ jié zòu biàn huà duō， nán dù hěn dà。","meaning":"It's a difficult piece, with numerous changes of tempo.","meaningThai":"เป็นเพลงที่ยาก โดยมีการเปลี่ยนแปลงจังหวะมากมาย"},{"chinese":"公众人物要赢得诽谤诉讼是有难度的。","pinyin":"Gōng zhòng rén wù yào yíng dé fěi bàng sù sòng shì yǒu nán dù de。","meaning":"It can be difficult for public figures to win a libel case.","meaningThai":"อาจเป็นเรื่องยากสำหรับบุคคลสาธารณะที่จะชนะคดีหมิ่นประมาท"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-790","chinese":"难以","pinyin":"nányǐ","meaning":"hard to (predict, imagine etc)","meaningThai":"ยาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"空气非常寒冷，我们难以呼吸。","pinyin":"Kōng qì fēi cháng hán lěng， wǒ mén nán yǐ hū xī。","meaning":"The air was so cold we could hardly breathe.","meaningThai":"อากาศหนาวจนแทบจะหายใจไม่ออก"},{"chinese":"损失情况难以全面估计。","pinyin":"Sǔn shī qíng kuàng nán yǐ quán miàn gū jì。","meaning":"It is difficult to assess the full extent of the damage.","meaningThai":"เป็นการยากที่จะประเมินความเสียหายทั้งหมด"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-791","chinese":"男子","pinyin":"nánzǐ","meaning":"a man; a male","meaningThai":"ผู้ชาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个男子有枪，是个危险分子。","pinyin":"Zhè gè nán zǐ yǒu qiāng， shì gè wēi xiǎn fēn zǐ。","meaning":"The man is armed and dangerous.","meaningThai":"ชายคนนี้มีอาวุธและอันตราย"},{"chinese":"这是当今时髦男子的穿着。","pinyin":"Zhè shì dāng jīn shí máo nán zǐ de chuān zháo。","meaning":"This is what today's well-dressed man is wearing.","meaningThai":"นี่คือสิ่งที่ผู้ชายแต่งตัวดีในปัจจุบันสวมใส่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-792","chinese":"闹","pinyin":"nào","meaning":"variant of 闹","meaningThai":"เสียงดัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"都是疫情闹的。","pinyin":"Dū shì yì qíng nào de。","meaning":"It's all due to the pandemic.","meaningThai":"ทั้งหมดนี้เกิดจากโรคระบาด"},{"chinese":"她很吵闹，不是吗？","pinyin":"Tā hěn chǎo nào， bù shì ma？","meaning":"She's loud, isn't she?","meaningThai":"เธอเสียงดังไม่ใช่เหรอ?"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-793","chinese":"闹钟","pinyin":"nàozhōng","meaning":"alarm clock","meaningThai":"นาฬิกาปลุก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我忘了上闹钟，所以睡过了头。","pinyin":"Wǒ wàng le shàng nào zhōng， suǒ yǐ shuì guò le tóu。","meaning":"I forgot to set my alarm and I overslept.","meaningThai":"ฉันลืมตั้งนาฬิกาปลุกและเผลอหลับไป"},{"chinese":"爸爸把闹钟设到了第2天8点。","pinyin":"Bà bà bǎ nào zhōng shè dào le dì 2 tiān 8 diǎn。","meaning":"Dad set the alarm for eight the next day.","meaningThai":"พ่อตั้งปลุกตอนแปดโมงในวันรุ่งขึ้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-794","chinese":"哪怕","pinyin":"nǎpà","meaning":"even; even if; even though; no matter how","meaningThai":"สม่ำเสมอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"哪怕是有人提到他的名字，她也会勃然大怒。","pinyin":"Nǎ pà shì yǒu rén tí dào tā de míng zì， tā yě huì bó rán dà nù。","meaning":"She flies into a passion if anyone even mentions his name.","meaningThai":"เธอรู้สึกหลงใหลหากใครก็ตามเอ่ยถึงชื่อของเขา"},{"chinese":"一项研究表明，每天哪怕只抽10支烟也会损害生育能力。","pinyin":"Yī xiàng yán jiū biǎo míng， měi tiān nǎ pà zhī chōu 10 zhī yān yě huì sǔn hài shēng yù néng lì。","meaning":"One study showed that even as few as ten cigarettes a day can damage fertility.","meaningThai":"การศึกษาชิ้นหนึ่งแสดงให้เห็นว่าแม้บุหรี่เพียงสิบมวนต่อวันก็สามารถทำลายภาวะเจริญพันธุ์ได้"}],"partOfSpeech":["conjunction"]},
  {"id":"hsk5-795","chinese":"内部","pinyin":"nèibù","meaning":"interior; inside (part, section); internal","meaningThai":"ภายใน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"75%的高层主管来自公司内部。","pinyin":"75% de gāo céng zhǔ guǎn lái zì gōng sī nèi bù。","meaning":"75 percent of chief executives come from inside the company.","meaningThai":"75 เปอร์เซ็นต์ของผู้บริหารระดับสูงมาจากภายในบริษัท"},{"chinese":"政府将继续努力重建市区内部。","pinyin":"Zhèng fǔ jiāng jì xù nǔ lì zhòng jiàn shì qū nèi bù。","meaning":"The government will continue to try to regenerate inner-city areas.","meaningThai":"รัฐบาลจะพยายามฟื้นฟูพื้นที่เมืองชั้นในต่อไป"}],"partOfSpeech":["other"]},
  {"id":"hsk5-796","chinese":"能干","pinyin":"nénggàn","meaning":"capable; competent","meaningThai":"มีความสามารถ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他是一个能干、正直、虔诚的人。","pinyin":"Tā shì yī gè néng gān、 zhèng zhí、 qián chéng de rén。","meaning":"He is an able, right-minded, and religious man.","meaningThai":"เขาเป็นคนมีความสามารถ มีความคิดถูกต้อง และเคร่งศาสนา"},{"chinese":"军队称赞他为杰出能干的工程师。","pinyin":"Jūn duì chēng zàn tā wéi jié chū néng gān de gōng chéng shī。","meaning":"The army recognized him as an outstandingly able engineer.","meaningThai":"กองทัพยอมรับว่าเขาเป็นวิศวกรที่มีความสามารถโดดเด่น"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-797","chinese":"念","pinyin":"niàn","meaning":"variant of 念, to read aloud","meaningThai":"อ่าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“请再念几遍，孩子。”她恳求道。","pinyin":"“ qǐng zài niàn jī biàn， hái zǐ。” tā kěn qiú dào。","meaning":"\"Please read it a few times over, child,\" she entreated.","meaningThai":"“โปรดอ่านซ้ำสองสามครั้งนะเด็กน้อย” เธออ้อนวอน"},{"chinese":"我念什么呢，奶奶？","pinyin":"Wǒ niàn shí mó ne， nǎi nǎi？","meaning":"What shall I read, grandmother?","meaningThai":"ฉันจะอ่านอะไรคุณยาย?"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-798","chinese":"年初","pinyin":"niánchū","meaning":"beginning of the year","meaningThai":"ต้นปี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她计划明年初展出自己的绘画作品。","pinyin":"Tā jì huá míng nián chū zhǎn chū zì jǐ de huì huà zuò pǐn。","meaning":"She plans to show her paintings early next year.","meaningThai":"เธอวางแผนที่จะแสดงภาพวาดของเธอในต้นปีหน้า"},{"chinese":"法文版在2006年初面市。","pinyin":"Fǎ wén bǎn zài 2006 nián chū miàn shì。","meaning":"The French edition came out in early 2006.","meaningThai":"ฉบับภาษาฝรั่งเศสออกมาเมื่อต้นปี พ.ศ. 2549"}],"partOfSpeech":["other"]},
  {"id":"hsk5-799","chinese":"年代","pinyin":"niándài","meaning":"a decade of a century (e.g. the Sixties); age; era; period","meaningThai":"ยุค","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我和他初次见面早在1980年代。","pinyin":"Wǒ hé tā chū cì jiàn miàn zǎo zài 1980 nián dài。","meaning":"I first met him way back in the 80s.","meaningThai":"ฉันพบเขาครั้งแรกในยุค 80"},{"chinese":"男子留长发在60年代流行开来。","pinyin":"Nán zǐ liú cháng fā zài 60 nián dài liú háng kāi lái。","meaning":"Long hair for men came in in the sixties.","meaningThai":"ผมยาวสำหรับผู้ชายเข้ามาในช่วงอายุหกสิบเศษ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-800","chinese":"年纪","pinyin":"niánjì","meaning":"age","meaningThai":"อายุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我在你这个年纪时已经结婚了。","pinyin":"Wǒ zài nǐ zhè gè nián jì shí yǐ jīng jié hūn le。","meaning":"When I was your age I was already married.","meaningThai":"ตอนที่ฉันอายุเท่าเธอ ฉันเคยแต่งงานแล้ว"},{"chinese":"这些测验使年纪较大的人受到歧视。","pinyin":"Zhè xiē cè yàn shǐ nián jì jiào dà de rén shòu dào qí shì。","meaning":"The tests discriminate unfairly against older people.","meaningThai":"การทดสอบนี้เลือกปฏิบัติอย่างไม่ยุติธรรมต่อผู้สูงอายุ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-801","chinese":"年夜饭","pinyin":"niányèfàn","meaning":"New Year's Eve family dinner","meaningThai":"อาหารเย็นวันส่งท้ายปีเก่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"过新年的时候我们会和家里人吃年夜饭。","pinyin":"Guò xīn nián de shí hòu wǒ mén huì hé jiā lǐ rén chī nián yè fàn。","meaning":"On the Lunar New Year, we usually have a big dinner with our family.","meaningThai":"ในช่วงปีใหม่ทางจันทรคติ เรามักจะทานอาหารมื้อใหญ่กับครอบครัว"},{"chinese":"“你愿意明天和我们一起吃年夜饭吗？”妈妈问。","pinyin":"“ nǐ yuàn yì míng tiān hé wǒ mén yī qǐ chī nián yè fàn ma？” mā mā wèn。","meaning":"\"Would you like to join us tomorrow for New Year's dinner?\" asked Mom.","meaningThai":"“พรุ่งนี้มาร่วมดินเนอร์วันปีใหม่กับเราไหม?” ถามแม่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-802","chinese":"牛仔裤","pinyin":"niúzǎikù","meaning":"jeans","meaningThai":"ยีนส์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"牛仔裤是典型的美式服装。","pinyin":"Niú zī kù shì diǎn xíng de měi shì fú zhuāng。","meaning":"Jeans are as American as apple pie.","meaningThai":"กางเกงยีนส์มีความเป็นอเมริกันพอๆ กับพายแอปเปิ้ล"},{"chinese":"她把牛仔裤卷到了膝盖处。","pinyin":"Tā bǎ niú zī kù juàn dào le xī gài chǔ。","meaning":"She rolled her jeans to her knees.","meaningThai":"เธอรีดกางเกงยีนส์ของเธอจนคุกเข่า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-803","chinese":"浓","pinyin":"nóng","meaning":"concentrated; dense; strong (smell etc)","meaningThai":"เข้มข้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这东西尝起来像鸡肉，只是味道浓一点。","pinyin":"Zhè dōng xī cháng qǐ lái xiàng jī ròu， zhī shì wèi dào nóng yī diǎn。","meaning":"It tastes like chicken, only stronger.","meaningThai":"รสชาติเหมือนไก่แต่เข้มข้นกว่าเท่านั้น"},{"chinese":"昨晚下了雨，所以花园里全是浓稠的泥浆。","pinyin":"Zuó wǎn xià le yǔ， suǒ yǐ huā yuán lǐ quán shì nóng chóu de ní jiāng。","meaning":"It had rained last night, so the garden was thick mud.","meaningThai":"เมื่อคืนฝนตก สวนจึงเป็นโคลนหนา"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-804","chinese":"农民","pinyin":"nóngmín","meaning":"peasant; farmer","meaningThai":"ชาวนา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"农民让土地休耕现在得到了回报。","pinyin":"Nóng mín ràng tǔ dì xiū gēng xiàn zài dé dào le huí bào。","meaning":"Farmers are now paid to let their land lie fallow.","meaningThai":"ตอนนี้เกษตรกรได้รับเงินเพื่อให้ที่ดินของตนรกร้าง"},{"chinese":"农民已获得政府授权开发这些农场。","pinyin":"Nóng mín yǐ huò dé zhèng fǔ shòu quán kāi fā zhè xiē nóng cháng。","meaning":"Farmers were granted concessions from the government to develop the farms.","meaningThai":"เกษตรกรได้รับสัมปทานจากรัฐบาลในการพัฒนาฟาร์ม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-805","chinese":"农业","pinyin":"nóngyè","meaning":"agriculture; farming","meaningThai":"เกษตรกรรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这项新技术已应用于农业。","pinyin":"Zhè xiàng xīn jì shù yǐ yīng yòng yú nóng yè。","meaning":"The new technology was applied to farming.","meaningThai":"นำเทคโนโลยีใหม่มาประยุกต์ใช้กับการเกษตร"},{"chinese":"有机农业在各处发展。","pinyin":"Yǒu jī nóng yè zài gè chǔ fā zhǎn。","meaning":"Organic farming is expanding everywhere.","meaningThai":"การทำเกษตรอินทรีย์กำลังขยายตัวไปทุกที่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-806","chinese":"女子","pinyin":"nǚzǐ","meaning":"woman; female","meaningThai":"ผู้หญิง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"凯瑟琳是位虔诚、真挚的女子。","pinyin":"Kǎi sè lín shì wèi qián chéng、 zhēn zhì de nǚ zǐ。","meaning":"Catherine was a pious, earnest woman.","meaningThai":"แคทเธอรีนเป็นผู้หญิงที่เคร่งครัดและจริงจัง"},{"chinese":"那个年轻女子个子高挑，身材苗条。","pinyin":"Nà gè nián qīng nǚ zǐ gè zǐ gāo tiāo， shēn cái miáo tiáo。","meaning":"The young woman was tall and slim.","meaningThai":"หญิงสาวสูงและผอมเพรียว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-807","chinese":"哦","pinyin":"ò","meaning":"to chant","meaningThai":"โอ้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"哦，看我们笑得!","pinyin":"Ó， kàn wǒ mén xiào dé!","meaning":"Oh, how we laughed!","meaningThai":"โอ้เราหัวเราะขนาดไหน!"}],"partOfSpeech":["other","interjection"]},
  {"id":"hsk5-808","chinese":"偶然","pinyin":"ǒurán","meaning":"incidentally; occasional; occasionally; by chance; randomly","meaningThai":"โดยบังเอิญ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"偶然发现。","pinyin":"Ou ran fa xian.","meaning":"Discover by chance.","meaningThai":"ค้นพบโดยบังเอิญ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-809","chinese":"欧洲","pinyin":"Ōuzhōu","meaning":"Europe (abbr. for 欧罗巴洲)","meaningThai":"ยุโรป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"战后，欧洲版图被重新划定。","pinyin":"Zhàn hòu， ōu zhōu bǎn tú bèi zhòng xīn huá dìng。","meaning":"After the war the map of Europe was redrawn.","meaningThai":"หลังสงคราม แผนที่ของยุโรปถูกวาดขึ้นใหม่"},{"chinese":"吉姆期待不久就被派往欧洲。","pinyin":"Jí mǔ qī dài bù jiǔ jiù bèi pài wǎng ōu zhōu。","meaning":"Jim expects to be sent to Europe any day now.","meaningThai":"จิมคาดว่าจะถูกส่งไปยุโรปสักวันหนึ่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-810","chinese":"派","pinyin":"pài","meaning":"clique; school; group; faction; to dispatch; to send; to assign; to appoint; pi (Greek letter Ππ); the circular ratio pi = 3.1415926; (loanword) pie","meaningThai":"กลุ่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"老板派她进城办事去了。","pinyin":"Lǎo bǎn pài tā jìn chéng bàn shì qù le。","meaning":"Her boss sent her on an errand into town.","meaningThai":"เจ้านายของเธอส่งเธอไปทำธุระในเมือง"},{"chinese":"已派信使去取文件。","pinyin":"Yǐ pài xìn shǐ qù qǔ wén jiàn。","meaning":"A courier was dispatched to collect the docu we are pirates, these data are stolen from youdao s.","meaningThai":"ได้มีการส่งเอกสารไปรับเอกสารแล้ว"}],"partOfSpeech":["verb","noun","measure word"]},
  {"id":"hsk5-811","chinese":"派出所","pinyin":"pàichūsuǒ","meaning":"police station","meaningThai":"สถานีตำรวจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"警察把我的车开到派出所。","pinyin":"Jǐng chá bǎ wǒ de chē kāi dào pài chū suǒ。","meaning":"The policeman drove my car to the police station.","meaningThai":"ตำรวจขับรถของฉันไปที่สถานีตำรวจ"},{"chinese":"那是派出所吗？","pinyin":"Nà shì pài chū suǒ ma？","meaning":"Is that the police office?","meaningThai":"นั่นคือสำนักงานตำรวจเหรอ?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-812","chinese":"排列","pinyin":"páiliè","meaning":"to arrange in order; (math.) permutation","meaningThai":"การจัดเตรียม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我按时间顺序排列了这些故事。","pinyin":"Wǒ àn shí jiān shùn xù pái liè le zhè xiē gù shì。","meaning":"I have arranged these stories in chronological order.","meaningThai":"ข้าพเจ้าได้จัดเรียงเรื่องราวเหล่านี้ตามลำดับเวลา"},{"chinese":"这些排列向无穷大增加。","pinyin":"Zhè xiē pái liè xiàng wú qióng dà zēng jiā。","meaning":"These permutations multiply toward infinity.","meaningThai":"การเรียงสับเปลี่ยนเหล่านี้ทวีคูณไปสู่อนันต์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-813","chinese":"拍摄","pinyin":"pāishè","meaning":"to take (a picture); to shoot (a film)","meaningThai":"การยิง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"镜头慢慢移动拍摄房间全景。","pinyin":"Jìng tóu màn màn yí dòng pāi shè fáng jiān quán jǐng。","meaning":"The shot panned slowly across the room.","meaningThai":"ภาพนั้นค่อยๆกระจายไปทั่วห้อง"},{"chinese":"他有个主意，以纯白为背景给他们拍摄。","pinyin":"Tā yǒu gè zhǔ yì， yǐ chún bái wéi bèi jǐng gěi tā mén pāi shè。","meaning":"He had the idea of shooting them against a complete plain white background.","meaningThai":"เขามีความคิดที่จะถ่ายภาพพวกเขากับพื้นหลังสีขาวเรียบๆ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-814","chinese":"跑道","pinyin":"pǎodào","meaning":"athletic track; track; runway (i.e. airstrip)","meaningThai":"ติดตาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些飞机在毗连的跑道上降落。","pinyin":"Zhè xiē fēi jī zài pí lián de pǎo dào shàng jiàng luò。","meaning":"The planes landed on adjacent runways.","meaningThai":"เครื่องบินลงจอดบนรันเวย์ที่อยู่ติดกัน"},{"chinese":"我们靠近跑道时，我减速了。","pinyin":"Wǒ mén kào jìn pǎo dào shí， wǒ jiǎn sù le。","meaning":"I throttled back as we approached the runway.","meaningThai":"ฉันเร่งความเร็วกลับเมื่อเราเข้าใกล้รันเวย์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-815","chinese":"赔","pinyin":"péi","meaning":"to compensate for loss; to indemnify; to suffer a financial loss","meaningThai":"จ่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"玻璃是我打碎的，由我来赔。","pinyin":"Bō lí shì wǒ dǎ suì de， yóu wǒ lái péi。","meaning":"I broke the glass, so I'll pay for it.","meaningThai":"ฉันทำกระจกแตก ฉันจะจ่ายค่ามัน"},{"chinese":"损坏东西要赔。","pinyin":"Sǔn huài dōng xī yào péi。","meaning":"Pay for anything you damage.","meaningThai":"จ่ายสำหรับสิ่งที่คุณเสียหาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-816","chinese":"配","pinyin":"pèi","meaning":"to join; to fit; to mate; to mix; to match; to deserve; to make up (a prescription); to allocate","meaningThai":"จับคู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们只得等药剂师给她配好药。","pinyin":"Wǒ mén zhī dé děng yào jì shī gěi tā pèi hǎo yào。","meaning":"We had to wait for the pharmacist to make up her prescription.","meaningThai":"เราต้องรอเภสัชกรสั่งยาให้เธอ"},{"chinese":"这幅画现在可以装裱、配框了。","pinyin":"Zhè fú huà xiàn zài kě yǐ zhuāng biǎo、 pèi kuàng le。","meaning":"The picture is now ready to be mounted and framed.","meaningThai":"ตอนนี้ภาพพร้อมที่จะติดตั้งและใส่กรอบแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-817","chinese":"陪伴","pinyin":"péibàn","meaning":"to accompany","meaningThai":"มาพร้อมกับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"罗斯一直都很享受女人的陪伴。","pinyin":"Luó sī yī zhí dū hěn xiǎng shòu nǚ rén de péi bàn。","meaning":"Ross had always enjoyed the company of women.","meaningThai":"รอสส์มีความสุขที่ได้อยู่กับผู้หญิงมาโดยตลอด"},{"chinese":"我依赖他的陪伴和他的判断。","pinyin":"Wǒ yī lài tā de péi bàn hé tā de pàn duàn。","meaning":"I depended on his companionship and on his judgment.","meaningThai":"ฉันขึ้นอยู่กับความเป็นเพื่อนของเขาและการตัดสินของเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-818","chinese":"配合","pinyin":"pèihé","meaning":"matching; fitting in with; compatible with; to correspond; to fit; to conform to; rapport; to coordinate with; to act in concert with; to cooperate; to become man and wife; to combine parts of machine","meaningThai":"ให้ความร่วมมือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"队员间的配合并非强迫命令而成。","pinyin":"Duì yuán jiān de pèi hé bìng fēi qiáng pò mìng líng ér chéng。","meaning":"You can't enforce cooperation between the players.","meaningThai":"คุณไม่สามารถบังคับใช้ความร่วมมือระหว่างผู้เล่นได้"},{"chinese":"他同意配合警方调查。","pinyin":"Tā tóng yì pèi hé jǐng fāng tiáo chá。","meaning":"He agreed to cooperate with the police investigation.","meaningThai":"เขาตกลงที่จะให้ความร่วมมือในการสืบสวนของตำรวจ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-819","chinese":"配送","pinyin":"pèisòng","meaning":"to put together an order and deliver it (i.e. 配货 and 送货); to deliver (goods)","meaningThai":"จัดส่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"营销组合的重点将放在价格和配送上。","pinyin":"Yíng xiāo zǔ hé de zhòng diǎn jiāng fàng zài jià gé hé pèi sòng shàng。","meaning":"The key focus of the marketing mix will be on price and distribution.","meaningThai":"จุดสนใจหลักของส่วนประสมทางการตลาดจะอยู่ที่ราคาและการจัดจำหน่าย"},{"chinese":"他们星期四到达配送中心，花了一天的时间为客人提供食物。","pinyin":"Tā mén xīng qī sì dào dá pèi sòng zhōng xīn， huā le yī tiān de shí jiān wéi kè rén tí gōng shí wù。","meaning":"They arrived at the distribution center on Thursday to spend the day serving food.","meaningThai":"พวกเขามาถึงศูนย์กระจายสินค้าในวันพฤหัสบดีเพื่อใช้เวลาทั้งวันเสิร์ฟอาหาร"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-820","chinese":"培训","pinyin":"péixùn","meaning":"to cultivate; to train; to groom; training","meaningThai":"การฝึกอบรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们考虑在明年缩小培训计划。","pinyin":"Wǒ mén kǎo lǜ zài míng nián suō xiǎo péi xùn jì huá。","meaning":"We are thinking of scaling down our training programmes next year.","meaningThai":"เรากำลังคิดที่จะลดขนาดโปรแกรมการฝึกอบรมของเราในปีหน้า"},{"chinese":"我们将在明年缩小培训计划。","pinyin":"Wǒ mén jiāng zài míng nián suō xiǎo péi xùn jì huá。","meaning":"We are scaling down our training programmes next year.","meaningThai":"เรากำลังลดขนาดโปรแกรมการฝึกอบรมของเราในปีหน้า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-821","chinese":"培养","pinyin":"péiyǎng","meaning":"to cultivate; to breed; to foster; to nurture; to educate; to groom (for a position); education; fostering; culture (biology)","meaningThai":"บำรุง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你可以培养自己有乐观思想的能力。","pinyin":"Nǐ kě yǐ péi yǎng zì jǐ yǒu lè guān sī xiǎng de néng lì。","meaning":"You can train your mind to think positively.","meaningThai":"คุณสามารถฝึกจิตใจให้คิดบวกได้"},{"chinese":"培养良好的学习方法很重要。","pinyin":"Péi yǎng liáng hǎo de xué xí fāng fǎ hěn zhòng yào。","meaning":"It is important to develop good study skills.","meaningThai":"การพัฒนาทักษะการเรียนที่ดีเป็นสิ่งสำคัญ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-822","chinese":"盆","pinyin":"pén","meaning":"basin; flower pot; unit of volume equal to 12 斗 and 8 升, approx 128 liters","meaningThai":"หม้อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她猛地把脸浸入一盆冷水中。","pinyin":"Tā měng dì bǎ liǎn jìn rù yī pén lěng shuǐ zhōng。","meaning":"She plunged her face into a bowl of cold water.","meaningThai":"เธอกระโจนหน้าของเธอลงในชามน้ำเย็น"},{"chinese":"水滴入房间后面的一个盆里。","pinyin":"Shuǐ dī rù fáng jiān hòu miàn de yī gè pén lǐ。","meaning":"Water dripped into a basin at the back of the room.","meaningThai":"น้ำหยดลงอ่างหลังห้อง"}],"partOfSpeech":["noun","measure word"]},
  {"id":"hsk5-823","chinese":"碰","pinyin":"pèng","meaning":"variant of 碰","meaningThai":"ชน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我不准任何人碰那台钟。","pinyin":"Wǒ bù zhǔn rèn hé rén pèng nà tái zhōng。","meaning":"I forbid anyone to touch that clock.","meaningThai":"ฉันห้ามใครแตะนาฬิกานั้น"},{"chinese":"别碰那个盘子，烫手！","pinyin":"Bié pèng nà gè pán zǐ， tàng shǒu！","meaning":"Don't touch that plate—it's hot!","meaningThai":"อย่าแตะจานนั้นนะ มันร้อน!"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-824","chinese":"碰见","pinyin":"pèngjiàn","meaning":"to run into; to meet (unexpectedly); to bump into","meaningThai":"พบปะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"说来也巧，昨天我刚碰见了她。","pinyin":"Shuō lái yě qiǎo， zuó tiān wǒ gāng pèng jiàn le tā。","meaning":"Funnily enough, I met her only yesterday.","meaningThai":"น่าตลกดีที่ฉันพบเธอเมื่อวานนี้เท่านั้น"},{"chinese":"你在城里碰见什么人了吗？","pinyin":"Nǐ zài chéng lǐ pèng jiàn shí mó rén le ma？","meaning":"Did you meet anyone in town?","meaningThai":"คุณเจอใครในเมืองบ้างไหม?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-825","chinese":"匹","pinyin":"pǐ","meaning":"mate; one of a pair","meaningThai":"จับคู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那匹马去了哪里？","pinyin":"Nà pǐ mǎ qù le nǎ lǐ？","meaning":"Where did the horse go?","meaningThai":"ม้าไปไหน?"},{"chinese":"我拥有一匹马。","pinyin":"Wǒ yōng yǒu yī pǐ mǎ。","meaning":"I own a horse.","meaningThai":"ฉันเป็นเจ้าของม้า"}],"partOfSpeech":["measure word","other"]},
  {"id":"hsk5-826","chinese":"批","pinyin":"pī","meaning":"to ascertain; to act on; to criticize; to pass on; classifier for batches, lots, military flights; tier (for the ranking of universities and colleges)","meaningThai":"แบทช์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我烤了一批小甜饼。","pinyin":"Wǒ kǎo le yī pī xiǎo tián bǐng。","meaning":"I baked a batch of cookies.","meaningThai":"ฉันอบคุกกี้เป็นชุด"},{"chinese":"她带来一大批剪报。","pinyin":"Tā dài lái yī dà pī jiǎn bào。","meaning":"She brought a large batch of newspaper clippings.","meaningThai":"เธอนำหนังสือพิมพ์จำนวนมากมาด้วย"}],"partOfSpeech":["measure word","verb"]},
  {"id":"hsk5-828","chinese":"骗","pinyin":"piàn","meaning":"to cheat; to swindle; to deceive; to get on (a horse etc) by swinging one leg over","meaningThai":"โกง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你骗不了他，他脑筋一向很快。","pinyin":"Nǐ piàn bù le tā， tā nǎo jīn yī xiàng hěn kuài。","meaning":"You can't fool him— he's always quick on the draw.","meaningThai":"คุณไม่สามารถหลอกเขาได้—เขาจะจับฉลากเร็วเสมอ"},{"chinese":"她受了骗，怒不可遏。","pinyin":"Tā shòu le piàn， nù bù kě è。","meaning":"She was absolutely furious at having been deceived.","meaningThai":"เธอโกรธมากที่ถูกหลอก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-829","chinese":"品","pinyin":"pǐn","meaning":"(bound form) article; commodity; product; goods; (bound form) grade; rank; kind; type; variety; character; disposition; nature; temperament; to taste sth; to sample; to criticize; to comment; to judge; to size up; fret (on a guitar or lute)","meaningThai":"รสชาติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"甜品吃厌了吗？","pinyin":"Tián pǐn chī yàn le ma？","meaning":"Are you fed up of desserts?","meaningThai":"คุณเบื่อของหวานหรือเปล่า?"},{"chinese":"请勿触碰展品。","pinyin":"Qǐng wù chù pèng zhǎn pǐn。","meaning":"Do not touch the exhibits. / Don't touch the exhibits.","meaningThai":"ห้ามสัมผัสสิ่งของจัดแสดง / ห้ามสัมผัสสิ่งจัดแสดง"}],"partOfSpeech":["other","verb"]},
  {"id":"hsk5-830","chinese":"拼","pinyin":"pīn","meaning":"to piece together; to join together; to stake all; adventurous; at the risk of one's life; to spell","meaningThai":"สะกด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你能不能把那个名字再拼一次？","pinyin":"Nǐ néng bù néng bǎ nà gè míng zì zài pīn yī cì？","meaning":"Could you spell that name out again?","meaningThai":"คุณช่วยสะกดชื่อนั้นอีกครั้งได้ไหม?"},{"chinese":"你的名字拼正确了吗？","pinyin":"Nǐ de míng zì pīn zhèng què le ma？","meaning":"Is your name spelled correctly?","meaningThai":"ชื่อของคุณสะกดถูกต้องหรือไม่?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-831","chinese":"平","pinyin":"píng","meaning":"surname Ping","meaningThai":"แบน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人们曾经认为地球是平的。","pinyin":"Rén mén zēng jīng rèn wéi dì qiú shì píng de。","meaning":"People used to think the earth was flat.","meaningThai":"คนเคยคิดว่าโลกแบน"},{"chinese":"他接过信，在桌上展平。","pinyin":"Tā jiē guò xìn， zài zhuō shàng zhǎn píng。","meaning":"He took the letter and smoothed it flat on the table.","meaningThai":"เขาหยิบจดหมายมาวางให้เรียบบนโต๊ะ"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-832","chinese":"评","pinyin":"píng","meaning":"to discuss; to comment; to criticize; to judge; to choose (by public appraisal)","meaningThai":"ความคิดเห็น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该剧获得了许多热评。","pinyin":"Gāi jù huò dé le xǔ duō rè píng。","meaning":"The play received rave reviews.","meaningThai":"ละครเรื่องนี้ได้รับการวิจารณ์อย่างล้นหลาม"},{"chinese":"总共有百分之几的恶评是由父母提出的？","pinyin":"Zǒng gòng yǒu bǎi fēn zhī jī de è píng shì yóu fù mǔ tí chū de？","meaning":"What percent of the bad comments were made by parents in total?","meaningThai":"ผู้ปกครองแสดงความคิดเห็นที่ไม่ดีทั้งหมดกี่เปอร์เซ็นต์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-833","chinese":"凭","pinyin":"píng","meaning":"variant of 凭","meaningThai":"โดย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"花儿不仅凭外观也凭香味而被选中。","pinyin":"Huā ér bù jǐn píng wài guān yě píng xiāng wèi ér bèi xuǎn zhōng。","meaning":"Flowers are chosen for their scent as well as their look.","meaningThai":"ดอกไม้ถูกเลือกเพราะกลิ่นและรูปลักษณ์"},{"chinese":"他凭自己的意志顶住了这一诱惑。","pinyin":"Tā píng zì jǐ de yì zhì dǐng zhù le zhè yī yòu huò。","meaning":"With an effort of will he resisted the temptation.","meaningThai":"ด้วยความพยายามที่เขาจะต่อต้านสิ่งล่อใจ"}],"partOfSpeech":["preposition","verb"]},
  {"id":"hsk5-834","chinese":"平安","pinyin":"píng'ān","meaning":"safe and sound; well; without mishap; quiet and safe; at peace","meaningThai":"ความปลอดภัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们祈求上苍保佑他们平安归来。","pinyin":"Wǒ mén qí qiú shàng cāng bǎo yòu tā mén píng ān guī lái。","meaning":"We offered up our prayers for the men's safe return.","meaningThai":"เราอธิษฐานขอให้พวกผู้ชายกลับมาอย่างปลอดภัย"},{"chinese":"愿我们大家都欢乐平安。","pinyin":"Yuàn wǒ mén dà jiā dū huān lè píng ān。","meaning":"May joy and peace abide in us all.","meaningThai":"ขอให้ความสุขและสันติสุขดำรงอยู่ในเราทุกคน"}],"partOfSpeech":["adjective","noun"]},
  {"id":"hsk5-835","chinese":"平衡","pinyin":"pínghéng","meaning":"balance; equilibrium","meaningThai":"สมดุล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"保持平衡。","pinyin":"Bao chi ping heng.","meaning":"Maintain balance.","meaningThai":"รักษาสมดุล"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-836","chinese":"评价","pinyin":"píngjià","meaning":"to evaluate; to assess","meaningThai":"ประเมิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"应由警方来评价证据的有效与否。","pinyin":"Yīng yóu jǐng fāng lái píng jià zhèng jù de yǒu xiào yǔ fǒu。","meaning":"It was for the police to assess the validity or otherwise of the evidence.","meaningThai":"เป็นหน้าที่ของตำรวจในการประเมินความถูกต้องหรือหลักฐานอื่นๆ"},{"chinese":"事后明白了再评价，这自然容易。","pinyin":"Shì hòu míng bái le zài píng jià， zhè zì rán róng yì。","meaning":"It's easy to criticize with the benefit of hindsight.","meaningThai":"การวิพากษ์วิจารณ์เป็นเรื่องง่ายโดยอาศัยการเข้าใจถึงปัญหาหลังเหตุการณ์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-837","chinese":"凭借","pinyin":"píngjiè","meaning":"to rely on; to depend on; by means of; thanks to; sth that one relies on","meaningThai":"โดยอาศัยอำนาจตาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他凭借最新的一部小说叩开了成功之门。","pinyin":"Tā píng jiè zuì xīn de yī bù xiǎo shuō kòu kāi le chéng gōng zhī mén。","meaning":"He has struck gold with his latest novel.","meaningThai":"เขาตีทองด้วยนวนิยายเรื่องล่าสุดของเขา"},{"chinese":"霍华德·霍克斯凭借影片《赤胆屠龙》一夜成名。","pinyin":"Huò huá dé · huò kè sī píng jiè yǐng piàn 《 chì dǎn tú lóng 》 yī yè chéng míng。","meaning":"Howard Hawks hit paydirt with \"Rio Bravo.\"","meaningThai":"Howard Hawks ทุบสถิติ \"Rio Bravo\""}],"partOfSpeech":["preposition"]},
  {"id":"hsk5-838","chinese":"平静","pinyin":"píngjìng","meaning":"tranquil; undisturbed; serene","meaningThai":"เงียบสงบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"市场本周在平静气氛中收市。","pinyin":"Shì cháng běn zhōu zài píng jìng qì fēn zhōng shōu shì。","meaning":"The markets ended the week on a quiet note.","meaningThai":"ตลาดสิ้นสุดสัปดาห์ด้วยความเงียบสงบ"},{"chinese":"我当时出奇地轻松和平静。","pinyin":"Wǒ dāng shí chū qí dì qīng sōng hé píng jìng。","meaning":"I was amazingly light-hearted and peaceful.","meaningThai":"ฉันเป็นคนจิตใจเบิกบานและสงบอย่างน่าอัศจรรย์"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-839","chinese":"平均","pinyin":"píngjūn","meaning":"average; on average; evenly; in equal proportions","meaningThai":"เฉลี่ย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她低于平均身高，娇小且苗条。","pinyin":"Tā dī yú píng jūn shēn gāo， jiāo xiǎo qiě miáo tiáo。","meaning":"She was of below average height, petite and slender.","meaningThai":"เธอมีส่วนสูงต่ำกว่าค่าเฉลี่ย มีรูปร่างเล็กและเรียวยาว"},{"chinese":"明年经济增长预计平均可达2%。","pinyin":"Míng nián jīng jì zēng cháng yù jì píng jūn kě dá2%。","meaning":"Economic growth is expected to average 2% next year.","meaningThai":"คาดเศรษฐกิจเติบโตเฉลี่ย 2% ในปีหน้า"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-840","chinese":"屏幕","pinyin":"píngmù","meaning":"screen (TV, computer or movie)","meaningThai":"หน้าจอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"电脑屏幕显示出到达和离开的时间。","pinyin":"Diàn nǎo píng mù xiǎn shì chū dào dá hé lí kāi de shí jiān。","meaning":"A computer screen shows arrival and departure times.","meaningThai":"หน้าจอคอมพิวเตอร์แสดงเวลามาถึงและออกเดินทาง"},{"chinese":"计算机屏幕应该与眼睛齐平。","pinyin":"Jì suàn jī píng mù yīng gāi yǔ yǎn jīng qí píng。","meaning":"Computer screens should be at eye level.","meaningThai":"หน้าจอคอมพิวเตอร์ควรอยู่ในระดับสายตา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-841","chinese":"平台","pinyin":"píngtái","meaning":"platform; terrace; flat-roofed building","meaningThai":"แพลตฟอร์ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"网络平台。","pinyin":"Wang luo ping tai.","meaning":"Online platform.","meaningThai":"แพลตฟอร์มออนไลน์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-842","chinese":"品牌","pinyin":"pǐnpái","meaning":"brand name; trademark","meaningThai":"แบรนด์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个品牌很有名。","pinyin":"Zhè ge pǐn pái hěn yǒu míng.","meaning":"This brand is very famous.","meaningThai":"แบรนด์นี้ดังมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-843","chinese":"聘请","pinyin":"pìnqǐng","meaning":"to engage; to hire (a lawyer etc)","meaningThai":"จ้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他已聘请一位律师为他所受的指控辩护。","pinyin":"Tā yǐ pìn qǐng yī wèi lǜ shī wéi tā suǒ shòu de zhǐ kòng biàn hù。","meaning":"He has hired a lawyer to defend him against the allegation.","meaningThai":"เขาได้จ้างทนายความเพื่อแก้ต่างข้อกล่าวหาดังกล่าว"},{"chinese":"他们聘请了一位最好的律师帮他们陈述案情。","pinyin":"Tā mén pìn qǐng le yī wèi zuì hǎo de lǜ shī bāng tā mén chén shù àn qíng。","meaning":"They hired a top lawyer to plead their case.","meaningThai":"พวกเขาจ้างทนายความชั้นนำเพื่อดำเนินคดี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-844","chinese":"拼音","pinyin":"pīnyīn","meaning":"Pinyin","meaningThai":"พินอิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"汤姆的拼音课本就在他眼前。","pinyin":"Tāng mǔ de pīn yīn kè běn jiù zài tā yǎn qián。","meaning":"Tom's spelling-book fell under his eye.","meaningThai":"หนังสือสะกดคำของทอมตกอยู่ใต้ดวงตาของเขา"},{"chinese":"1958年，中国语言学家周有光和他的团队设计了拼音。","pinyin":"1958 nián， zhōng guó yǔ yán xué jiā zhōu yǒu guāng hé tā de tuán duì shè jì le pīn yīn。","meaning":"In 1958, pinyin was designed by Chinese linguist Zhou Youguang and his team.","meaningThai":"ในปีพ.ศ. 2501 พินอินได้รับการออกแบบโดยนักภาษาศาสตร์ชาวจีน โจว โหยวกวง และทีมงานของเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-845","chinese":"品质","pinyin":"pǐnzhì","meaning":"character; intrinsic quality (of a person); quality (of a product or service, or as in \"quality of life\", \"air quality\" etc)","meaningThai":"คุณภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"其书籍以纸张和封面的品质而著称。","pinyin":"Qí shū jí yǐ zhǐ zhāng hé fēng miàn de pǐn zhì ér zhù chēng。","meaning":"Its books are noted for the quality of their paper and bindings.","meaningThai":"หนังสือของบริษัทขึ้นชื่อเรื่องคุณภาพของกระดาษและการเข้าเล่ม"},{"chinese":"这是高品质的东西。","pinyin":"Zhè shì gāo pǐn zhì de dōng xī。","meaning":"This is high quality stuff.","meaningThai":"นี่คือสิ่งที่มีคุณภาพสูง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-846","chinese":"品种","pinyin":"pǐnzhǒng","meaning":"breed; variety","meaningThai":"พันธุ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个品种很稀有。","pinyin":"Zhe ge pin zhong hen xi you.","meaning":"This variety is very rare.","meaningThai":"พันธุ์นี้หายากมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-847","chinese":"批准","pinyin":"pīzhǔn","meaning":"to approve; to ratify","meaningThai":"อนุมัติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这项计划获得无条件批准。","pinyin":"Zhè xiàng jì huá huò dé wú tiáo jiàn pī zhǔn。","meaning":"The plan was approved without qualification.","meaningThai":"แผนดังกล่าวได้รับการอนุมัติโดยไม่มีคุณสมบัติ"},{"chinese":"国务卿有权批准这些提议。","pinyin":"Guó wù qīng yǒu quán pī zhǔn zhè xiē tí yì。","meaning":"The Secretary of State has the power to approve the proposals.","meaningThai":"เลขาธิการแห่งรัฐมีอำนาจอนุมัติข้อเสนอได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-848","chinese":"破坏","pinyin":"pòhuài","meaning":"destruction; damage; to wreck; to break; to destroy","meaningThai":"ทำลาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"天气恶劣，破坏了我们的旅行。","pinyin":"Tiān qì è liè， pò huài le wǒ mén de lǚ háng。","meaning":"The bad weather ruined our trip.","meaningThai":"สภาพอากาศเลวร้ายทำให้การเดินทางของเราเสียหาย"},{"chinese":"这是无端的、愚蠢的恶意破坏。","pinyin":"Zhè shì wú duān de、 yú chǔn de è yì pò huài。","meaning":"It was wanton, moronic vandalism.","meaningThai":"มันเป็นการป่าเถื่อนที่ป่าเถื่อนและศีลธรรม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-849","chinese":"普及","pinyin":"pǔjí","meaning":"to spread extensively; to generalize; widespread; popular; universal; ubiquitous; pervasive","meaningThai":"สากล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他毕生致力于普及博物学。","pinyin":"Tā bì shēng zhì lì yú pǔ jí bó wù xué。","meaning":"He spent his life popularizing natural history.","meaningThai":"เขาใช้ชีวิตของเขาในการเผยแพร่ประวัติศาสตร์ธรรมชาติ"},{"chinese":"该项运动普及程度的大幅提高带来了更多要求更严格安全法规的呼声。","pinyin":"Gāi xiàng yùn dòng pǔ jí chéng dù de dà fú tí gāo dài lái le gēng duō yào qiú gēng yán gé ān quán fǎ guī de hū shēng。","meaning":"The boom in the sport's popularity has meant more calls for stricter safety regulations.","meaningThai":"ความนิยมในกีฬาชนิดนี้เพิ่มขึ้นส่งผลให้มีการเรียกร้องให้มีกฎระเบียบด้านความปลอดภัยที่เข้มงวดมากขึ้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-850","chinese":"齐","pinyin":"qí","meaning":"(name of states and dynasties at several different periods); surname Qi","meaningThai":"ด้วยกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“当心，帕齐，”警官提醒她说。","pinyin":"“ dāng xīn， pà qí，” jǐng guān tí xǐng tā shuō。","meaning":"\"Now watch it, Patsy,\" the sergeant told her.","meaningThai":"“ลองดูสิ แพตซี่” จ่าสิบเอกบอกเธอ"},{"chinese":"这房间安排得整整齐齐。","pinyin":"Zhè fáng jiān ān pái dé zhěng zhěng qí qí。","meaning":"The room was very tidily arranged.","meaningThai":"ห้องถูกจัดเป็นระเบียบเรียบร้อยมาก"}],"partOfSpeech":["adjective","adverb","verb","noun"]},
  {"id":"hsk5-851","chinese":"其","pinyin":"qí","meaning":"his; her; its; their; that; such; it (refers to sth preceding it)","meaningThai":"ที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些系统各有其优缺点。","pinyin":"Zhè xiē xì tǒng gè yǒu qí yōu quē diǎn。","meaning":"Each of these systems has its advantages and disadvantages.","meaningThai":"แต่ละระบบเหล่านี้มีข้อดีและข้อเสียของตัวเอง"},{"chinese":"银行宣布了其投标意向。","pinyin":"Yín háng xuān bù le qí tóu biāo yì xiàng。","meaning":"The bank announced its intention to bid.","meaningThai":"ธนาคารได้ประกาศเจตนารมณ์ในการประมูล"}],"partOfSpeech":["pronoun","particle"]},
  {"id":"hsk5-852","chinese":"欠","pinyin":"qiàn","meaning":"to owe; to lack; (literary) to be deficient in; (bound form) yawn; to raise slightly (a part of one's body)","meaningThai":"เป็นหนี้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"还有件小事儿，你欠我五十英镑呢。","pinyin":"Huán yǒu jiàn xiǎo shì ér， nǐ qiàn wǒ wǔ shí yīng bàng ne。","meaning":"And then there's the little matter of the fifty pounds you owe me.","meaningThai":"แล้วยังมีเรื่องเล็กน้อยจากเงินห้าสิบปอนด์ที่คุณเป็นหนี้ฉันอยู่"},{"chinese":"我完全记不得他欠我的钱了。","pinyin":"Wǒ wán quán jì bù dé tā qiàn wǒ de qián le。","meaning":"I'd completely forgotten about the money he owed me.","meaningThai":"ฉันลืมเงินที่เขาติดค้างฉันไปหมดแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-853","chinese":"浅","pinyin":"qiǎn","meaning":"sound of moving water","meaningThai":"ตื้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"河道变得又窄又浅，无法航行。","pinyin":"Hé dào biàn dé yòu zhǎi yòu qiǎn， wú fǎ háng háng。","meaning":"The river became too narrow and shallow to navigate.","meaningThai":"แม่น้ำแคบและตื้นเกินกว่าจะเดินเรือได้"},{"chinese":"沙发的颜色再浅一点就不那么扎眼了。","pinyin":"Shā fā de yán sè zài qiǎn yī diǎn jiù bù nà mó zā yǎn le。","meaning":"The sofa would be less obtrusive in a paler colour.","meaningThai":"โซฟาจะมีสีซีดจางกว่า"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-854","chinese":"签","pinyin":"qiān","meaning":"to sign one's name; to write brief comments on a document; inscribed bamboo stick (variant of 签); visa","meaningThai":"เข้าสู่ระบบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她对是否签这个合同还犹豫不决。","pinyin":"Tā duì shì fǒu qiān zhè gè hé tóng huán yóu yù bù jué。","meaning":"She's hesitant about signing the contract.","meaningThai":"เธอลังเลเกี่ยวกับการเซ็นสัญญา"},{"chinese":"她比任何人都急着去签那份合同。","pinyin":"Tā bǐ rèn hé rén dū jí zháo qù qiān nà fèn hé tóng。","meaning":"She more than anyone had hastened to sign the contract.","meaningThai":"เธอมากกว่าใครๆ ก็รีบเซ็นสัญญา"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-855","chinese":"签订","pinyin":"qiāndìng","meaning":"to agree to and sign (a treaty etc)","meaningThai":"เข้าสู่ระบบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们即将签订一份新的合同。","pinyin":"Tā mén jí jiāng qiān dìng yī fèn xīn de hé tóng。","meaning":"They are on the verge of signing a new contract.","meaningThai":"พวกเขากำลังจวนจะเซ็นสัญญาฉบับใหม่"},{"chinese":"条约是3月24日签订的。","pinyin":"Tiáo yuē shì 3 yuè 24 rì qiān dìng de。","meaning":"The treaty was signed on 24 March.","meaningThai":"สนธิสัญญาดังกล่าวลงนามเมื่อวันที่ 24 มีนาคม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-856","chinese":"墙","pinyin":"qiáng","meaning":"variant of 墙, wall","meaningThai":"กำแพง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我把钉子钉进墙里。","pinyin":"Wǒ bǎ dīng zǐ dīng jìn qiáng lǐ。","meaning":"I knocked the nail into the wall.","meaningThai":"ฉันตอกตะปูเข้ากับผนัง"},{"chinese":"他转身背对着墙。","pinyin":"Tā zhuǎn shēn bèi duì zháo qiáng。","meaning":"He turned his back to the wall.","meaningThai":"เขาหันหลังให้กำแพง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-857","chinese":"抢","pinyin":"qiǎng","meaning":"(literary) to knock against (esp. to knock one's head on the ground in grief or rage); opposite in direction; contrary","meaningThai":"ปล้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"别抢—多着呢，人人都有。","pinyin":"Bié qiāng — duō zháo ne， rén rén dū yǒu。","meaning":"Don't grab—there's plenty for everyone.","meaningThai":"อย่าคว้า—มีมากมายสำหรับทุกคน"},{"chinese":"他突然去抢她的手提包。","pinyin":"Tā tū rán qù qiāng tā de shǒu tí bāo。","meaning":"He made a grab for her bag.","meaningThai":"เขาคว้ากระเป๋าของเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-858","chinese":"强大","pinyin":"qiángdà","meaning":"large; formidable; powerful; strong","meaningThai":"ทรงพลัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"对于他们来说，他已变得过于强大。","pinyin":"Duì yú tā mén lái shuō， tā yǐ biàn dé guò yú qiáng dà。","meaning":"He had become too powerful for their liking.","meaningThai":"เขามีพลังมากเกินไปสำหรับความชอบของพวกเขา"},{"chinese":"城市对青年人有着强大的吸引力。","pinyin":"Chéng shì duì qīng nián rén yǒu zháo qiáng dà de xī yǐn lì。","meaning":"Cities have a powerful magnetizing effect on young people.","meaningThai":"เมืองต่างๆ มีพลังดึงดูดใจอันทรงพลังต่อคนหนุ่มสาว"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-859","chinese":"强调","pinyin":"qiángdiào","meaning":"to emphasize (a statement); to stress","meaningThai":"เน้นย้ำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她强调了团队合作的重要性。","pinyin":"Tā qiáng tiáo le tuán duì hé zuò de zhòng yào xìng。","meaning":"She stressed the importance of good teamwork.","meaningThai":"เธอเน้นย้ำถึงความสำคัญของการทำงานเป็นทีมที่ดี"},{"chinese":"这位作者强调个人的独特性。","pinyin":"Zhè wèi zuò zhě qiáng tiáo gè rén de dú tè xìng。","meaning":"The author stresses the uniqueness of the individual.","meaningThai":"ผู้เขียนเน้นย้ำถึงเอกลักษณ์ของแต่ละบุคคล"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-860","chinese":"强度","pinyin":"qiángdù","meaning":"strength; intensity","meaningThai":"ความแข็งแกร่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"某些材料可以制造成抗拉伸强度大的产品。","pinyin":"Mǒu xiē cái liào kě yǐ zhì zào chéng kàng lā shēn qiáng dù dà de chǎn pǐn。","meaning":"Certain materials can be manufactured with a high tensile strength.","meaningThai":"วัสดุบางชนิดสามารถผลิตได้ด้วยความต้านทานแรงดึงสูง"},{"chinese":"他检查了缆绳的强度。","pinyin":"Tā jiǎn chá le lǎn shéng de qiáng dù。","meaning":"He checked the strength of the cables.","meaningThai":"เขาตรวจสอบความแข็งแรงของสายเคเบิล"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-861","chinese":"抢救","pinyin":"qiǎngjiù","meaning":"to rescue","meaningThai":"กู้ภัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们在拼命抢救他们仅余的业务。","pinyin":"Tā mén zài pīn mìng qiāng jiù tā mén jǐn yú de yè wù。","meaning":"They are fighting to save what is left of their business.","meaningThai":"พวกเขากำลังต่อสู้เพื่อรักษาสิ่งที่เหลืออยู่ในธุรกิจของพวกเขา"},{"chinese":"火一旦熄灭，抢救队就会进去。","pinyin":"Huǒ yī dàn xī miè， qiāng jiù duì jiù huì jìn qù。","meaning":"Once the fire has died out, the salvage team will move in.","meaningThai":"เมื่อไฟดับแล้ว ทีมกู้ภัยจะย้ายเข้าไป"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-862","chinese":"强烈","pinyin":"qiángliè","meaning":"strong; intense","meaningThai":"แข็งแกร่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人们对这个问题反应强烈。","pinyin":"Rén mén duì zhè gè wèn tí fǎn yīng qiáng liè。","meaning":"People have strong feelings about this issue.","meaningThai":"ผู้คนมีความรู้สึกอย่างมากเกี่ยวกับปัญหานี้"},{"chinese":"代表强烈反对这些计划。","pinyin":"Dài biǎo qiáng liè fǎn duì zhè xiē jì huá。","meaning":"Delegates expressed strong opposition to the plans.","meaningThai":"ผู้ได้รับมอบหมายแสดงความขัดแย้งอย่างรุนแรงต่อแผนดังกล่าว"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-863","chinese":"前进","pinyin":"qiánjìn","meaning":"to go forward; to forge ahead; to advance; onward","meaningThai":"ไปข้างหน้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"部队终于得到前进的命令。","pinyin":"Bù duì zhōng yú dé dào qián jìn de mìng líng。","meaning":"The troops were finally given the order to advance.","meaningThai":"ในที่สุดกองทัพก็ได้รับคำสั่งให้รุกคืบ"},{"chinese":"黑泥阻止她前进。","pinyin":"Hēi ní zǔ zhǐ tā qián jìn。","meaning":"The black mud fettered her movements.","meaningThai":"โคลนสีดำกีดขวางการเคลื่อนไหวของเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-864","chinese":"前来","pinyin":"qiánlái","meaning":"to come (formal); before; previously","meaningThai":"มา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"所有老朋友都前来参加了这次活动。","pinyin":"Suǒ yǒu lǎo péng yǒu dū qián lái cān jiā le zhè cì huó dòng。","meaning":"All the old crowd have come out for this occasion.","meaningThai":"ฝูงชนเก่าทั้งหมดออกมาเพื่อโอกาสนี้"},{"chinese":"佩内洛普走上前来拥抱了她的妹妹。","pinyin":"Pèi nèi luò pǔ zǒu shàng qián lái yōng bào le tā de mèi mèi。","meaning":"Penelope came forward and embraced her sister.","meaningThai":"เพเนโลพีเดินเข้ามากอดน้องสาวของเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-865","chinese":"签名","pinyin":"qiānmíng","meaning":"to sign (one's name with a pen etc); to autograph; signature","meaningThai":"เข้าสู่ระบบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有人在支票上伪造了她的签名。","pinyin":"Yǒu rén zài zhī piào shàng wěi zào le tā de qiān míng。","meaning":"Someone had forged her signature on the cheque.","meaningThai":"มีคนปลอมลายเซ็นของเธอบนเช็ค"},{"chinese":"两个签名的相似之处非常明显。","pinyin":"Liǎng gè qiān míng de xiāng sì zhī chǔ fēi cháng míng xiǎn。","meaning":"The resemblance between the two signatures was remarkable.","meaningThai":"ความคล้ายคลึงกันระหว่างลายเซ็นทั้งสองนั้นน่าทึ่งมาก"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-866","chinese":"前途","pinyin":"qiántú","meaning":"prospects; future outlook; journey","meaningThai":"อนาคต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"突然感到前途似乎并非如此黯淡。","pinyin":"Tū rán gǎn dào qián tú sì hū bìng fēi rú cǐ àn dàn。","meaning":"Suddenly, the future didn't look so gloomy after all.","meaningThai":"ทันใดนั้น อนาคตก็ไม่ได้ดูมืดมนนัก"},{"chinese":"他在队中的前途还是个大问号。","pinyin":"Tā zài duì zhōng de qián tú huán shì gè dà wèn hào。","meaning":"There's still a big question mark hanging over his future with the team.","meaningThai":"ยังคงมีเครื่องหมายคำถามใหญ่แขวนอยู่เกี่ยวกับอนาคตของเขากับทีม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-867","chinese":"前往","pinyin":"qiánwǎng","meaning":"to leave for; to proceed towards; to go to","meaningThai":"ไปที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们正前往德国边界。","pinyin":"Tā mén zhèng qián wǎng dé guó biān jiè。","meaning":"They were heading towards the German border.","meaningThai":"พวกเขากำลังมุ่งหน้าไปยังชายแดนเยอรมัน"},{"chinese":"我们驱车前往海滨。","pinyin":"Wǒ mén qū chē qián wǎng hǎi bīn。","meaning":"We drove onwards towards the coast.","meaningThai":"เราขับต่อไปมุ่งหน้าสู่ชายฝั่ง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-868","chinese":"签字","pinyin":"qiānzì","meaning":"to sign (one's name); signature","meaningThai":"ลายเซ็น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她伪造了她母亲在文件上的签字。","pinyin":"Tā wěi zào le tā mǔ qīn zài wén jiàn shàng de qiān zì。","meaning":"She faked her mother's signature on the document.","meaningThai":"เธอปลอมลายเซ็นแม่ของเธอในเอกสาร"},{"chinese":"仔细阅读保险单的条款后再签字。","pinyin":"Zī xì yuè dú bǎo xiǎn dān de tiáo kuǎn hòu zài qiān zì。","meaning":"Check the terms of the policy before you sign.","meaningThai":"ตรวจสอบเงื่อนไขของกรมธรรม์ก่อนลงนาม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-869","chinese":"悄悄","pinyin":"qiāoqiāo","meaning":"quiet; making little or no noise; surreptitious; stealthy; anxious; worried; Taiwan pr. [qiǎo qiǎo]","meaningThai":"อย่างเงียบ ๆ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们悄悄说话，以免惊醒警卫。","pinyin":"Wǒ mén qiǎo qiǎo shuō huà， yǐ miǎn jīng xǐng jǐng wèi。","meaning":"We spoke quietly for fear of waking the guards.","meaningThai":"เราพูดกันเบาๆเพราะกลัวเจ้าหน้าที่ตื่น"},{"chinese":"他静悄悄地坐在那儿。","pinyin":"Tā jìng qiǎo qiǎo dì zuò zài nà ér。","meaning":"He sat there ever so quietly.","meaningThai":"เขานั่งอยู่ที่นั่นอย่างเงียบ ๆ เสมอ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-870","chinese":"期待","pinyin":"qīdài","meaning":"to look forward to; to await; expectation","meaningThai":"คาดหวัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他期待选举在11月左右举行。","pinyin":"Tā qī dài xuǎn jǔ zài 11 yuè zuǒ yòu jǔ háng。","meaning":"He expects the elections to be held around November.","meaningThai":"เขาคาดว่าการเลือกตั้งจะมีขึ้นประมาณเดือนพฤศจิกายน"},{"chinese":"我申请这个职位是希望多于期待。","pinyin":"Wǒ shēn qǐng zhè gè zhí wèi shì xī wàng duō yú qī dài。","meaning":"I applied for the post more in hope than expectation.","meaningThai":"ฉันสมัครโพสต์ด้วยความหวังมากกว่าความคาดหมาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-871","chinese":"切","pinyin":"qiē","meaning":"to cut; to slice; to carve; (math) tangential","meaningThai":"ตัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的事业是她生活中一切的一切。","pinyin":"Tā de shì yè shì tā shēng huó zhōng yī qiē de yī qiē。","meaning":"Her career is the be-all and end-all of her existence.","meaningThai":"อาชีพการงานของเธอคือจุดสิ้นสุดของการดำรงอยู่ของเธอ"},{"chinese":"安德鲁动手切鸡肉。","pinyin":"Ān dé lǔ dòng shǒu qiē jī ròu。","meaning":"Andrew began to carve the chicken.","meaningThai":"แอนดรูว์เริ่มแกะไก่"}],"partOfSpeech":["verb","adverb","other"]},
  {"id":"hsk5-872","chinese":"奇迹","pinyin":"qíjì","meaning":"miracle; miraculous; wonder; marvel","meaningThai":"ปาฏิหาริย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"创造奇迹。","pinyin":"Chuang zao qi ji.","meaning":"Create a miracle.","meaningThai":"สร้างปาฏิหาริย์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-873","chinese":"期间","pinyin":"qījiān","meaning":"period of time; time; time period; period","meaningThai":"ระยะเวลา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"审判期间，犯人戴着镣铐。","pinyin":"Shěn pàn qī jiān， fàn rén dài zháo liào kào。","meaning":"The prisoners were kept shackled during the trial.","meaningThai":"นักโทษถูกใส่กุญแจมือในระหว่างการพิจารณาคดี"},{"chinese":"审讯期间他吃尽了苦头。","pinyin":"Shěn xùn qī jiān tā chī jìn le kǔ tóu。","meaning":"He went through hell during the trial.","meaningThai":"เขาตกนรกในระหว่างการพิจารณาคดี"}],"partOfSpeech":["other"]},
  {"id":"hsk5-874","chinese":"亲","pinyin":"qīn","meaning":"parent; one's own (flesh and blood); relative; related; marriage; bride; close; intimate; in person; first-hand; in favor of; pro-; to kiss; (Internet slang) dear","meaningThai":"ญาติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"年轻选民是坚定的亲欧派。","pinyin":"Nián qīng xuǎn mín shì jiān dìng de qīn ōu pài。","meaning":"Younger voters are strongly pro-European.","meaningThai":"ผู้มีสิทธิเลือกตั้งที่อายุน้อยกว่านั้นสนับสนุนชาวยุโรปอย่างยิ่ง"},{"chinese":"奥谢家的姑娘们和我们家沾点儿亲。","pinyin":"Ào xiè jiā de gū niáng mén hé wǒ mén jiā zhān diǎn ér qīn。","meaning":"The O'Shea girls are distantly related to our family.","meaningThai":"สาวๆ O'Shea มีความเกี่ยวข้องกับครอบครัวของเราอย่างห่างไกล"}],"partOfSpeech":["verb","adjective","other"]},
  {"id":"hsk5-875","chinese":"亲爱","pinyin":"qīn'ài","meaning":"dear; beloved; darling","meaningThai":"ที่รัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我亲爱的姑娘，你错了。","pinyin":"Wǒ qīn ài de gū niáng， nǐ cuò le。","meaning":"My dear girl, you're wrong.","meaningThai":"ที่รักของฉัน คุณคิดผิดแล้ว"},{"chinese":"亲爱的父亲，我想念您。","pinyin":"Qīn ài de fù qīn， wǒ xiǎng niàn nín。","meaning":"I miss thee, beloved father.","meaningThai":"ฉันคิดถึงคุณพ่อที่รัก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-876","chinese":"勤奋","pinyin":"qínfèn","meaning":"hardworking; diligent","meaningThai":"ขยัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"要想生意兴旺，勤奋工作是关键。","pinyin":"Yào xiǎng shēng yì xīng wàng， qín fèn gōng zuò shì guān jiàn。","meaning":"Hard work is the name of the game if you want to succeed in business.","meaningThai":"การทำงานหนักเป็นชื่อของเกมหากคุณต้องการประสบความสำเร็จในธุรกิจ"},{"chinese":"她工作勤奋，不久就得到提升了。","pinyin":"Tā gōng zuò qín fèn， bù jiǔ jiù dé dào tí shēng le。","meaning":"She worked hard and was soon promoted.","meaningThai":"เธอทำงานหนักและไม่นานก็ได้รับการเลื่อนตำแหน่ง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-877","chinese":"青","pinyin":"qīng","meaning":"abbr. for 海, Qinghai Province","meaningThai":"สีเขียว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你能吃出菜里有青辣椒的味道，但它有点甜。","pinyin":"Nǐ néng chī chū cài lǐ yǒu qīng là jiāo de wèi dào， dàn tā yǒu diǎn tián。","meaning":"You can taste the green chilli in the dish but it is a little sweet.","meaningThai":"คุณสามารถลิ้มรสพริกเขียวในจานได้ แต่มีรสหวานเล็กน้อย"},{"chinese":"果子还青，吃起来很酸。","pinyin":"Guǒ zǐ huán qīng， chī qǐ lái hěn suān。","meaning":"The fruit is still green and eats sour.","meaningThai":"ผลยังคงเป็นสีเขียวและกินรสเปรี้ยว"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-878","chinese":"情感","pinyin":"qínggǎn","meaning":"feeling; emotion; to move (emotionally)","meaningThai":"อารมณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"经济原因的常常伴有情感原因。","pinyin":"Jīng jì yuán yīn de cháng cháng bàn yǒu qíng gǎn yuán yīn。","meaning":"Often there are emotional reasons paralleling the financial ones.","meaningThai":"บ่อยครั้งมีเหตุผลทางอารมณ์ควบคู่ไปกับเหตุผลทางการเงิน"},{"chinese":"她被自我怀疑和情感不安所困扰。","pinyin":"Tā bèi zì wǒ huái yí hé qíng gǎn bù ān suǒ kùn rǎo。","meaning":"She is assailed by self-doubt and emotional insecurity.","meaningThai":"เธอถูกโจมตีด้วยความสงสัยในตนเองและความไม่มั่นคงทางอารมณ์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-879","chinese":"请教","pinyin":"qǐngjiào","meaning":"to ask for guidance; to consult","meaningThai":"ปรึกษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他不屑于向自己的儿子请教。","pinyin":"Tā bù xiè yú xiàng zì jǐ de ér zǐ qǐng jiào。","meaning":"He disdained to turn to his son for advice.","meaningThai":"เขารังเกียจที่จะหันไปขอคำแนะนำจากลูกชาย"},{"chinese":"我想请教，你在用英语写作时，如何才能把自己的想法表达清楚。","pinyin":"Wǒ xiǎng qǐng jiào， nǐ zài yòng yīng yǔ xiě zuò shí， rú hé cái néng bǎ zì jǐ de xiǎng fǎ biǎo dá qīng chǔ。","meaning":"I'd like to ask you how can I make myself clear when writing in English.","meaningThai":"ฉันอยากจะถามคุณว่าฉันจะทำให้ตัวเองชัดเจนเมื่อเขียนเป็นภาษาอังกฤษได้อย่างไร"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-880","chinese":"情景","pinyin":"qíngjǐng","meaning":"scene; spectacle; circumstances; situation","meaningThai":"ฉาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们没有看出这情景的滑稽之处。","pinyin":"Tā mén méi yǒu kàn chū zhè qíng jǐng de huá jī zhī chǔ。","meaning":"They failed to see the humour of the situation.","meaningThai":"พวกเขามองไม่เห็นอารมณ์ขันของสถานการณ์"},{"chinese":"那种新奇的情景激起了他的好奇心。","pinyin":"Nà zhǒng xīn qí de qíng jǐng jī qǐ le tā de hǎo qí xīn。","meaning":"The novelty of the situation intrigued him.","meaningThai":"ความแปลกใหม่ของสถานการณ์ทำให้เขาทึ่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-881","chinese":"请求","pinyin":"qǐngqiú","meaning":"to request; to ask; request","meaningThai":"ถาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们将不再请求帮助。","pinyin":"Wǒ mén jiāng bù zài qǐng qiú bāng zhù。","meaning":"We are not going to beg for help anymore.","meaningThai":"เราจะไม่ขอความช่วยเหลืออีกต่อไป"},{"chinese":"她本应该请求帮助的。","pinyin":"Tā běn yīng gāi qǐng qiú bāng zhù de。","meaning":"She should have asked for some help.","meaningThai":"เธอควรจะขอความช่วยเหลือสักหน่อย"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-882","chinese":"情绪","pinyin":"qíngxù","meaning":"mood; state of mind; moodiness","meaningThai":"อารมณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他情绪不太好。","pinyin":"Ta qing xu bu tai hao.","meaning":"He is not in a good mood.","meaningThai":"เขาอารมณ์ไม่ดี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-883","chinese":"轻易","pinyin":"qīngyì","meaning":"easily; lightly; rashly","meaningThai":"อย่างง่ายดาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我气我自己那么轻易就让步了。","pinyin":"Wǒ qì wǒ zì jǐ nà mó qīng yì jiù ràng bù le。","meaning":"I was annoyed with myself for giving in so easily.","meaningThai":"ฉันรำคาญตัวเองที่ยอมแพ้ง่ายๆ"},{"chinese":"他并没有轻易让我离开。","pinyin":"Tā bìng méi yǒu qīng yì ràng wǒ lí kāi。","meaning":"He didn't make it easy for me to leave.","meaningThai":"เขาไม่ได้ทำให้ฉันต้องจากไปง่ายๆ"}],"partOfSpeech":["adverb","adjective"]},
  {"id":"hsk5-884","chinese":"轻重","pinyin":"qīngzhòng","meaning":"severity","meaningThai":"ความรุนแรง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"参议员克里在华盛顿举足轻重。","pinyin":"Cān yì yuán kè lǐ zài huá shèng dùn jǔ zú qīng zhòng。","meaning":"Senator Kerry carries considerable weight in Washington.","meaningThai":"วุฒิสมาชิกเคอร์รีมีน้ำหนักมากในวอชิงตัน"},{"chinese":"刑期长短要和罪行轻重一致。","pinyin":"Xíng qī cháng duǎn yào hé zuì háng qīng zhòng yī zhì。","meaning":"A prison sentence should match the severity of the crime.","meaningThai":"โทษจำคุกควรสอดคล้องกับความรุนแรงของอาชญากรรม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-885","chinese":"亲朋好友","pinyin":"qīnpéng-hǎoyǒu","meaning":"friends and family; kith and kin","meaningThai":"เพื่อนและญาติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"它没有展示疫情从我们身上夺走了什么，而是展示出疫情给予我们更多机会与与亲朋好友在一起。","pinyin":"Tā méi yǒu zhǎn shì yì qíng cóng wǒ mén shēn shàng duó zǒu le shí mó， ér shì zhǎn shì chū yì qíng gěi yú wǒ mén gēng duō jī huì yǔ yǔ qīn péng hǎo yǒu zài yī qǐ。","meaning":"Instead of showing what the pandemic has taken from us, it shows that it has given us more chances to be with family and friends and spend time together.","meaningThai":"แทนที่จะแสดงให้เห็นว่าโรคระบาดได้พรากไปจากเราอย่างไร กลับแสดงให้เห็นว่ามันทำให้เรามีโอกาสอยู่กับครอบครัวและเพื่อนฝูงและใช้เวลาร่วมกันมากขึ้น"},{"chinese":"他们和亲朋好友见面。","pinyin":"Tā mén hé qīn péng hǎo yǒu jiàn miàn。","meaning":"They meet their friends and relatives.","meaningThai":"พวกเขาได้พบกับเพื่อนและญาติของพวกเขา"}],"partOfSpeech":["expression"]},
  {"id":"hsk5-886","chinese":"亲切","pinyin":"qīnqiè","meaning":"amiable; cordial; close and dear; familiar","meaningThai":"ใจดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们受到了大家如此亲切的对待。","pinyin":"Wǒ mén shòu dào le dà jiā rú cǐ qīn qiē de duì dài。","meaning":"We have been treated with such kindness by everybody.","meaningThai":"เราได้รับการปฏิบัติด้วยความเมตตาจากทุกคน"},{"chinese":"她与他们亲切交谈。","pinyin":"Tā yǔ tā mén qīn qiē jiāo tán。","meaning":"She spoke kindly to them.","meaningThai":"เธอพูดจาดีกับพวกเขา"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-887","chinese":"亲情","pinyin":"qīnqíng","meaning":"affection; family love; love, esp. within a married couple or between parents and children","meaningThai":"ความรักในครอบครัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"亲情可能帮这个年轻人找到了生活的方向。","pinyin":"Qīn qíng kě néng bāng zhè gè nián qīng rén zhǎo dào le shēng huó de fāng xiàng。","meaning":"The ties of kinship may have helped the young man find his way in life.","meaningThai":"ความผูกพันทางเครือญาติอาจช่วยให้ชายหนุ่มพบเส้นทางชีวิตของเขา"},{"chinese":"友情和亲情都是无法定价的。","pinyin":"Yǒu qíng hé qīn qíng dū shì wú fǎ dìng jià de。","meaning":"Never can you put a price on friendship, nor on family.","meaningThai":"คุณไม่สามารถกำหนดราคาให้กับมิตรภาพหรือครอบครัวได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-888","chinese":"亲人","pinyin":"qīnrén","meaning":"one's close relatives","meaningThai":"ญาติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"除了父母，我没有其他亲人。","pinyin":"Chú le fù mǔ， wǒ méi yǒu qí tā qīn rén。","meaning":"I've got no family besides my parents.","meaningThai":"ฉันไม่มีครอบครัวนอกจากพ่อแม่"},{"chinese":"他渴望着回家与亲人团聚。","pinyin":"Tā kě wàng zháo huí jiā yǔ qīn rén tuán jù。","meaning":"He ached to be home with his loved ones.","meaningThai":"เขาปวดใจที่ต้องอยู่บ้านกับคนที่เขารัก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-889","chinese":"亲自","pinyin":"qīnzì","meaning":"personally; in person; oneself","meaningThai":"ส่วนตัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在这个录音中阿姆斯特朗亲自唱。","pinyin":"Zài zhè gè lù yīn zhōng ā mǔ sī tè lǎng qīn zì chàng。","meaning":"In this recording Armstrong himself is on vocals.","meaningThai":"ในการบันทึกนี้ Armstrong เองก็เป็นผู้ร้อง"},{"chinese":"总统亲自出面处理这场危机。","pinyin":"Zǒng tǒng qīn zì chū miàn chǔ lǐ zhè cháng wēi jī。","meaning":"The President intervened personally in the crisis.","meaningThai":"ประธานาธิบดีเข้าแทรกแซงเป็นการส่วนตัวในภาวะวิกฤติ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-890","chinese":"穷","pinyin":"qióng","meaning":"poor; destitute; to use up; to exhaust; thoroughly; extremely; (coll.) persistently and pointlessly","meaningThai":"ความยากจน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她老是没完没了地讲他们有多穷。","pinyin":"Tā lǎo shì méi wán méi le dì jiǎng tā mén yǒu duō qióng。","meaning":"She's forever going on about how poor they are.","meaningThai":"เธอพูดถึงว่าพวกเขายากจนแค่ไหนตลอดไป"},{"chinese":"他虽穷，但对贫苦的朋友很慷慨。","pinyin":"Tā suī qióng， dàn duì pín kǔ de péng yǒu hěn kāng kǎi。","meaning":"Although he was poor, he was quite generous to his needy friends.","meaningThai":"แม้ว่าเขาจะยากจน แต่เขาก็มีน้ำใจกับเพื่อนที่ขัดสนมาก"}],"partOfSpeech":["adjective","adverb","other"]},
  {"id":"hsk5-891","chinese":"气球","pinyin":"qìqiú","meaning":"balloon","meaningThai":"บอลลูน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你再给气球充气，它就要爆了。","pinyin":"Nǐ zài gěi qì qiú chōng qì， tā jiù yào bào le。","meaning":"That balloon will burst if you blow it up any more.","meaningThai":"ลูกโป่งนั้นจะแตกถ้าคุณระเบิดมันอีก"},{"chinese":"他们用花和气球装饰了房间。","pinyin":"Tā mén yòng huā hé qì qiú zhuāng shì le fáng jiān。","meaning":"They decorated the room with flowers and balloons.","meaningThai":"พวกเขาตกแต่งห้องด้วยดอกไม้และลูกโป่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-892","chinese":"企业","pinyin":"qǐyè","meaning":"company; firm; enterprise; corporation","meaningThai":"องค์กร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"安德鲁决定独力开办自己的企业。","pinyin":"Ān dé lǔ jué dìng dú lì kāi bàn zì jǐ de qǐ yè。","meaning":"Andrew decided to go it alone and start his own business.","meaningThai":"แอนดรูว์ตัดสินใจไปคนเดียวและเริ่มต้นธุรกิจของตัวเอง"},{"chinese":"他想要自己管理整个企业。","pinyin":"Tā xiǎng yào zì jǐ guǎn lǐ zhěng gè qǐ yè。","meaning":"He wanted all the running of the business for himself.","meaningThai":"เขาต้องการดำเนินธุรกิจทั้งหมดเพื่อตัวเขาเอง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-893","chinese":"汽油","pinyin":"qìyóu","meaning":"gasoline","meaningThai":"น้ำมันเบนซิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们已开始贮藏食物和汽油并攒钱。","pinyin":"Tā mén yǐ kāi shǐ zhù cáng shí wù hé qì yóu bìng zǎn qián。","meaning":"They've begun to hoard food and petrol and save their money.","meaningThai":"พวกเขาเริ่มกักตุนอาหารและน้ำมันและประหยัดเงิน"},{"chinese":"大约每个星期我加满一箱汽油。","pinyin":"Dà yuē měi gè xīng qī wǒ jiā mǎn yī xiāng qì yóu。","meaning":"I fill up the tank with gasoline about once a week.","meaningThai":"ฉันเติมน้ำมันเบนซินประมาณสัปดาห์ละครั้ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-894","chinese":"其余","pinyin":"qíyú","meaning":"the rest; the others; remaining; remainder; apart from them","meaningThai":"ส่วนที่เหลือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你留在这儿，其余的人去外面","pinyin":"Nǐ liú zài zhè ér， qí yú de rén qù wài miàn","meaning":"You stay here. Everyone else go outside.","meaningThai":"คุณอยู่ที่นี่ คนอื่นออกไปข้างนอกกัน"},{"chinese":"我的神与我的信仰是唯一的真理，其余都是虚构。","pinyin":"Wǒ de shén yǔ wǒ de xìn yǎng shì wéi yī de zhēn lǐ， qí yú dū shì xū gòu。","meaning":"My God and my faith are the only true ones, and the others are just fiction.","meaningThai":"พระเจ้าของฉันและความศรัทธาของฉันเป็นเพียงสิ่งที่แท้จริงเท่านั้น ส่วนสิ่งอื่นๆ เป็นเพียงนิยาย"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-895","chinese":"权","pinyin":"quán","meaning":"surname Quan","meaningThai":"ขวา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"现有股东将有优先购买权。","pinyin":"Xiàn yǒu gǔ dōng jiāng yǒu yōu xiān gòu mǎi quán。","meaning":"Existing shareholders will have pre-emption rights.","meaningThai":"ผู้ถือหุ้นเดิมจะมีสิทธิจองซื้อหุ้นล่วงหน้า"},{"chinese":"这里谁有优先通行权？","pinyin":"Zhè lǐ shuí yǒu yōu xiān tōng háng quán？","meaning":"Whose right of way is it?","meaningThai":"เป็นสิทธิทางของใคร?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-896","chinese":"劝","pinyin":"quàn","meaning":"to advise; to urge; to try to persuade; to exhort; to console; to soothe","meaningThai":"ให้คำแนะนำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有人劝我们找律师咨询。","pinyin":"Yǒu rén quàn wǒ mén zhǎo lǜ shī zī xún。","meaning":"We were advised to seek legal advice.","meaningThai":"เราได้รับคำแนะนำให้ขอคำแนะนำทางกฎหมาย"},{"chinese":"有人劝我饮食要忌糖。","pinyin":"Yǒu rén quàn wǒ yǐn shí yào jì táng。","meaning":"I've been advised to cut sugar out of my diet.","meaningThai":"ฉันได้รับคำแนะนำให้ตัดน้ำตาลออกจากอาหารของฉัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-897","chinese":"权利","pinyin":"quánlì","meaning":"right (i.e. an entitlement to sth); (classical) power and wealth","meaningThai":"ขวา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们支持《权利法案》制定的呼吁。","pinyin":"Wǒ mén zhī chí 《 quán lì fǎ àn 》 zhì dìng de hū xū。","meaning":"We support the call for the enactment of a Bill of Rights.","meaningThai":"เราสนับสนุนการเรียกร้องให้มีการตราพระราชบัญญัติสิทธิ"},{"chinese":"他们认为妇女有权利选择隆胸。","pinyin":"Tā mén rèn wéi fù nǚ yǒu quán lì xuǎn zé lóng xiōng。","meaning":"They felt a woman had a right to choose to have a breast implant.","meaningThai":"พวกเขารู้สึกว่าผู้หญิงมีสิทธิ์เลือกที่จะเสริมเต้านม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-898","chinese":"全力","pinyin":"quánlì","meaning":"with all one's strength; full strength; all-out (effort); fully (support)","meaningThai":"ออกทั้งหมด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他用全力推那块石头。","pinyin":"Tā yòng quán lì tuī nà kuài shí tóu。","meaning":"He pushed against the rock with all his strength.","meaningThai":"เขาผลักหินอย่างสุดกำลัง"},{"chinese":"我尽全力照顾他们。","pinyin":"Wǒ jìn quán lì zhào gù tā mén。","meaning":"I take care of them to the best of my abilities.","meaningThai":"ฉันดูแลพวกเขาอย่างสุดความสามารถ"}],"partOfSpeech":["adverb","noun"]},
  {"id":"hsk5-899","chinese":"全面","pinyin":"quánmiàn","meaning":"all-around; comprehensive; total; overall","meaningThai":"ครอบคลุม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"全面终止供给将使该国经济瘫痪。","pinyin":"Quán miàn zhōng zhǐ gōng gěi jiāng shǐ gāi guó jīng jì tān huàn。","meaning":"A total cutoff of supplies would cripple the country's economy.","meaningThai":"การตัดอุปทานทั้งหมดจะทำให้เศรษฐกิจของประเทศพิการ"},{"chinese":"这家医院将很快全面运作。","pinyin":"Zhè jiā yī yuàn jiāng hěn kuài quán miàn yùn zuò。","meaning":"The hospital will soon be fully functional.","meaningThai":"โรงพยาบาลจะเปิดให้บริการเต็มรูปแบบเร็วๆ นี้"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-900","chinese":"全体","pinyin":"quántǐ","meaning":"all; entire","meaningThai":"ทั้งหมด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"全体负责就是无责。","pinyin":"Quán tǐ fù zé jiù shì wú zé。","meaning":"Everybody's business is nobody's business. / Collective responsibility means irresponsibility.","meaningThai":"ธุรกิจของทุกคนไม่ใช่ธุรกิจของใคร / ความรับผิดชอบโดยรวมหมายถึงการขาดความรับผิดชอบ"},{"chinese":"在全体职员回家后，火事爆发了。","pinyin":"Zài quán tǐ zhí yuán huí jiā hòu， huǒ shì bào fā le。","meaning":"The fire broke out after the staff went home.","meaningThai":"เกิดเหตุเพลิงไหม้หลังจากที่เจ้าหน้าที่กลับบ้านแล้ว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-901","chinese":"全新","pinyin":"quánxīn","meaning":"all new; completely new","meaningThai":"ใหม่เอี่ยม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我想让你进入一种全新的心态。","pinyin":"Wǒ xiǎng ràng nǐ jìn rù yī zhǒng quán xīn de xīn tài。","meaning":"I want you to get into a whole new state of mind.","meaningThai":"ฉันอยากให้คุณเข้าสู่สภาวะใหม่ของจิตใจ"},{"chinese":"他发现自己面对着一个全新的局势。","pinyin":"Tā fā xiàn zì jǐ miàn duì zháo yī gè quán xīn de jú shì。","meaning":"He finds himself faced with a whole new ball game.","meaningThai":"เขาพบว่าตัวเองต้องเผชิญกับเกมบอลรูปแบบใหม่"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-902","chinese":"确保","pinyin":"quèbǎo","meaning":"to ensure; to guarantee","meaningThai":"ตรวจสอบให้แน่ใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"确保汤姆安全。","pinyin":"Què bǎo tāng mǔ ān quán。","meaning":"Keep Tom safe.","meaningThai":"ขอให้ทอมปลอดภัย"},{"chinese":"我可以确保成功。","pinyin":"Wǒ kě yǐ què bǎo chéng gōng。","meaning":"I can assure success.","meaningThai":"ฉันรับประกันความสำเร็จได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-903","chinese":"确定","pinyin":"quèdìng","meaning":"definite; certain; fixed; to fix (on sth); to determine; to be sure; to ensure; to make certain; to ascertain; to clinch; to recognize; to confirm; OK (on computer dialog box)","meaningThai":"แน่นอน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我无法确定谁当时在场。","pinyin":"Wǒ wú fǎ què dìng shuí dāng shí zài cháng。","meaning":"I'm not certain who was there.","meaningThai":"ฉันไม่แน่ใจว่าใครอยู่ที่นั่น"},{"chinese":"会议日期尚待确定。","pinyin":"Huì yì rì qī shàng dài què dìng。","meaning":"A date for the meeting has yet to be determined.","meaningThai":"ยังไม่ได้กำหนดวันประชุม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-904","chinese":"缺乏","pinyin":"quēfá","meaning":"to lack; to be short of","meaningThai":"ขาด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"缺乏经验。","pinyin":"Que fa jing yan.","meaning":"Lack of experience.","meaningThai":"ขาดประสบการณ์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-905","chinese":"确认","pinyin":"quèrèn","meaning":"to confirm; to verify; confirmation","meaningThai":"ยืนยัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些期限是暂定的，还有待确认。","pinyin":"Zhè xiē qī xiàn shì zàn dìng de， huán yǒu dài què rèn。","meaning":"These times are provisional and subject to confirmation.","meaningThai":"เวลาเหล่านี้เป็นเพียงเวลาชั่วคราวและอาจต้องได้รับการยืนยัน"},{"chinese":"你先预定，我再以书面形式确认。","pinyin":"Nǐ xiān yù dìng， wǒ zài yǐ shū miàn xíng shì què rèn。","meaning":"You make the reservation, and I'll confirm it in writing.","meaningThai":"คุณทำการจองและฉันจะยืนยันเป็นลายลักษณ์อักษร"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-906","chinese":"群","pinyin":"qún","meaning":"variant of 群","meaningThai":"กลุ่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"一群孩子在街上玩球。","pinyin":"Yī qún hái zǐ zài jiē shàng wán qiú。","meaning":"A group of kids were playing with a ball in the street.","meaningThai":"เด็กกลุ่มหนึ่งกำลังเล่นกับลูกบอลบนถนน"},{"chinese":"这两群学生互怀敌意。","pinyin":"Zhè liǎng qún xué shēng hù huái dí yì。","meaning":"There was a lot of bad feeling between the two groups of students.","meaningThai":"มีความรู้สึกไม่ดีมากมายระหว่างนักเรียนทั้งสองกลุ่ม"}],"partOfSpeech":["measure word","other"]},
  {"id":"hsk5-907","chinese":"群体","pinyin":"qúntǐ","meaning":"community; colony","meaningThai":"กลุ่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些信念在某些社会群体中仍很盛行。","pinyin":"Zhè xiē xìn niàn zài mǒu xiē shè huì qún tǐ zhōng réng hěn shèng háng。","meaning":"Those beliefs still prevail among certain social groups.","meaningThai":"ความเชื่อเหล่านั้นยังคงมีอยู่ในกลุ่มสังคมบางกลุ่ม"},{"chinese":"这些动物按母系群体生活。","pinyin":"Zhè xiē dòng wù àn mǔ xì qún tǐ shēng huó。","meaning":"The animals live in matriarchal groups.","meaningThai":"สัตว์เหล่านี้อาศัยอยู่ในกลุ่มที่ปกครองโดยผู้ปกครอง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-908","chinese":"去世","pinyin":"qùshì","meaning":"to pass away; to die","meaningThai":"เสียชีวิต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“去世”是“死”的委婉语。","pinyin":"“ qù shì ” shì “ sǐ ” de wěi wǎn yǔ。","meaning":"'Pass away' is a euphemism for 'die'.","meaningThai":"'Pass away' เป็นคำสละสลวยสำหรับ 'ตาย'"},{"chinese":"她为丈夫的去世而悲伤。","pinyin":"Tā wéi zhàng fū de qù shì ér bēi shāng。","meaning":"She grieved the death of her husband.","meaningThai":"เธอเสียใจกับการตายของสามีของเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-909","chinese":"趋势","pinyin":"qūshì","meaning":"trend; tendency","meaningThai":"แนวโน้ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"阻止这一健康的趋势是有悖常理的。","pinyin":"Zǔ zhǐ zhè yī jiàn kāng de qū shì shì yǒu bèi cháng lǐ de。","meaning":"It would be perverse to stop this healthy trend.","meaningThai":"คงจะเป็นการไม่ดีหากจะหยุดแนวโน้มที่ดีต่อสุขภาพนี้"},{"chinese":"类似的趋势在欧洲大陆也能见到。","pinyin":"Lèi sì de qū shì zài ōu zhōu dà lù yě néng jiàn dào。","meaning":"Similar trends are observable in mainland Europe.","meaningThai":"แนวโน้มที่คล้ายกันนี้สามารถสังเกตได้ในยุโรปแผ่นดินใหญ่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-910","chinese":"区域","pinyin":"qūyù","meaning":"area; region; district","meaningThai":"พื้นที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"此项调查覆盖的地理区域非常广阔。","pinyin":"Cǐ xiàng tiáo chá fù gài de dì lǐ qū yù fēi cháng guǎng kuò。","meaning":"The survey covers a wide geographical area.","meaningThai":"การสำรวจครอบคลุมพื้นที่ทางภูมิศาสตร์ในวงกว้าง"},{"chinese":"克里希那站在舞台前部的开阔区域。","pinyin":"Kè lǐ xī nà zhàn zài wǔ tái qián bù de kāi kuò qū yù。","meaning":"Krishna stands downstage in the open area.","meaningThai":"พระกฤษณะยืนอยู่ล่างเวทีในพื้นที่เปิดโล่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-911","chinese":"燃烧","pinyin":"ránshāo","meaning":"to ignite; to combust; to burn; combustion; flaming","meaningThai":"การเผาไหม้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"燃烧的硫磺会产生有毒烟雾。","pinyin":"Rán shāo de liú huáng huì chǎn shēng yǒu dú yān wù。","meaning":"Burning sulphur creates poisonous fumes.","meaningThai":"การเผาไหม้ของกำมะถันทำให้เกิดควันพิษ"},{"chinese":"哪种燃料燃烧效果最佳？","pinyin":"Nǎ zhǒng rán liào rán shāo xiào guǒ zuì jiā？","meaning":"Which fuel burns most efficiently?","meaningThai":"เชื้อเพลิงชนิดใดที่เผาไหม้ได้อย่างมีประสิทธิภาพมากที่สุด?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-912","chinese":"绕","pinyin":"rào","meaning":"to wind; to coil (thread); to rotate around; to spiral; to move around; to go round (an obstacle); to by-pass; to make a detour; to confuse; to perplex","meaningThai":"รอบๆ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那条河顺着山谷绕了个大弯儿。","pinyin":"Nà tiáo hé shùn zháo shān gǔ rào le gè dà wān ér。","meaning":"The river loops around the valley.","meaningThai":"แม่น้ำไหลวนรอบหุบเขา"},{"chinese":"护士绕床拉了一道帘子。","pinyin":"Hù shì rào chuáng lā le yī dào lián zǐ。","meaning":"The nurse put a screen around the bed.","meaningThai":"พยาบาลก็ติดมุ้งลวดไว้รอบเตียง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-913","chinese":"热爱","pinyin":"rè'ài","meaning":"to love ardently; to adore","meaningThai":"รัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他天生热爱冒险。","pinyin":"Tā tiān shēng rè ài mào xiǎn。","meaning":"He has an innate love of adventure.","meaningThai":"เขามีความรักในการผจญภัยโดยกำเนิด"},{"chinese":"他真的很热爱音乐。","pinyin":"Tā zhēn de hěn rè ài yīn lè。","meaning":"He really likes music a lot.","meaningThai":"เขาชอบดนตรีมากจริงๆ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-914","chinese":"热量","pinyin":"rèliàng","meaning":"heat; quantity of heat; calorific value","meaningThai":"แคลอรี่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"要注意控制热量摄入。","pinyin":"Yào zhù yì kòng zhì rè liàng shè rù.","meaning":"Be careful to control calorie intake.","meaningThai":"ระมัดระวังในการควบคุมปริมาณแคลอรี่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-915","chinese":"热烈","pinyin":"rèliè","meaning":"enthusiastic; ardent; warm","meaningThai":"อบอุ่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"学生们给了他热烈的欢迎。","pinyin":"Xué shēng mén gěi le tā rè liè de huān yíng。","meaning":"The students gave him a rapturous welcome.","meaningThai":"นักเรียนต่างแสดงความยินดีกับเขา"},{"chinese":"新成员受到热烈欢迎。","pinyin":"Xīn chéng yuán shòu dào rè liè huān yíng。","meaning":"New members are warmly welcomed.","meaningThai":"สมาชิกใหม่ได้รับการต้อนรับอย่างอบอุ่น"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-916","chinese":"认","pinyin":"rèn","meaning":"to recognize; to know; to admit","meaningThai":"จำได้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"书写的文字模糊难认。","pinyin":"Shū xiě de wén zì mó hū nán rèn。","meaning":"The lettering is fuzzy and indistinct.","meaningThai":"ตัวอักษรไม่ชัดเจนและไม่ชัดเจน"},{"chinese":"我们建议在你的学习过程中保留一些笔记卡，这样你就可以为接下来的考试制作抽认卡。","pinyin":"Wǒ mén jiàn yì zài nǐ de xué xí guò chéng zhōng bǎo liú yī xiē bǐ jì kǎ， zhè yàng nǐ jiù kě yǐ wéi jiē xià lái de kǎo shì zhì zuò chōu rèn kǎ。","meaning":"We suggest keeping some note cards in your study so that you can make flashcards for coming tests.","meaningThai":"เราขอแนะนำให้เก็บการ์ดบันทึกในการศึกษาของคุณเพื่อที่คุณจะได้สามารถทำแฟลชการ์ดสำหรับการทดสอบครั้งต่อไปได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-917","chinese":"忍","pinyin":"rěn","meaning":"to bear; to endure; to tolerate; to restrain oneself","meaningThai":"ทนต่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“我实在忍不下去了。”他声音哽咽地说道。","pinyin":"“ wǒ shí zài rěn bù xià qù le。” tā shēng yīn gěng yān dì shuō dào。","meaning":"'I can't bear it,' he said in a choked voice.","meaningThai":"“ฉันทนไม่ไหวแล้ว” เขาพูดด้วยน้ำเสียงสำลัก"},{"chinese":"骚扰已让他忍无可忍，他决定搬走。","pinyin":"Sāo rǎo yǐ ràng tā rěn wú kě rěn， tā jué dìng bān zǒu。","meaning":"The harassment had become too much to tolerate and he decided to move out.","meaningThai":"การคุกคามมีมากเกินไปที่จะทนได้ และเขาจึงตัดสินใจย้ายออก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-918","chinese":"人才","pinyin":"réncái","meaning":"talent; talented person; looks; attractive looks","meaningThai":"ความสามารถพิเศษ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"公司急需具有最新理念的人才。","pinyin":"Gōng sī jí xū jù yǒu zuì xīn lǐ niàn de rén cái。","meaning":"The company is crying out for fresh new talent.","meaningThai":"บริษัทกำลังเรียกร้องหาผู้มีความสามารถหน้าใหม่"},{"chinese":"我们在该地区有丰富的音乐人才。","pinyin":"Wǒ mén zài gāi dì qū yǒu fēng fù de yīn lè rén cái。","meaning":"We have a wealth of musical talent in this region.","meaningThai":"เรามีความสามารถทางดนตรีมากมายในภูมิภาคนี้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-919","chinese":"人工","pinyin":"réngōng","meaning":"artificial; manpower; manual work","meaningThai":"เทียม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她接受了人工呼吸和心脏按摩。","pinyin":"Tā jiē shòu le rén gōng hū xī hé xīn zāng àn mó。","meaning":"She was given artificial respiration and cardiac massage.","meaningThai":"เธอได้รับการช่วยหายใจและนวดหัวใจ"},{"chinese":"这种食品不含人工调味品。","pinyin":"Zhè zhǒng shí pǐn bù hán rén gōng tiáo wèi pǐn。","meaning":"This food contains no artificial flavourings.","meaningThai":"อาหารนี้ไม่มีสารปรุงแต่งรสเทียม"}],"partOfSpeech":["adjective","adverb","noun"]},
  {"id":"hsk5-920","chinese":"人际","pinyin":"rénjì","meaning":"interpersonal","meaningThai":"มนุษยสัมพันธ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"拥有良好的人际关系对我最为重要。","pinyin":"Yōng yǒu liáng hǎo de rén jì guān xì duì wǒ zuì wéi zhòng yào。","meaning":"Having good personal relationships is the most important thing for me.","meaningThai":"การมีความสัมพันธ์ส่วนตัวที่ดีเป็นสิ่งสำคัญที่สุดสำหรับฉัน"},{"chinese":"我们陷入了错综复杂的人际关系网络。","pinyin":"Wǒ mén xiàn rù le cuò zōng fù zá de rén jì guān xì wǎng luò。","meaning":"We were caught in a tangled web of relationships.","meaningThai":"เราติดอยู่ในความสัมพันธ์ที่ยุ่งเหยิง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-921","chinese":"人口","pinyin":"rénkǒu","meaning":"population; people","meaningThai":"ประชากร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种病感染了足足30%的人口。","pinyin":"Zhè zhǒng bìng gǎn rǎn le zú zú 30% de rén kǒu。","meaning":"The disease affects fully 30 per cent of the population.","meaningThai":"โรคนี้ส่งผลกระทบอย่างเต็มที่ถึงร้อยละ 30 ของประชากร"},{"chinese":"人口增长每年下降1.4%。","pinyin":"Rén kǒu zēng cháng měi nián xià jiàng1.4%。","meaning":"Population growth is decreasing by 1.4% each year.","meaningThai":"การเติบโตของประชากรลดลง 1.4% ในแต่ละปี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-922","chinese":"人类","pinyin":"rénlèi","meaning":"humanity; human race; mankind","meaningThai":"มนุษย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"贫穷和人类的愚蠢加剧自然灾难。","pinyin":"Pín qióng hé rén lèi de yú chǔn jiā jù zì rán zāi nán。","meaning":"Poverty and human folly magnify natural disasters.","meaningThai":"ความยากจนและความโง่เขลาของมนุษย์ทำให้เกิดภัยพิบัติทางธรรมชาติ"},{"chinese":"他的研究是为了人类生活的改善。","pinyin":"Tā de yán jiū shì wéi le rén lèi shēng huó de gǎi shàn。","meaning":"His research is for the betterment of mankind.","meaningThai":"งานวิจัยของเขามีไว้เพื่อการพัฒนามนุษยชาติให้ดีขึ้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-923","chinese":"人力","pinyin":"rénlì","meaning":"manpower; labor power","meaningThai":"กำลังคน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"医生们尽了人力所及的最大努力。","pinyin":"Yī shēng mén jìn le rén lì suǒ jí de zuì dà nǔ lì。","meaning":"The doctors did all that was humanly possible.","meaningThai":"แพทย์ทำทุกอย่างที่เป็นไปได้อย่างมนุษย์ปุถุชน"},{"chinese":"在许多行业中，机器已经替代了人力。","pinyin":"Zài xǔ duō háng yè zhōng， jī qì yǐ jīng tì dài le rén lì。","meaning":"Machines have replaced human labour in many industries.","meaningThai":"เครื่องจักรเข้ามาแทนที่แรงงานมนุษย์ในหลายอุตสาหกรรม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-924","chinese":"人民","pinyin":"rénmín","meaning":"the people","meaningThai":"ประชากร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"总统已对格鲁吉亚人民表示了同情。","pinyin":"Zǒng tǒng yǐ duì gé lǔ jí yà rén mín biǎo shì le tóng qíng。","meaning":"The president has offered his sympathy to the Georgian people.","meaningThai":"ประธานาธิบดีแสดงความเห็นใจต่อชาวจอร์เจีย"},{"chinese":"人民把曼德拉视为他们的救星。","pinyin":"Rén mín bǎ màn dé lā shì wéi tā mén de jiù xīng。","meaning":"People saw Mandela as their messiah.","meaningThai":"ผู้คนมองว่าแมนเดลาเป็นพระเมสสิยาห์ของพวกเขา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-925","chinese":"人民币","pinyin":"rénmínbì","meaning":"Renminbi (RMB); Chinese Yuan (CNY)","meaningThai":"หยวน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"通货膨胀正在迅速上升；人民币正在贬值。","pinyin":"Tōng huò péng zhàng zhèng zài xùn sù shàng shēng； rén mín bì zhèng zài biǎn zhí。","meaning":"Inflation is rising rapidly; the yuan is depreciating.","meaningThai":"อัตราเงินเฟ้อเพิ่มขึ้นอย่างรวดเร็ว เงินหยวนอ่อนค่าลง"},{"chinese":"维修手表花了我一百元人民币。","pinyin":"Wéi xiū shǒu biǎo huā le wǒ yī bǎi yuán rén mín bì。","meaning":"It cost me one hundred yuan to have my watch repaired.","meaningThai":"ฉันเสียเงินหนึ่งร้อยหยวนในการซ่อมนาฬิกา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-926","chinese":"人群","pinyin":"rénqún","meaning":"crowd","meaningThai":"ฝูงชน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人群很快便散开了。","pinyin":"Rén qún hěn kuài biàn sàn kāi le。","meaning":"The crowd dispersed quickly.","meaningThai":"ฝูงชนก็แยกย้ายกันไปอย่างรวดเร็ว"},{"chinese":"警察阻拦不住人群。","pinyin":"Jǐng chá zǔ lán bù zhù rén qún。","meaning":"The police were unable to hold back the crowd.","meaningThai":"ตำรวจไม่สามารถควบคุมฝูงชนได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-927","chinese":"人体","pinyin":"réntǐ","meaning":"human body","meaningThai":"ร่างกายมนุษย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"眼睛是人体最娇贵的器官之一。","pinyin":"Yǎn jīng shì rén tǐ zuì jiāo guì de qì guān zhī yī。","meaning":"The eye is one of the most delicate organs of the body.","meaningThai":"ดวงตาเป็นอวัยวะที่บอบบางที่สุดของร่างกาย"},{"chinese":"人体主要由骨、肌肉和脂肪组成。","pinyin":"Rén tǐ zhǔ yào yóu gǔ、 jī ròu hé zhī fáng zǔ chéng。","meaning":"The body is made up primarily of bone, muscle, and fat.","meaningThai":"ร่างกายประกอบด้วยกระดูก กล้ามเนื้อ และไขมันเป็นหลัก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-928","chinese":"人物","pinyin":"rénwù","meaning":"person; personage; figure (esp. sb of importance); character (in a play, novel etc); figure painting (as a genre of traditional Chinese painting)","meaningThai":"รูป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她只愿扮演自己认同的人物角色。","pinyin":"Tā zhī yuàn bàn yǎn zì jǐ rèn tóng de rén wù jiǎo sè。","meaning":"She would only play a role if she could identify with the character.","meaningThai":"เธอจะมีบทบาทก็ต่อเมื่อเธอสามารถระบุตัวตนของตัวละครได้"},{"chinese":"她简略地勾勒出人物的轮廓。","pinyin":"Tā jiǎn lüè dì gōu lè chū rén wù de lún kuò。","meaning":"She drew the figures in outline.","meaningThai":"เธอวาดรูปเป็นโครงร่าง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-929","chinese":"热心","pinyin":"rèxīn","meaning":"enthusiastic; ardent; zealous","meaningThai":"กระตือรือร้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我对他的想法怎么也热心不起来。","pinyin":"Wǒ duì tā de xiǎng fǎ zěn mó yě rè xīn bù qǐ lái。","meaning":"I can't work up any enthusiasm for his idea.","meaningThai":"ฉันไม่สามารถแสดงความกระตือรือร้นต่อความคิดของเขาได้"},{"chinese":"他是个热情、大方又热心肠的人。","pinyin":"Tā shì gè rè qíng、 dà fāng yòu rè xīn cháng de rén。","meaning":"He was a warm, generous and kind-hearted man.","meaningThai":"เขาเป็นผู้ชายที่อบอุ่น ใจกว้าง และใจดี"}],"partOfSpeech":["adjective","verb","particle"]},
  {"id":"hsk5-930","chinese":"日历","pinyin":"rìlì","meaning":"calendar","meaningThai":"ปฏิทิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"墙上有一副日历，日期周围是大的方框。","pinyin":"Qiáng shàng yǒu yī fù rì lì， rì qī zhōu wéi shì dà de fāng kuàng。","meaning":"There was a calendar on the wall, with large squares around the dates.","meaningThai":"มีปฏิทินอยู่บนผนังโดยมีสี่เหลี่ยมจัตุรัสขนาดใหญ่ล้อมรอบวันที่"},{"chinese":"墙的上方曾有一本日历，日期框在大方格里。","pinyin":"Qiáng de shàng fāng zēng yǒu yī běn rì lì， rì qī kuàng zài dà fāng gé lǐ。","meaning":"There was a calendar on the wall above, with large squares around the dates.","meaningThai":"มีปฏิทินอยู่บนผนังด้านบน โดยมีสี่เหลี่ยมขนาดใหญ่รอบๆ วันที่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-931","chinese":"日用品","pinyin":"rìyòngpǐn","meaning":"articles for daily use","meaningThai":"สิ่งจำเป็นในชีวิตประจำวัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"起初，罗森用失业保险购买了日用品并支付了房款。","pinyin":"Qǐ chū， luó sēn yòng shī yè bǎo xiǎn gòu mǎi le rì yòng pǐn bìng zhī fù le fáng kuǎn。","meaning":"At first, Rosen bought groceries and made house payments with the help of unemployment insurance.","meaningThai":"ในตอนแรก โรเซนซื้อของชำและชำระเงินบ้านด้วยความช่วยเหลือจากประกันการว่างงาน"},{"chinese":"派送包裹，购买日用品，甚至是盖房子，这些都是新机器人在世界机器人展上展示的新技能。","pinyin":"Pài sòng bāo guǒ， gòu mǎi rì yòng pǐn， shèn zhì shì gài fáng zǐ， zhè xiē dū shì xīn jī qì rén zài shì jiè jī qì rén zhǎn shàng zhǎn shì de xīn jì néng。","meaning":"Sending packets, shopping for everyday goods and even building a house, these are new skills that new robots show at the World Robot Exhibition.","meaningThai":"การส่งแพ็กเก็ต การซื้อของในชีวิตประจำวัน หรือแม้แต่การสร้างบ้าน เหล่านี้คือทักษะใหม่ที่หุ่นยนต์ตัวใหม่จะแสดงในงาน World Robot Exhibition"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-932","chinese":"如","pinyin":"rú","meaning":"as; as if; such as","meaningThai":"ชอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你必须键入指令，如“帮助”和“打印”。","pinyin":"Nǐ bì xū jiàn rù zhǐ líng， rú “ bāng zhù ” hé “ dǎ yìn”。","meaning":"You have to type in commands, such as \"help\" and \"print.\"","meaningThai":"คุณต้องพิมพ์คำสั่ง เช่น \"help\" และ \"print\""}],"partOfSpeech":["verb","conjunction"]},
  {"id":"hsk5-933","chinese":"软","pinyin":"ruǎn","meaning":"soft; flexible","meaningThai":"อ่อนนุ่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你不必多打肥皂—这儿的水很软。","pinyin":"Nǐ bù bì duō dǎ féi zào — zhè ér de shuǐ hěn ruǎn。","meaning":"You won't need much soap—the water here is very soft.","meaningThai":"ไม่ต้องใช้สบู่มากนัก เพราะน้ำที่นี่อ่อนมาก"},{"chinese":"那些叶子软而圆，就像绒毛一般。","pinyin":"Nà xiē yè zǐ ruǎn ér yuán， jiù xiàng róng máo yī bān。","meaning":"The leaves are soft, round and rather furry.","meaningThai":"ใบมีลักษณะนุ่ม กลมและมีขนค่อนข้างมาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-934","chinese":"软件","pinyin":"ruǎnjiàn","meaning":"(computer) software","meaningThai":"ซอฟต์แวร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个软件很好用。","pinyin":"Zhe ge ruan jian hen hao yong.","meaning":"This software is easy to use.","meaningThai":"ซอฟต์แวร์นี้ใช้งานง่าย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-935","chinese":"如此","pinyin":"rúcǐ","meaning":"like this; so; such","meaningThai":"ด้วยวิธีนี้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"公司无法承担如此巨大的亏损。","pinyin":"Gōng sī wú fǎ chéng dān rú cǐ jù dà de kuī sǔn。","meaning":"The company is unable to absorb such huge losses.","meaningThai":"บริษัทไม่สามารถรับผลขาดทุนมหาศาลดังกล่าวได้"},{"chinese":"她有着如此友善的性格。","pinyin":"Tā yǒu zháo rú cǐ yǒu shàn de xìng gé。","meaning":"She has such a kind, friendly personality.","meaningThai":"เธอมีบุคลิกที่ใจดีและเป็นมิตร"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-936","chinese":"如何","pinyin":"rúhé","meaning":"how; what way; what","meaningThai":"ยังไง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这车出过事故以后状况如何？","pinyin":"Zhè chē chū guò shì gù yǐ hòu zhuàng kuàng rú hé？","meaning":"What sort of shape was the car in after the accident?","meaningThai":"รถมีรูปร่างแบบไหนหลังเกิดอุบัติเหตุ?"},{"chinese":"我们在学习如何正视死亡。","pinyin":"Wǒ mén zài xué xí rú hé zhèng shì sǐ wáng。","meaning":"We are learning how to confront death.","meaningThai":"เรากำลังเรียนรู้วิธีเผชิญหน้ากับความตาย"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-937","chinese":"如今","pinyin":"rújīn","meaning":"nowadays; now","meaningThai":"ตอนนี้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"移植肾脏的手术如今相当常见。","pinyin":"Yí zhí shèn zāng de shǒu shù rú jīn xiāng dāng cháng jiàn。","meaning":"The operation to transplant a kidney is now fairly routine.","meaningThai":"การผ่าตัดปลูกถ่ายไตกลายเป็นเรื่องปกติไปแล้ว"},{"chinese":"如今驾车需要飞快的反应。","pinyin":"Rú jīn jià chē xū yào fēi kuài de fǎn yīng。","meaning":"Driving today demands lightning reflexes.","meaningThai":"การขับรถในปัจจุบันต้องใช้ปฏิกิริยาตอบสนองแบบสายฟ้าแลบ"}],"partOfSpeech":["other"]},
  {"id":"hsk5-938","chinese":"弱","pinyin":"ruò","meaning":"weak; feeble; young; inferior; not as good as; (following a decimal or fraction) slightly less than","meaningThai":"อ่อนแอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"您有哪些弱點呢？","pinyin":"Nín yǒu nǎ xiē ruò diǎn ne？","meaning":"What are your weaknesses? / What are your weak points?","meaningThai":"จุดอ่อนของคุณคืออะไร? / จุดอ่อนของคุณคืออะไร?"},{"chinese":"湯姆非常虚弱。","pinyin":"Tāng mǔ fēi cháng xū ruò。","meaning":"Tom is awfully sick.","meaningThai":"ทอมป่วยหนักมาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-939","chinese":"如同","pinyin":"rútóng","meaning":"like; as","meaningThai":"เช่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他在台上转圈，如同跳旋转舞蹈的托钵僧一样。","pinyin":"Tā zài tái shàng zhuǎn quān， rú tóng tiào xuán zhuǎn wǔ dǎo de tuō bō sēng yī yàng。","meaning":"He threw himself around the stage like a whirling dervish.","meaningThai":"เขาเหวี่ยงตัวเองไปรอบ ๆ เวทีเหมือนคนเดอร์วิชที่หมุนวน"},{"chinese":"他们待我如同父母。","pinyin":"Tā mén dài wǒ rú tóng fù mǔ。","meaning":"They were like proxy parents to me.","meaningThai":"พวกเขาเป็นเหมือนพ่อแม่ตัวแทนของฉัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-940","chinese":"如下","pinyin":"rúxià","meaning":"as follows","meaningThai":"ดังต่อไปนี้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有4种基本选择,简略描述如下。","pinyin":"Yǒu 4 zhǒng jī běn xuǎn zé, jiǎn lüè miáo shù rú xià。","meaning":"There are four basic alternatives; they are described briefly below.","meaningThai":"มีทางเลือกพื้นฐานสี่ทาง มีการอธิบายไว้ด้านล่างโดยย่อ"},{"chinese":"现将我们的几点结论综述如下。","pinyin":"Xiàn jiāng wǒ mén de jī diǎn jié lùn zōng shù rú xià。","meaning":"The following is a summary of our conclusions.","meaningThai":"ต่อไปนี้เป็นบทสรุปของข้อสรุปของเรา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-941","chinese":"洒","pinyin":"sǎ","meaning":"to sprinkle; to spray; to spill; to shed","meaningThai":"โรย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"湯姆把飲料洒到了自己身上。","pinyin":"Tāng mǔ bǎ yǐn liào sǎ dào le zì jǐ shēn shàng。","meaning":"Tom spilled his drink on himself.","meaningThai":"ทอมทำเครื่องดื่มหกใส่ตัวเอง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-942","chinese":"赛场","pinyin":"sàichǎng","meaning":"racetrack; field (for athletics competition)","meaningThai":"อารีน่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"场地保养人员全力准备赛场。","pinyin":"Cháng dì bǎo yǎng rén yuán quán lì zhǔn bèi sài cháng。","meaning":"The ground staff do all they can to prepare the field.","meaningThai":"เจ้าหน้าที่ภาคพื้นดินทำทุกอย่างเท่าที่ทำได้เพื่อเตรียมสนาม"},{"chinese":"运动员们慢慢跑进赛场。","pinyin":"Yùn dòng yuán mén màn màn pǎo jìn sài cháng。","meaning":"The players jogged onto the field.","meaningThai":"นักเตะก็วิ่งจ๊อกกิ้งลงสนาม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-943","chinese":"色彩","pinyin":"sècǎi","meaning":"tint; coloring; coloration; (fig.) flavor; character","meaningThai":"สี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她从姜黄里提取美丽色彩。","pinyin":"Tā cóng jiāng huáng lǐ tí qǔ měi lì sè cǎi。","meaning":"She extracts beautiful colors from turmeric.","meaningThai":"เธอสกัดสีที่สวยงามจากขมิ้น"},{"chinese":"胡蘿蔔為我的餐點增添了色彩。","pinyin":"Hú luó bo wéi wǒ de cān diǎn zēng tiān le sè cǎi。","meaning":"Carrots add color to my meals. / The carrots added color to my meal.","meaningThai":"แครอทเพิ่มสีสันให้กับมื้ออาหารของฉัน / แครอทเพิ่มสีสันให้กับมื้ออาหารของฉัน."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-944","chinese":"傻","pinyin":"shǎ","meaning":"foolish","meaningThai":"โง่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我还不至于傻得连那样的话都相信。","pinyin":"Wǒ huán bù zhì yú shǎ dé lián nà yàng de huà dū xiāng xìn。","meaning":"I'm not so stupid as to believe that.","meaningThai":"ฉันไม่ได้โง่ขนาดนั้นที่จะเชื่อแบบนั้น"},{"chinese":"不对，傻孩子，那不是你的鞋！","pinyin":"Bù duì， shǎ hái zǐ， nà bù shì nǐ de xié！","meaning":"No, silly, those aren't your shoes!","meaningThai":"ไม่ โง่ นั่นไม่ใช่รองเท้าของคุณ!"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-945","chinese":"晒","pinyin":"shài","meaning":"variant of 晒","meaningThai":"ดวงอาทิตย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我肤色很白，永远晒不黑。","pinyin":"Wǒ fū sè hěn bái， yǒng yuǎn shài bù hēi。","meaning":"I have very pale skin that never tans.","meaningThai":"ฉันมีผิวสีซีดมากที่ไม่เคยเป็นสีแทน"},{"chinese":"她的肩膀严重晒伤了。","pinyin":"Tā de jiān bǎng yán zhòng shài shāng le。","meaning":"Her shoulders were badly sunburned.","meaningThai":"ไหล่ของเธอถูกแดดเผาอย่างรุนแรง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-946","chinese":"沙漠","pinyin":"shāmò","meaning":"desert","meaningThai":"ทะเลทราย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"沙漠里非常干燥。","pinyin":"Shā mò lǐ fēi cháng gān zào.","meaning":"The desert is very dry.","meaningThai":"ทะเลทรายแห้งแล้งมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-947","chinese":"删","pinyin":"shān","meaning":"to delete","meaningThai":"ลบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"记住，你在网上或网站上发布的任何东西都是永远存在的，即使你想删也删不掉。","pinyin":"Jì zhù， nǐ zài wǎng shàng huò wǎng zhàn shàng fā bù de rèn hé dōng xī dū shì yǒng yuǎn cún zài de， jí shǐ nǐ xiǎng shān yě shān bù diào。","meaning":"Remember that anything you put online or post on a site is there forever, even if you try to delete it.","meaningThai":"โปรดจำไว้ว่าทุกสิ่งที่คุณโพสต์ทางออนไลน์หรือโพสต์บนเว็บไซต์จะยังคงอยู่ตลอดไป แม้ว่าคุณจะพยายามลบมันก็ตาม"},{"chinese":"你是否尝试过想删除一个文件而又删不掉？","pinyin":"Nǐ shì fǒu cháng shì guò xiǎng shān chú yī gè wén jiàn ér yòu shān bù diào？","meaning":"Ever tried deleting a file - and you couldn't?","meaningThai":"เคยลองลบไฟล์แล้วทำไม่ได้ใช่ไหม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-948","chinese":"扇","pinyin":"shān","meaning":"to fan; to slap sb on the face","meaningThai":"พัดลม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他来到一扇通往走廊的门前。","pinyin":"Tā lái dào yī shàn tōng wǎng zǒu láng de mén qián。","meaning":"He came to a door that led into a passageway.","meaningThai":"เขามาถึงประตูที่นำไปสู่ทางเดิน"},{"chinese":"他用一张报纸给自己扇凉。","pinyin":"Tā yòng yī zhāng bào zhǐ gěi zì jǐ shàn liáng。","meaning":"He fanned himself with a newspaper to cool down.","meaningThai":"เขาพัดหนังสือพิมพ์ให้ตัวเองคลายร้อน"}],"partOfSpeech":["measure word","verb","noun"]},
  {"id":"hsk5-949","chinese":"擅长","pinyin":"shàncháng","meaning":"to be good at; to be expert in","meaningThai":"เก่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们需要擅长管理的人。","pinyin":"Wǒ mén xū yào shàn cháng guǎn lǐ de rén。","meaning":"We need people who are good at managing.","meaningThai":"เราต้องการคนที่เก่งในการจัดการ"},{"chinese":"她擅长美术和设计。","pinyin":"Tā shàn cháng měi shù hé shè jì。","meaning":"She's good at art and design.","meaningThai":"เธอเก่งด้านศิลปะและการออกแบบ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-950","chinese":"删除","pinyin":"shānchú","meaning":"to delete; to cancel","meaningThai":"ลบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这一指令把文档从目录中删除。","pinyin":"Zhè yī zhǐ líng bǎ wén dàng cóng mù lù zhōng shān chú。","meaning":"This command deletes files from the directory.","meaningThai":"คำสั่งนี้จะลบไฟล์ออกจากไดเร็กทอรี"},{"chinese":"他也从计算机系统中删除了文件。","pinyin":"Tā yě cóng jì suàn jī xì tǒng zhōng shān chú le wén jiàn。","meaning":"He also deleted files from the computer system.","meaningThai":"เขายังลบไฟล์ออกจากระบบคอมพิวเตอร์ด้วย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-951","chinese":"赏","pinyin":"shǎng","meaning":"to bestow (a reward); to give (to an inferior); to hand down; a reward (bestowed by a superior); to appreciate (beauty)","meaningThai":"รางวัล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"设计得要雅俗共赏，老幼皆宜。","pinyin":"Shè jì dé yào yǎ sú gòng shǎng， lǎo yòu jiē yí。","meaning":"The design has to appeal to all ages and social groups.","meaningThai":"การออกแบบต้องดึงดูดทุกวัยและทุกกลุ่มสังคม"},{"chinese":"那里提供的活动包括赏鲸、远足，并且住宿旨在减少对自然环境的影响。","pinyin":"Nà lǐ tí gōng de huó dòng bāo kuò shǎng jīng、 yuǎn zú， bìng qiě zhù sù zhǐ zài jiǎn shǎo duì zì rán huán jìng de yǐng xiǎng。","meaning":"Activities there range from whale watching to hiking and accommodations aim to have a low impact on the natural environment.","meaningThai":"กิจกรรมต่างๆ มีตั้งแต่การดูปลาวาฬไปจนถึงการเดินป่า และที่พักมีเป้าหมายที่จะมีผลกระทบต่อสภาพแวดล้อมทางธรรมชาติเพียงเล็กน้อย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-952","chinese":"伤","pinyin":"shāng","meaning":"to injure; injury; wound","meaningThai":"เจ็บ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个队因伤实力减弱。","pinyin":"Zhè gè duì yīn shāng shí lì jiǎn ruò。","meaning":"The team has been weakened by injury.","meaningThai":"ทำให้ทีมอ่อนแอลงจากอาการบาดเจ็บ"},{"chinese":"他害怕伤我的感情。","pinyin":"Tā hài pà shāng wǒ de gǎn qíng。","meaning":"He was afraid of hurting my feelings.","meaningThai":"เขากลัวที่จะทำร้ายความรู้สึกของฉัน"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-953","chinese":"上传","pinyin":"shàngchuán","meaning":"upload","meaningThai":"อัปโหลด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你所需要做的只是把文件上传到你的网络空间。","pinyin":"Nǐ suǒ xū yào zuò de zhī shì bǎ wén jiàn shàng chuán dào nǐ de wǎng luò kōng jiān。","meaning":"All you need to do is upload the files on to your web space.","meaningThai":"สิ่งที่คุณต้องทำคืออัปโหลดไฟล์ไปยังพื้นที่เว็บของคุณ"},{"chinese":"一旦您修改了这个文件，通过 RAM 来上传它。","pinyin":"Yī dàn nín xiū gǎi le zhè gè wén jiàn， tōng guò  RAM  lái shàng chuán tā。","meaning":"Once you modify this file, upload it via RAM.","meaningThai":"เมื่อคุณแก้ไขไฟล์นี้แล้ว ให้อัปโหลดผ่าน RAM"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-954","chinese":"伤害","pinyin":"shānghài","meaning":"to injure; to harm","meaningThai":"อันตราย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"许多保单都列明不保障人身伤害。","pinyin":"Xǔ duō bǎo dān dū liè míng bù bǎo zhàng rén shēn shāng hài。","meaning":"Many policies do not protect you against personal injury.","meaningThai":"กรมธรรม์หลายฉบับไม่ได้คุ้มครองคุณจากการบาดเจ็บส่วนบุคคล"},{"chinese":"她不能相信他希望她受到伤害。","pinyin":"Tā bù néng xiāng xìn tā xī wàng tā shòu dào shāng hài。","meaning":"She could not believe that he wished her harm.","meaningThai":"เธอไม่อยากจะเชื่อเลยว่าเขาต้องการทำร้ายเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-955","chinese":"商家","pinyin":"shāngjiā","meaning":"Merchant","meaningThai":"พ่อค้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"当地商家迫于威胁缴纳了保护费。","pinyin":"Dāng dì shāng jiā pò yú wēi xié jiǎo nà le bǎo hù fèi。","meaning":"Local businesses were scared into paying protection money.","meaningThai":"ธุรกิจในท้องถิ่นกลัวที่จะจ่ายเงินคุ้มครอง"},{"chinese":"消费者花钱少了，商家感到手头拮据。","pinyin":"Xiāo fèi zhě huā qián shǎo le， shāng jiā gǎn dào shǒu tóu jié jù。","meaning":"Consumers are spending less and merchants are feeling the pinch.","meaningThai":"ผู้บริโภคใช้จ่ายน้อยลงและร้านค้าก็รู้สึกลำบากใจ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-956","chinese":"商人","pinyin":"shāngrén","meaning":"merchant; businessman","meaningThai":"พ่อค้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他声称那个商人骗了他1万美元。","pinyin":"Tā shēng chēng nà gè shāng rén piàn le tā 1 wàn měi yuán。","meaning":"He claimed that the businessman had conned him of $10,000.","meaningThai":"เขาอ้างว่านักธุรกิจรายนี้หลอกเขาไป 10,000 ดอลลาร์"},{"chinese":"这种态度对大多数商人都很陌生。","pinyin":"Zhè zhǒng tài dù duì dà duō shù shāng rén dū hěn mò shēng。","meaning":"Such an attitude is alien to most businessmen.","meaningThai":"ทัศนคติดังกล่าวเป็นเรื่องแปลกสำหรับนักธุรกิจส่วนใหญ่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-957","chinese":"上升","pinyin":"shàngshēng","meaning":"to rise; to go up; to ascend","meaningThai":"ลุกขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"犯罪数字正在迅速上升。","pinyin":"Fàn zuì shù zì zhèng zài xùn sù shàng shēng。","meaning":"Crime figures are rising rapidly.","meaningThai":"ตัวเลขอาชญากรรมเพิ่มขึ้นอย่างรวดเร็ว"},{"chinese":"利率从4%上升到5%。","pinyin":"Lì shuài cóng 4% shàng shēng dào5%。","meaning":"Interest rates rise from 4% to 5%.","meaningThai":"อัตราดอกเบี้ยเพิ่มขึ้นจาก 4% เป็น 5%"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-958","chinese":"商务","pinyin":"shāngwù","meaning":"commercial affairs; commercial; commerce; business","meaningThai":"ธุรกิจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这项工作适合有商务经验的人。","pinyin":"Zhè xiàng gōng zuò shì hé yǒu shāng wù jīng yàn de rén。","meaning":"The job would suit someone with a business background.","meaningThai":"งานนี้จะเหมาะกับคนที่มีพื้นฐานทางธุรกิจ"},{"chinese":"你可以花钱调换到商务舱的座位。","pinyin":"Nǐ kě yǐ huā qián tiáo huàn dào shāng wù cāng de zuò wèi。","meaning":"You can pay to be upgraded to a business class seat.","meaningThai":"คุณสามารถชำระเงินเพื่ออัปเกรดเป็นที่นั่งชั้นธุรกิจได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-959","chinese":"上下","pinyin":"shàngxià","meaning":"up and down; top and bottom; old and young; length; about","meaningThai":"ขึ้นและลง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她喊着让小孩从墙上下来。","pinyin":"Tā hǎn zháo ràng xiǎo hái cóng qiáng shàng xià lái。","meaning":"She yelled at the child to get down from the wall.","meaningThai":"เธอตะโกนบอกเด็กให้ลงจากกำแพง"},{"chinese":"巨大的气球在上空上下浮动。","pinyin":"Jù dà de qì qiú zài shàng kōng shàng xià fú dòng。","meaning":"Huge balloons bobbed about in the sky above.","meaningThai":"ลูกโป่งขนาดใหญ่ลอยอยู่บนท้องฟ้าเบื้องบน"}],"partOfSpeech":["other","noun","numeral","verb"]},
  {"id":"hsk5-960","chinese":"商业","pinyin":"shāngyè","meaning":"business; trade; commerce","meaningThai":"ธุรกิจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"直到1920年才有了商业电台。","pinyin":"Zhí dào 1920 nián cái yǒu le shāng yè diàn tái。","meaning":"There were no commercial radio stations until 1920.","meaningThai":"ไม่มีสถานีวิทยุเชิงพาณิชย์จนกระทั่งปี พ.ศ. 2463"},{"chinese":"艺术不该和商业成为错误的同盟。","pinyin":"Yì shù bù gāi hé shāng yè chéng wéi cuò wù de tóng méng。","meaning":"Art shouldn't enter an unholy alliance with business.","meaningThai":"ศิลปะไม่ควรเข้าร่วมเป็นพันธมิตรที่ไม่บริสุทธิ์กับธุรกิจ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-961","chinese":"上涨","pinyin":"shàngzhǎng","meaning":"to rise; to go up","meaningThai":"ลุกขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"预计房价会急剧上涨。","pinyin":"Yù jì fáng jià huì jí jù shàng zhǎng。","meaning":"House prices are expected to rise sharply.","meaningThai":"คาดว่าราคาบ้านจะสูงขึ้นอย่างรวดเร็ว"},{"chinese":"预计地产价格会上涨。","pinyin":"Yù jì dì chǎn jià gé huì shàng zhǎng。","meaning":"The expectation is that property prices will rise.","meaningThai":"ความคาดหวังก็คือราคาทรัพย์สินจะสูงขึ้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-962","chinese":"善良","pinyin":"shànliáng","meaning":"good and honest; kindhearted","meaningThai":"ใจดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我爱上了他，因为他天性善良。","pinyin":"Wǒ ài shàng le tā， yīn wéi tā tiān xìng shàn liáng。","meaning":"I fell in love with him because of his kind nature.","meaningThai":"ฉันตกหลุมรักเขาเพราะนิสัยใจดีของเขา"},{"chinese":"她似乎是善良和高贵的化身。","pinyin":"Tā sì hū shì shàn liáng hé gāo guì de huà shēn。","meaning":"She seemed to personify goodness and nobility.","meaningThai":"ดูเหมือนเธอจะแสดงถึงความดีและความสง่างาม"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-963","chinese":"山区","pinyin":"shānqū","meaning":"mountain area","meaningThai":"พื้นที่ภูเขา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"居住在山区的大猩猩已濒临灭绝。","pinyin":"Jū zhù zài shān qū de dà xīng xīng yǐ bīn lín miè jué。","meaning":"The mountain gorilla is on the verge of extinction.","meaningThai":"กอริลลาภูเขาใกล้จะสูญพันธุ์"},{"chinese":"在偏远山区，选民们是骑着马来的。","pinyin":"Zài piān yuǎn shān qū， xuǎn mín mén shì qí zháo mǎ lái de。","meaning":"In remote mountain areas, voters arrived on horseback.","meaningThai":"ในพื้นที่ภูเขาห่างไกล ผู้ลงคะแนนเสียงมาถึงบนหลังม้า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-964","chinese":"善于","pinyin":"shànyú","meaning":"to be good at; to be adept at","meaningThai":"เก่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她很善于鉴定别人的性格。","pinyin":"Tā hěn shàn yú jiàn dìng bié rén de xìng gé。","meaning":"She's a good judge of character.","meaningThai":"เธอเป็นผู้ตัดสินตัวละครที่ดี"},{"chinese":"他善于照顾自己的利益。","pinyin":"Tā shàn yú zhào gù zì jǐ de lì yì。","meaning":"He's good at looking after his own interests.","meaningThai":"เขาเก่งเรื่องการดูแลผลประโยชน์ของตัวเอง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-965","chinese":"扇子","pinyin":"shànzi","meaning":"fan","meaningThai":"พัดลม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她做了一个扇扇子的动作，假装使自己凉快一些。","pinyin":"Tā zuò le yī gè shàn shàn zǐ de dòng zuò， jiǎ zhuāng shǐ zì jǐ liáng kuài yī xiē。","meaning":"She made a fanning motion, pretending to cool herself off.","meaningThai":"เธอทำท่าพัด แสร้งทำเป็นทำตัวเองให้เย็นลง"},{"chinese":"你忘带你的雨伞和扇子啦！","pinyin":"Nǐ wàng dài nǐ de yǔ sǎn hé shàn zǐ lā！","meaning":"You forgot your umbrella and fan!","meaningThai":"คุณลืมร่มและพัดลม!"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-966","chinese":"烧","pinyin":"shāo","meaning":"to burn; to cook; to stew; to bake; to roast; to heat; to boil (tea, water etc); fever; to run a temperature; (coll.) to let things go to one's head","meaningThai":"เผา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这支蜡烛已全烧完了。","pinyin":"Zhè zhī là zhú yǐ quán shāo wán le。","meaning":"The candle had burned right down.","meaningThai":"เทียนก็ดับลงทันที"},{"chinese":"这些蔬菜烧的火候恰到好处。","pinyin":"Zhè xiē shū cài shāo de huǒ hòu qià dào hǎo chǔ。","meaning":"The vegetables were cooked to perfection.","meaningThai":"ผักถูกปรุงจนสมบูรณ์แบบ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-967","chinese":"烧烤","pinyin":"shāokǎo","meaning":"barbecue; to roast","meaningThai":"บาร์บีคิว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我喜欢烧烤食物。","pinyin":"Wǒ xǐ huān shāo kǎo shí wù。","meaning":"I love barbecue.","meaningThai":"ฉันรักบาร์บีคิว"},{"chinese":"我们星期天要去烧烤。","pinyin":"Wǒ mén xīng qī tiān yào qù shāo kǎo。","meaning":"We're having a barbeque on Sunday.","meaningThai":"เราจะมีบาร์บีคิวในวันอาทิตย์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-968","chinese":"沙子","pinyin":"shāzi","meaning":"sand; grit","meaningThai":"ทราย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们在结冰的路上撒沙子和盐。","pinyin":"Tā mén zài jié bīng de lù shàng sā shā zǐ hé yán。","meaning":"They were spreading grit and salt on the icy roads.","meaningThai":"พวกเขากำลังโปรยกรวดและเกลือบนถนนน้ำแข็ง"},{"chinese":"她用脚趾拨弄着板结的沙子。","pinyin":"Tā yòng jiǎo zhǐ bō nòng zháo bǎn jié de shā zǐ。","meaning":"She wiggled her toes against the packed sand.","meaningThai":"เธอขยับเท้าไปกับทรายที่อัดแน่น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-969","chinese":"蛇","pinyin":"shé","meaning":"variant of 蛇","meaningThai":"งู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"蛇没有脚。","pinyin":"Shé méi yǒu jiǎo.","meaning":"Snakes don't have feet.","meaningThai":"งูไม่มีเท้า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-970","chinese":"设备","pinyin":"shèbèi","meaning":"equipment; facilities; installations","meaningThai":"อุปกรณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"所有设备都应该定期彻底打扫。","pinyin":"Suǒ yǒu shè bèi dū yīng gāi dìng qī chè dǐ dǎ sǎo。","meaning":"All the equip we are pirates, these data are stolen from youdao  should be cleaned down regularly.","meaningThai":"อุปกรณ์ทั้งหมดควรได้รับการทำความสะอาดอย่างทั่วถึงและสม่ำเสมอ"},{"chinese":"这种设备仍处于试验阶段。","pinyin":"Zhè zhǒng shè bèi réng chǔ yú shì yàn jiē duàn。","meaning":"The equip we are pirates, these data are stolen from youdao  is still at the experi we are pirates, these data are stolen from youdao al stage.","meaningThai":"อุปกรณ์นี้ยังอยู่ในขั้นทดลอง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-971","chinese":"舍不得","pinyin":"shěbude","meaning":"to hate to do sth; to hate to part with; to begrudge","meaningThai":"ไม่กล้าที่จะแยกทางกับมัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"玛丽几乎舍不得离开他。","pinyin":"Mǎ lì jī hū shě bù dé lí kāi tā。","meaning":"Mary could scarcely bear to leave him.","meaningThai":"แมรี่แทบทนไม่ไหวที่จะทิ้งเขาไป"},{"chinese":"开饭了，别舍不得离开电视了。","pinyin":"Kāi fàn le， bié shě bù dé lí kāi diàn shì le。","meaning":"Dinner's ready, if you can tear yourself away from the TV.","meaningThai":"อาหารเย็นพร้อมแล้ว หากคุณสามารถแยกตัวออกจากทีวีได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-972","chinese":"舍得","pinyin":"shěde","meaning":"to be willing to part with sth","meaningThai":"เต็มใจที่จะยอมแพ้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你父母舍得你离开家吗？","pinyin":"Nǐ fù mǔ shě dé nǐ lí kāi jiā ma？","meaning":"Do your parents mind you leaving home?","meaningThai":"พ่อแม่ของคุณรังเกียจที่จะออกจากบ้านไหม?"},{"chinese":"舍得花钱去筹到更多的资金。","pinyin":"Shě dé huā qián qù chóu dào gēng duō de zī jīn。","meaning":"Spend money to raise mone.","meaningThai":"ใช้เงินเพื่อหาเงิน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-973","chinese":"设计","pinyin":"shèjì","meaning":"to design; to plan; design; plan","meaningThai":"ออกแบบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我已对设计作了几处调整。","pinyin":"Wǒ yǐ duì shè jì zuò le jī chǔ tiáo zhěng。","meaning":"I've made a few adjustments to the design.","meaningThai":"ฉันได้ทำการปรับเปลี่ยนการออกแบบเล็กน้อย"},{"chinese":"迈克负责设计全部工程。","pinyin":"Mài kè fù zé shè jì quán bù gōng chéng。","meaning":"Mike is responsible for designing the entire project.","meaningThai":"ไมค์รับผิดชอบในการออกแบบโครงการทั้งหมด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-974","chinese":"设立","pinyin":"shèlì","meaning":"to set up; to establish","meaningThai":"ตั้งค่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"它为减少温室气体排放设立了目标。","pinyin":"Tā wéi jiǎn shǎo wēn shì qì tǐ pái fàng shè lì le mù biāo。","meaning":"It sets targets for reduction of greenhouse-gas emissions.","meaningThai":"โดยกำหนดเป้าหมายในการลดการปล่อยก๊าซเรือนกระจก"},{"chinese":"每所学校都设立自己的入学政策。","pinyin":"Měi suǒ xué xiào dū shè lì zì jǐ de rù xué zhèng cè。","meaning":"Each school sets its own admissions policy.","meaningThai":"แต่ละโรงเรียนจะกำหนดนโยบายการรับเข้าเรียนของตนเอง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-975","chinese":"伸","pinyin":"shēn","meaning":"to stretch; to extend","meaningThai":"ยืด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"起司非常能伸展。","pinyin":"Qǐ sī fēi cháng néng shēn zhǎn。","meaning":"The cheese is very stretchy.","meaningThai":"ชีสยืดมาก"},{"chinese":"他伸长了他的右手。","pinyin":"Tā shēn cháng le tā de yòu shǒu。","meaning":"He extended his right arm.","meaningThai":"เขาขยายแขนขวาของเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-976","chinese":"身材","pinyin":"shēncái","meaning":"stature; build (height and weight); figure","meaningThai":"รูป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"母亲身材娇小，仅有5英尺高。","pinyin":"Mǔ qīn shēn cái jiāo xiǎo， jǐn yǒu 5 yīng chǐ gāo。","meaning":"Mother was of very small stature, barely five feet tall.","meaningThai":"แม่มีรูปร่างที่เล็กมาก สูงเพียงห้าฟุตเท่านั้น"},{"chinese":"我身材中等，但还是觉得胖了些。","pinyin":"Wǒ shēn cái zhōng děng， dàn huán shì jué dé pàng le xiē。","meaning":"I'm average for my height. But I still feel I'm fatter than I should be.","meaningThai":"ฉันถือว่าสูงปานกลาง แต่ฉันก็ยังรู้สึกว่าตัวเองอ้วนกว่าที่ควรจะเป็น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-977","chinese":"深度","pinyin":"shēndù","meaning":"depth; (of a speech etc) profundity; advanced stage of development","meaningThai":"ความลึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们测量了这条河的深度。","pinyin":"Wǒ mén cè liáng le zhè tiáo hé de shēn dù。","meaning":"We measured the depth of the river.","meaningThai":"เราวัดความลึกของแม่น้ำ"},{"chinese":"患者现在处于深度昏迷状态。","pinyin":"Huàn zhě xiàn zài chǔ yú shēn dù hūn mí zhuàng tài。","meaning":"The patient is in a state of profound stupor. / The patient is in a deep coma.","meaningThai":"ผู้ป่วยอยู่ในอาการมึนงงอย่างรุนแรง /ผู้ป่วยอยู่ในอาการโคม่าลึก."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-978","chinese":"身份","pinyin":"shēnfèn","meaning":"identity; aspect of one's identity (i.e. sth that one is – mayor, father, permanent resident etc); role; capacity (as in \"in his capacity as a ...\" 以…份); status (social, legal etc); position; rank","meaningThai":"ตัวตน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她是无辜的；那是身份判断错误。","pinyin":"Tā shì wú gū de； nà shì shēn fèn pàn duàn cuò wù。","meaning":"She is innocent; it was a case of mistaken identity.","meaningThai":"เธอไร้เดียงสา มันเป็นกรณีของการระบุตัวตนที่ผิดพลาด"},{"chinese":"他严密地保守她的身份。","pinyin":"Tā yán mì dì bǎo shǒu tā de shēn fèn。","meaning":"He closely guarded her identity.","meaningThai":"เขาปกป้องตัวตนของเธออย่างใกล้ชิด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-979","chinese":"胜","pinyin":"shèng","meaning":"victory; success; to beat; to defeat; to surpass; victorious; superior to; to get the better of; better than; surpassing; superb (of vista); beautiful (scenery); wonderful (view); (Taiwan pr. [shēng]) able to bear; equal to (a task)","meaningThai":"ชนะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"法国队以6:2狂胜丹麦队。","pinyin":"Fǎ guó duì yǐ 6:2 kuáng shèng dān mài duì。","meaning":"France swept to a 6–2 win over Denmark.","meaningThai":"ฝรั่งเศสกวาดชัยชนะเหนือเดนมาร์ก 6–2"},{"chinese":"她的新系列节目引人入胜。","pinyin":"Tā de xīn xì liè jié mù yǐn rén rù shèng。","meaning":"Her new series is compulsive viewing.","meaningThai":"ซีรีส์ใหม่ของเธอคือการรับชมแบบบังคับ"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-980","chinese":"省","pinyin":"shěng","meaning":"to save; to economize; to be frugal; to omit; to delete; to leave out; province; provincial capital; a ministry (of the Japanese government)","meaningThai":"จังหวัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"云南省在中国西南部。","pinyin":"Yúnnánshěng zài zhōngguó xīnánbù.","meaning":"Yunnan Province is in southwestern China.","meaningThai":"มณฑลยูนนานอยู่ทางตะวันตกเฉียงใต้ของจีน"},{"chinese":"中国有很多省。","pinyin":"Zhōngguó yǒu hěnduō shěng.","meaning":"China has many provinces.","meaningThai":"ประเทศจีนมีหลายจังหวัด"},{"chinese":"他来自山东省。","pinyin":"Tā láizì shāndōngshěng.","meaning":"He comes from Shandong Province.","meaningThai":"เขามาจากมณฑลซานตง"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-981","chinese":"升","pinyin":"shēng","meaning":"to ascend; to rise to the rank of; to promote; to hoist; liter; measure for dry grain equal to one-tenth dou 斗","meaningThai":"ยก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"两个水箱的总容量为400升。","pinyin":"Liǎng gè shuǐ xiāng de zǒng róng liáng wéi 400 shēng。","meaning":"Two water tanks provide a total capacity of 400 litres.","meaningThai":"ถังเก็บน้ำ 2 ใบมีความจุรวม 400 ลิตร"},{"chinese":"村民每天的用水量限定为两升。","pinyin":"Cūn mín měi tiān de yòng shuǐ liáng xiàn dìng wéi liǎng shēng。","meaning":"The villagers are rationed to two litres of water a day.","meaningThai":"ชาวบ้านได้รับปันส่วนน้ำวันละสองลิตร"}],"partOfSpeech":["verb","measure word"]},
  {"id":"hsk5-982","chinese":"生产","pinyin":"shēngchǎn","meaning":"to produce; to manufacture; to give birth to a child","meaningThai":"การผลิต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"新飞机的生产将于明年开始。","pinyin":"Xīn fēi jī de shēng chǎn jiāng yú míng nián kāi shǐ。","meaning":"Production of the new aircraft will start next year.","meaningThai":"การผลิตเครื่องบินใหม่จะเริ่มในปีหน้า"},{"chinese":"罢工已经使生产陷于停顿。","pinyin":"Bà gōng yǐ jīng shǐ shēng chǎn xiàn yú tíng dùn。","meaning":"Strikes have led to a halt in production.","meaningThai":"การนัดหยุดงานส่งผลให้ต้องหยุดการผลิต"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-983","chinese":"生存","pinyin":"shēngcún","meaning":"to exist; to survive","meaningThai":"รอดชีวิต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那次手术是凯利生存的唯一希望。","pinyin":"Nà cì shǒu shù shì kǎi lì shēng cún de wéi yī xī wàng。","meaning":"The operation was Kelly's only hope of survival.","meaningThai":"การผ่าตัดครั้งนี้เป็นความหวังเดียวในการอยู่รอดของเคลลี่"},{"chinese":"没有资产净值，任何公司都无法生存。","pinyin":"Méi yǒu zī chǎn jìng zhí， rèn hé gōng sī dū wú fǎ shēng cún。","meaning":"No business can survive without a capital account.","meaningThai":"ไม่มีธุรกิจใดที่สามารถอยู่รอดได้หากไม่มีบัญชีเงินทุน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-984","chinese":"生动","pinyin":"shēngdòng","meaning":"vivid; lively","meaningThai":"สดใส","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"报告生动地描绘了都市生活。","pinyin":"Bào gào shēng dòng dì miáo huì le dū shì shēng huó。","meaning":"The report paints a vivid picture of life in the city.","meaningThai":"รายงานดังกล่าวแสดงให้เห็นภาพชีวิตในเมืองที่สดใส"},{"chinese":"这本书生动地表现了墨西哥的生活。","pinyin":"Zhè běn shū shēng dòng dì biǎo xiàn le mò xī gē de shēng huó。","meaning":"The book gives us fascinating insights into life in Mexico.","meaningThai":"หนังสือเล่มนี้ให้ข้อมูลเชิงลึกอันน่าทึ่งเกี่ยวกับชีวิตในเม็กซิโก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-985","chinese":"省份","pinyin":"shěngfèn","meaning":"province","meaningThai":"จังหวัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"熊猫在四川省土生土长，不在任何其他省份的野外生活。","pinyin":"Xióng māo zài sì chuān shěng tǔ shēng tǔ cháng， bù zài rèn hé qí tā shěng fèn de yě wài shēng huó。","meaning":"The panda is indigenous to Sichuan Province and does not live in the wild in any other places.","meaningThai":"แพนด้ามีถิ่นกำเนิดในมณฑลเสฉวนและไม่ได้อาศัยอยู่ในป่าที่อื่น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-986","chinese":"省会","pinyin":"shěnghuì","meaning":"provincial capital","meaningThai":"เมืองหลวงของจังหวัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"蒙特利尔是该省的省会城市吗？","pinyin":"Mēng tè lì ěr shì gāi shěng de shěng huì chéng shì ma？","meaning":"Is Montreal the capital city of the province?","meaningThai":"มอนทรีออลเป็นเมืองหลวงของจังหวัดหรือไม่"},{"chinese":"辽宁省省会为沈阳。","pinyin":"Liáo níng shěng shěng huì wéi shěn yáng。","meaning":"Shenyang is the provincial capital of Liaoning.","meaningThai":"เสิ่นหยางเป็นเมืองหลวงของมณฑลเหลียวหนิง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-987","chinese":"升级","pinyin":"shēngjí","meaning":"to go up by one grade; to be promoted; to escalate (in intensity); (computing) to upgrade","meaningThai":"อัพเกรด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"医疗设施正在进行重组和升级。","pinyin":"Yī liáo shè shī zhèng zài jìn háng zhòng zǔ hé shēng jí。","meaning":"Medical facilities are being reorganized and upgraded.","meaningThai":"สิ่งอำนวยความสะดวกทางการแพทย์กำลังได้รับการจัดระเบียบและอัปเกรดใหม่"},{"chinese":"直升机已经升级并且装上现代化设备。","pinyin":"Zhí shēng jī yǐ jīng shēng jí bìng qiě zhuāng shàng xiàn dài huà shè bèi。","meaning":"Helicopters have been upgraded and modernized.","meaningThai":"เฮลิคอปเตอร์ได้รับการอัพเกรดและปรับปรุงให้ทันสมัย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-988","chinese":"胜利","pinyin":"shènglì","meaning":"victory","meaningThai":"ชัยชนะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"胜利将确保他们能参加决赛。","pinyin":"Shèng lì jiāng què bǎo tā mén néng cān jiā jué sài。","meaning":"Victory would assure them a place in the finals.","meaningThai":"ชัยชนะจะทำให้พวกเขาผ่านเข้าสู่รอบชิงชนะเลิศได้"},{"chinese":"他们希望重复去年的胜利。","pinyin":"Tā mén xī wàng zhòng fù qù nián de shèng lì。","meaning":"They are hoping to repeat last year's victory.","meaningThai":"พวกเขาหวังที่จะทำซ้ำชัยชนะของปีที่แล้ว"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-989","chinese":"升温","pinyin":"shēngwēn","meaning":"to become hot; temperature rise; (fig.) to intensify; to hot up; to escalate; to get a boost","meaningThai":"ร้อนขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"政治气氛也明显升温。","pinyin":"Zhèng zhì qì fēn yě míng xiǎn shēng wēn。","meaning":"There's also been a noticeable rise in the political temperature.","meaningThai":"อุณหภูมิทางการเมืองก็เพิ่มขึ้นอย่างเห็นได้ชัดเช่นกัน"},{"chinese":"然而，最近一次这样的升温发生在两年前。","pinyin":"Rán ér， zuì jìn yī cì zhè yàng de shēng wēn fā shēng zài liǎng nián qián。","meaning":"However, the last such increase in temperature took place two years ago.","meaningThai":"อย่างไรก็ตาม อุณหภูมิที่เพิ่มขึ้นครั้งสุดท้ายเกิดขึ้นเมื่อสองปีก่อน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-990","chinese":"生物","pinyin":"shēngwù","meaning":"organism; living creature; life form; biological","meaningThai":"ชีววิทยา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们明天有生物考试。","pinyin":"Wǒ men míng tiān yǒu shēng wù kǎo shì.","meaning":"We have a biology exam tomorrow.","meaningThai":"พรุ่งนี้เรามีสอบชีววิทยา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-991","chinese":"生肖","pinyin":"shēngxiào","meaning":"Chinese Zodiac","meaningThai":"จักรราศีจีน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"问题是，没有真正的新生肖。","pinyin":"Wèn tí shì， méi yǒu zhēn zhèng de xīn shēng xiāo。","meaning":"The problem is that there is no actual new zodiac.","meaningThai":"ปัญหาคือไม่มีราศีใหม่เกิดขึ้นจริง"},{"chinese":"猪是中国十二生肖中的第十二个生肖。","pinyin":"Zhū shì zhōng guó shí èr shēng xiāo zhōng de dì shí èr gè shēng xiāo。","meaning":"The pig is the twelfth sign in the Chinese zodiac cycle.","meaningThai":"หมูเป็นราศีที่สิบสองในวัฏจักรนักษัตรจีน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-992","chinese":"生长","pinyin":"shēngzhǎng","meaning":"to grow; to grow up; to be brought up","meaningThai":"เติบโต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"给植物施肥以促进其不断生长。","pinyin":"Gěi zhí wù shī féi yǐ cù jìn qí bù duàn shēng cháng。","meaning":"Feed plants to encourage steady growth.","meaningThai":"ให้อาหารพืชเพื่อส่งเสริมการเติบโตอย่างต่อเนื่อง"},{"chinese":"它们的年龄可从其生长速度来推定。","pinyin":"Tā mén de nián líng kě cóng qí shēng cháng sù dù lái tuī dìng。","meaning":"Their age can be determined by extrapolation from their growth rate.","meaningThai":"อายุของพวกเขาสามารถกำหนดได้โดยการอนุมานจากอัตราการเติบโต"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-993","chinese":"深厚","pinyin":"shēnhòu","meaning":"deep; profound","meaningThai":"ลึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"最后，我想借此机会请汤姆逊教授转达我们深厚的友谊，并表示对他的同胞良好的祝愿。","pinyin":"Zuì hòu， wǒ xiǎng jiè cǐ jī huì qǐng tāng mǔ xùn jiào shòu zhuǎn dá wǒ mén shēn hòu de yǒu yì， bìng biǎo shì duì tā de tóng bāo liáng hǎo de zhù yuàn。","meaning":"Finally, we want to take this opportunity to beg him to convey our profound friendship and best regards to his people.","meaningThai":"สุดท้ายเราต้องการใช้โอกาสนี้เพื่อขอร้องให้เขาถ่ายทอดมิตรภาพอันลึกซึ้งของเราและขอแสดงความนับถือต่อผู้คนของเขา"},{"chinese":"他每天给她写信，他对她的爱情如此深厚。","pinyin":"Tā měi tiān gěi tā xiě xìn， tā duì tā de ài qíng rú cǐ shēn hòu。","meaning":"He wrote to her every day; such was his love for her.","meaningThai":"เขาเขียนถึงเธอทุกวันนั่นคือความรักที่เขามีต่อเธอ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-994","chinese":"神话","pinyin":"shénhuà","meaning":"legend; fairy tale; myth; mythology","meaningThai":"ตำนาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些神话彼此有惊人的相似之处。","pinyin":"Zhè xiē shén huà bǐ cǐ yǒu jīng rén de xiāng sì zhī chǔ。","meaning":"These myths have a startling likeness to one another.","meaningThai":"ตำนานเหล่านี้มีความคล้ายคลึงกันที่น่าตกใจ"},{"chinese":"分清神话和现实是不可能的。","pinyin":"Fēn qīng shén huà hé xiàn shí shì bù kě néng de。","meaning":"It's impossible to disentangle the myth from reality.","meaningThai":"เป็นไปไม่ได้ที่จะแยกความเชื่อผิดๆ ออกจากความเป็นจริง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-995","chinese":"深刻","pinyin":"shēnkè","meaning":"profound; deep; deep-going","meaningThai":"ลึกซึ้ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"它给我留下了非常深刻的印象。","pinyin":"Tā gěi wǒ liú xià le fēi cháng shēn kè de yìn xiàng。","meaning":"It made a very forceful impression on me.","meaningThai":"มันทำให้ฉันประทับใจมาก"},{"chinese":"他们的勤奋给我们留下深刻印象。","pinyin":"Tā mén de qín fèn gěi wǒ mén liú xià shēn kè yìn xiàng。","meaning":"We were impressed by their industry.","meaningThai":"เราประทับใจกับอุตสาหกรรมของพวกเขา"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-996","chinese":"神秘","pinyin":"shénmì","meaning":"mysterious; mystery","meaningThai":"ความลึกลับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"几条信息已经神秘地消失了。","pinyin":"Jī tiáo xìn xī yǐ jīng shén mì dì xiāo shī le。","meaning":"A couple of messages had mysteriously disappeared.","meaningThai":"ข้อความสองสามข้อความหายไปอย่างลึกลับ"},{"chinese":"这墨镜使她显得有些神秘。","pinyin":"Zhè mò jìng shǐ tā xiǎn dé yǒu xiē shén mì。","meaning":"The dark glasses give her an air of mystery.","meaningThai":"แว่นตาดำทำให้เธอมีบรรยากาศแห่งความลึกลับ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-997","chinese":"深入","pinyin":"shēnrù","meaning":"to penetrate deeply; thorough","meaningThai":"ลึกลงไป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们可以把辩论更深入一步。","pinyin":"Wǒ mén kě yǐ bǎ biàn lùn gēng shēn rù yī bù。","meaning":"We can take the argument one stage further.","meaningThai":"เราสามารถนำข้อโต้แย้งนี้ไปอีกขั้นหนึ่ง"},{"chinese":"没有机会进行深入讨论了。","pinyin":"Méi yǒu jī huì jìn háng shēn rù tǎo lùn le。","meaning":"There was no opportunity for further discussion.","meaningThai":"ไม่มีโอกาสในการหารือเพิ่มเติม"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-998","chinese":"深远","pinyin":"shēnyuǎn","meaning":"far-reaching; profound and long-lasting","meaningThai":"กว้างขวาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的讲话对每个人都有深远的影响。","pinyin":"Tā de jiǎng huà duì měi gè rén dū yǒu shēn yuǎn de yǐng xiǎng。","meaning":"Her speech made a profound impact on everyone.","meaningThai":"คำพูดของเธอส่งผลกระทบอย่างลึกซึ้งต่อทุกคน"},{"chinese":"除非实施影响深远的改革，否则经济就有崩溃的危险。","pinyin":"Chú fēi shí shī yǐng xiǎng shēn yuǎn de gǎi gé， fǒu zé jīng jì jiù yǒu bēng kuì de wēi xiǎn。","meaning":"The economy is in danger of collapse unless far-reaching reforms are implemented.","meaningThai":"เศรษฐกิจตกอยู่ในอันตรายจากการล่มสลายเว้นแต่จะมีการปฏิรูปในวงกว้าง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-999","chinese":"社区","pinyin":"shèqū","meaning":"community; neighborhood","meaningThai":"ชุมชน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"新的社区中心在昨天隆重落成。","pinyin":"Xīn de shè qū zhōng xīn zài zuó tiān lóng zhòng luò chéng。","meaning":"The new community center was inaugurated yesterday with pomp and circumstance.","meaningThai":"ศูนย์ชุมชนแห่งใหม่เปิดตัวเมื่อวานนี้ด้วยความเอิกเกริกและสถานการณ์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1000","chinese":"设施","pinyin":"shèshī","meaning":"facilities; installation","meaningThai":"สิ่งอำนวยความสะดวก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这家酒店提供各种各样的设施。","pinyin":"Zhè jiā jiǔ diàn tí gōng gè zhǒng gè yàng de shè shī。","meaning":"The hotel offers a wide range of facilities.","meaningThai":"โรงแรมมีสิ่งอำนวยความสะดวกที่หลากหลาย"},{"chinese":"医疗设施正在进行重组和升级。","pinyin":"Yī liáo shè shī zhèng zài jìn háng zhòng zǔ hé shēng jí。","meaning":"Medical facilities are being reorganized and upgraded.","meaningThai":"สิ่งอำนวยความสะดวกทางการแพทย์กำลังได้รับการจัดระเบียบและอัปเกรดใหม่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1001","chinese":"摄影","pinyin":"shèyǐng","meaning":"to take a photograph; photography; to shoot (a movie)","meaningThai":"การถ่ายภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那些摄影和摄像师们涌向前去。","pinyin":"Nà xiē shè yǐng hé shè xiàng shī mén yǒng xiàng qián qù。","meaning":"The photographers and cameramen surged forward.","meaningThai":"ช่างภาพและตากล้องพุ่งไปข้างหน้า"},{"chinese":"这个摄影室的装备花费巨大。","pinyin":"Zhè gè shè yǐng shì de zhuāng bèi huā fèi jù dà。","meaning":"The equipment of the photographic studio was expensive.","meaningThai":"อุปกรณ์ของสตูดิโอถ่ายภาพมีราคาแพง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1002","chinese":"设置","pinyin":"shèzhì","meaning":"to set up; to install","meaningThai":"ตั้งค่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"设置的路障控制人流涌向广场。","pinyin":"Shè zhì de lù zhàng kòng zhì rén liú yǒng xiàng guǎng cháng。","meaning":"Barricades funnelled the crowds towards the square.","meaningThai":"เครื่องกีดขวางส่งฝูงชนไปทางจัตุรัส"},{"chinese":"设置了障碍，使人群无法靠近。","pinyin":"Shè zhì le zhàng ài， shǐ rén qún wú fǎ kào jìn。","meaning":"Barricades were erected to keep back the crowds.","meaningThai":"มีการสร้างเครื่องกีดขวางเพื่อป้องกันฝูงชน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1003","chinese":"式","pinyin":"shì","meaning":"type; form; pattern; style","meaningThai":"โหมด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她在400米自由式中获胜。","pinyin":"Tā zài 400 mǐ zì yóu shì zhōng huò shèng。","meaning":"She won the 400-metre freestyle.","meaningThai":"เธอได้รับรางวัลฟรีสไตล์ 400 เมตร"},{"chinese":"她装了一台墙壁式电扇。","pinyin":"Tā zhuāng le yī tái qiáng bì shì diàn shàn。","meaning":"She installed a wall-mounted electric fan.","meaningThai":"เธอติดตั้งพัดลมไฟฟ้าแบบติดผนัง"}],"partOfSpeech":["suffix","other"]},
  {"id":"hsk5-1004","chinese":"诗","pinyin":"shī","meaning":"abbr. for Shijing 诗经, the Book of Songs","meaningThai":"บทกวี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这首诗太长，不能全部引用。","pinyin":"Zhè shǒu shī tài cháng， bù néng quán bù yǐn yòng。","meaning":"The poem is too long to quote in its entirety.","meaningThai":"บทกวียาวเกินกว่าจะกล่าวได้ทั้งหมด"},{"chinese":"这首诗出自他的新书。","pinyin":"Zhè shǒu shī chū zì tā de xīn shū。","meaning":"This poem comes from his new book.","meaningThai":"บทกวีนี้มาจากหนังสือเล่มใหม่ของเขา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1005","chinese":"湿","pinyin":"shī","meaning":"variant of 湿","meaningThai":"เปียก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他脱下湿衣服，拧干了水。","pinyin":"Tā tuō xià shī yī fú， níng gān le shuǐ。","meaning":"He took off his wet clothes and squeezed the water out.","meaningThai":"เขาถอดเสื้อผ้าที่เปียกออกแล้วบีบน้ำออก"},{"chinese":"他用毛巾将湿头发擦干。","pinyin":"Tā yòng máo jīn jiāng shī tóu fā cā gān。","meaning":"He toweled his wet hair.","meaningThai":"เขาเช็ดผมที่เปียกของเขา"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1006","chinese":"时差","pinyin":"shíchā","meaning":"time difference; time lag; jet lag","meaningThai":"เวลา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我在倒时差。","pinyin":"Wǒ zài dào shí chā.","meaning":"I'm adjusting to the time difference.","meaningThai":"ฉันกำลังปรับตัวให้เข้ากับความแตกต่างของเวลา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1007","chinese":"时常","pinyin":"shícháng","meaning":"often; frequently","meaningThai":"บ่อยครั้ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"电影明星旅行时常喜欢隐瞒身份。","pinyin":"Diàn yǐng míng xīng lǚ háng shí cháng xǐ huān yǐn mán shēn fèn。","meaning":"Movie stars often prefer to travel incognito.","meaningThai":"ดาราภาพยนตร์มักชอบเดินทางโดยไม่ระบุตัวตน"},{"chinese":"她那时常常考虑搬到西雅图去。","pinyin":"Tā nà shí cháng cháng kǎo lǜ bān dào xī yǎ tú qù。","meaning":"She had often considered moving to Seattle.","meaningThai":"เธอมักจะคิดที่จะย้ายไปซีแอตเทิล"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1008","chinese":"时代","pinyin":"shídài","meaning":"Time, US weekly news magazine","meaningThai":"ยุค","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们都是我们时代的产物。","pinyin":"Wǒ mén dū shì wǒ mén shí dài de chǎn wù。","meaning":"We are all products of our time.","meaningThai":"เราทุกคนล้วนเป็นผลผลิตของยุคสมัยของเรา"},{"chinese":"时代变了，我也变了。","pinyin":"Shí dài biàn le， wǒ yě biàn le。","meaning":"Times have changed and so have I.","meaningThai":"ยุคสมัยมีการเปลี่ยนแปลง ฉันก็เช่นกัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1009","chinese":"适当","pinyin":"shìdàng","meaning":"suitable; appropriate","meaningThai":"เหมาะสม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的家人坚持要为他举行适当的葬礼。","pinyin":"Tā de jiā rén jiān chí yào wéi tā jǔ háng shì dāng de zàng lǐ。","meaning":"His family insisted he should be given a proper burial.","meaningThai":"ครอบครัวของเขายืนกรานว่าเขาควรได้รับการฝังศพอย่างเหมาะสม"},{"chinese":"大多数空缺在高层，要求适当的资历。","pinyin":"Dà duō shù kōng quē zài gāo céng， yào qiú shì dāng de zī lì。","meaning":"Most vacancies are at the senior level, requiring appropriate qualifications.","meaningThai":"ตำแหน่งงานว่างส่วนใหญ่อยู่ในระดับอาวุโสซึ่งต้องมีคุณสมบัติที่เหมาะสม"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1010","chinese":"似的","pinyin":"shìde","meaning":"seems as if; rather like; Taiwan pr. [sì de]","meaningThai":"คล้ายกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们跳绳或做类似的活动。","pinyin":"Wǒ mén tiào shéng huò zuò lèi sì de huó dòng。","meaning":"We did rope skipping and things like that.","meaningThai":"เรากระโดดเชือกและอะไรทำนองนั้น"},{"chinese":"他们有着出奇相似的嗓音。","pinyin":"Tā mén yǒu zháo chū qí xiāng sì de sǎng yīn。","meaning":"They have uncannily similar voices.","meaningThai":"พวกเขามีเสียงที่คล้ายกันอย่างน่าประหลาด"}],"partOfSpeech":["particle"]},
  {"id":"hsk5-1011","chinese":"使得","pinyin":"shǐde","meaning":"usable; workable; feasible; doable; to make; to cause","meaningThai":"ทำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那天气使得她无精打采。","pinyin":"Nà tiān qì shǐ dé tā wú jīng dǎ cǎi。","meaning":"The weather made her lethargic.","meaningThai":"อากาศทำให้เธอเซื่องซึม"},{"chinese":"他们使得她日子难过。","pinyin":"Tā mén shǐ dé tā rì zǐ nán guò。","meaning":"They're making life hot for her.","meaningThai":"พวกเขากำลังทำให้ชีวิตร้อนแรงสำหรับเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1012","chinese":"事故","pinyin":"shìgù","meaning":"accident","meaningThai":"อุบัติเหตุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"行人受伤事故下降了5%。","pinyin":"Háng rén shòu shāng shì gù xià jiàng le5%。","meaning":"Pedestrian accidents are down by 5%.","meaningThai":"อุบัติเหตุคนเดินเท้าลดลง 5%"},{"chinese":"他们还在调查这个事故。","pinyin":"Tā mén huán zài tiáo chá zhè gè shì gù。","meaning":"They're still investigating the accident.","meaningThai":"พวกเขายังคงสืบสวนอุบัติเหตุอยู่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1013","chinese":"实践","pinyin":"shíjiàn","meaning":"practice; to put into practice; to live up to (a promise); to carry out (a project)","meaningThai":"ฝึกฝน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她决心要把自己的新想法付诸实践。","pinyin":"Tā jué xīn yào bǎ zì jǐ de xīn xiǎng fǎ fù zhū shí jiàn。","meaning":"She's determined to put her new ideas into practice.","meaningThai":"เธอมุ่งมั่นที่จะนำแนวคิดใหม่ๆ ของเธอไปปฏิบัติ"},{"chinese":"会有一次书面考试来补充实践测试。","pinyin":"Huì yǒu yī cì shū miàn kǎo shì lái bǔ chōng shí jiàn cè shì。","meaning":"There will be a written examination to complement the practical test.","meaningThai":"จะมีการสอบข้อเขียนเพื่อเสริมการทดสอบภาคปฏิบัติ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1014","chinese":"事件","pinyin":"shìjiàn","meaning":"event; happening; incident","meaningThai":"เหตุการณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是个重要事件。","pinyin":"Zhè shì gè zhòng yào shì jiàn。","meaning":"This is an important event.","meaningThai":"นี่เป็นเหตุการณ์สำคัญ"},{"chinese":"这只是偶发事件。","pinyin":"Zhè zhī shì ǒu fā shì jiàn。","meaning":"That only happens occasionally.","meaningThai":"นั่นเกิดขึ้นเป็นครั้งคราวเท่านั้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1015","chinese":"试卷","pinyin":"shìjuàn","meaning":"examination paper; test paper","meaningThai":"กระดาษทดสอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我没答完试卷，我的时间不够了。","pinyin":"Wǒ méi dá wán shì juàn， wǒ de shí jiān bù gòu le。","meaning":"I didn't finish the test— I ran out of time.","meaningThai":"ฉันยังสอบไม่เสร็จ—ฉันหมดเวลาแล้ว"},{"chinese":"那道题真的在试卷上出现了。","pinyin":"Nà dào tí zhēn de zài shì juàn shàng chū xiàn le。","meaning":"That question did come up on the test.","meaningThai":"คำถามนั้นเกิดขึ้นในการทดสอบ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1016","chinese":"时刻","pinyin":"shíkè","meaning":"time; juncture; moment; period of time; constantly; always","meaningThai":"เวลา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个时刻需要行动果断、思维敏捷。","pinyin":"Zhè gè shí kè xū yào háng dòng guǒ duàn、 sī wéi mǐn jié。","meaning":"This is a time of decisive action and quick thinking.","meaningThai":"นี่คือช่วงเวลาแห่งการตัดสินใจอย่างเด็ดขาดและการคิดอย่างรวดเร็ว"},{"chinese":"我早早动身以避开交通高峰时刻。","pinyin":"Wǒ zǎo zǎo dòng shēn yǐ bì kāi jiāo tōng gāo fēng shí kè。","meaning":"I left early to avoid the rush hour.","meaningThai":"ฉันออกเดินทางเร็วเพื่อหลีกเลี่ยงชั่วโมงเร่งด่วน"}],"partOfSpeech":["noun","adverb"]},
  {"id":"hsk5-1017","chinese":"实力","pinyin":"shílì","meaning":"strength","meaningThai":"ความแข็งแกร่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们军事实力较强，占有巨大优势。","pinyin":"Tā mén jūn shì shí lì jiào qiáng， zhān yǒu jù dà yōu shì。","meaning":"Their superior military strength gives them a huge advantage.","meaningThai":"ความแข็งแกร่งทางการทหารที่เหนือกว่าทำให้พวกเขาได้เปรียบอย่างมาก"},{"chinese":"政治权力取决于经济实力。","pinyin":"Zhèng zhì quán lì qǔ jué yú jīng jì shí lì。","meaning":"Political power depends upon economic strength.","meaningThai":"อำนาจทางการเมืองขึ้นอยู่กับความเข้มแข็งทางเศรษฐกิจ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1018","chinese":"失恋","pinyin":"shīliàn","meaning":"to lose one's love; to break up (in a romantic relationship); to feel jilted","meaningThai":"อกหัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他又一次失恋了。","pinyin":"Tā yòu yī cì shī liàn le。","meaning":"Once again he was disappointed in love.","meaningThai":"เขาผิดหวังกับความรักอีกครั้ง"},{"chinese":"失恋假会随着员工的年龄而增加。","pinyin":"Shī liàn jiǎ huì suí zháo yuán gōng de nián líng ér zēng jiā。","meaning":"Well, the leave increases with age of the employee.","meaningThai":"การลาเพิ่มขึ้นตามอายุของพนักงาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1019","chinese":"失眠","pinyin":"shīmián","meaning":"to suffer from insomnia","meaningThai":"นอนไม่หลับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"最近失眠。","pinyin":"Zui jin shi mian.","meaning":"Having insomnia lately.","meaningThai":"ช่วงนี้มีอาการนอนไม่หลับ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1020","chinese":"市民","pinyin":"shìmín","meaning":"city resident","meaningThai":"พลเมือง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"1375年，市民造反了。","pinyin":"1375 nián， shì mín zào fǎn le。","meaning":"In 1375 the townspeople revolted.","meaningThai":"ในปี ค.ศ. 1375 ชาวเมืองได้ก่อกบฏ"},{"chinese":"多谢一群有公德心的市民，克利彭多夫花园才得以维持下去。","pinyin":"Duō xiè yī qún yǒu gōng dé xīn de shì mín， kè lì péng duō fū huā yuán cái dé yǐ wéi chí xià qù。","meaning":"Thanks to a group of public-spirited citizens, the Krippendorf garden has been preserved.","meaningThai":"ต้องขอบคุณกลุ่มพลเมืองที่มีใจรักสาธารณะ สวน Krippendorf จึงได้รับการอนุรักษ์ไว้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1021","chinese":"时期","pinyin":"shíqī","meaning":"period; phase","meaningThai":"ระยะเวลา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"现在我们正处在秋冬换季时期。","pinyin":"Xiàn zài wǒ mén zhèng chǔ zài qiū dōng huàn jì shí qī。","meaning":"Right now we are in the changeover period between autumn and winter.","meaningThai":"ตอนนี้เราอยู่ในช่วงเปลี่ยนผ่านระหว่างฤดูใบไม้ร่วงถึงฤดูหนาว"},{"chinese":"这部电影以俄国革命时期为背景。","pinyin":"Zhè bù diàn yǐng yǐ é guó gé mìng shí qī wéi bèi jǐng。","meaning":"The movie is set at the time of the Russian revolution.","meaningThai":"ภาพยนตร์เรื่องนี้เกิดขึ้นในช่วงเวลาแห่งการปฏิวัติรัสเซีย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1022","chinese":"诗人","pinyin":"shīrén","meaning":"bard; poet","meaningThai":"กวี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他是位诗人，也是热诚的唯灵论者。","pinyin":"Tā shì wèi shī rén， yě shì rè chéng de wéi líng lùn zhě。","meaning":"He was a poet and an ardent spiritualist.","meaningThai":"เขาเป็นกวีและนักเวทย์มนต์ผู้กระตือรือร้น"},{"chinese":"这所房子被误以为是诗人的出生地。","pinyin":"Zhè suǒ fáng zǐ bèi wù yǐ wéi shì shī rén de chū shēng dì。","meaning":"The house is wrongly reputed to have been the poet's birthplace.","meaningThai":"บ้านหลังนี้ขึ้นชื่อว่าเป็นบ้านเกิดของกวีอย่างไม่ถูกต้อง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1023","chinese":"实施","pinyin":"shíshī","meaning":"to implement; to carry out","meaningThai":"ดำเนินการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"广泛的安全措施实施了。","pinyin":"Guǎng fàn de ān quán cuò shī shí shī le。","meaning":"Broad safety measures were put into effect.","meaningThai":"มีการใช้มาตรการความปลอดภัยในวงกว้าง"},{"chinese":"根本就没实施过逮捕行动。","pinyin":"Gēn běn jiù méi shí shī guò dài bǔ háng dòng。","meaning":"No arrests were ever made.","meaningThai":"ไม่มีการจับกุมเลย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1024","chinese":"事实","pinyin":"shìshí","meaning":"fact","meaningThai":"ข้อเท็จจริง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那是个推测，不是事实。","pinyin":"Nà shì gè tuī cè， bù shì shì shí。","meaning":"That was a conjecture, not a fact.","meaningThai":"นั่นเป็นการคาดเดาไม่ใช่ข้อเท็จจริง"},{"chinese":"这本书事实和虚构并存。","pinyin":"Zhè běn shū shì shí hé xū gòu bìng cún。","meaning":"The book intermingles fact with fiction.","meaningThai":"หนังสือผสมผสานข้อเท็จจริงกับนิยาย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1025","chinese":"石头","pinyin":"shítou","meaning":"stone","meaningThai":"หิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有些孩子在朝窗户扔石头。","pinyin":"Yǒu xiē hái zǐ zài zhāo chuāng hù rēng shí tóu。","meaning":"Some kids were throwing stones at the window.","meaningThai":"เด็กบางคนขว้างก้อนหินไปที่หน้าต่าง"},{"chinese":"他们在朝墙那边扔石头。","pinyin":"Tā mén zài zhāo qiáng nà biān rēng shí tóu。","meaning":"They were lobbing stones over the wall.","meaningThai":"พวกเขากำลังขว้างก้อนหินข้ามกำแพง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1026","chinese":"视为","pinyin":"shìwéi","meaning":"to view as; to see as; to consider to be; to deem","meaningThai":"ถือเป็น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人民把曼德拉视为他们的救星。","pinyin":"Rén mín bǎ màn dé lā shì wéi tā mén de jiù xīng。","meaning":"People saw Mandela as their messiah.","meaningThai":"ผู้คนมองว่าแมนเดลาเป็นพระเมสสิยาห์ของพวกเขา"},{"chinese":"她被视为这门学科最重要的权威。","pinyin":"Tā bèi shì wéi zhè mén xué kē zuì zhòng yào de quán wēi。","meaning":"She's looked on as the leading authority on the subject.","meaningThai":"เธอถูกมองว่าเป็นผู้มีอำนาจชั้นนำในเรื่องนี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1027","chinese":"事物","pinyin":"shìwù","meaning":"thing; object","meaningThai":"สิ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她得到充分的鼓励去尝试新事物。","pinyin":"Tā dé dào chōng fēn de gǔ lì qù cháng shì xīn shì wù。","meaning":"She was given every encouragement to try something new.","meaningThai":"เธอได้รับทุกกำลังใจให้ลองทำอะไรใหม่ๆ"},{"chinese":"他们的解释是错误的–他们曲解了事物。","pinyin":"Tā mén de jiě shì shì cuò wù de – tā mén qū jiě le shì wù。","meaning":"Their interpretation was faulty – they had misinterpreted things.","meaningThai":"การตีความของพวกเขาผิดพลาด - พวกเขาตีความสิ่งต่าง ๆ ผิด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1028","chinese":"失误","pinyin":"shīwù","meaning":"lapse; mistake; to make a mistake; fault; service fault (in volleyball, tennis etc)","meaningThai":"ความผิดพลาด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他失误的原因是年轻没有经验。","pinyin":"Tā shī wù de yuán yīn shì nián qīng méi yǒu jīng yàn。","meaning":"His mistake was due to youth and inexperience.","meaningThai":"ความผิดพลาดของเขาเกิดจากความเยาว์วัยและไม่มีประสบการณ์"},{"chinese":"这场事故是飞行员的失误造成的。","pinyin":"Zhè cháng shì gù shì fēi háng yuán de shī wù zào chéng de。","meaning":"The accident was caused by pilot error.","meaningThai":"อุบัติเหตุครั้งนี้เกิดจากความผิดพลาดของนักบิน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1029","chinese":"实习","pinyin":"shíxí","meaning":"to practice; field work; to intern; internship","meaningThai":"ฝึกงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"暑假她在公司实习。","pinyin":"Shǔ jià tā zài gōng sī shí xí.","meaning":"She is interning at a company during summer break.","meaningThai":"เธอกำลังฝึกงานที่บริษัทแห่งหนึ่งในช่วงปิดเทอมฤดูร้อน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1030","chinese":"实现","pinyin":"shíxiàn","meaning":"to achieve; to implement; to realize; to bring about","meaningThai":"ทำให้สำเร็จ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你的梦想实现了吗？","pinyin":"Nǐ de mèng xiǎng shí xiàn le ma？","meaning":"Did your dream become reality? / Did you realize your dreams?","meaningThai":"ความฝันของคุณกลายเป็นจริงแล้วหรือยัง? / คุณตระหนักถึงความฝันของคุณหรือไม่?"},{"chinese":"你的梦想实现了。","pinyin":"Nǐ de mèng xiǎng shí xiàn le。","meaning":"Your dreams have come true.","meaningThai":"ความฝันของคุณเป็นจริงแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1031","chinese":"事先","pinyin":"shìxiān","meaning":"in advance; before the event; beforehand; prior","meaningThai":"ล่วงหน้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们需要事先得知涉及的数量。","pinyin":"Wǒ mén xū yào shì xiān dé zhī shè jí de shù liáng。","meaning":"We need advance notice of the numbers involved.","meaningThai":"เราต้องการการแจ้งเตือนล่วงหน้าเกี่ยวกับตัวเลขที่เกี่ยวข้อง"},{"chinese":"因事先有别的安排，她将不能出席。","pinyin":"Yīn shì xiān yǒu bié de ān pái， tā jiāng bù néng chū xí。","meaning":"She will be unable to attend because of a prior engagement.","meaningThai":"เธอจะไม่สามารถเข้าร่วมได้เนื่องจากการหมั้นหมายครั้งก่อน"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1032","chinese":"实行","pinyin":"shíxíng","meaning":"to implement; to carry out; to put into practice","meaningThai":"ดำเนินการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"法国对奶农实行补贴贷款制度。","pinyin":"Fǎ guó duì nǎi nóng shí háng bǔ tiē dài kuǎn zhì dù。","meaning":"France operates a system of subsidized loans to dairy farmers.","meaningThai":"ฝรั่งเศสดำเนินระบบการให้เงินอุดหนุนแก่เกษตรกรผู้เลี้ยงโคนม"},{"chinese":"他们在机场实行了安全检查。","pinyin":"Tā mén zài jī cháng shí háng le ān quán jiǎn chá。","meaning":"They carried out security checks at the airport.","meaningThai":"พวกเขาดำเนินการตรวจสอบความปลอดภัยที่สนามบิน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1033","chinese":"实验","pinyin":"shíyàn","meaning":"experiment; test; experimental; to experiment","meaningThai":"การทดลอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"实验室里做化学实验。","pinyin":"Shí yàn shì lǐ zuò huà xué shí yàn.","meaning":"Do chemistry experiments in the lab.","meaningThai":"ทำการทดลองทางเคมีในห้องแล็บ"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-1034","chinese":"试验","pinyin":"shìyàn","meaning":"experiment; test; to experiment; experimental","meaningThai":"ทดสอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些试验是否有用，人们有所保留。","pinyin":"Zhè xiē shì yàn shì fǒu yǒu yòng， rén mén yǒu suǒ bǎo liú。","meaning":"There are doubts about the usefulness of these tests.","meaningThai":"มีข้อสงสัยเกี่ยวกับประโยชน์ของการทดสอบเหล่านี้"},{"chinese":"试验项目的结果还没有制成表格。","pinyin":"Shì yàn xiàng mù de jié guǒ huán méi yǒu zhì chéng biǎo gé。","meaning":"Results for the test programme haven't been tabulated.","meaningThai":"ผลลัพธ์สำหรับโปรแกรมการทดสอบไม่ได้รับการจัดทำเป็นตาราง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1035","chinese":"实验室","pinyin":"shíyànshì","meaning":"laboratory","meaningThai":"ห้องทดลอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"实验室里设备齐全。","pinyin":"Shí yàn shì lǐ shè bèi qí quán.","meaning":"The lab is fully equipped.","meaningThai":"ห้องปฏิบัติการมีอุปกรณ์ครบครัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1036","chinese":"事业","pinyin":"shìyè","meaning":"undertaking; project; activity; (charitable, political or revolutionary) cause; publicly funded institution, enterprise or foundation; career; occupation","meaningThai":"สาเหตุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"回顾自己的事业，她深感欣慰。","pinyin":"Huí gù zì jǐ de shì yè， tā shēn gǎn xīn wèi。","meaning":"She looked back on her career with great satisfaction.","meaningThai":"เธอมองย้อนกลับไปในอาชีพการงานของเธอด้วยความพึงพอใจอย่างยิ่ง"},{"chinese":"他为了高尚的事业而牺牲。","pinyin":"Tā wéi le gāo shàng de shì yè ér xī shēng。","meaning":"He died for a noble cause.","meaningThai":"เขาเสียชีวิตด้วยสาเหตุอันสูงส่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1037","chinese":"失业","pinyin":"shīyè","meaning":"unemployment; to lose one's job","meaningThai":"การว่างงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这次倒闭使500人失业。","pinyin":"Zhè cì dǎo bì shǐ 500 rén shī yè。","meaning":"The closure left 500 people jobless.","meaningThai":"การปิดโรงงานทำให้มีผู้ว่างงาน 500 คน"},{"chinese":"失业人数再次猛增。","pinyin":"Shī yè rén shù zài cì měng zēng。","meaning":"Unemploy we are pirates, these data are stolen from youdao  has rocketed up again.","meaningThai":"ตัวเลขว่างงานพุ่งอีกครั้ง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1038","chinese":"实用","pinyin":"shíyòng","meaning":"practical; functional; pragmatic; applied (science)","meaningThai":"ใช้ได้จริง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种技术实用，但也有局限性。","pinyin":"Zhè zhǒng jì shù shí yòng， dàn yě yǒu jú xiàn xìng。","meaning":"This technique is useful but it has its limitations.","meaningThai":"เทคนิคนี้มีประโยชน์แต่ก็มีข้อจำกัด"},{"chinese":"他们的家具美观多于实用。","pinyin":"Tā mén de jiā jù měi guān duō yú shí yòng。","meaning":"Their furniture was more aesthetic than functional.","meaningThai":"เฟอร์นิเจอร์ของพวกเขามีความสวยงามมากกว่าประโยชน์ใช้สอย"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1039","chinese":"食用","pinyin":"shíyòng","meaning":"to eat; to consume; edible","meaningThai":"กินได้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"食用过多的糖会引起健康问题。","pinyin":"Shí yòng guò duō de táng huì yǐn qǐ jiàn kāng wèn tí。","meaning":"Eating too much sugar can lead to health problems.","meaningThai":"การกินน้ำตาลมากเกินไปอาจทำให้เกิดปัญหาสุขภาพได้"},{"chinese":"这种肉被宣布不适于人食用。","pinyin":"Zhè zhǒng ròu bèi xuān bù bù shì yú rén shí yòng。","meaning":"The meat was declared unfit for human consumption.","meaningThai":"เนื้อสัตว์ถูกประกาศว่าไม่เหมาะสำหรับการบริโภคของมนุษย์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1040","chinese":"试用","pinyin":"shìyòng","meaning":"to try sth out; to be on probation","meaningThai":"ลอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这台机器我们已经试用了一个星期。","pinyin":"Zhè tái jī qì wǒ mén yǐ jīng shì yòng le yī gè xīng qī。","meaning":"We had the machine on trial for a week.","meaningThai":"เราได้ทดลองใช้เครื่องเป็นเวลาหนึ่งสัปดาห์"},{"chinese":"试用期结束后，你将成为终身雇员。","pinyin":"Shì yòng qī jié shù hòu， nǐ jiāng chéng wéi zhōng shēn gù yuán。","meaning":"At the end of the probationary period you will become a permanent employee.","meaningThai":"เมื่อสิ้นสุดระยะเวลาทดลองงาน คุณจะกลายเป็นพนักงานประจำ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1041","chinese":"适用","pinyin":"shìyòng","meaning":"to be applicable","meaningThai":"ใช้งานได้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些原则统一适用于所有部门。","pinyin":"Zhè xiē yuán zé tǒng yī shì yòng yú suǒ yǒu bù mén。","meaning":"The principles were applied uniformly across all the departments.","meaningThai":"หลักการถูกนำไปใช้อย่างเท่าเทียมกันในทุกแผนก"},{"chinese":"这些规章不适用于外籍学生。","pinyin":"Zhè xiē guī zhāng bù shì yòng yú wài jí xué shēng。","meaning":"These regulations are inapplicable to international students.","meaningThai":"กฎระเบียบเหล่านี้ใช้ไม่ได้กับนักศึกษาต่างชาติ"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-1042","chinese":"始终","pinyin":"shǐzhōng","meaning":"from beginning to end; all along","meaningThai":"เสมอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她始终关注慈善工作。","pinyin":"Tā shǐ zhōng guān zhù cí shàn gōng zuò。","meaning":"She has always interested herself in charity work.","meaningThai":"เธอสนใจงานการกุศลมาโดยตลอด"},{"chinese":"不知何故，那封信始终未寄到。","pinyin":"Bù zhī hé gù， nà fēng xìn shǐ zhōng wèi jì dào。","meaning":"For some unaccountable reason, the letter never arrived.","meaningThai":"ด้วยเหตุผลบางอย่างที่ไม่สามารถอธิบายได้ จดหมายจึงมาไม่ถึง"}],"partOfSpeech":["adverb","noun"]},
  {"id":"hsk5-1043","chinese":"守","pinyin":"shǒu","meaning":"to guard; to defend; to keep watch; to abide by the law; to observe (rules or ritual); nearby; adjoining","meaningThai":"เก็บ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"汤姆言行完全不慎重，从来守不住秘密。","pinyin":"Tāng mǔ yán háng wán quán bù shèn zhòng， cóng lái shǒu bù zhù mì mì。","meaning":"Tom was utterly indiscreet, and could never keep a secret.","meaningThai":"ทอมเป็นคนไม่รอบคอบอย่างยิ่ง และไม่สามารถเก็บความลับได้"},{"chinese":"观众令人出奇地守秩序。","pinyin":"Guān zhòng líng rén chū qí dì shǒu zhì xù。","meaning":"The audience was surprisingly well behaved.","meaningThai":"ผู้ชมประพฤติตัวดีอย่างน่าประหลาดใจ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1044","chinese":"首次","pinyin":"shǒucì","meaning":"first; first time; for the first time","meaningThai":"อันดับแรก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个问题首次出现在2003年。","pinyin":"Zhè gè wèn tí shǒu cì chū xiàn zài 2003 nián。","meaning":"The problem first arose in 2003.","meaningThai":"ปัญหาเกิดขึ้นครั้งแรกในปี 2546"},{"chinese":"这是这家公司首次涉足电影制作。","pinyin":"Zhè shì zhè jiā gōng sī shǒu cì shè zú diàn yǐng zhì zuò。","meaning":"This is the first time the company has ventured into movie production.","meaningThai":"นี่เป็นครั้งแรกที่บริษัทได้เข้าสู่การผลิตภาพยนตร์"}],"partOfSpeech":["numeral"]},
  {"id":"hsk5-1045","chinese":"手段","pinyin":"shǒuduàn","meaning":"method; means (of doing sth); strategy; trick","meaningThai":"วิธี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这次采访是以欺骗手段进行的。","pinyin":"Zhè cì cǎi fǎng shì yǐ qī piàn shǒu duàn jìn háng de。","meaning":"This interview was conducted under false pretences.","meaningThai":"การสัมภาษณ์ครั้งนี้ดำเนินการภายใต้การแสร้งทำเป็นเท็จ"},{"chinese":"她用错误的手段和他们打交道。","pinyin":"Tā yòng cuò wù de shǒu duàn hé tā mén dǎ jiāo dào。","meaning":"She took the wrong approach in her dealings with them.","meaningThai":"เธอใช้แนวทางที่ผิดในการติดต่อกับพวกเขา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1046","chinese":"手工","pinyin":"shǒugōng","meaning":"handwork; manual","meaningThai":"คู่มือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的爱好是音乐、读书和手工。","pinyin":"Tā de ài hǎo shì yīn lè、 dú shū hé shǒu gōng。","meaning":"Her hobbies are music, reading and handicraft.","meaningThai":"งานอดิเรกของเธอคือดนตรี อ่านหนังสือ และงานหัตถกรรม"},{"chinese":"他退后几步欣赏他的手工制品。","pinyin":"Tā tuì hòu jī bù xīn shǎng tā de shǒu gōng zhì pǐn。","meaning":"He stood back to admire his handiwork.","meaningThai":"เขากลับมาชื่นชมผลงานของเขา"}],"partOfSpeech":["noun","adverb"]},
  {"id":"hsk5-1047","chinese":"收获","pinyin":"shōuhuò","meaning":"variant of 收获","meaningThai":"เก็บเกี่ยว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"公司正在收获他们的投资回报。","pinyin":"Gōng sī zhèng zài shōu huò tā mén de tóu zī huí bào。","meaning":"The company is now reaping the rewards of their investments.","meaningThai":"ขณะนี้บริษัทกำลังเก็บเกี่ยวผลตอบแทนจากการลงทุนของพวกเขา"},{"chinese":"参观者们被拉来帮助挖土豆和收获。","pinyin":"Cān guān zhě mén bèi lā lái bāng zhù wā tǔ dòu hé shōu huò。","meaning":"Visitors were roped in for potato picking and harvesting.","meaningThai":"นักท่องเที่ยวถูกผูกเชือกเพื่อเก็บและเก็บเกี่ยวมันฝรั่ง"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-1048","chinese":"收集","pinyin":"shōují","meaning":"to gather; to collect","meaningThai":"เก็บรวบรวม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我收集贝壳以及海边有趣的东西。","pinyin":"Wǒ shōu jí bèi ké yǐ jí hǎi biān yǒu qù de dōng xī。","meaning":"I collect shells and interesting seaside items.","meaningThai":"ฉันรวบรวมเปลือกหอยและสิ่งของริมทะเลที่น่าสนใจ"},{"chinese":"她在为其最新的小说收集素材。","pinyin":"Tā zài wéi qí zuì xīn de xiǎo shuō shōu jí sù cái。","meaning":"She's collecting material for her latest novel.","meaningThai":"เธอกำลังรวบรวมเนื้อหาสำหรับนวนิยายเรื่องล่าสุดของเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1049","chinese":"售价","pinyin":"shòujià","meaning":"selling price","meaningThai":"ราคาขาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这游戏的售价为每套15元。","pinyin":"Zhè yóu xì de shòu jià wéi měi tào 15 yuán。","meaning":"The game's selling price was $15 per unit.","meaningThai":"ราคาขายของเกมอยู่ที่ 15 ดอลลาร์ต่อหน่วย"},{"chinese":"此外，买主需要核实售价中是否包含运费。","pinyin":"Cǐ wài， mǎi zhǔ xū yào hé shí shòu jià zhōng shì fǒu bāo hán yùn fèi。","meaning":"Again, buyers need to check if carriage is included in the price.","meaningThai":"ผู้ซื้อจะต้องตรวจสอบอีกครั้งว่าราคารวมค่าขนส่งแล้วหรือไม่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1050","chinese":"收看","pinyin":"shōukàn","meaning":"to watch (a TV program)","meaningThai":"ดู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"再次谢谢您的收看。","pinyin":"Zài cì xiè xiè nín de shōu kàn。","meaning":"Thank you again for watching.","meaningThai":"ขอขอบคุณอีกครั้งสำหรับการรับชม"},{"chinese":"感谢你的收看！","pinyin":"Gǎn xiè nǐ de shōu kàn！","meaning":"Thank you for watching!","meaningThai":"ขอบคุณสำหรับการรับชม!"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1051","chinese":"手术","pinyin":"shǒushù","meaning":"(surgical) operation; surgery","meaningThai":"การดำเนินการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"手术后，他正在缓慢好转。","pinyin":"Shǒu shù hòu， tā zhèng zài huǎn màn hǎo zhuǎn。","meaning":"He's mending slowly after the operation.","meaningThai":"เขากำลังฟื้นตัวอย่างช้าๆ หลังการผ่าตัด"},{"chinese":"手术后，他仍在恢复之中。","pinyin":"Shǒu shù hòu， tā réng zài huī fù zhī zhōng。","meaning":"He's still recovering from his operation.","meaningThai":"เขายังคงฟื้นตัวจากการผ่าตัด"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-1052","chinese":"手套","pinyin":"shǒutào","meaning":"glove; mitten","meaningThai":"ถุงมือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"稍许翻一下就会找到几副手套。","pinyin":"Shāo xǔ fān yī xià jiù huì zhǎo dào jī fù shǒu tào。","meaning":"A brief rummage will provide several pairs of gloves.","meaningThai":"การค้นหาสั้น ๆ จะให้ถุงมือหลายคู่"},{"chinese":"冬天她穿着厚袜和靴子，还戴着手套。","pinyin":"Dōng tiān tā chuān zháo hòu wà hé xuē zǐ， huán dài zháo shǒu tào。","meaning":"In the winter she wears thick socks, boots and gloves.","meaningThai":"ในฤดูหนาวเธอสวมถุงเท้าหนา รองเท้าบูท และถุงมือ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1053","chinese":"手续","pinyin":"shǒuxù","meaning":"procedure; formalities","meaningThai":"พิธีการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"必须办理一定的手续方能移居他国。","pinyin":"Bì xū bàn lǐ yī dìng de shǒu xù fāng néng yí jū tā guó。","meaning":"Certain formalities have to be gone through before you can emigrate.","meaningThai":"จะต้องผ่านพิธีการบางอย่างก่อนจึงจะสามารถอพยพได้"},{"chinese":"一切手续必须按正确顺序办理。","pinyin":"Yī qiē shǒu xù bì xū àn zhèng què shùn xù bàn lǐ。","meaning":"All the procedures must be done in the correct order.","meaningThai":"ขั้นตอนทั้งหมดจะต้องดำเนินการตามลำดับที่ถูกต้อง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1054","chinese":"手指","pinyin":"shǒuzhǐ","meaning":"finger","meaningThai":"นิ้ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他弯了弯手指，说：“过来。”","pinyin":"Tā wān le wān shǒu zhǐ， shuō：“ guò lái。”","meaning":"He crooked his finger: \"Come forward,\" he said.","meaningThai":"เขาขยับนิ้ว: \"มาข้างหน้า\" เขากล่าว"},{"chinese":"萨姆给车门夹住了手指。","pinyin":"Sà mǔ gěi chē mén jiā zhù le shǒu zhǐ。","meaning":"Sam shut his finger in the car door.","meaningThai":"แซมเอานิ้วปิดประตูรถ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1055","chinese":"束","pinyin":"shù","meaning":"surname Shu","meaningThai":"มัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"磁线圈将电子束聚焦成细小的点。","pinyin":"Cí xiàn quān jiāng diàn zǐ shù jù jiāo chéng xì xiǎo de diǎn。","meaning":"Magnetic coils focus the electron beams into fine spots.","meaningThai":"ขดลวดแม่เหล็กจะโฟกัสลำแสงอิเล็กตรอนไปที่จุดละเอียด"},{"chinese":"有人给她送了一大束花。","pinyin":"Yǒu rén gěi tā sòng le yī dà shù huā。","meaning":"She was given a huge bunch of flowers.","meaningThai":"เธอได้รับดอกไม้ช่อใหญ่"}],"partOfSpeech":["measure word","verb"]},
  {"id":"hsk5-1056","chinese":"数","pinyin":"shǔ","meaning":"to count; to count as; to regard as; to enumerate; to list","meaningThai":"ตัวเลข","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们人太多了，数不过来。","pinyin":"Tāmen rén tài duō le, shù bú guòlái.","meaning":"They are too numerous to enumerate.","meaningThai":"มีจำนวนมากเกินไปที่จะแจกแจง"},{"chinese":"闭上你的眼睛，然后数到十。","pinyin":"Bì shàng nǐ de yǎnjīng, ránhòu shù dào shí.","meaning":"Close your eyes, and count to ten.","meaningThai":"หลับตาแล้วนับถึงสิบ"},{"chinese":"我儿子现在可以数到100。","pinyin":"Wǒ érzi xiànzài kěyǐ shù dào 100.","meaning":"My son can count up to a hundred now.","meaningThai":"ลูกชายของฉันนับได้ถึงร้อยแล้ว"}],"partOfSpeech":["numeral","noun","verb"]},
  {"id":"hsk5-1057","chinese":"摔","pinyin":"shuāi","meaning":"to throw down; to fall; to drop and break","meaningThai":"ตก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"幸亏有灌木接着，他摔得不重。","pinyin":"Xìng kuī yǒu guàn mù jiē zháo， tā shuāi dé bù zhòng。","meaning":"Luckily, a bush broke his fall.","meaningThai":"โชคดีที่มีพุ่มไม้หักเขาล้ม"},{"chinese":"她摔得很重，扭伤了脚踝，只好退出比赛。","pinyin":"Tā shuāi dé hěn zhòng， niǔ shāng le jiǎo huái， zhī hǎo tuì chū bǐ sài。","meaning":"She fell badly, spraining her ankle, and had to retire.","meaningThai":"เธอล้มลงอย่างแรง ข้อเท้าแพลง และต้องออกจากงาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1058","chinese":"双方","pinyin":"shuāngfāng","meaning":"bilateral; both sides; both parties involved","meaningThai":"ทั้งสองด้าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"双方都同意需要那笔钱。","pinyin":"Shuāng fāng dū tóng yì xū yào nà bǐ qián。","meaning":"Both have agreed on the need for the money.","meaningThai":"ทั้งสองได้ตกลงกันเรื่องความต้องการเงิน"},{"chinese":"双方均申明答应停火。","pinyin":"Shuāng fāng jūn shēn míng dá yīng tíng huǒ。","meaning":"Both sides affirmed their commitment to the ceasefire.","meaningThai":"ทั้งสองฝ่ายยืนยันความมุ่งมั่นในการหยุดยิง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1059","chinese":"鼠标","pinyin":"shǔbiāo","meaning":"mouse (computing)","meaningThai":"หนู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"玛丽买了鼠标垫。","pinyin":"Mǎ lì mǎi le shǔ biāo diàn。","meaning":"Mary bought the mousepad.","meaningThai":"แมรี่ซื้อแผ่นรองเมาส์"},{"chinese":"请帮我拿一下鼠标。","pinyin":"Qǐng bāng wǒ ná yī xià shǔ biāo。","meaning":"Please help me get the mouse.","meaningThai":"ขอความช่วยเหลือเรื่องเมาส์ครับ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1060","chinese":"蔬菜","pinyin":"shūcài","meaning":"vegetables","meaningThai":"ผัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"多吃蔬菜对身体好。","pinyin":"Duo chi shu cai dui shen ti hao.","meaning":"Eating more vegetables is good for you.","meaningThai":"การกินผักมากขึ้นจะดีต่อคุณ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1061","chinese":"书法","pinyin":"shūfǎ","meaning":"calligraphy; handwriting; penmanship","meaningThai":"การประดิษฐ์ตัวอักษร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"从他刚刚成年时起，他的书法就流畅而优美。","pinyin":"Cóng tā gāng gāng chéng nián shí qǐ， tā de shū fǎ jiù liú chàng ér yōu měi。","meaning":"His handwriting, from earliest young manhood, was flowing and graceful.","meaningThai":"ลายมือของเขาตั้งแต่ยังเป็นวัยรุ่น ลื่นไหลและสง่างาม"},{"chinese":"书法比赛会上，人们请他留字。","pinyin":"Shū fǎ bǐ sài huì shàng， rén mén qǐng tā liú zì。","meaning":"At the calligraphy competition, people asked him to write a few characters.","meaningThai":"ในการแข่งขันคัดลายมือ ผู้คนขอให้เขาเขียนตัวอักษรสองสามตัว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1062","chinese":"书房","pinyin":"shūfáng","meaning":"study (room); studio","meaningThai":"ศึกษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"晚饭后，他喜欢躲到书房里去。","pinyin":"Wǎn fàn hòu， tā xǐ huān duǒ dào shū fáng lǐ qù。","meaning":"After dinner he likes to retire to his study.","meaningThai":"หลังอาหารเย็นเขาชอบที่จะเกษียณไปเรียนหนังสือ"},{"chinese":"那天晚上我们一起坐在他的书房里。","pinyin":"Nà tiān wǎn shàng wǒ mén yī qǐ zuò zài tā de shū fáng lǐ。","meaning":"That evening we sat together in his study.","meaningThai":"เย็นวันนั้นเรานั่งอ่านหนังสือด้วยกัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1063","chinese":"税","pinyin":"shuì","meaning":"taxes; duties","meaningThai":"ภาษี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们已经降低了所得税。","pinyin":"Tā mén yǐ jīng jiàng dī le suǒ dé shuì。","meaning":"They have brought down income taxes.","meaningThai":"พวกเขาได้ลดภาษีเงินได้"},{"chinese":"他呼吁改革资本收益税。","pinyin":"Tā hū xū gǎi gé zī běn shōu yì shuì。","meaning":"He called for the reform of capital gains tax.","meaningThai":"ทรงเรียกร้องให้มีการปฏิรูปภาษีกำไรจากการขายหุ้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1064","chinese":"水分","pinyin":"shuǐfèn","meaning":"moisture content; (fig.) overstatement; padding","meaningThai":"ความชื้น, น้ำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"每天要补充足够的水分。","pinyin":"Měi tiān yào bǔ chōng zú gòu de shuǐ fèn.","meaning":"Replenish enough water every day.","meaningThai":"เติมน้ำให้เพียงพอทุกวัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1065","chinese":"睡眠","pinyin":"shuìmián","meaning":"sleep; to sleep; (computing) to enter sleep mode","meaningThai":"นอน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"紧张和缺少睡眠会使情况恶化。","pinyin":"Jǐn zhāng hé quē shǎo shuì mián huì shǐ qíng kuàng è huà。","meaning":"Stress and lack of sleep can aggravate the situation.","meaningThai":"ความเครียดและการอดนอนอาจทำให้สถานการณ์แย่ลงได้"},{"chinese":"他们因睡眠不足而疲惫不堪了。","pinyin":"Tā mén yīn shuì mián bù zú ér pí bèi bù kān le。","meaning":"They were exhausted from lack of sleep.","meaningThai":"พวกเขาเหนื่อยล้าจากการนอนไม่เพียงพอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1066","chinese":"书架","pinyin":"shūjià","meaning":"bookshelf","meaningThai":"ชั้นวางหนังสือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我用旧木板拼拼凑凑做了些书架。","pinyin":"Wǒ yòng jiù mù bǎn pīn pīn còu còu zuò le xiē shū jià。","meaning":"I knocked some bookshelves together from old planks.","meaningThai":"ฉันเคาะชั้นหนังสือบางชั้นจากไม้กระดานเก่าๆ"},{"chinese":"她浏览着书架，想找本有趣的书看。","pinyin":"Tā liú lǎn zháo shū jià， xiǎng zhǎo běn yǒu qù de shū kàn。","meaning":"She browsed the shelves for something interesting to read.","meaningThai":"เธอค้นดูชั้นวางเพื่อหาสิ่งที่น่าสนใจอ่าน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1067","chinese":"数据","pinyin":"shùjù","meaning":"data","meaningThai":"ข้อมูล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"收集数据进行分析。","pinyin":"Shōu jí shù jù jìn xíng fēn xī.","meaning":"Collect data for analysis.","meaningThai":"รวบรวมข้อมูลเพื่อการวิเคราะห์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1068","chinese":"熟练","pinyin":"shúliàn","meaning":"practiced; proficient; skilled; skillful","meaningThai":"มีทักษะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们需要熟练工人和专业技术知识。","pinyin":"Wǒ mén xū yào shú liàn gōng rén hé zhuān yè jì shù zhī shí。","meaning":"We need skilled workers and technical know-how.","meaningThai":"เราต้องการแรงงานที่มีทักษะและความรู้ทางเทคนิค"},{"chinese":"许多公司苦于缺乏熟练员工。","pinyin":"Xǔ duō gōng sī kǔ yú quē fá shú liàn yuán gōng。","meaning":"Many companies are suffering from a shortage of skilled staff.","meaningThai":"หลายบริษัทประสบปัญหาการขาดแคลนบุคลากรที่มีทักษะ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1069","chinese":"树木","pinyin":"shùmù","meaning":"tree","meaningThai":"ต้นไม้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"树木未被修剪，道路未被铺设。","pinyin":"Shù mù wèi bèi xiū jiǎn， dào lù wèi bèi pū shè。","meaning":"Trees were to be left uncut, roads unpaved.","meaningThai":"ต้นไม้ต้องไม่ถูกตัด ถนนไม่ลาดยาง"},{"chinese":"树木使房子的轮廓显得柔和。","pinyin":"Shù mù shǐ fáng zǐ de lún kuò xiǎn dé róu hé。","meaning":"Trees soften the outline of the house.","meaningThai":"ต้นไม้ทำให้โครงร่างของบ้านดูอ่อนลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1070","chinese":"顺","pinyin":"shùn","meaning":"to obey; to follow; to arrange; to make reasonable; along; favorable","meaningThai":"ชุน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我谨祝您一切顺利。","pinyin":"Wǒ jǐn zhù nín yī qiē shùn lì。","meaning":"I'd like to wish you every success.","meaningThai":"ผมขออวยพรให้คุณประสบความสำเร็จทุกประการ"},{"chinese":"小船稳稳地顺著运河突突地航行。","pinyin":"Xiǎo chuán wěn wěn dì shùn zhù yùn hé tū tū dì háng háng。","meaning":"The boat chugged along the canal.","meaningThai":"เรือแล่นไปตามคลอง"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-1071","chinese":"说不定","pinyin":"shuōbudìng","meaning":"can't say for sure; maybe","meaningThai":"อาจจะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"说不定我们什么时候还会再见面的。","pinyin":"Shuō bù dìng wǒ mén shí mó shí hòu huán huì zài jiàn miàn de。","meaning":"Maybe we'll meet again some time.","meaningThai":"บางทีเราอาจจะได้พบกันอีกสักครั้ง"},{"chinese":"说不定他已经走了。","pinyin":"Shuō bù dìng tā yǐ jīng zǒu le。","meaning":"Maybe he's already left.","meaningThai":"บางทีเขาอาจจะจากไปแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1072","chinese":"说服","pinyin":"shuōfú","meaning":"to persuade; to convince; to talk sb over; Taiwan pr. [shuì fú]","meaningThai":"โน้มน้าว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"显然我没能说服迈克。","pinyin":"Xiǎn rán wǒ méi néng shuō fú mài kè。","meaning":"It became clear that I hadn't been able to convince Mike.","meaningThai":"เห็นได้ชัดว่าฉันไม่สามารถโน้มน้าวไมค์ได้"},{"chinese":"她根本没有说服他们。","pinyin":"Tā gēn běn méi yǒu shuō fú tā mén。","meaning":"She utterly failed to convince them.","meaningThai":"เธอล้มเหลวอย่างสิ้นเชิงในการโน้มน้าวพวกเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1073","chinese":"熟人","pinyin":"shúrén","meaning":"acquaintance; friend","meaningThai":"คนรู้จัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有关旅馆的最佳信息通常来自曾经去过那儿的朋友和熟人。","pinyin":"Yǒu guān lǚ guǎn de zuì jiā xìn xī tōng cháng lái zì zēng jīng qù guò nà ér de péng yǒu hé shú rén。","meaning":"The best information about hotels usually comes from friends and acquaintances who have been there.","meaningThai":"ข้อมูลที่ดีที่สุดเกี่ยวกับโรงแรมมักมาจากเพื่อนและคนรู้จักที่เคยไปที่นั่น"},{"chinese":"显然，比起朋友，我们更看不起熟人。","pinyin":"Xiǎn rán， bǐ qǐ péng yǒu， wǒ mén gēng kàn bù qǐ shú rén。","meaning":"Apparently, we look down on acquaintances more so than friends.","meaningThai":"เห็นได้ชัดว่าเราดูถูกคนรู้จักมากกว่าเพื่อน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1074","chinese":"输入","pinyin":"shūrù","meaning":"to import; to input","meaningThai":"เข้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"输入了无效信息将显示错误代码。","pinyin":"Shū rù le wú xiào xìn xī jiāng xiǎn shì cuò wù dài mǎ。","meaning":"An error code will be displayed if any invalid information has been entered.","meaningThai":"รหัสข้อผิดพลาดจะปรากฏขึ้นหากมีการป้อนข้อมูลที่ไม่ถูกต้อง"},{"chinese":"我把指令输入了我的导航计算机。","pinyin":"Wǒ bǎ zhǐ líng shū rù le wǒ de dǎo háng jì suàn jī。","meaning":"I entered the command into my navigational computer.","meaningThai":"ฉันป้อนคำสั่งลงในคอมพิวเตอร์นำทางของฉัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1075","chinese":"舒适","pinyin":"shūshì","meaning":"cozy; snug","meaningThai":"สะดวกสบาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们发现这些床非常舒适。","pinyin":"Wǒ mén fā xiàn zhè xiē chuáng fēi cháng shū shì。","meaning":"We found the beds very comfortable.","meaningThai":"เราพบว่าเตียงนอนสบายมาก"},{"chinese":"他们喜欢家里的舒适环境。","pinyin":"Tā mén xǐ huān jiā lǐ de shū shì huán jìng。","meaning":"They appreciate all the creature comforts of home.","meaningThai":"พวกเขาชื่นชมความสะดวกสบายของบ้าน"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1076","chinese":"属于","pinyin":"shǔyú","meaning":"to be classified as; to belong to; to be part of","meaningThai":"เป็นของ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"狮子和老虎属于猫科。","pinyin":"Shī zǐ hé lǎo hǔ shǔ yú māo kē。","meaning":"Lions and tigers belong to the cat family.","meaningThai":"สิงโตและเสืออยู่ในตระกูลแมว"},{"chinese":"你不属于这里。","pinyin":"Nǐ bù shǔ yú zhè lǐ。","meaning":"You don't belong here.","meaningThai":"คุณไม่ได้อยู่ที่นี่"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1077","chinese":"四处","pinyin":"sìchù","meaning":"all over the place; everywhere and all directions","meaningThai":"รอบๆ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"地板上四处散乱着文件。","pinyin":"Dì bǎn shàng sì chǔ sàn luàn zháo wén jiàn。","meaning":"There were papers lying around all over the floor.","meaningThai":"มีเอกสารวางอยู่เต็มพื้น"},{"chinese":"人们走出家门四处察看。","pinyin":"Rén mén zǒu chū jiā mén sì chǔ chá kàn。","meaning":"People came out of their houses and looked around.","meaningThai":"ผู้คนออกมาจากบ้านและมองไปรอบๆ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1078","chinese":"似乎","pinyin":"sìhū","meaning":"it seems; seemingly; as if","meaningThai":"ดูเหมือน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个条约似乎偏向美国。","pinyin":"Zhè gè tiáo yuē sì hū piān xiàng měi guó。","meaning":"The treaty seems to favour the US.","meaningThai":"สนธิสัญญาดังกล่าวดูเหมือนจะเข้าข้างสหรัฐฯ"},{"chinese":"成功的几率似乎很高。","pinyin":"Chéng gōng de jī shuài sì hū hěn gāo。","meaning":"There seemed to be a high probability of success.","meaningThai":"ดูเหมือนจะมีความเป็นไปได้สูงที่จะประสบความสำเร็จ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1079","chinese":"思考","pinyin":"sīkǎo","meaning":"to reflect on; to ponder over","meaningThai":"คิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他仔细思考了有关的种种困难。","pinyin":"Tā zī xì sī kǎo le yǒu guān de zhǒng zhǒng kùn nán。","meaning":"He pondered over the difficulties involved.","meaningThai":"เขาไตร่ตรองถึงความยากลำบากที่เกี่ยวข้อง"},{"chinese":"好的教师鼓励独立思考。","pinyin":"Hǎo de jiào shī gǔ lì dú lì sī kǎo。","meaning":"A good teacher encourages independence of thought.","meaningThai":"ครูที่ดีส่งเสริมความเป็นอิสระทางความคิด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1080","chinese":"私人","pinyin":"sīrén","meaning":"private; personal; interpersonal; sb with whom one has a close personal relationship; a member of one's clique","meaningThai":"ส่วนตัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们正在擅自闯入私人领地。","pinyin":"Tā mén zhèng zài shàn zì chuǎng rù sī rén lǐng dì。","meaning":"They were trespassing on private property.","meaningThai":"พวกเขาบุกรุกทรัพย์สินส่วนตัว"},{"chinese":"信上标注着“私人”字样。","pinyin":"Xìn shàng biāo zhù zháo “ sī rén ” zì yàng。","meaning":"The letter was marked 'Personal'.","meaningThai":"จดหมายถูกทำเครื่องหมายว่า 'ส่วนตัว'"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1081","chinese":"思维","pinyin":"sīwéi","meaning":"(line of) thought; thinking","meaningThai":"ความคิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"思维方式。","pinyin":"Si wei fang shi.","meaning":"Way of thinking.","meaningThai":"วิธีคิด."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1082","chinese":"思想","pinyin":"sīxiǎng","meaning":"thought; thinking; idea; ideology","meaningThai":"คิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"借用他的思想。","pinyin":"Jiè yòng tā de sī xiǎng。","meaning":"Borrow his thoughts.","meaningThai":"ยืมความคิดของเขา"},{"chinese":"打開你的思想。","pinyin":"Dǎ kāi nǐ de sī xiǎng。","meaning":"Open your mind.","meaningThai":"เปิดใจของคุณ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1083","chinese":"四周","pinyin":"sìzhōu","meaning":"all around","meaningThai":"ทั่วทุกมุม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我绕着这座房子四周散步。","pinyin":"Wǒ rào zháo zhè zuò fáng zǐ sì zhōu sàn bù。","meaning":"I walked around the outside of the building.","meaningThai":"ฉันเดินไปรอบๆด้านนอกของอาคาร"},{"chinese":"这块地方四周都是陡坡。","pinyin":"Zhè kuài dì fāng sì zhōu dū shì dǒu pō。","meaning":"The ground rose steeply all around.","meaningThai":"พื้นดินสูงชันไปทั่ว"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1084","chinese":"搜","pinyin":"sōu","meaning":"to search","meaningThai":"ค้นหา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"士兵们为找非法武器搜了他们的家。","pinyin":"Shì bīng mén wéi zhǎo fēi fǎ wǔ qì sōu le tā mén de jiā。","meaning":"Soldiers searched their house for illegal arms.","meaningThai":"ทหารตรวจค้นบ้านเพื่อหาอาวุธผิดกฎหมาย"},{"chinese":"外国记者们被机场警察搜了身。","pinyin":"Wài guó jì zhě mén bèi jī cháng jǐng chá sōu le shēn。","meaning":"Foreign journalists were body-searched by airport police.","meaningThai":"นักข่าวต่างชาติถูกตำรวจสนามบินตรวจร่างกาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1085","chinese":"搜索","pinyin":"sōusuǒ","meaning":"to search (a place); to search (a database); to search for (sth)","meaningThai":"ค้นหา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"搜索队被传送到那个星球的表面。","pinyin":"Sōu suǒ duì bèi chuán sòng dào nà gè xīng qiú de biǎo miàn。","meaning":"The search party was teleported down to the planet's surface.","meaningThai":"กลุ่มค้นหาถูกเคลื่อนย้ายลงมายังพื้นผิวโลก"},{"chinese":"电脑程序在搜索，瞧！找到匹配的了。","pinyin":"Diàn nǎo chéng xù zài sōu suǒ， qiáo！ zhǎo dào pǐ pèi de le。","meaning":"The computer program searches, and bingo! We've got a match.","meaningThai":"โปรแกรมคอมพิวเตอร์ค้นหาและบิงโก! เรามีนัดกัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1086","chinese":"酸甜苦辣","pinyin":"suān-tián-kǔ-là","meaning":"sour, sweet, bitter and spicy hot; fig. the joys and sorrows of life","meaningThai":"ขึ้นและลง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"此刻，她正谈论着自己生活中的酸甜苦辣。","pinyin":"Cǐ kè， tā zhèng tán lùn zháo zì jǐ shēng huó zhōng de suān tián kǔ là。","meaning":"Here, she talks about the highs and lows of her life.","meaningThai":"ที่นี่เธอพูดถึงช่วงชีวิตที่รุ่งโรจน์และตกต่ำ"},{"chinese":"他尝遍了人生的酸甜苦辣。","pinyin":"Tā cháng biàn le rén shēng de suān tián kǔ là。","meaning":"He has tasted the sweets and bitters of life.","meaningThai":"เขาได้ลิ้มรสความหวานและความขมแห่งชีวิต"}],"partOfSpeech":["expression"]},
  {"id":"hsk5-1087","chinese":"随","pinyin":"suí","meaning":"surname Sui","meaningThai":"ติดตาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"汽车随惯性而下直至滑行停止。","pinyin":"Qì chē suí guàn xìng ér xià zhí zhì huá háng tíng zhǐ。","meaning":"The car coasted along until it stopped.","meaningThai":"รถแล่นไปตามทางจนหยุด"},{"chinese":"酒量随年龄的增大而减少。","pinyin":"Jiǔ liáng suí nián líng de zēng dà ér jiǎn shǎo。","meaning":"Tolerance to alcohol decreases with age.","meaningThai":"ความอดทนต่อแอลกอฮอล์จะลดลงตามอายุ"}],"partOfSpeech":["preposition","verb","other"]},
  {"id":"hsk5-1088","chinese":"碎","pinyin":"suì","meaning":"(transitive or intransitive verb) to break into pieces; to shatter; to crumble; broken; fragmentary; scattered; garrulous","meaningThai":"แตกหัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"碎瓶子的玻璃渣散落在人行道上。","pinyin":"Suì píng zǐ de bō lí zhā sàn luò zài rén háng dào shàng。","meaning":"Glass from broken bottles litters the sidewalk.","meaningThai":"แก้วจากขวดที่แตกเกลื่อนกลาดบนทางเท้า"},{"chinese":"这种新材料实际上是不碎的。","pinyin":"Zhè zhǒng xīn cái liào shí jì shàng shì bù suì de。","meaning":"This new material is virtually unbreakable.","meaningThai":"วัสดุใหม่นี้แทบไม่แตกหักเลย"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1089","chinese":"随后","pinyin":"suíhòu","meaning":"soon after","meaningThai":"ต่อมา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"随后，新的准则发给了所有雇员。","pinyin":"Suí hòu， xīn de zhǔn zé fā gěi le suǒ yǒu gù yuán。","meaning":"Subsequently, new guidelines were issued to all employees.","meaningThai":"ต่อมาได้มีการออกแนวปฏิบัติใหม่ให้กับพนักงานทุกคน"},{"chinese":"让我把这个弄完，随后就来。","pinyin":"Ràng wǒ bǎ zhè gè nòng wán， suí hòu jiù lái。","meaning":"Let me just finish this and then I'll come.","meaningThai":"ขอจบแค่นี้ก่อนแล้วจะมาครับ.."}],"partOfSpeech":["adverb","other"]},
  {"id":"hsk5-1090","chinese":"随时","pinyin":"suíshí","meaning":"at any time; at all times; at the right time; whenever necessary","meaningThai":"ในเวลาใดก็ได้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"快点！他随时都会回来。","pinyin":"Kuài diǎn！ tā suí shí dū huì huí lái。","meaning":"Hurry up! He'll be back any minute now.","meaningThai":"รีบหน่อย! เขาจะกลับมาทุกนาทีตอนนี้"},{"chinese":"你必须随时准备出发。","pinyin":"Nǐ bì xū suí shí zhǔn bèi chū fā。","meaning":"You must be ready to leave at a moment's notice.","meaningThai":"คุณต้องพร้อมที่จะออกเดินทางทันที"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1091","chinese":"随手","pinyin":"suíshǒu","meaning":"conveniently; without extra trouble; while doing it; in passing","meaningThai":"ไม่เป็นทางการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她走进自己的房间随手把门关上。","pinyin":"Tā zǒu jìn zì jǐ de fáng jiān suí shǒu bǎ mén guān shàng。","meaning":"She went into her room and shut the door behind her.","meaningThai":"เธอเข้าไปในห้องของเธอแล้วปิดประตูตามหลังเธอ"},{"chinese":"接着他走了出去，随手把灯关掉。","pinyin":"Jiē zháo tā zǒu le chū qù， suí shǒu bǎ dēng guān diào。","meaning":"Then he walked out, flipping the lights off.","meaningThai":"แล้วเขาก็เดินออกไปปิดไฟ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1092","chinese":"随意","pinyin":"suíyì","meaning":"as one wishes; according to one's wishes; at will; voluntary; conscious","meaningThai":"สุ่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"如果你有什么问题，请随意问我好了。","pinyin":"Rú guǒ nǐ yǒu shí mó wèn tí， qǐng suí yì wèn wǒ hǎo le。","meaning":"If you have any questions at all, please feel free to ask me.","meaningThai":"หากคุณมีคำถามใด ๆ โปรดอย่าลังเลที่จะถามฉัน"},{"chinese":"他们穿着随意，可能是学生。","pinyin":"Tā mén chuān zháo suí yì， kě néng shì xué shēng。","meaning":"They were casually dressed; possibly students.","meaningThai":"พวกเขาแต่งตัวสบายๆ อาจเป็นนักเรียน"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1093","chinese":"损害","pinyin":"sǔnhài","meaning":"harm; to damage; to impair","meaningThai":"ความเสียหาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"已知接触铅会损害幼童的大脑。","pinyin":"Yǐ zhī jiē chù qiān huì sǔn hài yòu tóng de dà nǎo。","meaning":"Exposure to lead is known to damage the brains of young children.","meaningThai":"การสัมผัสสารตะกั่วเป็นที่รู้กันว่าทำลายสมองของเด็กเล็ก"},{"chinese":"这会严重损害公司的声誉。","pinyin":"Zhè huì yán zhòng sǔn hài gōng sī de shēng yù。","meaning":"This could seriously injure the company's reputation.","meaningThai":"สิ่งนี้อาจส่งผลเสียต่อชื่อเสียงของบริษัทอย่างร้ายแรง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1094","chinese":"损失","pinyin":"sǔnshī","meaning":"loss; damage; to lose; to suffer damage","meaningThai":"ความเสียหาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"造成损失。","pinyin":"Zao cheng sun shi.","meaning":"Cause losses.","meaningThai":"ทำให้เกิดความสูญเสีย."}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-1095","chinese":"所","pinyin":"suǒ","meaning":"actually; place; classifier for houses, small buildings, institutions etc; that which; particle introducing a relative clause or passive","meaningThai":"สถานที่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"三所学院合并成了一所新的大学。","pinyin":"Sān suǒ xué yuàn hé bìng chéng le yī suǒ xīn de dà xué。","meaning":"Three colleges have come together to create a new university.","meaningThai":"สามวิทยาลัยมารวมตัวกันเพื่อสร้างมหาวิทยาลัยแห่งใหม่"},{"chinese":"这所宅院已向公众开放。","pinyin":"Zhè suǒ zhái yuàn yǐ xiàng gōng zhòng kāi fàng。","meaning":"The house had been thrown open to the public.","meaningThai":"บ้านถูกโยนออกไปเปิดให้ประชาชนทั่วไป"}],"partOfSpeech":["particle","measure word","noun"]},
  {"id":"hsk5-1096","chinese":"锁","pinyin":"suǒ","meaning":"to lock; to lock up; a lock","meaningThai":"ล็อค","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他把钥匙插入锁里转动。","pinyin":"Tā bǎ yuè chí chā rù suǒ lǐ zhuǎn dòng。","meaning":"He put the key in the lock and turned it.","meaningThai":"เขาใส่กุญแจลงในล็อคและหมุนมัน"},{"chinese":"锁锈住了，我们得把门砸开。","pinyin":"Suǒ xiù zhù le， wǒ mén dé bǎ mén zá kāi。","meaning":"The lock was rusty, so we had to smash the door open.","meaningThai":"ตัวล็อคเป็นสนิมเราจึงต้องทุบประตูให้เปิดออก"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-1097","chinese":"缩短","pinyin":"suōduǎn","meaning":"to curtail; to cut down","meaningThai":"สั้นลง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"交易日为了庆祝劳动节而缩短。","pinyin":"Jiāo yì rì wéi le qìng zhù láo dòng jié ér suō duǎn。","meaning":"The trading day is shortened in observance of the Labour Day holiday.","meaningThai":"วันซื้อขายจะสั้นลงเนื่องในวันหยุดวันแรงงาน"},{"chinese":"受伤的问题有可能缩短他的职业生涯。","pinyin":"Shòu shāng de wèn tí yǒu kě néng suō duǎn tā de zhí yè shēng yá。","meaning":"Injury problems could shorten his career.","meaningThai":"ปัญหาการบาดเจ็บอาจทำให้อาชีพการงานของเขาสั้นลง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1098","chinese":"缩小","pinyin":"suōxiǎo","meaning":"to reduce; to decrease; to shrink","meaningThai":"ซูมออก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"从某种意义上说电视把世界缩小了。","pinyin":"Cóng mǒu zhǒng yì yì shàng shuō diàn shì bǎ shì jiè suō xiǎo le。","meaning":"Television in a sense has shrunk the world.","meaningThai":"โทรทัศน์ทำให้โลกหดตัว"},{"chinese":"政府已经改变了缩小班级规模的承诺。","pinyin":"Zhèng fǔ yǐ jīng gǎi biàn le suō xiǎo bān jí guī mó de chéng nuò。","meaning":"The government had retreated from its pledge to reduce class sizes.","meaningThai":"รัฐบาลได้ถอนคำมั่นสัญญาที่จะลดขนาดชั้นเรียน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1099","chinese":"宿舍","pinyin":"sùshè","meaning":"dormitory; dorm room; living quarters; hostel","meaningThai":"หอพัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"现在许多大学的学生宿舍已经联网。","pinyin":"Xiàn zài xǔ duō dà xué de xué shēng sù shě yǐ jīng lián wǎng。","meaning":"Many colleges now have wired dormitories.","meaningThai":"ปัจจุบันวิทยาลัยหลายแห่งมีหอพักแบบมีสาย"},{"chinese":"学生们抗议宿舍里过度拥挤。","pinyin":"Xué shēng mén kàng yì sù shě lǐ guò dù yōng jǐ。","meaning":"Students were protesting at overcrowding in the dorms.","meaningThai":"นักศึกษาออกมาประท้วงความแออัดยัดเยียดในหอพัก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1100","chinese":"台灯","pinyin":"táidēng","meaning":"desk lamp; table lamp","meaningThai":"โคมไฟตั้งโต๊ะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这有几个沙发、衣柜、台灯和书架。","pinyin":"Zhè yǒu jī gè shā fā、 yī guì、 tái dēng hé shū jià。","meaning":"There are sofas, closets, table lamps and bookshelves.","meaningThai":"มีทั้งโซฟา ตู้เสื้อผ้า โคมไฟตั้งโต๊ะ และชั้นหนังสือ"},{"chinese":"台灯刚刚突然不亮了。","pinyin":"Tái dēng gāng gāng tū rán bù liàng le。","meaning":"The table lamp just went out suddenly.","meaningThai":"โคมไฟตั้งโต๊ะเพิ่งดับลงกะทันหัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1101","chinese":"台阶","pinyin":"táijiē","meaning":"steps; flight of steps; step (over obstacle); fig. way out of an embarrassing situation; bench (geology)","meaningThai":"ขั้นตอน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些石头台阶被磨平破裂了。","pinyin":"Zhè xiē shí tóu tái jiē bèi mó píng pò liè le。","meaning":"The stone steps were worn and broken.","meaningThai":"ขั้นบันไดหินก็ชำรุดทรุดโทรม"},{"chinese":"他跳上了台阶，按了门铃。","pinyin":"Tā tiào shàng le tái jiē， àn le mén líng。","meaning":"He bounded up the steps and pushed the bell of the door.","meaningThai":"เขากระโดดขึ้นบันไดแล้วกดกริ่งประตู"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1102","chinese":"太太","pinyin":"tàitai","meaning":"married woman; Mrs.; Madam; wife","meaningThai":"นาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"贝克太太，我很高兴与您相识。","pinyin":"Bèi kè tài tài， wǒ hěn gāo xīng yǔ nín xiāng shí。","meaning":"I am delighted to make your acquaintance, Mrs Baker.","meaningThai":"ฉันดีใจที่ได้รู้จักคุณ คุณเบเกอร์"},{"chinese":"哈迪太太忍住了没做任何评论。","pinyin":"Hā dí tài tài rěn zhù le méi zuò rèn hé píng lùn。","meaning":"Mrs. Hardie refrained from making any comment.","meaningThai":"นางฮาร์ดีงดเว้นจากการแสดงความคิดเห็นใดๆ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1103","chinese":"谈话","pinyin":"tánhuà","meaning":"to talk (with sb); to have a conversation; talk; conversation","meaningThai":"การสนทนา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们谈话时，比尔忙着做午饭。","pinyin":"Wǒ mén tán huà shí， bǐ ěr máng zháo zuò wǔ fàn。","meaning":"While we talked, Bill busied himself fixing lunch.","meaningThai":"ขณะที่เราคุยกัน บิลก็ยุ่งอยู่กับการเตรียมอาหารกลางวัน"},{"chinese":"她用尽办法要他跟她谈话。","pinyin":"Tā yòng jìn bàn fǎ yào tā gēn tā tán huà。","meaning":"She tried desperately to engage him in conversation.","meaningThai":"เธอพยายามอย่างยิ่งที่จะให้เขาสนทนา"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-1104","chinese":"桃","pinyin":"táo","meaning":"peach","meaningThai":"พีช","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我能闻到瓜桃熟透了的香甜味道。","pinyin":"Wǒ néng wén dào guā táo shú tòu le de xiāng tián wèi dào。","meaning":"I could smell the honeyed ripeness of melons and peaches.","meaningThai":"ฉันได้กลิ่นความสุกงอมของน้ำผึ้งของแตงและลูกพีช"},{"chinese":"我桃是粉红色的。","pinyin":"Wǒ táo shì fěn hóng sè de。","meaning":"My peach is pink.","meaningThai":"ลูกพีชของฉันเป็นสีชมพู"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1105","chinese":"套","pinyin":"tào","meaning":"to cover; to encase; cover; sheath; to overlap; to interleave; to model after; to copy; formula; harness; loop of rope; (fig.) to fish for; to obtain slyly; classifier for sets, collections; bend (of a river or mountain range, in place names); tau (Greek letter Ττ)","meaningThai":"ชุด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你有避孕套吗？","pinyin":"Nǐ yǒu bì yùn tào ma？","meaning":"Do you have a condom? / Do you have any condoms?","meaningThai":"คุณมีถุงยางอนามัยไหม? / คุณมีถุงยางอนามัยบ้างไหม?"},{"chinese":"那是您的手套嗎？","pinyin":"Nà shì nín de shǒu tào má？","meaning":"Are these your gloves?","meaningThai":"นี่คือถุงมือของคุณใช่ไหม?"}],"partOfSpeech":["measure word","verb","other"]},
  {"id":"hsk5-1106","chinese":"他人","pinyin":"tārén","meaning":"another person; sb else; other people","meaningThai":"คนอื่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个系统堪为他人仿效的典范。","pinyin":"Zhè gè xì tǒng kān wéi tā rén fǎng xiào de diǎn fàn。","meaning":"This system sets the pattern for others to follow.","meaningThai":"ระบบนี้กำหนดแบบแผนให้ผู้อื่นปฏิบัติตาม"},{"chinese":"他人的苦难使我大为震惊。","pinyin":"Tā rén de kǔ nán shǐ wǒ dà wéi zhèn jīng。","meaning":"The suffering of other people appals me.","meaningThai":"ความทุกข์ของคนอื่นทำให้ฉันตกใจ"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-1107","chinese":"特产","pinyin":"tèchǎn","meaning":"special local product; (regional) specialty","meaningThai":"พิเศษ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"鱼和甲壳类水生动物是特产。","pinyin":"Yú hé jiǎ ké lèi shuǐ shēng dòng wù shì tè chǎn。","meaning":"Fish and shellfish are the specialties.","meaningThai":"ปลาและหอยเป็นอาหารจานพิเศษ"},{"chinese":"海味是岛上的特产。","pinyin":"Hǎi wèi shì dǎo shàng de tè chǎn。","meaning":"Seafood is a speciality on the island.","meaningThai":"อาหารทะเลเป็นเมนูพิเศษบนเกาะ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1108","chinese":"疼痛","pinyin":"téngtòng","meaning":"pain; (of a body part) to be painful; to be sore; to hurt; (of a person) to be in pain","meaningThai":"ความเจ็บปวด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"疼痛渐渐消失了。","pinyin":"Téng tòng jiàn jiàn xiāo shī le。","meaning":"Gradually the pain seeped away.","meaningThai":"ความเจ็บปวดก็ค่อยๆ หายไป"},{"chinese":"按摩能减轻疼痛。","pinyin":"Àn mó néng jiǎn qīng téng tòng。","meaning":"Massage will help the pain.","meaningThai":"การนวดจะช่วยบรรเทาอาการปวดได้"}],"partOfSpeech":["adjective","noun"]},
  {"id":"hsk5-1109","chinese":"特色","pinyin":"tèsè","meaning":"characteristic; distinguishing feature or quality","meaningThai":"คุณสมบัติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"最新的款式有100多种新特色。","pinyin":"Zuì xīn de kuǎn shì yǒu 100 duō zhǒng xīn tè sè。","meaning":"The latest model has over 100 new features.","meaningThai":"รุ่นใหม่ล่าสุดมีคุณสมบัติใหม่มากกว่า 100 รายการ"},{"chinese":"菜单以各种烤肉和家禽肉为特色。","pinyin":"Cài dān yǐ gè zhǒng kǎo ròu hé jiā qín ròu wéi tè sè。","meaning":"The menu features roast meats and poultry.","meaningThai":"เมนูประกอบด้วยเนื้อย่างและสัตว์ปีก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1110","chinese":"特殊","pinyin":"tèshū","meaning":"special; particular; unusual; extraordinary","meaningThai":"พิเศษ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我們有特殊聯繫。","pinyin":"Wǒ mén yǒu tè shū lián xì。","meaning":"We have a special connection.","meaningThai":"เรามีการเชื่อมต่อพิเศษ"},{"chinese":"你有什么特殊的天赋吗？","pinyin":"Nǐ yǒu shí mó tè shū de tiān fù ma？","meaning":"Do you have any special talents?","meaningThai":"คุณมีความสามารถพิเศษอะไรบ้าง?"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1111","chinese":"特有","pinyin":"tèyǒu","meaning":"specific (to); characteristic (of); distinctive","meaningThai":"มีเอกลักษณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她说话带着特有的热情。","pinyin":"Tā shuō huà dài zháo tè yǒu de rè qíng。","meaning":"She spoke with characteristic enthusiasm.","meaningThai":"เธอพูดด้วยความกระตือรือร้นเป็นพิเศษ"},{"chinese":"每个焦虑的人都将有他/她自己特有的问题或担心。","pinyin":"Měi gè jiāo lǜ de rén dū jiāng yǒu tā / tā zì jǐ tè yǒu de wèn tí huò dān xīn。","meaning":"Every anxious person will have his or her own special problems or fears.","meaningThai":"คนที่วิตกกังวลทุกคนจะมีปัญหาหรือความกลัวเป็นพิเศษเป็นของตัวเอง"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1112","chinese":"特征","pinyin":"tèzhēng","meaning":"characteristic; diagnostic property; distinctive feature; trait","meaningThai":"คุณสมบัติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"变性者需要不断服用激素来维持性别特征吗？","pinyin":"Biàn xìng zhě xū yào bù duàn fú yòng jī sù lái wéi chí xìng bié tè zhēng ma？","meaning":"Do transgender people need to continuously use hormones to maintain their sexual characteristics?","meaningThai":"คนข้ามเพศจำเป็นต้องใช้ฮอร์โมนเพื่อรักษาลักษณะทางเพศอย่างต่อเนื่องหรือไม่?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1113","chinese":"替","pinyin":"tì","meaning":"to substitute for; to take the place of; to replace; for; on behalf of; to stand in for","meaningThai":"สำหรับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"请把这封信替我寄了好吗？","pinyin":"Qǐng bǎ zhè fēng xìn tì wǒ jì le hǎo ma？","meaning":"Could you post this letter for me?","meaningThai":"คุณช่วยโพสต์จดหมายนี้ให้ฉันได้ไหม"},{"chinese":"旅馆经理示意行李工替我拿箱子。","pinyin":"Lǚ guǎn jīng lǐ shì yì háng lǐ gōng tì wǒ ná xiāng zǐ。","meaning":"The hotel manager signed to the porter to pick up my case.","meaningThai":"ผู้จัดการโรงแรมเซ็นสัญญากับพนักงานยกกระเป๋าเพื่อรับคดีของฉัน"}],"partOfSpeech":["preposition","verb"]},
  {"id":"hsk5-1114","chinese":"填","pinyin":"tián","meaning":"to fill or stuff; (of a form etc) to fill in","meaningThai":"เติม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些社区现正开始用回收这种较为廉价的方法替代废物填埋法。","pinyin":"Zhè xiē shè qū xiàn zhèng kāi shǐ yòng huí shōu zhè zhǒng jiào wéi lián jià de fāng fǎ tì dài fèi wù tián mái fǎ。","meaning":"These communities are now turning to recycling as a cheaper alternative to landfills.","meaningThai":"ปัจจุบันชุมชนเหล่านี้หันมาใช้การรีไซเคิลเป็นทางเลือกที่ถูกกว่าการฝังกลบ"},{"chinese":"在生产的每一阶段都将有文书工作—要填的表格，要获得的许可，要写的信。","pinyin":"Zài shēng chǎn de měi yī jiē duàn dū jiāng yǒu wén shū gōng zuò — yào tián de biǎo gé， yào huò dé de xǔ kě， yào xiě de xìn。","meaning":"At every stage in the production there will be paperwork—forms to fill in, permissions to obtain, letters to write.","meaningThai":"ในทุกขั้นตอนของการผลิตจะมีเอกสาร เช่น แบบฟอร์มที่ต้องกรอก การอนุญาต การเขียนจดหมาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1115","chinese":"天空","pinyin":"tiānkōng","meaning":"sky","meaningThai":"ท้องฟ้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"空气清新，天空碧蓝。","pinyin":"Kōng qì qīng xīn， tiān kōng bì lán。","meaning":"The air was crisp and clear and the sky was blue.","meaningThai":"อากาศแจ่มใสและท้องฟ้าเป็นสีฟ้า"},{"chinese":"太阳低挂在天空。","pinyin":"Tài yáng dī guà zài tiān kōng。","meaning":"The sun was low in the sky.","meaningThai":"พระอาทิตย์อยู่ต่ำในท้องฟ้า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1116","chinese":"甜品","pinyin":"tiánpǐn","meaning":"Dessert","meaningThai":"ของหวาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"饭后我想吃甜品。","pinyin":"Fàn hòu wǒ xiǎng chī tián pǐn.","meaning":"I want dessert after the meal.","meaningThai":"ฉันต้องการของหวานหลังอาหาร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1117","chinese":"天上","pinyin":"tiānshàng","meaning":"celestial; heavenly","meaningThai":"สวรรค์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"天上滿是飛機。","pinyin":"Tiān shàng mǎn shì fēi jī。","meaning":"The sky was filled with airplanes. / The sky was filled with aeroplanes.","meaningThai":"ท้องฟ้าเต็มไปด้วยเครื่องบิน / ท้องฟ้าเต็มไปด้วยเครื่องบิน"},{"chinese":"今天上午下雨。","pinyin":"Jīn tiān shàng wǔ xià yǔ。","meaning":"It will rain this morning.","meaningThai":"เช้านี้ฝนจะตก"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1118","chinese":"调","pinyin":"tiáo","meaning":"to transfer; to move (troops or cadres); to investigate; to enquire into; accent; view; argument; key (in music); mode (music); tune; tone; melody","meaningThai":"ปรับแต่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"补偿可由调税实现。","pinyin":"Bǔ cháng kě yóu tiáo shuì shí xiàn。","meaning":"Compensation could be made by adjustments to taxation.","meaningThai":"การชดเชยสามารถทำได้โดยการปรับภาษี"},{"chinese":"我们也许要将这个数字往上调一调。","pinyin":"Wǒ mén yě xǔ yào jiāng zhè gè shù zì wǎng shàng tiáo yī tiáo。","meaning":"We may have to revise this figure upwards.","meaningThai":"เราอาจจะต้องแก้ไขตัวเลขนี้ขึ้นไป"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-1119","chinese":"挑","pinyin":"tiāo","meaning":"to carry on a shoulder pole; to choose; to pick; to nitpick","meaningThai":"เลือก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"汤姆相当挑剔。","pinyin":"Tāng mǔ xiāng dāng tiāo tī。","meaning":"Tom is quite fussy.","meaningThai":"ทอมค่อนข้างจุกจิก"},{"chinese":"給我挑一顆蘋果。","pinyin":"Gěi wǒ tiāo yī kē pín guǒ。","meaning":"Pick me an apple.","meaningThai":"เลือกแอปเปิ้ลมาให้ฉัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1120","chinese":"跳高","pinyin":"tiàogāo","meaning":"high jump (athletics)","meaningThai":"กระโดดสูง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她创造了新的跳高世界纪录。","pinyin":"Tā chuàng zào le xīn de tiào gāo shì jiè jì lù。","meaning":"She set a new world record for the high jump.","meaningThai":"เธอสร้างสถิติโลกใหม่สำหรับการกระโดดสูง"},{"chinese":"她跳高得了银牌。","pinyin":"Tā tiào gāo dé le yín pái。","meaning":"She won a silver medal in the high jump.","meaningThai":"เธอได้รับรางวัลเหรียญเงินจากการกระโดดสูง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1121","chinese":"调皮","pinyin":"tiáopí","meaning":"naughty; mischievous; unruly","meaningThai":"ซน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她在椅子上前后晃动，像个调皮的孩子。","pinyin":"Tā zài yǐ zǐ shàng qián hòu huǎng dòng， xiàng gè tiáo pí de hái zǐ。","meaning":"She rocks back and forth on her chair like a mischievous child.","meaningThai":"เธอโยกไปมาบนเก้าอี้เหมือนเด็กซุกซน"},{"chinese":"姑娘们，你们太调皮了。","pinyin":"Gū niáng mén， nǐ mén tài tiáo pí le。","meaning":"Girls, you're being very naughty.","meaningThai":"สาวๆ คุณซนมากเลยนะ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1122","chinese":"挑选","pinyin":"tiāoxuǎn","meaning":"to choose; to select","meaningThai":"เลือก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"别让我挑选。我连想都不愿想。","pinyin":"Bié ràng wǒ tiāo xuǎn。 wǒ lián xiǎng dū bù yuàn xiǎng。","meaning":"Don't ask me to choose. I don't want to go there.","meaningThai":"อย่าขอให้ฉันเลือก ฉันไม่ต้องการที่จะไปที่นั่น"},{"chinese":"会计们可以任意挑选公司的汽车。","pinyin":"Huì jì mén kě yǐ rèn yì tiāo xuǎn gōng sī de qì chē。","meaning":"Accountants can take their pick of company cars.","meaningThai":"นักบัญชีสามารถเลือกรถของบริษัทได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1123","chinese":"跳远","pinyin":"tiàoyuǎn","meaning":"long jump (athletics)","meaningThai":"กระโดดไกล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他来了一个三级跳远穿过了大厅。","pinyin":"Tā lái le yī gè sān jí tiào yuǎn chuān guò le dà tīng。","meaning":"He crossed the hall with a hop, skip and a jump.","meaningThai":"เขาข้ามห้องโถงด้วยการกระโดด กระโดด และกระโดด"},{"chinese":"跳远世界纪录的保持者是谁？","pinyin":"Tiào yuǎn shì jiè jì lù de bǎo chí zhě shì shuí？","meaning":"Who holds the world record for the long jump?","meaningThai":"ใครเป็นผู้ครองสถิติโลกในการกระโดดไกล?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1124","chinese":"挑战","pinyin":"tiǎozhàn","meaning":"to challenge; challenge","meaningThai":"ท้าทาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"女主席面临她职位的最大挑战。","pinyin":"Nǚ zhǔ xí miàn lín tā zhí wèi de zuì dà tiāo zhàn。","meaning":"The chairwoman is up against the greatest challenge to her position.","meaningThai":"ประธานหญิงต้องเผชิญหน้ากับความท้าทายที่ยิ่งใหญ่ที่สุดในตำแหน่งของเธอ"},{"chinese":"他们计划挑战法律的合宪法性。","pinyin":"Tā mén jì huá tiāo zhàn fǎ lǜ de hé xiàn fǎ xìng。","meaning":"They plan to challenge the constitutionality of the law.","meaningThai":"พวกเขาวางแผนที่จะท้าทายรัฐธรรมนูญของกฎหมาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1125","chinese":"调整","pinyin":"tiáozhěng","meaning":"to adjust; adjustment; revision","meaningThai":"การปรับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些数字未作季节性变化调整。","pinyin":"Zhè xiē shù zì wèi zuò jì jié xìng biàn huà tiáo zhěng。","meaning":"The figures aren't adjusted for seasonal variations.","meaningThai":"ตัวเลขไม่ได้รับการปรับตามการเปลี่ยนแปลงตามฤดูกาล"},{"chinese":"他已被迫调整了日程安排。","pinyin":"Tā yǐ bèi pò tiáo zhěng le rì chéng ān pái。","meaning":"He has been forced to adjust his schedule.","meaningThai":"เขาถูกบังคับให้ปรับตารางเวลาของเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1126","chinese":"提倡","pinyin":"tíchàng","meaning":"to promote; to advocate","meaningThai":"สนับสนุน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"提倡环保。","pinyin":"Ti chang huan bao.","meaning":"Promote environmental protection.","meaningThai":"ส่งเสริมการคุ้มครองสิ่งแวดล้อม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1127","chinese":"贴","pinyin":"tiē","meaning":"to stick; to paste; to post (e.g. on a blog); to keep close to; to fit snugly; to subsidize; allowance (e.g. money for food or housing); sticker; classifier for sticking plaster: strip","meaningThai":"ติด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她把他的照片贴满了卧室的墙。","pinyin":"Tā bǎ tā de zhào piàn tiē mǎn le wò shì de qiáng。","meaning":"She had photos of him plastered all over her bedroom wall.","meaningThai":"เธอมีรูปถ่ายของเขาติดอยู่เต็มผนังห้องนอนของเธอ"},{"chinese":"这些档案按主题内容贴有色标。","pinyin":"Zhè xiē dàng àn àn zhǔ tí nèi róng tiē yǒu sè biāo。","meaning":"The files have labels that are colour-coded according to subject.","meaningThai":"ไฟล์มีป้ายกำกับที่มีรหัสสีตามหัวเรื่อง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1128","chinese":"铁路","pinyin":"tiělù","meaning":"railroad; railway","meaningThai":"ทางรถไฟ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"铁路使这个国家的东部不再闭塞。","pinyin":"Tiě lù shǐ zhè gè guó jiā de dōng bù bù zài bì sāi。","meaning":"The railway opened up the east of the country.","meaningThai":"ทางรถไฟเปิดทางทิศตะวันออกของประเทศ"},{"chinese":"早在1974年铁路就电气化了。","pinyin":"Zǎo zài 1974 nián tiě lù jiù diàn qì huà le。","meaning":"The railway line was electrified as long ago as 1974.","meaningThai":"ทางรถไฟสายนี้ถูกไฟฟ้าใช้เมื่อนานมาแล้วเมื่อปี พ.ศ. 2517"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1129","chinese":"体会","pinyin":"tǐhuì","meaning":"to know from experience; to learn through experience; to realize; understanding; experience","meaningThai":"ประสบการณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们都体会到了她的论据的分量。","pinyin":"Wǒ mén dū tǐ huì dào le tā de lùn jù de fēn liáng。","meaning":"We all felt the force of her arguments.","meaningThai":"เราทุกคนรู้สึกถึงพลังของการโต้แย้งของเธอ"},{"chinese":"丧子之痛是难以体会的。","pinyin":"Sāng zǐ zhī tòng shì nán yǐ tǐ huì de。","meaning":"It is hard to fathom the pain felt at the death of a child.","meaningThai":"เป็นการยากที่จะหยั่งรู้ถึงความเจ็บปวดที่เกิดขึ้นเมื่อเด็กเสียชีวิต"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1130","chinese":"提交","pinyin":"tíjiāo","meaning":"to submit (a report etc); to refer (a problem) to sb","meaningThai":"ยื่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"提交报告。","pinyin":"Ti jiao bao gao.","meaning":"Submit a report.","meaningThai":"ส่งรายงาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1131","chinese":"体力","pinyin":"tǐlì","meaning":"physical strength; physical power","meaningThai":"กำลังกาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"体力劳动。","pinyin":"Ti li lao dong.","meaning":"Physical labor.","meaningThai":"แรงงานทางกายภาพ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1132","chinese":"题目","pinyin":"tímù","meaning":"subject; title; topic","meaningThai":"หัวข้อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们似乎偏离了应当讨论的题目。","pinyin":"Wǒ mén sì hū piān lí le yīng dāng tǎo lùn de tí mù。","meaning":"We seem to have got off the subject we're meant to be discussing.","meaningThai":"ดูเหมือนเราจะหลุดประเด็นที่เราตั้งใจจะพูดคุยกันไปแล้ว"},{"chinese":"这个题目将在下一章里详细论述。","pinyin":"Zhè gè tí mù jiāng zài xià yī zhāng lǐ xiáng xì lùn shù。","meaning":"This topic will be discussed at greater length in the next chapter.","meaningThai":"หัวข้อนี้จะกล่าวถึงในความยาวที่มากขึ้นในบทถัดไป"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1133","chinese":"停留","pinyin":"tíngliú","meaning":"to stay somewhere temporarily; to stop over","meaningThai":"อยู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她多停留了五天。","pinyin":"Tā duō tíng liú le wǔ tiān。","meaning":"She extended her stay by five days.","meaningThai":"เธอขยายเวลาการอยู่ต่อไปอีกห้าวัน"},{"chinese":"她延長停留五天。","pinyin":"Tā yán cháng tíng liú wǔ tiān。","meaning":"She extended her stay by five days.","meaningThai":"เธอขยายเวลาการอยู่ต่อไปอีกห้าวัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1134","chinese":"提起","pinyin":"tíqǐ","meaning":"to mention; to speak of; to lift; to pick up; to arouse; to raise (a topic, a heavy weight, one's fist, one's spirits etc)","meaningThai":"นำขึ้นมา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他没有提起和妻子的争吵。","pinyin":"Tā méi yǒu tí qǐ hé qī zǐ de zhēng chǎo。","meaning":"He did not mention the quarrel with his wife.","meaningThai":"เขาไม่ได้พูดถึงเรื่องทะเลาะกับภรรยา"},{"chinese":"他非常懊悔提起那件事。","pinyin":"Tā fēi cháng ào huǐ tí qǐ nà jiàn shì。","meaning":"He bitterly regretted ever having mentioned it.","meaningThai":"เขาเสียใจอย่างขมขื่นที่เคยพูดถึงมัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1135","chinese":"提升","pinyin":"tíshēng","meaning":"to promote (to a higher-ranking position); to lift; to hoist; (fig.) to elevate; to raise; to improve","meaningThai":"ส่งเสริม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我听说，我被定为提升的人选。","pinyin":"Wǒ tīng shuō， wǒ bèi dìng wéi tí shēng de rén xuǎn。","meaning":"I was told that I was being slated for promotion.","meaningThai":"ฉันได้รับแจ้งว่าฉันถูกกำหนดให้เลื่อนตำแหน่ง"},{"chinese":"不出几个月，她就被提升至部级。","pinyin":"Bù chū jī gè yuè， tā jiù bèi tí shēng zhì bù jí。","meaning":"Within months she was elevated to ministerial rank.","meaningThai":"ภายในไม่กี่เดือนเธอก็ได้รับการเลื่อนตำแหน่งเป็นรัฐมนตรี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1136","chinese":"提问","pinyin":"tíwèn","meaning":"to question; to quiz; to grill","meaningThai":"ถามคำถาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你们最后将有机会提问任何问题。","pinyin":"Nǐ mén zuì hòu jiāng yǒu jī huì tí wèn rèn hé wèn tí。","meaning":"You'll have the opportunity to ask any questions at the end.","meaningThai":"คุณจะมีโอกาสถามคำถามในตอนท้าย"},{"chinese":"她敌意地瞪着向她提问的人。","pinyin":"Tā dí yì dì dèng zháo xiàng tā tí wèn de rén。","meaning":"She fixed her questioner with a hostile glare.","meaningThai":"เธอจ้องผู้ถามด้วยสายตาที่ไม่เป็นมิตร"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1137","chinese":"体现","pinyin":"tǐxiàn","meaning":"to embody; to reflect; to incarnate","meaningThai":"สะท้อน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们的宪法体现了民主的所有基本原则。","pinyin":"Wǒ mén de xiàn fǎ tǐ xiàn le mín zhǔ de suǒ yǒu jī běn yuán zé。","meaning":"Our constitution embodies all the fundamental principles of democracy.","meaningThai":"รัฐธรรมนูญของเรารวบรวมหลักการพื้นฐานทั้งหมดของประชาธิปไตย"},{"chinese":"宗教团体现在可以公开集会了。","pinyin":"Zōng jiào tuán tǐ xiàn zài kě yǐ gōng kāi jí huì le。","meaning":"Religious groups are now able to meet quite openly.","meaningThai":"ปัจจุบันกลุ่มศาสนาสามารถพบปะกันได้อย่างเปิดเผย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1138","chinese":"体验","pinyin":"tǐyàn","meaning":"to experience for oneself","meaningThai":"ประสบการณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是奇妙的体验。","pinyin":"Zhè shì qí miào de tǐ yàn。","meaning":"It's been an amazing experience.","meaningThai":"มันเป็นประสบการณ์ที่น่าอัศจรรย์"},{"chinese":"除了雨之外，我们体验了强风。","pinyin":"Chú le yǔ zhī wài， wǒ mén tǐ yàn le qiáng fēng。","meaning":"Besides the rain, we experienced heavy winds.","meaningThai":"นอกจากฝนตกแล้วเรายังมีลมแรงอีกด้วย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1139","chinese":"同","pinyin":"tóng","meaning":"like; same; similar; together; alike; with","meaningThai":"เดียวกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她始终抱乐观态度同疾病斗争。","pinyin":"Tā shǐ zhōng bào lè guān tài dù tóng jí bìng dǒu zhēng。","meaning":"She fought the disease with unfailing good humour.","meaningThai":"เธอต่อสู้กับโรคร้ายด้วยอารมณ์ขันอันไม่สิ้นสุด"},{"chinese":"她还在同膝部的伤痛作斗争。","pinyin":"Tā huán zài tóng xī bù de shāng tòng zuò dǒu zhēng。","meaning":"She's still battling with a knee injury.","meaningThai":"เธอยังคงต่อสู้กับอาการบาดเจ็บที่เข่า"}],"partOfSpeech":["preposition","verb","adverb"]},
  {"id":"hsk5-1140","chinese":"通常","pinyin":"tōngcháng","meaning":"regular; usual; normal; usually; normally","meaningThai":"โดยทั่วไป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他通常想跟我练习英语。","pinyin":"Tā tōng cháng xiǎng gēn wǒ liàn xí yīng yǔ。","meaning":"He usually wants to practise his English on me.","meaningThai":"ปกติแล้วเขาต้องการฝึกภาษาอังกฤษกับฉัน"},{"chinese":"通常这种工作很乏味。","pinyin":"Tōng cháng zhè zhǒng gōng zuò hěn fá wèi。","meaning":"Usually, the work is boring.","meaningThai":"ปกติงานจะน่าเบื่อ"}],"partOfSpeech":["adverb","adjective"]},
  {"id":"hsk5-1141","chinese":"统计","pinyin":"tǒngjì","meaning":"statistics; to count; to add up","meaningThai":"สถิติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"统计数据显示明显变化。","pinyin":"Tǒng jì shù jù xiǎn shì míng xiǎn biàn huà.","meaning":"Statistical data shows significant changes.","meaningThai":"ข้อมูลทางสถิติแสดงการเปลี่ยนแปลงที่สำคัญ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1142","chinese":"痛苦","pinyin":"tòngkǔ","meaning":"pain; suffering; painful","meaningThai":"ความเจ็บปวด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"简依然怀着被拒绝的痛苦。","pinyin":"Jiǎn yī rán huái zháo bèi jù jué de tòng kǔ。","meaning":"Jane still nurses the pain of rejection.","meaningThai":"เจนยังคงรักษาความเจ็บปวดจากการถูกปฏิเสธ"},{"chinese":"这种痛苦是无法形容的。","pinyin":"Zhè zhǒng tòng kǔ shì wú fǎ xíng róng de。","meaning":"The pain is unspeakable.","meaningThai":"ความเจ็บปวดนั้นพูดไม่ได้"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1143","chinese":"同情","pinyin":"tóngqíng","meaning":"to sympathize with; sympathy","meaningThai":"สงสาร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"总统已对格鲁吉亚人民表示了同情。","pinyin":"Zǒng tǒng yǐ duì gé lǔ jí yà rén mín biǎo shì le tóng qíng。","meaning":"The president has offered his sympathy to the Georgian people.","meaningThai":"ประธานาธิบดีแสดงความเห็นใจต่อชาวจอร์เจีย"},{"chinese":"他的话里既有同情也有责备。","pinyin":"Tā de huà lǐ jì yǒu tóng qíng yě yǒu zé bèi。","meaning":"His words were a mixture of pity and reproof.","meaningThai":"คำพูดของเขามีทั้งความสงสารและการตำหนิ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1144","chinese":"通行","pinyin":"tōngxíng","meaning":"to go through; to pass through; to be in general use","meaningThai":"ผ่าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"禁止通行。","pinyin":"Jin zhi tong xing.","meaning":"No passage.","meaningThai":"ไม่มีข้อความผ่าน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1145","chinese":"同一","pinyin":"tóngyī","meaning":"identical; the same","meaningThai":"เดียวกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"本合同的所有开价均在同一范围内。","pinyin":"Běn hé tóng de suǒ yǒu kāi jià jūn zài tóng yī fàn wéi nèi。","meaning":"The offers for the contract were all in the same ballpark.","meaningThai":"ข้อเสนอสำหรับสัญญาทั้งหมดอยู่ในสนามเบสบอลเดียวกัน"},{"chinese":"同一颜色在不同光线下看起来会不同。","pinyin":"Tóng yī yán sè zài bù tóng guāng xiàn xià kàn qǐ lái huì bù tóng。","meaning":"The same hue will look different in different light.","meaningThai":"เฉดสีเดียวกันจะดูแตกต่างกันในแสงที่ต่างกัน"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1146","chinese":"统一","pinyin":"tǒngyī","meaning":"to unify; to integrate; unified; integrated","meaningThai":"แบบครบวงจร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些原则统一适用于所有部门。","pinyin":"Zhè xiē yuán zé tǒng yī shì yòng yú suǒ yǒu bù mén。","meaning":"The principles were applied uniformly across all the departments.","meaningThai":"หลักการถูกนำไปใช้อย่างเท่าเทียมกันในทุกแผนก"},{"chinese":"他们努力保证各部门之间的统一。","pinyin":"Tā mén nǔ lì bǎo zhèng gè bù mén zhī jiān de tǒng yī。","meaning":"They tried to ensure uniformity across the different departments.","meaningThai":"พวกเขาพยายามทำให้แผนกต่างๆ มีความสม่ำเสมอ"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-1147","chinese":"头","pinyin":"tou","meaning":"head; hair style; the top; end; beginning or end; a stub; remnant; chief; boss; side; aspect; first; leading; classifier for pigs or livestock","meaningThai":"หัว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是头。","pinyin":"Zhè shì tóu.","meaning":"This is head.","meaningThai":"นี่คือหัว."},{"chinese":"我看见了头。","pinyin":"Wǒ kànjiàn le tóu.","meaning":"I saw head.","meaningThai":"ฉันเห็นหัว."},{"chinese":"头在这里。","pinyin":"Tóu zài zhèlǐ.","meaning":"The head is here.","meaningThai":"หัวหน้าอยู่ที่นี่"}],"partOfSpeech":["noun","measure word","numeral","suffix"]},
  {"id":"hsk5-1148","chinese":"投","pinyin":"tóu","meaning":"to cast; to send; to throw oneself (into the river etc); to seek refuge; to place oneself into the hands of","meaningThai":"หล่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在上次选举中你是怎么投的票？","pinyin":"Zài shàng cì xuǎn jǔ zhōng nǐ shì zěn mó tóu de piào？","meaning":"How did you vote at the last election?","meaningThai":"คุณลงคะแนนเสียงในการเลือกตั้งครั้งล่าสุดอย่างไร?"},{"chinese":"很少有成员计划投他的票。","pinyin":"Hěn shǎo yǒu chéng yuán jì huá tóu tā de piào。","meaning":"Few members planned to vote for him.","meaningThai":"มีสมาชิกไม่กี่คนที่วางแผนจะลงคะแนนให้เขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1149","chinese":"投入","pinyin":"tóurù","meaning":"to throw into; to put into; to throw oneself into; to participate in; to invest in; absorbed; engrossed","meaningThai":"ลงทุน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"大量的工作已投入到这项工程。","pinyin":"Dà liáng de gōng zuò yǐ tóu rù dào zhè xiàng gōng chéng。","meaning":"A tremendous amount of work has gone into the project.","meaningThai":"มีงานจำนวนมหาศาลเข้าสู่โครงการนี้"},{"chinese":"应该赶紧让王子投入工作。","pinyin":"Yīng gāi gǎn jǐn ràng wáng zǐ tóu rù gōng zuò。","meaning":"The prince should be plunged into work.","meaningThai":"เจ้าชายควรกระโจนเข้าทำงาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1150","chinese":"团","pinyin":"tuán","meaning":"round; lump; ball; to roll into a ball; to gather; regiment; group; society; classifier for a lump or a soft mass: wad (of paper), ball (of wool), cloud (of smoke)","meaningThai":"กลุ่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"整团整团的旅游者乘长途汽车到达。","pinyin":"Zhěng tuán zhěng tuán de lǚ yóu zhě chéng cháng tú qì chē dào dá。","meaning":"Tourists were arriving by the coachload.","meaningThai":"นักท่องเที่ยวเดินทางมาโดยรถโค้ช"},{"chinese":"这些颗粒聚结形成较大的团。","pinyin":"Zhè xiē kē lì jù jié xíng chéng jiào dà de tuán。","meaning":"These small particles agglomerate together to form larger clusters.","meaningThai":"อนุภาคขนาดเล็กเหล่านี้จะรวมตัวกันเป็นกระจุกที่ใหญ่ขึ้น"}],"partOfSpeech":["noun","measure word"]},
  {"id":"hsk5-1151","chinese":"团队","pinyin":"tuánduì","meaning":"team","meaningThai":"ทีม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该团队正试图搜寻遗失的细节。","pinyin":"Gāi tuán duì zhèng shì tú sōu xún yí shī de xì jié。","meaning":"The team is trying to ferret out missing details.","meaningThai":"ทีมงานพยายามค้นหารายละเอียดที่ขาดหายไป"},{"chinese":"总统加入到团队中接受媒体拍照。","pinyin":"Zǒng tǒng jiā rù dào tuán duì zhōng jiē shòu méi tǐ pāi zhào。","meaning":"The president joined the team for a photocall.","meaningThai":"ประธานร่วมถ่ายภาพหมู่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1152","chinese":"突出","pinyin":"tūchū","meaning":"prominent; outstanding; to give prominence to; to protrude; to project","meaningThai":"ยื่นออกมา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他有一张颧骨突出、棱角分明的脸。","pinyin":"Tā yǒu yī zhāng quán gǔ tū chū、 léng jiǎo fēn míng de liǎn。","meaning":"He had an angular face with prominent cheekbones.","meaningThai":"เขามีใบหน้าที่เป็นเหลี่ยมและมีโหนกแก้มที่โดดเด่น"},{"chinese":"这里，窗户在设计中有着突出的作用。","pinyin":"Zhè lǐ， chuāng hù zài shè jì zhōng yǒu zháo tū chū de zuò yòng。","meaning":"Here the window plays a prominent part in the design.","meaningThai":"ที่นี่หน้าต่างมีส่วนสำคัญในการออกแบบ"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1153","chinese":"土地","pinyin":"tǔdì","meaning":"land; soil; territory","meaningThai":"ที่ดิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们给无土地的人们分同等面积的土地。","pinyin":"Wǒ mén gěi wú tǔ dì de rén mén fēn tóng děng miàn jī de tǔ dì。","meaning":"We are giving an equal area of land to the landless.","meaningThai":"เรากำลังมอบพื้นที่ที่เท่าเทียมกันให้กับผู้ไม่มีที่ดิน"},{"chinese":"土地松软，像海绵似的。","pinyin":"Tǔ dì sōng ruǎn， xiàng hǎi mián sì de。","meaning":"The ground was soft and spongy.","meaningThai":"พื้นก็นุ่มและเป็นรูพรุน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1154","chinese":"土豆","pinyin":"tǔdòu","meaning":"potato; (Tw) peanut","meaningThai":"มันฝรั่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她在厨房里坐下，开始削土豆。","pinyin":"Tā zài chú fáng lǐ zuò xià， kāi shǐ xiāo tǔ dòu。","meaning":"She sat down in the kitchen and began peeling potatoes.","meaningThai":"เธอนั่งลงในครัวและเริ่มปอกมันฝรั่ง"},{"chinese":"送货送来的土豆少了好几公斤。","pinyin":"Sòng huò sòng lái de tǔ dòu shǎo le hǎo jī gōng jīn。","meaning":"The delivery of potatoes was several kilos light.","meaningThai":"การส่งมันฝรั่งเบาไปหลายกิโล"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1155","chinese":"图画","pinyin":"túhuà","meaning":"drawing; picture","meaningThai":"รูปภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"文字和图画可以扫描进计算机。","pinyin":"Wén zì hé tú huà kě yǐ sǎo miáo jìn jì suàn jī。","meaning":"Text and pictures can be scanned into the computer.","meaningThai":"สามารถสแกนข้อความและรูปภาพลงในคอมพิวเตอร์ได้"},{"chinese":"我的滑稽图画把孩子们逗乐了。","pinyin":"Wǒ de huá jī tú huà bǎ hái zǐ mén dòu lè le。","meaning":"My funny drawings amused the kids.","meaningThai":"ภาพวาดตลกของฉันทำให้เด็กๆ สนุกสนาน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1156","chinese":"退","pinyin":"tuì","meaning":"to retreat; to withdraw; to reject; to return (sth); to decline","meaningThai":"ล่าถอย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"建筑师向后退了退，欣赏着自己的作品。","pinyin":"Jiàn zhù shī xiàng hòu tuì le tuì， xīn shǎng zháo zì jǐ de zuò pǐn。","meaning":"The architect stepped back to admire his handiwork.","meaningThai":"สถาปนิกก้าวถอยหลังมาชื่นชมผลงานของเขา"},{"chinese":"你可以再退两英尺左右。","pinyin":"Nǐ kě yǐ zài tuì liǎng yīng chǐ zuǒ yòu。","meaning":"You can back up another two feet or so.","meaningThai":"คุณสามารถถอยได้อีกสองฟุตหรือมากกว่านั้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1157","chinese":"退出","pinyin":"tuìchū","meaning":"to withdraw; to abort; to quit; to log out (computing)","meaningThai":"ล้มเลิก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"按“退出”键返回到你的文档。","pinyin":"Àn “ tuì chū ” jiàn fǎn huí dào nǐ de wén dàng。","meaning":"Press Exit to return to your document.","meaningThai":"กด Exit เพื่อกลับไปยังเอกสารของคุณ"},{"chinese":"去年他因身体欠佳而退出了表演。","pinyin":"Qù nián tā yīn shēn tǐ qiàn jiā ér tuì chū le biǎo yǎn。","meaning":"He quit the show last year because of bad health.","meaningThai":"เขาออกจากรายการเมื่อปีที่แล้วเพราะสุขภาพไม่ดี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1158","chinese":"推动","pinyin":"tuīdòng","meaning":"to push (e.g. for acceptance of a plan); to promote; to give impetus to","meaningThai":"ส่งเสริม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他仍从事志愿工作推动当地创业。","pinyin":"Tā réng cóng shì zhì yuàn gōng zuò tuī dòng dāng dì chuàng yè。","meaning":"He is still involved in voluntary work promoting local enterprise.","meaningThai":"เขายังคงมีส่วนร่วมในงานอาสาสมัครเพื่อส่งเสริมวิสาหกิจท้องถิ่น"},{"chinese":"任何短缺都会推动粮价上涨。","pinyin":"Rèn hé duǎn quē dū huì tuī dòng liáng jià shàng zhǎng。","meaning":"Any shortage could push up grain prices.","meaningThai":"การขาดแคลนอาจส่งผลให้ราคาธัญพืชสูงขึ้นได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1159","chinese":"推广","pinyin":"tuīguǎng","meaning":"to extend; to spread; to popularize; generalization; promotion (of a product etc)","meaningThai":"การส่งเสริม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个地区正被推广为旅游点。","pinyin":"Zhè gè dì qū zhèng bèi tuī guǎng wéi lǚ yóu diǎn。","meaning":"The area is being promoted as a tourist destination.","meaningThai":"พื้นที่นี้กำลังได้รับการส่งเสริมให้เป็นสถานที่ท่องเที่ยว"},{"chinese":"她从事销售和推广工作。","pinyin":"Tā cóng shì xiāo shòu hé tuī guǎng gōng zuò。","meaning":"She works in sales and promotion.","meaningThai":"เธอทำงานด้านการขายและการส่งเสริมการขาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1160","chinese":"退还","pinyin":"tuìhuán","meaning":"return","meaningThai":"กลับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"保险公司将退还你应得的所有款项。","pinyin":"Bǎo xiǎn gōng sī jiāng tuì huán nǐ yīng dé de suǒ yǒu kuǎn xiàng。","meaning":"The insurance company will refund any amount due to you.","meaningThai":"บริษัทประกันภัยจะคืนเงินจำนวนใด ๆ ให้กับคุณ"},{"chinese":"有问题的产品应退还生产厂家。","pinyin":"Yǒu wèn tí de chǎn pǐn yīng tuì huán shēng chǎn chǎng jiā。","meaning":"Faulty goods should be returned to the manufacturers.","meaningThai":"สินค้าที่ชำรุดควรส่งคืนให้กับผู้ผลิต"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1161","chinese":"推荐","pinyin":"tuījiàn","meaning":"to recommend; recommendation","meaningThai":"แนะนำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我推荐这本书。","pinyin":"Wo tui jian zhe ben shu.","meaning":"I recommend this book.","meaningThai":"ฉันแนะนำหนังสือเล่มนี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1162","chinese":"推进","pinyin":"tuījìn","meaning":"to impel; to carry forward; to push on; to advance; to drive forward","meaningThai":"ก้าวหน้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们担心接下来会马上向首都推进。","pinyin":"Wǒ mén dān xīn jiē xià lái huì mǎ shàng xiàng shǒu dū tuī jìn。","meaning":"We feared that an advance on the capital would soon follow.","meaningThai":"เรากลัวว่าความก้าวหน้าในเมืองหลวงจะตามมาในไม่ช้า"},{"chinese":"该政府打算推进其改革计划。","pinyin":"Gāi zhèng fǔ dǎ suàn tuī jìn qí gǎi gé jì huá。","meaning":"The government intends to push ahead with its reform programme.","meaningThai":"รัฐบาลตั้งใจที่จะผลักดันแผนการปฏิรูปต่อไป"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1163","chinese":"退休","pinyin":"tuìxiū","meaning":"to retire (from the workforce); to go into retirement","meaningThai":"เกษียณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他明年退休。","pinyin":"Tā míng nián tuì xiū.","meaning":"He will retire next year.","meaningThai":"เขาจะเกษียณในปีหน้า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1164","chinese":"拖鞋","pinyin":"tuōxié","meaning":"slippers; sandals; flip-flops","meaningThai":"รองเท้าแตะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"請穿這雙拖鞋。","pinyin":"Qǐng chuān zhè shuāng tuō xié。","meaning":"Please put on these slippers.","meaningThai":"กรุณาใส่รองเท้าแตะเหล่านี้"},{"chinese":"你的這雙拖鞋很萌。","pinyin":"Nǐ de zhè shuāng tuō xié hěn méng。","meaning":"Your pair of slippers are very cute.","meaningThai":"รองเท้าแตะของคุณน่ารักมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1165","chinese":"图书","pinyin":"túshū","meaning":"books (in a library or bookstore)","meaningThai":"หนังสือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我花在图书馆的时间很有收获。","pinyin":"Wǒ huā zài tú shū guǎn de shí jiān hěn yǒu shōu huò。","meaning":"My time spent in the library was very productive.","meaningThai":"การใช้เวลาในห้องสมุดของฉันมีประสิทธิผลมาก"},{"chinese":"警方扣留了各种图书和磁带。","pinyin":"Jǐng fāng kòu liú le gè zhǒng tú shū hé cí dài。","meaning":"Police seized various books and tapes.","meaningThai":"ตำรวจยึดหนังสือและเทปต่างๆ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1166","chinese":"兔子","pinyin":"tùzi","meaning":"hare; rabbit","meaningThai":"กระต่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"兔子喜欢吃胡萝卜。","pinyin":"Tù zi xǐ huān chī hú luó bo.","meaning":"Rabbits like to eat carrots.","meaningThai":"กระต่ายชอบกินแครอท"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1167","chinese":"外部","pinyin":"wàibù","meaning":"the outside; (attributive) external; exterior; surface","meaningThai":"ภายนอก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"伊朗对外部世界而言依然是个谜。","pinyin":"Yī lǎng duì wài bù shì jiè ér yán yī rán shì gè mí。","meaning":"Iran remains an enigma for the outside world.","meaningThai":"อิหร่านยังคงเป็นปริศนาสำหรับโลกภายนอก"},{"chinese":"外部审计员将核实这些账目。","pinyin":"Wài bù shěn jì yuán jiāng hé shí zhè xiē zhàng mù。","meaning":"An external auditor will verify the accounts.","meaningThai":"ผู้ตรวจสอบบัญชีภายนอกจะตรวจสอบบัญชี"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1168","chinese":"外公","pinyin":"wàigōng","meaning":"(coll.) mother's father; maternal grandfather","meaningThai":"ตา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"外公喜欢喝茶。","pinyin":"Wai gong xi huan he cha.","meaning":"Grandpa likes drinking tea.","meaningThai":"คุณปู่ชอบดื่มชา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1169","chinese":"外观","pinyin":"wàiguān","meaning":"outward appearance","meaningThai":"รูปร่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"花儿不仅凭外观也凭香味而被选中。","pinyin":"Huā ér bù jǐn píng wài guān yě píng xiāng wèi ér bèi xuǎn zhōng。","meaning":"Flowers are chosen for their scent as well as their look.","meaningThai":"ดอกไม้ถูกเลือกเพราะกลิ่นและรูปลักษณ์"},{"chinese":"这栋大楼外观雄伟，与照片中所见一模一样。","pinyin":"Zhè dòng dà lóu wài guān xióng wěi， yǔ zhào piàn zhōng suǒ jiàn yī mó yī yàng。","meaning":"The building looked as impressive in actuality as it did in photographs.","meaningThai":"อาคารหลังนี้ดูน่าประทับใจในความเป็นจริงพอๆ กับที่เห็นในรูปถ่าย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1170","chinese":"外婆","pinyin":"wàipó","meaning":"(coll.) mother's mother; maternal grandmother","meaningThai":"ยาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"外婆住在农村。","pinyin":"Wai po zhu zai nong cun.","meaning":"Grandma lives in the countryside.","meaningThai":"คุณยายอาศัยอยู่ในชนบท"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1171","chinese":"外形","pinyin":"wàixíng","meaning":"figure; shape; external form; contour","meaningThai":"รูปร่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这辆车外形设计流畅，看起来像赛车。","pinyin":"Zhè liàng chē wài xíng shè jì liú chàng， kàn qǐ lái xiàng sài chē。","meaning":"It is smoothly contoured to look like a racing car.","meaningThai":"มีรูปทรงเรียบหรูเหมือนรถแข่ง"},{"chinese":"他的体力与他的外形相称。","pinyin":"Tā de tǐ lì yǔ tā de wài xíng xiāng chēng。","meaning":"He had a physical strength that matched his outward appearance.","meaningThai":"เขามีความแข็งแกร่งทางกายภาพที่เข้ากับรูปลักษณ์ภายนอกของเขา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1172","chinese":"弯","pinyin":"wān","meaning":"to bend; bent; a bend; a turn (in a road etc)","meaningThai":"โค้งงอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他背疼，不能弯腰。","pinyin":"Tā bèi téng， bù néng wān yāo。","meaning":"He has back pain, he can't bend over.","meaningThai":"เขามีอาการปวดหลัง งอตัวไม่ได้"},{"chinese":"果子把树枝压弯了。","pinyin":"Guǒ zǐ bǎ shù zhī yā wān le。","meaning":"The fruit weighed the branches down.","meaningThai":"ผลไม้นั้นทำให้กิ่งก้านหนักลง"}],"partOfSpeech":["verb","other","adjective","measure word"]},
  {"id":"hsk5-1173","chinese":"往返","pinyin":"wǎngfǎn","meaning":"to go back and forth; to go to and fro; to do a round trip","meaningThai":"ไปกลับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"往返票更便宜。","pinyin":"Wang fan piao geng pian yi.","meaning":"Round trip tickets are cheaper.","meaningThai":"ตั๋วไปกลับถูกกว่า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1174","chinese":"网络","pinyin":"wǎngluò","meaning":"Internet","meaningThai":"เครือข่าย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"网络连接不稳定。","pinyin":"Wǎng luò lián jiē bù wěn dìng.","meaning":"The network connection is unstable.","meaningThai":"การเชื่อมต่อเครือข่ายไม่เสถียร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1175","chinese":"玩具","pinyin":"wánjù","meaning":"plaything; toy","meaningThai":"ของเล่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"很小的玩具可使婴儿窒息。","pinyin":"Hěn xiǎo de wán jù kě shǐ yīng ér zhì xī。","meaning":"Very small toys can choke a baby.","meaningThai":"ของเล่นที่มีขนาดเล็กมากอาจทำให้ทารกสำลักได้"},{"chinese":"他把散落的玩具捡了起来。","pinyin":"Tā bǎ sàn luò de wán jù jiǎn le qǐ lái。","meaning":"He picked up the scattered toys.","meaningThai":"เขาหยิบของเล่นที่กระจัดกระจายขึ้นมา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1176","chinese":"完美","pinyin":"wánměi","meaning":"perfect","meaningThai":"สมบูรณ์แบบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"相信可以达到完美是不现实的。","pinyin":"Xiāng xìn kě yǐ dá dào wán měi shì bù xiàn shí de。","meaning":"It is unrealistic to believe perfection is an attainable goal.","meaningThai":"มันไม่สมจริงที่จะเชื่อว่าความสมบูรณ์แบบคือเป้าหมายที่บรรลุได้"},{"chinese":"他对完美的追求是不懈的。","pinyin":"Tā duì wán měi de zhuī qiú shì bù xiè de。","meaning":"His quest for perfection is relentless.","meaningThai":"การแสวงหาความสมบูรณ์แบบของเขานั้นไม่หยุดยั้ง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1177","chinese":"完善","pinyin":"wánshàn","meaning":"(of systems, facilities etc) comprehensive; well-developed; excellent; to refine; to improve","meaningThai":"สมบูรณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们一直在努力完善新型号。","pinyin":"Tā mén yī zhí zài nǔ lì wán shàn xīn xíng hào。","meaning":"They have been working on the perfection of the new model.","meaningThai":"พวกเขาได้ทำงานเพื่อความสมบูรณ์แบบของโมเดลใหม่นี้"},{"chinese":"这项工艺的完善要归功于克利科夫人。","pinyin":"Zhè xiàng gōng yì de wán shàn yào guī gōng yú kè lì kē fū rén。","meaning":"Madame Clicquot is credited with the perfection of this technique.","meaningThai":"Madame Clicquot ได้รับการยกย่องในความสมบูรณ์แบบของเทคนิคนี้"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-1178","chinese":"万一","pinyin":"wànyī","meaning":"just in case; if by any chance; contingency","meaningThai":"ในกรณี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我多带了一些现金，以防万一。","pinyin":"Wǒ duō dài le yī xiē xiàn jīn， yǐ fáng wàn yī。","meaning":"I took some extra cash just to be on the safe side.","meaningThai":"ฉันใช้เงินสดเพิ่มเพื่อความปลอดภัย"},{"chinese":"我要保存这封信，以防万一。","pinyin":"Wǒ yào bǎo cún zhè fēng xìn， yǐ fáng wàn yī。","meaning":"I'll keep the letter as a precaution.","meaningThai":"ฉันจะเก็บจดหมายไว้เป็นการป้องกันไว้ก่อน"}],"partOfSpeech":["conjunction","adverb","other"]},
  {"id":"hsk5-1179","chinese":"完整","pinyin":"wánzhěng","meaning":"complete; intact","meaningThai":"ทั้งหมด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"为完整起见，所有名称均用全名。","pinyin":"Wéi wán zhěng qǐ jiàn， suǒ yǒu míng chēng jūn yòng quán míng。","meaning":"For the sake of completeness, all names are given in full.","meaningThai":"เพื่อความสมบูรณ์ จึงขอยกชื่อให้ครบถ้วน"},{"chinese":"口语中有很多不完整的句子。","pinyin":"Kǒu yǔ zhōng yǒu hěn duō bù wán zhěng de jù zǐ。","meaning":"Spoken language contains many incomplete sentences.","meaningThai":"ภาษาพูดมีประโยคที่ไม่สมบูรณ์จำนวนมาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1180","chinese":"围","pinyin":"wéi","meaning":"surname Wei","meaningThai":"ล้อมรอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们围火而坐取暖。","pinyin":"Wǒ mén wéi huǒ ér zuò qǔ nuǎn。","meaning":"We sat around the fire to keep ourselves warm.","meaningThai":"เรานั่งรอบกองไฟเพื่อให้ร่างกายอบอุ่น"},{"chinese":"我正感到尴尬，你为我解了围。","pinyin":"Wǒ zhèng gǎn dào gān gà， nǐ wéi wǒ jiě le wéi。","meaning":"You rescued me from an embarrassing situation.","meaningThai":"คุณช่วยฉันจากสถานการณ์ที่น่าอับอาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1181","chinese":"为","pinyin":"wéi","meaning":"as (in the capacity of); to take sth as; to act as; to serve as; to behave as; to become; to be; to do; by (in the passive voice)","meaningThai":"เพราะ; เนื่องจาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他为这次比赛准备了很久。","pinyin":"Tā wèi zhècì bǐsài zhǔnbèi le hěn jiǔ.","meaning":"He prepared for this competition for a long time.","meaningThai":"เขาเตรียมตัวสำหรับการแข่งขันครั้งนี้มาเป็นเวลานาน"},{"chinese":"大家都为她感到高兴。","pinyin":"Dàjiā dōu wèi tā gǎndào gāoxìng.","meaning":"Everyone felt happy for her.","meaningThai":"ทุกคนรู้สึกมีความสุขกับเธอ"},{"chinese":"这本书是为初学者写的。","pinyin":"Zhè běnshū shì wèi chūxuézhě xiě de.","meaning":"This book was written for beginners.","meaningThai":"หนังสือเล่มนี้เขียนขึ้นสำหรับผู้เริ่มต้น"}],"partOfSpeech":["preposition","verb"]},
  {"id":"hsk5-1182","chinese":"胃","pinyin":"wèi","meaning":"stomach","meaningThai":"ท้อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"验尸发现他胃中有微量毒物。","pinyin":"Yàn shī fā xiàn tā wèi zhōng yǒu wēi liáng dú wù。","meaning":"The post-mortem revealed traces of poison in his stomach.","meaningThai":"ชันสูตรพลิกศพพบร่องรอยพิษในท้อง"},{"chinese":"这样你的胃应该就不难受了。","pinyin":"Zhè yàng nǐ de wèi yīng gāi jiù bù nán shòu le。","meaning":"This should settle your stomach.","meaningThai":"นี่ควรจะทำให้ท้องของคุณสงบลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1183","chinese":"喂","pinyin":"wèi","meaning":"hello (when answering the phone)","meaningThai":"สวัสดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"喂，你好。","pinyin":"Wèi, nǐ hǎo.","meaning":"Hello? Hi.","meaningThai":"สวัสดี? สวัสดี."},{"chinese":"喂，请问李老师在吗？","pinyin":"Wèi, qǐngwèn Lǐ lǎoshī zài ma?","meaning":"Hello, may I ask whether Teacher Li is there?","meaningThai":"สวัสดีครับ ขออนุญาตถามครับว่าครูลี่อยู่หรือเปล่าครับ?"},{"chinese":"喂，你能听见我吗？","pinyin":"Wèi, nǐ néng tīngjiàn wǒ ma?","meaning":"Hello, can you hear me?","meaningThai":"สวัสดี คุณได้ยินฉันไหม"}],"partOfSpeech":["verb","interjection"]},
  {"id":"hsk5-1184","chinese":"尾巴","pinyin":"wěiba","meaning":"tail; colloquial pr. [yǐ ba]","meaningThai":"หาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那条狗咬着叫着，还摇着尾巴。","pinyin":"Nà tiáo gǒu yǎo zháo jiào zháo， huán yáo zháo wěi bā。","meaning":"The dog was biting, growling and wagging its tail.","meaningThai":"สุนัขกัดคำรามและกระดิกหาง"},{"chinese":"马轻轻甩动尾巴把苍蝇赶走。","pinyin":"Mǎ qīng qīng shuǎi dòng wěi bā bǎ cāng yíng gǎn zǒu。","meaning":"The horse was flicking flies away with its tail.","meaningThai":"ม้าก็สะบัดหางแมลงวันออกไป"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1185","chinese":"维持","pinyin":"wéichí","meaning":"to keep; to maintain; to preserve","meaningThai":"บำรุงรักษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"哪些行星可以维持生命的存在？","pinyin":"Nǎ xiē háng xīng kě yǐ wéi chí shēng mìng de cún zài？","meaning":"Which planets can sustain life?","meaningThai":"ดาวเคราะห์ดวงใดที่สามารถดำรงชีวิตได้?"},{"chinese":"军队被调进首都维持治安。","pinyin":"Jūn duì bèi tiáo jìn shǒu dū wéi chí zhì ān。","meaning":"The army has been sent in to maintain order in the capital.","meaningThai":"กองทัพถูกส่งเข้ามาเพื่อรักษาความสงบเรียบร้อยในเมืองหลวง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1186","chinese":"伟大","pinyin":"wěidà","meaning":"huge; great; grand; worthy of the greatest admiration; important (contribution etc)","meaningThai":"ยอดเยี่ยม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他曾是同辈中最伟大的板球击球手。","pinyin":"Tā zēng shì tóng bèi zhōng zuì wěi dà de bǎn qiú jī qiú shǒu。","meaning":"He was the greatest batsman of his generation.","meaningThai":"เขาเป็นนักตีลูกที่ยิ่งใหญ่ที่สุดในยุคของเขา"},{"chinese":"济慈是最伟大的浪漫主义诗人之一。","pinyin":"Jì cí shì zuì wěi dà de làng màn zhǔ yì shī rén zhī yī。","meaning":"Keats is one of the greatest Romantic poets.","meaningThai":"KEATS เป็นหนึ่งในกวีโรแมนติกที่ยิ่งใหญ่ที่สุด"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1187","chinese":"违法","pinyin":"wéifǎ","meaning":"illegal; to break the law","meaningThai":"ผิดกฎหมาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"猥亵电话和恐吓电话是违法的。","pinyin":"Wěi xiè diàn huà hé kǒng xià diàn huà shì wéi fǎ de。","meaning":"Obscene and threatening phone calls are against the law.","meaningThai":"การโทรศัพท์ที่หยาบคายและข่มขู่ถือเป็นการกระทำที่ผิดกฎหมาย"},{"chinese":"我们那时不知道我们在违法。","pinyin":"Wǒ mén nà shí bù zhī dào wǒ mén zài wéi fǎ。","meaning":"We didn't know we were breaking the law.","meaningThai":"เราไม่รู้ว่าเรากำลังทำผิดกฎหมาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1188","chinese":"违反","pinyin":"wéifǎn","meaning":"to violate (a law)","meaningThai":"ละเมิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"违反规定。","pinyin":"Wei fan gui ding.","meaning":"Violate regulations.","meaningThai":"ฝ่าฝืนกฎระเบียบ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1189","chinese":"危害","pinyin":"wēihài","meaning":"to jeopardize; to harm; to endanger; harmful effect; damage","meaningThai":"อันตราย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他沉重的体重正危害着他的健康。","pinyin":"Tā chén zhòng de tǐ zhòng zhèng wēi hài zháo tā de jiàn kāng。","meaning":"His weight was harming his health.","meaningThai":"น้ำหนักของเขาส่งผลเสียต่อสุขภาพของเขา"},{"chinese":"这场争论可能会危害中东和谈的倡议。","pinyin":"Zhè cháng zhēng lùn kě néng huì wēi hài zhōng dōng hé tán de chàng yì。","meaning":"The debate could endanger the proposed Mideast peace talks.","meaningThai":"การอภิปรายอาจเป็นอันตรายต่อข้อเสนอการเจรจาสันติภาพในตะวันออกกลาง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1190","chinese":"围巾","pinyin":"wéijīn","meaning":"scarf; shawl","meaningThai":"ผ้าพันคอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你为什么戴那条围巾？","pinyin":"Nǐ wéi shí mó dài nà tiáo wéi jīn？","meaning":"Why are you wearing that scarf?","meaningThai":"ทำไมคุณถึงสวมผ้าพันคอนั้น?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1191","chinese":"未来","pinyin":"wèilái","meaning":"future; tomorrow; approaching; coming; pending","meaningThai":"อนาคต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这部电影以未来为背景。","pinyin":"Zhè bù diàn yǐng yǐ wèi lái wéi bèi jǐng。","meaning":"The movie is set in the future.","meaningThai":"หนังมีฉากเกิดขึ้นในอนาคต"},{"chinese":"他没有未来晋升的希望。","pinyin":"Tā méi yǒu wèi lái jìn shēng de xī wàng。","meaning":"He had no hopes of future preferment.","meaningThai":"เขาไม่มีความหวังถึงการเลือกสรรในอนาคต"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1192","chinese":"围绕","pinyin":"wéirào","meaning":"to revolve around; to center on (an issue)","meaningThai":"รอบๆ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这场讨论围绕具体的会计技巧。","pinyin":"Zhè cháng tǎo lùn wéi rào jù tǐ de huì jì jì qiǎo。","meaning":"The debate revolves around specific accounting techniques.","meaningThai":"การอภิปรายเกี่ยวกับเทคนิคการบัญชีเฉพาะ"},{"chinese":"玫瑰被修整得围绕着门口生长。","pinyin":"Méi guī bèi xiū zhěng dé wéi rào zháo mén kǒu shēng cháng。","meaning":"Roses had been trained around the door.","meaningThai":"กุหลาบได้รับการฝึกฝนอยู่รอบประตู"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1193","chinese":"微笑","pinyin":"wēixiào","meaning":"smile; to smile","meaningThai":"รอยยิ้ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他露出微笑，可他的微笑没有得到回应。","pinyin":"Tā lòu chū wēi xiào， kě tā de wēi xiào méi yǒu dé dào huí yīng。","meaning":"He smiled but his smile was not reciprocated.","meaningThai":"เขายิ้มแต่รอยยิ้มของเขากลับไม่ตอบสนอง"},{"chinese":"微笑慢慢在她脸上绽开。","pinyin":"Wēi xiào màn màn zài tā liǎn shàng zhàn kāi。","meaning":"A smile spread slowly across her face.","meaningThai":"รอยยิ้มค่อยๆ กระจายไปทั่วใบหน้าของเธอ"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-1194","chinese":"威胁","pinyin":"wēixié","meaning":"to threaten; to menace","meaningThai":"คุกคาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"安全威胁。","pinyin":"An quan wei xie.","meaning":"Security threat.","meaningThai":"ภัยคุกคามด้านความปลอดภัย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1195","chinese":"维修","pinyin":"wéixiū","meaning":"maintenance (of equipment); to protect and maintain","meaningThai":"ซ่อมแซม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"按契约规定，房客负责房屋维修。","pinyin":"Àn qì yuē guī dìng， fáng kè fù zé fáng wū wéi xiū。","meaning":"Under the provisions of the lease, the tenant is responsible for repairs.","meaningThai":"ภายใต้ข้อกำหนดของสัญญาเช่าผู้เช่ามีหน้าที่ซ่อมแซม"},{"chinese":"他们驶入拉各斯港进行维修。","pinyin":"Tā mén shǐ rù lā gè sī gǎng jìn háng wéi xiū。","meaning":"They put in at Lagos for repairs.","meaningThai":"พวกเขาส่งไปที่ลากอสเพื่อซ่อมแซม"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1196","chinese":"唯一","pinyin":"wéiyī","meaning":"only; sole","meaningThai":"เท่านั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是我确实要走的唯一理由。","pinyin":"Zhè shì wǒ què shí yào zǒu de wéi yī lǐ yóu。","meaning":"That's the only reason I'm actually going.","meaningThai":"นั่นเป็นเหตุผลเดียวที่ฉันจะไปจริงๆ"},{"chinese":"屋子里唯一的光亮来自炉火。","pinyin":"Wū zǐ lǐ wéi yī de guāng liàng lái zì lú huǒ。","meaning":"The only illumination in the room came from the fire.","meaningThai":"แสงสว่างเพียงดวงเดียวในห้องนั้นมาจากไฟ"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-1197","chinese":"位于","pinyin":"wèiyú","meaning":"to be located at; to be situated at; to lie","meaningThai":"นอนอยู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"教堂位于这个岛偏僻的北部海岸。","pinyin":"Jiào táng wèi yú zhè gè dǎo piān pì de běi bù hǎi àn。","meaning":"The church is remotely situated on the north coast of the island.","meaningThai":"โบสถ์แห่งนี้ตั้งอยู่ห่างไกลบนชายฝั่งทางเหนือของเกาะ"},{"chinese":"许多难民村位于偏僻的地方。","pinyin":"Xǔ duō nán mín cūn wèi yú piān pì de dì fāng。","meaning":"Many of the refugee villages are in isolated areas.","meaningThai":"หมู่บ้านผู้ลี้ภัยหลายแห่งอยู่ในพื้นที่ห่างไกล"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1198","chinese":"位置","pinyin":"wèizhì","meaning":"position; place; seat","meaningThai":"ที่ตั้ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她知道“飞鹰”总部的准确位置。","pinyin":"Tā zhī dào “ fēi yīng ” zǒng bù de zhǔn què wèi zhì。","meaning":"She knew the exact location of The Eagle's headquarters.","meaningThai":"เธอรู้ตำแหน่งที่แน่นอนของสำนักงานใหญ่ของ The Eagle"},{"chinese":"那些游艇灵活地寻找位置。","pinyin":"Nà xiē yóu tǐng líng huó dì xún zhǎo wèi zhì。","meaning":"The yachts manoeuvred for position.","meaningThai":"เรือยอร์ชเคลื่อนตัวเข้าประจำตำแหน่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1199","chinese":"稳定","pinyin":"wěndìng","meaning":"steady; stable; stability; to stabilize; to pacify","meaningThai":"ทำให้เสถียร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该受伤男子处于稳定状态。","pinyin":"Gāi shòu shāng nán zǐ chǔ yú wěn dìng zhuàng tài。","meaning":"The injured man was in a stable condition.","meaningThai":"ผู้บาดเจ็บอาการอาการทรงตัวแล้ว"},{"chinese":"情况不稳定，可能有危险。","pinyin":"Qíng kuàng bù wěn dìng， kě néng yǒu wēi xiǎn。","meaning":"The situation is unstable and potentially dangerous.","meaningThai":"สถานการณ์ไม่มั่นคงและอาจเป็นอันตรายได้"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1200","chinese":"问卷","pinyin":"wènjuàn","meaning":"questionnaire","meaningThai":"แบบสอบถาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"教师们将被要求填写一份调查问卷。","pinyin":"Jiào shī mén jiāng bèi yào qiú tián xiě yī fèn tiáo chá wèn juàn。","meaning":"Teachers will be asked to fill in a questionnaire.","meaningThai":"ครูจะถูกขอให้กรอกแบบสอบถาม"},{"chinese":"他们向全国100所学校发出了问卷。","pinyin":"Tā mén xiàng quán guó 100 suǒ xué xiào fā chū le wèn juàn。","meaning":"They sent out questionnaires to one hundred schools countrywide.","meaningThai":"โดยได้ส่งแบบสอบถามไปยังโรงเรียนกว่าร้อยแห่งทั่วประเทศ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1201","chinese":"温暖","pinyin":"wēnnuǎn","meaning":"warm","meaningThai":"ความอบอุ่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些植物喜欢温暖潮湿的空气。","pinyin":"Zhè xiē zhí wù xǐ huān wēn nuǎn cháo shī de kōng qì。","meaning":"These plants love warm, humid atmospheres.","meaningThai":"ต้นไม้เหล่านี้ชอบบรรยากาศที่อบอุ่นและชื้น"},{"chinese":"母的必须找个温暖的地方孵蛋。","pinyin":"Mǔ de bì xū zhǎo gè wēn nuǎn de dì fāng fū dàn。","meaning":"The female must find a warm place to hatch her eggs.","meaningThai":"ตัวเมียต้องหาที่อบอุ่นเพื่อฟักไข่"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1202","chinese":"文学","pinyin":"wénxué","meaning":"literature","meaningThai":"วรรณกรรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"文学课要读很多小说。","pinyin":"Wén xué kè yào dú hěn duō xiǎo shuō.","meaning":"Literature class requires reading many novels.","meaningThai":"ชั้นเรียนวรรณคดีต้องอ่านนวนิยายหลายเล่ม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1203","chinese":"握","pinyin":"wò","meaning":"to hold; to grasp; to clench (one's fist); (bound form) to have in one's control; classifier: a handful","meaningThai":"ด้ามจับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"找到能让你大力击球的准确握拍方法。","pinyin":"Zhǎo dào néng ràng nǐ dà lì jī qiú de zhǔn què wò pāi fāng fǎ。","meaning":"Find the exact grip that allows you to hit the ball hard.","meaningThai":"ค้นหาการยึดเกาะที่ช่วยให้คุณตีลูกได้อย่างแรง"},{"chinese":"我的手抖得厉害以至于几乎握不住麦克风。","pinyin":"Wǒ de shǒu dǒu dé lì hài yǐ zhì yú jī hū wò bù zhù mài kè fēng。","meaning":"My hand shook so much that I could hardly hold the microphone.","meaningThai":"มือของฉันสั่นมากจนแทบจะจับไมโครโฟนไม่ได้เลย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1204","chinese":"卧室","pinyin":"wòshì","meaning":"bedroom","meaningThai":"ห้องนอน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他在卧室门口停了下来。","pinyin":"Tā zài wò shì mén kǒu tíng le xià lái。","meaning":"He stopped at the threshold of the bedroom.","meaningThai":"เขามาหยุดที่ธรณีประตูห้องนอน"},{"chinese":"镜头从卧室转换到街道。","pinyin":"Jìng tóu cóng wò shì zhuǎn huàn dào jiē dào。","meaning":"The scene cuts from the bedroom to the street.","meaningThai":"ฉากตัดจากห้องนอนไปที่ถนน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1205","chinese":"握手","pinyin":"wòshǒu","meaning":"to shake hands","meaningThai":"จับมือกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"讓我們握手吧。","pinyin":"Ràng wǒ mén wò shǒu bā。","meaning":"Let's shake hands.","meaningThai":"มาจับมือกันเถอะ"},{"chinese":"他拒绝跟我握手。","pinyin":"Tā jù jué gēn wǒ wò shǒu。","meaning":"He refused to shake hands with me. / He refused to shake my hand.","meaningThai":"เขาไม่ยอมจับมือกับฉัน / เขาไม่ยอมจับมือฉัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1206","chinese":"雾","pinyin":"wù","meaning":"fog; mist","meaningThai":"หมอก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"早上有大雾。","pinyin":"Zao shang you da wu.","meaning":"There is heavy fog in the morning.","meaningThai":"มีหมอกหนาในตอนเช้า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1207","chinese":"舞蹈","pinyin":"wǔdǎo","meaning":"dance (performance art); dancing","meaningThai":"เต้นรำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她喜欢舞蹈。","pinyin":"Ta xi huan wu dao.","meaning":"She likes dancing.","meaningThai":"เธอชอบเต้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1208","chinese":"无关","pinyin":"wúguān","meaning":"unrelated; having nothing to do (with sth else)","meaningThai":"ไม่เกี่ยวข้อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"对不起，不过这和你无关。","pinyin":"Duì bù qǐ， bù guò zhè hé nǐ wú guān。","meaning":"I'm sorry, but it's nothing to do with you.","meaningThai":"ฉันขอโทษ แต่มันไม่เกี่ยวอะไรกับคุณเลย"},{"chinese":"他与那起犯罪毫无关联。","pinyin":"Tā yǔ nà qǐ fàn zuì háo wú guān lián。","meaning":"There was nothing to connect him with the crime.","meaningThai":"ไม่มีอะไรเชื่อมโยงเขากับอาชญากรรมได้"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-1209","chinese":"物价","pinyin":"wùjià","meaning":"(commodity) prices","meaningThai":"ราคา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"收成不好导致物价急剧上涨。","pinyin":"Shōu chéng bù hǎo dǎo zhì wù jià jí jù shàng zhǎng。","meaning":"The poor harvest caused prices to rise sharply.","meaningThai":"การเก็บเกี่ยวที่ไม่ดีทำให้ราคาสูงขึ้นอย่างรวดเร็ว"},{"chinese":"他们在抗议不断飞涨的物价。","pinyin":"Tā mén zài kàng yì bù duàn fēi zhǎng de wù jià。","meaning":"They were protesting soaring prices.","meaningThai":"พวกเขากำลังประท้วงราคาที่พุ่งสูงขึ้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1210","chinese":"物理","pinyin":"wùlǐ","meaning":"physics; physical","meaningThai":"ฟิสิกส์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"物理实验很有意思。","pinyin":"Wù lǐ shí yàn hěn yǒu yì si.","meaning":"Physics experiments are very interesting.","meaningThai":"การทดลองฟิสิกส์น่าสนใจมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1211","chinese":"无奈","pinyin":"wúnài","meaning":"to have no alternative; frustrated; exasperated; helpless; (conjunction) but unfortunately","meaningThai":"ไม่มีทางเลือก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们无奈地看着自己的家被大火吞没。","pinyin":"Tā mén wú nài dì kàn zháo zì jǐ de jiā bèi dà huǒ tūn méi。","meaning":"They watched helplessly as their home went up in flames.","meaningThai":"พวกเขาเฝ้าดูอย่างช่วยไม่ได้เมื่อบ้านของพวกเขาลุกเป็นไฟ"},{"chinese":"有时无奈和愤怒会失去控制，变成直接的暴力行为。","pinyin":"Yǒu shí wú nài hé fèn nù huì shī qù kòng zhì， biàn chéng zhí jiē de bào lì háng wéi。","meaning":"Sometimes frustration and anger can boil over into direct and violent action.","meaningThai":"บางครั้งความคับข้องใจและความโกรธอาจเดือดพล่านจนกลายเป็นการกระทำที่ตรงไปตรงมาและรุนแรง"}],"partOfSpeech":["adverb","adjective","noun"]},
  {"id":"hsk5-1212","chinese":"物品","pinyin":"wùpǐn","meaning":"articles; goods","meaningThai":"สิ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些物品仅供展览—不卖。","pinyin":"Zhè xiē wù pǐn jǐn gōng zhǎn lǎn — bù mài。","meaning":"These items are just for show—they're not for sale.","meaningThai":"สินค้าเหล่านี้มีไว้เพื่อการแสดงเท่านั้น ไม่มีขาย"},{"chinese":"大件物品将分开收集。","pinyin":"Dà jiàn wù pǐn jiāng fēn kāi shōu jí。","meaning":"Bulky items will be collected separately.","meaningThai":"สินค้าขนาดใหญ่จะถูกรวบรวมแยกกัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1213","chinese":"无数","pinyin":"wúshù","meaning":"countless; numberless; innumerable","meaningThai":"นับไม่ถ้วน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"无数星星在天上闪烁。","pinyin":"Wú shù xīng xīng zài tiān shàng shǎn shuò。","meaning":"Countless stars were twinkling in the sky.","meaningThai":"ดวงดาวจำนวนนับไม่ถ้วนส่องแสงระยิบระยับบนท้องฟ้า"},{"chinese":"无数次的失败摧毁了他的雄心壮志。","pinyin":"Wú shù cì de shī bài cuī huǐ le tā de xióng xīn zhuàng zhì。","meaning":"His ambition was blasted by these repeated failures. / Countless failures destroyed his great ambitions.","meaningThai":"ความทะเยอทะยานของเขาถูกทำลายลงด้วยความล้มเหลวซ้ำแล้วซ้ำเล่าเหล่านี้ / ความล้มเหลวนับไม่ถ้วนทำลายความทะเยอทะยานอันยิ่งใหญ่ของเขา"}],"partOfSpeech":["numeral"]},
  {"id":"hsk5-1214","chinese":"武术","pinyin":"wǔshù","meaning":"military skill or technique (in former times); all kinds of martial art sports (some claiming spiritual development); self-defense; tradition of choreographed fights from opera and film (recent usage); also called kungfu 功夫","meaningThai":"ศิลปะการต่อสู้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"迪亚斯是个受过武术训练的健身迷。","pinyin":"Dí yà sī shì gè shòu guò wǔ shù xùn liàn de jiàn shēn mí。","meaning":"Diaz is a fitness freak who's trained in martial arts.","meaningThai":"ดิแอซเป็นคนคลั่งไคล้การออกกำลังกายที่ได้รับการฝึกฝนด้านศิลปะการต่อสู้"},{"chinese":"他总是吹嘘说他是伟大的武术家。","pinyin":"Tā zǒng shì chuī xū shuō tā shì wěi dà de wǔ shù jiā。","meaning":"He's always bragging that he's a great martial artist.","meaningThai":"เขาอวดอ้างอยู่เสมอว่าเขาเป็นนักกีฬาศิลปะการต่อสู้ที่ยอดเยี่ยม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1215","chinese":"舞台","pinyin":"wǔtái","meaning":"(lit. and fig.) stage; arena","meaningThai":"เวที","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他负责全部舞台道具和灯光。","pinyin":"Tā fù zé quán bù wǔ tái dào jù hé dēng guāng。","meaning":"He is responsible for all the stage props and lighting.","meaningThai":"เขารับผิดชอบอุปกรณ์ประกอบฉากและแสงบนเวทีทั้งหมด"},{"chinese":"柱子挡着，我们看不见舞台。","pinyin":"Zhù zǐ dǎng zháo， wǒ mén kàn bù jiàn wǔ tái。","meaning":"The pillar obstructed our view of the stage.","meaningThai":"เสาบังการมองเห็นเวทีของเรา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1216","chinese":"无限","pinyin":"wúxiàn","meaning":"unlimited; unbounded","meaningThai":"ไม่จำกัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你可以无限制使用这些档案。","pinyin":"Nǐ kě yǐ wú xiàn zhì shǐ yòng zhè xiē dàng àn。","meaning":"You will be allowed unlimited access to the files.","meaningThai":"คุณจะได้รับอนุญาตให้เข้าถึงไฟล์ได้ไม่จำกัด"},{"chinese":"人类的适应力是无限的。","pinyin":"Rén lèi de shì yīng lì shì wú xiàn de。","meaning":"Human beings are infinitely adaptable.","meaningThai":"มนุษย์สามารถปรับตัวได้ไม่สิ้นสุด"}],"partOfSpeech":["verb","adjective","adverb"]},
  {"id":"hsk5-1217","chinese":"无效","pinyin":"wúxiào","meaning":"not valid; ineffective; in vain","meaningThai":"ไม่ถูกต้อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"持无效证件的人被驱逐到别国。","pinyin":"Chí wú xiào zhèng jiàn de rén bèi qū zhú dào bié guó。","meaning":"People with invalid papers are deported to another country.","meaningThai":"ผู้ที่มีเอกสารไม่ถูกต้องจะถูกส่งตัวไปยังประเทศอื่น"},{"chinese":"审判被终止了，其结果被宣布无效。","pinyin":"Shěn pàn bèi zhōng zhǐ le， qí jié guǒ bèi xuān bù wú xiào。","meaning":"The trial was stopped and the results declared invalid.","meaningThai":"การทดลองหยุดลงและผลลัพธ์ที่ประกาศว่าไม่ถูกต้อง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1218","chinese":"五颜六色","pinyin":"wǔyán-liùsè","meaning":"multicolored; every color under the sun","meaningThai":"มีสีสัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们的旗五颜六色。","pinyin":"Tā mén de qí wǔ yán liù sè。","meaning":"Their flag was colourful.","meaningThai":"ธงของพวกเขามีสีสัน"}],"partOfSpeech":["expression"]},
  {"id":"hsk5-1219","chinese":"物业","pinyin":"wùyè","meaning":"property; real estate; abbr. for 物业管理, property management","meaningThai":"คุณสมบัติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那家公司已崭露头角，成为伦敦物业市场的主要竞争者。","pinyin":"Nà jiā gōng sī yǐ zhǎn lòu tóu jiǎo， chéng wéi lún dūn wù yè shì cháng de zhǔ yào jìng zhēng zhě。","meaning":"The company has emerged as a major player in the London property market.","meaningThai":"บริษัทได้กลายเป็นผู้เล่นหลักในตลาดอสังหาริมทรัพย์ในลอนดอน"},{"chinese":"该物业最古老的葡萄酒商在布雷恩-坎特纳克工作超过32年后才宣布退休。","pinyin":"Gāi wù yè zuì gǔ lǎo de pú táo jiǔ shāng zài bù léi ēn - kǎn tè nà kè gōng zuò chāo guò 32 nián hòu cái xuān bù tuì xiū。","meaning":"The property's oldest vintner just asserted his right to retire after working at Brane-Cantenac for over 32 years.","meaningThai":"เจ้าของร้านเหล้าองุ่นที่เก่าแก่ที่สุดของสถานที่แห่งนี้เพิ่งยืนยันสิทธิ์ของเขาในการเกษียณหลังจากทำงานที่ Brane-Cantenac มานานกว่า 32 ปี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1220","chinese":"物质","pinyin":"wùzhì","meaning":"matter; substance; material; materialistic","meaningThai":"วัตถุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"物质生活。","pinyin":"Wu zhi sheng huo.","meaning":"Material life.","meaningThai":"ชีวิตของวัสดุ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1221","chinese":"戏","pinyin":"xì","meaning":"variant of 戏","meaningThai":"เล่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那出戏让我们笑得前仰后合。","pinyin":"Nà chū xì ràng wǒ mén xiào dé qián yǎng hòu hé。","meaning":"The play had us in stitches.","meaningThai":"ละครเรื่องนี้ทำให้เราต้องเย็บแผล"},{"chinese":"我们觉得这部戏很艰涩。","pinyin":"Wǒ mén jué dé zhè bù xì hěn jiān sè。","meaning":"We found the play very heavy.","meaningThai":"เราพบว่าละครหนักมาก"}],"partOfSpeech":["noun","other"]},
  {"id":"hsk5-1222","chinese":"系","pinyin":"xì","meaning":"to connect; to relate to; to tie up; to bind; to be (literary)","meaningThai":"ผูก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我得系领带吗？","pinyin":"Wǒ dé xì lǐng dài ma？","meaning":"Do I have to wear a tie?","meaningThai":"ฉันต้องผูกเน็คไทหรือไม่?"},{"chinese":"她把皮带松松地系在腰上。","pinyin":"Tā bǎ pí dài sōng sōng dì xì zài yāo shàng。","meaning":"She fastened the belt loosely around her waist.","meaningThai":"เธอคาดเข็มขัดรอบเอวอย่างหลวมๆ"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-1223","chinese":"闲","pinyin":"xián","meaning":"enclosure; (variant of 闲) idle; unoccupied; leisure","meaningThai":"ไม่ได้ใช้งาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"别闲磨大好时光！","pinyin":"Bié xián mó dà hǎo shí guāng！","meaning":"Don't idle away your precious time.","meaningThai":"อย่าเสียเวลาอันมีค่าของคุณไปโดยเปล่าประโยชน์"},{"chinese":"他就愿意在家里闲待着。","pinyin":"Tā jiù yuàn yì zài jiā lǐ xián dài zháo。","meaning":"He's happy to mooch around the house all day.","meaningThai":"เขามีความสุขที่ได้เดินเล่นรอบๆ บ้านตลอดทั้งวัน"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-1224","chinese":"县","pinyin":"xiàn","meaning":"county","meaningThai":"เขต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我住在兵库县。","pinyin":"Wǒ zhù zài bīng kù xiàn。","meaning":"I live in Hyogo. / I live in Hyogo Prefecture.","meaningThai":"ฉันอาศัยอยู่ที่เฮียวโงะ / ฉันอาศัยอยู่ในจังหวัดเฮียวโกะ"},{"chinese":"我在兵库县立大学学习。","pinyin":"Wǒ zài bīng kù xiàn lì dà xué xué xí。","meaning":"I'm studying at the University of Hyogo. / I study at the University of Hyogo.","meaningThai":"ฉันกำลังศึกษาอยู่ที่มหาวิทยาลัยเฮียวโงะ / ฉันเรียนที่มหาวิทยาลัยเฮียวโงะ."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1225","chinese":"现场","pinyin":"xiànchǎng","meaning":"the scene (of a crime, accident etc); (on) the spot; (at) the site","meaningThai":"บนเว็บไซต์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在谋杀现场没有搏斗痕迹。","pinyin":"Zài móu shā xiàn cháng méi yǒu bó dǒu hén jì。","meaning":"There were no signs of a struggle at the murder scene.","meaningThai":"ไม่มีร่องรอยการต่อสู้ในที่เกิดเหตุ"},{"chinese":"这是我初次在现场看戏。","pinyin":"Zhè shì wǒ chū cì zài xiàn cháng kàn xì。","meaning":"This was my first taste of live theatre.","meaningThai":"นี่เป็นรสชาติการแสดงสดครั้งแรกของฉัน"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1226","chinese":"现代","pinyin":"xiàndài","meaning":"Hyundai, South Korean company","meaningThai":"ทันสมัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"现代音乐常被认为不如过去的。","pinyin":"Xiàn dài yīn lè cháng bèi rèn wéi bù rú guò qù de。","meaning":"Modern music is often considered inferior to that of the past.","meaningThai":"ดนตรีสมัยใหม่มักถูกมองว่าด้อยกว่าในอดีต"},{"chinese":"他是现代青年男子的典范。","pinyin":"Tā shì xiàn dài qīng nián nán zǐ de diǎn fàn。","meaning":"He is the epitome of a modern young man.","meaningThai":"เขาเป็นตัวอย่างที่ดีของชายหนุ่มยุคใหม่"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1227","chinese":"现代化","pinyin":"xiàndàihuà","meaning":"modernization","meaningThai":"ความทันสมัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"此处的现代化旅馆其实毫无特色。","pinyin":"Cǐ chǔ de xiàn dài huà lǚ guǎn qí shí háo wú tè sè。","meaning":"The modern hotels here have no real character.","meaningThai":"โรงแรมทันสมัยที่นี่ไม่มีตัวตนที่แท้จริง"},{"chinese":"遗憾的是我们缺乏现代化所需的财力。","pinyin":"Yí hàn de shì wǒ mén quē fá xiàn dài huà suǒ xū de cái lì。","meaning":"Unfortunately we lack the resources to modernize.","meaningThai":"น่าเสียดายที่เราขาดทรัพยากรในการปรับปรุงให้ทันสมัย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1228","chinese":"显得","pinyin":"xiǎnde","meaning":"to seem; to look; to appear","meaningThai":"ปรากฏ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的脸色显得憔悴疲惫。","pinyin":"Tā de liǎn sè xiǎn dé qiáo cuì pí bèi。","meaning":"Her face looked strained and weary.","meaningThai":"ใบหน้าของเธอดูเครียดและเหนื่อยล้า"},{"chinese":"希拉当时显得痛苦。","pinyin":"Xī lā dāng shí xiǎn dé tòng kǔ。","meaning":"Sheila was looking miserable.","meaningThai":"ชีล่าดูเศร้าหมอง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1229","chinese":"乡","pinyin":"xiāng","meaning":"country or countryside; native place; home village or town; township (PRC administrative unit)","meaningThai":"เขตการปกครอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他走乡串镇出售自己的货品。","pinyin":"Tā zǒu xiāng chuàn zhèn chū shòu zì jǐ de huò pǐn。","meaning":"He travelled from town to town selling his wares.","meaningThai":"เขาเดินทางจากเมืองหนึ่งไปอีกเมืองหนึ่งเพื่อขายสินค้าของเขา"},{"chinese":"游客可以去纳帕谷酒乡这样的边远地区。","pinyin":"Yóu kè kě yǐ qù nà pà gǔ jiǔ xiāng zhè yàng de biān yuǎn dì qū。","meaning":"Tourists can visit outlying areas like the Napa Valley Wine Country.","meaningThai":"นักท่องเที่ยวสามารถเยี่ยมชมพื้นที่ห่างไกล เช่น Napa Valley Wine Country"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1230","chinese":"相册","pinyin":"xiàngcè","meaning":"photo album","meaningThai":"อัลบั้มรูป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他把相册敞开着放在桌子上了。","pinyin":"Tā bǎ xiāng cè chǎng kāi zháo fàng zài zhuō zǐ shàng le。","meaning":"He left the album open on the table.","meaningThai":"เขาเปิดอัลบั้มทิ้งไว้บนโต๊ะ"},{"chinese":"在下方的书架上他发现了一本相册。","pinyin":"Zài xià fāng de shū jià shàng tā fā xiàn le yī běn xiāng cè。","meaning":"On a shelf beneath he spotted a photo album.","meaningThai":"บนชั้นวางด้านล่างเขามองเห็นอัลบั้มรูปหนึ่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1231","chinese":"相处","pinyin":"xiāngchǔ","meaning":"to be in contact (with sb); to associate; to interact; to get along (well, poorly)","meaningThai":"ได้รับพร้อม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她和同龄人相处融洽。","pinyin":"Tā hé tóng líng rén xiāng chǔ róng qià。","meaning":"She gets on well with her peer group.","meaningThai":"เธอเข้ากับกลุ่มเพื่อนได้ดี"},{"chinese":"不可能跟他和睦相处。","pinyin":"Bù kě néng gēn tā hé mù xiāng chǔ。","meaning":"It's impossible to get along with him.","meaningThai":"เป็นไปไม่ได้ที่จะเข้ากับเขาได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1232","chinese":"乡村","pinyin":"xiāngcūn","meaning":"rustic; village; countryside","meaningThai":"ชนบท","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他很享受乡村生活的宁静。","pinyin":"Tā hěn xiǎng shòu xiāng cūn shēng huó de níng jìng。","meaning":"He enjoyed the tranquillity of country life.","meaningThai":"เขาเพลิดเพลินกับความเงียบสงบของชีวิตในชนบท"},{"chinese":"她过着恬静的乡村生活。","pinyin":"Tā guò zháo tián jìng de xiāng cūn shēng huó。","meaning":"She led a tranquil life in the country.","meaningThai":"เธอมีชีวิตที่เงียบสงบในประเทศ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1233","chinese":"相当","pinyin":"xiāngdāng","meaning":"equivalent to; appropriate; considerably; to a certain extent; fairly; quite","meaningThai":"ค่อนข้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这份报告相当难懂。","pinyin":"Zhè fèn bào gào xiāng dāng nán dǒng。","meaning":"The report was fairly incomprehensible.","meaningThai":"รายงานนี้ค่อนข้างเข้าใจยาก"},{"chinese":"这个游戏相当不错。","pinyin":"Zhè gè yóu xì xiāng dāng bù cuò。","meaning":"The game was pretty good.","meaningThai":"เกมนี้ค่อนข้างดี"}],"partOfSpeech":["adverb","verb"]},
  {"id":"hsk5-1234","chinese":"相对","pinyin":"xiāngduì","meaning":"relatively; opposite; to resist; to oppose; relative; vis-a-vis; counterpart","meaningThai":"สัมพันธ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"相对而言。","pinyin":"Xiang dui er yan.","meaning":"Relatively speaking.","meaningThai":"พูดค่อนข้าง."}],"partOfSpeech":["adverb","verb","adjective"]},
  {"id":"hsk5-1235","chinese":"相关","pinyin":"xiāngguān","meaning":"related; relevant; pertinent; to be interrelated; (statistics) correlation","meaningThai":"ที่เกี่ยวข้อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些问题都是密切相关的。","pinyin":"Zhè xiē wèn tí dū shì mì qiē xiāng guān de。","meaning":"These problems are closely related.","meaningThai":"ปัญหาเหล่านี้มีความสัมพันธ์กันอย่างใกล้ชิด"},{"chinese":"你有相关的经历吗？","pinyin":"Nǐ yǒu xiāng guān de jīng lì ma？","meaning":"Do you have the relevant experience?","meaningThai":"คุณมีประสบการณ์ที่เกี่ยวข้องหรือไม่?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1236","chinese":"项目","pinyin":"xiàngmù","meaning":"item; project; (sports) event","meaningThai":"โครงการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个项目需要三个月完成。","pinyin":"Zhè ge xiàng mù xū yào sān gè yuè wán chéng.","meaning":"This project needs three months to complete.","meaningThai":"โครงการนี้ต้องใช้เวลาสามเดือนจึงจะเสร็จสมบูรณ์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1237","chinese":"想念","pinyin":"xiǎngniàn","meaning":"to miss; to remember with longing; to long to see again","meaningThai":"นางสาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"旅行期间她想念家里的舒适。","pinyin":"Lǚ háng qī jiān tā xiǎng niàn jiā lǐ de shū shì。","meaning":"While travelling she missed the comforts of home.","meaningThai":"ระหว่างเดินทางเธอคิดถึงความสะดวกสบายที่บ้าน"},{"chinese":"“你想念他们，是吗？”他温和地问道。","pinyin":"“ nǐ xiǎng niàn tā mén， shì ma？” tā wēn hé dì wèn dào。","meaning":"'You miss them, don't you?' he asked gently.","meaningThai":"'คุณคิดถึงพวกเขาใช่ไหม' เขาถามเบา ๆ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1238","chinese":"橡皮","pinyin":"xiàngpí","meaning":"rubber; an eraser","meaningThai":"ยางลบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"剁辣椒时戴上橡皮手套，因为它们会刺激皮肤。","pinyin":"Duò là jiāo shí dài shàng xiàng pí shǒu tào， yīn wéi tā mén huì cì jī pí fū。","meaning":"Wear rubber gloves while chopping chillies as they can irritate the skin.","meaningThai":"สวมถุงมือยางขณะสับพริกเพราะอาจทำให้ผิวหนังระคายเคืองได้"},{"chinese":"有7人在士兵们发射橡皮子弹驱散人群时受了伤。","pinyin":"Yǒu 7 rén zài shì bīng mén fā shè xiàng pí zǐ dàn qū sàn rén qún shí shòu le shāng。","meaning":"Seven people were wounded when soldiers fired rubber bullets to disperse crowds.","meaningThai":"เหตุทหารยิงกระสุนยางเข้าสลายฝูงชน บาดเจ็บ 7 ราย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1239","chinese":"向上","pinyin":"xiàngshàng","meaning":"upward; up; to advance; to try to improve oneself; to make progress","meaningThai":"ขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她再次沿着峭壁开始向上攀爬。","pinyin":"Tā zài cì yán zháo qiào bì kāi shǐ xiàng shàng pān pá。","meaning":"She started once again on the steep upward climb.","meaningThai":"เธอเริ่มต้นอีกครั้งด้วยการปีนขึ้นที่สูงชัน"},{"chinese":"两脚叉开站着，双手向上。","pinyin":"Liǎng jiǎo chā kāi zhàn zháo， shuāng shǒu xiàng shàng。","meaning":"Stand with your feet apart and your hands facing upwards.","meaningThai":"ยืนแยกเท้าออกจากกันและหงายมือขึ้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1240","chinese":"响声","pinyin":"xiǎngshēng","meaning":"noise","meaningThai":"เสียง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"听！那是什么响声？你能听见吗？","pinyin":"Tīng！ nà shì shí mó xiǎng shēng？ nǐ néng tīng jiàn ma？","meaning":"Listen! What's that noise? Can you hear it?","meaningThai":"ฟัง! นั่นเสียงอะไรน่ะ? คุณได้ยินมันไหม?"},{"chinese":"她听到响声，就回过头去看。","pinyin":"Tā tīng dào xiǎng shēng， jiù huí guò tóu qù kàn。","meaning":"She looked round when she heard the noise.","meaningThai":"เธอมองไปรอบๆ เมื่อได้ยินเสียงดัง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1241","chinese":"享受","pinyin":"xiǎngshòu","meaning":"to enjoy; to live it up; pleasure","meaningThai":"สนุก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他是个尽情享受生活乐趣的人。","pinyin":"Tā shì gè jìn qíng xiǎng shòu shēng huó lè qù de rén。","meaning":"He was a guy who enjoyed life to the full.","meaningThai":"เขาเป็นผู้ชายที่สนุกกับชีวิตอย่างเต็มที่"},{"chinese":"咱们轻松一下，好好享受享受。","pinyin":"Zán mén qīng sōng yī xià， hǎo hǎo xiǎng shòu xiǎng shòu。","meaning":"Let's just relax and enjoy ourselves.","meaningThai":"มาผ่อนคลายและสนุกกับตัวเองกันดีกว่า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1242","chinese":"相似","pinyin":"xiāngsì","meaning":"similar; alike","meaningThai":"ความคล้ายคลึงกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们所有的病人问题大致相似。","pinyin":"Wǒ mén suǒ yǒu de bìng rén wèn tí dà zhì xiāng sì。","meaning":"All our patients have broadly similar problems.","meaningThai":"คนไข้ของเราทุกคนก็มีปัญหาคล้ายกันในวงกว้าง"},{"chinese":"我的教学风格和多数教师相似。","pinyin":"Wǒ de jiào xué fēng gé hé duō shù jiào shī xiāng sì。","meaning":"My teaching style is similar to that of most other teachers.","meaningThai":"รูปแบบการสอนของฉันคล้ายกับครูคนอื่นๆ ส่วนใหญ่"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1243","chinese":"想象","pinyin":"xiǎngxiàng","meaning":"to imagine; to envision; imagination","meaningThai":"จินตนาการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她发挥了海阔天空的想象。","pinyin":"Tā fā huī le hǎi kuò tiān kōng de xiǎng xiàng。","meaning":"Her imagination took wing.","meaningThai":"จินตนาการของเธอมีปีก"},{"chinese":"我不能想象他会这么蠢。","pinyin":"Wǒ bù néng xiǎng xiàng tā huì zhè mó chǔn。","meaning":"I can't think (that) he would be so stupid.","meaningThai":"ไม่คิดว่าเขาจะโง่ขนาดนี้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1244","chinese":"象征","pinyin":"xiàngzhēng","meaning":"emblem; symbol; token; badge; to symbolize; to signify; to stand for","meaningThai":"เครื่องหมาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"黄色衣服被穿着来象征春天。","pinyin":"Huáng sè yī fú bèi chuān zháo lái xiàng zhēng chūn tiān。","meaning":"Yellow clothes are worn as symbolic of spring.","meaningThai":"เสื้อผ้าสีเหลืองสวมใส่เป็นสัญลักษณ์ของฤดูใบไม้ผลิ"},{"chinese":"用光明与黑暗来象征善与恶。","pinyin":"Yòng guāng míng yǔ hēi àn lái xiàng zhēng shàn yǔ è。","meaning":"The use of light and dark symbolizes good and evil.","meaningThai":"การใช้แสงสว่างและความมืดเป็นสัญลักษณ์ของความดีและความชั่ว"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-1245","chinese":"先后","pinyin":"xiānhòu","meaning":"early or late; priority; in succession; one after another","meaningThai":"อย่างต่อเนื่อง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"校队先后胜了5场球。","pinyin":"Xiào duì xiān hòu shèng le 5 cháng qiú。","meaning":"The school team won five games successively.","meaningThai":"ทีมโรงเรียนชนะห้าเกมติดต่อกัน"},{"chinese":"这些事实应按时间先后顺序陈述。","pinyin":"Zhè xiē shì shí yīng àn shí jiān xiān hòu shùn xù chén shù。","meaning":"The facts should be presented in chronological order.","meaningThai":"ควรนำเสนอข้อเท็จจริงตามลำดับเวลา"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1246","chinese":"先进","pinyin":"xiānjìn","meaning":"advanced (technology); to advance","meaningThai":"ขั้นสูง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些绝密文件涉及最先进的军事装备。","pinyin":"Zhè xiē jué mì wén jiàn shè jí zuì xiān jìn de jūn shì zhuāng bèi。","meaning":"The top secret documents had to do with the most advanced military equipment.","meaningThai":"เอกสารลับสุดยอดเกี่ยวข้องกับอุปกรณ์ทางทหารที่ทันสมัยที่สุด"},{"chinese":"我们一开始先进行自我介绍。","pinyin":"Wǒ mén yī kāi shǐ xiān jìn háng zì wǒ jiè shào。","meaning":"We started off by introducing ourselves.","meaningThai":"เราเริ่มต้นด้วยการแนะนำตัวเอง"}],"partOfSpeech":["adjective","noun"]},
  {"id":"hsk5-1247","chinese":"线路","pinyin":"xiànlù","meaning":"(electricity) line; circuit; wire; (traffic) road; track; route","meaningThai":"เส้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你的账单包括电话线路的租用费。","pinyin":"Nǐ de zhàng dān bāo kuò diàn huà xiàn lù de zū yòng fèi。","meaning":"Your bill includes line rental.","meaningThai":"ใบเรียกเก็บเงินของคุณรวมถึงการเช่าสาย"},{"chinese":"没用。我们挂断电话试打更好的线路吧。","pinyin":"Méi yòng。 wǒ mén guà duàn diàn huà shì dǎ gēng hǎo de xiàn lù bā。","meaning":"It's no use. Let's hang up and try for a better line.","meaningThai":"มันไม่มีประโยชน์ วางสายแล้วลองต่อสายดูดีกว่า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1248","chinese":"显然","pinyin":"xiǎnrán","meaning":"clearly; evidently; obviously","meaningThai":"อย่างชัดเจน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我的话显然惹恼了她。","pinyin":"Wǒ de huà xiǎn rán rě nǎo le tā。","meaning":"My remarks clearly nettled her.","meaningThai":"คำพูดของฉันทำให้เธอสะเทือนใจอย่างเห็นได้ชัด"},{"chinese":"这匹马显然状态不佳。","pinyin":"Zhè pǐ mǎ xiǎn rán zhuàng tài bù jiā。","meaning":"The horse was clearly out of form.","meaningThai":"ม้าเสียฟอร์มอย่างเห็นได้ชัด"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1249","chinese":"现实","pinyin":"xiànshí","meaning":"reality; actuality; real; actual; realistic; pragmatic; materialistic; self-interested","meaningThai":"ความเป็นจริง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"时光旅行真的会成为现实吗？","pinyin":"Shí guāng lǚ háng zhēn de huì chéng wéi xiàn shí ma？","meaning":"Will time travel ever become a reality ?","meaningThai":"การเดินทางข้ามเวลาจะกลายเป็นความจริงหรือไม่?"},{"chinese":"夏洛特好像生活在现实之外。","pinyin":"Xià luò tè hǎo xiàng shēng huó zài xiàn shí zhī wài。","meaning":"Charlotte seemed to be living at one remove from reality.","meaningThai":"ชาร์ลอตต์ดูเหมือนจะมีชีวิตอยู่ ณ จุดหนึ่งที่ห่างไกลจากความเป็นจริง"}],"partOfSpeech":["noun","adjective"]},
  {"id":"hsk5-1250","chinese":"显示","pinyin":"xiǎnshì","meaning":"to show; to illustrate; to display; to demonstrate","meaningThai":"แสดง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"发光的表盘上显示6：55。","pinyin":"Fā guāng de biǎo pán shàng xiǎn shì6：55。","meaning":"The luminous dial on the clock showed five minutes to seven.","meaningThai":"หน้าปัดเรืองแสงบนนาฬิกาบอกเวลาห้านาทีถึงเจ็ดนาที"},{"chinese":"电视画面显示了严寒的环境。","pinyin":"Diàn shì huà miàn xiǎn shì le yán hán de huán jìng。","meaning":"TV pictures showed the arctic conditions.","meaningThai":"ภาพทางทีวีแสดงให้เห็นสภาพอาร์กติก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1251","chinese":"现象","pinyin":"xiànxiàng","meaning":"phenomenon; appearance","meaningThai":"ปรากฏการณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该现象引起莫里思博士的兴趣。","pinyin":"Gāi xiàn xiàng yǐn qǐ mò lǐ sī bó shì de xīng qù。","meaning":"This phenomenon piqued Dr. Morris' interest.","meaningThai":"ปรากฏการณ์นี้กระตุ้นความสนใจของดร. มอร์ริส"},{"chinese":"造成这种现象的原因尚未彻底弄清。","pinyin":"Zào chéng zhè zhǒng xiàn xiàng de yuán yīn shàng wèi chè dǐ nòng qīng。","meaning":"The causes of the phenomenon are still incompletely understood.","meaningThai":"สาเหตุของปรากฏการณ์นี้ยังไม่เป็นที่เข้าใจอย่างสมบูรณ์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1252","chinese":"限制","pinyin":"xiànzhì","meaning":"to restrict; to limit; to confine; restriction; limit","meaningThai":"ขีด จำกัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"欧盟对污染程度作了严格的限制。","pinyin":"Ōu méng duì wū rǎn chéng dù zuò le yán gé de xiàn zhì。","meaning":"The EU has set strict limits on levels of pollution.","meaningThai":"สหภาพยุโรปได้กำหนดขีดจำกัดระดับมลพิษที่เข้มงวด"},{"chinese":"食品应允许快速流通，少受限制。","pinyin":"Shí pǐn yīng yǔn xǔ kuài sù liú tōng， shǎo shòu xiàn zhì。","meaning":"Food should be allowed to go through immediately with fewer restrictions.","meaningThai":"ควรอนุญาตให้อาหารผ่านได้ทันทีโดยมีข้อจำกัดน้อยลง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1253","chinese":"现状","pinyin":"xiànzhuàng","meaning":"current situation","meaningThai":"สภาพปัจจุบัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"维持现状。","pinyin":"Wei chi xian zhuang.","meaning":"Maintain the status quo.","meaningThai":"รักษาสภาพที่เป็นอยู่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1254","chinese":"消费","pinyin":"xiāofèi","meaning":"to consume; to spend","meaningThai":"การบริโภค","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们生活在一种消费文化之中。","pinyin":"Wǒ mén shēng huó zài yī zhǒng xiāo fèi wén huà zhī zhōng。","meaning":"We are living in a consumer culture.","meaningThai":"เราอาศัยอยู่ในวัฒนธรรมผู้บริโภค"},{"chinese":"消费结构的调整也落后了。","pinyin":"Xiāo fèi jié gòu de tiáo zhěng yě luò hòu le。","meaning":"The restructuring of the pattern of consumption also lagged behind.","meaningThai":"การปรับโครงสร้างรูปแบบการบริโภคยังล้าหลังอีกด้วย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1255","chinese":"消费者","pinyin":"xiāofèizhě","meaning":"consumer","meaningThai":"ผู้บริโภค","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"对于消费者来说暂时一切照常。","pinyin":"Duì yú xiāo fèi zhě lái shuō zàn shí yī qiē zhào cháng。","meaning":"For the time being it's business as usual for consumers.","meaningThai":"ในขณะนี้ก็ยังดำเนินธุรกิจตามปกติสำหรับผู้บริโภค"},{"chinese":"没有清楚公正的信息提供给消费者。","pinyin":"Méi yǒu qīng chǔ gōng zhèng de xìn xī tí gōng gěi xiāo fèi zhě。","meaning":"There is no clear and unbiased information available for consumers.","meaningThai":"ไม่มีข้อมูลที่ชัดเจนและเป็นกลางสำหรับผู้บริโภค"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1256","chinese":"消化","pinyin":"xiāohuà","meaning":"to digest (food); (fig.) to absorb (information etc); to assimilate; to process","meaningThai":"การย่อยอาหาร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"饭后你应该留点时间让食物消化。","pinyin":"Fàn hòu nǐ yīng gāi liú diǎn shí jiān ràng shí wù xiāo huà。","meaning":"You should allow a little time after a meal for the food to digest.","meaningThai":"คุณควรเผื่อเวลาเล็กน้อยหลังมื้ออาหารเพื่อให้อาหารย่อย"},{"chinese":"上菜时不提供饮料，因为会妨碍消化。","pinyin":"Shàng cài shí bù tí gōng yǐn liào， yīn wéi huì fáng ài xiāo huà。","meaning":"No liquids are served with meals because they interfere with digestion.","meaningThai":"ไม่มีการเสิร์ฟของเหลวพร้อมกับอาหารเนื่องจากจะรบกวนการย่อยอาหาร"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1257","chinese":"消极","pinyin":"xiāojí","meaning":"negative; passive; inactive","meaningThai":"เชิงลบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"失业会对工作产生消极态度。","pinyin":"Shī yè huì duì gōng zuò chǎn shēng xiāo jí tài dù。","meaning":"Being unemployed produces negative attitudes to work.","meaningThai":"การว่างงานทำให้เกิดทัศนคติเชิงลบต่อการทำงาน"},{"chinese":"尽量别受消极的想法左右。","pinyin":"Jìn liáng bié shòu xiāo jí de xiǎng fǎ zuǒ yòu。","meaning":"Try not to let negative thoughts take over.","meaningThai":"พยายามอย่าปล่อยให้ความคิดเชิงลบครอบงำ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1258","chinese":"小姐","pinyin":"xiǎojiě","meaning":"young lady; miss; (slang) prostitute","meaningThai":"นางสาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"祝相葉小姐生日快樂！","pinyin":"Zhù xiāng yè xiǎo jiě shēng rì kuài lè！","meaning":"Happy birthday, Miss Aiba!","meaningThai":"สุขสันต์วันเกิดคุณไอบะ!"},{"chinese":"小姐！我觉得不舒服。","pinyin":"Xiǎo jiě！ wǒ jué dé bù shū fú。","meaning":"Miss! I feel sick.","meaningThai":"นางสาว! ฉันรู้สึกไม่สบาย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1259","chinese":"销量","pinyin":"xiāoliàng","meaning":"sales volume","meaningThai":"ยอดขาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这款产品的销量很好。","pinyin":"Zhe kuan chan pin de xiao liang hen hao.","meaning":"This product has great sales volume.","meaningThai":"ผลิตภัณฑ์นี้มีปริมาณการขายที่ดี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1260","chinese":"效率","pinyin":"xiàolǜ","meaning":"efficiency","meaningThai":"ประสิทธิภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"定期给冰箱除霜能取得最大效率。","pinyin":"Dìng qī gěi bīng xiāng chú shuāng néng qǔ dé zuì dà xiào shuài。","meaning":"Defrost the fridge regularly so that it works at maximum efficiency.","meaningThai":"ละลายน้ำแข็งในตู้เย็นเป็นประจำเพื่อให้ทำงานได้อย่างมีประสิทธิภาพสูงสุด"},{"chinese":"计算机在处理信息方面效率极高。","pinyin":"Jì suàn jī zài chǔ lǐ xìn xī fāng miàn xiào shuài jí gāo。","meaning":"Computers are very efficient at manipulating information.","meaningThai":"คอมพิวเตอร์มีประสิทธิภาพมากในการจัดการข้อมูล"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1261","chinese":"消失","pinyin":"xiāoshī","meaning":"to disappear; to fade away","meaningThai":"หายไป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"小径过山顶后消失了。","pinyin":"Xiǎo jìng guò shān dǐng hòu xiāo shī le。","meaning":"The path disappeared over the brow of the hill.","meaningThai":"เส้นทางหายไปเหนือคิ้วเนินเขา"},{"chinese":"太阳消失在云层里。","pinyin":"Tài yáng xiāo shī zài yún céng lǐ。","meaning":"The sun disappeared behind the clouds.","meaningThai":"พระอาทิตย์หายไปหลังเมฆ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1262","chinese":"销售","pinyin":"xiāoshòu","meaning":"to sell; to market; sales (representative, agreement etc)","meaningThai":"ขาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"今年的销售数字情况看好。","pinyin":"Jīn nián de xiāo shòu shù zì qíng kuàng kàn hǎo。","meaning":"This year's sales figures are looking good.","meaningThai":"ตัวเลขยอดขายปีนี้ดูดี"},{"chinese":"公司正在削减销售人员。","pinyin":"Gōng sī zhèng zài xiāo jiǎn xiāo shòu rén yuán。","meaning":"The company is running down its sales force.","meaningThai":"บริษัทกำลังลดกำลังการขายลง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1263","chinese":"小型","pinyin":"xiǎoxíng","meaning":"small scale; small size","meaningThai":"เล็ก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们有一架小型飞机，对吧？","pinyin":"Tā mén yǒu yī jià xiǎo xíng fēi jī， duì bā？","meaning":"They have a small plane, right?","meaningThai":"พวกเขามีเครื่องบินเล็กใช่ไหม?"},{"chinese":"如今对小型专卖店已没有多大需求了。","pinyin":"Rú jīn duì xiǎo xíng zhuān mài diàn yǐ méi yǒu duō dà xū qiú le。","meaning":"There isn't a lot of call for small specialist shops nowadays.","meaningThai":"ในปัจจุบันนี้ไม่มีการเรียกร้องให้มีร้านค้าเฉพาะทางขนาดเล็กมากนัก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1264","chinese":"小于","pinyin":"xiǎoyú","meaning":"less than, <","meaningThai":"น้อยกว่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"是零，小于零，还是大于零呢？","pinyin":"Shì líng， xiǎo yú líng， huán shì dà yú líng ne？","meaning":"Is it zero, less than zero or more than zero?","meaningThai":"มันเป็นศูนย์ น้อยกว่าศูนย์ หรือมากกว่าศูนย์?"},{"chinese":"在火星上，直径小于5公里的陨石坑相对较少。","pinyin":"Zài huǒ xīng shàng， zhí jìng xiǎo yú 5 gōng lǐ de yǔn shí kēng xiāng duì jiào shǎo。","meaning":"On Mars, there are relatively few craters less than 5 kilometers in diameter.","meaningThai":"บนดาวอังคาร มีหลุมอุกกาบาตที่มีเส้นผ่านศูนย์กลางไม่ถึง 5 กิโลเมตรค่อนข้างน้อย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1265","chinese":"下载","pinyin":"xiàzài","meaning":"to download; also pr. [xià zài]","meaningThai":"ดาวน์โหลด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你可以用JPEG格式下载这些图像。","pinyin":"Nǐ kě yǐ yòng JPEG gé shì xià zǎi zhè xiē tú xiàng。","meaning":"You can download the pictures as JPEGs.","meaningThai":"คุณสามารถดาวน์โหลดรูปภาพเป็น JPEG ได้"},{"chinese":"你可以把文件下载，用文字处理系统做编辑。","pinyin":"Nǐ kě yǐ bǎ wén jiàn xià zǎi， yòng wén zì chǔ lǐ xì tǒng zuò biān jí。","meaning":"You can download the file and edit it on your word processor.","meaningThai":"คุณสามารถดาวน์โหลดไฟล์และแก้ไขด้วยโปรแกรมประมวลผลคำของคุณได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1266","chinese":"西餐","pinyin":"xīcān","meaning":"Western-style food","meaningThai":"อาหารตะวันตก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那家西餐厅，怎么样？","pinyin":"Nà jiā xī cān tīng， zěn mó yàng？","meaning":"How about that western restaurant?","meaningThai":"แล้วร้านอาหารตะวันตกล่ะ?"},{"chinese":"欢迎来我们西餐厅。","pinyin":"Huān yíng lái wǒ mén xī cān tīng。","meaning":"Welcome to our western restaurant.","meaningThai":"ยินดีต้อนรับสู่ร้านอาหารตะวันตกของเรา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1267","chinese":"斜","pinyin":"xié","meaning":"inclined; slanting; oblique; tilting","meaningThai":"เอียง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她把镜子斜放，开始梳头。","pinyin":"Tā bǎ jìng zǐ xié fàng， kāi shǐ shū tóu。","meaning":"She tilted the mirror and began to comb her hair.","meaningThai":"เธอเอียงกระจกและเริ่มหวีผม"},{"chinese":"这条裙子是斜裁的。","pinyin":"Zhè tiáo qún zǐ shì xié cái de。","meaning":"The skirt is cut on the bias.","meaningThai":"กระโปรงถูกตัดอคติ"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1268","chinese":"协议","pinyin":"xiéyì","meaning":"agreement; pact; protocol","meaningThai":"ข้อตกลง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"达成协议。","pinyin":"Da cheng xie yi.","meaning":"Reach an agreement.","meaningThai":"บรรลุข้อตกลง"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-1269","chinese":"写作","pinyin":"xiězuò","meaning":"to write; to compose; writing; written works","meaningThai":"การเขียน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"关于这项写作任务，以下有几点建议。","pinyin":"Guān yú zhè xiàng xiě zuò rèn wù， yǐ xià yǒu jī diǎn jiàn yì。","meaning":"Here are some pointers on how to go about the writing task.","meaningThai":"ต่อไปนี้เป็นคำแนะนำบางประการเกี่ยวกับวิธีดำเนินการเขียน"},{"chinese":"他的写作生涯超过了40年。","pinyin":"Tā de xiě zuò shēng yá chāo guò le 40 nián。","meaning":"His writing career extended over a period of 40 years.","meaningThai":"อาชีพการเขียนของเขาขยายออกไปเป็นระยะเวลา 40 ปี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1270","chinese":"吸管","pinyin":"xīguǎn","meaning":"(drinking) straw; pipette; eyedropper; snorkel","meaningThai":"หลอด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她正用吸管咕嘟咕嘟地喝牛奶。","pinyin":"Tā zhèng yòng xī guǎn gū dū gū dū dì hē niú nǎi。","meaning":"She was noisily sucking up milk through a straw.","meaningThai":"เธอดูดนมด้วยหลอดอย่างส่งเสียงดัง"},{"chinese":"塑料吸管尤其可怕。","pinyin":"Sù liào xī guǎn yóu qí kě pà。","meaning":"Plastic straws are especially terrible.","meaningThai":"หลอดพลาสติกนั้นแย่มากโดยเฉพาะ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1271","chinese":"细节","pinyin":"xìjié","meaning":"details; particulars","meaningThai":"รายละเอียด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们仍在为财务细节争吵。","pinyin":"Tā mén réng zài wéi cái wù xì jié zhēng chǎo。","meaning":"They're still wrangling over the financial details.","meaningThai":"พวกเขายังคงถกเถียงกันเรื่องรายละเอียดทางการเงิน"},{"chinese":"准确的细节仍需最后敲定。","pinyin":"Zhǔn què de xì jié réng xū zuì hòu qiāo dìng。","meaning":"The precise details still have to be firmed up.","meaningThai":"รายละเอียดที่ชัดเจนยังคงต้องได้รับการทำให้แน่นขึ้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1272","chinese":"戏剧","pinyin":"xìjù","meaning":"a drama; a play; theater; script of a play","meaningThai":"ละคร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我认为这部戏剧只是平庸之作。","pinyin":"Wǒ rèn wéi zhè bù xì jù zhī shì píng yōng zhī zuò。","meaning":"I thought the play was only mediocre.","meaningThai":"ฉันคิดว่าละครเรื่องนี้เป็นเพียงปานกลางเท่านั้น"},{"chinese":"她正在参加学校戏剧演员甄选。","pinyin":"Tā zhèng zài cān jiā xué xiào xì jù yǎn yuán zhēn xuǎn。","meaning":"She's trying out for the school play.","meaningThai":"เธอกำลังลองเล่นละครของโรงเรียน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1273","chinese":"信封","pinyin":"xìnfēng","meaning":"envelope","meaningThai":"ซองจดหมาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我撕开了信封。","pinyin":"Wǒ sī kāi le xìn fēng。","meaning":"I ripped the envelope open.","meaningThai":"ฉันฉีกซองจดหมายออก"},{"chinese":"請給我一個信封。","pinyin":"Qǐng gěi wǒ yī gè xìn fēng。","meaning":"Please give me an envelope.","meaningThai":"กรุณาส่งซองจดหมายให้ฉันด้วย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1274","chinese":"行程","pinyin":"xíngchéng","meaning":"journey; course of a journey; distance traveled; trajectory; itinerary; route; course (of history); stroke (of a piston); (Tw) (computing) process","meaningThai":"การเดินทาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他在最后一刻推迟了他的行程。","pinyin":"Tā zài zuì hòu yī kè tuī chí le tā de háng chéng。","meaning":"He postponed his trip at the eleventh hour.","meaningThai":"เขาเลื่อนการเดินทางออกไปตอนสิบเอ็ดโมง"},{"chinese":"行程已经延长以包括其他几项活动。","pinyin":"Háng chéng yǐ jīng yán cháng yǐ bāo kuò qí tā jī xiàng huó dòng。","meaning":"The trip has been extended to include a few other events.","meaningThai":"การเดินทางได้รับการขยายออกไปเพื่อรวมกิจกรรมอื่นๆ สองสามรายการ"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-1275","chinese":"形成","pinyin":"xíngchéng","meaning":"to form; to take shape","meaningThai":"รูปร่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种物质聚合形成坚硬的塑料。","pinyin":"Zhè zhǒng wù zhì jù hé xíng chéng jiān yìng de sù liào。","meaning":"The substance polymerizes to form a hard plastic.","meaningThai":"สารจะเกิดปฏิกิริยาโพลีเมอร์จนกลายเป็นพลาสติกแข็ง"},{"chinese":"这些颗粒聚结形成较大的团。","pinyin":"Zhè xiē kē lì jù jié xíng chéng jiào dà de tuán。","meaning":"These small particles agglomerate together to form larger clusters.","meaningThai":"อนุภาคขนาดเล็กเหล่านี้จะรวมตัวกันเป็นกระจุกที่ใหญ่ขึ้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1276","chinese":"行动","pinyin":"xíngdòng","meaning":"operation; action; to move about; mobile","meaningThai":"การกระทำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们立即断然采取了行动。","pinyin":"Tā mén lì jí duàn rán cǎi qǔ le háng dòng。","meaning":"They leapt into action immediately.","meaningThai":"พวกเขากระโจนลงมือปฏิบัติทันที"},{"chinese":"已经告诫他们采取行动。","pinyin":"Yǐ jīng gào jiè tā mén cǎi qǔ háng dòng。","meaning":"They had been exhorted to action.","meaningThai":"พวกเขาได้รับการกระตุ้นเตือนให้ลงมือปฏิบัติ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1277","chinese":"行人","pinyin":"xíngrén","meaning":"pedestrian; traveler on foot; passer-by; official responsible for arranging audiences with the emperor","meaningThai":"คนเดินเท้า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我的母亲经常让行人吃耳光。","pinyin":"Wǒ de mǔ qīn jīng cháng ràng háng rén chī ěr guāng。","meaning":"My mother often slaps passers-by.","meaningThai":"แม่ของฉันตบคนที่เดินผ่านไปมาบ่อยๆ"},{"chinese":"当时正是早高峰，来来往往的行人和车辆很多。","pinyin":"Dāng shí zhèng shì zǎo gāo fēng， lái lái wǎng wǎng de háng rén hé chē liàng hěn duō。","meaning":"It was the morning rush hour, and there were a lot of passing pedestrians and cars.","meaningThai":"เป็นชั่วโมงเร่งด่วนในตอนเช้า มีผู้คนสัญจรไปมาและรถยนต์สัญจรไปมาเป็นจำนวนมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1278","chinese":"形容","pinyin":"xíngróng","meaning":"to describe; (literary) countenance; appearance","meaningThai":"อธิบาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他形容毒品是这个时代最大的灾难。","pinyin":"Tā xíng róng dú pǐn shì zhè gè shí dài zuì dà de zāi nán。","meaning":"He described drugs as the greatest calamity of the age.","meaningThai":"เขาอธิบายว่ายาเสพติดเป็นหายนะที่ยิ่งใหญ่ที่สุดในยุคนั้น"},{"chinese":"我无法形容我当时的满足感。","pinyin":"Wǒ wú fǎ xíng róng wǒ dāng shí de mǎn zú gǎn。","meaning":"I cannot describe the feeling of contentment that was with me at that time.","meaningThai":"ฉันไม่สามารถอธิบายความรู้สึกพึงพอใจที่อยู่กับฉันในขณะนั้นได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1279","chinese":"形式","pinyin":"xíngshì","meaning":"outer appearance; form; shape; formality","meaningThai":"รูปร่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我反对任何形式的审查。","pinyin":"Wǒ fǎn duì rèn hé xíng shì de shěn chá。","meaning":"I'm opposed to censorship in any shape or form.","meaningThai":"ฉันไม่เห็นด้วยกับการเซ็นเซอร์ในรูปแบบหรือรูปแบบใดๆ"},{"chinese":"我反对任何形式的狩猎。","pinyin":"Wǒ fǎn duì rèn hé xíng shì de shòu liè。","meaning":"I am against hunting in any form.","meaningThai":"ฉันต่อต้านการล่าสัตว์ทุกรูปแบบ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1280","chinese":"形势","pinyin":"xíngshì","meaning":"circumstances; situation; terrain","meaningThai":"สถานการณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"黎巴嫩的形势非常复杂。","pinyin":"Lí bā nèn de xíng shì fēi cháng fù zá。","meaning":"The situation in Lebanon is very complicated.","meaningThai":"สถานการณ์ในเลบานอนมีความซับซ้อนมาก"},{"chinese":"我赞成她对形势的分析。","pinyin":"Wǒ zàn chéng tā duì xíng shì de fēn xī。","meaning":"I agree with her analysis of the situation.","meaningThai":"ฉันเห็นด้วยกับการวิเคราะห์สถานการณ์ของเธอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1281","chinese":"行驶","pinyin":"xíngshǐ","meaning":"to travel along a route (of vehicles etc)","meaningThai":"การท่องเที่ยว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在行驶中那个婴儿睡了。","pinyin":"Zài háng shǐ zhōng nà gè yīng ér shuì le。","meaning":"During the drive, the baby slept.","meaningThai":"ระหว่างขับรถลูกก็หลับไป"},{"chinese":"火车现在正缓慢行驶。","pinyin":"Huǒ chē xiàn zài zhèng huǎn màn háng shǐ。","meaning":"The train was moving now at a snail's pace.","meaningThai":"ตอนนี้รถไฟกำลังวิ่งด้วยความเร็วเท่าหอยทาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1282","chinese":"行为","pinyin":"xíngwéi","meaning":"action; conduct; behavior; activity","meaningThai":"พฤติกรรม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们认为他行为反常。","pinyin":"Tā mén rèn wéi tā háng wéi fǎn cháng。","meaning":"They thought his behaviour was abnormal.","meaningThai":"พวกเขาคิดว่าพฤติกรรมของเขาผิดปกติ"},{"chinese":"我不能宽恕那种行为。","pinyin":"Wǒ bù néng kuān shù nà zhǒng háng wéi。","meaning":"I can't forgive that type of behaviour.","meaningThai":"ฉันไม่สามารถให้อภัยพฤติกรรมแบบนั้นได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1283","chinese":"形象","pinyin":"xíngxiàng","meaning":"image; form; figure; visualization; vivid","meaningThai":"ภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些广告旨在提高公司的形象。","pinyin":"Zhè xiē guǎng gào zhǐ zài tí gāo gōng sī de xíng xiàng。","meaning":"The advertisements are intended to improve the company's image.","meaningThai":"โฆษณามีวัตถุประสงค์เพื่อปรับปรุงภาพลักษณ์ของบริษัท"},{"chinese":"这桩交易破坏了他的清廉形象。","pinyin":"Zhè zhuāng jiāo yì pò huài le tā de qīng lián xíng xiàng。","meaning":"The deal destroyed his image as Mr. Clean.","meaningThai":"ข้อตกลงดังกล่าวทำลายภาพลักษณ์ของเขาในฐานะมิสเตอร์คลีน"}],"partOfSpeech":["noun","adjective"]},
  {"id":"hsk5-1284","chinese":"幸运","pinyin":"xìngyùn","meaning":"fortunate; lucky; fortune; luck","meaningThai":"โชคดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们能平安返家真是幸运。","pinyin":"Tā mén néng píng ān fǎn jiā zhēn shì xìng yùn。","meaning":"They were lucky to get home in one piece.","meaningThai":"พวกเขาโชคดีที่กลับบ้านได้ชิ้นเดียว"},{"chinese":"和他相识，我觉得很幸运。","pinyin":"Hé tā xiāng shí， wǒ jué dé hěn xìng yùn。","meaning":"I count myself lucky to have known him.","meaningThai":"ฉันถือว่าตัวเองโชคดีที่ได้รู้จักเขา"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1285","chinese":"性质","pinyin":"xìngzhì","meaning":"nature; characteristic","meaningThai":"ธรรมชาติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"戴高乐将军意识到核武器将从根本上改变国际关系的性质。","pinyin":"Dài gāo lè jiāng jūn yì shí dào hé wǔ qì jiāng cóng gēn běn shàng gǎi biàn guó jì guān xì de xìng zhì。","meaning":"Gen. de Gaulle sensed that nuclear weapons would fundamentally change the nature of international relations.","meaningThai":"พล.อ. เดอ โกลรู้สึกว่าอาวุธนิวเคลียร์จะเปลี่ยนธรรมชาติของความสัมพันธ์ระหว่างประเทศโดยพื้นฐาน"},{"chinese":"他谈到保持该国的非宗教国性质。","pinyin":"Tā tán dào bǎo chí gāi guó de fēi zōng jiào guó xìng zhì。","meaning":"He spoke about preserving the country as a secular state.","meaningThai":"เขาพูดถึงการรักษาประเทศให้เป็นรัฐฆราวาส"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1286","chinese":"形状","pinyin":"xíngzhuàng","meaning":"form; shape","meaningThai":"รูปร่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有各种形状和大小的蜡烛供应。","pinyin":"Yǒu gè zhǒng xíng zhuàng hé dà xiǎo de là zhú gōng yīng。","meaning":"Candles come in all shapes and sizes.","meaningThai":"เทียนมีทุกรูปทรงและขนาด"},{"chinese":"帐篷有各种各样的形状和大小。","pinyin":"Zhàng péng yǒu gè zhǒng gè yàng de xíng zhuàng hé dà xiǎo。","meaning":"Tents come in various shapes and sizes.","meaningThai":"เต็นท์มีรูปทรงและขนาดต่างๆ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1287","chinese":"行走","pinyin":"xíngzǒu","meaning":"to walk","meaningThai":"เดิน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这本指南告诫夜间不要单独行走。","pinyin":"Zhè běn zhǐ nán gào jiè yè jiān bù yào dān dú háng zǒu。","meaning":"The guidebook warns against walking alone at night.","meaningThai":"หนังสือนำเที่ยวเตือนไม่ให้เดินคนเดียวในเวลากลางคืน"},{"chinese":"他沿着查尔斯大街快步行走。","pinyin":"Tā yán zháo chá ěr sī dà jiē kuài bù háng zǒu。","meaning":"He walked at a rapid pace along Charles Street.","meaningThai":"เขาเดินอย่างรวดเร็วไปตามถนนชาร์ลส์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1288","chinese":"新郎","pinyin":"xīnláng","meaning":"bridegroom; groom","meaningThai":"เจ้าบ่าว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"客人们以香槟为新娘新郎敬酒。","pinyin":"Kè rén mén yǐ xiāng bīn wéi xīn niáng xīn láng jìng jiǔ。","meaning":"Guests toasted the bride and groom with champagne.","meaningThai":"แขกรับเชิญฉลองให้กับเจ้าสาวและเจ้าบ่าวด้วยแชมเปญ"},{"chinese":"我提议为新郎新娘的幸福干杯！","pinyin":"Wǒ tí yì wéi xīn láng xīn niáng de xìng fú gān bēi！","meaning":"I'd like to propose a toast to the bride and groom.","meaningThai":"ฉันอยากจะเสนออวยพรให้เจ้าสาวและเจ้าบ่าว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1289","chinese":"心理","pinyin":"xīnlǐ","meaning":"psychology; mentality","meaningThai":"จิตวิทยา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"缺乏信心是阻碍成功的心理因素。","pinyin":"Quē fá xìn xīn shì zǔ ài chéng gōng de xīn lǐ yīn sù。","meaning":"Lack of confidence is a psychological barrier to success.","meaningThai":"การขาดความมั่นใจเป็นอุปสรรคทางจิตวิทยาต่อความสำเร็จ"},{"chinese":"这是个心理而不是生理问题。","pinyin":"Zhè shì gè xīn lǐ ér bù shì shēng lǐ wèn tí。","meaning":"The problem was psychological rather than physiological.","meaningThai":"ปัญหาคือทางจิตวิทยามากกว่าทางสรีรวิทยา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1290","chinese":"新娘","pinyin":"xīnniáng","meaning":"bride","meaningThai":"เจ้าสาว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"客人们以香槟为新娘新郎敬酒。","pinyin":"Kè rén mén yǐ xiāng bīn wéi xīn niáng xīn láng jìng jiǔ。","meaning":"Guests toasted the bride and groom with champagne.","meaningThai":"แขกรับเชิญฉลองให้กับเจ้าสาวและเจ้าบ่าวด้วยแชมเปญ"},{"chinese":"我提议为新郎新娘的幸福干杯！","pinyin":"Wǒ tí yì wéi xīn láng xīn niáng de xìng fú gān bēi！","meaning":"I'd like to propose a toast to the bride and groom.","meaningThai":"ฉันอยากจะเสนออวยพรให้เจ้าสาวและเจ้าบ่าว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1291","chinese":"信任","pinyin":"xìnrèn","meaning":"to trust; to have confidence in","meaningThai":"เชื่อมั่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"信任这样的人将是愚蠢至极。","pinyin":"Xìn rèn zhè yàng de rén jiāng shì yú chǔn zhì jí。","meaning":"It would be sheer madness to trust a man like that.","meaningThai":"คงจะบ้าไปแล้วถ้าเชื่อใจผู้ชายแบบนั้น"},{"chinese":"我们能够信任他到什么程度？","pinyin":"Wǒ mén néng gòu xìn rèn tā dào shí mó chéng dù？","meaning":"How far can we trust him?","meaningThai":"เราจะเชื่อใจเขาได้แค่ไหน?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1292","chinese":"新人","pinyin":"xīnrén","meaning":"newcomer; fresh talent; newlywed, esp. new bride; bride and groom; (paleoanthropology) Homo sapiens","meaningThai":"ผู้มาใหม่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她对于公司来说并非是新人。","pinyin":"Tā duì yú gōng sī lái shuō bìng fēi shì xīn rén。","meaning":"She wasn't new to the company.","meaningThai":"เธอไม่ใช่คนใหม่กับบริษัท"},{"chinese":"时装界出现了一位新人。","pinyin":"Shí zhuāng jiè chū xiàn le yī wèi xīn rén。","meaning":"A newcomer has appeared on the fashion scene.","meaningThai":"ผู้มาใหม่ปรากฏตัวในวงการแฟชั่น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1293","chinese":"欣赏","pinyin":"xīnshǎng","meaning":"to appreciate; to enjoy; to admire","meaningThai":"ชื่นชม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"欣赏风景。","pinyin":"Xin shang feng jing.","meaning":"Enjoy the scenery.","meaningThai":"เพลิดเพลินไปกับทัศนียภาพ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1294","chinese":"心态","pinyin":"xīntài","meaning":"attitude (of the heart); state of one's psyche; way of thinking; mentality","meaningThai":"ความคิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我想让你进入一种全新的心态。","pinyin":"Wǒ xiǎng ràng nǐ jìn rù yī zhǒng quán xīn de xīn tài。","meaning":"I want you to get into a whole new state of mind.","meaningThai":"ฉันอยากให้คุณเข้าสู่สภาวะใหม่ของจิตใจ"},{"chinese":"他的主张与国民的心态相吻合。","pinyin":"Tā de zhǔ zhāng yǔ guó mín de xīn tài xiāng wěn hé。","meaning":"His opinions chimed in with the mood of the nation.","meaningThai":"ความคิดเห็นของเขาสอดคล้องกับอารมณ์ของชาติ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1295","chinese":"新型","pinyin":"xīnxíng","meaning":"new type; new kind","meaningThai":"ชนิดใหม่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"公众对新型列车的安全深感忧虑。","pinyin":"Gōng zhòng duì xīn xíng liè chē de ān quán shēn gǎn yōu lǜ。","meaning":"There is considerable public disquiet about the safety of the new trains.","meaningThai":"ประชาชนมีความไม่สบายใจอย่างมากเกี่ยวกับความปลอดภัยของรถไฟขบวนใหม่"},{"chinese":"有人要求采用新型的安保措施。","pinyin":"Yǒu rén yào qiú cǎi yòng xīn xíng de ān bǎo cuò shī。","meaning":"There have been calls for a new kind of security arrange we are pirates, these data are stolen from youdao .","meaningThai":"มีการเรียกร้องให้มีมาตรการรักษาความปลอดภัยใหม่"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1296","chinese":"信用","pinyin":"xìnyòng","meaning":"trustworthiness; (commerce) credit; (literary) to trust and appoint","meaningThai":"เครดิต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们用信用卡账户支付电话费。","pinyin":"Tā mén yòng xìn yòng kǎ zhàng hù zhī fù diàn huà fèi。","meaning":"They charge the calls to their credit-card account.","meaningThai":"พวกเขาเรียกเก็บเงินค่าโทรเข้าบัญชีบัตรเครดิต"},{"chinese":"他们可以为了方便而使用信用卡。","pinyin":"Tā mén kě yǐ wéi le fāng biàn ér shǐ yòng xìn yòng kǎ。","meaning":"They may use a credit card for convenience.","meaningThai":"พวกเขาอาจใช้บัตรเครดิตเพื่อความสะดวก"}],"partOfSpeech":["noun","adjective"]},
  {"id":"hsk5-1297","chinese":"吸收","pinyin":"xīshōu","meaning":"to absorb; to assimilate; to ingest; to recruit","meaningThai":"ดูดซับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"平流層的臭氧會吸收紫外線。","pinyin":"Píng liú céng de chòu yǎng huì xī shōu zǐ wài xiàn。","meaning":"The ozone in the stratosphere absorbs ultraviolet radiation.","meaningThai":"โอโซนในชั้นสตราโตสเฟียร์ดูดซับรังสีอัลตราไวโอเลต"},{"chinese":"树木排出氧气，吸收二氧化碳。","pinyin":"Shù mù pái chū yǎng qì， xī shōu èr yǎng huà tàn。","meaning":"Trees give off oxygen and absorb carbon dioxide.","meaningThai":"ต้นไม้ปล่อยออกซิเจนและดูดซับคาร์บอนไดออกไซด์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1298","chinese":"系统","pinyin":"xìtǒng","meaning":"system","meaningThai":"ระบบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"系统是线性的吗？","pinyin":"Xì tǒng shì xiàn xìng de ma？","meaning":"Is the system linear?","meaningThai":"ระบบเป็นแบบเชิงเส้นหรือไม่?"},{"chinese":"系统运行起来了。","pinyin":"Xì tǒng yùn háng qǐ lái le。","meaning":"The system worked.","meaningThai":"ระบบทำงานได้"}],"partOfSpeech":["noun","adjective"]},
  {"id":"hsk5-1299","chinese":"修改","pinyin":"xiūgǎi","meaning":"to amend; to alter; to modify","meaningThai":"ปรับปรุงใหม่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他同意我们提出的全部修改方案。","pinyin":"Tā tóng yì wǒ mén tí chū de quán bù xiū gǎi fāng àn。","meaning":"He accepted all the changes we proposed.","meaningThai":"เขายอมรับการเปลี่ยนแปลงทั้งหมดที่เราเสนอ"},{"chinese":"他们不断要求修改这项法律。","pinyin":"Tā mén bù duàn yào qiú xiū gǎi zhè xiàng fǎ lǜ。","meaning":"They continued to press for a change in the law.","meaningThai":"พวกเขายังคงกดดันให้มีการเปลี่ยนแปลงกฎหมายต่อไป"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1300","chinese":"修建","pinyin":"xiūjiàn","meaning":"to build; to construct","meaningThai":"สร้าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"为方便残疾人的出入修建了坡道。","pinyin":"Wéi fāng biàn cán jí rén de chū rù xiū jiàn le pō dào。","meaning":"Ramps have been built to ease access for the disabled.","meaningThai":"ทางลาดถูกสร้างขึ้นเพื่อความสะดวกในการเข้าถึงสำหรับผู้พิการ"},{"chinese":"城墙是为防御敌人袭击而修建的。","pinyin":"Chéng qiáng shì wéi fáng yù dí rén xí jī ér xiū jiàn de。","meaning":"The town walls were built as a defence against enemy attacks.","meaningThai":"กำแพงเมืองถูกสร้างขึ้นเพื่อป้องกันการโจมตีของศัตรู"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1301","chinese":"休闲","pinyin":"xiūxián","meaning":"leisure; relaxation; not working; idle; to enjoy leisure; to lie fallow","meaningThai":"เวลาว่าง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"科伯，威廉1731－1800英国诗人，被认为是浪漫主义的先锋。他的最杰出的作品任务赞美了农村生活和休闲","pinyin":"Kē bó， wēi lián 1731－1800 yīng guó shī rén， bèi rèn wéi shì làng màn zhǔ yì de xiān fēng。 tā de zuì jié chū de zuò pǐn rèn wù zàn měi le nóng cūn shēng huó hé xiū xián","meaning":"British poet considered a precursor of romanticism. His best-known work, The Task(1785), praises rural life and leisure.","meaningThai":"กวีชาวอังกฤษถือว่าเป็นสารตั้งต้นของความโรแมนติกผลงานที่เป็นที่รู้จักกันดีที่สุดของเขา The Task (1785) ยกย่องชีวิตในชนบทและการพักผ่อนหย่อนใจ"},{"chinese":"对休闲有明显作用的另一产业是娱乐。","pinyin":"Duì xiū xián yǒu míng xiǎn zuò yòng de lìng yī chǎn yè shì yú lè。","meaning":"Another industry obviously devoted to leisure is entertainment.","meaningThai":"อีกหนึ่งอุตสาหกรรมที่อุทิศให้กับการพักผ่อนอย่างเห็นได้ชัดคือความบันเทิง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1302","chinese":"西装","pinyin":"xīzhuāng","meaning":"suit; Western-style clothes","meaningThai":"สูท","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"一套半价西装仍然花了$400。","pinyin":"Yī tào bàn jià xī zhuāng réng rán huā le$400。","meaning":"A half-price suit still cost $400.","meaningThai":"ชุดสูทครึ่งราคายังคงมีราคา 400 ดอลลาร์"},{"chinese":"把你的西装小心装好以免弄皱。","pinyin":"Bǎ nǐ de xī zhuāng xiǎo xīn zhuāng hǎo yǐ miǎn nòng zhòu。","meaning":"Pack your suit carefully so that you don't crease it.","meaningThai":"แพ็คสูทของคุณอย่างระมัดระวังเพื่อไม่ให้มันยับ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1303","chinese":"需","pinyin":"xū","meaning":"to require; to need; to want; necessity; need","meaningThai":"ความต้องการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"政府需对此工程投入更多的资金。","pinyin":"Zhèng fǔ xū duì cǐ gōng chéng tóu rù gēng duō de zī jīn。","meaning":"More government money needs to go into the project.","meaningThai":"จำเป็นต้องมีเงินของรัฐบาลมากขึ้นเพื่อเข้าสู่โครงการ"},{"chinese":"驾车者被告知需另寻其他路线。","pinyin":"Jià chē zhě bèi gào zhī xū lìng xún qí tā lù xiàn。","meaning":"Drivers are advised to seek alternative routes.","meaningThai":"ผู้ขับขี่ควรมองหาเส้นทางอื่น"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-1304","chinese":"宣布","pinyin":"xuānbù","meaning":"to declare; to announce; to proclaim","meaningThai":"ประกาศ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"选举结果仍未正式宣布。","pinyin":"Xuǎn jǔ jié guǒ réng wèi zhèng shì xuān bù。","meaning":"The election results have still not been officially announced.","meaningThai":"ผลการเลือกตั้งยังไม่มีการประกาศอย่างเป็นทางการ"},{"chinese":"公告宣布后，股市大跌。","pinyin":"Gōng gào xuān bù hòu， gǔ shì dà diē。","meaning":"Following the announcement, share prices went into a tailspin.","meaningThai":"หลังการประกาศ ราคาหุ้นก็เข้าสู่ภาวะพลิกผัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1305","chinese":"宣传","pinyin":"xuānchuán","meaning":"to disseminate; to give publicity to; propaganda","meaningThai":"การประชาสัมพันธ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"就此达成的协议无疑会被广泛宣传。","pinyin":"Jiù cǐ dá chéng de xié yì wú yí huì bèi guǎng fàn xuān chuán。","meaning":"The contract for this will no doubt be widely advertised.","meaningThai":"สัญญานี้จะได้รับการโฆษณาอย่างกว้างขวางอย่างไม่ต้องสงสัย"},{"chinese":"他不反对宣传，只要是正当的。","pinyin":"Tā bù fǎn duì xuān chuán， zhī yào shì zhèng dāng de。","meaning":"He's not averse to publicity, of the right kind.","meaningThai":"เขาไม่รังเกียจที่จะประชาสัมพันธ์ ในลักษณะที่ถูกต้อง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1306","chinese":"选手","pinyin":"xuǎnshǒu","meaning":"athlete; contestant","meaningThai":"ผู้เล่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"200多名选手参加了赛跑。","pinyin":"200 duō míng xuǎn shǒu cān jiā le sài pǎo。","meaning":"Over 200 competitors entered the race.","meaningThai":"มีผู้เข้าแข่งขันกว่า 200 คน"},{"chinese":"她几乎能与所有选手相匹敌。","pinyin":"Tā jī hū néng yǔ suǒ yǒu xuǎn shǒu xiāng pǐ dí。","meaning":"She can hold her own against almost any player.","meaningThai":"เธอสามารถสู้กับผู้เล่นเกือบทุกคนได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1307","chinese":"学分","pinyin":"xuéfēn","meaning":"course credit","meaningThai":"หน่วยกิต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"毕业需要修满一定学分。","pinyin":"Bì yè xū yào xiū mǎn yī dìng xué fēn.","meaning":"Graduation requires completing sufficient credits.","meaningThai":"การสำเร็จการศึกษาต้องมีหน่วยกิตเพียงพอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1308","chinese":"雪糕","pinyin":"xuěgāo","meaning":"ice cream","meaningThai":"ไอศครีม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"保持无核葡萄在冰箱而不是冰棍和雪糕。","pinyin":"Bǎo chí wú hé pú táo zài bīng xiāng ér bù shì bīng gùn hé xuě gāo。","meaning":"Keep seedless grapes in the freezer instead of popsicles and ice cream bars.","meaningThai":"เก็บองุ่นไร้เมล็ดไว้ในช่องแช่แข็งแทนไอศกรีมแท่งและไอศกรีมแท่ง"},{"chinese":"这是吃冰激凌或者雪糕的好时间。","pinyin":"Zhè shì chī bīng jī líng huò zhě xuě gāo de hǎo shí jiān。","meaning":"It is time for an Ice or an Ice-Cream.","meaningThai":"ถึงเวลาสำหรับน้ำแข็งหรือไอศกรีม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1309","chinese":"学科","pinyin":"xuékē","meaning":"subject; branch of learning; course; academic discipline","meaningThai":"การลงโทษ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们正在寻找各类学科的人才。","pinyin":"Wǒ mén zhèng zài xún zhǎo gè lèi xué kē de rén cái。","meaning":"We're looking for people from a wide range of disciplines.","meaningThai":"เรากำลังมองหาผู้คนจากหลากหลายสาขาวิชา"},{"chinese":"学校正在拓宽授课学科的范围。","pinyin":"Xué xiào zhèng zài tuò kuān shòu kè xué kē de fàn wéi。","meaning":"The school is extending the range of subjects taught.","meaningThai":"โรงเรียนกำลังขยายขอบเขตวิชาที่สอน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1310","chinese":"学历","pinyin":"xuélì","meaning":"educational background; academic qualifications","meaningThai":"วุฒิการศึกษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"提高学历。","pinyin":"Ti gao xue li.","meaning":"Improve education level.","meaningThai":"ปรับปรุงระดับการศึกษา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1311","chinese":"学年","pinyin":"xuénián","meaning":"academic year","meaningThai":"ปีการศึกษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"学生在最后一学年可以自由选修课程。","pinyin":"Xué shēng zài zuì hòu yī xué nián kě yǐ zì yóu xuǎn xiū kè chéng。","meaning":"Students have a free choice of courses in their final year.","meaningThai":"นักศึกษามีทางเลือกหลักสูตรฟรีในปีสุดท้าย"},{"chinese":"学生于十月返校，开始新学年的学习。","pinyin":"Xué shēng yú shí yuè fǎn xiào， kāi shǐ xīn xué nián de xué xí。","meaning":"The students return in October for the start of the new academic year.","meaningThai":"นักเรียนกลับมาในเดือนตุลาคมเพื่อเริ่มต้นปีการศึกษาใหม่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1312","chinese":"学术","pinyin":"xuéshù","meaning":"learning; science; academic","meaningThai":"วิชาการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他在学术方面很有成就。","pinyin":"Tā zài xué shù fāng miàn hěn yǒu chéng jiù.","meaning":"He has great achievements in academia.","meaningThai":"เขามีความสำเร็จอย่างมากในด้านวิชาการ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1313","chinese":"学者","pinyin":"xuézhě","meaning":"scholar","meaningThai":"นักวิชาการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"正是这个传奇故事误导了学者们。","pinyin":"Zhèng shì zhè gè chuán qí gù shì wù dǎo le xué zhě mén。","meaning":"It's this legend which has misled scholars.","meaningThai":"นี่คือตำนานที่ทำให้นักวิชาการเข้าใจผิด"},{"chinese":"这是全国学者都极为重视的话题。","pinyin":"Zhè shì quán guó xué zhě dū jí wéi zhòng shì de huà tí。","meaning":"This is a subject very dear to the hearts of academics up and down the country.","meaningThai":"นี่เป็นวิชาที่เป็นที่รักของนักวิชาการทั้งในประเทศและต่างประเทศ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1314","chinese":"训练","pinyin":"xùnliàn","meaning":"to train; to drill; training","meaningThai":"รถไฟ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们正在为大赛进行训练。","pinyin":"Tā mén zhèng zài wéi dà sài jìn háng xùn liàn。","meaning":"They're in training for the big game.","meaningThai":"พวกเขากำลังฝึกซ้อมสำหรับเกมสำคัญ"},{"chinese":"士兵接受徒手格斗训练。","pinyin":"Shì bīng jiē shòu tú shǒu gé dǒu xùn liàn。","meaning":"The soldiers were trained in unarmed combat.","meaningThai":"ทหารได้รับการฝึกฝนในการรบโดยไม่ต้องใช้อาวุธ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1315","chinese":"迅速","pinyin":"xùnsù","meaning":"rapid; speedy; fast","meaningThai":"เร็ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"犯罪数字正在迅速上升。","pinyin":"Fàn zuì shù zì zhèng zài xùn sù shàng shēng。","meaning":"Crime figures are rising rapidly.","meaningThai":"ตัวเลขอาชญากรรมเพิ่มขึ้นอย่างรวดเร็ว"},{"chinese":"地价正在迅速上涨。","pinyin":"Dì jià zhèng zài xùn sù shàng zhǎng。","meaning":"The price of land is rising rapidly.","meaningThai":"ราคาที่ดินเพิ่มขึ้นอย่างรวดเร็ว"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1316","chinese":"询问","pinyin":"xúnwèn","meaning":"to inquire","meaningThai":"ถาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"特此致函询问有关语言课程事宜。","pinyin":"Tè cǐ zhì hán xún wèn yǒu guān yǔ yán kè chéng shì yí。","meaning":"I'm writing to enquire about language courses.","meaningThai":"ฉันเขียนมาเพื่อสอบถามเกี่ยวกับหลักสูตรภาษา"},{"chinese":"我以询问在美国有多少日托中心开始。","pinyin":"Wǒ yǐ xún wèn zài měi guó yǒu duō shǎo rì tuō zhōng xīn kāi shǐ。","meaning":"I started by asking how many day-care centres were located in the United States.","meaningThai":"ฉันเริ่มด้วยการถามว่าศูนย์รับเลี้ยงเด็กตั้งอยู่ในสหรัฐอเมริกากี่แห่ง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1317","chinese":"寻找","pinyin":"xúnzhǎo","meaning":"to seek; to look for","meaningThai":"กำลังมองหา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他浏览文章寻找自己的名字。","pinyin":"Tā liú lǎn wén zhāng xún zhǎo zì jǐ de míng zì。","meaning":"He skimmed through the article trying to find his name.","meaningThai":"เขาอ่านบทความโดยพยายามค้นหาชื่อของเขา"},{"chinese":"我跑遍商店寻找可穿的东西。","pinyin":"Wǒ pǎo biàn shāng diàn xún zhǎo kě chuān de dōng xī。","meaning":"I combed the shops looking for something to wear.","meaningThai":"ฉันเดินไปตามร้านต่างๆ เพื่อหาของใส่"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1318","chinese":"需求","pinyin":"xūqiú","meaning":"requirement; to require; (economics) demand","meaningThai":"ความต้องการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"课堂教师必须理解孩子的需求。","pinyin":"Kè táng jiào shī bì xū lǐ jiě hái zǐ de xū qiú。","meaning":"The classroom teacher must be sensitive to a child's needs.","meaningThai":"ครูประจำชั้นจะต้องไวต่อความต้องการของเด็ก"},{"chinese":"那是对该产品需求最旺的时期。","pinyin":"Nà shì duì gāi chǎn pǐn xū qiú zuì wàng de shí qī。","meaning":"It was a time of peak demand for the product.","meaningThai":"เป็นช่วงที่มีความต้องการสินค้าสูงสุด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1319","chinese":"虚心","pinyin":"xūxīn","meaning":"open-minded; humble","meaningThai":"อ่อนน้อม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"虚心学习。","pinyin":"Xu xin xue xi.","meaning":"Learn with an open mind.","meaningThai":"เรียนรู้ด้วยใจที่เปิดกว้าง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1320","chinese":"呀","pinyin":"yā","meaning":"(particle equivalent to 啊 after a vowel, expressing surprise or doubt)","meaningThai":"อา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“多可爱呀，”她低声说。","pinyin":"“ duō kě ài yā，” tā dī shēng shuō。","meaning":"\"How lovely,\" she murmured.","meaningThai":"“น่ารักจังเลย” เธอพึมพำ"},{"chinese":"“真开心呀！”她笑着说。","pinyin":"“ zhēn kāi xīn yā！” tā xiào zháo shuō。","meaning":"'What fun!' she said with a laugh.","meaningThai":"'สนุกจริงๆ!' เธอพูดพร้อมกับหัวเราะ"}],"partOfSpeech":["particle"]},
  {"id":"hsk5-1321","chinese":"牙齿","pinyin":"yáchǐ","meaning":"tooth; dental","meaningThai":"ฟัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"每天刷牙保护牙齿。","pinyin":"Měi tiān shuā yá bǎo hù yá chǐ.","meaning":"Brush your teeth every day to protect them.","meaningThai":"แปรงฟันทุกวันเพื่อป้องกัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1322","chinese":"押金","pinyin":"yājīn","meaning":"deposit; down payment","meaningThai":"เงินฝาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你必须付三个月的房租作为押金。","pinyin":"Nǐ bì xū fù sān gè yuè de fáng zū zuò wéi yā jīn。","meaning":"You have to give three months' rent as a deposit.","meaningThai":"คุณต้องให้ค่าเช่าสามเดือนเป็นเงินมัดจำ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1323","chinese":"沿","pinyin":"yán","meaning":"along; to follow (a line, tradition etc); to carry on; to trim (a border with braid, tape etc); border; edge","meaningThai":"ตาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们沿运河测量了水深。","pinyin":"Tā mén yán yùn hé cè liáng le shuǐ shēn。","meaning":"They took soundings along the canal.","meaningThai":"พวกเขาเอาเสียงไปตามคลอง"},{"chinese":"我们开始沿小路追赶。","pinyin":"Wǒ mén kāi shǐ yán xiǎo lù zhuī gǎn。","meaning":"We gave chase along the footpath.","meaningThai":"เราไล่ตามทางเท้า"}],"partOfSpeech":["preposition","other","verb"]},
  {"id":"hsk5-1324","chinese":"眼","pinyin":"yǎn","meaning":"eye; small hole; crux (of a matter); classifier for big hollow things (wells, stoves, pots etc)","meaningThai":"ดวงตา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"乔治对他伴侣的私通睁一只眼闭一只眼。","pinyin":"Qiáo zhì duì tā bàn lǚ de sī tōng zhēng yī zhī yǎn bì yī zhī yǎn。","meaning":"George turned a blind eye to his partner's infidelities.","meaningThai":"จอร์จเมินเฉยต่อการนอกใจของคู่หูของเขา"},{"chinese":"她兴奋得两眼放光。","pinyin":"Tā xīng fèn dé liǎng yǎn fàng guāng。","meaning":"Her eyes were shining with excitement.","meaningThai":"ดวงตาของเธอเปล่งประกายด้วยความตื่นเต้น"}],"partOfSpeech":["noun","measure word"]},
  {"id":"hsk5-1325","chinese":"延长","pinyin":"yáncháng","meaning":"Yanchang county in Yan'an 安, Shaanxi","meaningThai":"ขยาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"行程已经延长以包括其他几项活动。","pinyin":"Háng chéng yǐ jīng yán cháng yǐ bāo kuò qí tā jī xiàng huó dòng。","meaning":"The trip has been extended to include a few other events.","meaningThai":"การเดินทางได้รับการขยายออกไปเพื่อรวมกิจกรรมอื่นๆ สองสามรายการ"},{"chinese":"猪肉经过化学处理以延长保存期。","pinyin":"Zhū ròu jīng guò huà xué chǔ lǐ yǐ yán cháng bǎo cún qī。","meaning":"The meat is chemically treated to extend shelf life.","meaningThai":"เนื้อได้รับการบำบัดด้วยสารเคมีเพื่อยืดอายุการเก็บ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1326","chinese":"研发","pinyin":"yánfā","meaning":"research and development; to develop","meaningThai":"การวิจัยและพัฒนา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们缺少进一步研发这些技术设备的科技人员。","pinyin":"Tā mén quē shǎo jìn yī bù yán fā zhè xiē jì shù shè bèi de kē jì rén yuán。","meaning":"They lacked the scientific personnel to develop the technical apparatus much further.","meaningThai":"พวกเขายังขาดบุคลากรทางวิทยาศาสตร์ที่จะพัฒนาเครื่องมือทางเทคนิคต่อไปอีกมาก"},{"chinese":"奥尔教授已经研发出了用现有的实验室激光给化学分子贴标签的有趣方法。","pinyin":"Ào ěr jiào shòu yǐ jīng yán fā chū le yòng xiàn yǒu de shí yàn shì jī guāng gěi huà xué fēn zǐ tiē biāo qiān de yǒu qù fāng fǎ。","meaning":"Professor Orr has developed interesting ways of tagging chemical molecules using existing laboratory lasers.","meaningThai":"ศาสตราจารย์ออร์ได้พัฒนาวิธีการที่น่าสนใจในการติดแท็กโมเลกุลเคมีโดยใช้เลเซอร์ในห้องปฏิบัติการที่มีอยู่"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1327","chinese":"样式","pinyin":"yàngshì","meaning":"type; style","meaningThai":"สไตล์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"样式有条纹的和格子的。","pinyin":"Yàng shì yǒu tiáo wén de hé gé zǐ de。","meaning":"Styles include stripes and checks.","meaningThai":"สไตล์มีทั้งลายทางและลายตาราง"},{"chinese":"这种汽车的基本设计与早期的样式非常相似。","pinyin":"Zhè zhǒng qì chē de jī běn shè jì yǔ zǎo qī de yàng shì fēi cháng xiāng sì。","meaning":"The basic design of the car is very similar to that of earlier models.","meaningThai":"การออกแบบพื้นฐานของรถมีความคล้ายคลึงกับรุ่นก่อนๆ มาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1328","chinese":"阳台","pinyin":"yángtái","meaning":"variant of 阳台","meaningThai":"ระเบียง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"学校不给开空调，学生们就会从阳台上扔热水瓶抗议。","pinyin":"Xué xiào bù gěi kāi kōng tiáo， xué shēng mén jiù huì cóng yáng tái shàng rēng rè shuǐ píng kàng yì。","meaning":"The school won't turn on the air conditioning, so the students are going to throw their hot water flasks off of the balcony in protest.","meaningThai":"โรงเรียนไม่เปิดเครื่องปรับอากาศ นักเรียนจึงโยนกระติกน้ำร้อนออกจากระเบียงเพื่อประท้วง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1329","chinese":"演讲","pinyin":"yǎnjiǎng","meaning":"lecture; to make a speech","meaningThai":"บรรยาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的演讲很精彩。","pinyin":"Tā de yǎn jiǎng hěn jīng cǎi.","meaning":"His speech was wonderful.","meaningThai":"คำพูดของเขายอดเยี่ยมมาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1330","chinese":"眼泪","pinyin":"yǎnlèi","meaning":"tears; crying","meaningThai":"น้ำตา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她紧闭双眼，却无法忍住眼泪。","pinyin":"Tā jǐn bì shuāng yǎn， què wú fǎ rěn zhù yǎn lèi。","meaning":"She closed her eyes tightly in a vain attempt to hold back the tears.","meaningThai":"เธอหลับตาลงแน่นเพื่อพยายามกลั้นน้ำตาอย่างไร้ผล"},{"chinese":"她轻轻拭去他的眼泪。","pinyin":"Tā qīng qīng shì qù tā de yǎn lèi。","meaning":"She stroked away his tears.","meaningThai":"เธอปาดน้ำตาของเขาออก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1331","chinese":"严肃","pinyin":"yánsù","meaning":"solemn; grave; serious; earnest; severe","meaningThai":"จริงจัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"严肃点儿，这件事很重要。","pinyin":"Yán sù diǎn ér， zhè jiàn shì hěn zhòng yào。","meaning":"Be serious for a mo we are pirates, these data are stolen from youdao ; this is important.","meaningThai":"อย่างจริงจังนี่เป็นสิ่งสำคัญ"},{"chinese":"她的表情显得严肃起来。","pinyin":"Tā de biǎo qíng xiǎn dé yán sù qǐ lái。","meaning":"Her expression grew solemn.","meaningThai":"สีหน้าของเธอดูเคร่งขรึม"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1332","chinese":"研制","pinyin":"yánzhì","meaning":"to research and manufacture; to research and to develop","meaningThai":"พัฒนา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他不喜欢吹嘘他研制的东西。","pinyin":"Tā bù xǐ huān chuī xū tā yán zhì de dōng xī。","meaning":"He doesn't like to be a blowhard about what he's developed.","meaningThai":"เขาไม่ชอบที่จะพูดเกินจริงเกี่ยวกับสิ่งที่เขาพัฒนาขึ้น"},{"chinese":"这种产品仍处于研制阶段。","pinyin":"Zhè zhǒng chǎn pǐn réng chǔ yú yán zhì jiē duàn。","meaning":"The product is still at a developmental stage.","meaningThai":"ผลิตภัณฑ์ยังอยู่ในขั้นตอนการพัฒนา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1333","chinese":"摇","pinyin":"yáo","meaning":"surname Yao","meaningThai":"เขย่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她头一摇，头发就散开了。","pinyin":"Tā tóu yī yáo， tóu fā jiù sàn kāi le。","meaning":"She shook her hair loose.","meaningThai":"เธอสะบัดผมของเธอหลวมๆ"},{"chinese":"她在座位上前摇后晃。","pinyin":"Tā zài zuò wèi shàng qián yáo hòu huǎng。","meaning":"She was rocking backwards and forwards in her seat.","meaningThai":"เธอโยกไปข้างหลังและข้างหน้าในที่นั่งของเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1334","chinese":"咬","pinyin":"yǎo","meaning":"to bite; to nip","meaningThai":"กัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那条狗又咬又叫，摇着尾巴。","pinyin":"Nà tiáo gǒu yòu yǎo yòu jiào， yáo zháo wěi bā。","meaning":"The dog was biting, growling, and wagging its tail.","meaningThai":"สุนัขกัดคำรามและกระดิกหาง"},{"chinese":"她挠了挠胳膊上虫咬的包。","pinyin":"Tā náo le náo gē bó shàng chóng yǎo de bāo。","meaning":"She scratched at the insect bites on her arm.","meaningThai":"เธอเกาแมลงกัดบนแขนของเธอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1335","chinese":"腰","pinyin":"yāo","meaning":"waist; lower back; pocket; middle; loins","meaningThai":"เอว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"里基搂着她的腰。","pinyin":"Lǐ jī lǒu zháo tā de yāo。","meaning":"Ricky kept his arm around her waist.","meaningThai":"ริกกี้เอาแขนของเขาโอบรอบเอวของเธอ"},{"chinese":"他搂住了她的腰。","pinyin":"Tā lǒu zhù le tā de yāo。","meaning":"He put his arm around her waist.","meaningThai":"เขาโอบแขนรอบเอวของเธอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1336","chinese":"要不（然）","pinyin":"yàobù(rán)","meaning":"otherwise)","meaningThai":"มิฉะนั้น)","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"只要不断朝前走，自然而然就会登上顶峰。","pinyin":"Zhī yào bù duàn zhāo qián zǒu， zì rán ér rán jiù huì dēng shàng dǐng fēng。","meaning":"If I continue to do that, I'll automatically rise to the top.","meaningThai":"หากฉันยังคงทำอย่างนั้น ฉันจะขึ้นไปด้านบนโดยอัตโนมัติ"},{"chinese":"这些观众一定错过了他们的音乐演出， 要不 然他们会高度赞扬这个演出的。","pinyin":"Zhè xiē guān zhòng yī dìng cuò guò le tā mén de yīn lè yǎn chū，  yào bù   rán tā mén huì gāo dù zàn yáng zhè gè yǎn chū de。","meaning":"The audience must have missed their musical performance, or they would have spoken highly of it.","meaningThai":"ผู้ฟังคงพลาดการแสดงดนตรีของตน ไม่เช่นนั้นพวกเขาจะชื่นชมการแสดงดนตรีนี้"}],"partOfSpeech":["conjunction"]},
  {"id":"hsk5-1337","chinese":"要不是","pinyin":"yàobúshì","meaning":"if it were not for; but for","meaningThai":"ถ้าไม่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他要不是膝部有伤的话，就上场了。","pinyin":"Tā yào bù shì xī bù yǒu shāng de huà， jiù shàng cháng le。","meaning":"He would have played but for a knee injury.","meaningThai":"เขาจะเล่นได้แต่เพราะอาการบาดเจ็บที่เข่า"},{"chinese":"要不是邻居介入，她可能会没命了。","pinyin":"Yào bù shì lín jū jiè rù， tā kě néng huì méi mìng le。","meaning":"She might have been killed if the neighbours hadn't intervened.","meaningThai":"เธออาจถูกฆ่าตายถ้าเพื่อนบ้านไม่เข้ามาแทรกแซง"}],"partOfSpeech":["conjunction"]},
  {"id":"hsk5-1338","chinese":"药品","pinyin":"yàopǐn","meaning":"medicaments; medicine; drug","meaningThai":"ยา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种药品以维乐命商标销售。","pinyin":"Zhè zhǒng yào pǐn yǐ wéi lè mìng shāng biāo xiāo shòu。","meaning":"The drug is marketed under the brand name Viramune.","meaningThai":"ยานี้วางตลาดภายใต้ชื่อแบรนด์ Viramune"},{"chinese":"医院甚至缺乏外科手术的基本必需的药品。","pinyin":"Yī yuàn shèn zhì quē fá wài kē shǒu shù de jī běn bì xū de yào pǐn。","meaning":"Hospitals lack even basic drugs for surgical operations.","meaningThai":"โรงพยาบาลยังขาดแม้แต่ยาพื้นฐานสำหรับการผ่าตัด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1339","chinese":"药物","pinyin":"yàowù","meaning":"medicaments; pharmaceuticals; medication; medicine; drug","meaningThai":"ยา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些药物阻止孕酮发挥作用。","pinyin":"Zhè xiē yào wù zǔ zhǐ yùn tóng fā huī zuò yòng。","meaning":"The drugs block the action of progesterone.","meaningThai":"ยาเสพติดขัดขวางการกระทำของฮอร์โมนโปรเจสเตอโรน"},{"chinese":"他病得很重，需要药物治疗。","pinyin":"Tā bìng dé hěn zhòng， xū yào yào wù zhì liáo。","meaning":"He's very sick. He needs medication.","meaningThai":"เขาป่วยมาก เขาต้องการยา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1340","chinese":"压岁钱","pinyin":"yāsuìqián","meaning":"money given to children as a gift on Chinese New Year's Eve","meaningThai":"เงินปีใหม่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"孩子们会得到压岁钱。","pinyin":"Hái zǐ mén huì dé dào yā suì qián。","meaning":"Kids are given lucky money.","meaningThai":"เด็ก ๆ จะได้รับเงินโชคดี"},{"chinese":"许多青少年把他们的零花钱和压岁钱捐出去了。","pinyin":"Xǔ duō qīng shǎo nián bǎ tā mén de líng huā qián hé yā suì qián juān chū qù le。","meaning":"Many teenagers gave away their pocket money and lucky money.","meaningThai":"วัยรุ่นหลายคนแจกเงินค่าขนมและเงินนำโชค"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1341","chinese":"鸭子","pinyin":"yāzi","meaning":"duck; male prostitute (slang)","meaningThai":"เป็ด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"此时，猫就在可攻击鸭子的距离内。","pinyin":"Cǐ shí， māo jiù zài kě gōng jī yā zǐ de jù lí nèi。","meaning":"The cat was now within striking distance of the duck.","meaningThai":"ขณะนี้แมวอยู่ในระยะที่สามารถโจมตีเป็ดได้"},{"chinese":"有鸭子在草坪上发出嘎嘎的叫着。","pinyin":"Yǒu yā zǐ zài cǎo píng shàng fā chū gā gā de jiào zháo。","meaning":"There were ducks quacking on the lawn.","meaningThai":"มีเป็ดกำลังร้องอยู่บนสนามหญ้า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1342","chinese":"夜间","pinyin":"yèjiān","meaning":"nighttime; evening or night (e.g. classes)","meaningThai":"ในเวลากลางคืน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"蛞蝓和蜗牛夜间进食。","pinyin":"Kuò yú hé wō niú yè jiān jìn shí。","meaning":"Slugs and snails feed at night.","meaningThai":"ทากและหอยทากหากินในเวลากลางคืน"},{"chinese":"夜间突然发生了火灾。","pinyin":"Yè jiān tū rán fā shēng le huǒ zāi。","meaning":"Fire broke out during the night.","meaningThai":"เกิดเหตุเพลิงไหม้ในเวลากลางคืน"}],"partOfSpeech":["other","noun"]},
  {"id":"hsk5-1343","chinese":"夜市","pinyin":"yèshì","meaning":"night market","meaningThai":"ตลาดกลางคืน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在元宵节，人们通常会去逛夜市，也是上许许多多的灯笼将夜晚点亮。","pinyin":"Zài yuán xiāo jié， rén mén tōng cháng huì qù guàng yè shì， yě shì shàng xǔ xǔ duō duō de dēng lóng jiāng yè wǎn diǎn liàng。","meaning":"In the Lantern Festival, people would usually go to the night fair where thousands of lanterns light the night up.","meaningThai":"ในเทศกาลโคมไฟ ผู้คนมักจะไปงานกลางคืนซึ่งมีโคมไฟนับพันดวงส่องสว่างในยามค่ำคืน"},{"chinese":"点击这里找到你所在城市的面条夜市。","pinyin":"Diǎn jī zhè lǐ zhǎo dào nǐ suǒ zài chéng shì de miàn tiáo yè shì。","meaning":"Click here to find a Night Noodle Market in your city.","meaningThai":"คลิกที่นี่เพื่อค้นหาตลาดบะหมี่กลางคืนในเมืองของคุณ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1344","chinese":"业务","pinyin":"yèwù","meaning":"business; professional work; service","meaningThai":"ธุรกิจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"业务范围。","pinyin":"Ye wu fan wei.","meaning":"Business scope.","meaningThai":"ขอบเขตธุรกิจ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1345","chinese":"业余","pinyin":"yèyú","meaning":"in one's spare time; outside working hours; amateur (historian etc)","meaningThai":"มือสมัครเล่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"安吉拉说她渴望参加业余戏剧班。","pinyin":"Ān jí lā shuō tā kě wàng cān jiā yè yú xì jù bān。","meaning":"Angela says she longs to join an amateur dramatics class.","meaningThai":"แองเจลาบอกว่าเธออยากเข้าร่วมชั้นเรียนละครสมัครเล่นมาก"},{"chinese":"这些绘画看起来是业余画家的作品。","pinyin":"Zhè xiē huì huà kàn qǐ lái shì yè yú huà jiā de zuò pǐn。","meaning":"The paintings looked amateurish.","meaningThai":"ภาพวาดดูไม่ชำนาญ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1346","chinese":"移","pinyin":"yí","meaning":"to move; to shift; to change; to alter; to remove","meaningThai":"กะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他慢慢地移近电话，准备抓起它。","pinyin":"Tā màn màn dì yí jìn diàn huà， zhǔn bèi zhuā qǐ tā。","meaning":"He edged closer to the telephone, ready to grab it.","meaningThai":"เขาขยับเข้าใกล้โทรศัพท์มากขึ้น เตรียมหยิบมันขึ้นมา"},{"chinese":"他把脚慢慢移离了油门。","pinyin":"Tā bǎ jiǎo màn màn yí lí le yóu mén。","meaning":"He eased his foot off the accelerator.","meaningThai":"เขาปล่อยเท้าออกจากคันเร่ง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1347","chinese":"亿","pinyin":"yì","meaning":"100 million","meaningThai":"100 ล้าน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"销售额从27亿元猛增到35亿元。","pinyin":"Xiāo shòu é cóng 27 yì yuán měng zēng dào 35 yì yuán。","meaning":"Sales jumped from $2.7 billion to $3.5 billion.","meaningThai":"ยอดขายเพิ่มขึ้นจาก 2.7 พันล้านดอลลาร์เป็น 3.5 พันล้านดอลลาร์"},{"chinese":"大概1.5亿美元将花在改进上。","pinyin":"Dà gài1.5 yì měi yuán jiāng huā zài gǎi jìn shàng。","meaning":"Approximately $150 million is to be spent on improvements.","meaningThai":"ต้องใช้เงินประมาณ 150 ล้านดอลลาร์เพื่อการปรับปรุง"}],"partOfSpeech":["numeral"]},
  {"id":"hsk5-1348","chinese":"乙","pinyin":"yǐ","meaning":"second of the ten Heavenly Stems 干; second in order; letter \"B\" or Roman \"II\" in list \"A, B, C\", or \"I, II, III\" etc; second party (in legal contract, usually 方, as opposed to 方); ethyl; bent; winding; radical in Chinese characters (Kangxi radical 5); ancient Chinese compass point: 105°","meaningThai":"ที่สอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"假设甲某和乙某在公园里相遇。","pinyin":"Jiǎ shè jiǎ mǒu hé yǐ mǒu zài gōng yuán lǐ xiāng yù。","meaning":"Let's pretend A meets B in the park.","meaningThai":"สมมติว่า A พบ B ในสวนสาธารณะ"},{"chinese":"假定甲知道乙应负罪责。","pinyin":"Jiǎ dìng jiǎ zhī dào yǐ yīng fù zuì zé。","meaning":"Assume A knows B is guilty.","meaningThai":"สมมติว่า A รู้ว่า B มีความผิด"}],"partOfSpeech":["numeral","other","noun"]},
  {"id":"hsk5-1349","chinese":"以","pinyin":"yǐ","meaning":"old variant of 以","meaningThai":"โดย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他以微弱劣势败北。","pinyin":"Tā yǐ wēi ruò liè shì bài běi。","meaning":"He was just beaten in a photo-finish.","meaningThai":"เขาเพิ่งถูกทุบตีในการถ่ายภาพเสร็จ"},{"chinese":"加入氯以杀菌。","pinyin":"Jiā rù lǜ yǐ shā jūn。","meaning":"Chlorine is added to kill bacteria.","meaningThai":"เติมคลอรีนเพื่อฆ่าเชื้อแบคทีเรีย"}],"partOfSpeech":["preposition","conjunction","adjective"]},
  {"id":"hsk5-1350","chinese":"一次性","pinyin":"yícìxìng","meaning":"one-off (offer); one-time; single-use; disposable (goods)","meaningThai":"แบบใช้แล้วทิ้ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"一次性尿布非常容易穿。","pinyin":"Yī cì xìng niào bù fēi cháng róng yì chuān。","meaning":"Disposable diapers are fairly straightforward to put on.","meaningThai":"ผ้าอ้อมสำเร็จรูปค่อนข้างสวมใส่ได้ง่าย"},{"chinese":"使用一次性产品被认为是没有顾及对生态的影响。","pinyin":"Shǐ yòng yī cì xìng chǎn pǐn bèi rèn wéi shì méi yǒu gù jí duì shēng tài de yǐng xiǎng。","meaning":"The use of disposable products is considered ecologically unsound.","meaningThai":"การใช้ผลิตภัณฑ์แบบใช้แล้วทิ้งถือเป็นความไม่เป็นมิตรต่อระบบนิเวศ"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-1351","chinese":"一代","pinyin":"yídài","meaning":"generation","meaningThai":"รุ่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"按理他是他那一代中最优秀的演员。","pinyin":"Àn lǐ tā shì tā nà yī dài zhōng zuì yōu xiù de yǎn yuán。","meaning":"He is arguably the best actor of his generation.","meaningThai":"เขาเป็นนักแสดงที่ดีที่สุดในรุ่นของเขา"},{"chinese":"自然资源应该完好无损地传给下一代。","pinyin":"Zì rán zī yuán yīng gāi wán hǎo wú sǔn dì chuán gěi xià yī dài。","meaning":"Natural resources should be handed on to the next generation intact.","meaningThai":"ทรัพยากรธรรมชาติควรถูกส่งต่อไปยังรุ่นต่อไปอย่างครบถ้วน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1352","chinese":"一旦","pinyin":"yídàn","meaning":"in case (sth happens); if; once (sth happens, then...); when; in a short time; in one day","meaningThai":"ครั้งหนึ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"一旦火鸡解冻，立刻移除鸡杂。","pinyin":"Yī dàn huǒ jī jiě dòng， lì kè yí chú jī zá。","meaning":"Once the turkey has defrosted, remove the giblets.","meaningThai":"เมื่อไก่งวงละลายน้ำแข็งแล้ว ให้เอาเครื่องในออก"},{"chinese":"一旦我到了迈阿密就能找到工作。","pinyin":"Yī dàn wǒ dào le mài ā mì jiù néng zhǎo dào gōng zuò。","meaning":"Once I'm in Miami I can get a job.","meaningThai":"เมื่อฉันอยู่ในไมอามี่ ฉันสามารถหางานได้"}],"partOfSpeech":["adverb","conjunction"]},
  {"id":"hsk5-1353","chinese":"移动","pinyin":"yídòng","meaning":"to move; movement; migration; mobile; portable","meaningThai":"เคลื่อนไหว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"坦克移动时掀起滚滚的尘土。","pinyin":"Tǎn kè yí dòng shí xiān qǐ gǔn gǔn de chén tǔ。","meaning":"Tanks raise huge trails of dust when they move.","meaningThai":"รถถังทำให้เกิดฝุ่นขนาดมหึมาเมื่อพวกมันเคลื่อนที่"},{"chinese":"我们需要用滚子来移动钢琴。","pinyin":"Wǒ mén xū yào yòng gǔn zǐ lái yí dòng gāng qín。","meaning":"We'll need to move the piano on rollers.","meaningThai":"เราจะต้องย้ายเปียโนบนลูกกลิ้ง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1354","chinese":"遗憾","pinyin":"yíhàn","meaning":"regret; to regret; to be sorry that","meaningThai":"สงสาร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"遗憾的是没有早些报警。","pinyin":"Yí hàn de shì méi yǒu zǎo xiē bào jǐng。","meaning":"It is regrettable that the police were not informed sooner.","meaningThai":"น่าเสียดายที่ตำรวจไม่แจ้งให้ทราบเร็วกว่านี้"},{"chinese":"失去工作非常令人遗憾。","pinyin":"Shī qù gōng zuò fēi cháng líng rén yí hàn。","meaning":"The loss of jobs is highly regrettable.","meaningThai":"การตกงานเป็นเรื่องน่าเสียใจอย่างยิ่ง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1355","chinese":"以及","pinyin":"yǐjí","meaning":"as well as; too; and","meaningThai":"เช่นเดียวกับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我收集贝壳以及海边有趣的东西。","pinyin":"Wǒ shōu jí bèi ké yǐ jí hǎi biān yǒu qù de dōng xī。","meaning":"I collect shells and interesting seaside items.","meaningThai":"ฉันรวบรวมเปลือกหอยและสิ่งของริมทะเลที่น่าสนใจ"},{"chinese":"结果取决于条件以及事件如何发展。","pinyin":"Jié guǒ qǔ jué yú tiáo jiàn yǐ jí shì jiàn rú hé fā zhǎn。","meaning":"The outcome depends on conditions as well as how events unfold.","meaningThai":"ผลลัพธ์ขึ้นอยู่กับเงื่อนไขตลอดจนเหตุการณ์ที่เกิดขึ้น"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1356","chinese":"依据","pinyin":"yījù","meaning":"according to; basis; foundation","meaningThai":"ตาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"法律依据。","pinyin":"Fa lv yi ju.","meaning":"Legal basis.","meaningThai":"พื้นฐานทางกฎหมาย"}],"partOfSpeech":["noun","preposition","verb"]},
  {"id":"hsk5-1357","chinese":"依靠","pinyin":"yīkào","meaning":"to rely on sth (for support etc); to depend on","meaningThai":"พึ่งพา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你可以依靠它。","pinyin":"Nǐ kě yǐ yī kào tā。","meaning":"You can count on it.","meaningThai":"คุณสามารถวางใจได้"},{"chinese":"你可以依靠他。","pinyin":"Nǐ kě yǐ yī kào tā。","meaning":"You can rely on him.","meaningThai":"คุณสามารถพึ่งพาเขาได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1358","chinese":"以来","pinyin":"yǐlái","meaning":"since (a previous event)","meaningThai":"เนื่องจาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这是有记录以来最严重的水灾。","pinyin":"Zhè shì yǒu jì lù yǐ lái zuì yán zhòng de shuǐ zāi。","meaning":"It was the worst flood since records began.","meaningThai":"มันเป็นน้ำท่วมที่เลวร้ายที่สุดนับตั้งแต่เริ่มบันทึก"},{"chinese":"1945年以来，空军的规模已经缩小。","pinyin":"1945 nián yǐ lái， kōng jūn de guī mó yǐ jīng suō xiǎo。","meaning":"Since 1945 air forces have decreased in size.","meaningThai":"ตั้งแต่ปี พ.ศ. 2488 กองทัพอากาศได้ลดขนาดลง"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1359","chinese":"医疗","pinyin":"yīliáo","meaning":"medical treatment","meaningThai":"ทางการแพทย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"良好的医疗保健是重中之重。","pinyin":"Liáng hǎo de yī liáo bǎo jiàn shì zhòng zhōng zhī zhòng。","meaning":"Good health care is of primary importance.","meaningThai":"การดูแลสุขภาพที่ดีเป็นสิ่งสำคัญอันดับแรก"},{"chinese":"医疗技术日益复杂精妙。","pinyin":"Yī liáo jì shù rì yì fù zá jīng miào。","meaning":"Medical techniques are becoming more sophisticated all the time.","meaningThai":"เทคนิคทางการแพทย์มีความซับซ้อนมากขึ้นตลอดเวลา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1360","chinese":"一路","pinyin":"yílù","meaning":"the whole journey; all the way; going the same way; going in the same direction; of the same kind","meaningThai":"ตลอดทาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们一路步行走到了第42街。","pinyin":"Wǒ mén yī lù bù háng zǒu dào le dì 42 jiē。","meaning":"We hoofed it all the way to 42nd Street.","meaningThai":"เรากีบมันไปจนถึงถนน 42"},{"chinese":"飞机一路大多在云层里飞行。","pinyin":"Fēi jī yī lù dà duō zài yún céng lǐ fēi háng。","meaning":"The plane was flying in cloud most of the way.","meaningThai":"เครื่องบินกำลังบินอยู่ในเมฆเกือบตลอดทาง"}],"partOfSpeech":["quantity expression","adverb"]},
  {"id":"hsk5-1361","chinese":"一路顺风","pinyin":"yílù-shùnfēng","meaning":"to have a pleasant journey (idiom)","meaningThai":"เดินทางโดยสวัสดิภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"一路顺风，到了给我发消息。","pinyin":"Yī lù shùn fēng, dào le gěi wǒ fā xiāo xī.","meaning":"Safe travels, message me when you arrive.","meaningThai":"เดินทางปลอดภัย ส่งข้อความถึงฉันเมื่อคุณมาถึง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1362","chinese":"因而","pinyin":"yīn’ér","meaning":"therefore; as a result; thus; and as a result, ...","meaningThai":"ดังนั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"因而成功。","pinyin":"Yin er cheng gong.","meaning":"Therefore succeed.","meaningThai":"จึงจะสำเร็จ."}],"partOfSpeech":["conjunction"]},
  {"id":"hsk5-1363","chinese":"迎","pinyin":"yíng","meaning":"to welcome; to meet; to forge ahead (esp. in the face of difficulties); to meet face to face","meaningThai":"ยินดีต้อนรับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"其实送鬼，是要先迎鬼的。","pinyin":"Qí shí sòng guǐ， shì yào xiān yíng guǐ de。","meaning":"In fact, when we send a ghost away, we must welcome the ghost first.","meaningThai":"จริงๆแล้วเมื่อเราส่งผีออกไปเราต้องต้อนรับผีก่อน"},{"chinese":"我的双眼迎视他冰冷的目光。","pinyin":"Wǒ de shuāng yǎn yíng shì tā bīng lěng de mù guāng。","meaning":"My eyes met his icy gaze.","meaningThai":"ดวงตาของฉันสบสายตาเย็นชาของเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1364","chinese":"硬","pinyin":"yìng","meaning":"hard; stiff; solid; (fig.) strong; firm; resolutely; uncompromisingly; laboriously; with great difficulty; good (quality); able (person); (of food) filling; substantial","meaningThai":"แข็ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"牛排硬得嚼不动，豌豆就像子弹。","pinyin":"Niú pái yìng dé jiáo bù dòng， wān dòu jiù xiàng zǐ dàn。","meaning":"The steak was tough and the peas were like bullets.","meaningThai":"สเต็กนั้นแข็งและถั่วก็เหมือนกระสุน"},{"chinese":"脚下踩的土地又干又硬。","pinyin":"Jiǎo xià cǎi de tǔ dì yòu gān yòu yìng。","meaning":"The ground was dry and firm underfoot.","meaningThai":"พื้นดินแห้งและมั่นคงใต้ฝ่าเท้า"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-1365","chinese":"应当","pinyin":"yīngdāng","meaning":"should; ought to","meaningThai":"ควร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"应当多学东西。","pinyin":"Yīng dāng duō xué dōng xī。","meaning":"You should learn more.","meaningThai":"คุณควรเรียนรู้เพิ่มเติม"},{"chinese":"火车应当准点到。","pinyin":"Huǒ chē yīng dāng zhǔn diǎn dào。","meaning":"The train should be on time.","meaningThai":"รถไฟควรจะตรงเวลา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1366","chinese":"应对","pinyin":"yìngduì","meaning":"to answer; to reply; to handle; to deal with; response","meaningThai":"การตอบสนอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他钦佩她应对生活的方式。","pinyin":"Tā qīn pèi tā yīng duì shēng huó de fāng shì。","meaning":"He admired the way she had coped with life.","meaningThai":"เขาชื่นชมวิธีที่เธอจัดการกับชีวิต"},{"chinese":"他迅速地应对突发事件。","pinyin":"Tā xùn sù dì yīng duì tū fā shì jiàn。","meaning":"He deals with emergencies promptly.","meaningThai":"เขาจัดการกับเหตุฉุกเฉินทันที"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1367","chinese":"硬件","pinyin":"yìngjiàn","meaning":"hardware","meaningThai":"ฮาร์ดแวร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"电脑硬件升级了。","pinyin":"Diàn nǎo yìng jiàn shēng jí le.","meaning":"The computer hardware was upgraded.","meaningThai":"ฮาร์ดแวร์คอมพิวเตอร์ได้รับการอัพเกรด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1368","chinese":"迎接","pinyin":"yíngjiē","meaning":"to welcome; to greet","meaningThai":"พบปะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我将在进港大厅的迎接点等你。","pinyin":"Wǒ jiāng zài jìn gǎng dà tīng de yíng jiē diǎn děng nǐ。","meaning":"I'll wait for you at the meeting point in the arrivals hall.","meaningThai":"ฉันจะรอคุณที่จุดนัดพบในอาคารผู้โดยสารขาเข้า"},{"chinese":"酒店有车在机场迎接各航班的旅客。","pinyin":"Jiǔ diàn yǒu chē zài jī cháng yíng jiē gè háng bān de lǚ kè。","meaning":"The hotel bus meets all incoming flights.","meaningThai":"รถบัสของโรงแรมรองรับเที่ยวบินขาเข้าทั้งหมด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1369","chinese":"影片","pinyin":"yǐngpiàn","meaning":"a copy of a film; film; motion picture; movie","meaningThai":"ฟิล์ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这次演出在纽约现场拍了影片。","pinyin":"Zhè cì yǎn chū zài niǔ yuē xiàn cháng pāi le yǐng piàn。","meaning":"The show was filmed on location in New York.","meaningThai":"รายการนี้ถ่ายทำในสถานที่ในนิวยอร์ก"},{"chinese":"他否认这部影片美化暴力。","pinyin":"Tā fǒu rèn zhè bù yǐng piàn měi huà bào lì。","meaning":"He denies that the movie glorifies violence.","meaningThai":"เขาปฏิเสธว่าภาพยนตร์เรื่องนี้เชิดชูความรุนแรง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1370","chinese":"影视","pinyin":"yǐngshì","meaning":"movies and television","meaningThai":"ภาพยนตร์และโทรทัศน์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他更为著名的是影视作品。","pinyin":"Tā gēng wéi zhù míng de shì yǐng shì zuò pǐn。","meaning":"He is better known for his film and TV work.","meaningThai":"เขาเป็นที่รู้จักกันดีจากผลงานภาพยนตร์และโทรทัศน์"},{"chinese":"布里斯班已成为一座新兴的澳大利亚影视城。","pinyin":"Bù lǐ sī bān yǐ chéng wéi yī zuò xīn xīng de ào dà lì yà yǐng shì chéng。","meaning":"Brisbane has become the boom town for Australian film and television.","meaningThai":"บริสเบนได้กลายเป็นเมืองที่เจริญรุ่งเรืองสำหรับภาพยนตร์และโทรทัศน์ของออสเตรเลีย"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1371","chinese":"营养","pinyin":"yíngyǎng","meaning":"nutrition; nourishment","meaningThai":"โภชนาการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个食谱营养丰富。","pinyin":"Zhè ge shí pǔ yíng yǎng fēng fù.","meaning":"This recipe is very nutritious.","meaningThai":"สูตรนี้มีคุณค่าทางโภชนาการมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1372","chinese":"营业","pinyin":"yíngyè","meaning":"to do business; to trade","meaningThai":"ธุรกิจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"那不是营业开张的吉时佳日。","pinyin":"Nà bù shì yíng yè kāi zhāng de jí shí jiā rì。","meaning":"It was not a propitious time to start a new business.","meaningThai":"ไม่ใช่เวลาอันสมควรในการเริ่มต้นธุรกิจใหม่"},{"chinese":"没有现金你无法继续营业。","pinyin":"Méi yǒu xiàn jīn nǐ wú fǎ jì xù yíng yè。","meaning":"You can't stay in business without cash.","meaningThai":"คุณไม่สามารถอยู่ในธุรกิจได้หากไม่มีเงินสด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1373","chinese":"应用","pinyin":"yìngyòng","meaning":"to put to use; to apply; practical; applied (science, linguistics etc); application; practical use; (computing) app","meaningThai":"แอปพลิเคชัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个软件是为学校应用设计的。","pinyin":"Zhè gè ruǎn jiàn shì wéi xué xiào yīng yòng shè jì de。","meaning":"The software is designed for use in schools.","meaningThai":"ซอฟต์แวร์นี้ออกแบบมาเพื่อใช้ในโรงเรียน"},{"chinese":"理论研究和实际应用之间存在时滞。","pinyin":"Lǐ lùn yán jiū hé shí jì yīng yòng zhī jiān cún zài shí zhì。","meaning":"There is a time-lag between theoretical research and practical applications.","meaningThai":"มีความล่าช้าระหว่างการวิจัยเชิงทฤษฎีและการประยุกต์ใช้ในทางปฏิบัติ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1374","chinese":"引进","pinyin":"yǐnjìn","meaning":"to recommend; to introduce (from outside)","meaningThai":"การแนะนำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"引进新系统后一定会发生变化。","pinyin":"Yǐn jìn xīn xì tǒng hòu yī dìng huì fā shēng biàn huà。","meaning":"There are bound to be changes when the new system is introduced.","meaningThai":"จะต้องมีการเปลี่ยนแปลงเมื่อมีการเปิดตัวระบบใหม่"},{"chinese":"引进新技术的成功程度不尽相同。","pinyin":"Yǐn jìn xīn jì shù de chéng gōng chéng dù bù jìn xiāng tóng。","meaning":"New techniques were introduced with varying degrees of success.","meaningThai":"มีการแนะนำเทคนิคใหม่พร้อมระดับความสำเร็จที่แตกต่างกัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1375","chinese":"音量","pinyin":"yīnliàng","meaning":"loudness; volume","meaningThai":"ปริมาณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个按钮是调节音量的。","pinyin":"Zhè gè àn niǔ shì tiáo jié yīn liáng de。","meaning":"This button is for adjusting the volume.","meaningThai":"ปุ่มนี้ใช้สำหรับปรับระดับเสียง"},{"chinese":"你能把音量开大点儿吗？","pinyin":"Nǐ néng bǎ yīn liáng kāi dà diǎn ér ma？","meaning":"Can you turn the volume up a bit?","meaningThai":"คุณช่วยเพิ่มระดับเสียงหน่อยได้ไหม?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1376","chinese":"饮食","pinyin":"yǐnshí","meaning":"eating and drinking; food and drink; diet","meaningThai":"อาหาร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"显然，饮食和运动是重要的。","pinyin":"Xiǎn rán， yǐn shí hé yùn dòng shì zhòng yào de。","meaning":"Diet and exercise are obviously important.","meaningThai":"อาหารและการออกกำลังกายมีความสำคัญอย่างเห็นได้ชัด"},{"chinese":"糟糕的饮食终将导致疾病。","pinyin":"Zāo gāo de yǐn shí zhōng jiāng dǎo zhì jí bìng。","meaning":"A poor diet will ultimately lead to illness.","meaningThai":"การรับประทานอาหารที่ไม่ดีจะนำไปสู่การเจ็บป่วยในที่สุด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1377","chinese":"印刷","pinyin":"yìnshuā","meaning":"to print; printing","meaningThai":"พิมพ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"印刷术是哪年发明的？","pinyin":"Yìn shuā shù shì nǎ nián fā míng de？","meaning":"In what year was printing invented?","meaningThai":"การพิมพ์ถูกประดิษฐ์ขึ้นในปีใด?"},{"chinese":"这本书在英国印刷。","pinyin":"Zhè běn shū zài yīng guó yìn shuā。","meaning":"This book was printed in England.","meaningThai":"หนังสือเล่มนี้จัดพิมพ์ในอังกฤษ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1378","chinese":"因素","pinyin":"yīnsù","meaning":"element; factor","meaningThai":"ปัจจัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"许多因素可以导致胎儿发育迟缓。","pinyin":"Xǔ duō yīn sù kě yǐ dǎo zhì tāi ér fā yù chí huǎn。","meaning":"Many factors can lead to growth retardation in unborn babies.","meaningThai":"ปัจจัยหลายประการสามารถนำไปสู่การชะลอการเจริญเติบโตในทารกในครรภ์ได้"},{"chinese":"经济因素影响着教育的成功。","pinyin":"Jīng jì yīn sù yǐng xiǎng zháo jiào yù de chéng gōng。","meaning":"Educational success is mediated by economic factors.","meaningThai":"ความสำเร็จทางการศึกษาขึ้นอยู่กับปัจจัยทางเศรษฐกิจ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1379","chinese":"依然","pinyin":"yīrán","meaning":"still; as before","meaningThai":"นิ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在他看来，价格依然低得荒谬。","pinyin":"Zài tā kàn lái， jià gé yī rán dī dé huāng miù。","meaning":"Prices were still absurdly low, in his opinion.","meaningThai":"ราคายังคงต่ำอย่างไร้เหตุผลในความคิดของเขา"},{"chinese":"美军依然驻守这个国家。","pinyin":"Měi jūn yī rán zhù shǒu zhè gè guó jiā。","meaning":"American troops still garrisoned the country.","meaningThai":"กองทหารอเมริกันยังคงรักษาการณ์ในประเทศ"}],"partOfSpeech":["adverb","other"]},
  {"id":"hsk5-1380","chinese":"意识","pinyin":"yìshí","meaning":"consciousness; awareness; to be aware; to realize","meaningThai":"จิตสำนึก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"安全意识。","pinyin":"An quan yi shi.","meaning":"Safety awareness.","meaningThai":"ความตระหนักด้านความปลอดภัย"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-1381","chinese":"意外","pinyin":"yìwài","meaning":"unexpected; accident; mishap","meaningThai":"อุบัติเหตุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的到来让我感到意外。","pinyin":"Tā de dào lái ràng wǒ gǎn dào yì wài。","meaning":"His arrival caught me by surprise.","meaningThai":"การมาถึงของเขาทำให้ฉันประหลาดใจ"},{"chinese":"该辞职来得十分意外。","pinyin":"Gāi cí zhí lái dé shí fēn yì wài。","meaning":"The resignation came as a complete surprise.","meaningThai":"การลาออกเป็นเรื่องที่น่าประหลาดใจอย่างยิ่ง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1382","chinese":"意味着","pinyin":"yìwèizhe","meaning":"to signify; to mean; to imply","meaningThai":"หมายถึง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这意味着什么？","pinyin":"Zhe yi wei zhe shen me?","meaning":"What does this mean?","meaningThai":"สิ่งนี้หมายความว่าอย่างไร?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1383","chinese":"疑问","pinyin":"yíwèn","meaning":"question; interrogation; doubt","meaningThai":"สงสัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他承认他有疑问。","pinyin":"Tā chéng rèn tā yǒu yí wèn。","meaning":"He admitted he was suspicious.","meaningThai":"เขายอมรับว่าเขาน่าสงสัย"},{"chinese":"宇宙毫无疑问是无限的。","pinyin":"Yǔ zhòu háo wú yí wèn shì wú xiàn de。","meaning":"There's no doubt that the universe is infinite. / There's no doubt: the universe is infinite.","meaningThai":"ไม่ต้องสงสัยเลยว่าจักรวาลไม่มีที่สิ้นสุด / ไม่ต้องสงสัยเลย: จักรวาลไม่มีที่สิ้นสุด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1384","chinese":"义务","pinyin":"yìwù","meaning":"duty; obligation; volunteer (work etc)","meaningThai":"ภาระผูกพัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"地方议员有义务为社区服务。","pinyin":"Dì fāng yì yuán yǒu yì wù wéi shè qū fú wù。","meaning":"Local councillors have a duty to serve the community.","meaningThai":"สมาชิกสภาท้องถิ่นมีหน้าที่รับใช้ชุมชน"},{"chinese":"她觉得没有义务告诉他实情。","pinyin":"Tā jué dé méi yǒu yì wù gào sù tā shí qíng。","meaning":"She did not feel under any obligation to tell him the truth.","meaningThai":"เธอไม่รู้สึกผูกพันที่จะต้องบอกความจริงแก่เขา"}],"partOfSpeech":["noun","adverb"]},
  {"id":"hsk5-1385","chinese":"医学","pinyin":"yīxué","meaning":"medicine; medical science; study of medicine","meaningThai":"แพทยศาสตร์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"医学专业需要学习六年。","pinyin":"Yī xué zhuān yè xū yào xué xí liù nián.","meaning":"Medical programs require six years of study.","meaningThai":"โปรแกรมการแพทย์ต้องใช้เวลาเรียนหกปี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1386","chinese":"意义","pinyin":"yìyì","meaning":"sense; meaning; significance; importance","meaningThai":"ความสำคัญ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他整个晚上大谈人生的意义。","pinyin":"Tā zhěng gè wǎn shàng dà tán rén shēng de yì yì。","meaning":"He spent the evening philosophizing on the meaning of life.","meaningThai":"เขาใช้เวลาช่วงเย็นคิดปรัชญาเกี่ยวกับความหมายของชีวิต"},{"chinese":"总统的访问富有象征意义。","pinyin":"Zǒng tǒng de fǎng wèn fù yǒu xiàng zhēng yì yì。","meaning":"The president's visit is loaded with symbolic significance.","meaningThai":"การมาเยือนของประธานาธิบดีเต็มไปด้วยความหมายเชิงสัญลักษณ์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1387","chinese":"一致","pinyin":"yízhì","meaning":"unanimous; identical (views or opinions)","meaningThai":"สม่ำเสมอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"编辑们一致谴责这些提议。","pinyin":"Biān jí mén yī zhì qiǎn zé zhè xiē tí yì。","meaning":"Editors were unanimous in their condemnation of the proposals.","meaningThai":"บรรณาธิการมีมติเป็นเอกฉันท์ในการประณามข้อเสนอดังกล่าว"},{"chinese":"我恰恰和你意见一致。","pinyin":"Wǒ qià qià hé nǐ yì jiàn yī zhì。","meaning":"I agree with you, as it happens.","meaningThai":"ฉันเห็นด้วยกับคุณเมื่อมันเกิดขึ้น"}],"partOfSpeech":["adjective","noun"]},
  {"id":"hsk5-1388","chinese":"拥抱","pinyin":"yōngbào","meaning":"to embrace; to hug","meaningThai":"กอด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"热情拥抱。","pinyin":"Re qing yong bao.","meaning":"Warm embrace.","meaningThai":"อ้อมกอดอันอบอุ่น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1389","chinese":"用法","pinyin":"yòngfǎ","meaning":"usage","meaningThai":"การใช้งาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个动词此处的用法是不及物的。","pinyin":"Zhè gè dòng cí cǐ chǔ de yòng fǎ shì bù jí wù de。","meaning":"The verb is being used intransitively.","meaningThai":"กริยากำลังถูกใช้แบบอกรรมกริยา"},{"chinese":"这肯定是从美国传至英国的一种用法。","pinyin":"Zhè kěn dìng shì cóng měi guó chuán zhì yīng guó de yī zhǒng yòng fǎ。","meaning":"It's very definitely a usage which has come over to Britain from America.","meaningThai":"เป็นการใช้งานที่มาจากอังกฤษจากอเมริกาอย่างแน่นอน"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-1390","chinese":"用户","pinyin":"yònghù","meaning":"user; consumer; subscriber; customer","meaningThai":"ผู้ใช้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"终端用户。","pinyin":"Zhong duan yong hu.","meaning":"End user.","meaningThai":"ผู้ใช้ปลายทาง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1391","chinese":"用力","pinyin":"yònglì","meaning":"to exert oneself physically","meaningThai":"ใช้กำลัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她用力地拍了球。","pinyin":"Tā yòng lì dì pāi le qiú。","meaning":"She hit the ball hard.","meaningThai":"เธอตีลูกบอลอย่างแรง"},{"chinese":"我把我自己用力拉起來。","pinyin":"Wǒ bǎ wǒ zì jǐ yòng lì lā qǐ lái。","meaning":"I heaved myself up.","meaningThai":"ฉันลุกขึ้นมา"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1392","chinese":"用品","pinyin":"yòngpǐn","meaning":"articles for use; products; goods","meaningThai":"เสบียง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"急需醫療用品。","pinyin":"Jí xū yī liáo yòng pǐn。","meaning":"There is an urgent need for medical supplies. / There's an urgent need for medical supplies.","meaningThai":"มีความจำเป็นเร่งด่วนด้านเวชภัณฑ์ / มีความจำเป็นเร่งด่วนด้านเวชภัณฑ์"},{"chinese":"他們賣體育用品。","pinyin":"Tā mén mài tǐ yù yòng pǐn。","meaning":"They sell sporting goods.","meaningThai":"พวกเขาขายสินค้ากีฬา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1393","chinese":"勇气","pinyin":"yǒngqì","meaning":"courage; valor","meaningThai":"ความกล้าหาญ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他应该因其勇气而受到称赞。","pinyin":"Tā yīng gāi yīn qí yǒng qì ér shòu dào chēng zàn。","meaning":"He should be applauded for his courage.","meaningThai":"เขาควรได้รับการปรบมือให้กับความกล้าหาญของเขา"},{"chinese":"她想勇敢，但却鼓不起勇气。","pinyin":"Tā xiǎng yǒng gǎn， dàn què gǔ bù qǐ yǒng qì。","meaning":"She tried to be brave, but her courage failed her.","meaningThai":"เธอพยายามจะกล้าหาญ แต่ความกล้าหาญของเธอทำให้เธอล้มเหลว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1394","chinese":"用途","pinyin":"yòngtú","meaning":"use; application","meaningThai":"ใช้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种化学制品在工业上用途广泛。","pinyin":"Zhè zhǒng huà xué zhì pǐn zài gōng yè shàng yòng tú guǎng fàn。","meaning":"This chemical has a wide range of industrial uses.","meaningThai":"สารเคมีนี้มีการใช้ในอุตสาหกรรมอย่างกว้างขวาง"},{"chinese":"我相信你会给这东西找到用途的。","pinyin":"Wǒ xiāng xìn nǐ huì gěi zhè dōng xī zhǎo dào yòng tú de。","meaning":"I'm sure you'll think of a use for it.","meaningThai":"ฉันแน่ใจว่าคุณจะคิดถึงการใช้มัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1395","chinese":"拥有","pinyin":"yōngyǒu","meaning":"to have; to possess","meaningThai":"มี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们并不永久拥有这片土地。","pinyin":"Tā mén bìng bù yǒng jiǔ yōng yǒu zhè piàn tǔ dì。","meaning":"They do not own the land in perpetuity.","meaningThai":"พวกเขาไม่ได้เป็นเจ้าของที่ดินตลอดไป"},{"chinese":"他还被指控非法拥有火器。","pinyin":"Tā huán bèi zhǐ kòng fēi fǎ yōng yǒu huǒ qì。","meaning":"He was also charged with illegal possession of firearms.","meaningThai":"นอกจากนี้เขายังถูกตั้งข้อหาครอบครองอาวุธปืนโดยผิดกฎหมายอีกด้วย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1396","chinese":"由此","pinyin":"yóu cǐ","meaning":"hereby; from this","meaningThai":"ดังนั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"由此，你能得到什么呢？","pinyin":"Yóu cǐ， nǐ néng dé dào shí mó ne？","meaning":"What do you gain by this?","meaningThai":"คุณได้อะไรจากสิ่งนี้?"},{"chinese":"由此开始，它一直在发展、高升。","pinyin":"Yóu cǐ kāi shǐ， tā yī zhí zài fā zhǎn、 gāo shēng。","meaning":"From here, it has been onward and upward all the way.","meaningThai":"จากนี้ไปก็ขึ้นๆลงๆตลอดทาง"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1397","chinese":"有害","pinyin":"yǒu hài","meaning":"destructive; harmful; damaging","meaningThai":"เป็นอันตราย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"水不能有效阻挡太阳中更有害的射线。","pinyin":"Shuǐ bù néng yǒu xiào zǔ dǎng tài yáng zhōng gēng yǒu hài de shè xiàn。","meaning":"Water is not an effective shield against the sun's more harmful rays.","meaningThai":"น้ำไม่ใช่เกราะป้องกันแสงแดดที่เป็นอันตรายมากกว่า"},{"chinese":"饮酒过度对你的身体有害。","pinyin":"Yǐn jiǔ guò dù duì nǐ de shēn tǐ yǒu hài。","meaning":"Too much drink is bad for your health.","meaningThai":"การดื่มมากเกินไปไม่ดีต่อสุขภาพของคุณ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1398","chinese":"幼儿园","pinyin":"yòu'éryuán","meaning":"kindergarten; nursery school","meaningThai":"โรงเรียนอนุบาล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她从一名幼儿园教师开始了职业生涯。","pinyin":"Tā cóng yī míng yòu ér yuán jiào shī kāi shǐ le zhí yè shēng yá。","meaning":"She began her professional career as a nursery school teacher.","meaningThai":"เธอเริ่มอาชีพการงานของเธอในฐานะครูโรงเรียนอนุบาล"},{"chinese":"我的音乐生涯包括在幼儿园演奏三角铁。","pinyin":"Wǒ de yīn lè shēng yá bāo kuò zài yòu ér yuán yǎn zòu sān jiǎo tiě。","meaning":"My musical career consisted of playing the triangle in kindergarten.","meaningThai":"อาชีพนักดนตรีของฉันประกอบด้วยการเล่นสามเหลี่ยมในโรงเรียนอนุบาล"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1399","chinese":"优惠","pinyin":"yōuhuì","meaning":"privilege; favorable (terms); preferential (treatment); discount (price)","meaningThai":"การลดราคา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"财政优惠具有不稳定性。","pinyin":"Cái zhèng yōu huì jù yǒu bù wěn dìng xìng。","meaning":"The financial concessions were of a precarious character.","meaningThai":"สัมปทานทางการเงินมีลักษณะไม่มั่นคง"},{"chinese":"这项优惠不包括雇员的伴侣。","pinyin":"Zhè xiàng yōu huì bù bāo kuò gù yuán de bàn lǚ。","meaning":"The offer does not extend to employees' partners.","meaningThai":"ข้อเสนอนี้ไม่ครอบคลุมถึงพันธมิตรของพนักงาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1400","chinese":"邮寄","pinyin":"yóujì","meaning":"send by post","meaningThai":"ส่งทางไปรษณีย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们建议你用挂号邮寄你的证书。","pinyin":"Wǒ mén jiàn yì nǐ yòng guà hào yóu jì nǐ de zhèng shū。","meaning":"We recommend that you send your certificates by recorded delivery.","meaningThai":"เราขอแนะนำให้คุณส่งใบรับรองของคุณโดยการบันทึกการจัดส่ง"},{"chinese":"我已经列在你的邮寄名单上了。","pinyin":"Wǒ yǐ jīng liè zài nǐ de yóu jì míng dān shàng le。","meaning":"I am already on your mailing list.","meaningThai":"ฉันอยู่ในรายชื่อผู้รับจดหมายของคุณแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1401","chinese":"悠久","pinyin":"yōujiǔ","meaning":"long (tradition, history etc)","meaningThai":"ยาวนาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"悠久历史。","pinyin":"You jiu li shi.","meaning":"Long history.","meaningThai":"ประวัติศาสตร์อันยาวนาน"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1402","chinese":"邮局","pinyin":"yóujú","meaning":"post office","meaningThai":"ที่ทำการไปรษณีย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她赶在邮局关门之前到达邮局。","pinyin":"Tā gǎn zài yóu jú guān mén zhī qián dào dá yóu jú。","meaning":"She rushed to get to the post office before it closed.","meaningThai":"เธอรีบไปที่ที่ทำการไปรษณีย์ก่อนที่ไปรษณีย์จะปิด"},{"chinese":"她到邮局去领取她的养老金。","pinyin":"Tā dào yóu jú qù lǐng qǔ tā de yǎng lǎo jīn。","meaning":"She went to the post office to draw her pension.","meaningThai":"เธอไปที่ทำการไปรษณีย์เพื่อรับเงินบำนาญของเธอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1403","chinese":"游览","pinyin":"yóulǎn","meaning":"to go sightseeing; to tour; to visit","meaningThai":"ท่องเที่ยว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"游览名胜。","pinyin":"You lan ming sheng.","meaning":"Visit scenic spots.","meaningThai":"เยี่ยมชมจุดชมวิว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1404","chinese":"有力","pinyin":"yǒulì","meaning":"powerful; forceful; vigorous","meaningThai":"ทรงพลัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她正手击球强劲有力。","pinyin":"Tā zhèng shǒu jī qiú qiáng jìn yǒu lì。","meaning":"She has a strong forehand.","meaningThai":"เธอมีหน้ามือที่แข็งแกร่ง"},{"chinese":"信仰比理智更有力。","pinyin":"Xìn yǎng bǐ lǐ zhì gēng yǒu lì。","meaning":"Faith is stronger than reason.","meaningThai":"ศรัทธาแข็งแกร่งกว่าเหตุผล"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1405","chinese":"有利","pinyin":"yǒulì","meaning":"advantageous; favorable","meaningThai":"ดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"协议条款对双方都有利。","pinyin":"Xié yì tiáo kuǎn duì shuāng fāng dū yǒu lì。","meaning":"The terms of the agree we are pirates, these data are stolen from youdao  are favourable to both sides.","meaningThai":"เงื่อนไขของสัญญาจะเป็นประโยชน์ต่อทั้งสองฝ่าย"},{"chinese":"早到那里是否有利？","pinyin":"Zǎo dào nà lǐ shì fǒu yǒu lì？","meaning":"Is there any advantage in getting there early?","meaningThai":"มีข้อได้เปรียบในการไปถึงที่นั่นก่อนเวลาหรือไม่?"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1406","chinese":"优良","pinyin":"yōuliáng","meaning":"fine; good; first-rate","meaningThai":"ยอดเยี่ยม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"本旅馆提供优良的家庭服务设施。","pinyin":"Běn lǚ guǎn tí gōng yōu liáng de jiā tíng fú wù shè shī。","meaning":"The hotel offers excellent facilities for families.","meaningThai":"โรงแรมมีสิ่งอำนวยความสะดวกชั้นยอดสำหรับครอบครัว"},{"chinese":"她考试成绩优良。","pinyin":"Tā kǎo shì chéng jì yōu liáng。","meaning":"She got good grades on her exams.","meaningThai":"เธอได้คะแนนสอบที่ดี"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1407","chinese":"优美","pinyin":"yōuměi","meaning":"graceful; fine; elegant","meaningThai":"สวย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"旅馆位于柠檬树丛之中，优美宜人。","pinyin":"Lǚ guǎn wèi yú níng méng shù cóng zhī zhōng， yōu měi yí rén。","meaning":"The hotel was in a beautiful position amid lemon groves.","meaningThai":"โรงแรมอยู่ในตำแหน่งที่สวยงามท่ามกลางสวนมะนาว"},{"chinese":"这优美的诗被她拙劣的朗诵给糟蹋了。","pinyin":"Zhè yōu měi de shī bèi tā zhuō liè de lǎng sòng gěi zāo tà le。","meaning":"The beautiful poetry was ruined by her poor delivery.","meaningThai":"บทกวีอันงดงามถูกทำลายลงเพราะการถ่ายทอดที่ย่ำแย่ของเธอ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1408","chinese":"邮票","pinyin":"yóupiào","meaning":"(postage) stamp","meaningThai":"แสตมป์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们特别发行了一套纪念邮票。","pinyin":"Tā mén tè bié fā háng le yī tào jì niàn yóu piào。","meaning":"They issued a special set of stamps to mark the occasion.","meaningThai":"พวกเขาได้ออกแสตมป์ชุดพิเศษเพื่อเฉลิมฉลองโอกาสนี้"},{"chinese":"他说他完全可以鉴定这枚邮票。","pinyin":"Tā shuō tā wán quán kě yǐ jiàn dìng zhè méi yóu piào。","meaning":"He says he'll have no problem authenticating the stamp.","meaningThai":"เขาบอกว่าเขาจะไม่มีปัญหาในการตรวจสอบความถูกต้องของแสตมป์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1409","chinese":"优势","pinyin":"yōushì","meaning":"superiority; dominance; advantage","meaningThai":"ข้อดี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种科技的优势是什么？","pinyin":"Zhè zhǒng kē jì de yōu shì shì shí mó？","meaning":"What is the advantage of this technology? / What is the advantage to this technology?","meaningThai":"ข้อดีของเทคโนโลยีนี้คืออะไร? / ข้อดีของเทคโนโลยีนี้คืออะไร?"},{"chinese":"主场队总是比对手有优势。","pinyin":"Zhǔ cháng duì zǒng shì bǐ duì shǒu yǒu yōu shì。","meaning":"The home team always have an advantage over their opponents.","meaningThai":"เจ้าบ้านได้เปรียบเหนือคู่แข่งเสมอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1410","chinese":"油条","pinyin":"yóutiáo","meaning":"Fried dough sticks","meaningThai":"แป้งทอดแท่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"光棍节的早餐，单身汉们通常会吃四根油条，再吃一个包子，代表中间的那个点。","pinyin":"Guāng gùn jié de zǎo cān， dān shēn hàn mén tōng cháng huì chī sì gēn yóu tiáo， zài chī yī gè bāo zǐ， dài biǎo zhōng jiān de nà gè diǎn。","meaning":"For breakfast on Singles' Day, singles often eat four deep-fried dough sticks and one steamed stuffed bun representing the middle dot.","meaningThai":"สำหรับอาหารเช้าในวันคนโสด คนโสดมักจะกินแป้งทอดสี่แท่งและซาลาเปาไส้นึ่งหนึ่งอันแทนจุดตรงกลาง"},{"chinese":"许多国家都有类似于油条的菜品。","pinyin":"Xǔ duō guó jiā dū yǒu lèi sì yú yóu tiáo de cài pǐn。","meaning":"Many countries have dishes that are similar to youtiao.","meaningThai":"หลายประเทศมีอาหารที่คล้ายกับคุณเตียว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1411","chinese":"有限","pinyin":"yǒuxiàn","meaning":"limited; finite","meaningThai":"จำกัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她知道时间有限，所以很着急。","pinyin":"Tā zhī dào shí jiān yǒu xiàn， suǒ yǐ hěn zháo jí。","meaning":"She was impatient in the knowledge that time was limited.","meaningThai":"เธอไม่อดทนกับความรู้ที่ว่าเวลามีจำกัด"},{"chinese":"座位有限，务必早日预订。","pinyin":"Zuò wèi yǒu xiàn， wù bì zǎo rì yù dìng。","meaning":"Early booking is essential, as space is limited.","meaningThai":"จำเป็นต้องจองล่วงหน้าเนื่องจากพื้นที่มีจำนวนจำกัด"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1412","chinese":"有益","pinyin":"yǒuyì","meaning":"useful; beneficial; profitable","meaningThai":"มีประโยชน์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"发简讯是沟通师生的有益渠道。","pinyin":"Fā jiǎn xùn shì gōu tōng shī shēng de yǒu yì qú dào。","meaning":"The newsletter is a useful channel of communication between teacher and students.","meaningThai":"จดหมายข่าวเป็นช่องทางการสื่อสารที่เป็นประโยชน์ระหว่างครูและนักเรียน"},{"chinese":"他提出了一些有益的建议。","pinyin":"Tā tí chū le yī xiē yǒu yì de jiàn yì。","meaning":"He offered some useful advice.","meaningThai":"เขาเสนอคำแนะนำที่เป็นประโยชน์บางอย่าง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1413","chinese":"犹豫","pinyin":"yóuyù","meaning":"to hesitate","meaningThai":"ลังเล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"布莱恩的犹豫几乎难以察觉。","pinyin":"Bù lái ēn de yóu yù jī hū nán yǐ chá jué。","meaning":"Brian's hesitation was almost imperceptible.","meaningThai":"ความลังเลของ Brian แทบจะมองไม่เห็น"},{"chinese":"玛丽似乎要抗议，又犹豫了。","pinyin":"Mǎ lì sì hū yào kàng yì， yòu yóu yù le。","meaning":"Mary made as if to protest, then hesitated.","meaningThai":"แมรี่ทำราวกับจะประท้วงแล้วลังเล"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1414","chinese":"优质","pinyin":"yōuzhì","meaning":"excellent quality","meaningThai":"คุณภาพสูง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们以公道的价格出售优质食品。","pinyin":"Wǒ mén yǐ gōng dào de jià gé chū shòu yōu zhì shí pǐn。","meaning":"We sell good quality food at reasonable prices.","meaningThai":"เราขายอาหารคุณภาพดีในราคาที่สมเหตุสมผล"},{"chinese":"这些树是制造优质纸张的原料。","pinyin":"Zhè xiē shù shì zhì zào yōu zhì zhǐ zhāng de yuán liào。","meaning":"These trees provide the raw material for high-quality paper.","meaningThai":"ต้นไม้เหล่านี้เป็นวัตถุดิบสำหรับกระดาษคุณภาพสูง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1415","chinese":"有助于","pinyin":"yǒuzhùyú","meaning":"to contribute to; to promote","meaningThai":"มีประโยชน์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"角色扮演有助于提高沟通技巧。","pinyin":"Jiǎo sè bàn yǎn yǒu zhù yú tí gāo gōu tōng jì qiǎo。","meaning":"Role-play is helpful in developing communication skills.","meaningThai":"การแสดงบทบาทสมมติมีประโยชน์ในการพัฒนาทักษะการสื่อสาร"},{"chinese":"这个会有助于治好割伤和擦伤。","pinyin":"Zhè gè huì yǒu zhù yú zhì hǎo gē shāng hé cā shāng。","meaning":"This will help to heal your cuts and scratches.","meaningThai":"นี่จะช่วยรักษาบาดแผลและรอยขีดข่วนของคุณ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1416","chinese":"原","pinyin":"yuán","meaning":"surname Yuan; (Japanese surname) Hara","meaningThai":"ต้นฉบับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"一切未支付的账单将由原住户偿付。","pinyin":"Yī qiē wèi zhī fù de zhàng dān jiāng yóu yuán zhù hù cháng fù。","meaning":"All outstanding bills will be paid by the previous occupants.","meaningThai":"ค่าใช้จ่ายคงค้างทั้งหมดจะต้องชำระโดยผู้พักอาศัยคนก่อน"},{"chinese":"从原公司分离出好几个企业。","pinyin":"Cóng yuán gōng sī fēn lí chū hǎo jī gè qǐ yè。","meaning":"Several firms have splintered off from the original company.","meaningThai":"มีหลายบริษัทแตกตัวออกจากบริษัทเดิม"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-1417","chinese":"圆","pinyin":"yuán","meaning":"circle; round; circular; spherical; (of the moon) full; unit of Chinese currency (yuan); tactful; to make consistent and whole (the narrative of a dream or a lie)","meaningThai":"กลม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这条船船头是圆的，船尾则是方的。","pinyin":"Zhè tiáo chuán chuán tóu shì yuán de， chuán wěi zé shì fāng de。","meaning":"The boat is rounded at the front but squared off at the back.","meaningThai":"เรือมีลักษณะโค้งมนที่ด้านหน้า แต่ถูกยกกำลังสองที่ด้านหลัง"},{"chinese":"那些叶子软而圆，就像绒毛一般。","pinyin":"Nà xiē yè zǐ ruǎn ér yuán， jiù xiàng róng máo yī bān。","meaning":"The leaves are soft, round and rather furry.","meaningThai":"ใบมีลักษณะนุ่ม กลมและมีขนค่อนข้างมาก"}],"partOfSpeech":["other","adjective","noun","verb"]},
  {"id":"hsk5-1418","chinese":"愿","pinyin":"yuàn","meaning":"honest; prudent; variant of 愿","meaningThai":"เต็มใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"愿我们大家都欢乐平安。","pinyin":"Yuàn wǒ mén dà jiā dū huān lè píng ān。","meaning":"May joy and peace abide in us all.","meaningThai":"ขอให้ความสุขและสันติสุขดำรงอยู่ในเราทุกคน"},{"chinese":"我们愿对延迟表示歉意。","pinyin":"Wǒ mén yuàn duì yán chí biǎo shì qiàn yì。","meaning":"We would like to apologize for the delay.","meaningThai":"เราขออภัยในความล่าช้า"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-1419","chinese":"原有","pinyin":"yuán yǒu","meaning":"original; former","meaningThai":"ต้นฉบับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这所房子保留了许多原有的魅力。","pinyin":"Zhè suǒ fáng zǐ bǎo liú le xǔ duō yuán yǒu de mèi lì。","meaning":"The house retains much of its original charm.","meaningThai":"บ้านยังคงรักษาเสน่ห์ดั้งเดิมไว้ได้มาก"},{"chinese":"改动作曲家原有的符号是亵渎行为。","pinyin":"Gǎi dòng zuò qū jiā yuán yǒu de fú hào shì xiè dú háng wéi。","meaning":"It would be sacrilege to alter the composer's original markings.","meaningThai":"การเปลี่ยนแปลงเครื่องหมายดั้งเดิมของผู้แต่งถือเป็นการดูหมิ่นศาสนา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1420","chinese":"元旦","pinyin":"Yuándàn","meaning":"New Year's Day","meaningThai":"ปีใหม่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"商店只在圣诞日和元旦停业。","pinyin":"Shāng diàn zhī zài shèng dàn rì hé yuán dàn tíng yè。","meaning":"Shops close only on Christmas Day and New Year's Day.","meaningThai":"ร้านค้าปิดเฉพาะวันคริสต์มาสและวันปีใหม่"},{"chinese":"包括元旦在内我有三天假。","pinyin":"Bāo kuò yuán dàn zài nèi wǒ yǒu sān tiān jiǎ。","meaning":"I've got three days' holiday including New Year's Day.","meaningThai":"ฉันมีวันหยุดสามวันรวมวันปีใหม่ด้วย"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1421","chinese":"员工","pinyin":"yuángōng","meaning":"staff; personnel; employee","meaningThai":"พนักงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"公司创业之初只有30名员工。","pinyin":"Gōng sī chuàng yè zhī chū zhī yǒu 30 míng yuán gōng。","meaning":"The company started out with 30 employees.","meaningThai":"บริษัทเริ่มต้นจากพนักงาน 30 คน"},{"chinese":"工资已被冻结，员工们下岗了。","pinyin":"Gōng zī yǐ bèi dòng jié， yuán gōng mén xià gǎng le。","meaning":"Wages have been frozen and workers laid off.","meaningThai":"ค่าจ้างถูกแช่แข็งและคนงานถูกเลิกจ้าง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1422","chinese":"愿望","pinyin":"yuànwàng","meaning":"desire; wish","meaningThai":"ความต้องการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他满怀着寻求社会正义的愿望。","pinyin":"Tā mǎn huái zháo xún qiú shè huì zhèng yì de yuàn wàng。","meaning":"He was imbued with a desire for social justice.","meaningThai":"เขาตื้นตันใจกับความปรารถนาที่จะได้รับความยุติธรรมทางสังคม"},{"chinese":"人们以投票方式表达他们的愿望。","pinyin":"Rén mén yǐ tóu piào fāng shì biǎo dá tā mén de yuàn wàng。","meaning":"The people make their wishes known through the ballot box.","meaningThai":"ประชาชนแสดงความปรารถนาของตนผ่านตู้ลงคะแนน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1423","chinese":"原则","pinyin":"yuánzé","meaning":"principle; doctrine","meaningThai":"ในหลักการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她总是信守自己的政治原则。","pinyin":"Tā zǒng shì xìn shǒu zì jǐ de zhèng zhì yuán zé。","meaning":"She has always remained loyal to her political principles.","meaningThai":"เธอยังคงภักดีต่อหลักการทางการเมืองของเธอมาโดยตลอด"},{"chinese":"新宪法包括联邦主义的原则。","pinyin":"Xīn xiàn fǎ bāo kuò lián bāng zhǔ yì de yuán zé。","meaning":"The new constitution includes federalist principles.","meaningThai":"รัฐธรรมนูญฉบับใหม่ประกอบด้วยหลักการของสหพันธรัฐ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1424","chinese":"预报","pinyin":"yùbào","meaning":"forecast","meaningThai":"การพยากรณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"天气预报说明天有雨。","pinyin":"Tiān qi yù bào shuō míng tiān yǒu yǔ.","meaning":"The forecast says rain tomorrow.","meaningThai":"พยากรณ์บอกว่าพรุ่งนี้ฝนจะตก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1425","chinese":"预测","pinyin":"yùcè","meaning":"to forecast; to predict","meaningThai":"ทำนาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"报告预测下月物价将上涨3%。","pinyin":"Bào gào yù cè xià yuè wù jià jiāng shàng zhǎng3%。","meaning":"The report forecasts that prices will rise by 3% next month.","meaningThai":"รายงานคาดการณ์ว่าราคาจะเพิ่มขึ้น 3% ในเดือนหน้า"},{"chinese":"实验结果证实了我们的预测。","pinyin":"Shí yàn jié guǒ zhèng shí le wǒ mén de yù cè。","meaning":"The results of the experi we are pirates, these data are stolen from youdao  confirmed our predictions.","meaningThai":"ผลการทดลองยืนยันการคาดการณ์ของเรา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1426","chinese":"预订","pinyin":"yùdìng","meaning":"to place an order; to book ahead","meaningThai":"จอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我预订了一个房间。","pinyin":"Wǒ yù dìng le yī gè fáng jiān.","meaning":"I booked a room.","meaningThai":"ฉันจองห้องพักแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1427","chinese":"约定","pinyin":"yuēdìng","meaning":"to agree on sth (after discussion); to conclude a bargain; to arrange; to promise; to stipulate; to make an appointment; stipulated (time, amount, quality etc); an arrangement; a deal; appointment; undertaking; commitment; understanding; engagement; stipulation","meaningThai":"ข้อตกลง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她为儿子约定了看医生的时间。","pinyin":"Tā wéi ér zǐ yuē dìng le kàn yī shēng de shí jiān。","meaning":"She made an appointment for her son to see the doctor.","meaningThai":"เธอนัดลูกชายมาพบแพทย์"},{"chinese":"他们约定在家中绝不谈工作。","pinyin":"Tā mén yuē dìng zài jiā zhōng jué bù tán gōng zuò。","meaning":"They had an agreement never to talk about work at home.","meaningThai":"พวกเขามีข้อตกลงว่าจะไม่คุยเรื่องงานที่บ้าน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1428","chinese":"预防","pinyin":"yùfáng","meaning":"to prevent; to take precautions against; to protect; to guard against; precautionary; prophylactic","meaningThai":"การป้องกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"预防在传统医学中也起着主导作用。","pinyin":"Yù fáng zài chuán tǒng yī xué zhōng yě qǐ zháo zhǔ dǎo zuò yòng。","meaning":"Prevention also plays a central role in traditional medicine.","meaningThai":"การป้องกันยังมีบทบาทสำคัญในการแพทย์แผนโบราณอีกด้วย"},{"chinese":"进一步治疗将预防癌症恶化。","pinyin":"Jìn yī bù zhì liáo jiāng yù fáng ái zhèng è huà。","meaning":"Further treatment will prevent cancer from developing.","meaningThai":"การรักษาต่อไปจะป้องกันไม่ให้มะเร็งเกิดขึ้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1429","chinese":"预计","pinyin":"yùjì","meaning":"to forecast; to predict; to estimate","meaningThai":"ที่คาดหวัง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"预计保险索赔会急剧增加。","pinyin":"Yù jì bǎo xiǎn suǒ péi huì jí jù zēng jiā。","meaning":"Insurance claims are expected to soar.","meaningThai":"คาดว่าการเคลมประกันจะเพิ่มขึ้น"},{"chinese":"我们预计要来三十人左右。","pinyin":"Wǒ mén yù jì yào lái sān shí rén zuǒ yòu。","meaning":"We are expecting thirty or so people to come.","meaningThai":"เราคาดว่าจะมีคนมาประมาณสามสิบคน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1430","chinese":"娱乐","pinyin":"yúlè","meaning":"to entertain; to amuse; entertainment; recreation; amusement; hobby; fun; joy","meaningThai":"บันเทิง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"娱乐活动。","pinyin":"Yu le huo dong.","meaning":"Entertainment activities.","meaningThai":"กิจกรรมบันเทิง"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-1431","chinese":"玉米","pinyin":"yùmǐ","meaning":"corn; maize","meaningThai":"ข้าวโพด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"這玉米很新鮮。","pinyin":"Zhè yù mǐ hěn xīn xiān。","meaning":"This corn is fresh.","meaningThai":"ข้าวโพดอันนี้สด"},{"chinese":"我不喜歡玉米。","pinyin":"Wǒ bù xǐ huān yù mǐ。","meaning":"I don't like corn.","meaningThai":"ฉันไม่ชอบข้าวโพด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1432","chinese":"运","pinyin":"yùn","meaning":"to move; to transport; to use; to apply; fortune; luck; fate","meaningThai":"ขนส่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"运土卡车和水泥搅拌车都闲置着。","pinyin":"Yùn tǔ kǎ chē hé shuǐ ní jiǎo bàn chē dū xián zhì zháo。","meaning":"The earth-moving trucks and cement mixers lay idle.","meaningThai":"รถบรรทุกขนดินและเครื่องผสมปูนซีเมนต์ไม่ได้ใช้งาน"},{"chinese":"刑警们把尸体装进了一个运尸袋。","pinyin":"Xíng jǐng mén bǎ shī tǐ zhuāng jìn le yī gè yùn shī dài。","meaning":"Detectives placed the corpse in a body bag.","meaningThai":"เจ้าหน้าที่นำศพใส่ถุงใส่ศพ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1433","chinese":"运费","pinyin":"yùnfèi","meaning":"freight","meaningThai":"ค่าขนส่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"此外，买主需要核实售价中是否包含运费。","pinyin":"Cǐ wài， mǎi zhǔ xū yào hé shí shòu jià zhōng shì fǒu bāo hán yùn fèi。","meaning":"Again, buyers need to check if carriage is included in the price.","meaningThai":"ผู้ซื้อจะต้องตรวจสอบอีกครั้งว่าราคารวมค่าขนส่งแล้วหรือไม่"},{"chinese":"运费包括在账内。","pinyin":"Yùn fèi bāo kuò zài zhàng nèi。","meaning":"The freight is included in the account.","meaningThai":"ค่าขนส่งจะรวมอยู่ในบัญชี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1434","chinese":"运气","pinyin":"yùnqi","meaning":"luck (good or bad)","meaningThai":"โชค","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人们普遍认为他们的运气不佳。","pinyin":"Rén mén pǔ biàn rèn wéi tā mén de yùn qì bù jiā。","meaning":"They were widely perceived to have been unlucky.","meaningThai":"พวกเขาถูกมองว่าโชคร้าย"},{"chinese":"我们能去是我们的运气好。","pinyin":"Wǒ mén néng qù shì wǒ mén de yùn qì hǎo。","meaning":"It was lucky for us that we were able to go.","meaningThai":"โชคดีนะที่เราได้ไป"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1435","chinese":"运输","pinyin":"yùnshū","meaning":"to transport; to carry; transportation","meaningThai":"การขนส่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"行李正迅速被装好收起以便运输。","pinyin":"Háng lǐ zhèng xùn sù bèi zhuāng hǎo shōu qǐ yǐ biàn yùn shū。","meaning":"The baggage was being rapidly stowed away for transportation.","meaningThai":"สัมภาระถูกจัดเก็บอย่างรวดเร็วเพื่อการขนส่ง"},{"chinese":"货物在运输期间受损。","pinyin":"Huò wù zài yùn shū qī jiān shòu sǔn。","meaning":"The goods were damaged during transport.","meaningThai":"สินค้าได้รับความเสียหายระหว่างการขนส่ง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1436","chinese":"运用","pinyin":"yùnyòng","meaning":"to use; to put to use","meaningThai":"ใช้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她运用了自己最有魅力的嗓音。","pinyin":"Tā yùn yòng le zì jǐ zuì yǒu mèi lì de sǎng yīn。","meaning":"She used her most seductive voice.","meaningThai":"เธอใช้เสียงที่เย้ายวนใจที่สุดของเธอ"},{"chinese":"这位艺术家娴熟地运用了明暗对比。","pinyin":"Zhè wèi yì shù jiā xián shú dì yùn yòng le míng àn duì bǐ。","meaning":"The artist's use of contrast is masterly.","meaningThai":"การใช้คอนทราสต์ของศิลปินนั้นเชี่ยวชาญ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1437","chinese":"语气","pinyin":"yǔqì","meaning":"tone; manner of speaking; mood","meaningThai":"โทน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他说话的语气变得严肃起来。","pinyin":"Tā shuō huà de yǔ qì biàn dé yán sù qǐ lái。","meaning":"His voice took on a more serious tone.","meaningThai":"น้ำเสียงของเขามีน้ำเสียงจริงจังมากขึ้น"},{"chinese":"这次讲话的语气颇为乐观。","pinyin":"Zhè cì jiǎng huà de yǔ qì pō wéi lè guān。","meaning":"The tone of the speech was upbeat.","meaningThai":"น้ำเสียงของคำพูดมีจังหวะดี"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1438","chinese":"雨水","pinyin":"yǔshuǐ","meaning":"Yushui or Rain Water, 2nd of the 24 solar terms 二十四节气 19th February-5th March","meaningThai":"น้ำฝน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"雨水已将这片草地变成了沼泽。","pinyin":"Yǔ shuǐ yǐ jiāng zhè piàn cǎo dì biàn chéng le zhǎo zé。","meaning":"Rain had turned the grass into a quagmire.","meaningThai":"ฝนตกทำให้หญ้ากลายเป็นหล่ม"},{"chinese":"9月的雨水之后，土壤适度湿润。","pinyin":"9 yuè de yǔ shuǐ zhī hòu， tǔ rǎng shì dù shī rùn。","meaning":"The soil is reasonably moist after the September rain.","meaningThai":"ดินมีความชื้นพอสมควรหลังฝนตกในเดือนกันยายน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1439","chinese":"语文","pinyin":"yǔwén","meaning":"Chinese","meaningThai":"ภาษาจีน (วิชา)","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我最喜欢语文课。","pinyin":"Wǒ zuì xǐ huān yǔ wén kè.","meaning":"I like Chinese class the most.","meaningThai":"ฉันชอบวิชาภาษาจีนมากที่สุด"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1440","chinese":"语音","pinyin":"yǔyīn","meaning":"speech sounds; pronunciation; colloquial (rather than literary) pronunciation of a Chinese character; phonetic; audio; voice; (Internet) to voice chat; voice message","meaningThai":"เสียง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们学习了语音、重读和语调。","pinyin":"Wǒ mén xué xí le yǔ yīn、 zhòng dú hé yǔ tiáo。","meaning":"We worked on pronunciation, stress and intonation.","meaningThai":"เราฝึกเรื่องการออกเสียง ความเครียด และน้ำเสียง"},{"chinese":"我的语音信箱里有她含混不清的留言。","pinyin":"Wǒ de yǔ yīn xìn xiāng lǐ yǒu tā hán hùn bù qīng de liú yán。","meaning":"There was a garbled message from her on my voicemail.","meaningThai":"มีข้อความที่อ่านไม่ออกจากเธอในวอยซ์เมลของฉัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1441","chinese":"预约","pinyin":"yùyuē","meaning":"booking; reservation; to book; to make an appointment","meaningThai":"จอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"如果电话预约，你就免得等了。","pinyin":"Rú guǒ diàn huà yù yuē， nǐ jiù miǎn dé děng le。","meaning":"If you phone for an appointment, it'll save you waiting.","meaningThai":"หากคุณโทรศัพท์เพื่อนัดหมายก็จะช่วยให้คุณประหยัดเวลาในการรอ"},{"chinese":"只有预约方可察看这处房产。","pinyin":"Zhī yǒu yù yuē fāng kě chá kàn zhè chǔ fáng chǎn。","meaning":"The property can only be viewed by appointment.","meaningThai":"สามารถดูทรัพย์สินได้โดยการนัดหมายเท่านั้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1442","chinese":"在场","pinyin":"zàichǎng","meaning":"to be present; to be on the scene","meaningThai":"ปัจจุบัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"据我回忆，当时她不在场。","pinyin":"Jù wǒ huí yì， dāng shí tā bù zài cháng。","meaning":"As far as I can recollect, she wasn't there on that occasion.","meaningThai":"เท่าที่ผมจำได้ ตอนนั้นเธอไม่ได้อยู่ที่นั่นด้วย"},{"chinese":"我无法确定谁当时在场。","pinyin":"Wǒ wú fǎ què dìng shuí dāng shí zài cháng。","meaning":"I'm not certain who was there.","meaningThai":"ฉันไม่แน่ใจว่าใครอยู่ที่นั่น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1443","chinese":"在乎","pinyin":"zàihu","meaning":"to care about; equivalent of 在于","meaningThai":"การดูแล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你似乎不再在乎，这令我担忧。","pinyin":"Nǐ sì hū bù zài zài hū， zhè líng wǒ dān yōu。","meaning":"It concerns me that you no longer seem to care.","meaningThai":"มันทำให้ฉันกังวลว่าคุณดูเหมือนจะไม่สนใจอีกต่อไป"},{"chinese":"他不在乎人们怎样看他。","pinyin":"Tā bù zài hū rén mén zěn yàng kàn tā。","meaning":"He doesn't care what people think of him.","meaningThai":"เขาไม่สนใจว่าคนอื่นจะคิดอย่างไรกับเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1444","chinese":"在内","pinyin":"zàinèi","meaning":"(included) in it; among them","meaningThai":"ภายใน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"三个退伍军人在内海一个小镇边上租了一套房子，并生活在一起。","pinyin":"Sān gè tuì wǔ jūn rén zài nèi hǎi yī gè xiǎo zhèn biān shàng zū le yī tào fáng zǐ， bìng shēng huó zài yī qǐ。","meaning":"Three soldiers who came back from the war are renting a house at the edge of a small town on the shore of the Inland Sea and live together.","meaningThai":"ทหารสามคนที่กลับมาจากสงครามกำลังเช่าบ้านหลังเล็ก ๆ ริมชายฝั่งทะเลในและอาศัยอยู่ร่วมกัน"}],"partOfSpeech":["particle","verb"]},
  {"id":"hsk5-1445","chinese":"在线","pinyin":"zàixiàn","meaning":"online","meaningThai":"ออนไลน์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在线课程越来越流行。","pinyin":"Zài xiàn kè chéng yuè lái yuè liú xíng.","meaning":"Online courses are becoming more popular.","meaningThai":"หลักสูตรออนไลน์กำลังได้รับความนิยมมากขึ้น"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-1446","chinese":"在于","pinyin":"zàiyú","meaning":"to be in; to lie in; to consist in; to depend on; to rest with","meaningThai":"อยู่ใน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们的成功在于商品的质量。","pinyin":"Tā mén de chéng gōng zài yú shāng pǐn de zhì liáng。","meaning":"Their success is ascribable to the quality of their goods.","meaningThai":"ความสำเร็จของพวกเขาขึ้นอยู่กับคุณภาพของสินค้าของพวกเขา"},{"chinese":"问题在于决定何时介入。","pinyin":"Wèn tí zài yú jué dìng hé shí jiè rù。","meaning":"The problem lies in deciding when to intervene.","meaningThai":"ปัญหาอยู่ที่การตัดสินใจว่าจะเข้าแทรกแซงเมื่อใด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1447","chinese":"赞成","pinyin":"zànchéng","meaning":"to approve; to endorse; (literary) to assist","meaningThai":"เห็นด้วย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"95%的人投票赞成新宪法。","pinyin":"95% de rén tóu piào zàn chéng xīn xiàn fǎ。","meaning":"About ninety-five per cent of those who cast their votes approve the new constitution.","meaningThai":"ประมาณร้อยละเก้าสิบห้าของผู้ลงคะแนนเสียงเห็นชอบรัฐธรรมนูญฉบับใหม่"},{"chinese":"你赞成还是反对死刑？","pinyin":"Nǐ zàn chéng huán shì fǎn duì sǐ xíng？","meaning":"Are you for or against the death penalty?","meaningThai":"คุณสนับสนุนหรือต่อต้านโทษประหารชีวิตหรือไม่?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1448","chinese":"造","pinyin":"zào","meaning":"to make; to build; to manufacture; to invent; to fabricate; to go to; party (in a lawsuit or legal agreement); crop; classifier for crops","meaningThai":"ทำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"彼得已经造好了悬挂梯，第二天他就把它们装在了墙上。","pinyin":"Bǐ dé yǐ jīng zào hǎo le xuán guà tī， dì èr tiān tā jiù bǎ tā mén zhuāng zài le qiáng shàng。","meaning":"Peter had built the overhead ladders, and the next day he fitted them to the wall.","meaningThai":"เปโตรได้สร้างบันไดเหนือศีรษะ และในวันรุ่งขึ้นเขาก็ติดบันไดไว้กับผนัง"},{"chinese":"我都已经造好了。","pinyin":"Wǒ dū yǐ jīng zào hǎo le。","meaning":"I've already built it.","meaningThai":"ฉันได้สร้างมันแล้ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1449","chinese":"糟","pinyin":"zāo","meaning":"dregs; draff; pickled in wine; rotten; messy; ruined","meaningThai":"แย่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"哦，好啦，情况并不是那么糟。","pinyin":"Ó， hǎo lā， qíng kuàng bìng bù shì nà mó zāo。","meaning":"Oh come now, things aren't as bad as all that.","meaningThai":"โอ้ มาตอนนี้ สิ่งต่างๆ ก็ไม่ได้เลวร้ายขนาดนั้น"},{"chinese":"客观地看，局面并不算太糟。","pinyin":"Kè guān dì kàn， jú miàn bìng bù suàn tài zāo。","meaning":"Looked at objectively, the situation is not too bad.","meaningThai":"เมื่อมองอย่างเป็นกลางแล้ว สถานการณ์ก็ไม่ได้เลวร้ายนัก"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1450","chinese":"造成","pinyin":"zàochéng","meaning":"to bring about; to create; to cause","meaningThai":"สาเหตุ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"街道狭窄，造成很多交通问题。","pinyin":"Jiē dào xiá zhǎi， zào chéng hěn duō jiāo tōng wèn tí。","meaning":"The narrowness of the streets caused many traffic problems.","meaningThai":"ความแคบของถนนทำให้เกิดปัญหาการจราจรมากมาย"},{"chinese":"恒河泛滥时造成严重损害。","pinyin":"Héng hé fàn làn shí zào chéng yán zhòng sǔn hài。","meaning":"When the Ganges floods, it causes considerable damage.","meaningThai":"เมื่อน้ำท่วมคงคาจะสร้างความเสียหายอย่างมาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1451","chinese":"糟糕","pinyin":"zāogāo","meaning":"too bad; how terrible; what bad luck; terrible; bad","meaningThai":"อ๊ะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"糟糕的饮食终将导致疾病。","pinyin":"Zāo gāo de yǐn shí zhōng jiāng dǎo zhì jí bìng。","meaning":"A poor diet will ultimately lead to illness.","meaningThai":"การรับประทานอาหารที่ไม่ดีจะนำไปสู่การเจ็บป่วยในที่สุด"},{"chinese":"我到过糟糕得多的地方。","pinyin":"Wǒ dào guò zāo gāo dé duō de dì fāng。","meaning":"I've been to far worse places.","meaningThai":"ฉันเคยไปสถานที่ที่แย่กว่านั้นมาก"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1452","chinese":"早期","pinyin":"zǎoqī","meaning":"early period; early phase; early stage","meaningThai":"วันแรก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"早期手术可以抑制病情的发展。","pinyin":"Zǎo qī shǒu shù kě yǐ yì zhì bìng qíng de fā zhǎn。","meaning":"The progression of the disease can be retarded by early surgery.","meaningThai":"การลุกลามของโรคสามารถชะลอได้ด้วยการผ่าตัดตั้งแต่เนิ่นๆ"},{"chinese":"这些结果与早期的发现相矛盾。","pinyin":"Zhè xiē jié guǒ yǔ zǎo qī de fā xiàn xiāng máo dùn。","meaning":"These results conflict with earlier findings.","meaningThai":"ผลลัพธ์เหล่านี้ขัดแย้งกับผลการวิจัยก่อนหน้านี้"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1453","chinese":"早晚","pinyin":"zǎowǎn","meaning":"morning and evening; (dialect) some time in the future; some day","meaningThai":"ไม่ช้าก็เร็ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我們早晚要死。","pinyin":"Wǒ mén zǎo wǎn yào sǐ。","meaning":"We shall die sooner or later. / We will die sooner or later. / We'll die sooner or later.","meaningThai":"เราคงตายไม่ช้าก็เร็ว / เราจะตายไม่ช้าก็เร็ว / เราจะตายไม่ช้าก็เร็ว"},{"chinese":"我今早晚了起床。","pinyin":"Wǒ jīn zǎo wǎn le qǐ chuáng。","meaning":"I got up late this morning.","meaningThai":"ฉันตื่นสายเมื่อเช้านี้"}],"partOfSpeech":["adverb","other"]},
  {"id":"hsk5-1454","chinese":"早已","pinyin":"zǎoyǐ","meaning":"for a long time; long since; (dialect) in the past","meaningThai":"เรียบร้อยแล้ว","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"事情早已发生，痛哭流涕也于事无补。","pinyin":"Shì qíng zǎo yǐ fā shēng， tòng kū liú tì yě yú shì wú bǔ。","meaning":"There's no point wailing about something that happened so long ago.","meaningThai":"ไม่มีประโยชน์ที่จะคร่ำครวญเกี่ยวกับบางสิ่งที่เกิดขึ้นเมื่อนานมาแล้ว"},{"chinese":"这座坟墓里的财宝早已被盗。","pinyin":"Zhè zuò fén mù lǐ de cái bǎo zǎo yǐ bèi dào。","meaning":"The tomb had been robbed of its treasures.","meaningThai":"สุสานถูกปล้นสมบัติไป"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1455","chinese":"赠","pinyin":"zèng","meaning":"to give as a present; to repel; to bestow an honorary title after death (old)","meaningThai":"ของขวัญ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"感谢赠我这份礼物，这正是我想要的。","pinyin":"Gǎn xiè zèng wǒ zhè fèn lǐ wù， zhè zhèng shì wǒ xiǎng yào de。","meaning":"Thanks for the present—it's just what I wanted.","meaningThai":"ขอบคุณสำหรับของขวัญ นั่นคือสิ่งที่ฉันต้องการ"},{"chinese":"他在退休时获赠这块手表。","pinyin":"Tā zài tuì xiū shí huò zèng zhè kuài shǒu biǎo。","meaning":"He was presented with the watch on the occasion of his retirement.","meaningThai":"เขาได้รับมอบนาฬิกาเรือนนี้เนื่องในโอกาสที่เขาเกษียณอายุ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1456","chinese":"增","pinyin":"zēng","meaning":"(bound form) to increase; to augment; to add to","meaningThai":"เพิ่มขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人口正在增長。","pinyin":"Rén kǒu zhèng zài zēng cháng。","meaning":"The population is growing.","meaningThai":"ประชากรมีการเติบโต"},{"chinese":"我增加了體重。","pinyin":"Wǒ zēng jiā le tǐ zhòng。","meaning":"I've gained weight.","meaningThai":"ฉันมีน้ำหนักเพิ่มขึ้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1457","chinese":"增进","pinyin":"zēngjìn","meaning":"to promote; to enhance; to further; to advance (a cause etc)","meaningThai":"ยกระดับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"辅助帆一片被绷在船头或船尾以增进航行区域的油布","pinyin":"Fǔ zhù fān yī piàn bèi bēng zài chuán tóu huò chuán wěi yǐ zēng jìn háng háng qū yù de yóu bù","meaning":"A strip of canvas laced to a fore-and-aft sail to increase sail area.","meaningThai":"แถบผ้าใบผูกติดกับใบเรือด้านหน้าและด้านหลังเพื่อเพิ่มพื้นที่การแล่นเรือ"},{"chinese":"他们把车厢上面的中央部分打开以增进空气的流通。","pinyin":"Tā mén bǎ chē xiāng shàng miàn de zhōng yāng bù fēn dǎ kāi yǐ zēng jìn kōng qì de liú tōng。","meaning":"They increased ventilation by opening the top center part of the carriage window.","meaningThai":"พวกมันเพิ่มการระบายอากาศโดยการเปิดส่วนตรงกลางด้านบนของหน้าต่างตัวบรรจุ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1458","chinese":"增强","pinyin":"zēngqiáng","meaning":"to increase; to strengthen","meaningThai":"ยกระดับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"克罗斯的兴趣增强了。","pinyin":"Kè luó sī de xīng qù zēng qiáng le。","meaning":"Cross's interest heightened.","meaningThai":"ความสนใจของครอสเพิ่มสูงขึ้น"},{"chinese":"双方仍在增强各自的军事力量。","pinyin":"Shuāng fāng réng zài zēng qiáng gè zì de jūn shì lì liáng。","meaning":"Both sides are still beefing up their military strength.","meaningThai":"ทั้งสองฝ่ายยังคงเพิ่มความแข็งแกร่งทางการทหาร"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1459","chinese":"赠送","pinyin":"zèngsòng","meaning":"to present as a gift","meaningThai":"ให้ออกไป","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们正在赠送2000件免费样品。","pinyin":"Wǒ mén zhèng zài zèng sòng 2000 jiàn miǎn fèi yàng pǐn。","meaning":"We're giving away 2,000 free samples.","meaningThai":"เราแจกตัวอย่างฟรี 2,000 ตัวอย่าง"},{"chinese":"家人把他的画作赠送给了美术馆。","pinyin":"Jiā rén bǎ tā de huà zuò zèng sòng gěi le měi shù guǎn。","meaning":"The family made a gift of his paintings to the gallery.","meaningThai":"ครอบครัวนี้ได้มอบภาพวาดของเขาเป็นของขวัญให้กับแกลเลอรี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1460","chinese":"炸","pinyin":"zhá","meaning":"to deep fry; Taiwan pr. [zhà]","meaningThai":"ทอด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"炸鸡很好吃。","pinyin":"Zha ji hen hao chi.","meaning":"Fried chicken is delicious.","meaningThai":"ไก่ทอดก็อร่อย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1461","chinese":"窄","pinyin":"zhǎi","meaning":"narrow; narrow-minded; badly off","meaningThai":"แคบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"河道变得又窄又浅，无法航行。","pinyin":"Hé dào biàn dé yòu zhǎi yòu qiǎn， wú fǎ háng háng。","meaning":"The river became too narrow and shallow to navigate.","meaningThai":"แม่น้ำแคบและตื้นเกินกว่าจะเดินเรือได้"},{"chinese":"道路太窄，汽车无法通过。","pinyin":"Dào lù tài zhǎi， qì chē wú fǎ tōng guò。","meaning":"The road was so narrow that cars were unable to pass.","meaningThai":"ถนนแคบมากจนรถยนต์ไม่สามารถผ่านได้"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1462","chinese":"摘","pinyin":"zhāi","meaning":"to take; to borrow; to pick (flowers, fruit etc); to pluck; to select; to remove; to take off (glasses, hat etc)","meaningThai":"เลือก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些浆果太小了，很难摘。","pinyin":"Zhè xiē jiāng guǒ tài xiǎo le， hěn nán zhāi。","meaning":"These berries are the devil to pick because they're so small.","meaningThai":"ผลเบอร์รี่เหล่านี้เป็นปีศาจที่จะเด็ดเพราะมันเล็กมาก"},{"chinese":"她弯下腰摘了一朵红玫瑰。","pinyin":"Tā wān xià yāo zhāi le yī duǒ hóng méi guī。","meaning":"She bent to pick a red rose.","meaningThai":"เธอก้มหยิบดอกกุหลาบสีแดง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1463","chinese":"占","pinyin":"zhàn","meaning":"variant of 占","meaningThai":"ครอบครอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"日本市场占该公司收入的35%。","pinyin":"Rì běn shì cháng zhān gāi gōng sī shōu rù de35%。","meaning":"The Japanese market accounts for 35% of the company's revenue.","meaningThai":"ตลาดญี่ปุ่นคิดเป็น 35% ของรายได้ของบริษัท"},{"chinese":"即便小飞机也占很多空间。","pinyin":"Jí biàn xiǎo fēi jī yě zhān hěn duō kōng jiān。","meaning":"Even small aircraft occupy a lot of space.","meaningThai":"แม้แต่เครื่องบินขนาดเล็กก็ใช้พื้นที่มาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1464","chinese":"展出","pinyin":"zhǎnchū","meaning":"to put on display; to be on show; to exhibit","meaningThai":"แสดง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"最新电脑软件将在展览会上展出。","pinyin":"Zuì xīn diàn nǎo ruǎn jiàn jiāng zài zhǎn lǎn huì shàng zhǎn chū。","meaning":"The latest software will be on parade at the exhibition.","meaningThai":"ซอฟต์แวร์ล่าสุดจะเข้าร่วมขบวนพาเหรดในนิทรรศการ"},{"chinese":"她计划明年初展出自己的绘画作品。","pinyin":"Tā jì huá míng nián chū zhǎn chū zì jǐ de huì huà zuò pǐn。","meaning":"She plans to show her paintings early next year.","meaningThai":"เธอวางแผนที่จะแสดงภาพวาดของเธอในต้นปีหน้า"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1465","chinese":"涨","pinyin":"zhǎng","meaning":"to rise (of prices, rivers)","meaningThai":"ลุกขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有些地区，房价能每月都涨。","pinyin":"Yǒu xiē dì qū， fáng jià néng měi yuè dū zhǎng。","meaning":"In some areas the property price can rise monthly.","meaningThai":"ในบางพื้นที่ราคาทรัพย์สินอาจเพิ่มขึ้นทุกเดือน"},{"chinese":"房价一直时涨时落，但最终应该会趋于稳定。","pinyin":"Fáng jià yī zhí shí zhǎng shí luò， dàn zuì zhōng yīng gāi huì qū yú wěn dìng。","meaning":"House prices keep rising and falling but they should eventually even out.","meaningThai":"ราคาบ้านขึ้นลงเรื่อยๆ แต่ในที่สุดราคาก็ควรจะกลับคืนมา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1466","chinese":"账号","pinyin":"zhànghào","meaning":"account; username","meaningThai":"บัญชี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"请问你的账号是多少？","pinyin":"Qǐng wèn nǐ de zhàng hào shì duō shǎo？","meaning":"What is your account number, please?","meaningThai":"กรุณาระบุหมายเลขบัญชีของคุณคืออะไร?"},{"chinese":"博物馆的社交媒体账号里充斥着支持此举的消息。","pinyin":"Bó wù guǎn de shè jiāo méi tǐ zhàng hào lǐ chōng chì zháo zhī chí cǐ jǔ de xiāo xī。","meaning":"The museum's social media account has been flooded with messages of support doing this.","meaningThai":"บัญชีโซเชียลมีเดียของพิพิธภัณฑ์เต็มไปด้วยข้อความสนับสนุนการดำเนินการนี้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1467","chinese":"账户","pinyin":"zhànghù","meaning":"bank account; online account","meaningThai":"บัญชี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"银行对那些账户不支付利息。","pinyin":"Yín háng duì nà xiē zhàng hù bù zhī fù lì xī。","meaning":"The banks don't pay interest on those accounts.","meaningThai":"ธนาคารไม่จ่ายดอกเบี้ยสำหรับบัญชีเหล่านั้น"},{"chinese":"我把支票存入我的储蓄账户。","pinyin":"Wǒ bǎ zhī piào cún rù wǒ de chǔ xù zhàng hù。","meaning":"I paid the cheque into my savings account.","meaningThai":"ฉันจ่ายเช็คเข้าบัญชีออมทรัพย์ของฉัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1468","chinese":"涨价","pinyin":"zhǎngjià","meaning":"to appreciate (in value); to increase in price","meaningThai":"ราคาเพิ่มขึ้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这一产业靠的是原料便宜，不涨价。","pinyin":"Zhè yī chǎn yè kào de shì yuán liào biàn yí， bù zhǎng jià。","meaning":"The industry relies on the price of raw materials remaining low.","meaningThai":"อุตสาหกรรมต้องอาศัยราคาวัตถุดิบที่เหลืออยู่ในระดับต่ำ"},{"chinese":"香烟又要涨价。","pinyin":"Xiāng yān yòu yào zhǎng jià。","meaning":"The price of cigarettes is set to rise again.","meaningThai":"ราคาบุหรี่กลับพุ่งสูงขึ้นอีกครั้ง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1469","chinese":"掌声","pinyin":"zhǎngshēng","meaning":"applause","meaningThai":"ปรบมือ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的讲演不时被阵阵掌声打断。","pinyin":"Tā de jiǎng yǎn bù shí bèi zhèn zhèn zhǎng shēng dǎ duàn。","meaning":"Her speech was punctuated by bursts of applause.","meaningThai":"คำพูดของเธอถูกคั่นด้วยเสียงปรบมือดังลั่น"},{"chinese":"全场观众爆发出响亮的掌声。","pinyin":"Quán cháng guān zhòng bào fā chū xiǎng liàng de zhǎng shēng。","meaning":"The entire audience broke into loud applause.","meaningThai":"ผู้ชมทั้งหมดต่างปรบมือดังลั่น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1470","chinese":"掌握","pinyin":"zhǎngwò","meaning":"to grasp (often fig.); to control; to seize (initiative, opportunity, destiny); to master; to know well; to understand sth well and know how to use it; fluency","meaningThai":"ผู้เชี่ยวชาญ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"掌握一门外语很难。","pinyin":"Zhǎng wò yī mén wài yǔ hěn nán。","meaning":"Mastering a foreign language is difficult.","meaningThai":"การเรียนรู้ภาษาต่างประเทศเป็นเรื่องยาก"},{"chinese":"他很快就掌握了俄語。","pinyin":"Tā hěn kuài jiù zhǎng wò le é yǔ。","meaning":"He acquired Russian quickly.","meaningThai":"เขาได้รับภาษารัสเซียอย่างรวดเร็ว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1471","chinese":"展开","pinyin":"zhǎnkāi","meaning":"to unfold; to spread out; to open up; to launch; to carry out","meaningThai":"ขยาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"警方展开了全面的调查。","pinyin":"Jǐng fāng zhǎn kāi le quán miàn de tiáo chá。","meaning":"The police carried out a thorough investigation.","meaningThai":"ตำรวจได้ทำการสอบสวนอย่างละเอียด"},{"chinese":"抖动绳索把绳圈展开。","pinyin":"Dǒu dòng shéng suǒ bǎ shéng quān zhǎn kāi。","meaning":"Shake the rope and let the coils unwind.","meaningThai":"เขย่าเชือกแล้วปล่อยให้ขดคลายออก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1472","chinese":"展览","pinyin":"zhǎnlǎn","meaning":"to put on display; to exhibit; exhibition; show","meaningThai":"นิทรรศการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"艺术展览。","pinyin":"Yi shu zhan lan.","meaning":"Art exhibition.","meaningThai":"นิทรรศการศิลปะ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1473","chinese":"展示","pinyin":"zhǎnshì","meaning":"to reveal; to display; to show; to exhibit","meaningThai":"จัดแสดง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我給他展示了我的臥室。","pinyin":"Wǒ gěi tā zhǎn shì le wǒ de wò shì。","meaning":"I showed him my bedroom.","meaningThai":"ฉันให้เขาดูห้องนอนของฉัน"},{"chinese":"我给她展示了我的房间。","pinyin":"Wǒ gěi tā zhǎn shì le wǒ de fáng jiān。","meaning":"I showed her my room.","meaningThai":"ฉันพาเธอไปดูห้องของฉัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1474","chinese":"站台","pinyin":"zhàntái","meaning":"platform (at a railway station); (Tw) (of an influential person) to publicly lend one's support (e.g. for an election candidate); (Tw) website","meaningThai":"แพลตฟอร์ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他沿站台猛跑，纵身跳上火车。","pinyin":"Tā yán zhàn tái měng pǎo， zòng shēn tiào shàng huǒ chē。","meaning":"He dashed along the platform and jumped on the train.","meaningThai":"เขารีบวิ่งไปตามชานชาลาแล้วกระโดดขึ้นรถไฟ"},{"chinese":"去爱丁堡的火车在4号站台等候。","pinyin":"Qù ài dīng bǎo de huǒ chē zài 4 hào zhàn tái děng hòu。","meaning":"The Edinburgh train is waiting at platform 4.","meaningThai":"รถไฟเอดินบะระรออยู่ที่ชานชาลา 4"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1475","chinese":"占线","pinyin":"zhànxiàn","meaning":"busy (telephone line)","meaningThai":"ยุ่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"分机现在占线。您能等一会吗？","pinyin":"Fēn jī xiàn zài zhān xiàn。 nín néng děng yī huì ma？","meaning":"That extension is busy right now. Can you hold?","meaningThai":"ส่วนขยายนั้นไม่ว่างในขณะนี้ ถือได้ไหม?"},{"chinese":"占线—我过会儿再打。","pinyin":"Zhān xiàn — wǒ guò huì ér zài dǎ。","meaning":"The line is busy—I'll try again later.","meaningThai":"สายไม่ว่าง ฉันจะลองอีกครั้งในภายหลัง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1476","chinese":"展现","pinyin":"zhǎnxiàn","meaning":"to unfold before one's eyes; to emerge; to reveal; to display","meaningThai":"แสดง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她的表演展现了精湛的技艺。","pinyin":"Tā de biǎo yǎn zhǎn xiàn le jīng zhàn de jì yì。","meaning":"Her performance displayed great art.","meaningThai":"การแสดงของเธอแสดงศิลปะที่ยอดเยี่ยม"},{"chinese":"还没有反对总统的公开展现。","pinyin":"Huán méi yǒu fǎn duì zǒng tǒng de gōng kāi zhǎn xiàn。","meaning":"There's been no public demonstration of opposition to the president.","meaningThai":"ไม่มีการสาธิตต่อสาธารณะต่อประธานาธิบดี"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1477","chinese":"召开","pinyin":"zhàokāi","meaning":"to convene (a conference or meeting); to convoke; to call together","meaningThai":"ประชุม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"定期召开会议监控案件的进展情况。","pinyin":"Dìng qī zhào kāi huì yì jiān kòng àn jiàn de jìn zhǎn qíng kuàng。","meaning":"Meetings are held periodically to monitor progress on the case.","meaningThai":"มีการประชุมติดตามความคืบหน้าของคดีเป็นระยะ"},{"chinese":"事故后调查委员会立即召开了会议。","pinyin":"Shì gù hòu tiáo chá wěi yuán huì lì jí zhào kāi le huì yì。","meaning":"A Board of Inquiry was convened immediately after the accident.","meaningThai":"คณะกรรมการสอบสวนถูกเรียกประชุมทันทีหลังเกิดอุบัติเหตุ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1478","chinese":"着凉","pinyin":"zháoliáng","meaning":"to catch cold; Taiwan pr. [zhāo liáng]","meaningThai":"เป็นหวัด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"别站在风口上，小心着凉。","pinyin":"Bié zhàn zài fēng kǒu shàng， xiǎo xīn zháo liáng。","meaning":"Don't stand in the draught. You may catch cold.","meaningThai":"อย่ายืนอยู่ในร่าง คุณอาจเป็นหวัดได้"},{"chinese":"别让她着凉，你听见了吗？","pinyin":"Bié ràng tā zháo liáng， nǐ tīng jiàn le ma？","meaning":"Don't let her get cold, do you hear?","meaningThai":"อย่าปล่อยให้เธอเป็นหวัดคุณได้ยินไหม?"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1479","chinese":"折扣","pinyin":"zhékòu","meaning":"discount","meaningThai":"การลดราคา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"早到早得的折扣通常在季初有。","pinyin":"Zǎo dào zǎo dé de zhē kòu tōng cháng zài jì chū yǒu。","meaning":"Early bird discounts are usually available at the beginning of the season.","meaningThai":"โดยปกติแล้วส่วนลดสำหรับนกล่วงหน้าจะมีให้ในช่วงต้นฤดูกาล"},{"chinese":"商业折扣可以用作保持顾客忠诚度的一种竞争策略。","pinyin":"Shāng yè zhē kòu kě yǐ yòng zuò bǎo chí gù kè zhōng chéng dù de yī zhǒng jìng zhēng cè lüè。","meaning":"Trade discounts may be used as a competitive stratagem to secure customer loyalty.","meaningThai":"ส่วนลดการค้าอาจใช้เป็นกลยุทธ์การแข่งขันเพื่อรักษาความภักดีของลูกค้า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1480","chinese":"阵","pinyin":"zhèn","meaning":"disposition of troops; wave; spate; burst; spell; short period of time; classifier for events or states of short duration","meaningThai":"อาร์เรย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这一阵我很忙！","pinyin":"Zhè yī zhèn wǒ hěn máng！","meaning":"I'm very busy these days. / I am very busy these days. / I'm very busy these days!","meaningThai":"ช่วงนี้ฉันยุ่งมาก / ช่วงนี้ฉันยุ่งมาก / ช่วงนี้ฉันยุ่งมาก!"},{"chinese":"明天天气晴转阵雨。","pinyin":"Míng tiān tiān qì qíng zhuǎn zhèn yǔ。","meaning":"Tomorrow's weather should be sunny with occasional rain.","meaningThai":"พรุ่งนี้อากาศน่าจะมีแดดจัดและมีฝนตกบ้าง"}],"partOfSpeech":["other","verb"]},
  {"id":"hsk5-1481","chinese":"真诚","pinyin":"zhēnchéng","meaning":"sincere; genuine; true","meaningThai":"จริงใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我不会原谅你，除非你真诚地道歉。","pinyin":"Wǒ bù huì yuán liàng nǐ， chú fēi nǐ zhēn chéng dì dào qiàn。","meaning":"I won’t forgive you unless you apologise sincerely.","meaningThai":"ฉันจะไม่ให้อภัยคุณ เว้นแต่คุณจะขอโทษอย่างจริงใจ"},{"chinese":"任何情绪，只要它是真诚的，就说明它是发自内心的自然流露。","pinyin":"Rèn hé qíng xù， zhī yào tā shì zhēn chéng de， jiù shuō míng tā shì fā zì nèi xīn de zì rán liú lòu。","meaning":"Any emotion, if it is sincere, is involuntary.","meaningThai":"อารมณ์ใด ๆ ถ้ามันจริงใจก็ไม่สมัครใจ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1482","chinese":"诊断","pinyin":"zhěnduàn","meaning":"to diagnose","meaningThai":"วินิจฉัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"医生诊断。","pinyin":"Yi sheng zhen duan.","meaning":"Doctor's diagnosis.","meaningThai":"การวินิจฉัยของแพทย์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1483","chinese":"针对","pinyin":"zhēnduì","meaning":"to target; to focus on; to be aimed at or against; in response to","meaningThai":"ขัดต่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他要求完全收回针对他的言论。","pinyin":"Tā yào qiú wán quán shōu huí zhēn duì tā de yán lùn。","meaning":"He demanded a full retraction of the allegations against him.","meaningThai":"เขาเรียกร้องให้เพิกถอนข้อกล่าวหาที่มีต่อเขาโดยสมบูรณ์"},{"chinese":"我的批评不是针对你的。","pinyin":"Wǒ de pī píng bù shì zhēn duì nǐ de。","meaning":"My criticism wasn't aimed at you.","meaningThai":"คำวิจารณ์ของฉันไม่ได้มุ่งเป้าไปที่คุณ"}],"partOfSpeech":["preposition","verb"]},
  {"id":"hsk5-1484","chinese":"挣","pinyin":"zhèng","meaning":"used in 挣扎","meaningThai":"ได้รับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我不怪他们想要挣些钱。","pinyin":"Wǒ bù guài tā mén xiǎng yào zhèng xiē qián。","meaning":"I do not blame them for trying to make some money.","meaningThai":"ฉันไม่โทษพวกเขาที่พยายามหาเงิน"},{"chinese":"他挣的钱不如我多。","pinyin":"Tā zhèng de qián bù rú wǒ duō。","meaning":"He doesn't earn as much as I do.","meaningThai":"เขามีรายได้ไม่มากเท่าฉัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1485","chinese":"争","pinyin":"zhēng","meaning":"to strive for; to vie for; to argue or debate; deficient or lacking (dialect); how or what (literary)","meaningThai":"ต่อสู้","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他在争球时受了伤。","pinyin":"Tā zài zhēng qiú shí shòu le shāng。","meaning":"He was injured during a tussle for the ball.","meaningThai":"เขาได้รับบาดเจ็บระหว่างแย่งบอล"},{"chinese":"律师和会计师都觉得他们要一争高下。","pinyin":"Lǜ shī hé huì jì shī dū jué dé tā mén yào yī zhēng gāo xià。","meaning":"Lawyers and accountants felt that they were being pitted against each other.","meaningThai":"ทนายความและนักบัญชีรู้สึกว่าพวกเขากำลังถูกแย่งชิงกัน"}],"partOfSpeech":["verb","other"]},
  {"id":"hsk5-1486","chinese":"政府","pinyin":"zhèngfǔ","meaning":"government","meaningThai":"รัฐบาล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"政府负责提供医疗服务。","pinyin":"Zhèng fǔ fù zé tí gōng yī liáo fú wù。","meaning":"The government is responsible for the provision of health care.","meaningThai":"รัฐบาลมีหน้าที่รับผิดชอบในการให้บริการด้านสุขภาพ"},{"chinese":"政府已承诺铲除腐败。","pinyin":"Zhèng fǔ yǐ chéng nuò chǎn chú fǔ bài。","meaning":"The government has pledged itself to root out corruption.","meaningThai":"รัฐบาลได้ให้คำมั่นที่จะกำจัดการทุจริต"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1487","chinese":"证据","pinyin":"zhèngjù","meaning":"evidence; proof; testimony","meaningThai":"หลักฐาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些结论与证据完全相悖。","pinyin":"Zhè xiē jié lùn yǔ zhèng jù wán quán xiāng bèi。","meaning":"These conclusions are totally at variance with the evidence.","meaningThai":"ข้อสรุปเหล่านี้ขัดแย้งกับหลักฐานโดยสิ้นเชิง"},{"chinese":"证据似乎指向那个方向。","pinyin":"Zhèng jù sì hū zhǐ xiàng nà gè fāng xiàng。","meaning":"The evidence seems to point in that direction.","meaningThai":"หลักฐานดูเหมือนจะชี้ไปในทิศทางนั้น"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1488","chinese":"整齐","pinyin":"zhěngqí","meaning":"orderly; neat; even; tidy","meaningThai":"เรียบร้อย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"地板上的鞋子都整齐成双地摆着。","pinyin":"Dì bǎn shàng de xié zǐ dū zhěng qí chéng shuāng dì bǎi zháo。","meaning":"All the shoes on the floor were neatly paired.","meaningThai":"รองเท้าที่อยู่บนพื้นถูกจับคู่อย่างเรียบร้อย"},{"chinese":"她的头发整齐地梳到后面。","pinyin":"Tā de tóu fā zhěng qí dì shū dào hòu miàn。","meaning":"Her hair was neatly combed back.","meaningThai":"ผมของเธอถูกหวีไปข้างหลังอย่างเรียบร้อย"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1489","chinese":"争取","pinyin":"zhēngqǔ","meaning":"to fight for; to strive for; to win over","meaningThai":"พยายามเพื่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"争取使他获释的斗争声势日益加强。","pinyin":"Zhēng qǔ shǐ tā huò shì de dǒu zhēng shēng shì rì yì jiā qiáng。","meaning":"The fight for his release gathers momentum each day.","meaningThai":"การต่อสู้เพื่อปลดปล่อยเขารวบรวมแรงผลักดันในแต่ละวัน"},{"chinese":"他们终于争取到了那份合同。","pinyin":"Tā mén zhōng yú zhēng qǔ dào le nà fèn hé tóng。","meaning":"They were successful in winning the contract.","meaningThai":"พวกเขาประสบความสำเร็จในการคว้าสัญญา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1490","chinese":"正如","pinyin":"zhèngrú","meaning":"just as; precisely as","meaningThai":"เช่น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"正如任何此类图表，这是个简图。","pinyin":"Zhèng rú rèn hé cǐ lèi tú biǎo， zhè shì gè jiǎn tú。","meaning":"Like any such diagram, it is a simplification.","meaningThai":"เช่นเดียวกับแผนภาพอื่นๆ มันเป็นการทำให้ง่ายขึ้น"},{"chinese":"正如约翰已经变了，他妻子也变了。","pinyin":"Zhèng rú yuē hàn yǐ jīng biàn le， tā qī zǐ yě biàn le。","meaning":"Just as John has changed, so has his wife.","meaningThai":"จอห์นเปลี่ยนไปอย่างไร ภรรยาของเขาก็เปลี่ยนไปเช่นกัน"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-1491","chinese":"证书","pinyin":"zhèngshū","meaning":"credentials; certificate","meaningThai":"ใบรับรอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们接过证书，同时表示了谢意。","pinyin":"Tā mén jiē guò zhèng shū， tóng shí biǎo shì le xiè yì。","meaning":"They accepted their certificates with words of thanks.","meaningThai":"พวกเขารับใบรับรองด้วยคำขอบคุณ"},{"chinese":"我们建议你用挂号邮寄你的证书。","pinyin":"Wǒ mén jiàn yì nǐ yòng guà hào yóu jì nǐ de zhèng shū。","meaning":"We recommend that you send your certificates by recorded delivery.","meaningThai":"เราขอแนะนำให้คุณส่งใบรับรองของคุณโดยการบันทึกการจัดส่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1492","chinese":"整体","pinyin":"zhěngtǐ","meaning":"whole entity; entire body; synthesis; as a whole (situation, construction, team etc); global; macrocosm; integral; holistic; whole","meaningThai":"โดยรวม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个房间的整体氛围是舒适的。","pinyin":"Zhè gè fáng jiān de zhěng tǐ fēn wéi shì shū shì de。","meaning":"The overall ambience of the room is cosy.","meaningThai":"บรรยากาศโดยรวมของห้องพักดูอบอุ่นเป็นกันเอง"},{"chinese":"该宾馆的整体理念是轻松服务。","pinyin":"Gāi bīn guǎn de zhěng tǐ lǐ niàn shì qīng sōng fú wù。","meaning":"The whole ethos of the hotel is effortless service.","meaningThai":"หลักการทั้งหมดของโรงแรมคือการบริการที่ง่ายดาย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1493","chinese":"珍贵","pinyin":"zhēnguì","meaning":"precious","meaningThai":"ล้ำค่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"家人的支持对乔茜尤为珍贵。","pinyin":"Jiā rén de zhī chí duì qiáo qiàn yóu wéi zhēn guì。","meaning":"Her family's support is particularly precious to Josie.","meaningThai":"การสนับสนุนจากครอบครัวของเธอมีค่าต่อ Josie เป็นพิเศษ"},{"chinese":"有了地质地图、书籍和地图册，你就可以找到所有已探明的珍贵矿藏的位置。","pinyin":"Yǒu le dì zhì dì tú、 shū jí hé dì tú cè， nǐ jiù kě yǐ zhǎo dào suǒ yǒu yǐ tàn míng de zhēn guì kuàng cáng de wèi zhì。","meaning":"With geological maps, books, and atlases you can find out all the proven sites of precious minerals.","meaningThai":"ด้วยแผนที่ทางธรณีวิทยา หนังสือ และแผนที่ คุณสามารถค้นหาแหล่งแร่อันล้ำค่าที่ได้รับการพิสูจน์แล้วทั้งหมด"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1494","chinese":"整整","pinyin":"zhěngzhěng","meaning":"whole; full","meaningThai":"เต็ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"雨下了整整三个小时。","pinyin":"Yǔ xià le zhěng zhěng sān gè xiǎo shí。","meaning":"It rained solidly for three hours.","meaningThai":"ฝนตกหนักเป็นเวลาสามชั่วโมง"},{"chinese":"他整整睡了十个小时。","pinyin":"Tā zhěng zhěng shuì le shí gè xiǎo shí。","meaning":"He slept solidly for ten hours.","meaningThai":"เขานอนหลับสนิทเป็นเวลาสิบชั่วโมง"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1495","chinese":"政治","pinyin":"zhèngzhì","meaning":"politics; political","meaningThai":"การเมือง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"政治课讨论国家大事。","pinyin":"Zhèng zhì kè tǎo lùn guó jiā dà shì.","meaning":"Politics class discusses national affairs.","meaningThai":"ชั้นเรียนการเมืองอภิปรายเรื่องชาติ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1496","chinese":"真实","pinyin":"zhēnshí","meaning":"true; real","meaningThai":"ความเป็นจริง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“不真实！”她肯定地说道。","pinyin":"“ bù zhēn shí！” tā kěn dìng dì shuō dào。","meaning":"'Not true!' she said with conviction.","meaningThai":"'ไม่จริง!' เธอพูดด้วยความมั่นใจ"},{"chinese":"不，那不是梦。它是真实的。","pinyin":"Bù， nà bù shì mèng。 tā shì zhēn shí de。","meaning":"No, it wasn't a dream. It was real.","meaningThai":"ไม่ มันไม่ใช่ความฝัน มันเป็นเรื่องจริง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1497","chinese":"珍惜","pinyin":"zhēnxī","meaning":"to treasure; to value; to cherish","meaningThai":"หวงแหน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"目前人们很珍惜能放松的机会。","pinyin":"Mù qián rén mén hěn zhēn xī néng fàng sōng de jī huì。","meaning":"These days, people appreciate a chance to relax.","meaningThai":"ทุกวันนี้ผู้คนชื่นชมโอกาสที่จะได้พักผ่อน"},{"chinese":"她珍惜那些快乐时光的记忆。","pinyin":"Tā zhēn xī nà xiē kuài lè shí guāng de jì yì。","meaning":"She treasures her memories of those joyous days.","meaningThai":"เธอเก็บความทรงจำในช่วงเวลาอันแสนสุขเหล่านั้นไว้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1498","chinese":"哲学","pinyin":"zhéxué","meaning":"philosophy","meaningThai":"ปรัชญา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人生哲学。","pinyin":"Ren sheng zhe xue.","meaning":"Life philosophy.","meaningThai":"ปรัชญาชีวิต."}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1499","chinese":"直","pinyin":"zhí","meaning":"surname Zhi; Zhi (c. 2000 BC), fifth of the legendary Flame Emperors 帝 descended from Shennong 神农 Farmer God","meaningThai":"ตรง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她直直地看着我的眼睛。","pinyin":"Tā zhí zhí dì kàn zháo wǒ de yǎn jīng。","meaning":"She looked at me squarely in the eye.","meaningThai":"เธอมองมาที่ฉันด้วยสายตาตรง"},{"chinese":"我一直支付家庭开销,并且一直是养家的人。","pinyin":"Wǒ yī zhí zhī fù jiā tíng kāi xiāo, bìng qiě yī zhí shì yǎng jiā de rén。","meaning":"I've always paid the bills and been the breadwinner.","meaningThai":"ฉันจ่ายบิลมาโดยตลอดและเป็นคนหาเลี้ยงครอบครัว"}],"partOfSpeech":["adverb","adjective","verb"]},
  {"id":"hsk5-1500","chinese":"至","pinyin":"zhì","meaning":"to arrive; most; to; until","meaningThai":"ถึง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我快速翻阅至索引部分。","pinyin":"Wǒ kuài sù fān yuè zhì suǒ yǐn bù fēn。","meaning":"I riffled through the pages until I reached the index.","meaningThai":"ฉันค้นดูหน้าต่างๆ จนกระทั่งถึงดัชนี"},{"chinese":"我九点至五点上班。","pinyin":"Wǒ jiǔ diǎn zhì wǔ diǎn shàng bān。","meaning":"I work nine to five.","meaningThai":"ฉันทำงานเก้าโมงถึงตีห้า"}],"partOfSpeech":["preposition","verb","other"]},
  {"id":"hsk5-1501","chinese":"治","pinyin":"zhì","meaning":"to rule; to govern; to manage; to control; to harness (a river); to treat (a disease); to wipe out (a pest); to punish; to research","meaningThai":"กฎ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"迪伦一到纽约就直接去了格林威治村。","pinyin":"Dí lún yī dào niǔ yuē jiù zhí jiē qù le gé lín wēi zhì cūn。","meaning":"On arriving in New York, Dylan went directly to Greenwich Village.","meaningThai":"เมื่อมาถึงนิวยอร์ก ดีแลนก็ตรงไปที่หมู่บ้านกรีนิช"},{"chinese":"这些产品被当作包治百病的良药来促销。","pinyin":"Zhè xiē chǎn pǐn bèi dāng zuò bāo zhì bǎi bìng de liáng yào lái cù xiāo。","meaning":"These products are promoted as surefire cures for various diseases.","meaningThai":"ผลิตภัณฑ์เหล่านี้ได้รับการส่งเสริมให้เป็นยารักษาโรคต่างๆ ได้แน่นอน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1502","chinese":"止","pinyin":"zhǐ","meaning":"to stop; to prohibit; until; only","meaningThai":"จบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她细小而又抑扬顿挫的声音戛然而止。","pinyin":"Tā xì xiǎo ér yòu yì yáng dùn cuò de shēng yīn jiá rán ér zhǐ。","meaning":"Her voice, small and fluting, stopped abruptly.","meaningThai":"เสียงของเธอแผ่วเบาและเบาลงหยุดกะทันหัน"},{"chinese":"她一踏进屋子里，热烈的谈话便戛然而止。","pinyin":"Tā yī tà jìn wū zǐ lǐ， rè liè de tán huà biàn jiá rán ér zhǐ。","meaning":"The buzz of conversation suddenly stopped when she came into the room.","meaningThai":"จู่ๆ บทสนทนาก็หยุดลงเมื่อเธอเข้ามาในห้อง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1503","chinese":"支","pinyin":"zhī","meaning":"surname Zhi","meaningThai":"สาขา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"请别挂断，我去拿支笔，好吗？","pinyin":"Qǐng bié guà duàn， wǒ qù ná zhī bǐ， hǎo ma？","meaning":"Could you hold the line and I'll just get my pen.","meaningThai":"คุณช่วยถือสายหน่อยได้ไหม แล้วฉันจะไปเอาปากกามา"},{"chinese":"“你要来支香烟吗？”—“不了，谢谢。”","pinyin":"“ nǐ yào lái zhī xiāng yān ma？”—“ bù le， xiè xiè。”","meaning":"\"Would you like a cigarette?\"—\"No thank you.\"","meaningThai":"\"คุณต้องการบุหรี่ไหม?\"—\"ไม่ ขอบคุณ\""}],"partOfSpeech":["measure word","verb"]},
  {"id":"hsk5-1504","chinese":"直播","pinyin":"zhíbō","meaning":"(TV, radio) to broadcast live; live broadcast; (Internet) to livestream; (agriculture) direct seeding","meaningThai":"ไลฟ์สตรีม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她在做直播带货。","pinyin":"Tā zài zuò zhí bō dài huò.","meaning":"She is doing live-streaming sales.","meaningThai":"เธอกำลังทำการขายแบบสตรีมมิ่งสด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1505","chinese":"职场","pinyin":"zhíchǎng","meaning":"workplace","meaningThai":"ที่ทำงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们急需一场职场革命。","pinyin":"Wǒ mén jí xū yī cháng zhí cháng gé mìng。","meaning":"It's imperative for us to embrace a workplace revolution.","meaningThai":"จำเป็นอย่างยิ่งที่เราต้องยอมรับการปฏิวัติในที่ทำงาน"},{"chinese":"“这就是我们在职场上的叫法。”一位20多岁的女性说道。","pinyin":"“ zhè jiù shì wǒ mén zài zhí cháng shàng de jiào fǎ。” yī wèi 20 duō suì de nǚ xìng shuō dào。","meaning":"\"That's what we call it in the workplace,\" says a woman in her 20s.","meaningThai":"“นั่นคือสิ่งที่เราเรียกว่าในที่ทำงาน” ผู้หญิงวัย 20 ปีคนหนึ่งกล่าว"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1506","chinese":"指导","pinyin":"zhǐdǎo","meaning":"to guide; to give directions; to direct; to coach; guidance; tuition","meaningThai":"แนะนำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"学生们可以决定寻求助教的指导。","pinyin":"Xué shēng mén kě yǐ jué dìng xún qiú zhù jiào de zhǐ dǎo。","meaning":"Students may decide to seek tutorial guidance.","meaningThai":"นักเรียนอาจตัดสินใจขอคำแนะนำการสอน"},{"chinese":"每位候选人都被给予了安全指导。","pinyin":"Měi wèi hòu xuǎn rén dū bèi gěi yú le ān quán zhǐ dǎo。","meaning":"Each candidate is given instruction in safety.","meaningThai":"ผู้สมัครแต่ละคนจะได้รับคำแนะนำด้านความปลอดภัย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1507","chinese":"制订","pinyin":"zhìdìng","meaning":"to work out; to formulate","meaningThai":"กำหนด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个方案的具体细节尚需制订。","pinyin":"Zhè gè fāng àn de jù tǐ xì jié shàng xū zhì dìng。","meaning":"The fine detail of the plan has yet to be worked out.","meaningThai":"รายละเอียดปลีกย่อยของแผนยังไม่ได้รับการแก้ไข"},{"chinese":"该工程已制订一千万法郎的预算。","pinyin":"Gāi gōng chéng yǐ zhì dìng yī qiān wàn fǎ láng de yù suàn。","meaning":"The project has been budgeted at ten million francs.","meaningThai":"โครงการนี้ได้รับงบประมาณสิบล้านฟรังก์"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1508","chinese":"制定","pinyin":"zhìdìng","meaning":"to draw up; to formulate","meaningThai":"กำหนด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你们准备如何达到你们制定的目标？","pinyin":"Nǐ mén zhǔn bèi rú hé dá dào nǐ mén zhì dìng de mù biāo？","meaning":"How do you plan to achieve the goals you set?","meaningThai":"คุณวางแผนที่จะบรรลุเป้าหมายที่คุณตั้งไว้อย่างไร?"},{"chinese":"只要制定學習計劃，就能有效地取得進步。","pinyin":"Zhī yào zhì dìng xué xí jì huá， jiù néng yǒu xiào dì qǔ dé jìn bù。","meaning":"If you make a study plan, you can make progress efficiently.","meaningThai":"ถ้าวางแผนการเรียนก็ก้าวหน้าได้อย่างมีประสิทธิภาพ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1509","chinese":"制度","pinyin":"zhìdù","meaning":"system (e.g. political, adminstrative etc); institution","meaningThai":"ระบบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他承认，当前的制度有些缺陷。","pinyin":"Tā chéng rèn， dāng qián de zhì dù yǒu xiē quē xiàn。","meaning":"He concedes that there are imperfections in the current system.","meaningThai":"เขายอมรับว่ามีความไม่สมบูรณ์ในระบบปัจจุบัน"},{"chinese":"我们正在转用新的发票制度。","pinyin":"Wǒ mén zhèng zài zhuǎn yòng xīn de fā piào zhì dù。","meaning":"We're in the process of switching over to a new system of invoicing.","meaningThai":"เรากำลังอยู่ระหว่างการเปลี่ยนไปใช้ระบบการออกใบแจ้งหนี้แบบใหม่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1510","chinese":"职工","pinyin":"zhígōng","meaning":"workers; staff","meaningThai":"พนักงาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该公司雇用18位职工。","pinyin":"Gāi gōng sī gù yòng 18 wèi zhí gōng。","meaning":"The company employs 18 workers.","meaningThai":"บริษัทมีพนักงาน 18 คน"},{"chinese":"他们正对职工加以重组和裁减。","pinyin":"Tā mén zhèng duì zhí gōng jiā yǐ zhòng zǔ hé cái jiǎn。","meaning":"They're restructuring and slimming down the workforce.","meaningThai":"พวกเขากำลังปรับโครงสร้างใหม่และลดจำนวนพนักงานลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1511","chinese":"智慧","pinyin":"zhìhuì","meaning":"wisdom; knowledge; intelligent; intelligence","meaningThai":"ปัญญา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"集体智慧。","pinyin":"Ji ti zhi hui.","meaning":"Collective wisdom.","meaningThai":"ภูมิปัญญาส่วนรวม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1512","chinese":"至今","pinyin":"zhìjīn","meaning":"so far; to this day; until now","meaningThai":"จนถึงปัจจุบัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"兩隊至今均未嘗敗績。","pinyin":"Liǎng duì zhì jīn jūn wèi cháng bài jì。","meaning":"Both teams are unbeaten.","meaningThai":"ทั้งสองทีมไม่แพ้ใคร"},{"chinese":"我父亲至今从未去过国外。","pinyin":"Wǒ fù qīn zhì jīn cóng wèi qù guò guó wài。","meaning":"My father has never been abroad.","meaningThai":"พ่อของฉันไม่เคยไปต่างประเทศ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1513","chinese":"治疗","pinyin":"zhìliáo","meaning":"to treat (an illness); medical treatment; therapy","meaningThai":"รักษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"扭转治疗是酷刑。","pinyin":"Niǔ zhuǎn zhì liáo shì kù xíng。","meaning":"Conversion therapy is torture.","meaningThai":"การบำบัดเพื่อเปลี่ยนใจเลื่อมใสเป็นการทรมาน"},{"chinese":"汤姆需要接受治疗。","pinyin":"Tāng mǔ xū yào jiē shòu zhì liáo。","meaning":"Tom needed treatment.","meaningThai":"ทอมจำเป็นต้องได้รับการรักษา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1514","chinese":"知名","pinyin":"zhīmíng","meaning":"well-known; famous","meaningThai":"มีชื่อเสียง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她在对人脑的研究方面最为知名。","pinyin":"Tā zài duì rén nǎo de yán jiū fāng miàn zuì wéi zhī míng。","meaning":"She is best known for her work on the human brain.","meaningThai":"เธอเป็นที่รู้จักกันดีที่สุดจากการทำงานเกี่ยวกับสมองของมนุษย์"},{"chinese":"这些案例均吸引了大批知名作家。","pinyin":"Zhè xiē àn lì jūn xī yǐn le dà pī zhī míng zuò jiā。","meaning":"These cases all attracted flocks of famous writers.","meaningThai":"กรณีเหล่านี้ดึงดูดนักเขียนชื่อดังมากมาย"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1515","chinese":"智能","pinyin":"zhìnéng","meaning":"intelligent; able; smart (phone, system, bomb etc)","meaningThai":"ฉลาด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"神经元本身毕竟不具备智能。","pinyin":"Shén jīng yuán běn shēn bì jìng bù jù bèi zhì néng。","meaning":"Nerve cells, after all, do not have intelligence of their own.","meaningThai":"เซลล์ประสาทไม่มีความฉลาดในตัวเอง"},{"chinese":"我们鼓励智能卡在网上支付中的使用。","pinyin":"Wǒ mén gǔ lì zhì néng kǎ zài wǎng shàng zhī fù zhōng de shǐ yòng。","meaning":"We encourage the use of smart cards for online payments.","meaningThai":"เราสนับสนุนการใช้สมาร์ทการ์ดสำหรับการชำระเงินออนไลน์"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1516","chinese":"执行","pinyin":"zhíxíng","meaning":"to implement; to carry out; to execute; to run","meaningThai":"ปฏิบัติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"严格执行。","pinyin":"Yan ge zhi xing.","meaning":"Strictly implement.","meaningThai":"ปฏิบัติอย่างเคร่งครัด"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1517","chinese":"志愿者","pinyin":"zhìyuànzhě","meaning":"volunteer","meaningThai":"อาสาสมัคร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她是位志愿者，不是被逼来的。","pinyin":"Tā shì wèi zhì yuàn zhě， bù shì bèi bī lái de。","meaning":"She was a volunteer, she hadn't had to be press-ganged.","meaningThai":"เธอเป็นอาสาสมัคร เธอไม่ต้องถูกกดขี่ข่มเหง"},{"chinese":"每天24小时都有志愿者接听电话。","pinyin":"Měi tiān 24 xiǎo shí dū yǒu zhì yuàn zhě jiē tīng diàn huà。","meaning":"The telephones are manned 24 hours a day by volunteers.","meaningThai":"โทรศัพท์ได้รับการดูแลตลอด 24 ชั่วโมงโดยอาสาสมัคร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1518","chinese":"制造","pinyin":"zhìzào","meaning":"to manufacture; to make","meaningThai":"ผลิต","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"该产品上贴有“中国制造”的标签。","pinyin":"Gāi chǎn pǐn shàng tiē yǒu “ zhōng guó zhì zào ” de biāo qiān。","meaning":"The produce was labelled \"Made in China.\"","meaningThai":"ผลผลิตมีป้ายกำกับว่า \"Made in China\""},{"chinese":"每个制造商都有几种可能的选择。","pinyin":"Měi gè zhì zào shāng dū yǒu jī zhǒng kě néng de xuǎn zé。","meaning":"There were several possibilities open to each manufacturer.","meaningThai":"มีความเป็นไปได้หลายประการสำหรับผู้ผลิตแต่ละราย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1519","chinese":"制作","pinyin":"zhìzuò","meaning":"to make; to manufacture","meaningThai":"ทำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"萨米制作了一个视频。","pinyin":"Sà mǐ zhì zuò le yī gè shì pín。","meaning":"Sami made a video.","meaningThai":"ซามีได้ทำวิดีโอ"},{"chinese":"阿尔及利亚制作手机。","pinyin":"Ā ěr jí lì yà zhì zuò shǒu jī。","meaning":"Algeria produces cellphones.","meaningThai":"แอลจีเรียผลิตโทรศัพท์มือถือ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1520","chinese":"重大","pinyin":"zhòngdà","meaning":"great; important; major; significant","meaningThai":"วิชาเอก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们能受托解决重大国家问题。","pinyin":"Tā mén néng shòu tuō jiě jué zhòng dà guó jiā wèn tí。","meaning":"They can be entrusted to solve major national problems.","meaningThai":"พวกเขาสามารถมอบหมายให้แก้ไขปัญหาสำคัญของประเทศได้"},{"chinese":"政府将这些变化描述成重大改革。","pinyin":"Zhèng fǔ jiāng zhè xiē biàn huà miáo shù chéng zhòng dà gǎi gé。","meaning":"The govern we are pirates, these data are stolen from youdao  has presented these changes as major reforms.","meaningThai":"รัฐบาลอธิบายว่าการเปลี่ยนแปลงดังกล่าวเป็นการปฏิรูปครั้งใหญ่"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1521","chinese":"众多","pinyin":"zhòngduō","meaning":"numerous","meaningThai":"มากมาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个城市人口众多。","pinyin":"Zhè gè chéng shì rén kǒu zhòng duō。","meaning":"The city has a large population.","meaningThai":"เมืองนี้มีประชากรจำนวนมาก"}],"partOfSpeech":["numeral"]},
  {"id":"hsk5-1522","chinese":"中华","pinyin":"Zhōnghuá","meaning":"China (alternate formal name)","meaningThai":"จีน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"“龙舟竞渡”是中华民族传统体育项目之一。","pinyin":"“ lóng zhōu jìng dù ” shì zhōng huá mín zú chuán tǒng tǐ yù xiàng mù zhī yī。","meaning":"Dragon Boat Race is one of the traditional Chinese sports.","meaningThai":"การแข่งขันเรือมังกรเป็นกีฬาชนิดหนึ่งของจีน"},{"chinese":"在中华民族的历史中，出现了很多的民族英雄。","pinyin":"Zài zhōng huá mín zú de lì shǐ zhōng， chū xiàn le hěn duō de mín zú yīng xióng。","meaning":"Many national heroes have emerged in the history of the Chinese nation.","meaningThai":"วีรบุรุษของชาติหลายคนได้ปรากฏตัวในประวัติศาสตร์ของประชาชาติจีน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1523","chinese":"中华民族","pinyin":"Zhōnghuá Mínzú","meaning":"the Chinese nation; the Chinese people (collective reference to all the ethnic groups in China)","meaningThai":"ชาติจีน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在中华民族的历史中，出现了很多的民族英雄。","pinyin":"Zài zhōng huá mín zú de lì shǐ zhōng， chū xiàn le hěn duō de mín zú yīng xióng。","meaning":"Many national heroes have emerged in the history of the Chinese nation.","meaningThai":"วีรบุรุษของชาติหลายคนได้ปรากฏตัวในประวัติศาสตร์ของประชาชาติจีน"},{"chinese":"它是中华民族的象征。","pinyin":"Tā shì zhōng huá mín zú de xiàng zhēng。","meaning":"It is a symbol of the Chinese nation.","meaningThai":"เป็นสัญลักษณ์ของประชาชาติจีน"}]},
  {"id":"hsk5-1524","chinese":"中级","pinyin":"zhōngjí","meaning":"middle level (in a hierarchy)","meaningThai":"ระดับกลาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"学生分为新生、中级生或高级生。","pinyin":"Xué shēng fēn wéi xīn shēng、 zhōng jí shēng huò gāo jí shēng。","meaning":"Students are categorized as novice, intermediate, or advanced.","meaningThai":"นักเรียนจะถูกจัดประเภทเป็นสามเณร ระดับกลาง หรือขั้นสูง"},{"chinese":"滑雪学校训练初级、中级和高级水平的滑雪者。","pinyin":"Huá xuě xué xiào xùn liàn chū jí、 zhōng jí hé gāo jí shuǐ píng de huá xuě zhě。","meaning":"The ski school coaches beginners, intermediates, and advanced skiers.","meaningThai":"โรงเรียนสอนสกีให้บริการผู้ฝึกสอนผู้เริ่มต้น ระดับกลาง และนักสกีขั้นสูง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1525","chinese":"中介","pinyin":"zhōngjiè","meaning":"to act as intermediary; to link; intermediate; inter-; agency; agent","meaningThai":"ตัวกลาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"旅行社是市场中介机构，他们通过收集、组织和分发有关旅游相关服务的信息来谋生。","pinyin":"Lǚ háng shè shì shì cháng zhōng jiè jī gòu， tā mén tōng guò shōu jí、 zǔ zhī hé fēn fā yǒu guān lǚ yóu xiāng guān fú wù de xìn xī lái móu shēng。","meaning":"Travel agents are market intermediaries who make their living by gathering, organizing, and dispensing information about travel-related services.","meaningThai":"ตัวแทนการท่องเที่ยวเป็นตัวกลางทางการตลาดที่หาเลี้ยงชีพด้วยการรวบรวม จัดระเบียบ และแจกจ่ายข้อมูลเกี่ยวกับบริการที่เกี่ยวข้องกับการเดินทาง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1526","chinese":"种类","pinyin":"zhǒnglèi","meaning":"kind; genus; type; category; variety; species; sort; class","meaningThai":"พิมพ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个地区有很多种类的野花。","pinyin":"Zhè gè dì qū yǒu hěn duō zhǒng lèi de yě huā。","meaning":"This region is the home of many species of wild flower.","meaningThai":"ภูมิภาคนี้เป็นถิ่นกำเนิดของดอกไม้ป่านานาพันธุ์"},{"chinese":"吃某些种类的鱼变得时髦了。","pinyin":"Chī mǒu xiē zhǒng lèi de yú biàn dé shí máo le。","meaning":"It became fashionable to eat certain kinds of fish.","meaningThai":"การกินปลาบางชนิดกลายเป็นกระแสนิยม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1527","chinese":"重量","pinyin":"zhòngliàng","meaning":"weight","meaningThai":"น้ำหนัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些立柱必须支撑起屋顶的重量。","pinyin":"Zhè xiē lì zhù bì xū zhī chēng qǐ wū dǐng de zhòng liáng。","meaning":"The pillars have to support the weight of the roof.","meaningThai":"เสาต้องรับน้ำหนักหลังคา"},{"chinese":"他身体的重量把树枝都压弯了。","pinyin":"Tā shēn tǐ de zhòng liáng bǎ shù zhī dū yā wān le。","meaning":"The branch began to give under his weight.","meaningThai":"กิ่งไม้เริ่มให้ตามน้ำหนักของเขา"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1528","chinese":"中期","pinyin":"zhōngqī","meaning":"middle (of a period of time); medium-term (plan, forecast etc)","meaningThai":"ระยะกลาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这支队正处于赛季中期的不稳定状态。","pinyin":"Zhè zhī duì zhèng chǔ yú sài jì zhōng qī de bù wěn dìng zhuàng tài。","meaning":"The team is experiencing a mid-season wobble.","meaningThai":"ทีมกำลังประสบปัญหาโยกเยกกลางฤดูกาล"},{"chinese":"这是70年代中期的一个老故事的再现。","pinyin":"Zhè shì 70 nián dài zhōng qī de yī gè lǎo gù shì de zài xiàn。","meaning":"This is a resurrection of an old story from the mid-70s.","meaningThai":"นี่คือการฟื้นคืนชีพของเรื่องราวเก่าๆ ในช่วงกลางทศวรรษที่ 70"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1529","chinese":"中外","pinyin":"zhōngwài","meaning":"Sino-foreign; Chinese-foreign; home and abroad","meaningThai":"ชาวจีนและต่างประเทศ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"在这样的暴风雨中外出简直是荒唐和莫名其妙。","pinyin":"Zài zhè yàng de bào fēng yǔ zhōng wài chū jiǎn zhí shì huāng táng hé mò míng qí miào。","meaning":"It was absurd and illogical to go out into such a storm.","meaningThai":"มันไร้สาระและไร้เหตุผลที่ต้องออกไปเผชิญพายุเช่นนี้"},{"chinese":"100多名中外记者出席了吹风会。","pinyin":"100 duō míng zhōng wài jì zhě chū xí le chuī fēng huì。","meaning":"More than 100 Chinese and foreign journalists attended the briefing.","meaningThai":"มีนักข่าวชาวจีนและต่างประเทศมากกว่า 100 คนเข้าร่วมการบรรยายสรุป"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1530","chinese":"中心","pinyin":"zhōngxīn","meaning":"center; heart; core","meaningThai":"ศูนย์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"国家庆典总是以国王为中心。","pinyin":"Guó jiā qìng diǎn zǒng shì yǐ guó wáng wéi zhōng xīn。","meaning":"State occasions always centred around the king.","meaningThai":"โอกาสของรัฐมีศูนย์กลางอยู่ที่กษัตริย์เสมอ"},{"chinese":"她被推到了政治舞台的中心。","pinyin":"Tā bèi tuī dào le zhèng zhì wǔ tái de zhōng xīn。","meaning":"She was forced to the centre of the political stage.","meaningThai":"เธอถูกบังคับให้เป็นศูนย์กลางของเวทีการเมือง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1531","chinese":"中药","pinyin":"zhōngyào","meaning":"traditional Chinese medicine","meaningThai":"ยาจีนโบราณ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"它仍然被用于中药。","pinyin":"Tā réng rán bèi yòng yú zhōng yào。","meaning":"It's still being used in Chinese medicine.","meaningThai":"ยังคงถูกนำมาใช้ในการแพทย์แผนจีน"},{"chinese":"总之，中药是中国的瑰宝。","pinyin":"Zǒng zhī， zhōng yào shì zhōng guó de guī bǎo。","meaning":"In a word, traditional Chinese medicine is the treasure of China.","meaningThai":"กล่าวอีกนัยหนึ่ง การแพทย์แผนจีนถือเป็นสมบัติของจีน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1532","chinese":"中医","pinyin":"zhōngyī","meaning":"traditional Chinese medical science; a doctor trained in Chinese medicine","meaningThai":"การแพทย์แผนจีน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"中医认为，立夏是滋润心脏的关键时刻。","pinyin":"Zhōng yī rèn wéi， lì xià shì zī rùn xīn zāng de guān jiàn shí kè。","meaning":"According to Chinese traditional medicine, start of summer is a key time to moisten the heart.","meaningThai":"ตามหลักการแพทย์แผนจีน การเริ่มต้นฤดูร้อนเป็นช่วงเวลาสำคัญในการทำให้หัวใจชุ่มชื้น"},{"chinese":"最好还是病向浅中医。","pinyin":"Zuì hǎo huán shì bìng xiàng qiǎn zhōng yī。","meaning":"It is best to treat the disease early before it takes a hold.","meaningThai":"ทางที่ดีควรรักษาโรคตั้งแต่เนิ่นๆก่อนที่จะเกิดอาการ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1533","chinese":"种植","pinyin":"zhòngzhí","meaning":"to plant; to grow (a crop); to cultivate","meaningThai":"การปลูก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这里的人们主要种植稻子和豆类。","pinyin":"Zhè lǐ de rén mén zhǔ yào zhǒng zhí dào zǐ hé dòu lèi。","meaning":"The people cultivate mainly rice and beans.","meaningThai":"ประชาชนปลูกข้าวและถั่วเป็นหลัก"},{"chinese":"小麦、玉米和甜菜是轮流种植的。","pinyin":"Xiǎo mài、 yù mǐ hé tián cài shì lún liú zhǒng zhí de。","meaning":"Wheat, maize and sugar beet are planted in rotation.","meaningThai":"มีการปลูกข้าวสาลี ข้าวโพด และชูการ์บีทแบบหมุนเวียนกัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1534","chinese":"种子","pinyin":"zhǒngzi","meaning":"seed","meaningThai":"เมล็ด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"春天播种种子。","pinyin":"Chūn tiān bō zhǒng zhǒng zi.","meaning":"Sow seeds in spring.","meaningThai":"หว่านเมล็ดในฤดูใบไม้ผลิ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1535","chinese":"周年","pinyin":"zhōunián","meaning":"anniversary; annual","meaningThai":"วันครบรอบปี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们在佛罗伦萨庆祝结婚25周年。","pinyin":"Wǒ mén zài fó luó lún sà qìng zhù jié hūn 25 zhōu nián。","meaning":"We celebrated our 25th wedding anniversary in Florence.","meaningThai":"เราฉลองวันครบรอบแต่งงาน 25 ปีที่ฟลอเรนซ์"},{"chinese":"该学会今年将举行10周年年庆。","pinyin":"Gāi xué huì jīn nián jiāng jǔ háng 10 zhōu nián nián qìng。","meaning":"The society is celebrating its tenth anniversary this year.","meaningThai":"สังคมกำลังฉลองครบรอบสิบปีในปีนี้"}],"partOfSpeech":["measure word"]},
  {"id":"hsk5-1536","chinese":"煮","pinyin":"zhǔ","meaning":"variant of 煮","meaningThai":"ต้ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"煮面条很简单。","pinyin":"Zhu mian tiao hen jian dan.","meaning":"Boiling noodles is simple.","meaningThai":"การต้มบะหมี่เป็นเรื่องง่าย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1537","chinese":"猪","pinyin":"zhū","meaning":"hog; pig; swine","meaningThai":"หมู","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"猪被宰杀了，火腿吊在屋顶下风干。","pinyin":"Zhū bèi zǎi shā le， huǒ tuǐ diào zài wū dǐng xià fēng gān。","meaning":"Pigs were butchered, hams were hung to dry from the ceiling.","meaningThai":"หมูถูกฆ่า แฮมถูกแขวนไว้ให้แห้งจากเพดาน"},{"chinese":"我们喜欢猪，它们很爱干净。","pinyin":"Wǒ mén xǐ huān zhū， tā mén hěn ài gān jìng。","meaning":"We like pigs, they're very clean.","meaningThai":"เราชอบหมู มันสะอาดมาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1538","chinese":"抓","pinyin":"zhuā","meaning":"to grab; to catch; to arrest; to snatch; to scratch","meaningThai":"เข้าใจ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他猛地伸出手去抓她。","pinyin":"Tā měng dì shēn chū shǒu qù zhuā tā。","meaning":"He shot out his hand to grab her.","meaningThai":"เขายื่นมือออกไปจับเธอ"},{"chinese":"那狗嗷嗷地叫着抓门。","pinyin":"Nà gǒu áo áo dì jiào zháo zhuā mén。","meaning":"The dog whined and scratched at the door.","meaningThai":"สุนัขสะอื้นและข่วนที่ประตู"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1539","chinese":"抓紧","pinyin":"zhuājǐn","meaning":"to keep a firm grip on; to pay close attention to; to lose no time in (doing sth)","meaningThai":"ให้ความสนใจอย่างใกล้ชิด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"如果你想赶上那趟火车就得抓紧时间了。","pinyin":"Rú guǒ nǐ xiǎng gǎn shàng nà tàng huǒ chē jiù dé zhuā jǐn shí jiān le。","meaning":"You'll have to hurry if you want to catch that train.","meaningThai":"คุณจะต้องรีบถ้าคุณต้องการขึ้นรถไฟขบวนนั้น"},{"chinese":"快点—抓紧时间吧！","pinyin":"Kuài diǎn — zhuā jǐn shí jiān bā！","meaning":"Hurry— there's no time to lose !","meaningThai":"รีบหน่อย— ไม่มีเวลาจะเสียแล้ว!"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1540","chinese":"转变","pinyin":"zhuǎnbiàn","meaning":"to change; to transform; shift; transformation","meaningThai":"เปลี่ยน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这种突然转变背后的动机是什么？","pinyin":"Zhè zhǒng tū rán zhuǎn biàn bèi hòu de dòng jī shì shí mó？","meaning":"What is the motivation behind this sudden change?","meaningThai":"อะไรคือแรงจูงใจเบื้องหลังการเปลี่ยนแปลงกะทันหันนี้?"},{"chinese":"他试图转变话题，但她不愿被打断。","pinyin":"Tā shì tú zhuǎn biàn huà tí， dàn tā bù yuàn bèi dǎ duàn。","meaning":"He tried to change the subject, but she wasn't to be put off.","meaningThai":"เขาพยายามเปลี่ยนเรื่อง แต่เธอก็ไม่ยอมเปลี่ยนเรื่อง"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1541","chinese":"撞","pinyin":"zhuàng","meaning":"to knock against; to bump into; to run into; to meet by accident","meaningThai":"ชนกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你被车撞过吗?","pinyin":"Nǐ bèi chē zhuàng guò ma?","meaning":"Have you ever been hit by a car?","meaningThai":"คุณเคยถูกรถชนบ้างไหม?"},{"chinese":"狗被卡車撞了。","pinyin":"Gǒu bèi kǎ chē zhuàng le。","meaning":"The dog was hit by a truck.","meaningThai":"สุนัขถูกรถบรรทุกชน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1542","chinese":"转告","pinyin":"zhuǎngào","meaning":"to pass on; to communicate; to transmit","meaningThai":"ถ่ายทอด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"请转告他我稍后会打电话给他。","pinyin":"Qǐng zhuǎn gào tā wǒ shāo hòu huì dǎ diàn huà gěi tā。","meaning":"Please tell him I'll call him later.","meaningThai":"กรุณาบอกเขาว่าฉันจะโทรหาเขาทีหลัง"},{"chinese":"好的，我会转告他的。","pinyin":"Hǎo de， wǒ huì zhuǎn gào tā de。","meaning":"OK. I'll tell him.","meaningThai":"ตกลง. ฉันจะบอกเขา"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1543","chinese":"状况","pinyin":"zhuàngkuàng","meaning":"condition; state; situation","meaningThai":"สถานการณ์","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"港口的海防工事状况很差。","pinyin":"Gǎng kǒu de hǎi fáng gōng shì zhuàng kuàng hěn chà。","meaning":"The harbour's sea defences are in poor condition.","meaningThai":"การป้องกันทางทะเลของท่าเรืออยู่ในสภาพที่ย่ำแย่"},{"chinese":"这座房子的状况没得挑。","pinyin":"Zhè zuò fáng zǐ de zhuàng kuàng méi dé tiāo。","meaning":"The house is in tip-top condition.","meaningThai":"บ้านอยู่ในสภาพดีเยี่ยม"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1544","chinese":"装饰","pinyin":"zhuāngshì","meaning":"to decorate; decoration; decorative; ornamental","meaningThai":"ตกแต่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"室内装饰。","pinyin":"Shi nei zhuang shi.","meaning":"Interior decoration.","meaningThai":"การตกแต่งภายใน"}],"partOfSpeech":["noun","verb"]},
  {"id":"hsk5-1545","chinese":"状态","pinyin":"zhuàngtài","meaning":"condition; state; state of affairs","meaningThai":"สถานะ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"当时车子处于最佳状态。","pinyin":"Dāng shí chē zǐ chǔ yú zuì jiā zhuàng tài。","meaning":"The car was in first-class condition.","meaningThai":"รถอยู่ในสภาพชั้นหนึ่ง"},{"chinese":"整座建筑处于失修状态。","pinyin":"Zhěng zuò jiàn zhù chǔ yú shī xiū zhuàng tài。","meaning":"The building was in a general state of disrepair.","meaningThai":"อาคารอยู่ในสภาพทรุดโทรมโดยทั่วไป"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1546","chinese":"装修","pinyin":"zhuāngxiū","meaning":"to decorate; interior decoration; to fit up; to renovate","meaningThai":"ตกแต่ง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"它曾是一栋完全未经装修的大楼。","pinyin":"Tā zēng shì yī dòng wán quán wèi jīng zhuāng xiū de dà lóu。","meaning":"It was a building without any adornment or decoration.","meaningThai":"เป็นอาคารที่ไม่มีการตกแต่งใดๆ"},{"chinese":"我自己干了很多装修的活儿。","pinyin":"Wǒ zì jǐ gān le hěn duō zhuāng xiū de huó ér。","meaning":"I did a lot of the decorating myself.","meaningThai":"ฉันตกแต่งตัวเองเยอะมาก"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1547","chinese":"专家","pinyin":"zhuānjiā","meaning":"expert; specialist","meaningThai":"ผู้เชี่ยวชาญ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"医学专家们还得全面汇报。","pinyin":"Yī xué zhuān jiā mén huán dé quán miàn huì bào。","meaning":"The medical experts have yet to report in full.","meaningThai":"ผู้เชี่ยวชาญทางการแพทย์ยังไม่ได้รายงานอย่างครบถ้วน"},{"chinese":"专家对这幅画估价很高。","pinyin":"Zhuān jiā duì zhè fú huà gū jià hěn gāo。","meaning":"Experts set a high valuation on the painting.","meaningThai":"ผู้เชี่ยวชาญประเมินมูลค่าภาพวาดไว้สูง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1548","chinese":"专心","pinyin":"zhuānxīn","meaning":"to focus one's attention; to concentrate on (doing sth)","meaningThai":"สมาธิ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我要离开去专心写小说。","pinyin":"Wǒ yào lí kāi qù zhuān xīn xiě xiǎo shuō。","meaning":"I am leaving to concentrate on writing fiction.","meaningThai":"ฉันกำลังออกไปมีสมาธิกับการเขียนนิยาย"},{"chinese":"工作时你要能专心。","pinyin":"Gōng zuò shí nǐ yào néng zhuān xīn。","meaning":"At work you need to be able to concentrate.","meaningThai":"ในที่ทำงานคุณต้องมีสมาธิ"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1549","chinese":"逐步","pinyin":"zhúbù","meaning":"progressively; step by step","meaningThai":"ค่อยๆ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他们在逐步减少生产旧型号的产品。","pinyin":"Tā mén zài zhú bù jiǎn shǎo shēng chǎn jiù xíng hào de chǎn pǐn。","meaning":"They are gradually tapering off production of the older models.","meaningThai":"พวกเขากำลังค่อยๆ ลดการผลิตรุ่นเก่าลง"},{"chinese":"她的症状逐步恶化。","pinyin":"Tā de zhèng zhuàng zhú bù è huà。","meaning":"Her symptoms became progressively worse.","meaningThai":"อาการของเธอแย่ลงเรื่อยๆ"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1550","chinese":"注册","pinyin":"zhùcè","meaning":"to register; to enroll","meaningThai":"ลงทะเบียน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"注册用户。","pinyin":"Zhu ce yong hu.","meaning":"Registered user.","meaningThai":"ผู้ใช้ที่ลงทะเบียน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1551","chinese":"主持","pinyin":"zhǔchí","meaning":"to take charge of; to manage or direct; to preside over; to uphold; to stand for (justice etc); to host (a TV or radio program etc); (TV) anchor","meaningThai":"เจ้าภาพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"凱利主持新聞部門。","pinyin":"Kǎi lì zhǔ chí xīn wén bù mén。","meaning":"Kelly carries the news department.","meaningThai":"เคลลี่แบกแผนกข่าว"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1552","chinese":"主动","pinyin":"zhǔdòng","meaning":"to take the initiative; to do sth of one's own accord; spontaneous; active; opposite: passive 被动; drive (of gears and shafts etc)","meaningThai":"ความคิดริเริ่ม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他要是想见我，就得采取主动。","pinyin":"Tā yào shì xiǎng jiàn wǒ， jiù dé cǎi qǔ zhǔ dòng。","meaning":"If he wants to see me, he should make the first move.","meaningThai":"หากเขาต้องการพบฉันเขาควรเคลื่อนไหวก่อน"},{"chinese":"他们非常热情，主动提出等候我们。","pinyin":"Tā mén fēi cháng rè qíng， zhǔ dòng tí chū děng hòu wǒ mén。","meaning":"They were very obliging and offered to wait for us.","meaningThai":"พวกเขาเต็มใจมากและเสนอตัวให้รอเรา"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1553","chinese":"住房","pinyin":"zhùfáng","meaning":"housing","meaningThai":"ที่อยู่อาศัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些住房项目得到政府的补贴。","pinyin":"Zhè xiē zhù fáng xiàng mù dé dào zhèng fǔ de bǔ tiē。","meaning":"The housing projects are subsidized by the government.","meaningThai":"โครงการบ้านจัดสรรได้รับการสนับสนุนจากรัฐบาล"},{"chinese":"现有的住房中少有质量够好的。","pinyin":"Xiàn yǒu de zhù fáng zhōng shǎo yǒu zhì liáng gòu hǎo de。","meaning":"Little of the existing housing is of good enough quality.","meaningThai":"ที่อยู่อาศัยที่มีอยู่น้อยนิดก็มีคุณภาพเพียงพอ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1554","chinese":"主观","pinyin":"zhǔguān","meaning":"subjective","meaningThai":"อัตนัย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"主观原因。","pinyin":"Zhu guan yuan yin.","meaning":"Subjective reason.","meaningThai":"เหตุผลส่วนตัว"}],"partOfSpeech":["adjective","noun"]},
  {"id":"hsk5-1555","chinese":"追","pinyin":"zhuī","meaning":"to sculpt; to carve; musical instrument (old)","meaningThai":"ไล่ล่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他一边逃跑，一边用枪对准追他的警察。","pinyin":"Tā yī biān táo pǎo， yī biān yòng qiāng duì zhǔn zhuī tā de jǐng chá。","meaning":"He fled, pointing the gun at officers as they chased him.","meaningThai":"เขาหนีไปโดยชี้ปืนไปที่เจ้าหน้าที่ขณะที่พวกเขาไล่ล่าเขา"},{"chinese":"他就爱追年轻女子。","pinyin":"Tā jiù ài zhuī nián qīng nǚ zǐ。","meaning":"He's always running after younger women.","meaningThai":"เขามักจะวิ่งตามผู้หญิงที่อายุน้อยกว่าอยู่เสมอ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1556","chinese":"追求","pinyin":"zhuīqiú","meaning":"to pursue (a goal etc) stubbornly; to seek after; to woo","meaningThai":"ติดตาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他继续追求他成为演员的目标。","pinyin":"Tā jì xù zhuī qiú tā chéng wéi yǎn yuán de mù biāo。","meaning":"He continued to pursue his goal of becoming an actor.","meaningThai":"เขายังคงติดตามเป้าหมายในการเป็นนักแสดงต่อไป"},{"chinese":"她从未结婚，不过追求者不少。","pinyin":"Tā cóng wèi jié hūn， bù guò zhuī qiú zhě bù shǎo。","meaning":"She never married but had many admirers.","meaningThai":"เธอไม่เคยแต่งงาน แต่มีแฟน ๆ มากมาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1557","chinese":"逐渐","pinyin":"zhújiàn","meaning":"gradually","meaningThai":"ค่อยๆ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"乐观正逐渐替代悲观。","pinyin":"Lè guān zhèng zhú jiàn tì dài bēi guān。","meaning":"Optimism was gradually taking the place of pessimism.","meaningThai":"การมองโลกในแง่ดีค่อยๆ เข้ามาแทนที่การมองโลกในแง่ร้าย"},{"chinese":"峭壁正在逐渐崩坍。","pinyin":"Qiào bì zhèng zài zhú jiàn bēng tān。","meaning":"The cliff is gradually crumbling away.","meaningThai":"หน้าผาค่อยๆพังทลายลง"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1558","chinese":"主人","pinyin":"zhǔrén","meaning":"master; host; owner","meaningThai":"เจ้าของ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这块地可随主人的意愿出售。","pinyin":"Zhè kuài dì kě suí zhǔ rén de yì yuàn chū shòu。","meaning":"The land can be sold at the owner's pleasure.","meaningThai":"ที่ดินสามารถขายได้ตามความพอใจของเจ้าของ"},{"chinese":"酿熟期由地窖的主人决定。","pinyin":"Niàng shú qī yóu dì jiào de zhǔ rén jué dìng。","meaning":"The period of maturation is determined by the cellar master.","meaningThai":"ระยะเวลาการเจริญเติบโตจะถูกกำหนดโดยปรมาจารย์ห้องใต้ดิน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1559","chinese":"主任","pinyin":"zhǔrèn","meaning":"director; head","meaningThai":"ผู้อำนวยการ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"新来的主任确实使事情有了进展。","pinyin":"Xīn lái de zhǔ rèn què shí shǐ shì qíng yǒu le jìn zhǎn。","meaning":"The new director has really got things moving.","meaningThai":"ผู้กำกับคนใหม่มีหลายอย่างที่เคลื่อนไหวจริงๆ"},{"chinese":"我逐渐升到了主任秘书这样的职位。","pinyin":"Wǒ zhú jiàn shēng dào le zhǔ rèn mì shū zhè yàng de zhí wèi。","meaning":"I escalated to the dizzy heights of director's secretary.","meaningThai":"ฉันลุกลามจนถึงขั้นมึนงงของเลขาผู้กำกับ"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1560","chinese":"主食","pinyin":"zhǔshí","meaning":"staple food","meaningThai":"อาหารหลัก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"米饭是南方人的主食。","pinyin":"Mi fan shi nan fang ren de zhu shi.","meaning":"Rice is the staple food for southerners.","meaningThai":"ข้าวเป็นอาหารหลักของชาวใต้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1561","chinese":"住宿","pinyin":"zhùsù","meaning":"to stay at; lodging; accommodation","meaningThai":"อยู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"您提供住宿吗？","pinyin":"Nín tí gōng zhù sù ma？","meaning":"Do you offer accommodation?","meaningThai":"คุณมีที่พักไหม?"},{"chinese":"我想延长这里的住宿多几天。","pinyin":"Wǒ xiǎng yán cháng zhè lǐ de zhù sù duō jī tiān。","meaning":"I want to extend my stay here for a few more days.","meaningThai":"ฉันอยากจะขยายเวลาการอยู่ที่นี่ต่อไปอีกสักสองสามวัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1562","chinese":"主题","pinyin":"zhǔtí","meaning":"theme; subject","meaningThai":"ธีม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"已经有无数书籍写过这个主题。","pinyin":"Yǐ jīng yǒu wú shù shū jí xiě guò zhè gè zhǔ tí。","meaning":"Innumerable books have been written on the subject.","meaningThai":"มีการเขียนหนังสือมากมายเกี่ยวกับเรื่องนี้"},{"chinese":"这些档案按主题内容贴有色标。","pinyin":"Zhè xiē dàng àn àn zhǔ tí nèi róng tiē yǒu sè biāo。","meaning":"The files have labels that are colour-coded according to subject.","meaningThai":"ไฟล์มีป้ายกำกับที่มีรหัสสีตามหัวเรื่อง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1563","chinese":"主席","pinyin":"zhǔxí","meaning":"chairperson; premier; chairman","meaningThai":"ประธาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我提名汤姆•埃利斯做主席。","pinyin":"Wǒ tí míng tāng mǔ • āi lì sī zuò zhǔ xí。","meaning":"I propose Tom Ellis for chairman.","meaningThai":"ฉันเสนอให้ทอม เอลลิสเป็นประธาน"},{"chinese":"他接替伯纳德•艾伦任主席。","pinyin":"Tā jiē tì bó nà dé • ài lún rèn zhǔ xí。","meaning":"He became chairman in succession to Bernard Allen.","meaningThai":"เขาขึ้นเป็นประธานต่อจากเบอร์นาร์ด อัลเลน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1564","chinese":"住址","pinyin":"zhùzhǐ","meaning":"address","meaningThai":"ที่อยู่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"注意一定要让你的邮件改投到你的新住址。","pinyin":"Zhù yì yī dìng yào ràng nǐ de yóu jiàn gǎi tóu dào nǐ de xīn zhù zhǐ。","meaning":"Make sure you get your mail redirected to your new address.","meaningThai":"ตรวจสอบให้แน่ใจว่าคุณได้รับอีเมลของคุณเปลี่ยนเส้นทางไปยังที่อยู่ใหม่ของคุณ"},{"chinese":"你的姓名、住址？","pinyin":"Nǐ de xìng míng、 zhù zhǐ？","meaning":"What's your name and address ?","meaningThai":"คุณชื่อและที่อยู่อะไร?"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1565","chinese":"注重","pinyin":"zhùzhòng","meaning":"to pay attention to; to emphasize","meaningThai":"ให้ความสนใจกับ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"有些学校极注重语言学习。","pinyin":"Yǒu xiē xué xiào jí zhù zhòng yǔ yán xué xí。","meaning":"Some schools put/lay/place great emphasis on language study.","meaningThai":"บางโรงเรียนให้ความสำคัญกับการเรียนภาษาเป็นอย่างมาก"},{"chinese":"注重尊严的人都会轻视那种行为。","pinyin":"Zhù zhòng zūn yán de rén dū huì qīng shì nà zhǒng háng wéi。","meaning":"All people with a sense of decency will look down upon such conduct as that.","meaningThai":"ผู้มีคุณธรรมทั้งหลายย่อมดูหมิ่นความประพฤติเช่นนั้น"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1566","chinese":"竹子","pinyin":"zhúzi","meaning":"bamboo","meaningThai":"ไม้ไผ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"熊猫喜欢吃竹子。","pinyin":"Xióng māo xǐ huān chī zhú zi.","meaning":"Pandas like to eat bamboo.","meaningThai":"แพนด้าชอบกินไผ่"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1567","chinese":"紫","pinyin":"zǐ","meaning":"purple; violet","meaningThai":"สีม่วง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他的面颊上有一块大紫疤。","pinyin":"Tā de miàn jiá shàng yǒu yī kuài dà zǐ bā。","meaning":"A large purple scar marked his cheek.","meaningThai":"รอยแผลเป็นสีม่วงขนาดใหญ่ปรากฏบนแก้มของเขา"},{"chinese":"他被按照最高军事荣誉埋葬，死后被授予一枚紫心勋章","pinyin":"Tā bèi àn zhào zuì gāo jūn shì róng yù mái zàng， sǐ hòu bèi shòu yú yī méi zǐ xīn xūn zhāng","meaning":"He was buried with full military honours and posthumously awarded a Purple Heart.","meaningThai":"เขาถูกฝังด้วยเกียรติยศทางทหารเต็มรูปแบบ และมรณกรรมได้รับรางวัลหัวใจสีม่วง"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1568","chinese":"自从","pinyin":"zìcóng","meaning":"since (a time); ever since","meaningThai":"เนื่องจาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"自从我上次见到你后，你又见长了！","pinyin":"Zì cóng wǒ shàng cì jiàn dào nǐ hòu， nǐ yòu jiàn cháng le！","meaning":"You've grown since the last time I saw you!","meaningThai":"คุณโตขึ้นตั้งแต่ครั้งสุดท้ายที่ฉันเห็นคุณ!"},{"chinese":"自从她走后，他全心扑在工作上。","pinyin":"Zì cóng tā zǒu hòu， tā quán xīn pū zài gōng zuò shàng。","meaning":"Since she left, he's buried himself in his work.","meaningThai":"ตั้งแต่เธอจากไป เขาก็ฝังตัวเองอยู่ในงานของเขา"}],"partOfSpeech":["preposition"]},
  {"id":"hsk5-1569","chinese":"自动","pinyin":"zìdòng","meaning":"automatic; voluntarily","meaningThai":"อัตโนมัติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她把照相机调到自动状态。","pinyin":"Tā bǎ zhào xiāng jī tiáo dào zì dòng zhuàng tài。","meaning":"She set the camera on automatic.","meaningThai":"เธอตั้งกล้องเป็นอัตโนมัติ"},{"chinese":"该供暖系统可自动关闭。","pinyin":"Gāi gōng nuǎn xì tǒng kě zì dòng guān bì。","meaning":"The heating switches off automatically.","meaningThai":"เครื่องทำความร้อนจะปิดโดยอัตโนมัติ"}],"partOfSpeech":["adverb","adjective"]},
  {"id":"hsk5-1570","chinese":"资格","pinyin":"zīgé","meaning":"qualifications; seniority","meaningThai":"คุณสมบัติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"你有资格知道。","pinyin":"Nǐ yǒu zī gé zhī dào。","meaning":"You have the right to know.","meaningThai":"คุณมีสิทธิที่จะรู้"},{"chinese":"我当然有资格这么说啦。","pinyin":"Wǒ dāng rán yǒu zī gé zhè mó shuō lā。","meaning":"I am certainly entitled to speak like this.","meaningThai":"ข้าพเจ้ามีสิทธิที่จะพูดเช่นนี้อย่างแน่นอน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1571","chinese":"资金","pinyin":"zījīn","meaning":"funds; capital","meaningThai":"กองทุน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个项目因缺乏资金已经撤销。","pinyin":"Zhè gè xiàng mù yīn quē fá zī jīn yǐ jīng chè xiāo。","meaning":"The project has been cancelled because of lack of funds.","meaningThai":"โครงการถูกยกเลิกเนื่องจากขาดเงินทุน"},{"chinese":"财务主管盗走了俱乐部的资金。","pinyin":"Cái wù zhǔ guǎn dào zǒu le jù lè bù de zī jīn。","meaning":"The treasurer had run off with the club's funds.","meaningThai":"เหรัญญิกเงินของสโมสรหมดไป"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1572","chinese":"自觉","pinyin":"zìjué","meaning":"conscious; aware; on one's own initiative; conscientious","meaningThai":"มีสติ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人人自觉管，事事有人管。","pinyin":"Rén rén zì jué guǎn， shì shì yǒu rén guǎn。","meaning":"Everybody consciously attends to things and everything is attended to.","meaningThai":"ทุกคนใส่ใจกับสิ่งต่างๆ อย่างมีสติ และทุกๆ อย่างก็ใส่ใจ"},{"chinese":"说话的最佳心理场所是一种不自觉的自我意识，它提供了一种自然的幻觉。","pinyin":"Shuō huà de zuì jiā xīn lǐ cháng suǒ shì yī zhǒng bù zì jué de zì wǒ yì shí， tā tí gōng le yī zhǒng zì rán de huàn jué。","meaning":"The best psychological place from which to speak is an unselfconscious self-consciousness, providing the illusion of being natural.","meaningThai":"สถานที่ทางจิตวิทยาที่ดีที่สุดในการพูดคือการประหม่าโดยไม่รู้สึกตัว ทำให้เกิดภาพลวงตาว่าเป็นธรรมชาติ"}],"partOfSpeech":["adjective","verb"]},
  {"id":"hsk5-1573","chinese":"字母","pinyin":"zìmǔ","meaning":"letter (of the alphabet)","meaningThai":"จดหมาย","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"游戏可以帮助儿童学会组合字母。","pinyin":"Yóu xì kě yǐ bāng zhù ér tóng xué huì zǔ hé zì mǔ。","meaning":"Games can help children learn to form letters.","meaningThai":"เกมสามารถช่วยให้เด็กๆ เรียนรู้การสร้างตัวอักษรได้"},{"chinese":"这些表格应该按字母顺序归档。","pinyin":"Zhè xiē biǎo gé yīng gāi àn zì mǔ shùn xù guī dàng。","meaning":"The forms should be filed alphabetically.","meaningThai":"ควรยื่นแบบฟอร์มตามตัวอักษร"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1574","chinese":"子女","pinyin":"zǐnǚ","meaning":"children; sons and daughters","meaningThai":"เด็ก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"母亲总爱挂念自己的子女。","pinyin":"Mǔ qīn zǒng ài guà niàn zì jǐ de zǐ nǚ。","meaning":"Mothers typically worry about their children.","meaningThai":"มารดามักจะกังวลเกี่ยวกับลูกของตน"},{"chinese":"他把子女都送进了大学。","pinyin":"Tā bǎ zǐ nǚ dū sòng jìn le dà xué。","meaning":"He put all his children through college.","meaningThai":"เขาส่งลูก ๆ ของเขาทั้งหมดเข้าเรียนในวิทยาลัย"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1575","chinese":"自身","pinyin":"zìshēn","meaning":"itself; oneself; one's own","meaningThai":"ตัวมันเอง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"此野营地有其自身独特的魅力。","pinyin":"Cǐ yě yíng dì yǒu qí zì shēn dú tè de mèi lì。","meaning":"The wilderness campsite had its own peculiar enchant we are pirates, these data are stolen from youdao .","meaningThai":"ที่ตั้งแคมป์แห่งนี้มีเสน่ห์ที่เป็นเอกลักษณ์ของตัวเอง"},{"chinese":"他不得不正视自身作为父亲的不足。","pinyin":"Tā bù dé bù zhèng shì zì shēn zuò wéi fù qīn de bù zú。","meaning":"He had to face up to his own inadequacies as a father.","meaningThai":"เขาต้องเผชิญกับความบกพร่องของตนเองในฐานะพ่อ"}],"partOfSpeech":["pronoun"]},
  {"id":"hsk5-1576","chinese":"姿势","pinyin":"zīshì","meaning":"posture; position","meaningThai":"ท่าทาง","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"正确姿势。","pinyin":"Zheng que zi shi.","meaning":"Correct posture.","meaningThai":"ท่าทางที่ถูกต้อง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1577","chinese":"咨询","pinyin":"zīxún","meaning":"to consult; to seek advice; consultation; (sales) inquiry (formal)","meaningThai":"ปรึกษา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们计划利用外面的咨询公司。","pinyin":"Wǒ mén jì huá lì yòng wài miàn de zī xún gōng sī。","meaning":"We plan to use an outside firm of consultants.","meaningThai":"เราวางแผนที่จะใช้บริษัทที่ปรึกษาภายนอก"},{"chinese":"公司提供咨询并帮助找工作。","pinyin":"Gōng sī tí gōng zī xún bìng bāng zhù zhǎo gōng zuò。","meaning":"The company provides advice and assistance in finding work.","meaningThai":"บริษัทให้คำปรึกษาและช่วยเหลือในการหางาน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1578","chinese":"自由","pinyin":"zìyóu","meaning":"freedom; liberty; free; unrestricted","meaningThai":"ฟรี","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"人不能光为了自己的自由而不顾别人的自由。","pinyin":"Rén bù néng guāng wéi le zì jǐ de zì yóu ér bù gù bié rén de zì yóu。","meaning":"One cannot choose freedom for oneself without choosing it for others.","meaningThai":"เราไม่สามารถเลือกเสรีภาพให้กับตนเองได้ โดยไม่เลือกเสรีภาพเพื่อผู้อื่น"},{"chinese":"选举是自由公正的。","pinyin":"Xuǎn jǔ shì zì yóu gōng zhèng de。","meaning":"The elections were free and fair.","meaningThai":"การเลือกตั้งเป็นไปอย่างเสรีและยุติธรรม"}],"partOfSpeech":["adjective"]},
  {"id":"hsk5-1579","chinese":"资源","pinyin":"zīyuán","meaning":"Ziyuan county in Guilin 林, Guangxi","meaningThai":"ทรัพยากร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"正在调拨更多的资源给这个项目。","pinyin":"Zhèng zài tiáo bō gēng duō de zī yuán gěi zhè gè xiàng mù。","meaning":"More resources are being allocated to the project.","meaningThai":"กำลังจัดสรรทรัพยากรเพิ่มเติมให้กับโครงการ"},{"chinese":"他们无法调用他们需要的资源。","pinyin":"Tā mén wú fǎ tiáo yòng tā mén xū yào de zī yuán。","meaning":"They were unable to mobilize the resources they needed.","meaningThai":"พวกเขาไม่สามารถระดมทรัพยากรที่ต้องการได้"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1580","chinese":"总部","pinyin":"zǒngbù","meaning":"general headquarters","meaningThai":"สำนักงานใหญ่","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"公司总部在北京。","pinyin":"Gōng sī zǒng bù zài Běi jīng.","meaning":"The company headquarters is in Beijing.","meaningThai":"สำนักงานใหญ่ของบริษัทอยู่ที่กรุงปักกิ่ง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1581","chinese":"总共","pinyin":"zǒnggòng","meaning":"altogether; in sum; in all; in total","meaningThai":"ทั้งหมด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这些公司总共有1776名雇员。","pinyin":"Zhè xiē gōng sī zǒng gòng yǒu 1776 míng gù yuán。","meaning":"The companies have a total of 1,776 employees.","meaningThai":"บริษัทมีพนักงานทั้งหมด 1,776 คน"},{"chinese":"我和我丈夫在一起总共8年。","pinyin":"Wǒ hé wǒ zhàng fū zài yī qǐ zǒng gòng 8 nián。","meaning":"I was with my husband for eight years in total.","meaningThai":"รวมฉันอยู่กับสามีมาแปดปีแล้ว"}],"partOfSpeech":["adverb"]},
  {"id":"hsk5-1582","chinese":"综合","pinyin":"zōnghé","meaning":"comprehensive; composite; synthesized; mixed; to sum up; to integrate; to synthesize","meaningThai":"ครอบคลุม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"综合中学常把学生按能力分班。","pinyin":"Zōng hé zhōng xué cháng bǎ xué shēng àn néng lì fēn bān。","meaning":"Streaming within comprehensive schools is common practice.","meaningThai":"การสตรีมภายในโรงเรียนที่ครอบคลุมถือเป็นเรื่องปกติ"},{"chinese":"这份文件是不同来源信息的综合。","pinyin":"Zhè fèn wén jiàn shì bù tóng lái yuán xìn xī de zōng hé。","meaning":"The docu we are pirates, these data are stolen from youdao  was a composite of information from various sources.","meaningThai":"เอกสารนี้เป็นการสังเคราะห์ข้อมูลจากแหล่งต่างๆ"}],"partOfSpeech":["verb","adjective"]},
  {"id":"hsk5-1583","chinese":"总数","pinyin":"zǒngshù","meaning":"total; sum; aggregate","meaningThai":"ทั้งหมด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我想你在计算总数时出了差错。","pinyin":"Wǒ xiǎng nǐ zài jì suàn zǒng shù shí chū le chà cuò。","meaning":"I think you have made an error in calculating the total.","meaningThai":"ฉันคิดว่าคุณทำผิดพลาดในการคำนวณผลรวม"},{"chinese":"这家俱乐部的成员总数为300人。","pinyin":"Zhè jiā jù lè bù de chéng yuán zǒng shù wéi 300 rén。","meaning":"The club has a total membership of 300.","meaningThai":"สโมสรมีสมาชิกทั้งหมด 300 คน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1584","chinese":"总体","pinyin":"zǒngtǐ","meaning":"completely; totally; total; entire; overall; population (statistics)","meaningThai":"โดยรวม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"农业的总体形势是令人鼓舞的。","pinyin":"Nóng yè de zǒng tǐ xíng shì shì líng rén gǔ wǔ de。","meaning":"The overall picture for farming is encouraging.","meaningThai":"ภาพรวมการทำฟาร์มก็น่าสนับสนุน"},{"chinese":"这些数字表明就业率的总体下降。","pinyin":"Zhè xiē shù zì biǎo míng jiù yè shuài de zǒng tǐ xià jiàng。","meaning":"The figures represent a general decline in employment.","meaningThai":"ตัวเลขดังกล่าวแสดงถึงการจ้างงานโดยทั่วไปที่ลดลง"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1585","chinese":"总统","pinyin":"zǒngtǒng","meaning":"president (of a country)","meaningThai":"ประธาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"我们欢迎他当选总统。","pinyin":"Wǒ mén huān yíng tā dāng xuǎn zǒng tǒng。","meaning":"We welcome his election as president.","meaningThai":"เรายินดีต้อนรับการเลือกตั้งของเขาในฐานะประธานาธิบดี"},{"chinese":"总统面带愉悦的神情。","pinyin":"Zǒng tǒng miàn dài yú yuè de shén qíng。","meaning":"There was an amused look on the President's face.","meaningThai":"ใบหน้าของประธานาธิบดีมีสีหน้าขบขัน"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1586","chinese":"总之","pinyin":"zǒngzhī","meaning":"in a word; in short; in brief","meaningThai":"ในระยะสั้น","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"总之，我喜欢动画片。","pinyin":"Zǒng zhī， wǒ xǐ huān dòng huà piàn。","meaning":"In a word, I like cartoons.","meaningThai":"บอกได้คำเดียวว่าผมชอบการ์ตูน"},{"chinese":"总之，他是可靠的。","pinyin":"Zǒng zhī， tā shì kě kào de。","meaning":"In short, he's reliable.","meaningThai":"สรุปคือเขาเชื่อถือได้"}],"partOfSpeech":["conjunction"]},
  {"id":"hsk5-1587","chinese":"族","pinyin":"zú","meaning":"race; nationality; ethnicity; clan; by extension, social group (e.g. office workers 上班族)","meaningThai":"ตระกูล","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"您是维族人吗？","pinyin":"Nín shì wéi zú rén ma？","meaning":"Are you an Uighur?","meaningThai":"คุณเป็นคนอุยกูร์หรือเปล่า?"},{"chinese":"你是维族人吗？","pinyin":"Nǐ shì wéi zú rén ma？","meaning":"Are you an Uighur?","meaningThai":"คุณเป็นคนอุยกูร์หรือเปล่า?"}],"partOfSpeech":["other","measure word"]},
  {"id":"hsk5-1588","chinese":"组成","pinyin":"zǔchéng","meaning":"to form; to make up; to constitute","meaningThai":"องค์ประกอบ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这根链条由136个环组成。","pinyin":"Zhè gēn liàn tiáo yóu 136 gè huán zǔ chéng。","meaning":"The chain is formed from 136 links.","meaningThai":"โซ่ประกอบด้วย 136 ลิงค์"},{"chinese":"政府计划的重要组成部分是…","pinyin":"Zhèng fǔ jì huá de zhòng yào zǔ chéng bù fēn shì …","meaning":"Key components of the government's plan are...","meaningThai":"องค์ประกอบสำคัญของแผนของรัฐบาลคือ..."}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1589","chinese":"足够","pinyin":"zúgòu","meaning":"enough; sufficient","meaningThai":"เพียงพอ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"没有足够的空间扩建这些大楼。","pinyin":"Méi yǒu zú gòu de kōng jiān kuò jiàn zhè xiē dà lóu。","meaning":"There is insufficient space for enlargement of the buildings.","meaningThai":"มีพื้นที่ไม่เพียงพอที่จะขยายอาคารได้"},{"chinese":"我们的食物足够维持三天。","pinyin":"Wǒ mén de shí wù zú gòu wéi chí sān tiān。","meaning":"We've got enough food to last us (for) three days.","meaningThai":"เรามีอาหารเพียงพอที่จะอยู่ได้สามวัน"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1590","chinese":"组合","pinyin":"zǔhé","meaning":"to assemble; to combine; to compose; combination; association; set; compilation; (math.) combinatorial","meaningThai":"การผสมผสาน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这里你可以看到漂亮的颜色组合。","pinyin":"Zhè lǐ nǐ kě yǐ kàn dào piāo liàng de yán sè zǔ hé。","meaning":"Here you can see beautiful colour combinations.","meaningThai":"ที่นี่คุณสามารถเห็นการผสมสีที่สวยงาม"}],"partOfSpeech":["verb","noun"]},
  {"id":"hsk5-1591","chinese":"醉","pinyin":"zuì","meaning":"intoxicated","meaningThai":"เมา","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"萨莉已经习惯了听他的抱怨，通常都是些语无伦次、醉后的胡言乱语。","pinyin":"Sà lì yǐ jīng xí guàn le tīng tā de bào yuàn， tōng cháng dū shì xiē yǔ wú lún cì、 zuì hòu de hú yán luàn yǔ。","meaning":"Sally was used to hearing his complaints, usually in the form of disjointed, drunken ramblings.","meaningThai":"แซลลี่คุ้นเคยกับการได้ยินคำบ่นของเขา ซึ่งมักจะอยู่ในรูปแบบของการคุยโวอย่างไม่ปะติดปะต่อและเมามาย"},{"chinese":"醉驾，有时被称为美国社会认可的谋杀形式，已经在全国范围内泛滥。","pinyin":"Zuì jià， yǒu shí bèi chēng wéi měi guó shè huì rèn kě de móu shā xíng shì， yǐ jīng zài quán guó fàn wéi nèi fàn làn。","meaning":"Drunken driving—sometimes called America's socially accepted form of murder—has become a national epidemic.","meaningThai":"การเมาแล้วขับซึ่งบางครั้งเรียกว่ารูปแบบการฆาตกรรมที่เป็นที่ยอมรับในสังคมของอเมริกา ได้กลายเป็นโรคระบาดระดับชาติ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1592","chinese":"嘴巴","pinyin":"zuǐba","meaning":"mouth; slap in the face","meaningThai":"ปาก","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"她站在那里看着卡曼，嘴巴大张着。","pinyin":"Tā zhàn zài nà lǐ kàn zháo kǎ màn， zuǐ bā dà zhāng zháo。","meaning":"She stood looking at Carmen with her mouth agape.","meaningThai":"เธอยืนมองคาร์เมนพร้อมกับอ้าปากค้าง"},{"chinese":"我的心开始怦怦跳，而且嘴巴发干。","pinyin":"Wǒ de xīn kāi shǐ pēng pēng tiào， ér qiě zuǐ bā fā gān。","meaning":"My heart had started to thud, and my mouth was dry.","meaningThai":"หัวใจของฉันเริ่มที่จะเต้นรัว และปากของฉันก็แห้งผาก"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1593","chinese":"最初","pinyin":"zuìchū","meaning":"first; primary; initial; original; at first; initially; originally","meaningThai":"อักษรย่อ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这个问题最初在市区中心出现。","pinyin":"Zhè gè wèn tí zuì chū zài shì qū zhōng xīn chū xiàn。","meaning":"This problem first appeared in the inner cities.","meaningThai":"ปัญหานี้เกิดขึ้นครั้งแรกในเมืองชั้นใน"},{"chinese":"他们已决定接受我们最初的报价。","pinyin":"Tā mén yǐ jué dìng jiē shòu wǒ mén zuì chū de bào jià。","meaning":"They've decided to accept our original offer.","meaningThai":"พวกเขาตัดสินใจยอมรับข้อเสนอเดิมของเรา"}],"partOfSpeech":["adjective","adverb"]},
  {"id":"hsk5-1594","chinese":"最佳","pinyin":"zuìjiā","meaning":"optimum; optimal; peak; best (athlete, movie etc)","meaningThai":"เหมาะสมที่สุด","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"航空绝对是最佳旅行方式。","pinyin":"Háng kōng jué duì shì zuì jiā lǚ háng fāng shì。","meaning":"Flying is quite the best way to travel.","meaningThai":"การบินถือเป็นวิธีที่ดีที่สุดในการเดินทาง"},{"chinese":"这是我读过的最佳小说。","pinyin":"Zhè shì wǒ dú guò de zuì jiā xiǎo shuō。","meaning":"It's the best novel (that) I've ever read.","meaningThai":"เป็นนวนิยายที่ดีที่สุด (นั้น) ที่ฉันเคยอ่าน"}],"partOfSpeech":["other"]},
  {"id":"hsk5-1595","chinese":"租金","pinyin":"zūjīn","meaning":"rent","meaningThai":"เช่า","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"这辆汽车每周的租金是200多元。","pinyin":"Zhè liàng qì chē měi zhōu de zū jīn shì 200 duō yuán。","meaning":"The weekly rent on the car was over $200.","meaningThai":"ค่าเช่ารถรายสัปดาห์มากกว่า 200 ดอลลาร์"},{"chinese":"租金由承租人共同且分别承担。","pinyin":"Zū jīn yóu chéng zū rén gòng tóng qiě fēn bié chéng dān。","meaning":"Tenants are jointly and severally liable for payment of the rent.","meaningThai":"ผู้เช่าต้องรับผิดชอบร่วมกันและร่วมกันในการชำระค่าเช่า"}],"partOfSpeech":["noun"]},
  {"id":"hsk5-1596","chinese":"尊敬","pinyin":"zūnjìng","meaning":"to respect; to revere; to esteem; honorable; distinguished (used on formal occasions before a term of address)","meaningThai":"เคารพ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"值得尊敬。","pinyin":"Zhi de zun jing.","meaning":"Worthy of respect.","meaningThai":"น่านับถือครับ."}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1597","chinese":"遵守","pinyin":"zūnshǒu","meaning":"to comply with; to abide by; to respect (an agreement)","meaningThai":"ปฏิบัติตาม","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"遵守法律。","pinyin":"Zun shou fa lv.","meaning":"Comply with the law.","meaningThai":"ปฏิบัติตามกฎหมาย"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1598","chinese":"作出","pinyin":"zuòchū","meaning":"to put out; to come up with; to make (a choice, decision, proposal, response, comment etc); to issue (a permit, statement, explanation, apology, reassurance to the public etc); to draw (conclusion); to deliver (speech, judgment); to devise (explanation); to extract","meaningThai":"ทำ","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"他不愿对来年作出预言。","pinyin":"Tā bù yuàn duì lái nián zuò chū yù yán。","meaning":"He was unwilling to make a prediction for the coming year.","meaningThai":"เขาไม่เต็มใจที่จะทำนายในปีหน้า"},{"chinese":"尚未作出决定。","pinyin":"Shàng wèi zuò chū jué dìng。","meaning":"No decision has yet been made.","meaningThai":"ยังไม่มีการตัดสินใจ"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1599","chinese":"阻止","pinyin":"zǔzhǐ","meaning":"to prevent; to block","meaningThai":"ป้องกัน","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"没人能阻止我！","pinyin":"Méi rén néng zǔ zhǐ wǒ！","meaning":"Nobody can stop me! / Nobody can stop me.","meaningThai":"ไม่มีใครสามารถหยุดฉันได้! / ไม่มีใครสามารถหยุดฉันได้"},{"chinese":"我无法阻止它。","pinyin":"Wǒ wú fǎ zǔ zhǐ tā。","meaning":"I cannot stop it. / I can't stop it.","meaningThai":"ฉันไม่สามารถหยุดมันได้ / ฉันหยุดมันไม่ได้"}],"partOfSpeech":["verb"]},
  {"id":"hsk5-1600","chinese":"组织","pinyin":"zǔzhī","meaning":"to organize; organization; (biology) tissue; (textiles) weave","meaningThai":"องค์กร","category":"hsk","subcategory":"hsk5","hskLevel":5,"status":"new","examples":[{"chinese":"组织活动。","pinyin":"Zu zhi huo dong.","meaning":"Organize activities.","meaningThai":"จัดกิจกรรม."}],"partOfSpeech":["noun","verb"]}
];

